window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1KI"]={"book":"1KI","editions":{"hbo-source":[[1,1,"וְ⁠הַ⁠מֶּ֤לֶךְ דָּוִד֙ זָקֵ֔ן בָּ֖א בַּ⁠יָּמִ֑ים וַ⁠יְכַסֻּ֨⁠הוּ֙ בַּ⁠בְּגָדִ֔ים וְ⁠לֹ֥א יִחַ֖ם לֽ⁠וֹ׃","wĕ⁠ha⁠mė֤lekĕ dá̇wid֙ záqé֔n bá֖̇ʼ bȧ⁠yá̇mi֑ym wa⁠yĕkasu̇֨⁠hẇ֙ bȧ⁠bĕ̇gádi֔ym wĕ⁠lò֥ʼ yiẖa֖m lֽ⁠wò׃"],[1,2,"וַ⁠יֹּ֧אמְרוּ ל֣⁠וֹ עֲבָדָ֗י⁠ו יְבַקְשׁ֞וּ לַ⁠אדֹנִ֤⁠י הַ⁠מֶּ֨לֶךְ֙ נַעֲרָ֣ה בְתוּלָ֔ה וְ⁠עָֽמְדָה֙ לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ וּ⁠תְהִי־ל֖⁠וֹ סֹכֶ֑נֶת וְ⁠שָׁכְבָ֣ה בְ⁠חֵיקֶ֔⁠ךָ וְ⁠חַ֖ם לַ⁠אדֹנִ֥⁠י הַ⁠מֶּֽלֶךְ׃","wa⁠yò֧̇ʼmĕrẇ l֣⁠wò ʻàbádá֗y⁠w yĕbaqĕş̌֞ẇ la⁠ʼdòni֤⁠y ha⁠mė֨lekĕ֙ naʻàrá֣h bĕţẇlá֔h wĕ⁠ʻáֽmĕdáh֙ li⁠pĕné֣y ha⁠mė֔lekĕ ẇ⁠ţĕhiy-l֖⁠wò sòke֑neţ wĕ⁠şá̌kĕbá֣h bĕ⁠ẖéyqe֔⁠ká wĕ⁠ẖa֖m la⁠ʼdòni֥⁠y ha⁠mėֽlekĕ׃"],[1,3,"וַ⁠יְבַקְשׁוּ֙ נַעֲרָ֣ה יָפָ֔ה בְּ⁠כֹ֖ל גְּב֣וּל יִשְׂרָאֵ֑ל וַֽ⁠יִּמְצְא֗וּ אֶת־אֲבִישַׁג֙ הַ⁠שּׁ֣וּנַמִּ֔ית וַ⁠יָּבִ֥אוּ אֹתָ֖⁠הּ לַ⁠מֶּֽלֶךְ׃","wa⁠yĕbaqĕş̌ẇ֙ naʻàrá֣h yápá֔h bĕ̇⁠kò֖l gĕ̇b֣ẇl yişĕ̂ráʼé֑l waֽ⁠yi̇mĕẕĕʼ֗ẇ ʼeţ-ʼàbiyşǎg֙ ha⁠ş֣̇̌ẇnami̇֔yţ wa⁠yá̇bi֥ʼẇ ʼòţá֖⁠ḣ la⁠mėֽlekĕ׃"],[1,4,"וְ⁠הַֽ⁠נַּעֲרָ֖ה יָפָ֣ה עַד־מְאֹ֑ד וַ⁠תְּהִ֨י לַ⁠מֶּ֤לֶךְ סֹכֶ֨נֶת֙ וַ⁠תְּשָׁ֣רְתֵ֔⁠הוּ וְ⁠הַ⁠מֶּ֖לֶךְ לֹ֥א יְדָעָֽ⁠הּ׃","wĕ⁠haֽ⁠nȧʻàrá֖h yápá֣h ʻad-mĕʼò֑d wa⁠ţĕ̇hi֨y la⁠mė֤lekĕ sòke֨neţ֙ wa⁠ţĕ̇şá֣̌rĕţé֔⁠hẇ wĕ⁠ha⁠mė֖lekĕ lò֥ʼ yĕdáʻáֽ⁠ḣ׃"],[1,5,"וַ⁠אֲדֹנִיָּ֧ה בֶן־חַגִּ֛ית מִתְנַשֵּׂ֥א לֵ⁠אמֹ֖ר אֲנִ֣י אֶמְלֹ֑ךְ וַ⁠יַּ֣עַשׂ ל֗⁠וֹ רֶ֚כֶב וּ⁠פָ֣רָשִׁ֔ים וַ⁠חֲמִשִּׁ֥ים אִ֖ישׁ רָצִ֥ים לְ⁠פָנָֽי⁠ו׃","wa⁠ʼàdòniyá֧̇h ben-ẖagi֛̇yţ miţĕnaşé֥̇̂ʼ lé⁠ʼmò֖r ʼàni֣y ʼemĕlò֑kĕ wa⁠yȧ֣ʻaş̂ l֗⁠wò re֚keb ẇ⁠pá֣ráşǐ֔ym wa⁠ẖàmişi֥̇̌ym ʼi֖yş̌ ráẕi֥ym lĕ⁠pánáֽy⁠w׃"],[1,6,"וְ⁠לֹֽא־עֲצָב֨⁠וֹ אָבִ֤י⁠ו מִ⁠יָּמָי⁠ו֙ לֵ⁠אמֹ֔ר מַדּ֖וּעַ כָּ֣כָה עָשִׂ֑יתָ וְ⁠גַם־ה֤וּא טֽוֹב־תֹּ֨אַר֙ מְאֹ֔ד וְ⁠אֹת֥⁠וֹ יָלְדָ֖ה אַחֲרֵ֥י אַבְשָׁלֽוֹם׃","wĕ⁠lòֽʼ-ʻàẕáb֨⁠wò ʼábi֤y⁠w mi⁠yá̇máy⁠w֙ lé⁠ʼmò֔r maḋ֖ẇʻa ká֣̇káh ʻáşî֑yţá wĕ⁠gam-h֤ẇʼ tֽwòb-ţò̇֨ʼar֙ mĕʼò֔d wĕ⁠ʼòţ֥⁠wò yálĕdá֖h ʼaẖàré֥y ʼabĕşá̌lֽwòm׃"],[1,7,"וַ⁠יִּהְי֣וּ דְבָרָ֔י⁠ו עִ֚ם יוֹאָ֣ב בֶּן־צְרוּיָ֔ה וְ⁠עִ֖ם אֶבְיָתָ֣ר הַ⁠כֹּהֵ֑ן וַֽ⁠יַּעְזְר֔וּ אַחֲרֵ֖י אֲדֹנִיָּֽה׃","wa⁠yi̇hĕy֣ẇ dĕbárá֔y⁠w ʻi֚m ywòʼá֣b bėn-ẕĕrẇyá֔h wĕ⁠ʻi֖m ʼebĕyáţá֣r ha⁠kò̇hé֑n waֽ⁠yȧʻĕzĕr֔ẇ ʼaẖàré֖y ʼàdòniyáֽ̇h׃"],[1,8,"וְ⁠צָד֣וֹק הַ֠⁠כֹּהֵן וּ⁠בְנָיָ֨הוּ בֶן־יְהוֹיָדָ֜ע וְ⁠נָתָ֤ן הַ⁠נָּבִיא֙ וְ⁠שִׁמְעִ֣י וְ⁠רֵעִ֔י וְ⁠הַ⁠גִּבּוֹרִ֖ים אֲשֶׁ֣ר לְ⁠דָוִ֑ד לֹ֥א הָי֖וּ עִם־אֲדֹנִיָּֽהוּ׃","wĕ⁠ẕád֣wòq ha֠⁠kò̇hén ẇ⁠bĕnáyá֨hẇ ben-yĕhwòyádá֜ʻ wĕ⁠náţá֤n ha⁠ná̇biyʼ֙ wĕ⁠şǐmĕʻi֣y wĕ⁠réʻi֔y wĕ⁠ha⁠gi̇ḃwòri֖ym ʼàşě֣r lĕ⁠dáwi֑d lò֥ʼ háy֖ẇ ʻim-ʼàdòniyáֽ̇hẇ׃"],[1,9,"וַ⁠יִּזְבַּ֣ח אֲדֹנִיָּ֗הוּ צֹ֤אן וּ⁠בָקָר֙ וּ⁠מְרִ֔יא עִ֚ם אֶ֣בֶן הַזֹּחֶ֔לֶת אֲשֶׁר־אֵ֖צֶל עֵ֣ין רֹגֵ֑ל וַ⁠יִּקְרָ֗א אֶת־כָּל־אֶחָי⁠ו֙ בְּנֵ֣י הַ⁠מֶּ֔לֶךְ וּ⁠לְ⁠כָל־אַנְשֵׁ֥י יְהוּדָ֖ה עַבְדֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yi̇zĕbȧ֣ẖ ʼàdòniyá̇֗hẇ ẕò֤ʼn ẇ⁠báqár֙ ẇ⁠mĕri֔yʼ ʻi֚m ʼe֣ben hazò̇ẖe֔leţ ʼàşěr-ʼé֖ẕel ʻé֣yn rògé֑l wa⁠yi̇qĕrá֗ʼ ʼeţ-ká̇l-ʼeẖáy⁠w֙ bĕ̇né֣y ha⁠mė֔lekĕ ẇ⁠lĕ⁠kál-ʼanĕşé֥̌y yĕhẇdá֖h ʻabĕdé֥y ha⁠mėֽlekĕ׃"],[1,10,"וְֽ⁠אֶת־נָתָן֩ הַ⁠נָּבִ֨יא וּ⁠בְנָיָ֜הוּ וְ⁠אֶת־הַ⁠גִּבּוֹרִ֛ים וְ⁠אֶת־שְׁלֹמֹ֥ה אָחִ֖י⁠ו לֹ֥א קָרָֽא׃","wĕֽ⁠ʼeţ-náţán֩ ha⁠ná̇bi֨yʼ ẇ⁠bĕnáyá֜hẇ wĕ⁠ʼeţ-ha⁠gi̇ḃwòri֛ym wĕ⁠ʼeţ-şĕ̌lòmò֥h ʼáẖi֖y⁠w lò֥ʼ qáráֽʼ׃"],[1,11,"וַ⁠יֹּ֣אמֶר נָתָ֗ן אֶל־בַּת־שֶׁ֤בַע אֵם־שְׁלֹמֹה֙ לֵ⁠אמֹ֔ר הֲ⁠ל֣וֹא שָׁמַ֔עַתְּ כִּ֥י מָלַ֖ךְ אֲדֹנִיָּ֣הוּ בֶן־חַגִּ֑ית וַ⁠אֲדֹנֵ֥י⁠נוּ דָוִ֖ד לֹ֥א יָדָֽע׃","wa⁠yò֣̇ʼmer náţá֗n ʼel-bȧţ-şě֤baʻ ʼém-şĕ̌lòmòh֙ lé⁠ʼmò֔r hà⁠l֣wòʼ şá̌ma֔ʻaţĕ̇ ki֥̇y mála֖kĕ ʼàdòniyá֣̇hẇ ben-ẖagi֑̇yţ wa⁠ʼàdòné֥y⁠nẇ dáwi֖d lò֥ʼ yádáֽʻ׃"],[1,12,"וְ⁠עַתָּ֕ה לְכִ֛י אִיעָצֵ֥⁠ךְ נָ֖א עֵצָ֑ה וּ⁠מַלְּטִי֙ אֶת־נַפְשֵׁ֔⁠ךְ וְ⁠אֶת־נֶ֥פֶשׁ בְּנֵ֖⁠ךְ שְׁלֹמֹֽה׃","wĕ⁠ʻaţá̇֕h lĕki֛y ʼiyʻáẕé֥⁠kĕ ná֖ʼ ʻéẕá֑h ẇ⁠malĕ̇tiy֙ ʼeţ-napĕşé̌֔⁠kĕ wĕ⁠ʼeţ-ne֥peş̌ bĕ̇né֖⁠kĕ şĕ̌lòmòֽh׃"],[1,13,"לְכִ֞י וּ⁠בֹ֣אִי ׀ אֶל־הַ⁠מֶּ֣לֶךְ דָּוִ֗ד וְ⁠אָמַ֤רְתְּ אֵלָי⁠ו֙ הֲ⁠לֹֽא־אַתָּ֞ה אֲדֹנִ֣⁠י הַ⁠מֶּ֗לֶךְ נִשְׁבַּ֤עְתָּ לַ⁠אֲמָֽתְ⁠ךָ֙ לֵ⁠אמֹ֔ר כִּֽי־שְׁלֹמֹ֤ה בְנֵ⁠ךְ֙ יִמְלֹ֣ךְ אַחֲרַ֔⁠י וְ⁠ה֖וּא יֵשֵׁ֣ב עַל־כִּסְאִ֑⁠י וּ⁠מַדּ֖וּעַ מָלַ֥ךְ אֲדֹנִיָֽהוּ׃","lĕki֞y ẇ⁠bò֣ʼiy ׀ ʼel-ha⁠mė֣lekĕ dá̇wi֗d wĕ⁠ʼáma֤rĕţĕ̇ ʼéláy⁠w֙ hà⁠lòֽʼ-ʼaţá̇֞h ʼàdòni֣⁠y ha⁠mė֗lekĕ nişĕ̌bȧ֤ʻĕţá̇ la⁠ʼàmáֽţĕ⁠ká֙ lé⁠ʼmò֔r kiֽ̇y-şĕ̌lòmò֤h bĕné⁠kĕ֙ yimĕlò֣kĕ ʼaẖàra֔⁠y wĕ⁠h֖ẇʼ yéşé֣̌b ʻal-ki̇sĕʼi֑⁠y ẇ⁠maḋ֖ẇʻa mála֥kĕ ʼàdòniyáֽhẇ׃"],[1,14,"הִנֵּ֗ה עוֹדָ֛⁠ךְ מְדַבֶּ֥רֶת שָׁ֖ם עִם־הַ⁠מֶּ֑לֶךְ וַ⁠אֲנִי֙ אָב֣וֹא אַחֲרַ֔יִ⁠ךְ וּ⁠מִלֵּאתִ֖י אֶת־דְּבָרָֽיִ⁠ךְ׃","hiné̇֗h ʻwòdá֛⁠kĕ mĕdabė֥reţ şá֖̌m ʻim-ha⁠mė֑lekĕ wa⁠ʼàniy֙ ʼáb֣wòʼ ʼaẖàra֔yi⁠kĕ ẇ⁠milé̇ʼţi֖y ʼeţ-dĕ̇báráֽyi⁠kĕ׃"],[1,15,"וַ⁠תָּבֹ֨א בַת־שֶׁ֤בֶע אֶל־הַ⁠מֶּ֨לֶךְ֙ הַ⁠חַ֔דְרָ⁠ה וְ⁠הַ⁠מֶּ֖לֶךְ זָקֵ֣ן מְאֹ֑ד וַֽ⁠אֲבִישַׁג֙ הַ⁠שּׁ֣וּנַמִּ֔ית מְשָׁרַ֖ת אֶת־הַ⁠מֶּֽלֶךְ׃","wa⁠ţá̇bò֨ʼ baţ-şě֤beʻ ʼel-ha⁠mė֨lekĕ֙ ha⁠ẖa֔dĕrá⁠h wĕ⁠ha⁠mė֖lekĕ záqé֣n mĕʼò֑d waֽ⁠ʼàbiyşǎg֙ ha⁠ş֣̇̌ẇnami̇֔yţ mĕşá̌ra֖ţ ʼeţ-ha⁠mėֽlekĕ׃"],[1,16,"וַ⁠תִּקֹּ֣ד בַּת־שֶׁ֔בַע וַ⁠תִּשְׁתַּ֖חוּ לַ⁠מֶּ֑לֶךְ וַ⁠יֹּ֥אמֶר הַ⁠מֶּ֖לֶךְ מַה־לָּֽ⁠ךְ׃","wa⁠ţi̇qò֣̇d bȧţ-şě֔baʻ wa⁠ţi̇şĕ̌ţȧ֖ẖẇ la⁠mė֑lekĕ wa⁠yò֥̇ʼmer ha⁠mė֖lekĕ mah-láֽ̇⁠kĕ׃"],[1,17,"וַ⁠תֹּ֣אמֶר ל֗⁠וֹ אֲדֹנִ⁠י֙ אַתָּ֨ה נִשְׁבַּ֜עְתָּ בַּֽ⁠יהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ לַֽ⁠אֲמָתֶ֔⁠ךָ כִּֽי־שְׁלֹמֹ֥ה בְנֵ֖⁠ךְ יִמְלֹ֣ךְ אַחֲרָ֑⁠י וְ⁠ה֖וּא יֵשֵׁ֥ב עַל־כִּסְאִֽ⁠י׃","wa⁠ţò֣̇ʼmer l֗⁠wò ʼàdòni⁠y֙ ʼaţá̇֨h nişĕ̌bȧ֜ʻĕţá̇ bȧֽ⁠yhwá֤h ʼèlòhe֨y⁠ká֙ laֽ⁠ʼàmáţe֔⁠ká kiֽ̇y-şĕ̌lòmò֥h bĕné֖⁠kĕ yimĕlò֣kĕ ʼaẖàrá֑⁠y wĕ⁠h֖ẇʼ yéşé֥̌b ʻal-ki̇sĕʼiֽ⁠y׃"],[1,18,"וְ⁠עַתָּ֕ה הִנֵּ֥ה אֲדֹנִיָּ֖ה מָלָ֑ךְ וְ⁠עַתָּ֛ה אֲדֹנִ֥⁠י הַ⁠מֶּ֖לֶךְ לֹ֥א יָדָֽעְתָּ׃","wĕ⁠ʻaţá̇֕h hiné֥̇h ʼàdòniyá֖̇h málá֑kĕ wĕ⁠ʻaţá֛̇h ʼàdòni֥⁠y ha⁠mė֖lekĕ lò֥ʼ yádáֽʻĕţá̇׃"],[1,19,"וַ֠⁠יִּזְבַּח שׁ֥וֹר וּֽ⁠מְרִיא־וְ⁠צֹאן֮ לָ⁠רֹב֒ וַ⁠יִּקְרָא֙ לְ⁠כָל־בְּנֵ֣י הַ⁠מֶּ֔לֶךְ וּ⁠לְ⁠אֶבְיָתָר֙ הַ⁠כֹּהֵ֔ן וּ⁠לְ⁠יֹאָ֖ב שַׂ֣ר הַ⁠צָּבָ֑א וְ⁠לִ⁠שְׁלֹמֹ֥ה עַבְדְּ⁠ךָ֖ לֹ֥א קָרָֽא׃","wa֠⁠yi̇zĕbȧẖ ş֥̌wòr ẇֽ⁠mĕriyʼ-wĕ⁠ẕòʼn֮ lá⁠ròb֒ wa⁠yi̇qĕráʼ֙ lĕ⁠kál-bĕ̇né֣y ha⁠mė֔lekĕ ẇ⁠lĕ⁠ʼebĕyáţár֙ ha⁠kò̇hé֔n ẇ⁠lĕ⁠yòʼá֖b şâ֣r ha⁠ẕá̇bá֑ʼ wĕ⁠li⁠şĕ̌lòmò֥h ʻabĕdĕ̇⁠ká֖ lò֥ʼ qáráֽʼ׃"],[1,20,"וְ⁠אַתָּה֙ אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ עֵינֵ֥י כָל־יִשְׂרָאֵ֖ל עָלֶ֑י⁠ךָ לְ⁠הַגִּ֣יד לָ⁠הֶ֔ם מִ֗י יֵשֵׁ֛ב עַל־כִּסֵּ֥א אֲדֹנִֽ⁠י־הַ⁠מֶּ֖לֶךְ אַחֲרָֽי⁠ו׃","wĕ⁠ʼaţá̇h֙ ʼàdòni֣⁠y ha⁠mė֔lekĕ ʻéyné֥y kál-yişĕ̂ráʼé֖l ʻále֑y⁠ká lĕ⁠hagi֣̇yd lá⁠he֔m mi֗y yéşé֛̌b ʻal-ki̇sé֥̇ʼ ʼàdòniֽ⁠y-ha⁠mė֖lekĕ ʼaẖàráֽy⁠w׃"],[1,21,"וְ⁠הָיָ֕ה כִּ⁠שְׁכַ֥ב אֲדֹנִֽ⁠י־הַ⁠מֶּ֖לֶךְ עִם־אֲבֹתָ֑י⁠ו וְ⁠הָיִ֗יתִי אֲנִ֛י וּ⁠בְנִ֥⁠י שְׁלֹמֹ֖ה חַטָּאִֽים׃","wĕ⁠háyá֕h ki̇⁠şĕ̌ka֥b ʼàdòniֽ⁠y-ha⁠mė֖lekĕ ʻim-ʼàbòţá֑y⁠w wĕ⁠háyi֗yţiy ʼàni֛y ẇ⁠bĕni֥⁠y şĕ̌lòmò֖h ẖatá̇ʼiֽym׃"],[1,22,"וְ⁠הִנֵּ֛ה עוֹדֶ֥⁠נָּה מְדַבֶּ֖רֶת עִם־הַ⁠מֶּ֑לֶךְ וְ⁠נָתָ֥ן הַ⁠נָּבִ֖יא בָּֽא׃","wĕ⁠hiné֛̇h ʻwòde֥⁠ná̇h mĕdabė֖reţ ʻim-ha⁠mė֑lekĕ wĕ⁠náţá֥n ha⁠ná̇bi֖yʼ báֽ̇ʼ׃"],[1,23,"וַ⁠יַּגִּ֤ידוּ לַ⁠מֶּ֨לֶךְ֙ לֵ⁠אמֹ֔ר הִנֵּ֖ה נָתָ֣ן הַ⁠נָּבִ֑יא וַ⁠יָּבֹא֙ לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ וַ⁠יִּשְׁתַּ֧חוּ לַ⁠מֶּ֛לֶךְ עַל־אַפָּ֖י⁠ו אָֽרְצָ⁠ה׃","wa⁠yȧgi֤̇ydẇ la⁠mė֨lekĕ֙ lé⁠ʼmò֔r hiné֖̇h náţá֣n ha⁠ná̇bi֑yʼ wa⁠yá̇bòʼ֙ li⁠pĕné֣y ha⁠mė֔lekĕ wa⁠yi̇şĕ̌ţȧ֧ẖẇ la⁠mė֛lekĕ ʻal-ʼapá֖̇y⁠w ʼáֽrĕẕá⁠h׃"],[1,24,"וַ⁠יֹּאמֶר֮ נָתָן֒ אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ אַתָּ֣ה אָמַ֔רְתָּ אֲדֹנִיָּ֖הוּ יִמְלֹ֣ךְ אַחֲרָ֑⁠י וְ⁠ה֖וּא יֵשֵׁ֥ב עַל־כִּסְאִֽ⁠י׃","wa⁠yò̇ʼmer֮ náţán֒ ʼàdòni֣⁠y ha⁠mė֔lekĕ ʼaţá֣̇h ʼáma֔rĕţá̇ ʼàdòniyá֖̇hẇ yimĕlò֣kĕ ʼaẖàrá֑⁠y wĕ⁠h֖ẇʼ yéşé֥̌b ʻal-ki̇sĕʼiֽ⁠y׃"],[1,25,"כִּ֣י ׀ יָרַ֣ד הַ⁠יּ֗וֹם וַ֠⁠יִּזְבַּח שׁ֥וֹר וּֽ⁠מְרִיא־וְ⁠צֹאן֮ לָ⁠רֹב֒ וַ⁠יִּקְרָא֩ לְ⁠כָל־בְּנֵ֨י הַ⁠מֶּ֜לֶךְ וּ⁠לְ⁠שָׂרֵ֤י הַ⁠צָּבָא֙ וּ⁠לְ⁠אֶבְיָתָ֣ר הַ⁠כֹּהֵ֔ן וְ⁠הִנָּ֛⁠ם אֹכְלִ֥ים וְ⁠שֹׁתִ֖ים לְ⁠פָנָ֑י⁠ו וַ⁠יֹּ֣אמְר֔וּ יְחִ֖י הַ⁠מֶּ֥לֶךְ אֲדֹנִיָּֽהוּ׃","ki֣̇y ׀ yára֣d ha⁠ẏ֗wòm wa֠⁠yi̇zĕbȧẖ ş֥̌wòr ẇֽ⁠mĕriyʼ-wĕ⁠ẕòʼn֮ lá⁠ròb֒ wa⁠yi̇qĕráʼ֩ lĕ⁠kál-bĕ̇né֨y ha⁠mė֜lekĕ ẇ⁠lĕ⁠şá̂ré֤y ha⁠ẕá̇báʼ֙ ẇ⁠lĕ⁠ʼebĕyáţá֣r ha⁠kò̇hé֔n wĕ⁠hiná֛̇⁠m ʼòkĕli֥ym wĕ⁠şò̌ţi֖ym lĕ⁠páná֑y⁠w wa⁠yò֣̇ʼmĕr֔ẇ yĕẖi֖y ha⁠mė֥lekĕ ʼàdòniyáֽ̇hẇ׃"],[1,26,"וְ⁠לִ֣⁠י אֲנִֽי־עַ֠בְדֶּ⁠ךָ וּ⁠לְ⁠צָדֹ֨ק הַ⁠כֹּהֵ֜ן וְ⁠לִ⁠בְנָיָ֧הוּ בֶן־יְהוֹיָדָ֛ע וְ⁠לִ⁠שְׁלֹמֹ֥ה עַבְדְּ⁠ךָ֖ לֹ֥א קָרָֽא׃","wĕ⁠li֣⁠y ʼàniֽy-ʻa֠bĕdė⁠ká ẇ⁠lĕ⁠ẕádò֨q ha⁠kò̇hé֜n wĕ⁠li⁠bĕnáyá֧hẇ ben-yĕhwòyádá֛ʻ wĕ⁠li⁠şĕ̌lòmò֥h ʻabĕdĕ̇⁠ká֖ lò֥ʼ qáráֽʼ׃"],[1,27,"אִ֗ם מֵ⁠אֵת֙ אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ נִהְיָ֖ה הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וְ⁠לֹ֤א הוֹדַ֨עְתָּ֙ אֶֽת־עבדי⁠ך מִ֗י יֵשֵׁ֛ב עַל־כִּסֵּ֥א אֲדֹנִֽ⁠י־הַ⁠מֶּ֖לֶךְ אַחֲרָֽי⁠ו׃ס","ʼi֗m mé⁠ʼéţ֙ ʼàdòni֣⁠y ha⁠mė֔lekĕ nihĕyá֖h ha⁠dá̇bá֣r ha⁠zė֑h wĕ⁠lò֤ʼ hwòda֨ʻĕţá̇֙ ʼeֽţ-ʻbdy⁠k mi֗y yéşé֛̌b ʻal-ki̇sé֥̇ʼ ʼàdòniֽ⁠y-ha⁠mė֖lekĕ ʼaẖàráֽy⁠w׃s"],[1,28,"וַ⁠יַּ֨עַן הַ⁠מֶּ֤לֶךְ דָּוִד֙ וַ⁠יֹּ֔אמֶר קִרְאוּ־לִ֖⁠י לְ⁠בַת־שָׁ֑בַע וַ⁠תָּבֹא֙ לִ⁠פְנֵ֣י הַ⁠מֶּ֔לֶךְ וַֽ⁠תַּעֲמֹ֖ד לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yȧ֨ʻan ha⁠mė֤lekĕ dá̇wid֙ wa⁠yò̇֔ʼmer qirĕʼẇ-li֖⁠y lĕ⁠baţ-şá֑̌baʻ wa⁠ţá̇bòʼ֙ li⁠pĕné֣y ha⁠mė֔lekĕ waֽ⁠ţȧʻàmò֖d li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[1,29,"וַ⁠יִּשָּׁבַ֥ע הַ⁠מֶּ֖לֶךְ וַ⁠יֹּאמַ֑ר חַי־יְהוָ֕ה אֲשֶׁר־פָּדָ֥ה אֶת־נַפְשִׁ֖⁠י מִ⁠כָּל־צָרָֽה׃","wa⁠yi̇şá̇̌ba֥ʻ ha⁠mė֖lekĕ wa⁠yò̇ʼma֑r ẖay-yĕhwá֕h ʼàşěr-pá̇dá֥h ʼeţ-napĕşǐ֖⁠y mi⁠ká̇l-ẕáráֽh׃"],[1,30,"כִּ֡י כַּ⁠אֲשֶׁר֩ נִשְׁבַּ֨עְתִּי לָ֜⁠ךְ בַּ⁠יהוָ֨ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ לֵ⁠אמֹ֔ר כִּֽי־שְׁלֹמֹ֤ה בְנֵ⁠ךְ֙ יִמְלֹ֣ךְ אַחֲרַ֔⁠י וְ⁠ה֛וּא יֵשֵׁ֥ב עַל־כִּסְאִ֖⁠י תַּחְתָּ֑⁠י כִּ֛י כֵּ֥ן אֶעֱשֶׂ֖ה הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ki̇֡y kȧ⁠ʼàşěr֩ nişĕ̌bȧ֨ʻĕţi̇y lá֜⁠kĕ bȧ⁠yhwá֨h ʼèlòhé֤y yişĕ̂ráʼél֙ lé⁠ʼmò֔r kiֽ̇y-şĕ̌lòmò֤h bĕné⁠kĕ֙ yimĕlò֣kĕ ʼaẖàra֔⁠y wĕ⁠h֛ẇʼ yéşé֥̌b ʻal-ki̇sĕʼi֖⁠y ţȧẖĕţá֑̇⁠y ki֛̇y ké֥̇n ʼeʻèşê֖h ha⁠ẏ֥wòm ha⁠zėֽh׃"],[1,31,"וַ⁠תִּקֹּ֨ד בַּת־שֶׁ֤בַע אַפַּ֨יִם֙ אֶ֔רֶץ וַ⁠תִּשְׁתַּ֖חוּ לַ⁠מֶּ֑לֶךְ וַ⁠תֹּ֕אמֶר יְחִ֗י אֲדֹנִ֛⁠י הַ⁠מֶּ֥לֶךְ דָּוִ֖ד לְ⁠עֹלָֽם׃פ","wa⁠ţi̇qò̇֨d bȧţ-şě֤baʻ ʼapȧ֨yim֙ ʼe֔reẕ wa⁠ţi̇şĕ̌ţȧ֖ẖẇ la⁠mė֑lekĕ wa⁠ţò̇֕ʼmer yĕẖi֗y ʼàdòni֛⁠y ha⁠mė֥lekĕ dá̇wi֖d lĕ⁠ʻòláֽm׃p"],[1,32,"וַ⁠יֹּ֣אמֶר ׀ הַ⁠מֶּ֣לֶךְ דָּוִ֗ד קִרְאוּ־לִ֞⁠י לְ⁠צָד֤וֹק הַ⁠כֹּהֵן֙ וּ⁠לְ⁠נָתָ֣ן הַ⁠נָּבִ֔יא וְ⁠לִ⁠בְנָיָ֖הוּ בֶּן־יְהוֹיָדָ֑ע וַ⁠יָּבֹ֖אוּ לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yò֣̇ʼmer ׀ ha⁠mė֣lekĕ dá̇wi֗d qirĕʼẇ-li֞⁠y lĕ⁠ẕád֤wòq ha⁠kò̇hén֙ ẇ⁠lĕ⁠náţá֣n ha⁠ná̇bi֔yʼ wĕ⁠li⁠bĕnáyá֖hẇ bėn-yĕhwòyádá֑ʻ wa⁠yá̇bò֖ʼẇ li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[1,33,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ לָ⁠הֶ֗ם קְח֤וּ עִמָּ⁠כֶם֙ אֶת־עַבְדֵ֣י אֲדֹנֵי⁠כֶ֔ם וְ⁠הִרְכַּבְתֶּם֙ אֶת־שְׁלֹמֹ֣ה בְנִ֔⁠י עַל־הַ⁠פִּרְדָּ֖ה אֲשֶׁר־לִ֑⁠י וְ⁠הוֹרַדְתֶּ֥ם אֹת֖⁠וֹ אֶל־גִּחֽוֹן׃","wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ lá⁠he֗m qĕẖ֤ẇ ʻimá̇⁠kem֙ ʼeţ-ʻabĕdé֣y ʼàdònéy⁠ke֔m wĕ⁠hirĕkȧbĕţėm֙ ʼeţ-şĕ̌lòmò֣h bĕni֔⁠y ʻal-ha⁠pi̇rĕdá֖̇h ʼàşěr-li֑⁠y wĕ⁠hwòradĕţė֥m ʼòţ֖⁠wò ʼel-gi̇ẖֽwòn׃"],[1,34,"וּ⁠מָשַׁ֣ח אֹת֣⁠וֹ שָׁ֠ם צָד֨וֹק הַ⁠כֹּהֵ֜ן וְ⁠נָתָ֧ן הַ⁠נָּבִ֛יא לְ⁠מֶ֖לֶךְ עַל־יִשְׂרָאֵ֑ל וּ⁠תְקַעְתֶּם֙ בַּ⁠שּׁוֹפָ֔ר וַ⁠אֲמַרְתֶּ֕ם יְחִ֖י הַ⁠מֶּ֥לֶךְ שְׁלֹמֹֽה׃","ẇ⁠máşǎ֣ẖ ʼòţ֣⁠wò şá̌֠m ẕád֨wòq ha⁠kò̇hé֜n wĕ⁠náţá֧n ha⁠ná̇bi֛yʼ lĕ⁠me֖lekĕ ʻal-yişĕ̂ráʼé֑l ẇ⁠ţĕqaʻĕţėm֙ bȧ⁠ş̇̌wòpá֔r wa⁠ʼàmarĕţė֕m yĕẖi֖y ha⁠mė֥lekĕ şĕ̌lòmòֽh׃"],[1,35,"וַ⁠עֲלִיתֶ֣ם אַחֲרָ֗י⁠ו וּ⁠בָא֙ וְ⁠יָשַׁ֣ב עַל־כִּסְאִ֔⁠י וְ⁠ה֥וּא יִמְלֹ֖ךְ תַּחְתָּ֑⁠י וְ⁠אֹת֤⁠וֹ צִוִּ֨יתִי֙ לִֽ⁠הְי֣וֹת נָגִ֔יד עַל־יִשְׂרָאֵ֖ל וְ⁠עַל־יְהוּדָֽה׃","wa⁠ʻàliyţe֣m ʼaẖàrá֗y⁠w ẇ⁠báʼ֙ wĕ⁠yáşǎ֣b ʻal-ki̇sĕʼi֔⁠y wĕ⁠h֥ẇʼ yimĕlò֖kĕ ţȧẖĕţá֑̇⁠y wĕ⁠ʼòţ֤⁠wò ẕiwi̇֨yţiy֙ liֽ⁠hĕy֣wòţ nági֔yd ʻal-yişĕ̂ráʼé֖l wĕ⁠ʻal-yĕhẇdáֽh׃"],[1,36,"וַ⁠יַּ֨עַן בְּנָיָ֧הוּ בֶן־יְהֽוֹיָדָ֛ע אֶת־הַ⁠מֶּ֖לֶךְ וַ⁠יֹּ֣אמֶר ׀ אָמֵ֑ן כֵּ֚ן יֹאמַ֣ר יְהוָ֔ה אֱלֹהֵ֖י אֲדֹנִ֥⁠י הַ⁠מֶּֽלֶךְ׃","wa⁠yȧ֨ʻan bĕ̇náyá֧hẇ ben-yĕhֽwòyádá֛ʻ ʼeţ-ha⁠mė֖lekĕ wa⁠yò֣̇ʼmer ׀ ʼámé֑n ké֚̇n yòʼma֣r yĕhwá֔h ʼèlòhé֖y ʼàdòni֥⁠y ha⁠mėֽlekĕ׃"],[1,37,"כַּ⁠אֲשֶׁ֨ר הָיָ֤ה יְהוָה֙ עִם־אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ כֵּ֖ן יהי עִם־שְׁלֹמֹ֑ה וִֽ⁠יגַדֵּל֙ אֶת־כִּסְא֔⁠וֹ מִ֨⁠כִּסֵּ֔א אֲדֹנִ֖⁠י הַ⁠מֶּ֥לֶךְ דָּוִֽד׃","kȧ⁠ʼàşě֨r háyá֤h yĕhwáh֙ ʻim-ʼàdòni֣⁠y ha⁠mė֔lekĕ ké֖̇n yhy ʻim-şĕ̌lòmò֑h wiֽ⁠ygadé̇l֙ ʼeţ-ki̇sĕʼ֔⁠wò mi֨⁠ki̇sé̇֔ʼ ʼàdòni֖⁠y ha⁠mė֥lekĕ dá̇wiֽd׃"],[1,38,"וַ⁠יֵּ֣רֶד צָד֣וֹק הַ֠⁠כֹּהֵן וְ⁠נָתָ֨ן הַ⁠נָּבִ֜יא וּ⁠בְנָיָ֣הוּ בֶן־יְהוֹיָדָ֗ע וְ⁠הַ⁠כְּרֵתִי֙ וְ⁠הַ⁠פְּלֵתִ֔י וַ⁠יַּרְכִּ֨בוּ֙ אֶת־שְׁלֹמֹ֔ה עַל־פִּרְדַּ֖ת הַ⁠מֶּ֣לֶךְ דָּוִ֑ד וַ⁠יֹּלִ֥כוּ אֹת֖⁠וֹ עַל־גִּחֽוֹן׃","wa⁠yé֣̇red ẕád֣wòq ha֠⁠kò̇hén wĕ⁠náţá֨n ha⁠ná̇bi֜yʼ ẇ⁠bĕnáyá֣hẇ ben-yĕhwòyádá֗ʻ wĕ⁠ha⁠kĕ̇réţiy֙ wĕ⁠ha⁠pĕ̇léţi֔y wa⁠yȧrĕki̇֨bẇ֙ ʼeţ-şĕ̌lòmò֔h ʻal-pi̇rĕdȧ֖ţ ha⁠mė֣lekĕ dá̇wi֑d wa⁠yò̇li֥kẇ ʼòţ֖⁠wò ʻal-gi̇ẖֽwòn׃"],[1,39,"וַ⁠יִּקַּח֩ צָד֨וֹק הַ⁠כֹּהֵ֜ן אֶת־קֶ֤רֶן הַ⁠שֶּׁ֨מֶן֙ מִן־הָ⁠אֹ֔הֶל וַ⁠יִּמְשַׁ֖ח אֶת־שְׁלֹמֹ֑ה וַֽ⁠יִּתְקְעוּ֙ בַּ⁠שּׁוֹפָ֔ר וַ⁠יֹּֽאמְרוּ֙ כָּל־הָ⁠עָ֔ם יְחִ֖י הַ⁠מֶּ֥לֶךְ שְׁלֹמֹֽה׃","wa⁠yi̇qȧẖ֩ ẕád֨wòq ha⁠kò̇hé֜n ʼeţ-qe֤ren ha⁠şė̌֨men֙ min-há⁠ʼò֔hel wa⁠yi̇mĕşǎ֖ẖ ʼeţ-şĕ̌lòmò֑h waֽ⁠yi̇ţĕqĕʻẇ֙ bȧ⁠ş̇̌wòpá֔r wa⁠yòֽ̇ʼmĕrẇ֙ ká̇l-há⁠ʻá֔m yĕẖi֖y ha⁠mė֥lekĕ şĕ̌lòmòֽh׃"],[1,40,"וַ⁠יַּעֲל֤וּ כָל־הָ⁠עָם֙ אַֽחֲרָ֔י⁠ו וְ⁠הָ⁠עָם֙ מְחַלְּלִ֣ים בַּ⁠חֲלִלִ֔ים וּ⁠שְׂמֵחִ֖ים שִׂמְחָ֣ה גְדוֹלָ֑ה וַ⁠תִּבָּקַ֥ע הָ⁠אָ֖רֶץ בְּ⁠קוֹלָֽ⁠ם׃","wa⁠yȧʻàl֤ẇ kál-há⁠ʻám֙ ʼֽaẖàrá֔y⁠w wĕ⁠há⁠ʻám֙ mĕẖalĕ̇li֣ym bȧ⁠ẖàlili֔ym ẇ⁠şĕ̂méẖi֖ym şîmĕẖá֣h gĕdwòlá֑h wa⁠ţi̇bá̇qa֥ʻ há⁠ʼá֖reẕ bĕ̇⁠qwòláֽ⁠m׃"],[1,41,"וַ⁠יִּשְׁמַ֣ע אֲדֹנִיָּ֗הוּ וְ⁠כָל־הַ⁠קְּרֻאִים֙ אֲשֶׁ֣ר אִתּ֔⁠וֹ וְ⁠הֵ֖ם כִּלּ֣וּ לֶ⁠אֱכֹ֑ל וַ⁠יִּשְׁמַ֤ע יוֹאָב֙ אֶת־ק֣וֹל הַ⁠שּׁוֹפָ֔ר וַ⁠יֹּ֕אמֶר מַדּ֥וּעַ קֽוֹל־הַ⁠קִּרְיָ֖ה הוֹמָֽה׃","wa⁠yi̇şĕ̌ma֣ʻ ʼàdòniyá̇֗hẇ wĕ⁠kál-ha⁠qĕ̇ruʼiym֙ ʼàşě֣r ʼiţ̇֔⁠wò wĕ⁠hé֖m ki̇l֣̇ẇ le⁠ʼèkò֑l wa⁠yi̇şĕ̌ma֤ʻ ywòʼáb֙ ʼeţ-q֣wòl ha⁠ş̇̌wòpá֔r wa⁠yò̇֕ʼmer maḋ֥ẇʻa qֽwòl-ha⁠qi̇rĕyá֖h hwòmáֽh׃"],[1,42,"עוֹדֶ֣⁠נּוּ מְדַבֵּ֔ר וְ⁠הִנֵּ֧ה יוֹנָתָ֛ן בֶּן־אֶבְיָתָ֥ר הַ⁠כֹּהֵ֖ן בָּ֑א וַ⁠יֹּ֤אמֶר אֲדֹנִיָּ֨הוּ֙ בֹּ֔א כִּ֣י אִ֥ישׁ חַ֛יִל אַ֖תָּה וְ⁠ט֥וֹב תְּבַשֵּֽׂר׃","ʻwòde֣⁠ṅẇ mĕdabé̇֔r wĕ⁠hiné֧̇h ywònáţá֛n bėn-ʼebĕyáţá֥r ha⁠kò̇hé֖n bá֑̇ʼ wa⁠yò֤̇ʼmer ʼàdòniyá̇֨hẇ֙ bò̇֔ʼ ki֣̇y ʼi֥yş̌ ẖa֛yil ʼa֖ţá̇h wĕ⁠t֥wòb ţĕ̇başéֽ̇̂r׃"],[1,43,"וַ⁠יַּ֨עַן֙ יוֹנָתָ֔ן וַ⁠יֹּ֖אמֶר לַ⁠אֲדֹנִיָּ֑הוּ אֲבָ֕ל אֲדֹנֵ֥י⁠נוּ הַ⁠מֶּֽלֶךְ־דָּוִ֖ד הִמְלִ֥יךְ אֶת־שְׁלֹמֹֽה׃","wa⁠yȧ֨ʻan֙ ywònáţá֔n wa⁠yò֖̇ʼmer la⁠ʼàdòniyá֑̇hẇ ʼàbá֕l ʼàdòné֥y⁠nẇ ha⁠mėֽlekĕ-dá̇wi֖d himĕli֥ykĕ ʼeţ-şĕ̌lòmòֽh׃"],[1,44,"וַ⁠יִּשְׁלַ֣ח אִתּֽ⁠וֹ־הַ֠⁠מֶּלֶךְ אֶת־צָד֨וֹק הַ⁠כֹּהֵ֜ן וְ⁠אֶת־נָתָ֣ן הַ⁠נָּבִ֗יא וּ⁠בְנָיָ֨הוּ֙ בֶּן־יְה֣וֹיָדָ֔ע וְ⁠הַ⁠כְּרֵתִ֖י וְ⁠הַ⁠פְּלֵתִ֑י וַ⁠יַּרְכִּ֣בוּ אֹת֔⁠וֹ עַ֖ל פִּרְדַּ֥ת הַ⁠מֶּֽלֶךְ׃","wa⁠yi̇şĕ̌la֣ẖ ʼiţֽ̇⁠wò-ha֠⁠mėlekĕ ʼeţ-ẕád֨wòq ha⁠kò̇hé֜n wĕ⁠ʼeţ-náţá֣n ha⁠ná̇bi֗yʼ ẇ⁠bĕnáyá֨hẇ֙ bėn-yĕh֣wòyádá֔ʻ wĕ⁠ha⁠kĕ̇réţi֖y wĕ⁠ha⁠pĕ̇léţi֑y wa⁠yȧrĕki֣̇bẇ ʼòţ֔⁠wò ʻa֖l pi̇rĕdȧ֥ţ ha⁠mėֽlekĕ׃"],[1,45,"וַ⁠יִּמְשְׁח֣וּ אֹת֡⁠וֹ צָד֣וֹק הַ⁠כֹּהֵ֣ן וְ⁠נָתָן֩ הַ⁠נָּבִ֨יא לְ⁠מֶ֜לֶךְ בְּ⁠גִח֗וֹן וַ⁠יַּעֲל֤וּ מִ⁠שָּׁם֙ שְׂמֵחִ֔ים וַ⁠תֵּהֹ֖ם הַ⁠קִּרְיָ֑ה ה֥וּא הַ⁠קּ֖וֹל אֲשֶׁ֥ר שְׁמַעְתֶּֽם׃","wa⁠yi̇mĕşĕ̌ẖ֣ẇ ʼòţ֡⁠wò ẕád֣wòq ha⁠kò̇hé֣n wĕ⁠náţán֩ ha⁠ná̇bi֨yʼ lĕ⁠me֜lekĕ bĕ̇⁠giẖ֗wòn wa⁠yȧʻàl֤ẇ mi⁠şá̇̌m֙ şĕ̂méẖi֔ym wa⁠ţé̇hò֖m ha⁠qi̇rĕyá֑h h֥ẇʼ ha⁠q֖̇wòl ʼàşě֥r şĕ̌maʻĕţėֽm׃"],[1,46,"וְ⁠גַם֙ יָשַׁ֣ב שְׁלֹמֹ֔ה עַ֖ל כִּסֵּ֥א הַ⁠מְּלוּכָֽה׃","wĕ⁠gam֙ yáşǎ֣b şĕ̌lòmò֔h ʻa֖l ki̇sé֥̇ʼ ha⁠mĕ̇lẇkáֽh׃"],[1,47,"וְ⁠גַם־בָּ֜אוּ עַבְדֵ֣י הַ⁠מֶּ֗לֶךְ לְ֠⁠בָרֵךְ אֶת־אֲדֹנֵ֜י⁠נוּ הַ⁠מֶּ֣לֶךְ דָּוִד֮ לֵ⁠אמֹר֒ יֵיטֵ֨ב אלהי⁠ך אֶת־שֵׁ֤ם שְׁלֹמֹה֙ מִ⁠שְּׁמֶ֔⁠ךָ וִֽ⁠יגַדֵּ֥ל אֶת־כִּסְא֖⁠וֹ מִ⁠כִּסְאֶ֑⁠ךָ וַ⁠יִּשְׁתַּ֥חוּ הַ⁠מֶּ֖לֶךְ עַל־הַ⁠מִּשְׁכָּֽב׃","wĕ⁠gam-bá̇֜ʼẇ ʻabĕdé֣y ha⁠mė֗lekĕ lĕ֠⁠bárékĕ ʼeţ-ʼàdòné֜y⁠nẇ ha⁠mė֣lekĕ dá̇wid֮ lé⁠ʼmòr֒ yéyté֨b ʼlhy⁠k ʼeţ-şé֤̌m şĕ̌lòmòh֙ mi⁠şĕ̇̌me֔⁠ká wiֽ⁠ygadé֥̇l ʼeţ-ki̇sĕʼ֖⁠wò mi⁠ki̇sĕʼe֑⁠ká wa⁠yi̇şĕ̌ţȧ֥ẖẇ ha⁠mė֖lekĕ ʻal-ha⁠mi̇şĕ̌káֽ̇b׃"],[1,48,"וְ⁠גַם־כָּ֖כָה אָמַ֣ר הַ⁠מֶּ֑לֶךְ בָּר֨וּךְ יְהוָ֜ה אֱלֹהֵ֣י יִשְׂרָאֵ֗ל אֲשֶׁ֨ר נָתַ֥ן הַ⁠יּ֛וֹם יֹשֵׁ֥ב עַל־כִּסְאִ֖⁠י וְ⁠עֵינַ֥⁠י רֹאֽוֹת׃","wĕ⁠gam-ká֖̇káh ʼáma֣r ha⁠mė֑lekĕ bá̇r֨ẇkĕ yĕhwá֜h ʼèlòhé֣y yişĕ̂ráʼé֗l ʼàşě֨r náţa֥n ha⁠ẏ֛wòm yòşé֥̌b ʻal-ki̇sĕʼi֖⁠y wĕ⁠ʻéyna֥⁠y ròʼֽwòţ׃"],[1,49,"וַ⁠יֶּֽחֶרְדוּ֙ וַ⁠יָּקֻ֔מוּ כָּל־הַ֨⁠קְּרֻאִ֔ים אֲשֶׁ֖ר לַ⁠אֲדֹנִיָּ֑הוּ וַ⁠יֵּלְכ֖וּ אִ֥ישׁ לְ⁠דַרְכּֽ⁠וֹ׃","wa⁠ẏֽeẖerĕdẇ֙ wa⁠yá̇qu֔mẇ ká̇l-ha֨⁠qĕ̇ruʼi֔ym ʼàşě֖r la⁠ʼàdòniyá֑̇hẇ wa⁠yé̇lĕk֖ẇ ʼi֥yş̌ lĕ⁠darĕkֽ̇⁠wò׃"],[1,50,"וַ⁠אֲדֹ֣נִיָּ֔הוּ יָרֵ֖א מִ⁠פְּנֵ֣י שְׁלֹמֹ֑ה וַ⁠יָּ֣קָם וַ⁠יֵּ֔לֶךְ וַֽ⁠יַּחֲזֵ֖ק בְּ⁠קַרְנ֥וֹת הַ⁠מִּזְבֵּֽחַ׃","wa⁠ʼàdò֣niyá̇֔hẇ yáré֖ʼ mi⁠pĕ̇né֣y şĕ̌lòmò֑h wa⁠yá֣̇qám wa⁠yé̇֔lekĕ waֽ⁠yȧẖàzé֖q bĕ̇⁠qarĕn֥wòţ ha⁠mi̇zĕbéֽ̇ẖa׃"],[1,51,"וַ⁠יֻּגַּ֤ד לִ⁠שְׁלֹמֹה֙ לֵ⁠אמֹ֔ר הִנֵּה֙ אֲדֹ֣נִיָּ֔הוּ יָרֵ֖א אֶת־הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֑ה וְ֠⁠הִנֵּה אָחַ֞ז בְּ⁠קַרְנ֤וֹת הַ⁠מִּזְבֵּ֨חַ֙ לֵ⁠אמֹ֔ר יִשָּֽׁבַֽע־לִ֤⁠י כַ⁠יּוֹם֙ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה אִם־יָמִ֥ית אֶת־עַבְדּ֖⁠וֹ בֶּ⁠חָֽרֶב׃","wa⁠yu̇gȧ֤d li⁠şĕ̌lòmòh֙ lé⁠ʼmò֔r hiné̇h֙ ʼàdò֣niyá̇֔hẇ yáré֖ʼ ʼeţ-ha⁠mė֣lekĕ şĕ̌lòmò֑h wĕ֠⁠hiné̇h ʼáẖa֞z bĕ̇⁠qarĕn֤wòţ ha⁠mi̇zĕbé̇֨ẖa֙ lé⁠ʼmò֔r yişáֽ̇̌baֽʻ-li֤⁠y ka⁠ẏwòm֙ ha⁠mė֣lekĕ şĕ̌lòmò֔h ʼim-yámi֥yţ ʼeţ-ʻabĕḋ֖⁠wò bė⁠ẖáֽreb׃"],[1,52,"וַ⁠יֹּ֣אמֶר שְׁלֹמֹ֔ה אִ֚ם יִהְיֶ֣ה לְ⁠בֶן־חַ֔יִל לֹֽא־יִפֹּ֥ל מִ⁠שַּׂעֲרָת֖⁠וֹ אָ֑רְצָ⁠ה וְ⁠אִם־רָעָ֥ה תִמָּצֵא־ב֖⁠וֹ וָ⁠מֵֽת׃","wa⁠yò֣̇ʼmer şĕ̌lòmò֔h ʼi֚m yihĕye֣h lĕ⁠ben-ẖa֔yil lòֽʼ-yipò֥̇l mi⁠şȧ̂ʻàráţ֖⁠wò ʼá֑rĕẕá⁠h wĕ⁠ʼim-ráʻá֥h ţimá̇ẕéʼ-b֖⁠wò wá⁠méֽţ׃"],[1,53,"וַ⁠יִּשְׁלַ֞ח הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֗ה וַ⁠יֹּרִדֻ֨⁠הוּ֙ מֵ⁠עַ֣ל הַ⁠מִּזְבֵּ֔חַ וַ⁠יָּבֹ֕א וַ⁠יִּשְׁתַּ֖חוּ לַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֑ה וַ⁠יֹּֽאמֶר־ל֥⁠וֹ שְׁלֹמֹ֖ה לֵ֥ךְ לְ⁠בֵיתֶֽ⁠ךָ׃פ","wa⁠yi̇şĕ̌la֞ẖ ha⁠mė֣lekĕ şĕ̌lòmò֗h wa⁠yò̇ridu֨⁠hẇ֙ mé⁠ʻa֣l ha⁠mi̇zĕbé̇֔ẖa wa⁠yá̇bò֕ʼ wa⁠yi̇şĕ̌ţȧ֖ẖẇ la⁠mė֣lekĕ şĕ̌lòmò֑h wa⁠yòֽ̇ʼmer-l֥⁠wò şĕ̌lòmò֖h lé֥kĕ lĕ⁠béyţeֽ⁠ká׃p"],[2,1,"וַ⁠יִּקְרְב֥וּ יְמֵֽי־דָוִ֖ד לָ⁠מ֑וּת וַ⁠יְצַ֛ו אֶת־שְׁלֹמֹ֥ה בְנ֖⁠וֹ לֵ⁠אמֹֽר׃","wa⁠yi̇qĕrĕb֥ẇ yĕméֽy-dáwi֖d lá⁠m֑ẇţ wa⁠yĕẕa֛w ʼeţ-şĕ̌lòmò֥h bĕn֖⁠wò lé⁠ʼmòֽr׃"],[2,2,"אָנֹכִ֣י הֹלֵ֔ךְ בְּ⁠דֶ֖רֶךְ כָּל־הָ⁠אָ֑רֶץ וְ⁠חָזַקְתָּ֖ וְ⁠הָיִ֥יתָֽ לְ⁠אִֽישׁ׃","ʼánòki֣y hòlé֔kĕ bĕ̇⁠de֖rekĕ ká̇l-há⁠ʼá֑reẕ wĕ⁠ẖázaqĕţá֖̇ wĕ⁠háyi֥yţáֽ lĕ⁠ʼiֽyş̌׃"],[2,3,"וְ⁠שָׁמַרְתָּ֞ אֶת־מִשְׁמֶ֣רֶת ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ לָ⁠לֶ֤כֶת בִּ⁠דְרָכָי⁠ו֙ לִ⁠שְׁמֹ֨ר חֻקֹּתָ֤י⁠ו מִצְוֺתָי⁠ו֙ וּ⁠מִשְׁפָּטָ֣י⁠ו וְ⁠עֵדְוֺתָ֔י⁠ו כַּ⁠כָּת֖וּב בְּ⁠תוֹרַ֣ת מֹשֶׁ֑ה לְמַ֣עַן תַּשְׂכִּ֗יל אֵ֚ת כָּל־אֲשֶׁ֣ר תַּֽעֲשֶׂ֔ה וְ⁠אֵ֛ת כָּל־אֲשֶׁ֥ר תִּפְנֶ֖ה שָֽׁם׃","wĕ⁠şá̌marĕţá̇֞ ʼeţ-mişĕ̌me֣reţ ׀ yĕhwá֣h ʼèlòhe֗y⁠ká lá⁠le֤keţ bi̇⁠dĕrákáy⁠w֙ li⁠şĕ̌mò֨r ẖuqò̇ţá֤y⁠w miẕĕwֺţáy⁠w֙ ẇ⁠mişĕ̌pá̇tá֣y⁠w wĕ⁠ʻédĕwֺţá֔y⁠w kȧ⁠ká̇ţ֖ẇb bĕ̇⁠ţwòra֣ţ mòşě֑h lĕma֣ʻan ţȧşĕ̂ki̇֗yl ʼé֚ţ ká̇l-ʼàşě֣r ţȧֽʻàşê֔h wĕ⁠ʼé֛ţ ká̇l-ʼàşě֥r ţi̇pĕne֖h şáֽ̌m׃"],[2,4,"לְמַעַן֩ יָקִ֨ים יְהוָ֜ה אֶת־דְּבָר֗⁠וֹ אֲשֶׁ֨ר דִּבֶּ֣ר עָלַ⁠י֮ לֵ⁠אמֹר֒ אִם־יִשְׁמְר֨וּ בָנֶ֜י⁠ךָ אֶת־דַּרְכָּ֗⁠ם לָ⁠לֶ֤כֶת לְ⁠פָנַ⁠י֙ בֶּ⁠אֱמֶ֔ת בְּ⁠כָל־לְבָבָ֖⁠ם וּ⁠בְ⁠כָל־נַפְשָׁ֑⁠ם לֵ⁠אמֹ֕ר לֹֽא־יִכָּרֵ֤ת לְ⁠ךָ֙ אִ֔ישׁ מֵ⁠עַ֖ל כִּסֵּ֥א יִשְׂרָאֵֽל׃","lĕmaʻan֩ yáqi֨ym yĕhwá֜h ʼeţ-dĕ̇bár֗⁠wò ʼàşě֨r di̇bė֣r ʻála⁠y֮ lé⁠ʼmòr֒ ʼim-yişĕ̌mĕr֨ẇ báne֜y⁠ká ʼeţ-dȧrĕká̇֗⁠m lá⁠le֤keţ lĕ⁠pána⁠y֙ bė⁠ʼème֔ţ bĕ̇⁠kál-lĕbábá֖⁠m ẇ⁠bĕ⁠kál-napĕşá֑̌⁠m lé⁠ʼmò֕r lòֽʼ-yiká̇ré֤ţ lĕ⁠ká֙ ʼi֔yş̌ mé⁠ʻa֖l ki̇sé֥̇ʼ yişĕ̂ráʼéֽl׃"],[2,5,"וְ⁠גַ֣ם אַתָּ֣ה יָדַ֡עְתָּ אֵת֩ אֲשֶׁר־עָ֨שָׂה לִ֜⁠י יוֹאָ֣ב בֶּן־צְרוּיָ֗ה אֲשֶׁ֣ר עָשָׂ֣ה לִ⁠שְׁנֵֽי־שָׂרֵ֣י צִבְא֣וֹת יִ֠שְׂרָאֵל לְ⁠אַבְנֵ֨ר בֶּן־נֵ֜ר וְ⁠לַ⁠עֲמָשָׂ֤א בֶן־יֶ֨תֶר֙ וַ⁠יַּ֣הַרְגֵ֔⁠ם וַ⁠יָּ֥שֶׂם דְּמֵֽי־מִלְחָמָ֖ה בְּ⁠שָׁלֹ֑ם וַ⁠יִּתֵּ֞ן דְּמֵ֣י מִלְחָמָ֗ה בַּ⁠חֲגֹֽרָת⁠וֹ֙ אֲשֶׁ֣ר בְּ⁠מָתְנָ֔י⁠ו וּֽ⁠בְ⁠נַעֲל֖⁠וֹ אֲשֶׁ֥ר בְּ⁠רַגְלָֽי⁠ו׃","wĕ⁠ga֣m ʼaţá֣̇h yáda֡ʻĕţá̇ ʼéţ֩ ʼàşěr-ʻá֨şá̂h li֜⁠y ywòʼá֣b bėn-ẕĕrẇyá֗h ʼàşě֣r ʻáşá֣̂h li⁠şĕ̌néֽy-şá̂ré֣y ẕibĕʼ֣wòţ yi֠şĕ̂ráʼél lĕ⁠ʼabĕné֨r bėn-né֜r wĕ⁠la⁠ʻàmáşá֤̂ʼ ben-ye֨ţer֙ wa⁠yȧ֣harĕgé֔⁠m wa⁠yá֥̇şêm dĕ̇méֽy-milĕẖámá֖h bĕ̇⁠şá̌lò֑m wa⁠yi̇ţé̇֞n dĕ̇mé֣y milĕẖámá֗h bȧ⁠ẖàgòֽráţ⁠wò֙ ʼàşě֣r bĕ̇⁠máţĕná֔y⁠w ẇֽ⁠bĕ⁠naʻàl֖⁠wò ʼàşě֥r bĕ̇⁠ragĕláֽy⁠w׃"],[2,6,"וְ⁠עָשִׂ֖יתָ כְּ⁠חָכְמָתֶ֑⁠ךָ וְ⁠לֹֽא־תוֹרֵ֧ד שֵׂיבָת֛⁠וֹ בְּ⁠שָׁלֹ֖ם שְׁאֹֽל׃ס","wĕ⁠ʻáşî֖yţá kĕ̇⁠ẖákĕmáţe֑⁠ká wĕ⁠lòֽʼ-ţwòré֧d şé̂ybáţ֛⁠wò bĕ̇⁠şá̌lò֖m şĕ̌ʼòֽl׃s"],[2,7,"וְ⁠לִ⁠בְנֵ֨י בַרְזִלַּ֤י הַ⁠גִּלְעָדִי֙ תַּֽעֲשֶׂה־חֶ֔סֶד וְ⁠הָי֖וּ בְּ⁠אֹכְלֵ֣י שֻׁלְחָנֶ֑⁠ךָ כִּי־כֵן֙ קָרְב֣וּ אֵלַ֔⁠י בְּ⁠בָרְחִ֕⁠י מִ⁠פְּנֵ֖י אַבְשָׁל֥וֹם אָחִֽי⁠ךָ׃","wĕ⁠li⁠bĕné֨y barĕzilȧ֤y ha⁠gi̇lĕʻádiy֙ ţȧֽʻàşêh-ẖe֔sed wĕ⁠háy֖ẇ bĕ̇⁠ʼòkĕlé֣y şǔlĕẖáne֑⁠ká ki̇y-kén֙ qárĕb֣ẇ ʼéla֔⁠y bĕ̇⁠bárĕẖi֕⁠y mi⁠pĕ̇né֖y ʼabĕşá̌l֥wòm ʼáẖiֽy⁠ká׃"],[2,8,"וְ⁠הִנֵּ֣ה עִ֠מְּ⁠ךָ שִֽׁמְעִ֨י בֶן־גֵּרָ֥א בֶן־הַ⁠יְמִינִי֮ מִ⁠בַּחֻרִים֒ וְ⁠ה֤וּא קִֽלְלַ֨⁠נִי֙ קְלָלָ֣ה נִמְרֶ֔צֶת בְּ⁠י֖וֹם לֶכְתִּ֣⁠י מַחֲנָ֑יִם וְ⁠הֽוּא־יָרַ֤ד לִ⁠קְרָאתִ⁠י֙ הַ⁠יַּרְדֵּ֔ן וָ⁠אֶשָּׁ֨בַֽע ל֤⁠וֹ בַֽ⁠יהוָה֙ לֵ⁠אמֹ֔ר אִם־אֲמִֽיתְ⁠ךָ֖ בֶּ⁠חָֽרֶב׃","wĕ⁠hiné֣̇h ʻi֠mĕ̇⁠ká şǐֽmĕʻi֨y ben-gé̇rá֥ʼ ben-ha⁠yĕmiyniy֮ mi⁠bȧẖuriym֒ wĕ⁠h֤ẇʼ qiֽlĕla֨⁠niy֙ qĕlálá֣h nimĕre֔ẕeţ bĕ̇⁠y֖wòm lekĕţi֣̇⁠y maẖàná֑yim wĕ⁠hֽẇʼ-yára֤d li⁠qĕráʼţi⁠y֙ ha⁠yȧrĕdé̇֔n wá⁠ʼeşá̇̌֨baֽʻ l֤⁠wò baֽ⁠yhwáh֙ lé⁠ʼmò֔r ʼim-ʼàmiֽyţĕ⁠ká֖ bė⁠ẖáֽreb׃"],[2,9,"וְ⁠עַתָּה֙ אַל־תְּנַקֵּ֔⁠הוּ כִּ֛י אִ֥ישׁ חָכָ֖ם אָ֑תָּה וְ⁠יָֽדַעְתָּ֙ אֵ֣ת אֲשֶׁ֣ר תַּֽעֲשֶׂה־לּ֔⁠וֹ וְ⁠הוֹרַדְתָּ֧ אֶת־שֵׂיבָת֛⁠וֹ בְּ⁠דָ֖ם שְׁאֽוֹל׃","wĕ⁠ʻaţá̇h֙ ʼal-ţĕ̇naqé̇֔⁠hẇ ki֛̇y ʼi֥yş̌ ẖáká֖m ʼá֑ţá̇h wĕ⁠yáֽdaʻĕţá̇֙ ʼé֣ţ ʼàşě֣r ţȧֽʻàşêh-l̇֔⁠wò wĕ⁠hwòradĕţá֧̇ ʼeţ-şé̂ybáţ֛⁠wò bĕ̇⁠dá֖m şĕ̌ʼֽwòl׃"],[2,10,"וַ⁠יִּשְׁכַּ֥ב דָּוִ֖ד עִם־אֲבֹתָ֑י⁠ו וַ⁠יִּקָּבֵ֖ר בְּ⁠עִ֥יר דָּוִֽד׃פ","wa⁠yi̇şĕ̌kȧ֥b dá̇wi֖d ʻim-ʼàbòţá֑y⁠w wa⁠yi̇qá̇bé֖r bĕ̇⁠ʻi֥yr dá̇wiֽd׃p"],[2,11,"וְ⁠הַ⁠יָּמִ֗ים אֲשֶׁ֨ר מָלַ֤ךְ דָּוִד֙ עַל־יִשְׂרָאֵ֔ל אַרְבָּעִ֖ים שָׁנָ֑ה בְּ⁠חֶבְר֤וֹן מָלַךְ֙ שֶׁ֣בַע שָׁנִ֔ים וּ⁠בִ⁠ירוּשָׁלִַ֣ם מָלַ֔ךְ שְׁלֹשִׁ֥ים וְ⁠שָׁלֹ֖שׁ שָׁנִֽים׃","wĕ⁠ha⁠yá̇mi֗ym ʼàşě֨r mála֤kĕ dá̇wid֙ ʻal-yişĕ̂ráʼé֔l ʼarĕbá̇ʻi֖ym şá̌ná֑h bĕ̇⁠ẖebĕr֤wòn málakĕ֙ şě֣baʻ şá̌ni֔ym ẇ⁠bi⁠yrẇşá̌lia֣m mála֔kĕ şĕ̌lòşǐ֥ym wĕ⁠şá̌lò֖ş̌ şá̌niֽym׃"],[2,12,"וּ⁠שְׁלֹמֹ֕ה יָשַׁ֕ב עַל־כִּסֵּ֖א דָּוִ֣ד אָבִ֑י⁠ו וַ⁠תִּכֹּ֥ן מַלְכֻת֖⁠וֹ מְאֹֽד׃","ẇ⁠şĕ̌lòmò֕h yáşǎ֕b ʻal-ki̇sé֖̇ʼ dá̇wi֣d ʼábi֑y⁠w wa⁠ţi̇kò֥̇n malĕkuţ֖⁠wò mĕʼòֽd׃"],[2,13,"וַ⁠יָּבֹ֞א אֲדֹנִיָּ֣הוּ בֶן־חַגֵּ֗ית אֶל־בַּת־שֶׁ֨בַע֙ אֵם־שְׁלֹמֹ֔ה וַ⁠תֹּ֖אמֶר הֲ⁠שָׁל֣וֹם בֹּאֶ֑⁠ךָ וַ⁠יֹּ֖אמֶר שָׁלֽוֹם׃","wa⁠yá̇bò֞ʼ ʼàdòniyá֣̇hẇ ben-ẖagé̇֗yţ ʼel-bȧţ-şě֨baʻ֙ ʼém-şĕ̌lòmò֔h wa⁠ţò֖̇ʼmer hà⁠şá̌l֣wòm bò̇ʼe֑⁠ká wa⁠yò֖̇ʼmer şá̌lֽwòm׃"],[2,14,"וַ⁠יֹּ֕אמֶר דָּבָ֥ר לִ֖⁠י אֵלָ֑יִ⁠ךְ וַ⁠תֹּ֖אמֶר דַּבֵּֽר׃","wa⁠yò̇֕ʼmer dá̇bá֥r li֖⁠y ʼélá֑yi⁠kĕ wa⁠ţò֖̇ʼmer dȧbéֽ̇r׃"],[2,15,"וַ⁠יֹּ֗אמֶר אַ֤תְּ יָדַ֨עַתְּ֙ כִּי־לִ⁠י֙ הָיְתָ֣ה הַ⁠מְּלוּכָ֔ה וְ⁠עָלַ֞⁠י שָׂ֧מוּ כָֽל־יִשְׂרָאֵ֛ל פְּנֵי⁠הֶ֖ם לִ⁠מְלֹ֑ךְ וַ⁠תִּסֹּ֤ב הַ⁠מְּלוּכָה֙ וַ⁠תְּהִ֣י לְ⁠אָחִ֔⁠י כִּ֥י מֵ⁠יְהוָ֖ה הָ֥יְתָה לּֽ⁠וֹ׃","wa⁠yò̇֗ʼmer ʼa֤ţĕ̇ yáda֨ʻaţĕ̇֙ ki̇y-li⁠y֙ háyĕţá֣h ha⁠mĕ̇lẇká֔h wĕ⁠ʻála֞⁠y şá֧̂mẇ káֽl-yişĕ̂ráʼé֛l pĕ̇néy⁠he֖m li⁠mĕlò֑kĕ wa⁠ţi̇sò֤̇b ha⁠mĕ̇lẇkáh֙ wa⁠ţĕ̇hi֣y lĕ⁠ʼáẖi֔⁠y ki֥̇y mé⁠yĕhwá֖h há֥yĕţáh lֽ̇⁠wò׃"],[2,16,"וְ⁠עַתָּ֗ה שְׁאֵלָ֤ה אַחַת֙ אָֽנֹכִי֙ שֹׁאֵ֣ל מֵֽ⁠אִתָּ֔⁠ךְ אַל־תָּשִׁ֖בִי אֶת־פָּנָ֑⁠י וַ⁠תֹּ֥אמֶר אֵלָ֖י⁠ו דַּבֵּֽר׃","wĕ⁠ʻaţá̇֗h şĕ̌ʼélá֤h ʼaẖaţ֙ ʼáֽnòkiy֙ şò̌ʼé֣l méֽ⁠ʼiţá̇֔⁠kĕ ʼal-ţá̇şǐ֖biy ʼeţ-pá̇ná֑⁠y wa⁠ţò֥̇ʼmer ʼélá֖y⁠w dȧbéֽ̇r׃"],[2,17,"וַ⁠יֹּ֗אמֶר אִמְרִי־נָא֙ לִ⁠שְׁלֹמֹ֣ה הַ⁠מֶּ֔לֶךְ כִּ֥י לֹֽא־יָשִׁ֖יב אֶת־פָּנָ֑יִ⁠ךְ וְ⁠יִתֶּן־לִ֛⁠י אֶת־אֲבִישַׁ֥ג הַ⁠שּׁוּנַמִּ֖ית לְ⁠אִשָּֽׁה׃","wa⁠yò̇֗ʼmer ʼimĕriy-náʼ֙ li⁠şĕ̌lòmò֣h ha⁠mė֔lekĕ ki֥̇y lòֽʼ-yáşǐ֖yb ʼeţ-pá̇ná֑yi⁠kĕ wĕ⁠yiţėn-li֛⁠y ʼeţ-ʼàbiyşǎ֥g ha⁠ş̇̌ẇnami֖̇yţ lĕ⁠ʼişáֽ̇̌h׃"],[2,18,"וַ⁠תֹּ֥אמֶר בַּת־שֶׁ֖בַע ט֑וֹב אָנֹכִ֕י אֲדַבֵּ֥ר עָלֶ֖י⁠ךָ אֶל־הַ⁠מֶּֽלֶךְ׃","wa⁠ţò֥̇ʼmer bȧţ-şě֖baʻ t֑wòb ʼánòki֕y ʼàdabé֥̇r ʻále֖y⁠ká ʼel-ha⁠mėֽlekĕ׃"],[2,19,"וַ⁠תָּבֹ֤א בַת־שֶׁ֨בַע֙ אֶל־הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה לְ⁠דַבֶּר־ל֖⁠וֹ עַל־אֲדֹנִיָּ֑הוּ וַ⁠יָּקָם֩ הַ⁠מֶּ֨לֶךְ לִ⁠קְרָאתָ֜⁠הּ וַ⁠יִּשְׁתַּ֣חוּ לָ֗⁠הּ וַ⁠יֵּ֨שֶׁב֙ עַל־כִּסְא֔⁠וֹ וַ⁠יָּ֤שֶׂם כִּסֵּא֙ לְ⁠אֵ֣ם הַ⁠מֶּ֔לֶךְ וַ⁠תֵּ֖שֶׁב לִֽ⁠ימִינֽ⁠וֹ׃","wa⁠ţá̇bò֤ʼ baţ-şě֨baʻ֙ ʼel-ha⁠mė֣lekĕ şĕ̌lòmò֔h lĕ⁠dabėr-l֖⁠wò ʻal-ʼàdòniyá֑̇hẇ wa⁠yá̇qám֩ ha⁠mė֨lekĕ li⁠qĕráʼţá֜⁠ḣ wa⁠yi̇şĕ̌ţȧ֣ẖẇ lá֗⁠ḣ wa⁠yé̇֨şěb֙ ʻal-ki̇sĕʼ֔⁠wò wa⁠yá֤̇şêm ki̇sé̇ʼ֙ lĕ⁠ʼé֣m ha⁠mė֔lekĕ wa⁠ţé֖̇şěb liֽ⁠ymiynֽ⁠wò׃"],[2,20,"וַ⁠תֹּ֗אמֶר שְׁאֵלָ֨ה אַחַ֤ת קְטַנָּה֙ אָֽנֹכִי֙ שֹׁאֶ֣לֶת מֵֽ⁠אִתָּ֔⁠ךְ אַל־תָּ֖שֶׁב אֶת־פָּנָ֑⁠י וַ⁠יֹּֽאמֶר־לָ֤⁠הּ הַ⁠מֶּ֨לֶךְ֙ שַׁאֲלִ֣י אִמִּ֔⁠י כִּ֥י לֹֽא־אָשִׁ֖יב אֶת־פָּנָֽיִ⁠ךְ׃","wa⁠ţò̇֗ʼmer şĕ̌ʼélá֨h ʼaẖa֤ţ qĕtaná̇h֙ ʼáֽnòkiy֙ şò̌ʼe֣leţ méֽ⁠ʼiţá̇֔⁠kĕ ʼal-ţá֖̇şěb ʼeţ-pá̇ná֑⁠y wa⁠yòֽ̇ʼmer-lá֤⁠ḣ ha⁠mė֨lekĕ֙ şǎʼàli֣y ʼimi̇֔⁠y ki֥̇y lòֽʼ-ʼáşǐ֖yb ʼeţ-pá̇náֽyi⁠kĕ׃"],[2,21,"וַ⁠תֹּ֕אמֶר יֻתַּ֖ן אֶת־אֲבִישַׁ֣ג הַ⁠שֻּׁנַמִּ֑ית לַ⁠אֲדֹנִיָּ֥הוּ אָחִ֖י⁠ךָ לְ⁠אִשָּֽׁה׃","wa⁠ţò̇֕ʼmer yuţȧ֖n ʼeţ-ʼàbiyşǎ֣g ha⁠şu̇̌nami֑̇yţ la⁠ʼàdòniyá֥̇hẇ ʼáẖi֖y⁠ká lĕ⁠ʼişáֽ̇̌h׃"],[2,22,"וַ⁠יַּעַן֩ הַ⁠מֶּ֨לֶךְ שְׁלֹמֹ֜ה וַ⁠יֹּ֣אמֶר לְ⁠אִמּ֗⁠וֹ וְ⁠לָ⁠מָה֩ אַ֨תְּ שֹׁאֶ֜לֶת אֶת־אֲבִישַׁ֤ג הַ⁠שֻּׁנַמִּית֙ לַ⁠אֲדֹ֣נִיָּ֔הוּ וְ⁠שַֽׁאֲלִי־ל⁠וֹ֙ אֶת־הַ⁠מְּלוּכָ֔ה כִּ֛י ה֥וּא אָחִ֖⁠י הַ⁠גָּד֣וֹל מִמֶּ֑⁠נִּי וְ⁠ל⁠וֹ֙ וּ⁠לְ⁠אֶבְיָתָ֣ר הַ⁠כֹּהֵ֔ן וּ⁠לְ⁠יוֹאָ֖ב בֶּן־צְרוּיָֽה׃פ","wa⁠yȧʻan֩ ha⁠mė֨lekĕ şĕ̌lòmò֜h wa⁠yò֣̇ʼmer lĕ⁠ʼiṁ֗⁠wò wĕ⁠lá⁠máh֩ ʼa֨ţĕ̇ şò̌ʼe֜leţ ʼeţ-ʼàbiyşǎ֤g ha⁠şu̇̌nami̇yţ֙ la⁠ʼàdò֣niyá̇֔hẇ wĕ⁠şǎֽʼàliy-l⁠wò֙ ʼeţ-ha⁠mĕ̇lẇká֔h ki֛̇y h֥ẇʼ ʼáẖi֖⁠y ha⁠gá̇d֣wòl mimė֑⁠ni̇y wĕ⁠l⁠wò֙ ẇ⁠lĕ⁠ʼebĕyáţá֣r ha⁠kò̇hé֔n ẇ⁠lĕ⁠ywòʼá֖b bėn-ẕĕrẇyáֽh׃p"],[2,23,"וַ⁠יִּשָּׁבַע֙ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה בַּֽ⁠יהוָ֖ה לֵ⁠אמֹ֑ר כֹּ֣ה יַֽעֲשֶׂה־לִּ֤⁠י אֱלֹהִים֙ וְ⁠כֹ֣ה יוֹסִ֔יף כִּ֣י בְ⁠נַפְשׁ֔⁠וֹ דִּבֶּר֙ אֲדֹ֣נִיָּ֔הוּ אֶת־הַ⁠דָּבָ֖ר הַ⁠זֶּֽה׃","wa⁠yi̇şá̇̌baʻ֙ ha⁠mė֣lekĕ şĕ̌lòmò֔h bȧֽ⁠yhwá֖h lé⁠ʼmò֑r kò֣̇h yaֽʻàşêh-li֤̇⁠y ʼèlòhiym֙ wĕ⁠kò֣h ywòsi֔yp ki֣̇y bĕ⁠napĕş̌֔⁠wò di̇bėr֙ ʼàdò֣niyá̇֔hẇ ʼeţ-ha⁠dá̇bá֖r ha⁠zėֽh׃"],[2,24,"וְ⁠עַתָּ֗ה חַי־יְהוָה֙ אֲשֶׁ֣ר הֱכִינַ֗⁠נִי ו⁠יושיבי⁠ני עַל־כִּסֵּא֙ דָּוִ֣ד אָבִ֔⁠י וַ⁠אֲשֶׁ֧ר עָֽשָׂה־לִ֛⁠י בַּ֖יִת כַּ⁠אֲשֶׁ֣ר דִּבֵּ֑ר כִּ֣י הַ⁠יּ֔וֹם יוּמַ֖ת אֲדֹנִיָּֽהוּ׃","wĕ⁠ʻaţá̇֗h ẖay-yĕhwáh֙ ʼàşě֣r hèkiyna֗⁠niy w⁠ywşyby⁠ny ʻal-ki̇sé̇ʼ֙ dá̇wi֣d ʼábi֔⁠y wa⁠ʼàşě֧r ʻáֽşá̂h-li֛⁠y bȧ֖yiţ kȧ⁠ʼàşě֣r di̇bé֑̇r ki֣̇y ha⁠ẏ֔wòm yẇma֖ţ ʼàdòniyáֽ̇hẇ׃"],[2,25,"וַ⁠יִּשְׁלַח֙ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה בְּ⁠יַ֖ד בְּנָיָ֣הוּ בֶן־יְהוֹיָדָ֑ע וַ⁠יִּפְגַּע־בּ֖⁠וֹ וַ⁠יָּמֹֽת׃ס","wa⁠yi̇şĕ̌laẖ֙ ha⁠mė֣lekĕ şĕ̌lòmò֔h bĕ̇⁠ya֖d bĕ̇náyá֣hẇ ben-yĕhwòyádá֑ʻ wa⁠yi̇pĕgȧʻ-ḃ֖⁠wò wa⁠yá̇mòֽţ׃s"],[2,26,"וּ⁠לְ⁠אֶבְיָתָ֨ר הַ⁠כֹּהֵ֜ן אָמַ֣ר הַ⁠מֶּ֗לֶךְ עֲנָתֹת֙ לֵ֣ךְ עַל־שָׂדֶ֔י⁠ךָ כִּ֛י אִ֥ישׁ מָ֖וֶת אָ֑תָּה וּ⁠בַ⁠יּ֨וֹם הַ⁠זֶּ֜ה לֹ֣א אֲמִיתֶ֗⁠ךָ כִּֽי־נָשָׂ֜אתָ אֶת־אֲר֨וֹן אֲדֹנָ֤⁠י יְהֹוִה֙ לִ⁠פְנֵי֙ דָּוִ֣ד אָבִ֔⁠י וְ⁠כִ֣י הִתְעַנִּ֔יתָ בְּ⁠כֹ֥ל אֲשֶֽׁר־הִתְעַנָּ֖ה אָבִֽ⁠י׃","ẇ⁠lĕ⁠ʼebĕyáţá֨r ha⁠kò̇hé֜n ʼáma֣r ha⁠mė֗lekĕ ʻànáţòţ֙ lé֣kĕ ʻal-şá̂de֔y⁠ká ki֛̇y ʼi֥yş̌ má֖weţ ʼá֑ţá̇h ẇ⁠ba⁠ẏ֨wòm ha⁠zė֜h lò֣ʼ ʼàmiyţe֗⁠ká kiֽ̇y-náşá̂֜ʼţá ʼeţ-ʼàr֨wòn ʼàdòná֤⁠y yĕhòwih֙ li⁠pĕnéy֙ dá̇wi֣d ʼábi֔⁠y wĕ⁠ki֣y hiţĕʻani̇֔yţá bĕ̇⁠kò֥l ʼàşěֽr-hiţĕʻaná֖̇h ʼábiֽ⁠y׃"],[2,27,"וַ⁠יְגָ֤רֶשׁ שְׁלֹמֹה֙ אֶת־אֶבְיָתָ֔ר מִ⁠הְי֥וֹת כֹּהֵ֖ן לַֽ⁠יהוָ֑ה לְ⁠מַלֵּא֙ אֶת־דְּבַ֣ר יְהוָ֔ה אֲשֶׁ֥ר דִּבֶּ֛ר עַל־בֵּ֥ית עֵלִ֖י בְּ⁠שִׁלֹֽה׃פ","wa⁠yĕgá֤reş̌ şĕ̌lòmòh֙ ʼeţ-ʼebĕyáţá֔r mi⁠hĕy֥wòţ kò̇hé֖n laֽ⁠yhwá֑h lĕ⁠malé̇ʼ֙ ʼeţ-dĕ̇ba֣r yĕhwá֔h ʼàşě֥r di̇bė֛r ʻal-bé֥̇yţ ʻéli֖y bĕ̇⁠şǐlòֽh׃p"],[2,28,"וְ⁠הַ⁠שְּׁמֻעָה֙ בָּ֣אָה עַד־יוֹאָ֔ב כִּ֣י יוֹאָ֗ב נָטָה֙ אַחֲרֵ֣י אֲדֹנִיָּ֔ה וְ⁠אַחֲרֵ֥י אַבְשָׁל֖וֹם לֹ֣א נָטָ֑ה וַ⁠יָּ֤נָס יוֹאָב֙ אֶל־אֹ֣הֶל יְהוָ֔ה וַֽ⁠יַּחֲזֵ֖ק בְּ⁠קַרְנ֥וֹת הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠ha⁠şĕ̇̌muʻáh֙ bá֣̇ʼáh ʻad-ywòʼá֔b ki֣̇y ywòʼá֗b nátáh֙ ʼaẖàré֣y ʼàdòniyá̇֔h wĕ⁠ʼaẖàré֥y ʼabĕşá̌l֖wòm lò֣ʼ nátá֑h wa⁠yá֤̇nás ywòʼáb֙ ʼel-ʼò֣hel yĕhwá֔h wֽa⁠yȧẖàzé֖q bĕ̇⁠qarĕn֥wòţ ha⁠mi̇zĕbéֽ̇ẖa׃"],[2,29,"וַ⁠יֻּגַּ֞ד לַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֗ה כִּ֣י נָ֤ס יוֹאָב֙ אֶל־אֹ֣הֶל יְהוָ֔ה וְ⁠הִנֵּ֖ה אֵ֣צֶל הַ⁠מִּזְבֵּ֑חַ וַ⁠יִּשְׁלַ֨ח שְׁלֹמֹ֜ה אֶת־בְּנָיָ֧הוּ בֶן־יְהוֹיָדָ֛ע לֵ⁠אמֹ֖ר לֵ֥ךְ פְּגַע־בּֽ⁠וֹ׃","wa⁠yu̇gȧ֞d la⁠mė֣lekĕ şĕ̌lòmò֗h ki֣̇y ná֤s ywòʼáb֙ ʼel-ʼò֣hel yĕhwá֔h wĕ⁠hiné֖̇h ʼé֣ẕel ha⁠mi̇zĕbé֑̇ẖa wa⁠yi̇şĕ̌la֨ẖ şĕ̌lòmò֜h ʼeţ-bĕ̇náyá֧hẇ ben-yĕhwòyádá֛ʻ lé⁠ʼmò֖r lé֥kĕ pĕ̇gaʻ-ḃֽ⁠wò׃"],[2,30,"וַ⁠יָּבֹ֨א בְנָיָ֜הוּ אֶל־אֹ֣הֶל יְהוָ֗ה וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו כֹּֽה־אָמַ֤ר הַ⁠מֶּ֨לֶךְ֙ צֵ֔א וַ⁠יֹּ֥אמֶר ׀ לֹ֖א כִּ֣י פֹ֣ה אָמ֑וּת וַ⁠יָּ֨שֶׁב בְּנָיָ֤הוּ אֶת־הַ⁠מֶּ֨לֶךְ֙ דָּבָ֣ר לֵ⁠אמֹ֔ר כֹּֽה־דִבֶּ֥ר יוֹאָ֖ב וְ⁠כֹ֥ה עָנָֽ⁠נִי׃","wa⁠yá̇bò֨ʼ bĕnáyá֜hẇ ʼel-ʼò֣hel yĕhwá֗h wa⁠yò̇֨ʼmer ʼélá֜y⁠w kòֽ̇h-ʼáma֤r ha⁠mė֨lekĕ֙ ẕé֔ʼ wa⁠yò֥̇ʼmer ׀ lò֖ʼ ki֣̇y pò֣h ʼám֑ẇţ wa⁠yá̇֨şěb bĕ̇náyá֤hẇ ʼeţ-ha⁠mė֨lekĕ֙ dá̇bá֣r lé⁠ʼmò֔r kòֽ̇h-dibė֥r ywòʼá֖b wĕ⁠kò֥h ʻánáֽ⁠niy׃"],[2,31,"וַ⁠יֹּ֧אמֶר ל֣⁠וֹ הַ⁠מֶּ֗לֶךְ עֲשֵׂה֙ כַּ⁠אֲשֶׁ֣ר דִּבֶּ֔ר וּ⁠פְגַע־בּ֖⁠וֹ וּ⁠קְבַרְתּ֑⁠וֹ וַ⁠הֲסִירֹ֣תָ ׀ דְּמֵ֣י חִנָּ֗ם אֲשֶׁר֙ שָׁפַ֣ךְ יוֹאָ֔ב מֵ⁠עָלַ֕⁠י וּ⁠מֵ⁠עַ֖ל בֵּ֥ית אָבִֽ⁠י׃","wa⁠yò֧̇ʼmer l֣⁠wò ha⁠mė֗lekĕ ʻàşé̂h֙ kȧ⁠ʼàşě֣r di̇bė֔r ẇ⁠pĕgaʻ-ḃ֖⁠wò ẇ⁠qĕbarĕţ֑̇⁠wò wa⁠hàsiyrò֣ţá ׀ dĕ̇mé֣y ẖiná̇֗m ʼàşěr֙ şá̌pa֣kĕ ywòʼá֔b mé⁠ʻála֕⁠y ẇ⁠mé⁠ʻa֖l bé֥̇yţ ʼábiֽ⁠y׃"],[2,32,"וְ⁠הֵשִׁיב֩ יְהוָ֨ה אֶת־דָּמ֜⁠וֹ עַל־רֹאשׁ֗⁠וֹ אֲשֶׁ֣ר פָּגַ֣ע בִּ⁠שְׁנֵֽי־אֲ֠נָשִׁים צַדִּקִ֨ים וְ⁠טֹבִ֤ים מִמֶּ֨⁠נּוּ֙ וַ⁠יַּהַרְגֵ֣⁠ם בַּ⁠חֶ֔רֶב וְ⁠אָבִ֥⁠י דָוִ֖ד לֹ֣א יָדָ֑ע אֶת־אַבְנֵ֤ר בֶּן־נֵר֙ שַׂר־צְבָ֣א יִשְׂרָאֵ֔ל וְ⁠אֶת־עֲמָשָׂ֥א בֶן־יֶ֖תֶר שַׂר־צְבָ֥א יְהוּדָֽה׃","wĕ⁠héşǐyb֩ yĕhwá֨h ʼeţ-dá̇m֜⁠wò ʻal-ròʼş̌֗⁠wò ʼàşě֣r pá̇ga֣ʻ bi̇⁠şĕ̌néֽy-ʼà֠náşǐym ẕadi̇qi֨ym wĕ⁠tòbi֤ym mimė֨⁠ṅẇ֙ wa⁠yȧharĕgé֣⁠m bȧ⁠ẖe֔reb wĕ⁠ʼábi֥⁠y dáwi֖d lò֣ʼ yádá֑ʻ ʼeţ-ʼabĕné֤r bėn-nér֙ şâr-ẕĕbá֣ʼ yişĕ̂ráʼé֔l wĕ⁠ʼeţ-ʻàmáşá֥̂ʼ ben-ye֖ţer şâr-ẕĕbá֥ʼ yĕhẇdáֽh׃"],[2,33,"וְ⁠שָׁ֤בוּ דְמֵי⁠הֶם֙ בְּ⁠רֹ֣אשׁ יוֹאָ֔ב וּ⁠בְ⁠רֹ֥אשׁ זַרְע֖⁠וֹ לְ⁠עֹלָ֑ם וּ⁠לְ⁠דָוִ֡ד וּ֠⁠לְ⁠זַרְע⁠וֹ וּ⁠לְ⁠בֵית֨⁠וֹ וּ⁠לְ⁠כִסְא֜⁠וֹ יִהְיֶ֥ה שָׁל֛וֹם עַד־עוֹלָ֖ם מֵ⁠עִ֥ם יְהוָֽה׃","wĕ⁠şá֤̌bẇ dĕméy⁠hem֙ bĕ̇⁠rò֣ʼş̌ ywòʼá֔b ẇ⁠bĕ⁠rò֥ʼş̌ zarĕʻ֖⁠wò lĕ⁠ʻòlá֑m ẇ⁠lĕ⁠dáwi֡d ẇ֠⁠lĕ⁠zarĕʻ⁠wò ẇ⁠lĕ⁠béyţ֨⁠wò ẇ⁠lĕ⁠kisĕʼ֜⁠wò yihĕye֥h şá̌l֛wòm ʻad-ʻwòlá֖m mé⁠ʻi֥m yĕhwáֽh׃"],[2,34,"וַ⁠יַּ֗עַל בְּנָיָ֨הוּ֙ בֶּן־יְה֣וֹיָדָ֔ע וַ⁠יִּפְגַּע־בּ֖⁠וֹ וַ⁠יְמִתֵ֑⁠הוּ וַ⁠יִּקָּבֵ֥ר בְּ⁠בֵית֖⁠וֹ בַּ⁠מִּדְבָּֽר׃","wa⁠yȧ֗ʻal bĕ̇náyá֨hẇ֙ bėn-yĕh֣wòyádá֔ʻ wa⁠yi̇pĕgȧʻ-ḃ֖⁠wò wa⁠yĕmiţé֑⁠hẇ wa⁠yi̇qá̇bé֥r bĕ̇⁠béyţ֖⁠wò bȧ⁠mi̇dĕbáֽ̇r׃"],[2,35,"וַ⁠יִּתֵּ֨ן הַ⁠מֶּ֜לֶךְ אֶת־בְּנָיָ֧הוּ בֶן־יְהוֹיָדָ֛ע תַּחְתָּ֖י⁠ו עַל־הַ⁠צָּבָ֑א וְ⁠אֶת־צָד֤וֹק הַ⁠כֹּהֵן֙ נָתַ֣ן הַ⁠מֶּ֔לֶךְ תַּ֖חַת אֶבְיָתָֽר׃","wa⁠yi̇ţé̇֨n ha⁠mė֜lekĕ ʼeţ-bĕ̇náyá֧hẇ ben-yĕhwòyádá֛ʻ ţȧẖĕţá֖̇y⁠w ʻal-ha⁠ẕá̇bá֑ʼ wĕ⁠ʼeţ-ẕád֤wòq ha⁠kò̇hén֙ náţa֣n ha⁠mė֔lekĕ ţȧ֖ẖaţ ʼebĕyáţáֽr׃"],[2,36,"וַ⁠יִּשְׁלַ֤ח הַ⁠מֶּ֨לֶךְ֙ וַ⁠יִּקְרָ֣א לְ⁠שִׁמְעִ֔י וַ⁠יֹּ֣אמֶר ל֗⁠וֹ בְּֽנֵה־לְ⁠ךָ֥ בַ֨יִת֙ בִּ⁠יר֣וּשָׁלִַ֔ם וְ⁠יָשַׁבְתָּ֖ שָׁ֑ם וְ⁠לֹֽא־תֵצֵ֥א מִ⁠שָּׁ֖ם אָ֥נֶה וָ⁠אָֽנָה׃","wa⁠yi̇şĕ̌la֤ẖ ha⁠mė֨lekĕ֙ wa⁠yi̇qĕrá֣ʼ lĕ⁠şǐmĕʻi֔y wa⁠yò֣̇ʼmer l֗⁠wò bĕֽ̇néh-lĕ⁠ká֥ ba֨yiţ֙ bi̇⁠yr֣ẇşá̌lia֔m wĕ⁠yáşǎbĕţá֖̇ şá֑̌m wĕ⁠lòֽʼ-ţéẕé֥ʼ mi⁠şá֖̇̌m ʼá֥neh wá⁠ʼáֽnáh׃"],[2,37,"וְ⁠הָיָ֣ה ׀ בְּ⁠י֣וֹם צֵאתְ⁠ךָ֗ וְ⁠עָֽבַרְתָּ֙ אֶת־נַ֣חַל קִדְר֔וֹן יָדֹ֥עַ תֵּדַ֖ע כִּ֣י מ֣וֹת תָּמ֑וּת דָּמְ⁠ךָ֖ יִהְיֶ֥ה בְ⁠רֹאשֶֽׁ⁠ךָ׃","wĕ⁠háyá֣h ׀ bĕ̇⁠y֣wòm ẕéʼţĕ⁠ká֗ wĕ⁠ʻáֽbarĕţá̇֙ ʼeţ-na֣ẖal qidĕr֔wòn yádò֥ʻa ţé̇da֖ʻ ki֣̇y m֣wòţ ţá̇m֑ẇţ dá̇mĕ⁠ká֖ yihĕye֥h bĕ⁠ròʼşěֽ⁠ká׃"],[2,38,"וַ⁠יֹּ֨אמֶר שִׁמְעִ֤י לַ⁠מֶּ֨לֶךְ֙ ט֣וֹב הַ⁠דָּבָ֔ר כַּ⁠אֲשֶׁ֤ר דִּבֶּר֙ אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ כֵּ֖ן יַעֲשֶׂ֣ה עַבְדֶּ֑⁠ךָ וַ⁠יֵּ֧שֶׁב שִׁמְעִ֛י בִּ⁠ירוּשָׁלִַ֖ם יָמִ֥ים רַבִּֽים׃ס","wa⁠yò̇֨ʼmer şǐmĕʻi֤y la⁠mė֨lekĕ֙ t֣wòb ha⁠dá̇bá֔r kȧ⁠ʼàşě֤r di̇bėr֙ ʼàdòni֣⁠y ha⁠mė֔lekĕ ké֖̇n yaʻàşê֣h ʻabĕdė֑⁠ká wa⁠yé֧̇şěb şǐmĕʻi֛y bi̇⁠yrẇşá̌lia֖m yámi֥ym rabiֽ̇ym׃s"],[2,39,"וַ⁠יְהִ֗י מִ⁠קֵּץ֙ שָׁלֹ֣שׁ שָׁנִ֔ים וַ⁠יִּבְרְח֤וּ שְׁנֵֽי־עֲבָדִים֙ לְ⁠שִׁמְעִ֔י אֶל־אָכִ֥ישׁ בֶּֽן־מַעֲכָ֖ה מֶ֣לֶךְ גַּ֑ת וַ⁠יַּגִּ֤ידוּ לְ⁠שִׁמְעִי֙ לֵ⁠אמֹ֔ר הִנֵּ֥ה עֲבָדֶ֖י⁠ךָ בְּ⁠גַֽת׃","wa⁠yĕhi֗y mi⁠qé̇ẕ֙ şá̌lò֣ş̌ şá̌ni֔ym wa⁠yi̇bĕrĕẖ֤ẇ şĕ̌néֽy-ʻàbádiym֙ lĕ⁠şǐmĕʻi֔y ʼel-ʼáki֥yş̌ bėֽn-maʻàká֖h me֣lekĕ gȧ֑ţ wa⁠yȧgi֤̇ydẇ lĕ⁠şǐmĕʻiy֙ lé⁠ʼmò֔r hiné֥̇h ʻàbáde֖y⁠ká bĕ̇⁠gaֽţ׃"],[2,40,"וַ⁠יָּ֣קָם שִׁמְעִ֗י וַֽ⁠יַּחֲבֹשׁ֙ אֶת־חֲמֹר֔⁠וֹ וַ⁠יֵּ֤לֶךְ גַּ֨תָ⁠ה֙ אֶל־אָכִ֔ישׁ לְ⁠בַקֵּ֖שׁ אֶת־עֲבָדָ֑י⁠ו וַ⁠יֵּ֣לֶךְ שִׁמְעִ֔י וַ⁠יָּבֵ֥א אֶת־עֲבָדָ֖י⁠ו מִ⁠גַּֽת׃","wa⁠yá֣̇qám şǐmĕʻi֗y waֽ⁠yȧẖàbòş̌֙ ʼeţ-ẖàmòr֔⁠wò wa⁠yé֤̇lekĕ gȧ֨ţá⁠h֙ ʼel-ʼáki֔yş̌ lĕ⁠baqé֖̇ş̌ ʼeţ-ʻàbádá֑y⁠w wa⁠yé֣̇lekĕ şǐmĕʻi֔y wa⁠yá̇bé֥ʼ ʼeţ-ʻàbádá֖y⁠w mi⁠gȧֽţ׃"],[2,41,"וַ⁠יֻּגַּ֖ד לִ⁠שְׁלֹמֹ֑ה כִּי־הָלַ֨ךְ שִׁמְעִ֧י מִ⁠ירוּשָׁלִַ֛ם גַּ֖ת וַ⁠יָּשֹֽׁב׃","wa⁠yu̇gȧ֖d li⁠şĕ̌lòmò֑h ki̇y-hála֨kĕ şǐmĕʻi֧y mi⁠yrẇşá̌lia֛m gȧ֖ţ wa⁠yá̇şòֽ̌b׃"],[2,42,"וַ⁠יִּשְׁלַ֨ח הַ⁠מֶּ֜לֶךְ וַ⁠יִּקְרָ֣א לְ⁠שִׁמְעִ֗י וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו הֲ⁠ל֧וֹא הִשְׁבַּעְתִּ֣י⁠ךָ בַֽ⁠יהוָ֗ה וָ⁠אָעִ֤ד בְּ⁠ךָ֙ לֵ⁠אמֹ֔ר בְּ⁠י֣וֹם צֵאתְ⁠ךָ֗ וְ⁠הָֽלַכְתָּ֙ אָ֣נֶה וָ⁠אָ֔נָה יָדֹ֥עַ תֵּדַ֖ע כִּ֣י מ֣וֹת תָּמ֑וּת וַ⁠תֹּ֧אמֶר אֵלַ֛⁠י ט֥וֹב הַ⁠דָּבָ֖ר שָׁמָֽעְתִּי׃","wa⁠yi̇şĕ̌la֨ẖ ha⁠mė֜lekĕ wa⁠yi̇qĕrá֣ʼ lĕ⁠şǐmĕʻi֗y wa⁠yò̇֨ʼmer ʼélá֜y⁠w hà⁠l֧wòʼ hişĕ̌bȧʻĕţi֣̇y⁠ká baֽ⁠yhwá֗h wá⁠ʼáʻi֤d bĕ̇⁠ká֙ lé⁠ʼmò֔r bĕ̇⁠y֣wòm ẕéʼţĕ⁠ká֗ wĕ⁠háֽlakĕţá̇֙ ʼá֣neh wá⁠ʼá֔náh yádò֥ʻa ţé̇da֖ʻ ki֣̇y m֣wòţ ţá̇m֑ẇţ wa⁠ţò֧̇ʼmer ʼéla֛⁠y t֥wòb ha⁠dá̇bá֖r şá̌máֽʻĕţi̇y׃"],[2,43,"וּ⁠מַדּ֕וּעַ לֹ֣א שָׁמַ֔רְתָּ אֵ֖ת שְׁבֻעַ֣ת יְהוָ֑ה וְ⁠אֶת־הַ⁠מִּצְוָ֖ה אֲשֶׁר־צִוִּ֥יתִי עָלֶֽי⁠ךָ׃","ẇ⁠maḋ֕ẇʻa lò֣ʼ şá̌ma֔rĕţá̇ ʼé֖ţ şĕ̌buʻa֣ţ yĕhwá֑h wĕ⁠ʼeţ-ha⁠mi̇ẕĕwá֖h ʼàşěr-ẕiwi֥̇yţiy ʻáleֽy⁠ká׃"],[2,44,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ אֶל־שִׁמְעִ֗י אַתָּ֤ה יָדַ֨עְתָּ֙ אֵ֣ת כָּל־הָ⁠רָעָ֗ה אֲשֶׁ֤ר יָדַע֙ לְבָ֣בְ⁠ךָ֔ אֲשֶׁ֥ר עָשִׂ֖יתָ לְ⁠דָוִ֣ד אָבִ֑⁠י וְ⁠הֵשִׁ֧יב יְהוָ֛ה אֶת־רָעָתְ⁠ךָ֖ בְּ⁠רֹאשֶֽׁ⁠ךָ׃","wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ ʼel-şǐmĕʻi֗y ʼaţá֤̇h yáda֨ʻĕţá̇֙ ʼé֣ţ ká̇l-há⁠ráʻá֗h ʼàşě֤r yádaʻ֙ lĕbá֣bĕ⁠ká֔ ʼàşě֥r ʻáşî֖yţá lĕ⁠dáwi֣d ʼábi֑⁠y wĕ⁠héşǐ֧yb yĕhwá֛h ʼeţ-ráʻáţĕ⁠ká֖ bĕ̇⁠ròʼşěֽ⁠ká׃"],[2,45,"וְ⁠הַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה בָּר֑וּךְ וְ⁠כִסֵּ֣א דָוִ֗ד יִהְיֶ֥ה נָכ֛וֹן לִ⁠פְנֵ֥י יְהוָ֖ה עַד־עוֹלָֽם׃","wĕ⁠ha⁠mė֥lekĕ şĕ̌lòmò֖h bá̇r֑ẇkĕ wĕ⁠kisé֣̇ʼ dáwi֗d yihĕye֥h nák֛wòn li⁠pĕné֥y yĕhwá֖h ʻad-ʻwòláֽm׃"],[2,46,"וַ⁠יְצַ֣ו הַ⁠מֶּ֗לֶךְ אֶת־בְּנָיָ֨הוּ֙ בֶּן־יְה֣וֹיָדָ֔ע וַ⁠יֵּצֵ֕א וַ⁠יִּפְגַּע־בּ֖⁠וֹ וַ⁠יָּמֹ֑ת וְ⁠הַ⁠מַּמְלָכָ֥ה נָכ֖וֹנָה בְּ⁠יַד־שְׁלֹמֹֽה׃","wa⁠yĕẕa֣w ha⁠mė֗lekĕ ʼeţ-bĕ̇náyá֨hẇ֙ bėn-yĕh֣wòyádá֔ʻ wa⁠yé̇ẕé֕ʼ wa⁠yi̇pĕgȧʻ-ḃ֖⁠wò wa⁠yá̇mò֑ţ wĕ⁠ha⁠mȧmĕláká֥h nák֖wònáh bĕ̇⁠yad-şĕ̌lòmòֽh׃"],[3,1,"וַ⁠יִּתְחַתֵּ֣ן שְׁלֹמֹ֔ה אֶת־פַּרְעֹ֖ה מֶ֣לֶךְ מִצְרָ֑יִם וַ⁠יִּקַּ֣ח אֶת־בַּת־פַּרְעֹ֗ה וַ⁠יְבִיאֶ֨⁠הָ֙ אֶל־עִ֣יר דָּוִ֔ד עַ֣ד כַּלֹּת֗⁠וֹ לִ⁠בְנ֤וֹת אֶת־בֵּית⁠וֹ֙ וְ⁠אֶת־בֵּ֣ית יְהוָ֔ה וְ⁠אֶת־חוֹמַ֥ת יְרוּשָׁלִַ֖ם סָבִֽיב׃","wa⁠yi̇ţĕẖaţé֣̇n şĕ̌lòmò֔h ʼeţ-pȧrĕʻò֖h me֣lekĕ miẕĕrá֑yim wa⁠yi̇qȧ֣ẖ ʼeţ-bȧţ-pȧrĕʻò֗h wa⁠yĕbiyʼe֨⁠há֙ ʼel-ʻi֣yr dá̇wi֔d ʻa֣d kȧlò̇ţ֗⁠wò li⁠bĕn֤wòţ ʼeţ-bé̇yţ⁠wò֙ wĕ⁠ʼeţ-bé֣̇yţ yĕhwá֔h wĕ⁠ʼeţ-ẖwòma֥ţ yĕrẇşá̌lia֖m sábiֽyb׃"],[3,2,"רַ֣ק הָ⁠עָ֔ם מְזַבְּחִ֖ים בַּ⁠בָּמ֑וֹת כִּ֠י לֹא־נִבְנָ֥ה בַ֨יִת֙ לְ⁠שֵׁ֣ם יְהוָ֔ה עַ֖ד הַ⁠יָּמִ֥ים הָ⁠הֵֽם׃פ","ra֣q há⁠ʻá֔m mĕzabĕ̇ẖi֖ym bȧ⁠bá̇m֑wòţ ki̇֠y lòʼ-nibĕná֥h ba֨yiţ֙ lĕ⁠şé֣̌m yĕhwá֔h ʻa֖d ha⁠yá̇mi֥ym há⁠héֽm׃p"],[3,3,"וַ⁠יֶּאֱהַ֤ב שְׁלֹמֹה֙ אֶת־יְהוָ֔ה לָ⁠לֶ֕כֶת בְּ⁠חֻקּ֖וֹת דָּוִ֣ד אָבִ֑י⁠ו רַ֚ק בַּ⁠בָּמ֔וֹת ה֥וּא מְזַבֵּ֖חַ וּ⁠מַקְטִֽיר׃","wa⁠yėʼèha֤b şĕ̌lòmòh֙ ʼeţ-yĕhwá֔h lá⁠le֕keţ bĕ̇⁠ẖuq֖̇wòţ dá̇wi֣d ʼábi֑y⁠w ra֚q bȧ⁠bá̇m֔wòţ h֥ẇʼ mĕzabé֖̇ẖa ẇ⁠maqĕtiֽyr׃"],[3,4,"וַ⁠יֵּ֨לֶךְ הַ⁠מֶּ֤לֶךְ גִּבְעֹ֨נָ⁠ה֙ לִ⁠זְבֹּ֣חַ שָׁ֔ם כִּ֥י הִ֖יא הַ⁠בָּמָ֣ה הַ⁠גְּדוֹלָ֑ה אֶ֤לֶף עֹלוֹת֙ יַעֲלֶ֣ה שְׁלֹמֹ֔ה עַ֖ל הַ⁠מִּזְבֵּ֥חַ הַ⁠הֽוּא׃","wa⁠yé̇֨lekĕ ha⁠mė֤lekĕ gi̇bĕʻò֨ná⁠h֙ li⁠zĕbò֣̇ẖa şá̌֔m ki֥̇y hi֖yʼ ha⁠bá̇má֣h ha⁠gĕ̇dwòlá֑h ʼe֤lep ʻòlwòţ֙ yaʻàle֣h şĕ̌lòmò֔h ʻa֖l ha⁠mi̇zĕbé֥̇ẖa ha⁠hֽẇʼ׃"],[3,5,"בְּ⁠גִבְע֗וֹן נִרְאָ֧ה יְהֹוָ֛ה אֶל־שְׁלֹמֹ֖ה בַּ⁠חֲל֣וֹם הַ⁠לָּ֑יְלָה וַ⁠יֹּ֣אמֶר אֱלֹהִ֔ים שְׁאַ֖ל מָ֥ה אֶתֶּן־לָֽ⁠ךְ׃","bĕ̇⁠gibĕʻ֗wòn nirĕʼá֧h yĕhòwá֛h ʼel-şĕ̌lòmò֖h bȧ⁠ẖàl֣wòm ha⁠lá֑̇yĕláh wa⁠yò֣̇ʼmer ʼèlòhi֔ym şĕ̌ʼa֖l má֥h ʼeţėn-láֽ⁠kĕ׃"],[3,6,"וַ⁠יֹּ֣אמֶר שְׁלֹמֹ֗ה אַתָּ֨ה עָשִׂ֜יתָ עִם־עַבְדְּ⁠ךָ֙ דָוִ֣ד אָבִ⁠י֮ חֶ֣סֶד גָּדוֹל֒ כַּ⁠אֲשֶׁר֩ הָלַ֨ךְ לְ⁠פָנֶ֜י⁠ךָ בֶּ⁠אֱמֶ֧ת וּ⁠בִ⁠צְדָקָ֛ה וּ⁠בְ⁠יִשְׁרַ֥ת לֵבָ֖ב עִמָּ֑⁠ךְ וַ⁠תִּשְׁמָר־ל֗⁠וֹ אֶת־הַ⁠חֶ֤סֶד הַ⁠גָּדוֹל֙ הַ⁠זֶּ֔ה וַ⁠תִּתֶּן־ל֥⁠וֹ בֵ֛ן יֹשֵׁ֥ב עַל־כִּסְא֖⁠וֹ כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yò֣̇ʼmer şĕ̌lòmò֗h ʼaţá̇֨h ʻáşî֜yţá ʻim-ʻabĕdĕ̇⁠ká֙ dáwi֣d ʼábi⁠y֮ ẖe֣sed gá̇dwòl֒ kȧ⁠ʼàşěr֩ hála֨kĕ lĕ⁠páne֜y⁠ká bė⁠ʼème֧ţ ẇ⁠bi⁠ẕĕdáqá֛h ẇ⁠bĕ⁠yişĕ̌ra֥ţ lébá֖b ʻimá֑̇⁠kĕ wa⁠ţi̇şĕ̌már-l֗⁠wò ʼeţ-ha⁠ẖe֤sed ha⁠gá̇dwòl֙ ha⁠zė֔h wa⁠ţi̇ţėn-l֥⁠wò bé֛n yòşé֥̌b ʻal-ki̇sĕʼ֖⁠wò kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[3,7,"וְ⁠עַתָּה֙ יְהוָ֣ה אֱלֹהָ֔⁠י אַתָּה֙ הִמְלַ֣כְתָּ אֶֽת־עַבְדְּ⁠ךָ֔ תַּ֖חַת דָּוִ֣ד אָבִ֑⁠י וְ⁠אָֽנֹכִי֙ נַ֣עַר קָטֹ֔ן לֹ֥א אֵדַ֖ע צֵ֥את וָ⁠בֹֽא׃","wĕ⁠ʻaţá̇h֙ yĕhwá֣h ʼèlòhá֔⁠y ʼaţá̇h֙ himĕla֣kĕţá̇ ʼeֽţ-ʻabĕdĕ̇⁠ká֔ ţȧ֖ẖaţ dá̇wi֣d ʼábi֑⁠y wĕ⁠ʼáֽnòkiy֙ na֣ʻar qátò֔n lò֥ʼ ʼéda֖ʻ ẕé֥ʼţ wá⁠bòֽʼ׃"],[3,8,"וְ⁠עַ֨בְדְּ⁠ךָ֔ בְּ⁠ת֥וֹךְ עַמְּ⁠ךָ֖ אֲשֶׁ֣ר בָּחָ֑רְתָּ עַם־רָ֕ב אֲשֶׁ֧ר לֹֽא־יִמָּנֶ֛ה וְ⁠לֹ֥א יִסָּפֵ֖ר מֵ⁠רֹֽב׃","wĕ⁠ʻa֨bĕdĕ̇⁠ká֔ bĕ̇⁠ţ֥wòkĕ ʻamĕ̇⁠ká֖ ʼàşě֣r bá̇ẖá֑rĕţá̇ ʻam-rá֕b ʼàşě֧r lòֽʼ-yimá̇ne֛h wĕ⁠lò֥ʼ yisá̇pé֖r mé⁠ròֽb׃"],[3,9,"וְ⁠נָתַתָּ֨ לְ⁠עַבְדְּ⁠ךָ֜ לֵ֤ב שֹׁמֵ֨עַ֙ לִ⁠שְׁפֹּ֣ט אֶֽת־עַמְּ⁠ךָ֔ לְ⁠הָבִ֖ין בֵּֽין־ט֣וֹב לְ⁠רָ֑ע כִּ֣י מִ֤י יוּכַל֙ לִ⁠שְׁפֹּ֔ט אֶת־עַמְּ⁠ךָ֥ הַ⁠כָּבֵ֖ד הַ⁠זֶּֽה׃","wĕ⁠náţaţá̇֨ lĕ⁠ʻabĕdĕ̇⁠ká֜ lé֤b şò̌mé֨ʻa֙ li⁠şĕ̌pò֣̇t ʼeֽţ-ʻamĕ̇⁠ká֔ lĕ⁠hábi֖yn béֽ̇yn-t֣wòb lĕ⁠rá֑ʻ ki֣̇y mi֤y yẇkal֙ li⁠şĕ̌pò̇֔t ʼeţ-ʻamĕ̇⁠ká֥ ha⁠ká̇bé֖d ha⁠zėֽh׃"],[3,10,"וַ⁠יִּיטַ֥ב הַ⁠דָּבָ֖ר בְּ⁠עֵינֵ֣י אֲדֹנָ֑⁠י כִּ֚י שָׁאַ֣ל שְׁלֹמֹ֔ה אֶת־הַ⁠דָּבָ֖ר הַ⁠זֶּֽה׃","wa⁠yi̇yta֥b ha⁠dá̇bá֖r bĕ̇⁠ʻéyné֣y ʼàdòná֑⁠y ki֚̇y şá̌ʼa֣l şĕ̌lòmò֔h ʼeţ-ha⁠dá̇bá֖r ha⁠zėֽh׃"],[3,11,"וַ⁠יֹּ֨אמֶר אֱלֹהִ֜ים אֵלָ֗י⁠ו יַעַן֩ אֲשֶׁ֨ר שָׁאַ֜לְתָּ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה וְ⁠לֹֽא־שָׁאַ֨לְתָּ לְּ⁠ךָ֜ יָמִ֣ים רַבִּ֗ים וְ⁠לֹֽא־שָׁאַ֤לְתָּ לְּ⁠ךָ֙ עֹ֔שֶׁר וְ⁠לֹ֥א שָׁאַ֖לְתָּ נֶ֣פֶשׁ אֹיְבֶ֑י⁠ךָ וְ⁠שָׁאַ֧לְתָּ לְּ⁠ךָ֛ הָבִ֖ין לִ⁠שְׁמֹ֥עַ מִשְׁפָּֽט׃","wa⁠yò̇֨ʼmer ʼèlòhi֜ym ʼélá֗y⁠w yaʻan֩ ʼàşě֨r şá̌ʼa֜lĕţá̇ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֗h wĕ⁠lòֽʼ-şá̌ʼa֨lĕţá̇ lĕ̇⁠ká֜ yámi֣ym rabi̇֗ym wĕ⁠lòֽʼ-şá̌ʼa֤lĕţá̇ lĕ̇⁠ká֙ ʻò֔şěr wĕ⁠lò֥ʼ şá̌ʼa֖lĕţá̇ ne֣peş̌ ʼòyĕbe֑y⁠ká wĕ⁠şá̌ʼa֧lĕţá̇ lĕ̇⁠ká֛ hábi֖yn li⁠şĕ̌mò֥ʻa mişĕ̌páֽ̇t׃"],[3,12,"הִנֵּ֥ה עָשִׂ֖יתִי כִּ⁠דְבָרֶ֑י⁠ךָ הִנֵּ֣ה ׀ נָתַ֣תִּי לְ⁠ךָ֗ לֵ֚ב חָכָ֣ם וְ⁠נָב֔וֹן אֲשֶׁ֤ר כָּמ֨וֹ⁠ךָ֙ לֹא־הָיָ֣ה לְ⁠פָנֶ֔י⁠ךָ וְ⁠אַחֲרֶ֖י⁠ךָ לֹא־יָק֥וּם כָּמֽוֹ⁠ךָ׃","hiné֥̇h ʻáşî֖yţiy ki̇⁠dĕbáre֑y⁠ká hiné֣̇h ׀ náţa֣ţi̇y lĕ⁠ká֗ lé֚b ẖáká֣m wĕ⁠náb֔wòn ʼàşě֤r ká̇m֨wò⁠ká֙ lòʼ-háyá֣h lĕ⁠páne֔y⁠ká wĕ⁠ʼaẖàre֖y⁠ká lòʼ-yáq֥ẇm ká̇mֽwò⁠ká׃"],[3,13,"וְ⁠גַ֨ם אֲשֶׁ֤ר לֹֽא־שָׁאַ֨לְתָּ֙ נָתַ֣תִּי לָ֔⁠ךְ גַּם־עֹ֖שֶׁר גַּם־כָּב֑וֹד אֲ֠שֶׁר לֹא־הָיָ֨ה כָמ֥וֹ⁠ךָ אִ֛ישׁ בַּ⁠מְּלָכִ֖ים כָּל־יָמֶֽי⁠ךָ׃","wĕ⁠ga֨m ʼàşě֤r lòֽʼ-şá̌ʼa֨lĕţá̇֙ náţa֣ţi̇y lá֔⁠kĕ gȧm-ʻò֖şěr gȧm-ká̇b֑wòd ʼà֠şěr lòʼ-háyá֨h kám֥wò⁠ká ʼi֛yş̌ bȧ⁠mĕ̇láki֖ym ká̇l-yámeֽy⁠ká׃"],[3,14,"וְ⁠אִ֣ם ׀ תֵּלֵ֣ךְ בִּ⁠דְרָכַ֗⁠י לִ⁠שְׁמֹ֤ר חֻקַּ⁠י֙ וּ⁠מִצְוֺתַ֔⁠י כַּ⁠אֲשֶׁ֥ר הָלַ֖ךְ דָּוִ֣יד אָבִ֑י⁠ךָ וְ⁠הַאַרַכְתִּ֖י אֶת־יָמֶֽי⁠ךָ׃ס","wĕ⁠ʼi֣m ׀ ţé̇lé֣kĕ bi̇⁠dĕráka֗⁠y li⁠şĕ̌mò֤r ẖuqȧ⁠y֙ ẇ⁠miẕĕwֺţa֔⁠y kȧ⁠ʼàşě֥r hála֖kĕ dá̇wi֣yd ʼábi֑y⁠ká wĕ⁠haʼarakĕţi֖̇y ʼeţ-yámeֽy⁠ká׃s"],[3,15,"וַ⁠יִּקַ֥ץ שְׁלֹמֹ֖ה וְ⁠הִנֵּ֣ה חֲל֑וֹם וַ⁠יָּב֨וֹא יְרוּשָׁלִַ֜ם וַֽ⁠יַּעֲמֹ֣ד ׀ לִ⁠פְנֵ֣י ׀ אֲר֣וֹן בְּרִית־אֲדֹנָ֗⁠י וַ⁠יַּ֤עַל עֹלוֹת֙ וַ⁠יַּ֣עַשׂ שְׁלָמִ֔ים וַ⁠יַּ֥עַשׂ מִשְׁתֶּ֖ה לְ⁠כָל־עֲבָדָֽי⁠ו׃פ","wa⁠yi̇qa֥ẕ şĕ̌lòmò֖h wĕ⁠hiné֣̇h ẖàl֑wòm wa⁠yá̇b֨wòʼ yĕrẇşá̌lia֜m wֽa⁠yȧʻàmò֣d ׀ li⁠pĕné֣y ׀ ʼàr֣wòn bĕ̇riyţ-ʼàdòná֗⁠y wa⁠yȧ֤ʻal ʻòlwòţ֙ wa⁠yȧ֣ʻaş̂ şĕ̌lámi֔ym wa⁠yȧ֥ʻaş̂ mişĕ̌ţė֖h lĕ⁠kál-ʻàbádáֽy⁠w׃p"],[3,16,"אָ֣ז תָּבֹ֗אנָה שְׁתַּ֛יִם נָשִׁ֥ים זֹנ֖וֹת אֶל־הַ⁠מֶּ֑לֶךְ וַֽ⁠תַּעֲמֹ֖דְנָה לְ⁠פָנָֽי⁠ו׃","ʼá֣z ţá̇bò֗ʼnáh şĕ̌ţȧ֛yim náşǐ֥ym zòn֖wòţ ʼel-ha⁠mė֑lekĕ wֽa⁠ţȧʻàmò֖dĕnáh lĕ⁠pánáֽy⁠w׃"],[3,17,"וַ⁠תֹּ֜אמֶר הָ⁠אִשָּׁ֤ה הָֽ⁠אַחַת֙ בִּ֣י אֲדֹנִ֔⁠י אֲנִי֙ וְ⁠הָ⁠אִשָּׁ֣ה הַ⁠זֹּ֔את יֹשְׁבֹ֖ת בְּ⁠בַ֣יִת אֶחָ֑ד וָ⁠אֵלֵ֥ד עִמָּ֖⁠הּ בַּ⁠בָּֽיִת׃","wa⁠ţò̇֜ʼmer há⁠ʼişá֤̇̌h háֽ⁠ʼaẖaţ֙ bi֣̇y ʼàdòni֔⁠y ʼàniy֙ wĕ⁠há⁠ʼişá֣̇̌h ha⁠zò̇֔ʼţ yòşĕ̌bò֖ţ bĕ̇⁠ba֣yiţ ʼeẖá֑d wá⁠ʼélé֥d ʻimá֖̇⁠ḣ bȧ⁠báֽ̇yiţ׃"],[3,18,"וַ⁠יְהִ֞י בַּ⁠יּ֤וֹם הַ⁠שְּׁלִישִׁי֙ לְ⁠לִדְתִּ֔⁠י וַ⁠תֵּ֖לֶד גַּם־הָ⁠אִשָּׁ֣ה הַ⁠זֹּ֑את וַ⁠אֲנַ֣חְנוּ יַחְדָּ֗ו אֵֽין־זָ֤ר אִתָּ֨⁠נוּ֙ בַּ⁠בַּ֔יִת זוּלָתִ֥י שְׁתַּֽיִם־אֲנַ֖חְנוּ בַּ⁠בָּֽיִת׃","wa⁠yĕhi֞y bȧ⁠ẏ֤wòm ha⁠şĕ̇̌liyşǐy֙ lĕ⁠lidĕţi̇֔⁠y wa⁠ţé֖̇led gȧm-há⁠ʼişá֣̇̌h ha⁠zò֑̇ʼţ wa⁠ʼàna֣ẖĕnẇ yaẖĕdá̇֗w ʼéֽyn-zá֤r ʼiţá̇֨⁠nẇ֙ bȧ⁠bȧ֔yiţ zẇláţi֥y şĕ̌ţȧֽyim-ʼàna֖ẖĕnẇ bȧ⁠báֽ̇yiţ׃"],[3,19,"וַ⁠יָּ֛מָת בֶּן־הָ⁠אִשָּׁ֥ה הַ⁠זֹּ֖את לָ֑יְלָה אֲשֶׁ֥ר שָׁכְבָ֖ה עָלָֽי⁠ו׃","wa⁠yá֛̇máţ bėn-há⁠ʼişá֥̇̌h ha⁠zò֖̇ʼţ lá֑yĕláh ʼàşě֥r şá̌kĕbá֖h ʻáláֽy⁠w׃"],[3,20,"וַ⁠תָּקָם֩ בְּ⁠ת֨וֹךְ הַ⁠לַּ֜יְלָה וַ⁠תִּקַּ֧ח אֶת־בְּנִ֣⁠י מֵֽ⁠אֶצְלִ֗⁠י וַ⁠אֲמָֽתְ⁠ךָ֙ יְשֵׁנָ֔ה וַ⁠תַּשְׁכִּיבֵ֖⁠הוּ בְּ⁠חֵיקָ֑⁠הּ וְ⁠אֶת־בְּנָ֥⁠הּ הַ⁠מֵּ֖ת הִשְׁכִּ֥יבָה בְ⁠חֵיקִֽ⁠י׃","wa⁠ţá̇qám֩ bĕ̇⁠ţ֨wòkĕ ha⁠lȧ֜yĕláh wa⁠ţi̇qȧ֧ẖ ʼeţ-bĕ̇ni֣⁠y méֽ⁠ʼeẕĕli֗⁠y wa⁠ʼàmáֽţĕ⁠ká֙ yĕşé̌ná֔h wa⁠ţȧşĕ̌ki̇ybé֖⁠hẇ bĕ̇⁠ẖéyqá֑⁠ḣ wĕ⁠ʼeţ-bĕ̇ná֥⁠ḣ ha⁠mé֖̇ţ hişĕ̌ki֥̇ybáh bĕ⁠ẖéyqiֽ⁠y׃"],[3,21,"וָ⁠אָקֻ֥ם בַּ⁠בֹּ֛קֶר לְ⁠הֵינִ֥יק אֶת־בְּנִ֖⁠י וְ⁠הִנֵּה־מֵ֑ת וָ⁠אֶתְבּוֹנֵ֤ן אֵלָי⁠ו֙ בַּ⁠בֹּ֔קֶר וְ⁠הִנֵּ֛ה לֹֽא־הָיָ֥ה בְנִ֖⁠י אֲשֶׁ֥ר יָלָֽדְתִּי׃","wá⁠ʼáqu֥m bȧ⁠bò֛̇qer lĕ⁠héyni֥yq ʼeţ-bĕ̇ni֖⁠y wĕ⁠hiné̇h-mé֑ţ wá⁠ʼeţĕḃwòné֤n ʼéláy⁠w֙ bȧ⁠bò̇֔qer wĕ⁠hiné֛̇h lòֽʼ-háyá֥h bĕni֖⁠y ʼàşě֥r yáláֽdĕţi̇y׃"],[3,22,"וַ⁠תֹּאמֶר֩ הָ⁠אִשָּׁ֨ה הָ⁠אַחֶ֜רֶת לֹ֣א כִ֗י בְּנִ֤⁠י הַ⁠חַי֙ וּ⁠בְנֵ֣⁠ךְ הַ⁠מֵּ֔ת וְ⁠זֹ֤את אֹמֶ֨רֶת֙ לֹ֣א כִ֔י בְּנֵ֥⁠ךְ הַ⁠מֵּ֖ת וּ⁠בְנִ֣⁠י הֶ⁠חָ֑י וַ⁠תְּדַבֵּ֖רְנָה לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠ţò̇ʼmer֩ há⁠ʼişá̇̌֨h há⁠ʼaẖe֜reţ lò֣ʼ ki֗y bĕ̇ni֤⁠y ha⁠ẖay֙ ẇ⁠bĕné֣⁠kĕ ha⁠mé̇֔ţ wĕ⁠zò֤ʼţ ʼòme֨reţ֙ lò֣ʼ ki֔y bĕ̇né֥⁠kĕ ha⁠mé֖̇ţ ẇ⁠bĕni֣⁠y he⁠ẖá֑y wa⁠ţĕ̇dabé֖̇rĕnáh li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[3,23,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ זֹ֣את אֹמֶ֔רֶת זֶה־בְּנִ֥⁠י הַ⁠חַ֖י וּ⁠בְנֵ֣⁠ךְ הַ⁠מֵּ֑ת וְ⁠זֹ֤את אֹמֶ֨רֶת֙ לֹ֣א כִ֔י בְּנֵ֥⁠ךְ הַ⁠מֵּ֖ת וּ⁠בְנִ֥⁠י הֶ⁠חָֽי׃פ","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ zò֣ʼţ ʼòme֔reţ zeh-bĕ̇ni֥⁠y ha⁠ẖa֖y ẇ⁠bĕné֣⁠kĕ ha⁠mé֑̇ţ wĕ⁠zò֤ʼţ ʼòme֨reţ֙ lò֣ʼ ki֔y bĕ̇né֥⁠kĕ ha⁠mé֖̇ţ ẇ⁠bĕni֥⁠y he⁠ẖáֽy׃p"],[3,24,"וַ⁠יֹּ֥אמֶר הַ⁠מֶּ֖לֶךְ קְח֣וּ לִ⁠י־חָ֑רֶב וַ⁠יָּבִ֥אוּ הַ⁠חֶ֖רֶב לִ⁠פְנֵ֥י הַ⁠מֶּֽלֶךְ׃","wa⁠yò֥̇ʼmer ha⁠mė֖lekĕ qĕẖ֣ẇ li⁠y-ẖá֑reb wa⁠yá̇bi֥ʼẇ ha⁠ẖe֖reb li⁠pĕné֥y ha⁠mėֽlekĕ׃"],[3,25,"וַ⁠יֹּ֣אמֶר הַ⁠מֶּ֔לֶךְ גִּזְר֛וּ אֶת־הַ⁠יֶּ֥לֶד הַ⁠חַ֖י לִ⁠שְׁנָ֑יִם וּ⁠תְנ֤וּ אֶֽת־הַ⁠חֲצִי֙ לְ⁠אַחַ֔ת וְ⁠אֶֽת־הַ⁠חֲצִ֖י לְ⁠אֶחָֽת׃","wa⁠yò֣̇ʼmer ha⁠mė֔lekĕ gi̇zĕr֛ẇ ʼeţ-ha⁠yė֥led ha⁠ẖa֖y li⁠şĕ̌ná֑yim ẇ⁠ţĕn֤ẇ ʼeֽţ-ha⁠ẖàẕiy֙ lĕ⁠ʼaẖa֔ţ wĕ⁠ʼeֽţ-ha⁠ẖàẕi֖y lĕ⁠ʼeẖáֽţ׃"],[3,26,"וַ⁠תֹּ֣אמֶר הָ⁠אִשָּׁה֩ אֲשֶׁר־בְּנָ֨⁠הּ הַ⁠חַ֜י אֶל־הַ⁠מֶּ֗לֶךְ כִּֽי־נִכְמְר֣וּ רַחֲמֶי⁠הָ֮ עַל־בְּנָ⁠הּ֒ וַ⁠תֹּ֣אמֶר ׀ בִּ֣י אֲדֹנִ֗⁠י תְּנוּ־לָ⁠הּ֙ אֶת־הַ⁠יָּל֣וּד הַ⁠חַ֔י וְ⁠הָמֵ֖ת אַל־תְּמִיתֻ֑⁠הוּ וְ⁠זֹ֣את אֹמֶ֗רֶת גַּם־לִ֥⁠י גַם־לָ֛⁠ךְ לֹ֥א יִהְיֶ֖ה גְּזֹֽרוּ׃","wa⁠ţò֣̇ʼmer há⁠ʼişá̇̌h֩ ʼàşěr-bĕ̇ná֨⁠ḣ ha⁠ẖa֜y ʼel-ha⁠mė֗lekĕ kiֽ̇y-nikĕmĕr֣ẇ raẖàmey⁠há֮ ʻal-bĕ̇ná⁠ḣ֒ wa⁠ţò֣̇ʼmer ׀ bi֣̇y ʼàdòni֗⁠y ţĕ̇nẇ-lá⁠ḣ֙ ʼeţ-ha⁠yá̇l֣ẇd ha⁠ẖa֔y wĕ⁠hámé֖ţ ʼal-ţĕ̇miyţu֑⁠hẇ wĕ⁠zò֣ʼţ ʼòme֗reţ gȧm-li֥⁠y gam-lá֛⁠kĕ lò֥ʼ yihĕye֖h gĕ̇zòֽrẇ׃"],[3,27,"וַ⁠יַּ֨עַן הַ⁠מֶּ֜לֶךְ וַ⁠יֹּ֗אמֶר תְּנוּ־לָ⁠הּ֙ אֶת־הַ⁠יָּל֣וּד הַ⁠חַ֔י וְ⁠הָמֵ֖ת לֹ֣א תְמִיתֻ֑⁠הוּ הִ֖יא אִמּֽ⁠וֹ׃","wa⁠yȧ֨ʻan ha⁠mė֜lekĕ wa⁠yò̇֗ʼmer ţĕ̇nẇ-lá⁠ḣ֙ ʼeţ-ha⁠yá̇l֣ẇd ha⁠ẖa֔y wĕ⁠hámé֖ţ lò֣ʼ ţĕmiyţu֑⁠hẇ hi֖yʼ ʼiṁֽ⁠wò׃"],[3,28,"וַ⁠יִּשְׁמְע֣וּ כָל־יִשְׂרָאֵ֗ל אֶת־הַ⁠מִּשְׁפָּט֙ אֲשֶׁ֣ר שָׁפַ֣ט הַ⁠מֶּ֔לֶךְ וַ⁠יִּֽרְא֖וּ מִ⁠פְּנֵ֣י הַ⁠מֶּ֑לֶךְ כִּ֣י רָא֔וּ כִּֽי־חָכְמַ֧ת אֱלֹהִ֛ים בְּ⁠קִרְבּ֖⁠וֹ לַ⁠עֲשׂ֥וֹת מִשְׁפָּֽט׃ס","wa⁠yi̇şĕ̌mĕʻ֣ẇ kál-yişĕ̂ráʼé֗l ʼeţ-ha⁠mi̇şĕ̌pá̇t֙ ʼàşě֣r şá̌pa֣t ha⁠mė֔lekĕ wa⁠yiֽ̇rĕʼ֖ẇ mi⁠pĕ̇né֣y ha⁠mė֑lekĕ ki֣̇y ráʼ֔ẇ kiֽ̇y-ẖákĕma֧ţ ʼèlòhi֛ym bĕ̇⁠qirĕḃ֖⁠wò la⁠ʻàş֥̂wòţ mişĕ̌páֽ̇t׃s"],[4,1,"וַֽ⁠יְהִי֙ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה מֶ֖לֶךְ עַל־כָּל־יִשְׂרָאֵֽל׃ס","waֽ⁠yĕhiy֙ ha⁠mė֣lekĕ şĕ̌lòmò֔h me֖lekĕ ʻal-ká̇l-yişĕ̂ráʼéֽl׃s"],[4,2,"וְ⁠אֵ֥לֶּה הַ⁠שָּׂרִ֖ים אֲשֶׁר־ל֑⁠וֹ עֲזַרְיָ֥הוּ בֶן־צָד֖וֹק הַ⁠כֹּהֵֽן׃ס","wĕ⁠ʼé֥lėh ha⁠şá̇̂ri֖ym ʼàşěr-l֑⁠wò ʻàzarĕyá֥hẇ ben-ẕád֖wòq ha⁠kò̇héֽn׃s"],[4,3,"אֱלִיחֹ֧רֶף וַ⁠אֲחִיָּ֛ה בְּנֵ֥י שִׁישָׁ֖א סֹפְרִ֑ים יְהוֹשָׁפָ֥ט בֶּן־אֲחִיל֖וּד הַ⁠מַּזְכִּֽיר׃","ʼèliyẖò֧rep wa⁠ʼàẖiyá֛̇h bĕ̇né֥y şǐyşá֖̌ʼ sòpĕri֑ym yĕhwòşá̌pá֥t bėn-ʼàẖiyl֖ẇd ha⁠mȧzĕkiֽ̇yr׃"],[4,4,"וּ⁠בְנָיָ֥הוּ בֶן־יְהוֹיָדָ֖ע עַל־הַ⁠צָּבָ֑א וְ⁠צָד֥וֹק וְ⁠אֶבְיָתָ֖ר כֹּהֲנִֽים׃ס","ẇ⁠bĕnáyá֥hẇ ben-yĕhwòyádá֖ʻ ʻal-ha⁠ẕá̇bá֑ʼ wĕ⁠ẕád֥wòq wĕ⁠ʼebĕyáţá֖r kò̇hàniֽym׃s"],[4,5,"וַ⁠עֲזַרְיָ֥הוּ בֶן־נָתָ֖ן עַל־הַ⁠נִּצָּבִ֑ים וְ⁠זָב֧וּד בֶּן־נָתָ֛ן כֹּהֵ֖ן רֵעֶ֥ה הַ⁠מֶּֽלֶךְ׃","wa⁠ʻàzarĕyá֥hẇ ben-náţá֖n ʻal-ha⁠ni̇ẕá̇bi֑ym wĕ⁠záb֧ẇd bėn-náţá֛n kò̇hé֖n réʻe֥h ha⁠mėֽlekĕ׃"],[4,6,"וַ⁠אֲחִישָׁ֖ר עַל־הַ⁠בָּ֑יִת וַ⁠אֲדֹנִירָ֥ם בֶּן־עַבְדָּ֖א עַל־הַ⁠מַּֽס׃ס","wa⁠ʼàẖiyşá֖̌r ʻal-ha⁠bá֑̇yiţ wa⁠ʼàdòniyrá֥m bėn-ʻabĕdá֖̇ʼ ʻal-ha⁠mȧֽs׃s"],[4,7,"וְ⁠לִ⁠שְׁלֹמֹ֞ה שְׁנֵים־עָשָׂ֤ר נִצָּבִים֙ עַל־כָּל־יִשְׂרָאֵ֔ל וְ⁠כִלְכְּל֥וּ אֶת־הַ⁠מֶּ֖לֶךְ וְ⁠אֶת־בֵּית֑⁠וֹ חֹ֧דֶשׁ בַּ⁠שָּׁנָ֛ה יִהְיֶ֥ה עַל־אחד לְ⁠כַלְכֵּֽל׃ס","wĕ⁠li⁠şĕ̌lòmò֞h şĕ̌néym-ʻáşá֤̂r niẕá̇biym֙ ʻal-ká̇l-yişĕ̂ráʼé֔l wĕ⁠kilĕkĕ̇l֥ẇ ʼeţ-ha⁠mė֖lekĕ wĕ⁠ʼeţ-bé̇yţ֑⁠wò ẖò֧deş̌ bȧ⁠şá̇̌ná֛h yihĕye֥h ʻal-ʼẖd lĕ⁠kalĕkéֽ̇l׃s"],[4,8,"וְ⁠אֵ֣לֶּה שְׁמוֹתָ֔⁠ם בֶּן־ח֖וּר בְּ⁠הַ֥ר אֶפְרָֽיִם׃ס","wĕ⁠ʼé֣lėh şĕ̌mwòţá֔⁠m bėn-ẖ֖ẇr bĕ̇⁠ha֥r ʼepĕráֽyim׃s"],[4,9,"בֶּן־דֶּ֛קֶר בְּ⁠מָקַ֥ץ וּ⁠בְ⁠שַֽׁעַלְבִ֖ים וּ⁠בֵ֣ית שָׁ֑מֶשׁ וְ⁠אֵיל֖וֹן בֵּ֥ית חָנָֽן׃ס","bėn-dė֛qer bĕ̇⁠máqa֥ẕ ẇ⁠bĕ⁠şǎֽʻalĕbi֖ym ẇ⁠bé֣yţ şá֑̌meş̌ wĕ⁠ʼéyl֖wòn bé֥̇yţ ẖánáֽn׃s"],[4,10,"בֶּן־חֶ֖סֶד בָּֽ⁠אֲרֻבּ֑וֹת ל֥⁠וֹ שֹׂכֹ֖ה וְ⁠כָל־אֶ֥רֶץ חֵֽפֶר׃ס","bėn-ẖe֖sed báֽ̇⁠ʼàruḃ֑wòţ l֥⁠wò şò̂kò֖h wĕ⁠kál-ʼe֥reẕ ẖéֽper׃s"],[4,11,"בֶּן־אֲבִֽינָדָ֖ב כָּל־נָ֣פַת דֹּ֑אר טָפַת֙ בַּת־שְׁלֹמֹ֔ה הָ֥יְתָה לּ֖⁠וֹ לְ⁠אִשָּֽׁה׃ס","bėn-ʼàbiֽynádá֖b ká̇l-ná֣paţ dò֑̇ʼr tápaţ֙ bȧţ-şĕ̌lòmò֔h há֥yĕţáh l֖̇⁠wò lĕ⁠ʼişáֽ̇̌h׃s"],[4,12,"בַּֽעֲנָא֙ בֶּן־אֲחִיל֔וּד תַּעְנַ֖ךְ וּ⁠מְגִדּ֑וֹ וְ⁠כָל־בֵּ֣ית שְׁאָ֡ן אֲשֶׁר֩ אֵ֨צֶל צָרְתַ֜נָ⁠ה מִ⁠תַּ֣חַת לְ⁠יִזְרְעֶ֗אל מִ⁠בֵּ֤ית שְׁאָן֙ עַ֚ד אָבֵ֣ל מְחוֹלָ֔ה עַ֖ד מֵ⁠עֵ֥בֶר לְ⁠יָקְמֳעָֽם׃ס","bȧֽʻànáʼ֙ bėn-ʼàẖiyl֔ẇd ţȧʻĕna֖kĕ ẇ⁠mĕgiḋ֑wò wĕ⁠kál-bé֣̇yţ şĕ̌ʼá֡n ʼàşěr֩ ʼé֨ẕel ẕárĕţa֜ná⁠h mi⁠ţȧ֣ẖaţ lĕ⁠yizĕrĕʻe֗ʼl mi⁠bé֤̇yţ şĕ̌ʼán֙ ʻa֚d ʼábé֣l mĕẖwòlá֔h ʻa֖d mé⁠ʻé֥ber lĕ⁠yáqĕmoʻáֽm׃s"],[4,13,"בֶּן־גֶּ֖בֶר בְּ⁠רָמֹ֣ת גִּלְעָ֑ד ל֡⁠וֹ חַוֺּת֩ יָאִ֨יר בֶּן־מְנַשֶּׁ֜ה אֲשֶׁ֣ר בַּ⁠גִּלְעָ֗ד ל֚⁠וֹ חֶ֤בֶל אַרְגֹּב֙ אֲשֶׁ֣ר בַּ⁠בָּשָׁ֔ן שִׁשִּׁים֙ עָרִ֣ים גְּדֹל֔וֹת חוֹמָ֖ה וּ⁠בְרִ֥יחַ נְחֹֽשֶׁת׃ס","bėn-gė֖ber bĕ̇⁠rámò֣ţ gi̇lĕʻá֑d l֡⁠wò ẖaẇֺţ֩ yáʼi֨yr bėn-mĕnaşė̌֜h ʼàşě֣r bȧ⁠gi̇lĕʻá֗d l֚⁠wò ẖe֤bel ʼarĕgò̇b֙ ʼàşě֣r bȧ⁠bá̇şá̌֔n şǐşi̇̌ym֙ ʻári֣ym gĕ̇dòl֔wòţ ẖwòmá֖h ẇ⁠bĕri֥yẖa nĕẖòֽşěţ׃s"],[4,14,"אֲחִֽינָדָ֥ב בֶּן־עִדֹּ֖א מַחֲנָֽיְמָ⁠ה׃","ʼàẖiֽynádá֥b bėn-ʻidò֖̇ʼ maẖànáֽyĕmá⁠h׃"],[4,15,"אֲחִימַ֖עַץ בְּ⁠נַפְתָּלִ֑י גַּם־ה֗וּא לָקַ֛ח אֶת־בָּשְׂמַ֥ת בַּת־שְׁלֹמֹ֖ה לְ⁠אִשָּֽׁה׃","ʼàẖiyma֖ʻaẕ bĕ̇⁠napĕţá̇li֑y gȧm-h֗ẇʼ láqa֛ẖ ʼeţ-bá̇şĕ̂ma֥ţ bȧţ-şĕ̌lòmò֖h lĕ⁠ʼişáֽ̇̌h׃"],[4,16,"בַּֽעֲנָא֙ בֶּן־חוּשָׁ֔י בְּ⁠אָשֵׁ֖ר וּ⁠בְעָלֽוֹת׃ס","bȧֽʻànáʼ֙ bėn-ẖẇşá̌֔y bĕ̇⁠ʼáşé֖̌r ẇ⁠bĕʻálֽwòţ׃s"],[4,17,"יְהוֹשָׁפָ֥ט בֶּן־פָּר֖וּחַ בְּ⁠יִשָׂשכָֽר׃ס","yĕhwòşá̌pá֥t bėn-pá̇r֖ẇẖa bĕ̇⁠yişá̂şkáֽr׃s"],[4,18,"שִׁמְעִ֥י בֶן־אֵלָ֖א בְּ⁠בִנְיָמִֽן׃ס","şǐmĕʻi֥y ben-ʼélá֖ʼ bĕ̇⁠binĕyámiֽn׃s"],[4,19,"גֶּ֥בֶר בֶּן־אֻרִ֖י בְּ⁠אֶ֣רֶץ גִּלְעָ֑ד אֶ֜רֶץ סִיח֣וֹן ׀ מֶ֣לֶךְ הָ⁠אֱמֹרִ֗י וְ⁠עֹג֙ מֶ֣לֶךְ הַ⁠בָּשָׁ֔ן וּ⁠נְצִ֥יב אֶחָ֖ד אֲשֶׁ֥ר בָּ⁠אָֽרֶץ׃","gė֥ber bėn-ʼuri֖y bĕ̇⁠ʼe֣reẕ gi̇lĕʻá֑d ʼe֜reẕ siyẖ֣wòn ׀ me֣lekĕ há⁠ʼèmòri֗y wĕ⁠ʻòg֙ me֣lekĕ ha⁠bá̇şá̌֔n ẇ⁠nĕẕi֥yb ʼeẖá֖d ʼàşě֥r bá̇⁠ʼáֽreẕ׃"],[4,20,"יְהוּדָ֤ה וְ⁠יִשְׂרָאֵל֙ רַבִּ֔ים כַּ⁠ח֥וֹל אֲשֶׁר־עַל־הַ⁠יָּ֖ם לָ⁠רֹ֑ב אֹכְלִ֥ים וְ⁠שֹׁתִ֖ים וּ⁠שְׂמֵחִֽים׃","yĕhẇdá֤h wĕ⁠yişĕ̂ráʼél֙ rabi̇֔ym kȧ⁠ẖ֥wòl ʼàşěr-ʻal-ha⁠yá֖̇m lá⁠rò֑b ʼòkĕli֥ym wĕ⁠şò̌ţi֖ym ẇ⁠şĕ̂méẖiֽym׃"],[4,21,"וּ⁠שְׁלֹמֹ֗ה הָיָ֤ה מוֹשֵׁל֙ בְּ⁠כָל־הַ⁠מַּמְלָכ֔וֹת מִן־הַ⁠נָּהָר֙ אֶ֣רֶץ פְּלִשְׁתִּ֔ים וְ⁠עַ֖ד גְּב֣וּל מִצְרָ֑יִם מַגִּשִׁ֥ים מִנְחָ֛ה וְ⁠עֹבְדִ֥ים אֶת־שְׁלֹמֹ֖ה כָּל־יְמֵ֥י חַיָּֽי⁠ו׃פ","ẇ⁠şĕ̌lòmò֗h háyá֤h mwòşé̌l֙ bĕ̇⁠kál-ha⁠mȧmĕlák֔wòţ min-ha⁠ná̇hár֙ ʼe֣reẕ pĕ̇lişĕ̌ţi̇֔ym wĕ⁠ʻa֖d gĕ̇b֣ẇl miẕĕrá֑yim magi̇şǐ֥ym minĕẖá֛h wĕ⁠ʻòbĕdi֥ym ʼeţ-şĕ̌lòmò֖h ká̇l-yĕmé֥y ẖayáֽ̇y⁠w׃p"],[4,22,"וַ⁠יְהִ֥י לֶֽחֶם־שְׁלֹמֹ֖ה לְ⁠י֣וֹם אֶחָ֑ד שְׁלֹשִׁ֥ים כֹּר֙ סֹ֔לֶת וְ⁠שִׁשִּׁ֥ים כֹּ֖ר קָֽמַח׃","wa⁠yĕhi֥y leֽẖem-şĕ̌lòmò֖h lĕ⁠y֣wòm ʼeẖá֑d şĕ̌lòşǐ֥ym kò̇r֙ sò֔leţ wĕ⁠şǐşi֥̇̌ym kò֖̇r qáֽmaẖ׃"],[4,23,"עֲשָׂרָ֨ה בָקָ֜ר בְּרִאִ֗ים וְ⁠עֶשְׂרִ֥ים בָּקָ֛ר רְעִ֖י וּ⁠מֵ֣אָה צֹ֑אן לְ֠⁠בַד מֵֽ⁠אַיָּ֤ל וּ⁠צְבִי֙ וְ⁠יַחְמ֔וּר וּ⁠בַרְבֻּרִ֖ים אֲבוּסִֽים׃","ʻàşá̂rá֨h báqá֜r bĕ̇riʼi֗ym wĕ⁠ʻeşĕ̂ri֥ym bá̇qá֛r rĕʻi֖y ẇ⁠mé֣ʼáh ẕò֑ʼn lĕ֠⁠bad méֽ⁠ʼayá֤̇l ẇ⁠ẕĕbiy֙ wĕ⁠yaẖĕm֔ẇr ẇ⁠barĕbu̇ri֖ym ʼàbẇsiֽym׃"],[4,24,"כִּי־ה֞וּא רֹדֶ֣ה ׀ בְּ⁠כָל־עֵ֣בֶר הַ⁠נָּהָ֗ר מִ⁠תִּפְסַח֙ וְ⁠עַד־עַזָּ֔ה בְּ⁠כָל־מַלְכֵ֖י עֵ֣בֶר הַ⁠נָּהָ֑ר וְ⁠שָׁל֗וֹם הָ֥יָה ל֛⁠וֹ מִ⁠כָּל־עֲבָרָ֖י⁠ו מִ⁠סָּבִֽיב׃","ki̇y-h֞ẇʼ ròde֣h ׀ bĕ̇⁠kál-ʻé֣ber ha⁠ná̇há֗r mi⁠ţi̇pĕsaẖ֙ wĕ⁠ʻad-ʻazá̇֔h bĕ̇⁠kál-malĕké֖y ʻé֣ber ha⁠ná̇há֑r wĕ⁠şá̌l֗wòm há֥yáh l֛⁠wò mi⁠ká̇l-ʻàbárá֖y⁠w mi⁠sá̇biֽyb׃"],[4,25,"וַ⁠יֵּשֶׁב֩ יְהוּדָ֨ה וְ⁠יִשְׂרָאֵ֜ל לָ⁠בֶ֗טַח אִ֣ישׁ תַּ֤חַת גַּפְנ⁠וֹ֙ וְ⁠תַ֣חַת תְּאֵֽנָת֔⁠וֹ מִ⁠דָּ֖ן וְ⁠עַד־בְּאֵ֣ר שָׁ֑בַע כֹּ֖ל יְמֵ֥י שְׁלֹמֹֽה׃ס","wa⁠yé̇şěb֩ yĕhẇdá֨h wĕ⁠yişĕ̂ráʼé֜l lá⁠be֗taẖ ʼi֣yş̌ ţȧ֤ẖaţ gȧpĕn⁠wò֙ wĕ⁠ţa֣ẖaţ ţĕ̇ʼéֽnáţ֔⁠wò mi⁠dá֖̇n wĕ⁠ʻad-bĕ̇ʼé֣r şá֑̌baʻ kò֖̇l yĕmé֥y şĕ̌lòmòֽh׃s"],[4,26,"וַ⁠יְהִ֣י לִ⁠שְׁלֹמֹ֗ה אַרְבָּעִ֥ים אֶ֛לֶף אֻרְוֺ֥ת סוּסִ֖ים לְ⁠מֶרְכָּב֑⁠וֹ וּ⁠שְׁנֵים־עָשָׂ֥ר אֶ֖לֶף פָּרָשִֽׁים׃","wa⁠yĕhi֣y li⁠şĕ̌lòmò֗h ʼarĕbá̇ʻi֥ym ʼe֛lep ʼurĕwֺ֥ţ sẇsi֖ym lĕ⁠merĕká̇b֑⁠wò ẇ⁠şĕ̌néym-ʻáşá֥̂r ʼe֖lep pá̇ráşǐֽym׃"],[4,27,"וְ⁠כִלְכְּלוּ֩ הַ⁠נִּצָּבִ֨ים הָ⁠אֵ֜לֶּה אֶת־הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֗ה וְ⁠אֵ֧ת כָּל־הַ⁠קָּרֵ֛ב אֶל־שֻׁלְחַ֥ן הַ⁠מֶּֽלֶךְ־שְׁלֹמֹ֖ה אִ֣ישׁ חָדְשׁ֑⁠וֹ לֹ֥א יְעַדְּר֖וּ דָּבָֽר׃","wĕ⁠kilĕkĕ̇lẇ֩ ha⁠ni̇ẕá̇bi֨ym há⁠ʼé֜lėh ʼeţ-ha⁠mė֣lekĕ şĕ̌lòmò֗h wĕ⁠ʼé֧ţ ká̇l-ha⁠qá̇ré֛b ʼel-şǔlĕẖa֥n ha⁠mėֽlekĕ-şĕ̌lòmò֖h ʼi֣yş̌ ẖádĕş֑̌⁠wò lò֥ʼ yĕʻadĕ̇r֖ẇ dá̇báֽr׃"],[4,28,"וְ⁠הַ⁠שְּׂעֹרִ֣ים וְ⁠הַ⁠תֶּ֔בֶן לַ⁠סּוּסִ֖ים וְ⁠לָ⁠רָ֑כֶשׁ יָבִ֗אוּ אֶל־הַ⁠מָּקוֹם֙ אֲשֶׁ֣ר יִֽהְיֶה־שָּׁ֔ם אִ֖ישׁ כְּ⁠מִשְׁפָּטֽ⁠וֹ׃ס","wĕ⁠ha⁠şĕ̇̂ʻòri֣ym wĕ⁠ha⁠ţė֔ben la⁠ṡẇsi֖ym wĕ⁠lá⁠rá֑keş̌ yábi֗ʼẇ ʼel-ha⁠má̇qwòm֙ ʼàşě֣r yiֽhĕyeh-şá̇̌֔m ʼi֖yş̌ kĕ̇⁠mişĕ̌pá̇tֽ⁠wò׃s"],[4,29,"וַ⁠יִּתֵּן֩ אֱלֹהִ֨ים חָכְמָ֧ה לִ⁠שְׁלֹמֹ֛ה וּ⁠תְבוּנָ֖ה הַרְבֵּ֣ה מְאֹ֑ד וְ⁠רֹ֣חַב לֵ֔ב כַּ⁠ח֕וֹל אֲשֶׁ֖ר עַל־שְׂפַ֥ת הַ⁠יָּֽם׃","wa⁠yi̇ţé̇n֩ ʼèlòhi֨ym ẖákĕmá֧h li⁠şĕ̌lòmò֛h ẇ⁠ţĕbẇná֖h harĕbé֣̇h mĕʼò֑d wĕ⁠rò֣ẖab lé֔b kȧ⁠ẖ֕wòl ʼàşě֖r ʻal-şĕ̂pa֥ţ ha⁠yáֽ̇m׃"],[4,30,"וַ⁠תֵּ֨רֶב֙ חָכְמַ֣ת שְׁלֹמֹ֔ה מֵֽ⁠חָכְמַ֖ת כָּל־בְּנֵי־קֶ֑דֶם וּ⁠מִ⁠כֹּ֖ל חָכְמַ֥ת מִצְרָֽיִם׃","wa⁠ţé̇֨reb֙ ẖákĕma֣ţ şĕ̌lòmò֔h méֽ⁠ẖákĕma֖ţ ká̇l-bĕ̇néy-qe֑dem ẇ⁠mi⁠kò֖̇l ẖákĕma֥ţ miẕĕráֽyim׃"],[4,31,"וַ⁠יֶּחְכַּם֮ מִ⁠כָּל־הָֽ⁠אָדָם֒ מֵ⁠אֵיתָ֣ן הָ⁠אֶזְרָחִ֗י וְ⁠הֵימָ֧ן וְ⁠כַלְכֹּ֛ל וְ⁠דַרְדַּ֖ע בְּנֵ֣י מָח֑וֹל וַ⁠יְהִֽי־שְׁמ֥⁠וֹ בְ⁠כָֽל־הַ⁠גּוֹיִ֖ם סָבִֽיב׃","wa⁠yėẖĕkȧm֮ mi⁠ká̇l-háֽ⁠ʼádám֒ mé⁠ʼéyţá֣n há⁠ʼezĕráẖi֗y wĕ⁠héymá֧n wĕ⁠kalĕkò֛̇l wĕ⁠darĕdȧ֖ʻ bĕ̇né֣y máẖ֑wòl wa⁠yĕhiֽy-şĕ̌m֥⁠wò bĕ⁠káֽl-ha⁠ġwòyi֖m sábiֽyb׃"],[4,32,"וַ⁠יְדַבֵּ֕ר שְׁלֹ֥שֶׁת אֲלָפִ֖ים מָשָׁ֑ל וַ⁠יְהִ֥י שִׁיר֖⁠וֹ חֲמִשָּׁ֥ה וָ⁠אָֽלֶף׃","wa⁠yĕdabé̇֕r şĕ̌lò֥şěţ ʼàlápi֖ym máşá֑̌l wa⁠yĕhi֥y şǐyr֖⁠wò ẖàmişá֥̇̌h wá⁠ʼáֽlep׃"],[4,33,"וַ⁠יְדַבֵּר֮ עַל־הָֽ⁠עֵצִים֒ מִן־הָ⁠אֶ֨רֶז֙ אֲשֶׁ֣ר בַּ⁠לְּבָנ֔וֹן וְ⁠עַד֙ הָ⁠אֵז֔וֹב אֲשֶׁ֥ר יֹצֵ֖א בַּ⁠קִּ֑יר וַ⁠יְדַבֵּר֙ עַל־הַ⁠בְּהֵמָ֣ה וְ⁠עַל־הָ⁠ע֔וֹף וְ⁠עַל־הָ⁠רֶ֖מֶשׂ וְ⁠עַל־הַ⁠דָּגִֽים׃","wa⁠yĕdabé̇r֮ ʻal-hֽá⁠ʻéẕiym֒ min-há⁠ʼe֨rez֙ ʼàşě֣r bȧ⁠lĕ̇bán֔wòn wĕ⁠ʻad֙ há⁠ʼéz֔wòb ʼàşě֥r yòẕé֖ʼ bȧ⁠qi֑̇yr wa⁠yĕdabé̇r֙ ʻal-ha⁠bĕ̇hémá֣h wĕ⁠ʻal-há⁠ʻ֔wòp wĕ⁠ʻal-há⁠re֖meş̂ wĕ⁠ʻal-ha⁠dá̇giֽym׃"],[4,34,"וַ⁠יָּבֹ֨אוּ֙ מִ⁠כָּל־הָ֣⁠עַמִּ֔ים לִ⁠שְׁמֹ֕עַ אֵ֖ת חָכְמַ֣ת שְׁלֹמֹ֑ה מֵ⁠אֵת֙ כָּל־מַלְכֵ֣י הָ⁠אָ֔רֶץ אֲשֶׁ֥ר שָׁמְע֖וּ אֶת־חָכְמָתֽ⁠וֹ׃ס","wa⁠yá̇bò֨ʼẇ֙ mi⁠ká̇l-há֣⁠ʻami̇֔ym li⁠şĕ̌mò֕ʻa ʼé֖ţ ẖákĕma֣ţ şĕ̌lòmò֑h mé⁠ʼéţ֙ ká̇l-malĕké֣y há⁠ʼá֔reẕ ʼàşě֥r şá̌mĕʻ֖ẇ ʼeţ-ẖákĕmáţֽ⁠wò׃s"],[5,1,"וַ֠⁠יִּשְׁלַח חִירָ֨ם מֶֽלֶךְ־צ֤וֹר אֶת־עֲבָדָי⁠ו֙ אֶל־שְׁלֹמֹ֔ה כִּ֣י שָׁמַ֔ע כִּ֥י אֹת֛⁠וֹ מָשְׁח֥וּ לְ⁠מֶ֖לֶךְ תַּ֣חַת אָבִ֑י⁠הוּ כִּ֣י אֹהֵ֗ב הָיָ֥ה חִירָ֛ם לְ⁠דָוִ֖ד כָּל־הַ⁠יָּמִֽים׃ס","wa֠⁠yi̇şĕ̌laẖ ẖiyrá֨m meֽlekĕ-ẕ֤wòr ʼeţ-ʻàbádáy⁠w֙ ʼel-şĕ̌lòmò֔h ki֣̇y şá̌ma֔ʻ ki֥̇y ʼòţ֛⁠wò máşĕ̌ẖ֥ẇ lĕ⁠me֖lekĕ ţȧ֣ẖaţ ʼábi֑y⁠hẇ ki֣̇y ʼòhé֗b háyá֥h ẖiyrá֛m lĕ⁠dáwi֖d ká̇l-ha⁠yá̇miֽym׃s"],[5,2,"וַ⁠יִּשְׁלַ֣ח שְׁלֹמֹ֔ה אֶל־חִירָ֖ם לֵ⁠אמֹֽר׃","wa⁠yi̇şĕ̌la֣ẖ şĕ̌lòmò֔h ʼel-ẖiyrá֖m lé⁠ʼmòֽr׃"],[5,3,"אַתָּ֨ה יָדַ֜עְתָּ אֶת־דָּוִ֣ד אָבִ֗⁠י כִּ֣י לֹ֤א יָכֹל֙ לִ⁠בְנ֣וֹת בַּ֗יִת לְ⁠שֵׁם֙ יְהוָ֣ה אֱלֹהָ֔י⁠ו מִ⁠פְּנֵ֥י הַ⁠מִּלְחָמָ֖ה אֲשֶׁ֣ר סְבָבֻ֑⁠הוּ עַ֤ד תֵּת־יְהוָה֙ אֹתָ֔⁠ם תַּ֖חַת כַּפּ֥וֹת רגל⁠ו׃","ʼaţá̇֨h yáda֜ʻĕţá̇ ʼeţ-dá̇wi֣d ʼábi֗⁠y ki֣̇y lò֤ʼ yákòl֙ li⁠bĕn֣wòţ bȧ֗yiţ lĕ⁠şé̌m֙ yĕhwá֣h ʼèlòhá֔y⁠w mi⁠pĕ̇né֥y ha⁠mi̇lĕẖámá֖h ʼàşě֣r sĕbábu֑⁠hẇ ʻa֤d ţé̇ţ-yĕhwáh֙ ʼòţá֔⁠m ţȧ֖ẖaţ kȧṗ֥wòţ rgl⁠w׃"],[5,4,"וְ⁠עַתָּ֕ה הֵנִ֨יחַ יְהוָ֧ה אֱלֹהַ֛⁠י לִ֖⁠י מִ⁠סָּבִ֑יב אֵ֣ין שָׂטָ֔ן וְ⁠אֵ֖ין פֶּ֥גַע רָֽע׃","wĕ⁠ʻaţá̇֕h héni֨yẖa yĕhwá֧h ʼèlòha֛⁠y li֖⁠y mi⁠sá̇bi֑yb ʼé֣yn şá̂tá֔n wĕ⁠ʼé֖yn pė֥gaʻ ráֽʻ׃"],[5,5,"וְ⁠הִנְ⁠נִ֣י אֹמֵ֔ר לִ⁠בְנ֣וֹת בַּ֔יִת לְ⁠שֵׁ֖ם יְהוָ֣ה אֱלֹהָ֑⁠י כַּ⁠אֲשֶׁ֣ר ׀ דִּבֶּ֣ר יְהוָ֗ה אֶל־דָּוִ֤ד אָבִ⁠י֙ לֵ⁠אמֹ֔ר בִּנְ⁠ךָ֗ אֲשֶׁ֨ר אֶתֵּ֤ן תַּחְתֶּ֨י⁠ךָ֙ עַל־כִּסְאֶ֔⁠ךָ הֽוּא־יִבְנֶ֥ה הַ⁠בַּ֖יִת לִ⁠שְׁמִֽ⁠י׃","wĕ⁠hinĕ⁠ni֣y ʼòmé֔r li⁠bĕn֣wòţ bȧ֔yiţ lĕ⁠şé֖̌m yĕhwá֣h ʼèlòhá֑⁠y kȧ⁠ʼàşě֣r ׀ di̇bė֣r yĕhwá֗h ʼel-dá̇wi֤d ʼábi⁠y֙ lé⁠ʼmò֔r bi̇nĕ⁠ká֗ ʼàşě֨r ʼeţé֤̇n ţȧẖĕţė֨y⁠ká֙ ʻal-ki̇sĕʼe֔⁠ká hֽẇʼ-yibĕne֥h ha⁠bȧ֖yiţ li⁠şĕ̌miֽ⁠y׃"],[5,6,"וְ⁠עַתָּ֡ה צַוֵּה֩ וְ⁠יִכְרְתוּ־לִ֨⁠י אֲרָזִ֜ים מִן־הַ⁠לְּבָנ֗וֹן וַֽ⁠עֲבָדַ⁠י֙ יִהְי֣וּ עִם־עֲבָדֶ֔י⁠ךָ וּ⁠שְׂכַ֤ר עֲבָדֶ֨י⁠ךָ֙ אֶתֵּ֣ן לְ⁠ךָ֔ כְּ⁠כֹ֖ל אֲשֶׁ֣ר תֹּאמֵ֑ר כִּ֣י ׀ אַתָּ֣ה יָדַ֗עְתָּ כִּ֣י אֵ֥ין בָּ֛⁠נוּ אִ֛ישׁ יֹדֵ֥עַ לִ⁠כְרָת־עֵצִ֖ים כַּ⁠צִּדֹנִֽים׃","wĕ⁠ʻaţá̇֡h ẕawé̇h֩ wĕ⁠yikĕrĕţẇ-li֨⁠y ʼàrázi֜ym min-ha⁠lĕ̇bán֗wòn waֽ⁠ʻàbáda⁠y֙ yihĕy֣ẇ ʻim-ʻàbáde֔y⁠ká ẇ⁠şĕ̂ka֤r ʻàbáde֨y⁠ká֙ ʼeţé֣̇n lĕ⁠ká֔ kĕ̇⁠kò֖l ʼàşě֣r ţò̇ʼmé֑r ki֣̇y ׀ ʼaţá֣̇h yáda֗ʻĕţá̇ ki֣̇y ʼé֥yn bá֛̇⁠nẇ ʼi֛yş̌ yòdé֥ʻa li⁠kĕráţ-ʻéẕi֖ym kȧ⁠ẕi̇dòniֽym׃"],[5,7,"וַ⁠יְהִ֞י כִּ⁠שְׁמֹ֧עַ חִירָ֛ם אֶת־דִּבְרֵ֥י שְׁלֹמֹ֖ה וַ⁠יִּשְׂמַ֣ח מְאֹ֑ד וַ⁠יֹּ֗אמֶר בָּר֤וּךְ יְהוָה֙ הַ⁠יּ֔וֹם אֲשֶׁ֨ר נָתַ֤ן לְ⁠דָוִד֙ בֵּ֣ן חָכָ֔ם עַל־הָ⁠עָ֥ם הָ⁠רָ֖ב הַ⁠זֶּֽה׃","wa⁠yĕhi֞y ki̇⁠şĕ̌mò֧ʻa ẖiyrá֛m ʼeţ-di̇bĕré֥y şĕ̌lòmò֖h wa⁠yi̇şĕ̂ma֣ẖ mĕʼò֑d wa⁠yò̇֗ʼmer bá̇r֤ẇkĕ yĕhwáh֙ ha⁠ẏ֔wòm ʼàşě֨r náţa֤n lĕ⁠dáwid֙ bé֣̇n ẖáká֔m ʻal-há⁠ʻá֥m há⁠rá֖b ha⁠zėֽh׃"],[5,8,"וַ⁠יִּשְׁלַ֤ח חִירָם֙ אֶל־שְׁלֹמֹ֣ה לֵ⁠אמֹ֔ר שָׁמַ֕עְתִּי אֵ֥ת אֲשֶׁר־שָׁלַ֖חְתָּ אֵלָ֑⁠י אֲנִ֤י אֶֽעֱשֶׂה֙ אֶת־כָּל־חֶפְצְ⁠ךָ֔ בַּ⁠עֲצֵ֥י אֲרָזִ֖ים וּ⁠בַ⁠עֲצֵ֥י בְרוֹשִֽׁים׃","wa⁠yi̇şĕ̌la֤ẖ ẖiyrám֙ ʼel-şĕ̌lòmò֣h lé⁠ʼmò֔r şá̌ma֕ʻĕţi̇y ʼé֥ţ ʼàşěr-şá̌la֖ẖĕţá̇ ʼélá֑⁠y ʼàni֤y ʼeֽʻèşêh֙ ʼeţ-ká̇l-ẖepĕẕĕ⁠ká֔ bȧ⁠ʻàẕé֥y ʼàrázi֖ym ẇ⁠ba⁠ʻàẕé֥y bĕrwòşǐֽym׃"],[5,9,"עֲ֠בָדַ⁠י יֹרִ֨דוּ מִן־הַ⁠לְּבָנ֜וֹן יָ֗מָּ⁠ה וַ֠⁠אֲנִי אֲשִׂימֵ֨⁠ם דֹּבְר֤וֹת בַּ⁠יָּם֙ עַֽד־הַ⁠מָּק֞וֹם אֲשֶׁר־תִּשְׁלַ֥ח אֵלַ֛⁠י וְ⁠נִפַּצְתִּ֥י⁠ם שָׁ֖ם וְ⁠אַתָּ֣ה תִשָּׂ֑א וְ⁠אַתָּה֙ תַּעֲשֶׂ֣ה אֶת־חֶפְצִ֔⁠י לָ⁠תֵ֖ת לֶ֥חֶם בֵּיתִֽ⁠י׃","ʻà֠báda⁠y yòri֨dẇ min-ha⁠lĕ̇bán֜wòn yá֗má̇⁠h wa֠⁠ʼàniy ʼàşîymé֨⁠m dò̇bĕr֤wòţ bȧ⁠yá̇m֙ ʻaֽd-ha⁠má̇q֞wòm ʼàşěr-ţi̇şĕ̌la֥ẖ ʼéla֛⁠y wĕ⁠nipȧẕĕţi֥̇y⁠m şá֖̌m wĕ⁠ʼaţá֣̇h ţişá֑̇̂ʼ wĕ⁠ʼaţá̇h֙ ţȧʻàşê֣h ʼeţ-ẖepĕẕi֔⁠y lá⁠ţé֖ţ le֥ẖem bé̇yţiֽ⁠y׃"],[5,10,"וַ⁠יְהִ֨י חִיר֜וֹם נֹתֵ֣ן לִ⁠שְׁלֹמֹ֗ה עֲצֵ֧י אֲרָזִ֛ים וַ⁠עֲצֵ֥י בְרוֹשִׁ֖ים כָּל־חֶפְצֽ⁠וֹ׃","wa⁠yĕhi֨y ẖiyr֜wòm nòţé֣n li⁠şĕ̌lòmò֗h ʻàẕé֧y ʼàrázi֛ym wa⁠ʻàẕé֥y bĕrwòşǐ֖ym ká̇l-ẖepĕẕֽ⁠wò׃"],[5,11,"וּ⁠שְׁלֹמֹה֩ נָתַ֨ן לְ⁠חִירָ֜ם עֶשְׂרִים֩ אֶ֨לֶף כֹּ֤ר חִטִּים֙ מַכֹּ֣לֶת לְ⁠בֵית֔⁠וֹ וְ⁠עֶשְׂרִ֥ים כֹּ֖ר שֶׁ֣מֶן כָּתִ֑ית כֹּֽה־יִתֵּ֧ן שְׁלֹמֹ֛ה לְ⁠חִירָ֖ם שָׁנָ֥ה בְ⁠שָׁנָֽה׃פ","ẇ⁠şĕ̌lòmòh֩ náţa֨n lĕ⁠ẖiyrá֜m ʻeşĕ̂riym֩ ʼe֨lep kò֤̇r ẖiti̇ym֙ makò֣̇leţ lĕ⁠béyţ֔⁠wò wĕ⁠ʻeşĕ̂ri֥ym kò֖̇r şě֣men ká̇ţi֑yţ kòֽ̇h-yiţé֧̇n şĕ̌lòmò֛h lĕ⁠ẖiyrá֖m şá̌ná֥h bĕ⁠şá̌náֽh׃p"],[5,12,"וַ⁠יהוָ֗ה נָתַ֤ן חָכְמָה֙ לִ⁠שְׁלֹמֹ֔ה כַּ⁠אֲשֶׁ֖ר דִּבֶּר־ל֑⁠וֹ וַ⁠יְהִ֣י שָׁלֹ֗ם בֵּ֤ין חִירָם֙ וּ⁠בֵ֣ין שְׁלֹמֹ֔ה וַ⁠יִּכְרְת֥וּ בְרִ֖ית שְׁנֵי⁠הֶֽם׃","wa⁠yhwá֗h náţa֤n ẖákĕmáh֙ li⁠şĕ̌lòmò֔h kȧ⁠ʼàşě֖r di̇bėr-l֑⁠wò wa⁠yĕhi֣y şá̌lò֗m bé֤̇yn ẖiyrám֙ ẇ⁠bé֣yn şĕ̌lòmò֔h wa⁠yi̇kĕrĕţ֥ẇ bĕri֖yţ şĕ̌néy⁠heֽm׃"],[5,13,"וַ⁠יַּ֨עַל הַ⁠מֶּ֧לֶךְ שְׁלֹמֹ֛ה מַ֖ס מִ⁠כָּל־יִשְׂרָאֵ֑ל וַ⁠יְהִ֣י הַ⁠מַּ֔ס שְׁלֹשִׁ֥ים אֶ֖לֶף אִֽישׁ׃","wa⁠yȧ֨ʻal ha⁠mė֧lekĕ şĕ̌lòmò֛h ma֖s mi⁠ká̇l-yişĕ̂ráʼé֑l wa⁠yĕhi֣y ha⁠mȧ֔s şĕ̌lòşǐ֥ym ʼe֖lep ʼiֽyş̌׃"],[5,14,"וַ⁠יִּשְׁלָחֵ֣⁠ם לְבָנ֗וֹנָ⁠ה עֲשֶׂ֨רֶת אֲלָפִ֤ים בַּ⁠חֹ֨דֶשׁ֙ חֲלִיפ֔וֹת חֹ֚דֶשׁ יִהְי֣וּ בַ⁠לְּבָנ֔וֹן שְׁנַ֥יִם חֳדָשִׁ֖ים בְּ⁠בֵית֑⁠וֹ וַ⁠אֲדֹנִירָ֖ם עַל־הַ⁠מַּֽס׃ס","wa⁠yi̇şĕ̌láẖé֣⁠m lĕbán֗wòná⁠h ʻàşê֨reţ ʼàlápi֤ym bȧ⁠ẖò֨deş̌֙ ẖàliyp֔wòţ ẖò֚deş̌ yihĕy֣ẇ ba⁠lĕ̇bán֔wòn şĕ̌na֥yim ẖodáşǐ֖ym bĕ̇⁠béyţ֑⁠wò wa⁠ʼàdòniyrá֖m ʻal-ha⁠mȧֽs׃s"],[5,15,"וַ⁠יְהִ֧י לִ⁠שְׁלֹמֹ֛ה שִׁבְעִ֥ים אֶ֖לֶף נֹשֵׂ֣א סַבָּ֑ל וּ⁠שְׁמֹנִ֥ים אֶ֖לֶף חֹצֵ֥ב בָּ⁠הָֽר׃","wa⁠yĕhi֧y li⁠şĕ̌lòmò֛h şǐbĕʻi֥ym ʼe֖lep nòşé֣̂ʼ sabá֑̇l ẇ⁠şĕ̌mòni֥ym ʼe֖lep ẖòẕé֥b bá̇⁠háֽr׃"],[5,16,"לְ֠⁠בַד מִ⁠שָּׂרֵ֨י הַ⁠נִּצָּבִ֤ים לִ⁠שְׁלֹמֹה֙ אֲשֶׁ֣ר עַל־הַ⁠מְּלָאכָ֔ה שְׁלֹ֥שֶׁת אֲלָפִ֖ים וּ⁠שְׁלֹ֣שׁ מֵא֑וֹת הָ⁠רֹדִ֣ים בָּ⁠עָ֔ם הָ⁠עֹשִׂ֖ים בַּ⁠מְּלָאכָֽה׃","lĕ֠⁠bad mi⁠şá̇̂ré֨y ha⁠ni̇ẕá̇bi֤ym li⁠şĕ̌lòmòh֙ ʼàşě֣r ʻal-ha⁠mĕ̇láʼká֔h şĕ̌lò֥şěţ ʼàlápi֖ym ẇ⁠şĕ̌lò֣ş̌ méʼ֑wòţ há⁠ròdi֣ym bá̇⁠ʻá֔m há⁠ʻòşî֖ym bȧ⁠mĕ̇láʼkáֽh׃"],[5,17,"וַ⁠יְצַ֣ו הַ⁠מֶּ֡לֶךְ וַ⁠יַּסִּעוּ֩ אֲבָנִ֨ים גְּדֹל֜וֹת אֲבָנִ֧ים יְקָר֛וֹת לְ⁠יַסֵּ֥ד הַ⁠בָּ֖יִת אַבְנֵ֥י גָזִֽית׃","wa⁠yĕẕa֣w ha⁠mė֡lekĕ wa⁠yȧsi̇ʻẇ֩ ʼàbáni֨ym gĕ̇dòl֜wòţ ʼàbáni֧ym yĕqár֛wòţ lĕ⁠yasé֥̇d ha⁠bá֖̇yiţ ʼabĕné֥y gáziֽyţ׃"],[5,18,"וַֽ⁠יִּפְסְל֞וּ בֹּנֵ֧י שְׁלֹמֹ֛ה וּ⁠בֹנֵ֥י חִיר֖וֹם וְ⁠הַ⁠גִּבְלִ֑ים וַ⁠יָּכִ֛ינוּ הָ⁠עֵצִ֥ים וְ⁠הָ⁠אֲבָנִ֖ים לִ⁠בְנ֥וֹת הַ⁠בָּֽיִת׃פ","waֽ⁠yi̇pĕsĕl֞ẇ bò̇né֧y şĕ̌lòmò֛h ẇ⁠bòné֥y ẖiyr֖wòm wĕ⁠ha⁠gi̇bĕli֑ym wa⁠yá̇ki֛ynẇ há⁠ʻéẕi֥ym wĕ⁠há⁠ʼàbáni֖ym li⁠bĕn֥wòţ ha⁠báֽ̇yiţ׃p"],[6,1,"וַ⁠יְהִ֣י בִ⁠שְׁמוֹנִ֣ים שָׁנָ֣ה וְ⁠אַרְבַּ֣ע מֵא֣וֹת שָׁנָ֡ה לְ⁠צֵ֣את בְּנֵֽי־יִשְׂרָאֵ֣ל מֵ⁠אֶֽרֶץ־מִצְרַיִם֩ בַּ⁠שָּׁנָ֨ה הָ⁠רְבִיעִ֜ית בְּ⁠חֹ֣דֶשׁ זִ֗ו ה֚וּא הַ⁠חֹ֣דֶשׁ הַ⁠שֵּׁנִ֔י לִ⁠מְלֹ֥ךְ שְׁלֹמֹ֖ה עַל־יִשְׂרָאֵ֑ל וַ⁠יִּ֥בֶן הַ⁠בַּ֖יִת לַ⁠יהוָֽה׃","wa⁠yĕhi֣y bi⁠şĕ̌mwòni֣ym şá̌ná֣h wĕ⁠ʼarĕbȧ֣ʻ méʼ֣wòţ şá̌ná֡h lĕ⁠ẕé֣ʼţ bĕ̇néֽy-yişĕ̂ráʼé֣l mé⁠ʼeֽreẕ-miẕĕrayim֩ bȧ⁠şá̇̌ná֨h há⁠rĕbiyʻi֜yţ bĕ̇⁠ẖò֣deş̌ zi֗w h֚ẇʼ ha⁠ẖò֣deş̌ ha⁠şé̇̌ni֔y li⁠mĕlò֥kĕ şĕ̌lòmò֖h ʻal-yişĕ̂ráʼé֑l wa⁠yi֥̇ben ha⁠bȧ֖yiţ la⁠yhwáֽh׃"],[6,2,"וְ⁠הַ⁠בַּ֗יִת אֲשֶׁ֨ר בָּנָ֜ה הַ⁠מֶּ֤לֶךְ שְׁלֹמֹה֙ לַֽ⁠יהוָ֔ה שִׁשִּֽׁים־אַמָּ֥ה אָרְכּ֖⁠וֹ וְ⁠עֶשְׂרִ֤ים רָחְבּ֑⁠וֹ וּ⁠שְׁלֹשִׁ֥ים אַמָּ֖ה קוֹמָתֽ⁠וֹ׃","wĕ⁠ha⁠bȧ֗yiţ ʼàşě֨r bá̇ná֜h ha⁠mė֤lekĕ şĕ̌lòmòh֙ laֽ⁠yhwá֔h şǐşiֽ̇̌ym-ʼamá֥̇h ʼárĕk֖̇⁠wò wĕ⁠ʻeşĕ̂ri֤ym ráẖĕḃ֑⁠wò ẇ⁠şĕ̌lòşǐ֥ym ʼamá֖̇h qwòmáţֽ⁠wò׃"],[6,3,"וְ⁠הָ⁠אוּלָ֗ם עַל־פְּנֵי֙ הֵיכַ֣ל הַ⁠בַּ֔יִת עֶשְׂרִ֣ים אַמָּה֙ אָרְכּ֔⁠וֹ עַל־פְּנֵ֖י רֹ֣חַב הַ⁠בָּ֑יִת עֶ֧שֶׂר בָּ⁠אַמָּ֛ה רָחְבּ֖⁠וֹ עַל־פְּנֵ֥י הַ⁠בָּֽיִת׃","wĕ⁠há⁠ʼẇlá֗m ʻal-pĕ̇néy֙ héyka֣l ha⁠bȧ֔yiţ ʻeşĕ̂ri֣ym ʼamá̇h֙ ʼárĕk̇֔⁠wò ʻal-pĕ̇né֖y rò֣ẖab ha⁠bá֑̇yiţ ʻe֧şêr bá̇⁠ʼamá֛̇h ráẖĕḃ֖⁠wò ʻal-pĕ̇né֥y ha⁠báֽ̇yiţ׃"],[6,4,"וַ⁠יַּ֣עַשׂ לַ⁠בָּ֔יִת חַלּוֹנֵ֖י שְׁקֻפִ֥ים אֲטֻמִֽים׃","wa⁠yȧ֣ʻaş̂ la⁠bá̇֔yiţ ẖal̇wòné֖y şĕ̌qupi֥ym ʼàtumiֽym׃"],[6,5,"וַ⁠יִּבֶן֩ עַל־קִ֨יר הַ⁠בַּ֤יִת יצוע סָבִ֔יב אֶת־קִיר֤וֹת הַ⁠בַּ֨יִת֙ סָבִ֔יב לַֽ⁠הֵיכָ֖ל וְ⁠לַ⁠דְּבִ֑יר וַ⁠יַּ֥עַשׂ צְלָע֖וֹת סָבִֽיב׃","wa⁠yi̇ben֩ ʻal-qi֨yr ha⁠bȧ֤yiţ yẕwʻ sábi֔yb ʼeţ-qiyr֤wòţ ha⁠bȧ֨yiţ֙ sábi֔yb laֽ⁠héyká֖l wĕ⁠la⁠dĕ̇bi֑yr wa⁠yȧ֥ʻaş̂ ẕĕláʻ֖wòţ sábiֽyb׃"],[6,6,"ה⁠יצוע הַ⁠תַּחְתֹּנָ֜ה חָמֵ֧שׁ בָּ⁠אַמָּ֣ה רָחְבָּ֗⁠הּ וְ⁠הַ⁠תִּֽיכֹנָה֙ שֵׁ֤שׁ בָּֽ⁠אַמָּה֙ רָחְבָּ֔⁠הּ וְ⁠הַ֨⁠שְּׁלִישִׁ֔ית שֶׁ֥בַע בָּ⁠אַמָּ֖ה רָחְבָּ֑⁠הּ כִּ֡י מִגְרָעוֹת֩ נָתַ֨ן לַ⁠בַּ֤יִת סָבִיב֙ ח֔וּצָ⁠ה לְ⁠בִלְתִּ֖י אֲחֹ֥ז בְּ⁠קִֽירוֹת־הַ⁠בָּֽיִת׃","h⁠yẕwʻ ha⁠ţȧẖĕţò̇ná֜h ẖámé֧ş̌ bá̇⁠ʼamá֣̇h ráẖĕbá̇֗⁠ḣ wĕ⁠ha⁠ţiֽ̇ykònáh֙ şé֤̌ş̌ báֽ̇⁠ʼamá̇h֙ ráẖĕbá̇֔⁠ḣ wĕ⁠ha֨⁠şĕ̇̌liyşǐ֔yţ şě֥baʻ bá̇⁠ʼamá֖̇h ráẖĕbá֑̇⁠ḣ ki̇֡y migĕráʻwòţ֩ náţa֨n la⁠bȧ֤yiţ sábiyb֙ ẖ֔ẇẕá⁠h lĕ⁠bilĕţi֖̇y ʼàẖò֥z bĕ̇⁠qiֽyrwòţ-ha⁠báֽ̇yiţ׃"],[6,7,"וְ⁠הַ⁠בַּ֨יִת֙ בְּ⁠הִבָּ֣נֹת֔⁠וֹ אֶֽבֶן־שְׁלֵמָ֥ה מַסָּ֖ע נִבְנָ֑ה וּ⁠מַקָּב֤וֹת וְ⁠הַ⁠גַּרְזֶן֙ כָּל־כְּלִ֣י בַרְזֶ֔ל לֹֽא־נִשְׁמַ֥ע בַּ⁠בַּ֖יִת בְּ⁠הִבָּנֹתֽ⁠וֹ׃","wĕ⁠ha⁠bȧ֨yiţ֙ bĕ̇⁠hibá֣̇nòţ֔⁠wò ʼeֽben-şĕ̌lémá֥h masá֖̇ʻ nibĕná֑h ẇ⁠maqá̇b֤wòţ wĕ⁠ha⁠gȧrĕzen֙ ká̇l-kĕ̇li֣y barĕze֔l lòֽʼ-nişĕ̌ma֥ʻ bȧ⁠bȧ֖yiţ bĕ̇⁠hibá̇nòţֽ⁠wò׃"],[6,8,"פֶּ֗תַח הַ⁠צֵּלָע֙ הַ⁠תִּ֣יכֹנָ֔ה אֶל־כֶּ֥תֶף הַ⁠בַּ֖יִת הַ⁠יְמָנִ֑ית וּ⁠בְ⁠לוּלִּ֗ים יַֽעֲלוּ֙ עַל־הַ⁠תִּ֣יכֹנָ֔ה וּ⁠מִן־הַ⁠תִּֽיכֹנָ֖ה אֶל־הַ⁠שְּׁלִשִֽׁים׃","pė֗ţaẖ ha⁠ẕé̇láʻ֙ ha⁠ţi֣̇ykòná֔h ʼel-kė֥ţep ha⁠bȧ֖yiţ ha⁠yĕmáni֑yţ ẇ⁠bĕ⁠lẇli̇֗ym yaֽʻàlẇ֙ ʻal-ha⁠ţi֣̇ykòná֔h ẇ⁠min-ha⁠ţiֽ̇ykòná֖h ʼel-ha⁠şĕ̇̌lişǐֽym׃"],[6,9,"וַ⁠יִּ֥בֶן אֶת־הַ⁠בַּ֖יִת וַ⁠יְכַלֵּ֑⁠הוּ וַ⁠יִּסְפֹּ֤ן אֶת־הַ⁠בַּ֨יִת֙ גֵּבִ֔ים וּ⁠שְׂדֵרֹ֖ת בָּ⁠אֲרָזִֽים׃","wa⁠yi֥̇ben ʼeţ-ha⁠bȧ֖yiţ wa⁠yĕkalé֑̇⁠hẇ wa⁠yi̇sĕpò֤̇n ʼeţ-ha⁠bȧ֨yiţ֙ gé̇bi֔ym ẇ⁠şĕ̂dérò֖ţ bá̇⁠ʼàráziֽym׃"],[6,10,"וַ⁠יִּ֤בֶן אֶת־ה⁠יצוע עַל־כָּל־הַ⁠בַּ֔יִת חָמֵ֥שׁ אַמּ֖וֹת קֽוֹמָת֑⁠וֹ וַ⁠יֶּאֱחֹ֥ז אֶת־הַ⁠בַּ֖יִת בַּ⁠עֲצֵ֥י אֲרָזִֽים׃פ","wa⁠yi֤̇ben ʼeţ-h⁠yẕwʻ ʻal-ká̇l-ha⁠bȧ֔yiţ ẖámé֥ş̌ ʼaṁ֖wòţ qֽwòmáţ֑⁠wò wa⁠yėʼèẖò֥z ʼeţ-ha⁠bȧ֖yiţ bȧ⁠ʻàẕé֥y ʼàráziֽym׃p"],[6,11,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־שְׁלֹמֹ֖ה לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-şĕ̌lòmò֖h lé⁠ʼmòֽr׃"],[6,12,"הַ⁠בַּ֨יִת הַ⁠זֶּ֜ה אֲשֶׁר־אַתָּ֣ה בֹנֶ֗ה אִם־תֵּלֵ֤ךְ בְּ⁠חֻקֹּתַ⁠י֙ וְ⁠אֶת־מִשְׁפָּטַ֣⁠י תַּֽעֲשֶׂ֔ה וְ⁠שָׁמַרְתָּ֥ אֶת־כָּל־מִצְוֺתַ֖⁠י לָ⁠לֶ֣כֶת בָּ⁠הֶ֑ם וַ⁠הֲקִמֹתִ֤י אֶת־דְּבָרִ⁠י֙ אִתָּ֔⁠ךְ אֲשֶׁ֥ר דִּבַּ֖רְתִּי אֶל־דָּוִ֥ד אָבִֽי⁠ךָ׃","ha⁠bȧ֨yiţ ha⁠zė֜h ʼàşěr-ʼaţá֣̇h bòne֗h ʼim-ţé̇lé֤kĕ bĕ̇⁠ẖuqò̇ţa⁠y֙ wĕ⁠ʼeţ-mişĕ̌pá̇ta֣⁠y ţȧֽʻàşê֔h wĕ⁠şá̌marĕţá֥̇ ʼeţ-ká̇l-miẕĕwֺţa֖⁠y lá⁠le֣keţ bá̇⁠he֑m wa⁠hàqimòţi֤y ʼeţ-dĕ̇bári⁠y֙ ʼiţá̇֔⁠kĕ ʼàşě֥r di̇bȧ֖rĕţi̇y ʼel-dá̇wi֥d ʼábiֽy⁠ká׃"],[6,13,"וְ⁠שָׁ֣כַנְתִּ֔י בְּ⁠ת֖וֹךְ בְּנֵ֣י יִשְׂרָאֵ֑ל וְ⁠לֹ֥א אֶעֱזֹ֖ב אֶת־עַמִּ֥⁠י יִשְׂרָאֵֽל׃ס","wĕ⁠şá֣̌kanĕţi̇֔y bĕ̇⁠ţ֖wòkĕ bĕ̇né֣y yişĕ̂ráʼé֑l wĕ⁠lò֥ʼ ʼeʻèzò֖b ʼeţ-ʻami֥̇⁠y yişĕ̂ráʼéֽl׃s"],[6,14,"וַ⁠יִּ֧בֶן שְׁלֹמֹ֛ה אֶת־הַ⁠בַּ֖יִת וַ⁠יְכַלֵּֽ⁠הוּ׃","wa⁠yi֧̇ben şĕ̌lòmò֛h ʼeţ-ha⁠bȧ֖yiţ wa⁠yĕkaléֽ̇⁠hẇ׃"],[6,15,"וַ⁠יִּבֶן֩ אֶת־קִיר֨וֹת הַ⁠בַּ֤יִת מִ⁠בַּ֨יְתָ⁠ה֙ בְּ⁠צַלְע֣וֹת אֲרָזִ֔ים מִ⁠קַּרְקַ֤ע הַ⁠בַּ֨יִת֙ עַד־קִיר֣וֹת הַ⁠סִּפֻּ֔ן צִפָּ֥ה עֵ֖ץ מִ⁠בָּ֑יִת וַ⁠יְצַ֛ף אֶת־קַרְקַ֥ע הַ⁠בַּ֖יִת בְּ⁠צַלְע֥וֹת בְּרוֹשִֽׁים׃","wa⁠yi̇ben֩ ʼeţ-qiyr֨wòţ ha⁠bȧ֤yiţ mi⁠bȧ֨yĕţá⁠h֙ bĕ̇⁠ẕalĕʻ֣wòţ ʼàrázi֔ym mi⁠qȧrĕqa֤ʻ ha⁠bȧ֨yiţ֙ ʻad-qiyr֣wòţ ha⁠si̇pu̇֔n ẕipá֥̇h ʻé֖ẕ mi⁠bá֑̇yiţ wa⁠yĕẕa֛p ʼeţ-qarĕqa֥ʻ ha⁠bȧ֖yiţ bĕ̇⁠ẕalĕʻ֥wòţ bĕ̇rwòşǐֽym׃"],[6,16,"וַ⁠יִּבֶן֩ אֶת־עֶשְׂרִ֨ים אַמָּ֜ה מ⁠ירכותי הַ⁠בַּ֨יִת֙ בְּ⁠צַלְע֣וֹת אֲרָזִ֔ים מִן־הַ⁠קַּרְקַ֖ע עַד־הַ⁠קִּיר֑וֹת וַ⁠יִּ֤בֶן ל⁠וֹ֙ מִ⁠בַּ֣יִת לִ⁠דְבִ֔יר לְ⁠קֹ֖דֶשׁ הַ⁠קֳּדָשִֽׁים׃","wa⁠yi̇ben֩ ʼeţ-ʻeşĕ̂ri֨ym ʼamá̇֜h m⁠yrkwţy ha⁠bȧ֨yiţ֙ bĕ̇⁠ẕalĕʻ֣wòţ ʼàrázi֔ym min-ha⁠qȧrĕqa֖ʻ ʻad-ha⁠qi̇yr֑wòţ wa⁠yi֤̇ben l⁠wò֙ mi⁠bȧ֣yiţ li⁠dĕbi֔yr lĕ⁠qò֖deş̌ ha⁠qȯdáşǐֽym׃"],[6,17,"וְ⁠אַרְבָּעִ֥ים בָּ⁠אַמָּ֖ה הָיָ֣ה הַ⁠בָּ֑יִת ה֖וּא הַ⁠הֵיכָ֥ל לִ⁠פְנָֽ⁠י׃","wĕ⁠ʼarĕbá̇ʻi֥ym bá̇⁠ʼamá֖̇h háyá֣h ha⁠bá֑̇yiţ h֖ẇʼ ha⁠héyká֥l li⁠pĕnáֽ⁠y׃"],[6,18,"וְ⁠אֶ֤רֶז אֶל־הַ⁠בַּ֨יִת֙ פְּנִ֔ימָה מִקְלַ֣עַת פְּקָעִ֔ים וּ⁠פְטוּרֵ֖י צִצִּ֑ים הַ⁠כֹּ֣ל אֶ֔רֶז אֵ֥ין אֶ֖בֶן נִרְאָֽה׃","wĕ⁠ʼe֤rez ʼel-ha⁠bȧ֨yiţ֙ pĕ̇ni֔ymáh miqĕla֣ʻaţ pĕ̇qáʻi֔ym ẇ⁠pĕtẇré֖y ẕiẕi֑̇ym ha⁠kò֣̇l ʼe֔rez ʼé֥yn ʼe֖ben nirĕʼáֽh׃"],[6,19,"וּ⁠דְבִ֧יר בְּ⁠תוֹךְ־הַ⁠בַּ֛יִת מִ⁠פְּנִ֖ימָה הֵכִ֑ין לְ⁠תִתֵּ֣ן שָׁ֔ם אֶת־אֲר֖וֹן בְּרִ֥ית יְהוָֽה׃","ẇ⁠dĕbi֧yr bĕ̇⁠ţwòkĕ-ha⁠bȧ֛yiţ mi⁠pĕ̇ni֖ymáh héki֑yn lĕ⁠ţiţé֣̇n şá̌֔m ʼeţ-ʼàr֖wòn bĕ̇ri֥yţ yĕhwáֽh׃"],[6,20,"וְ⁠לִ⁠פְנֵ֣י הַ⁠דְּבִ֡יר עֶשְׂרִים֩ אַמָּ֨ה אֹ֜רֶךְ וְ⁠עֶשְׂרִ֧ים אַמָּ֣ה רֹ֗חַב וְ⁠עֶשְׂרִ֤ים אַמָּה֙ קֽוֹמָת֔⁠וֹ וַ⁠יְצַפֵּ֖⁠הוּ זָהָ֣ב סָג֑וּר וַ⁠יְצַ֥ף מִזְבֵּ֖חַ אָֽרֶז׃","wĕ⁠li⁠pĕné֣y ha⁠dĕ̇bi֡yr ʻeşĕ̂riym֩ ʼamá̇֨h ʼò֜rekĕ wĕ⁠ʻeşĕ̂ri֧ym ʼamá֣̇h rò֗ẖab wĕ⁠ʻeşĕ̂ri֤ym ʼamá̇h֙ qֽwòmáţ֔⁠wò wa⁠yĕẕapé֖̇⁠hẇ záhá֣b ság֑ẇr wa⁠yĕẕa֥p mizĕbé֖̇ẖa ʼáֽrez׃"],[6,21,"וַ⁠יְצַ֨ף שְׁלֹמֹ֧ה אֶת־הַ⁠בַּ֛יִת מִ⁠פְּנִ֖ימָה זָהָ֣ב סָג֑וּר וַ⁠יְעַבֵּ֞ר ב⁠רתיקות זָהָב֙ לִ⁠פְנֵ֣י הַ⁠דְּבִ֔יר וַ⁠יְצַפֵּ֖⁠הוּ זָהָֽב׃","wa⁠yĕẕa֨p şĕ̌lòmò֧h ʼeţ-ha⁠bȧ֛yiţ mi⁠pĕ̇ni֖ymáh záhá֣b ság֑ẇr wa⁠yĕʻabé̇֞r b⁠rţyqwţ záháb֙ li⁠pĕné֣y ha⁠dĕ̇bi֔yr wa⁠yĕẕapé֖̇⁠hẇ záháֽb׃"],[6,22,"וְ⁠אֶת־כָּל־הַ⁠בַּ֛יִת צִפָּ֥ה זָהָ֖ב עַד־תֹּ֣ם כָּל־הַ⁠בָּ֑יִת וְ⁠כָל־הַ⁠מִּזְבֵּ֥חַ אֲֽשֶׁר־לַ⁠דְּבִ֖יר צִפָּ֥ה זָהָֽב׃","wĕ⁠ʼeţ-ká̇l-ha⁠bȧ֛yiţ ẕipá֥̇h záhá֖b ʻad-ţò֣̇m ká̇l-ha⁠bá֑̇yiţ wĕ⁠kál-ha⁠mi̇zĕbé֥̇ẖa ʼàֽşěr-la⁠dĕ̇bi֖yr ẕipá֥̇h záháֽb׃"],[6,23,"וַ⁠יַּ֣עַשׂ בַּ⁠דְּבִ֔יר שְׁנֵ֥י כְרוּבִ֖ים עֲצֵי־שָׁ֑מֶן עֶ֥שֶׂר אַמּ֖וֹת קוֹמָתֽ⁠וֹ׃","wa⁠yȧ֣ʻaş̂ bȧ⁠dĕ̇bi֔yr şĕ̌né֥y kĕrẇbi֖ym ʻàẕéy-şá֑̌men ʻe֥şêr ʼaṁ֖wòţ qwòmáţֽ⁠wò׃"],[6,24,"וְ⁠חָמֵ֣שׁ אַמּ֗וֹת כְּנַ֤ף הַ⁠כְּרוּב֙ הָֽ⁠אֶחָ֔ת וְ⁠חָמֵ֣שׁ אַמּ֔וֹת כְּנַ֥ף הַ⁠כְּר֖וּב הַ⁠שֵּׁנִ֑ית עֶ֣שֶׂר אַמּ֔וֹת מִ⁠קְצ֥וֹת כְּנָפָ֖י⁠ו וְ⁠עַד־קְצ֥וֹת כְּנָפָֽי⁠ו׃","wĕ⁠ẖámé֣ş̌ ʼaṁ֗wòţ kĕ̇na֤p ha⁠kĕ̇rẇb֙ háֽ⁠ʼeẖá֔ţ wĕ⁠ẖámé֣ş̌ ʼaṁ֔wòţ kĕ̇na֥p ha⁠kĕ̇r֖ẇb ha⁠şé̇̌ni֑yţ ʻe֣şêr ʼaṁ֔wòţ mi⁠qĕẕ֥wòţ kĕ̇nápá֖y⁠w wĕ⁠ʻad-qĕẕ֥wòţ kĕ̇nápáֽy⁠w׃"],[6,25,"וְ⁠עֶ֨שֶׂר֙ בָּֽ⁠אַמָּ֔ה הַ⁠כְּר֖וּב הַ⁠שֵּׁנִ֑י מִדָּ֥ה אַחַ֛ת וְ⁠קֶ֥צֶב אֶחָ֖ד לִ⁠שְׁנֵ֥י הַ⁠כְּרֻבִֽים׃","wĕ⁠ʻe֨şêr֙ báֽ̇⁠ʼamá̇֔h ha⁠kĕ̇r֖ẇb ha⁠şé̇̌ni֑y midá֥̇h ʼaẖa֛ţ wĕ⁠qe֥ẕeb ʼeẖá֖d li⁠şĕ̌né֥y ha⁠kĕ̇rubiֽym׃"],[6,26,"קוֹמַת֙ הַ⁠כְּר֣וּב הָֽ⁠אֶחָ֔ד עֶ֖שֶׂר בָּֽ⁠אַמָּ֑ה וְ⁠כֵ֖ן הַ⁠כְּר֥וּב הַ⁠שֵּׁנִֽי׃","qwòmaţ֙ ha⁠kĕ̇r֣ẇb háֽ⁠ʼeẖá֔d ʻe֖şêr báֽ̇⁠ʼamá֑̇h wĕ⁠ké֖n ha⁠kĕ̇r֥ẇb ha⁠şé̇̌niֽy׃"],[6,27,"וַ⁠יִּתֵּ֨ן אֶת־הַ⁠כְּרוּבִ֜ים בְּ⁠ת֣וֹךְ ׀ הַ⁠בַּ֣יִת הַ⁠פְּנִימִ֗י וַֽ⁠יִּפְרְשׂוּ֮ אֶת־כַּנְפֵ֣י הַ⁠כְּרֻבִים֒ וַ⁠תִּגַּ֤ע כְּנַף־הָֽ⁠אֶחָד֙ בַּ⁠קִּ֔יר וּ⁠כְנַף֙ הַ⁠כְּר֣וּב הַ⁠שֵּׁנִ֔י נֹגַ֖עַת בַּ⁠קִּ֣יר הַ⁠שֵּׁנִ֑י וְ⁠כַנְפֵי⁠הֶם֙ אֶל־תּ֣וֹךְ הַ⁠בַּ֔יִת נֹגְעֹ֖ת כָּנָ֥ף אֶל־כָּנָֽף׃","wa⁠yi̇ţé̇֨n ʼeţ-ha⁠kĕ̇rẇbi֜ym bĕ̇⁠ţ֣wòkĕ ׀ ha⁠bȧ֣yiţ ha⁠pĕ̇niymi֗y waֽ⁠yi̇pĕrĕş̂ẇ֮ ʼeţ-kȧnĕpé֣y ha⁠kĕ̇rubiym֒ wa⁠ţi̇gȧ֤ʻ kĕ̇nap-háֽ⁠ʼeẖád֙ bȧ⁠qi̇֔yr ẇ⁠kĕnap֙ ha⁠kĕ̇r֣ẇb ha⁠şé̇̌ni֔y nòga֖ʻaţ bȧ⁠qi֣̇yr ha⁠şé̇̌ni֑y wĕ⁠kanĕpéy⁠hem֙ ʼel-ţ֣̇wòkĕ ha⁠bȧ֔yiţ nògĕʻò֖ţ ká̇ná֥p ʼel-ká̇náֽp׃"],[6,28,"וַ⁠יְצַ֥ף אֶת־הַ⁠כְּרוּבִ֖ים זָהָֽב׃","wa⁠yĕẕa֥p ʼeţ-ha⁠kĕ̇rẇbi֖ym záháֽb׃"],[6,29,"וְ⁠אֵת֩ כָּל־קִיר֨וֹת הַ⁠בַּ֜יִת מֵסַ֣ב ׀ קָלַ֗ע פִּתּוּחֵי֙ מִקְלְעוֹת֙ כְּרוּבִ֣ים וְ⁠תִֽמֹרֹ֔ת וּ⁠פְטוּרֵ֖י צִצִּ֑ים מִ⁠לִּ⁠פְנִ֖ים וְ⁠לַ⁠חִיצֽוֹן׃","wĕ⁠ʼéţ֩ ká̇l-qiyr֨wòţ ha⁠bȧ֜yiţ mésa֣b ׀ qála֗ʻ pi̇ţ̇ẇẖéy֙ miqĕlĕʻwòţ֙ kĕ̇rẇbi֣ym wĕ⁠ţiֽmòrò֔ţ ẇ⁠pĕtẇré֖y ẕiẕi֑̇ym mi⁠li̇⁠pĕni֖ym wĕ⁠la⁠ẖiyẕֽwòn׃"],[6,30,"וְ⁠אֶת־קַרְקַ֥ע הַ⁠בַּ֖יִת צִפָּ֣ה זָהָ֑ב לִ⁠פְנִ֖ימָה וְ⁠לַ⁠חִיצֽוֹן׃","wĕ⁠ʼeţ-qarĕqa֥ʻ ha⁠bȧ֖yiţ ẕipá֣̇h záhá֑b li⁠pĕni֖ymáh wĕ⁠la⁠ẖiyẕֽwòn׃"],[6,31,"וְ⁠אֵת֙ פֶּ֣תַח הַ⁠דְּבִ֔יר עָשָׂ֖ה דַּלְת֣וֹת עֲצֵי־שָׁ֑מֶן הָ⁠אַ֥יִל מְזוּז֖וֹת חֲמִשִֽׁית׃","wĕ⁠ʼéţ֙ pė֣ţaẖ ha⁠dĕ̇bi֔yr ʻáşá֖̂h dȧlĕţ֣wòţ ʻàẕéy-şá֑̌men há⁠ʼa֥yil mĕzẇz֖wòţ ẖàmişǐֽyţ׃"],[6,32,"וּ⁠שְׁתֵּי֮ דַּלְת֣וֹת עֲצֵי־שֶׁמֶן֒ וְ⁠קָלַ֣ע עֲ֠לֵי⁠הֶם מִקְלְע֨וֹת כְּרוּבִ֧ים וְ⁠תִמֹר֛וֹת וּ⁠פְטוּרֵ֥י צִצִּ֖ים וְ⁠צִפָּ֣ה זָהָ֑ב וַ⁠יָּ֛רֶד עַל־הַ⁠כְּרוּבִ֥ים וְ⁠עַל־הַ⁠תִּֽמֹר֖וֹת אֶת־הַ⁠זָּהָֽב׃","ẇ⁠şĕ̌ţé̇y֮ dȧlĕţ֣wòţ ʻàẕéy-şěmen֒ wĕ⁠qála֣ʻ ʻà֠léy⁠hem miqĕlĕʻ֨wòţ kĕ̇rẇbi֧ym wĕ⁠ţimòr֛wòţ ẇ⁠pĕtẇré֥y ẕiẕi֖̇ym wĕ⁠ẕipá֣̇h záhá֑b wa⁠yá֛̇red ʻal-ha⁠kĕ̇rẇbi֥ym wĕ⁠ʻal-ha⁠ţiֽ̇mòr֖wòţ ʼeţ-ha⁠zá̇háֽb׃"],[6,33,"וְ⁠כֵ֥ן עָשָׂ֛ה לְ⁠פֶ֥תַח הַֽ⁠הֵיכָ֖ל מְזוּז֣וֹת עֲצֵי־שָׁ֑מֶן מֵ⁠אֵ֖ת רְבִעִֽית׃","wĕ⁠ké֥n ʻáşá֛̂h lĕ⁠pe֥ţaẖ haֽ⁠héyká֖l mĕzẇz֣wòţ ʻàẕéy-şá֑̌men mé⁠ʼé֖ţ rĕbiʻiֽyţ׃"],[6,34,"וּ⁠שְׁתֵּ֥י דַלְת֖וֹת עֲצֵ֣י בְרוֹשִׁ֑ים שְׁנֵ֨י צְלָעִ֜ים הַ⁠דֶּ֤לֶת הָֽ⁠אַחַת֙ גְּלִילִ֔ים וּ⁠שְׁנֵ֧י קְלָעִ֛ים הַ⁠דֶּ֥לֶת הַ⁠שֵּׁנִ֖ית גְּלִילִֽים׃","ẇ⁠şĕ̌ţé֥̇y dalĕţ֖wòţ ʻàẕé֣y bĕrwòşǐ֑ym şĕ̌né֨y ẕĕláʻi֜ym ha⁠dė֤leţ háֽ⁠ʼaẖaţ֙ gĕ̇liyli֔ym ẇ⁠şĕ̌né֧y qĕláʻi֛ym ha⁠dė֥leţ ha⁠şé̇̌ni֖yţ gĕ̇liyliֽym׃"],[6,35,"וְ⁠קָלַ֤ע כְּרוּבִים֙ וְ⁠תִ֣מֹר֔וֹת וּ⁠פְטֻרֵ֖י צִצִּ֑ים וְ⁠צִפָּ֣ה זָהָ֔ב מְיֻשָּׁ֖ר עַל־הַ⁠מְּחֻקֶּֽה׃","wĕ⁠qála֤ʻ kĕ̇rẇbiym֙ wĕ⁠ţi֣mòr֔wòţ ẇ⁠pĕturé֖y ẕiẕi֑̇ym wĕ⁠ẕipá֣̇h záhá֔b mĕyuşá֖̇̌r ʻal-ha⁠mĕ̇ẖuqėֽh׃"],[6,36,"וַ⁠יִּ֨בֶן֙ אֶת־הֶ⁠חָצֵ֣ר הַ⁠פְּנִימִ֔ית שְׁלֹשָׁ֖ה טוּרֵ֣י גָזִ֑ית וְ⁠ט֖וּר כְּרֻתֹ֥ת אֲרָזִֽים׃","wa⁠yi̇֨ben֙ ʼeţ-he⁠ẖáẕé֣r ha⁠pĕ̇niymi֔yţ şĕ̌lòşá֖̌h tẇré֣y gázi֑yţ wĕ⁠t֖ẇr kĕ̇ruţò֥ţ ʼàráziֽym׃"],[6,37,"בַּ⁠שָּׁנָה֙ הָֽ⁠רְבִיעִ֔ית יֻסַּ֖ד בֵּ֣ית יְהוָ֑ה בְּ⁠יֶ֖רַח זִֽו׃","bȧ⁠şá̇̌náh֙ háֽ⁠rĕbiyʻi֔yţ yusȧ֖d bé֣̇yţ yĕhwá֑h bĕ̇⁠ye֖raẖ ziֽw׃"],[6,38,"וּ⁠בַ⁠שָּׁנָה֩ הָ⁠אַחַ֨ת עֶשְׂרֵ֜ה בְּ⁠יֶ֣רַח בּ֗וּל ה֚וּא הַ⁠חֹ֣דֶשׁ הַ⁠שְּׁמִינִ֔י כָּלָ֣ה הַ⁠בַּ֔יִת לְ⁠כָל־דְּבָרָ֖י⁠ו וּ⁠לְ⁠כָל־משפט⁠ו וַ⁠יִּבְנֵ֖⁠הוּ שֶׁ֥בַע שָׁנִֽים׃","ẇ⁠ba⁠şá̇̌náh֩ há⁠ʼaẖa֨ţ ʻeşĕ̂ré֜h bĕ̇⁠ye֣raẖ ḃ֗ẇl h֚ẇʼ ha⁠ẖò֣deş̌ ha⁠şĕ̇̌miyni֔y ká̇lá֣h ha⁠bȧ֔yiţ lĕ⁠kál-dĕ̇bárá֖y⁠w ẇ⁠lĕ⁠kál-mşpt⁠w wa⁠yi̇bĕné֖⁠hẇ şě֥baʻ şá̌niֽym׃"],[7,1,"וְ⁠אֶת־בֵּית⁠וֹ֙ בָּנָ֣ה שְׁלֹמֹ֔ה שְׁלֹ֥שׁ עֶשְׂרֵ֖ה שָׁנָ֑ה וַ⁠יְכַ֖ל אֶת־כָּל־בֵּיתֽ⁠וֹ׃","wĕ⁠ʼeţ-bé̇yţ⁠wò֙ bá̇ná֣h şĕ̌lòmò֔h şĕ̌lò֥ş̌ ʻeşĕ̂ré֖h şá̌ná֑h wa⁠yĕka֖l ʼeţ-ká̇l-bé̇yţֽ⁠wò׃"],[7,2,"וַ⁠יִּ֜בֶן אֶת־בֵּ֣ית ׀ יַ֣עַר הַ⁠לְּבָנ֗וֹן מֵאָ֨ה אַמָּ֤ה אָרְכּ⁠וֹ֙ וַ⁠חֲמִשִּׁ֤ים אַמָּה֙ רָחְבּ֔⁠וֹ וּ⁠שְׁלֹשִׁ֥ים אַמָּ֖ה קוֹמָת֑⁠וֹ עַ֗ל אַרְבָּעָה֙ טוּרֵי֙ עַמּוּדֵ֣י אֲרָזִ֔ים וּ⁠כְרֻת֥וֹת אֲרָזִ֖ים עַל־הָ⁠עַמּוּדִֽים׃","wa⁠yi̇֜ben ʼeţ-bé֣̇yţ ׀ ya֣ʻar ha⁠lĕ̇bán֗wòn méʼá֨h ʼamá֤̇h ʼárĕk̇⁠wò֙ wa⁠ẖàmişi֤̇̌ym ʼamá̇h֙ ráẖĕḃ֔⁠wò ẇ⁠şĕ̌lòşǐ֥ym ʼamá֖̇h qwòmáţ֑⁠wò ʻa֗l ʼarĕbá̇ʻáh֙ tẇréy֙ ʻaṁẇdé֣y ʼàrázi֔ym ẇ⁠kĕruţ֥wòţ ʼàrázi֖ym ʻal-há⁠ʻaṁẇdiֽym׃"],[7,3,"וְ⁠סָפֻ֣ן בָּ⁠אֶ֗רֶז מִ⁠מַּ֨עַל֙ עַל־הַ⁠צְּלָעֹת֙ אֲשֶׁ֣ר עַל־הָֽ⁠עַמּוּדִ֔ים אַרְבָּעִ֖ים וַ⁠חֲמִשָּׁ֑ה חֲמִשָּׁ֥ה עָשָׂ֖ר הַ⁠טּֽוּר׃","wĕ⁠sápu֣n bá̇⁠ʼe֗rez mi⁠mȧ֨ʻal֙ ʻal-ha⁠ẕĕ̇láʻòţ֙ ʼàşě֣r ʻal-háֽ⁠ʻaṁẇdi֔ym ʼarĕbá̇ʻi֖ym wa⁠ẖàmişá֑̇̌h ẖàmişá֥̇̌h ʻáşá֖̂r ha⁠ṫֽẇr׃"],[7,4,"וּ⁠שְׁקֻפִ֖ים שְׁלֹשָׁ֣ה טוּרִ֑ים וּ⁠מֶחֱזָ֥ה אֶל־מֶחֱזָ֖ה שָׁלֹ֥שׁ פְּעָמִֽים׃","ẇ⁠şĕ̌qupi֖ym şĕ̌lòşá֣̌h tẇri֑ym ẇ⁠meẖèzá֥h ʼel-meẖèzá֖h şá̌lò֥ş̌ pĕ̇ʻámiֽym׃"],[7,5,"וְ⁠כָל־הַ⁠פְּתָחִ֥ים וְ⁠הַ⁠מְּזוּז֖וֹת רְבֻעִ֣ים שָׁ֑קֶף וּ⁠מ֧וּל מֶחֱזָ֛ה אֶל־מֶחֱזָ֖ה שָׁלֹ֥שׁ פְּעָמִֽים׃","wĕ⁠kál-ha⁠pĕ̇ţáẖi֥ym wĕ⁠ha⁠mĕ̇zẇz֖wòţ rĕbuʻi֣ym şá֑̌qep ẇ⁠m֧ẇl meẖèzá֛h ʼel-meẖèzá֖h şá̌lò֥ş̌ pĕ̇ʻámiֽym׃"],[7,6,"וְ⁠אֵ֨ת אוּלָ֤ם הָֽ⁠עַמּוּדִים֙ עָשָׂ֔ה חֲמִשִּׁ֤ים אַמָּה֙ אָרְכּ֔⁠וֹ וּ⁠שְׁלֹשִׁ֥ים אַמָּ֖ה רָחְבּ֑⁠וֹ וְ⁠אוּלָם֙ עַל־פְּנֵי⁠הֶ֔ם וְ⁠עַמֻּדִ֥ים וְ⁠עָ֖ב עַל־פְּנֵי⁠הֶֽם׃","wĕ⁠ʼé֨ţ ʼẇlá֤m háֽ⁠ʻaṁẇdiym֙ ʻáşá̂֔h ẖàmişi֤̇̌ym ʼamá̇h֙ ʼárĕk̇֔⁠wò ẇ⁠şĕ̌lòşǐ֥ym ʼamá֖̇h ráẖĕḃ֑⁠wò wĕ⁠ʼẇlám֙ ʻal-pĕ̇néy⁠he֔m wĕ⁠ʻamu̇di֥ym wĕ⁠ʻá֖b ʻal-pĕ̇néy⁠heֽm׃"],[7,7,"וְ⁠אוּלָ֤ם הַ⁠כִּסֵּא֙ אֲשֶׁ֣ר יִשְׁפָּט־שָׁ֔ם אֻלָ֥ם הַ⁠מִּשְׁפָּ֖ט עָשָׂ֑ה וְ⁠סָפ֣וּן בָּ⁠אֶ֔רֶז מֵ⁠הַ⁠קַּרְקַ֖ע עַד־הַ⁠קַּרְקָֽע׃","wĕ⁠ʼẇlá֤m ha⁠ki̇sé̇ʼ֙ ʼàşě֣r yişĕ̌pá̇t-şá̌֔m ʼulá֥m ha⁠mi̇şĕ̌pá֖̇t ʻáşá֑̂h wĕ⁠sáp֣ẇn bá̇⁠ʼe֔rez mé⁠ha⁠qȧrĕqa֖ʻ ʻad-ha⁠qȧrĕqáֽʻ׃"],[7,8,"וּ⁠בֵית⁠וֹ֩ אֲשֶׁר־יֵ֨שֶׁב שָׁ֜ם חָצֵ֣ר הָ⁠אַחֶ֗רֶת מִ⁠בֵּית֙ לָֽ⁠אוּלָ֔ם כַּ⁠מַּֽעֲשֶׂ֥ה הַ⁠זֶּ֖ה הָיָ֑ה וּ⁠בַ֜יִת יַעֲשֶׂ֤ה לְ⁠בַת־פַּרְעֹה֙ אֲשֶׁ֣ר לָקַ֣ח שְׁלֹמֹ֔ה כָּ⁠אוּלָ֖ם הַ⁠זֶּֽה׃","ẇ⁠béyţ⁠wò֩ ʼàşěr-yé֨şěb şá̌֜m ẖáẕé֣r há⁠ʼaẖe֗reţ mi⁠bé̇yţ֙ láֽ⁠ʼẇlá֔m kȧ⁠mȧֽʻàşê֥h ha⁠zė֖h háyá֑h ẇ⁠ba֜yiţ yaʻàşê֤h lĕ⁠baţ-pȧrĕʻòh֙ ʼàşě֣r láqa֣ẖ şĕ̌lòmò֔h ká̇⁠ʼẇlá֖m ha⁠zėֽh׃"],[7,9,"כָּל־אֵ֜לֶּה אֲבָנִ֤ים יְקָרֹת֙ כְּ⁠מִדֹּ֣ת גָּזִ֔ית מְגֹרָר֥וֹת בַּ⁠מְּגֵרָ֖ה מִ⁠בַּ֣יִת וּ⁠מִ⁠ח֑וּץ וּ⁠מִ⁠מַּסָּד֙ עַד־הַ⁠טְּפָח֔וֹת וּ⁠מִ⁠ח֖וּץ עַד־הֶ⁠חָצֵ֥ר הַ⁠גְּדוֹלָֽה׃","ká̇l-ʼé֜lėh ʼàbáni֤ym yĕqáròţ֙ kĕ̇⁠midò֣̇ţ gá̇zi֔yţ mĕgòrár֥wòţ bȧ⁠mĕ̇gérá֖h mi⁠bȧ֣yiţ ẇ⁠mi⁠ẖ֑ẇẕ ẇ⁠mi⁠mȧsá̇d֙ ʻad-ha⁠tĕ̇páẖ֔wòţ ẇ⁠mi⁠ẖ֖ẇẕ ʻad-he⁠ẖáẕé֥r ha⁠gĕ̇dwòláֽh׃"],[7,10,"וּ⁠מְיֻסָּ֕ד אֲבָנִ֥ים יְקָר֖וֹת אֲבָנִ֣ים גְּדֹל֑וֹת אַבְנֵי֙ עֶ֣שֶׂר אַמּ֔וֹת וְ⁠אַבְנֵ֖י שְׁמֹנֶ֥ה אַמּֽוֹת׃","ẇ⁠mĕyusá̇֕d ʼàbáni֥ym yĕqár֖wòţ ʼàbáni֣ym gĕ̇dòl֑wòţ ʼabĕnéy֙ ʻe֣şêr ʼaṁ֔wòţ wĕ⁠ʼabĕné֖y şĕ̌mòne֥h ʼaṁֽwòţ׃"],[7,11,"וּ⁠מִ⁠לְ⁠מַ֗עְלָ⁠ה אֲבָנִ֧ים יְקָר֛וֹת כְּ⁠מִדּ֥וֹת גָּזִ֖ית וָ⁠אָֽרֶז׃","ẇ⁠mi⁠lĕ⁠ma֗ʻĕlá⁠h ʼàbáni֧ym yĕqár֛wòţ kĕ̇⁠miḋ֥wòţ gá̇zi֖yţ wá⁠ʼáֽrez׃"],[7,12,"וְ⁠חָצֵ֨ר הַ⁠גְּדוֹלָ֜ה סָבִ֗יב שְׁלֹשָׁה֙ טוּרִ֣ים גָּזִ֔ית וְ⁠ט֖וּר כְּרֻתֹ֣ת אֲרָזִ֑ים וְ⁠לַ⁠חֲצַ֧ר בֵּית־יְהוָ֛ה הַ⁠פְּנִימִ֖ית וּ⁠לְ⁠אֻלָ֥ם הַ⁠בָּֽיִת׃פ","wĕ⁠ẖáẕé֨r ha⁠gĕ̇dwòlá֜h sábi֗yb şĕ̌lòşá̌h֙ tẇri֣ym gá̇zi֔yţ wĕ⁠t֖ẇr kĕ̇ruţò֣ţ ʼàrázi֑ym wĕ⁠la⁠ẖàẕa֧r bé̇yţ-yĕhwá֛h ha⁠pĕ̇niymi֖yţ ẇ⁠lĕ⁠ʼulá֥m ha⁠báֽ̇yiţ׃p"],[7,13,"וַ⁠יִּשְׁלַח֙ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה וַ⁠יִּקַּ֥ח אֶת־חִירָ֖ם מִ⁠צֹּֽר׃","wa⁠yi̇şĕ̌laẖ֙ ha⁠mė֣lekĕ şĕ̌lòmò֔h wa⁠yi̇qȧ֥ẖ ʼeţ-ẖiyrá֖m mi⁠ẕòֽ̇r׃"],[7,14,"בֶּן־אִשָּׁה֩ אַלְמָנָ֨ה ה֜וּא מִ⁠מַּטֵּ֣ה נַפְתָּלִ֗י וְ⁠אָבִ֣י⁠ו אִישׁ־צֹרִי֮ חֹרֵ֣שׁ נְחֹשֶׁת֒ וַ֠⁠יִּמָּלֵא אֶת־הַ⁠חָכְמָ֤ה וְ⁠אֶת־הַ⁠תְּבוּנָה֙ וְ⁠אֶת־הַ⁠דַּ֔עַת לַ⁠עֲשׂ֥וֹת כָּל־מְלָאכָ֖ה בַּ⁠נְּחֹ֑שֶׁת וַ⁠יָּבוֹא֙ אֶל־הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה וַ⁠יַּ֖עַשׂ אֶת־כָּל־מְלַאכְתּֽ⁠וֹ׃","bėn-ʼişá̇̌h֩ ʼalĕmáná֨h h֜ẇʼ mi⁠mȧté֣̇h napĕţá̇li֗y wĕ⁠ʼábi֣y⁠w ʼiyş̌-ẕòriy֮ ẖòré֣ş̌ nĕẖòşěţ֒ wa֠⁠yi̇má̇léʼ ʼeţ-ha⁠ẖákĕmá֤h wĕ⁠ʼeţ-ha⁠ţĕ̇bẇnáh֙ wĕ⁠ʼeţ-ha⁠dȧ֔ʻaţ la⁠ʻàş֥̂wòţ ká̇l-mĕláʼká֖h bȧ⁠nĕ̇ẖò֑şěţ wa⁠yá̇bwòʼ֙ ʼel-ha⁠mė֣lekĕ şĕ̌lòmò֔h wa⁠yȧ֖ʻaş̂ ʼeţ-ká̇l-mĕlaʼkĕţֽ̇⁠wò׃"],[7,15,"וַ⁠יָּ֛צַר אֶת־שְׁנֵ֥י הָ⁠עַמּוּדִ֖ים נְחֹ֑שֶׁת שְׁמֹנֶ֨ה עֶשְׂרֵ֜ה אַמָּ֗ה קוֹמַת֙ הָ⁠עַמּ֣וּד הָ⁠אֶחָ֔ד וְ⁠חוּט֙ שְׁתֵּים־עֶשְׂרֵ֣ה אַמָּ֔ה יָסֹ֖ב אֶת־הָ⁠עַמּ֥וּד הַ⁠שֵּׁנִֽי׃","wa⁠yá֛̇ẕar ʼeţ-şĕ̌né֥y há⁠ʻaṁẇdi֖ym nĕẖò֑şěţ şĕ̌mòne֨h ʻeşĕ̂ré֜h ʼamá̇֗h qwòmaţ֙ há⁠ʻaṁ֣ẇd há⁠ʼeẖá֔d wĕ⁠ẖẇt֙ şĕ̌ţé̇ym-ʻeşĕ̂ré֣h ʼamá̇֔h yásò֖b ʼeţ-há⁠ʻaṁ֥ẇd ha⁠şé̇̌niֽy׃"],[7,16,"וּ⁠שְׁתֵּ֨י כֹתָרֹ֜ת עָשָׂ֗ה לָ⁠תֵ֛ת עַל־רָאשֵׁ֥י הָֽ⁠עַמּוּדִ֖ים מֻצַ֣ק נְחֹ֑שֶׁת חָמֵ֣שׁ אַמּ֗וֹת קוֹמַת֙ הַ⁠כֹּתֶ֣רֶת הָ⁠אֶחָ֔ת וְ⁠חָמֵ֣שׁ אַמּ֔וֹת קוֹמַ֖ת הַ⁠כֹּתֶ֥רֶת הַ⁠שֵּׁנִֽית׃","ẇ⁠şĕ̌ţé̇֨y kòţárò֜ţ ʻáşá̂֗h lá⁠ţé֛ţ ʻal-ráʼşé֥̌y háֽ⁠ʻaṁẇdi֖ym muẕa֣q nĕẖò֑şěţ ẖámé֣ş̌ ʼaṁ֗wòţ qwòmaţ֙ ha⁠kò̇ţe֣reţ há⁠ʼeẖá֔ţ wĕ⁠ẖámé֣ş̌ ʼaṁ֔wòţ qwòma֖ţ ha⁠kò̇ţe֥reţ ha⁠şé̇̌niֽyţ׃"],[7,17,"שְׂבָכִ֞ים מַעֲשֵׂ֣ה שְׂבָכָ֗ה גְּדִלִים֙ מַעֲשֵׂ֣ה שַׁרְשְׁר֔וֹת לַ⁠כֹּ֣תָרֹ֔ת אֲשֶׁ֖ר עַל־רֹ֣אשׁ הָ⁠עַמּוּדִ֑ים שִׁבְעָה֙ לַ⁠כֹּתֶ֣רֶת הָ⁠אֶחָ֔ת וְ⁠שִׁבְעָ֖ה לַ⁠כֹּתֶ֥רֶת הַ⁠שֵּׁנִֽית׃","şĕ̂báki֞ym maʻàşé֣̂h şĕ̂báká֗h gĕ̇diliym֙ maʻàşé֣̂h şǎrĕşĕ̌r֔wòţ la⁠kò֣̇ţárò֔ţ ʼàşě֖r ʻal-rò֣ʼş̌ há⁠ʻaṁẇdi֑ym şǐbĕʻáh֙ la⁠kò̇ţe֣reţ há⁠ʼeẖá֔ţ wĕ⁠şǐbĕʻá֖h la⁠kò̇ţe֥reţ ha⁠şé̇̌niֽyţ׃"],[7,18,"וַ⁠יַּ֖עַשׂ אֶת־הָ⁠עַמּוּדִ֑ים וּ⁠שְׁנֵי֩ טוּרִ֨ים סָבִ֜יב עַל־הַ⁠שְּׂבָכָ֣ה הָ⁠אֶחָ֗ת לְ⁠כַסּ֤וֹת אֶת־הַ⁠כֹּֽתָרֹת֙ אֲשֶׁר֙ עַל־רֹ֣אשׁ הָֽ⁠רִמֹּנִ֔ים וְ⁠כֵ֣ן עָשָׂ֔ה לַ⁠כֹּתֶ֖רֶת הַ⁠שֵּׁנִֽית׃","wa⁠yȧ֖ʻaş̂ ʼeţ-há⁠ʻaṁẇdi֑ym ẇ⁠şĕ̌néy֩ tẇri֨ym sábi֜yb ʻal-ha⁠şĕ̇̂báká֣h há⁠ʼeẖá֗ţ lĕ⁠kaṡ֤wòţ ʼeţ-ha⁠kòֽ̇ţáròţ֙ ʼàşěr֙ ʻal-rò֣ʼş̌ háֽ⁠rimò̇ni֔ym wĕ⁠ké֣n ʻáşá̂֔h la⁠kò̇ţe֖reţ ha⁠şé̇̌niֽyţ׃"],[7,19,"וְ⁠כֹֽתָרֹ֗ת אֲשֶׁר֙ עַל־רֹ֣אשׁ הָ⁠עַמּוּדִ֔ים מַעֲשֵׂ֖ה שׁוּשַׁ֣ן בָּֽ⁠אוּלָ֑ם אַרְבַּ֖ע אַמּֽוֹת׃","wĕ⁠kòֽţárò֗ţ ʼàşěr֙ ʻal-rò֣ʼş̌ há⁠ʻaṁẇdi֔ym maʻàşé֖̂h ş̌ẇşǎ֣n báֽ̇⁠ʼẇlá֑m ʼarĕbȧ֖ʻ ʼaṁֽwòţ׃"],[7,20,"וְ⁠כֹתָרֹ֗ת עַל־שְׁנֵי֙ הָֽ⁠עַמּוּדִ֔ים גַּם־מִ⁠מַּ֨עַל֙ מִ⁠לְּ⁠עֻמַּ֣ת הַ⁠בֶּ֔טֶן אֲשֶׁ֖ר לְ⁠עֵ֣בֶר שבכה וְ⁠הָ⁠רִמּוֹנִ֤ים מָאתַ֨יִם֙ טֻרִ֣ים סָבִ֔יב עַ֖ל הַ⁠כֹּתֶ֥רֶת הַ⁠שֵּׁנִֽית׃","wĕ⁠kòţárò֗ţ ʻal-şĕ̌néy֙ háֽ⁠ʻaṁẇdi֔ym gȧm-mi⁠mȧ֨ʻal֙ mi⁠lĕ̇⁠ʻumȧ֣ţ ha⁠bė֔ten ʼàşě֖r lĕ⁠ʻé֣ber şbkh wĕ⁠há⁠riṁwòni֤ym máʼţa֨yim֙ turi֣ym sábi֔yb ʻa֖l ha⁠kò̇ţe֥reţ ha⁠şé̇̌niֽyţ׃"],[7,21,"וַ⁠יָּ֨קֶם֙ אֶת־הָֽ⁠עַמֻּדִ֔ים לְ⁠אֻלָ֖ם הַֽ⁠הֵיכָ֑ל וַ⁠יָּ֜קֶם אֶת־הָ⁠עַמּ֣וּד הַ⁠יְמָנִ֗י וַ⁠יִּקְרָ֤א אֶת־שְׁמ⁠וֹ֙ יָכִ֔ין וַ⁠יָּ֨קֶם֙ אֶת־הָ⁠עַמּ֣וּד הַ⁠שְּׂמָאלִ֔י וַ⁠יִּקְרָ֥א אֶת־שְׁמ֖⁠וֹ בֹּֽעַז׃","wa⁠yá̇֨qem֙ ʼeţ-háֽ⁠ʻamu̇di֔ym lĕ⁠ʼulá֖m haֽ⁠héyká֑l wa⁠yá̇֜qem ʼeţ-há⁠ʻaṁ֣ẇd ha⁠yĕmáni֗y wa⁠yi̇qĕrá֤ʼ ʼeţ-şĕ̌m⁠wò֙ yáki֔yn wa⁠yá̇֨qem֙ ʼeţ-há⁠ʻaṁ֣ẇd ha⁠şĕ̇̂máʼli֔y wa⁠yi̇qĕrá֥ʼ ʼeţ-şĕ̌m֖⁠wò bòֽ̇ʻaz׃"],[7,22,"וְ⁠עַ֛ל רֹ֥אשׁ הָ⁠עַמּוּדִ֖ים מַעֲשֵׂ֣ה שׁוֹשָׁ֑ן וַ⁠תִּתֹּ֖ם מְלֶ֥אכֶת הָ⁠עַמּוּדִֽים׃","wĕ⁠ʻa֛l rò֥ʼş̌ há⁠ʻaṁẇdi֖ym maʻàşé֣̂h ş̌wòşá֑̌n wa⁠ţi̇ţò֖̇m mĕle֥ʼkeţ há⁠ʻaṁẇdiֽym׃"],[7,23,"וַ⁠יַּ֥עַשׂ אֶת־הַ⁠יָּ֖ם מוּצָ֑ק עֶ֣שֶׂר בָּ֠⁠אַמָּה מִ⁠שְּׂפָת֨⁠וֹ עַד־שְׂפָת֜⁠וֹ עָגֹ֣ל ׀ סָבִ֗יב וְ⁠חָמֵ֤שׁ בָּֽ⁠אַמָּה֙ קוֹמָת֔⁠וֹ ו⁠קוה שְׁלֹשִׁ֣ים בָּֽ⁠אַמָּ֔ה יָסֹ֥ב אֹת֖⁠וֹ סָבִֽיב׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ha⁠yá֖̇m mẇẕá֑q ʻe֣şêr bá̇֠⁠ʼamá̇h mi⁠şĕ̇̂páţ֨⁠wò ʻad-şĕ̂páţ֜⁠wò ʻágò֣l ׀ sábi֗yb wĕ⁠ẖámé֤ş̌ báֽ̇⁠ʼamá̇h֙ qwòmáţ֔⁠wò w⁠qwh şĕ̌lòşǐ֣ym báֽ̇⁠ʼamá̇֔h yásò֥b ʼòţ֖⁠wò sábiֽyb׃"],[7,24,"וּ⁠פְקָעִים֩ מִ⁠תַּ֨חַת לִ⁠שְׂפָת֤⁠וֹ ׀ סָבִיב֙ סֹבְבִ֣ים אֹת֔⁠וֹ עֶ֚שֶׂר בָּֽ⁠אַמָּ֔ה מַקִּפִ֥ים אֶת־הַ⁠יָּ֖ם סָבִ֑יב שְׁנֵ֤י טוּרִים֙ הַ⁠פְּקָעִ֔ים יְצֻקִ֖ים בִּ⁠יצֻקָתֽ⁠וֹ׃","ẇ⁠pĕqáʻiym֩ mi⁠ţȧ֨ẖaţ li⁠şĕ̂páţ֤⁠wò ׀ sábiyb֙ sòbĕbi֣ym ʼòţ֔⁠wò ʻe֚şêr báֽ̇⁠ʼamá̇֔h maqi̇pi֥ym ʼeţ-ha⁠yá֖̇m sábi֑yb şĕ̌né֤y tẇriym֙ ha⁠pĕ̇qáʻi֔ym yĕẕuqi֖ym bi̇⁠yẕuqáţֽ⁠wò׃"],[7,25,"עֹמֵ֞ד עַל־שְׁנֵ֧י עָשָׂ֣ר בָּקָ֗ר שְׁלֹשָׁ֣ה פֹנִ֣ים ׀ צָפ֡וֹנָ⁠ה וּ⁠שְׁלֹשָׁה֩ פֹנִ֨ים ׀ יָ֜מָּ⁠ה וּ⁠שְׁלֹשָׁ֣ה ׀ פֹּנִ֣ים נֶ֗גְבָּ⁠ה וּ⁠שְׁלֹשָׁה֙ פֹּנִ֣ים מִזְרָ֔חָ⁠ה וְ⁠הַ⁠יָּ֥ם עֲלֵי⁠הֶ֖ם מִ⁠לְ⁠מָ֑עְלָ⁠ה וְ⁠כָל־אֲחֹֽרֵי⁠הֶ֖ם בָּֽיְתָ⁠ה׃","ʻòmé֞d ʻal-şĕ̌né֧y ʻáşá֣̂r bá̇qá֗r şĕ̌lòşá֣̌h pòni֣ym ׀ ẕáp֡wòná⁠h ẇ⁠şĕ̌lòşá̌h֩ pòni֨ym ׀ yá֜má̇⁠h ẇ⁠şĕ̌lòşá֣̌h ׀ pò̇ni֣ym ne֗gĕbá̇⁠h ẇ⁠şĕ̌lòşá̌h֙ pò̇ni֣ym mizĕrá֔ẖá⁠h wĕ⁠ha⁠yá֥̇m ʻàléy⁠he֖m mi⁠lĕ⁠má֑ʻĕlá⁠h wĕ⁠kál-ʼàẖòֽréy⁠he֖m báֽ̇yĕţá⁠h׃"],[7,26,"וְ⁠עָבְי֣⁠וֹ טֶ֔פַח וּ⁠שְׂפָת֛⁠וֹ כְּ⁠מַעֲשֵׂ֥ה שְׂפַת־כּ֖וֹס פֶּ֣רַח שׁוֹשָׁ֑ן אַלְפַּ֥יִם בַּ֖ת יָכִֽיל׃פ","wĕ⁠ʻábĕy֣⁠wò te֔paẖ ẇ⁠şĕ̂páţ֛⁠wò kĕ̇⁠maʻàşé֥̂h şĕ̂paţ-k֖̇wòs pė֣raẖ ş̌wòşá֑̌n ʼalĕpȧ֥yim bȧ֖ţ yákiֽyl׃p"],[7,27,"וַ⁠יַּ֧עַשׂ אֶת־הַ⁠מְּכֹנ֛וֹת עֶ֖שֶׂר נְחֹ֑שֶׁת אַרְבַּ֣ע בָּ⁠אַמָּ֗ה אֹ֚רֶךְ הַ⁠מְּכוֹנָ֣ה הָֽ⁠אֶחָ֔ת וְ⁠אַרְבַּ֤ע בָּֽ⁠אַמָּה֙ רָחְבָּ֔⁠הּ וְ⁠שָׁלֹ֥שׁ בָּ⁠אַמָּ֖ה קוֹמָתָֽ⁠הּ׃","wa⁠yȧ֧ʻaş̂ ʼeţ-ha⁠mĕ̇kòn֛wòţ ʻe֖şêr nĕẖò֑şěţ ʼarĕbȧ֣ʻ bá̇⁠ʼamá̇֗h ʼò֚rekĕ ha⁠mĕ̇kwòná֣h háֽ⁠ʼeẖá֔ţ wĕ⁠ʼarĕbȧ֤ʻ báֽ̇⁠ʼamá̇h֙ ráẖĕbá̇֔⁠ḣ wĕ⁠şá̌lò֥ş̌ bá̇⁠ʼamá֖̇h qwòmáţáֽ⁠ḣ׃"],[7,28,"וְ⁠זֶ֛ה מַעֲשֵׂ֥ה הַ⁠מְּכוֹנָ֖ה מִסְגְּרֹ֣ת לָ⁠הֶ֑ם וּ⁠מִסְגְּרֹ֖ת בֵּ֥ין הַ⁠שְׁלַבִּֽים׃","wĕ⁠ze֛h maʻàşé֥̂h ha⁠mĕ̇kwòná֖h misĕgĕ̇rò֣ţ lá⁠he֑m ẇ⁠misĕgĕ̇rò֖ţ bé֥̇yn ha⁠şĕ̌labiֽ̇ym׃"],[7,29,"וְ⁠עַֽל־הַ⁠מִּסְגְּר֞וֹת אֲשֶׁ֣ר ׀ בֵּ֣ין הַ⁠שְׁלַבִּ֗ים אֲרָי֤וֹת ׀ בָּקָר֙ וּ⁠כְרוּבִ֔ים וְ⁠עַל־הַ⁠שְׁלַבִּ֖ים כֵּ֣ן מִ⁠מָּ֑עַל וּ⁠מִ⁠תַּ֨חַת֙ לַ⁠אֲרָי֣וֹת וְ⁠לַ⁠בָּקָ֔ר לֹי֖וֹת מַעֲשֵׂ֥ה מוֹרָֽד׃","wĕ⁠ʻaֽl-ha⁠mi̇sĕgĕ̇r֞wòţ ʼàşě֣r ׀ bé֣̇yn ha⁠şĕ̌labi̇֗ym ʼàráy֤wòţ ׀ bá̇qár֙ ẇ⁠kĕrẇbi֔ym wĕ⁠ʻal-ha⁠şĕ̌labi֖̇ym ké֣̇n mi⁠má֑̇ʻal ẇ⁠mi⁠ţȧ֨ẖaţ֙ la⁠ʼàráy֣wòţ wĕ⁠la⁠bá̇qá֔r lòy֖wòţ maʻàşé֥̂h mwòráֽd׃"],[7,30,"וְ⁠אַרְבָּעָה֩ אוֹפַנֵּ֨י נְחֹ֜שֶׁת לַ⁠מְּכוֹנָ֤ה הָֽ⁠אַחַת֙ וְ⁠סַרְנֵ֣י נְחֹ֔שֶׁת וְ⁠אַרְבָּעָ֥ה פַעֲמֹתָ֖י⁠ו כְּתֵפֹ֣ת לָ⁠הֶ֑ם מִ⁠תַּ֤חַת לַ⁠כִּיֹּר֙ הַ⁠כְּתֵפֹ֣ת יְצֻק֔וֹת מֵ⁠עֵ֥בֶר אִ֖ישׁ לֹיֽוֹת׃","wĕ⁠ʼarĕbá̇ʻáh֩ ʼwòpané̇֨y nĕẖò֜şěţ la⁠mĕ̇kwòná֤h háֽ⁠ʼaẖaţ֙ wĕ⁠sarĕné֣y nĕẖò֔şěţ wĕ⁠ʼarĕbá̇ʻá֥h paʻàmòţá֖y⁠w kĕ̇ţépò֣ţ lá⁠he֑m mi⁠ţȧ֤ẖaţ la⁠ki̇yò̇r֙ ha⁠kĕ̇ţépò֣ţ yĕẕuq֔wòţ mé⁠ʻé֥ber ʼi֖yş̌ lòyֽwòţ׃"],[7,31,"וּ֠⁠פִי⁠הוּ מִ⁠בֵּ֨ית לַ⁠כֹּתֶ֤רֶת וָ⁠מַ֨עְלָ⁠ה֙ בָּֽ⁠אַמָּ֔ה וּ⁠פִ֨י⁠הָ֙ עָגֹ֣ל מַעֲשֵׂה־כֵ֔ן אַמָּ֖ה וַ⁠חֲצִ֣י הָֽ⁠אַמָּ֑ה וְ⁠גַם־עַל־פִּ֨י⁠הָ֙ מִקְלָע֔וֹת וּ⁠מִסְגְּרֹתֵי⁠הֶ֥ם מְרֻבָּע֖וֹת לֹ֥א עֲגֻלּֽוֹת׃","ẇ֠⁠piy⁠hẇ mi⁠bé̇֨yţ la⁠kò̇ţe֤reţ wá⁠ma֨ʻĕlá⁠h֙ báֽ̇⁠ʼamá̇֔h ẇ⁠pi֨y⁠há֙ ʻágò֣l maʻàşé̂h-ké֔n ʼamá֖̇h wa⁠ẖàẕi֣y háֽ⁠ʼamá֑̇h wĕ⁠gam-ʻal-pi̇֨y⁠há֙ miqĕláʻ֔wòţ ẇ⁠misĕgĕ̇ròţéy⁠he֥m mĕrubá̇ʻ֖wòţ lò֥ʼ ʻàgulֽ̇wòţ׃"],[7,32,"וְ⁠אַרְבַּ֣עַת הָ⁠אֽוֹפַנִּ֗ים לְ⁠מִ⁠תַּ֨חַת֙ לַֽ⁠מִּסְגְּר֔וֹת וִ⁠יד֥וֹת הָ⁠אֽוֹפַנִּ֖ים בַּ⁠מְּכוֹנָ֑ה וְ⁠קוֹמַת֙ הָ⁠אוֹפַ֣ן הָ⁠אֶחָ֔ד אַמָּ֖ה וַ⁠חֲצִ֥י הָ⁠אַמָּֽה׃","wĕ⁠ʼarĕbȧ֣ʻaţ há⁠ʼֽwòpani̇֗ym lĕ⁠mi⁠ţȧ֨ẖaţ֙ laֽ⁠mi̇sĕgĕ̇r֔wòţ wi⁠yd֥wòţ há⁠ʼֽwòpani֖̇ym bȧ⁠mĕ̇kwòná֑h wĕ⁠qwòmaţ֙ há⁠ʼwòpa֣n há⁠ʼeẖá֔d ʼamá֖̇h wa⁠ẖàẕi֥y há⁠ʼamáֽ̇h׃"],[7,33,"וּ⁠מַֽעֲשֵׂה֙ הָ⁠א֣וֹפַנִּ֔ים כְּ⁠מַעֲשֵׂ֖ה אוֹפַ֣ן הַ⁠מֶּרְכָּבָ֑ה יְדוֹתָ֣⁠ם וְ⁠גַבֵּי⁠הֶ֗ם וְ⁠חִשֻּׁקֵי⁠הֶ֛ם וְ⁠חִשֻּׁרֵי⁠הֶ֖ם הַ⁠כֹּ֥ל מוּצָֽק׃","ẇ⁠maֽʻàşé̂h֙ há⁠ʼ֣wòpani̇֔ym kĕ̇⁠maʻàşé֖̂h ʼwòpa֣n ha⁠mėrĕká̇bá֑h yĕdwòţá֣⁠m wĕ⁠gabé̇y⁠he֗m wĕ⁠ẖişu̇̌qéy⁠he֛m wĕ⁠ẖişu̇̌réy⁠he֖m ha⁠kò֥̇l mẇẕáֽq׃"],[7,34,"וְ⁠אַרְבַּ֣ע כְּתֵפ֔וֹת אֶ֚ל אַרְבַּ֣ע פִּנּ֔וֹת הַ⁠מְּכֹנָ֖ה הָֽ⁠אֶחָ֑ת מִן־הַ⁠מְּכֹנָ֖ה כְּתֵפֶֽי⁠הָ׃","wĕ⁠ʼarĕbȧ֣ʻ kĕ̇ţép֔wòţ ʼe֚l ʼarĕbȧ֣ʻ pi̇ṅ֔wòţ ha⁠mĕ̇kòná֖h háֽ⁠ʼeẖá֑ţ min-ha⁠mĕ̇kòná֖h kĕ̇ţépeֽy⁠há׃"],[7,35,"וּ⁠בְ⁠רֹ֣אשׁ הַ⁠מְּכוֹנָ֗ה חֲצִ֧י הָ⁠אַמָּ֛ה קוֹמָ֖ה עָגֹ֣ל ׀ סָבִ֑יב וְ⁠עַ֨ל רֹ֤אשׁ הַ⁠מְּכֹנָה֙ יְדֹתֶ֔י⁠הָ וּ⁠מִסְגְּרֹתֶ֖י⁠הָ מִמֶּֽ⁠נָּה׃","ẇ⁠bĕ⁠rò֣ʼş̌ ha⁠mĕ̇kwòná֗h ẖàẕi֧y há⁠ʼamá֛̇h qwòmá֖h ʻágò֣l ׀ sábi֑yb wĕ⁠ʻa֨l rò֤ʼş̌ ha⁠mĕ̇kònáh֙ yĕdòţe֔y⁠há ẇ⁠misĕgĕ̇ròţe֖y⁠há mimėֽ⁠ná̇h׃"],[7,36,"וַ⁠יְפַתַּ֤ח עַל־הַ⁠לֻּחֹת֙ יְדֹתֶ֔י⁠הָ וְ⁠עַל֙ ו⁠מסגרתי⁠ה כְּרוּבִ֖ים אֲרָי֣וֹת וְ⁠תִמֹרֹ֑ת כְּ⁠מַֽעַר־אִ֥ישׁ וְ⁠לֹי֖וֹת סָבִֽיב׃","wa⁠yĕpaţȧ֤ẖ ʻal-ha⁠lu̇ẖòţ֙ yĕdòţe֔y⁠há wĕ⁠ʻal֙ w⁠msgrţy⁠h kĕ̇rẇbi֖ym ʼàráy֣wòţ wĕ⁠ţimòrò֑ţ kĕ̇⁠maֽʻar-ʼi֥yş̌ wĕ⁠lòy֖wòţ sábiֽyb׃"],[7,37,"כָּ⁠זֹ֣את עָשָׂ֔ה אֵ֖ת עֶ֣שֶׂר הַ⁠מְּכֹנ֑וֹת מוּצָ֨ק אֶחָ֜ד מִדָּ֥ה אַחַ֛ת קֶ֥צֶב אֶחָ֖ד לְ⁠כֻלָּֽ⁠הְנָה׃ס","ká̇⁠zò֣ʼţ ʻáşá̂֔h ʼé֖ţ ʻe֣şêr ha⁠mĕ̇kòn֑wòţ mẇẕá֨q ʼeẖá֜d midá֥̇h ʼaẖa֛ţ qe֥ẕeb ʼeẖá֖d lĕ⁠kuláֽ̇⁠hĕnáh׃s"],[7,38,"וַ⁠יַּ֛עַשׂ עֲשָׂרָ֥ה כִיֹּר֖וֹת נְחֹ֑שֶׁת אַרְבָּעִ֨ים בַּ֜ת יָכִ֣יל ׀ הַ⁠כִּיּ֣וֹר הָ⁠אֶחָ֗ד אַרְבַּ֤ע בָּֽ⁠אַמָּה֙ הַ⁠כִּיּ֣וֹר הָ⁠אֶחָ֔ד כִּיּ֤וֹר אֶחָד֙ עַל־הַ⁠מְּכוֹנָ֣ה הָ⁠אַחַ֔ת לְ⁠עֶ֖שֶׂר הַ⁠מְּכֹנֽוֹת׃","wa⁠yȧ֛ʻaş̂ ʻàşá̂rá֥h kiyò̇r֖wòţ nĕẖò֑şěţ ʼarĕbá̇ʻi֨ym bȧ֜ţ yáki֣yl ׀ ha⁠ki̇ẏ֣wòr há⁠ʼeẖá֗d ʼarĕbȧ֤ʻ báֽ̇⁠ʼamá̇h֙ ha⁠ki̇ẏ֣wòr há⁠ʼeẖá֔d ki̇ẏ֤wòr ʼeẖád֙ ʻal-ha⁠mĕ̇kwòná֣h há⁠ʼaẖa֔ţ lĕ⁠ʻe֖şêr ha⁠mĕ̇kònֽwòţ׃"],[7,39,"וַ⁠יִּתֵּן֙ אֶת־הַ⁠מְּכֹנ֔וֹת חָמֵ֞שׁ עַל־כֶּ֤תֶף הַ⁠בַּ֨יִת֙ מִ⁠יָּמִ֔ין וְ⁠חָמֵ֛שׁ עַל־כֶּ֥תֶף הַ⁠בַּ֖יִת מִ⁠שְּׂמֹאל֑⁠וֹ וְ⁠אֶת־הַ⁠יָּ֗ם נָתַ֞ן מִ⁠כֶּ֨תֶף הַ⁠בַּ֧יִת הַ⁠יְמָנִ֛ית קֵ֖דְמָ⁠ה מִ⁠מּ֥וּל נֶֽגֶב׃ס","wa⁠yi̇ţé̇n֙ ʼeţ-ha⁠mĕ̇kòn֔wòţ ẖámé֞ş̌ ʻal-kė֤ţep ha⁠bȧ֨yiţ֙ mi⁠yá̇mi֔yn wĕ⁠ẖámé֛ş̌ ʻal-kė֥ţep ha⁠bȧ֖yiţ mi⁠şĕ̇̂mòʼl֑⁠wò wĕ⁠ʼeţ-ha⁠yá̇֗m náţa֞n mi⁠kė֨ţep ha⁠bȧ֧yiţ ha⁠yĕmáni֛yţ qé֖dĕmá⁠h mi⁠ṁ֥ẇl neֽgeb׃s"],[7,40,"וַ⁠יַּ֣עַשׂ חִיר֔וֹם אֶת־הַ֨⁠כִּיֹּר֔וֹת וְ⁠אֶת־הַ⁠יָּעִ֖ים וְ⁠אֶת־הַ⁠מִּזְרָק֑וֹת וַ⁠יְכַ֣ל חִירָ֗ם לַֽ⁠עֲשׂוֹת֙ אֶת־כָּל־הַ⁠מְּלָאכָ֔ה אֲשֶׁ֥ר עָשָׂ֛ה לַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה בֵּ֥ית יְהוָֽה׃","wa⁠yȧ֣ʻaş̂ ẖiyr֔wòm ʼeţ-ha֨⁠ki̇yò̇r֔wòţ wĕ⁠ʼeţ-ha⁠yá̇ʻi֖ym wĕ⁠ʼeţ-ha⁠mi̇zĕráq֑wòţ wa⁠yĕka֣l ẖiyrá֗m laֽ⁠ʻàş̂wòţ֙ ʼeţ-ká̇l-ha⁠mĕ̇láʼká֔h ʼàşě֥r ʻáşá֛̂h la⁠mė֥lekĕ şĕ̌lòmò֖h bé֥̇yţ yĕhwáֽh׃"],[7,41,"עַמֻּדִ֣ים שְׁנַ֔יִם וְ⁠גֻלֹּ֧ת הַ⁠כֹּתָרֹ֛ת אֲשֶׁר־עַל־רֹ֥אשׁ הָֽ⁠עַמֻּדִ֖ים שְׁתָּ֑יִם וְ⁠הַ⁠שְּׂבָכ֣וֹת שְׁתַּ֔יִם לְ⁠כַסּ֗וֹת אֶת־שְׁתֵּי֙ גֻּלֹּ֣ת הַ⁠כֹּֽתָרֹ֔ת אֲשֶׁ֖ר עַל־רֹ֥אשׁ הָ⁠עַמּוּדִֽים׃","ʻamu̇di֣ym şĕ̌na֔yim wĕ⁠gulò֧̇ţ ha⁠kò̇ţárò֛ţ ʼàşěr-ʻal-rò֥ʼş̌ háֽ⁠ʻamu̇di֖ym şĕ̌ţá֑̇yim wĕ⁠ha⁠şĕ̇̂bák֣wòţ şĕ̌ţȧ֔yim lĕ⁠kaṡ֗wòţ ʼeţ-şĕ̌ţé̇y֙ gu̇lò֣̇ţ ha⁠kòֽ̇ţárò֔ţ ʼàşě֖r ʻal-rò֥ʼş̌ há⁠ʻaṁẇdiֽym׃"],[7,42,"וְ⁠אֶת־הָ⁠רִמֹּנִ֛ים אַרְבַּ֥ע מֵא֖וֹת לִ⁠שְׁתֵּ֣י הַ⁠שְּׂבָכ֑וֹת שְׁנֵֽי־טוּרִ֤ים רִמֹּנִים֙ לַ⁠שְּׂבָכָ֣ה הָֽ⁠אֶחָ֔ת לְ⁠כַסּ֗וֹת אֶת־שְׁתֵּי֙ גֻּלֹּ֣ת הַ⁠כֹּֽתָרֹ֔ת אֲשֶׁ֖ר עַל־פְּנֵ֥י הָ⁠עַמּוּדִֽים׃","wĕ⁠ʼeţ-há⁠rimò̇ni֛ym ʼarĕbȧ֥ʻ méʼ֖wòţ li⁠şĕ̌ţé֣̇y ha⁠şĕ̇̂bák֑wòţ şĕ̌néֽy-tẇri֤ym rimò̇niym֙ la⁠şĕ̇̂báká֣h háֽ⁠ʼeẖá֔ţ lĕ⁠kaṡ֗wòţ ʼeţ-şĕ̌ţé̇y֙ gu̇lò֣̇ţ ha⁠kòֽ̇ţárò֔ţ ʼàşě֖r ʻal-pĕ̇né֥y há⁠ʻaṁẇdiֽym׃"],[7,43,"וְ⁠אֶת־הַ⁠מְּכֹנ֖וֹת עָ֑שֶׂר וְ⁠אֶת־הַ⁠כִּיֹּרֹ֥ת עֲשָׂרָ֖ה עַל־הַ⁠מְּכֹנֽוֹת׃","wĕ⁠ʼeţ-ha⁠mĕ̇kòn֖wòţ ʻá֑şêr wĕ⁠ʼeţ-ha⁠ki̇yò̇rò֥ţ ʻàşá̂rá֖h ʻal-ha⁠mĕ̇kònֽwòţ׃"],[7,44,"וְ⁠אֶת־הַ⁠יָּ֖ם הָ⁠אֶחָ֑ד וְ⁠אֶת־הַ⁠בָּקָ֥ר שְׁנֵים־עָשָׂ֖ר תַּ֥חַת הַ⁠יָּֽם׃","wĕ⁠ʼeţ-ha⁠yá֖̇m há⁠ʼeẖá֑d wĕ⁠ʼeţ-ha⁠bá̇qá֥r şĕ̌néym-ʻáşá֖̂r ţȧ֥ẖaţ ha⁠yáֽ̇m׃"],[7,45,"וְ⁠אֶת־הַ⁠סִּיר֨וֹת וְ⁠אֶת־הַ⁠יָּעִ֜ים וְ⁠אֶת־הַ⁠מִּזְרָק֗וֹת וְ⁠אֵת֙ כָּל־הַ⁠כֵּלִ֣ים ה⁠אהל אֲשֶׁ֨ר עָשָׂ֥ה חִירָ֛ם לַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה בֵּ֣ית יְהוָ֑ה נְחֹ֖שֶׁת מְמֹרָֽט׃","wĕ⁠ʼeţ-ha⁠si̇yr֨wòţ wĕ⁠ʼeţ-ha⁠yá̇ʻi֜ym wĕ⁠ʼeţ-ha⁠mi̇zĕráq֗wòţ wĕ⁠ʼéţ֙ ká̇l-ha⁠ké̇li֣ym h⁠ʼhl ʼàşě֨r ʻáşá֥̂h ẖiyrá֛m la⁠mė֥lekĕ şĕ̌lòmò֖h bé֣̇yţ yĕhwá֑h nĕẖò֖şěţ mĕmòráֽt׃"],[7,46,"בְּ⁠כִכַּ֤ר הַ⁠יַּרְדֵּן֙ יְצָקָ֣⁠ם הַ⁠מֶּ֔לֶךְ בְּ⁠מַעֲבֵ֖ה הָ⁠אֲדָמָ֑ה בֵּ֥ין סֻכּ֖וֹת וּ⁠בֵ֥ין צָרְתָֽן׃","bĕ̇⁠kikȧ֤r ha⁠yȧrĕdé̇n֙ yĕẕáqá֣⁠m ha⁠mė֔lekĕ bĕ̇⁠maʻàbé֖h há⁠ʼàdámá֑h bé֥̇yn suk֖̇wòţ ẇ⁠bé֥yn ẕárĕţáֽn׃"],[7,47,"וַ⁠יַּנַּ֤ח שְׁלֹמֹה֙ אֶת־כָּל־הַ⁠כֵּלִ֔ים מֵ⁠רֹ֖ב מְאֹ֣ד מְאֹ֑ד לֹ֥א נֶחְקַ֖ר מִשְׁקַ֥ל הַ⁠נְּחֹֽשֶׁת׃","wa⁠yȧnȧ֤ẖ şĕ̌lòmòh֙ ʼeţ-ká̇l-ha⁠ké̇li֔ym mé⁠rò֖b mĕʼò֣d mĕʼò֑d lò֥ʼ neẖĕqa֖r mişĕ̌qa֥l ha⁠nĕ̇ẖòֽşěţ׃"],[7,48,"וַ⁠יַּ֣עַשׂ שְׁלֹמֹ֔ה אֵ֚ת כָּל־הַ⁠כֵּלִ֔ים אֲשֶׁ֖ר בֵּ֣ית יְהוָ֑ה אֵ֚ת מִזְבַּ֣ח הַ⁠זָּהָ֔ב וְ⁠אֶת־הַ⁠שֻּׁלְחָ֗ן אֲשֶׁ֥ר עָלָ֛י⁠ו לֶ֥חֶם הַ⁠פָּנִ֖ים זָהָֽב׃","wa⁠yȧ֣ʻaş̂ şĕ̌lòmò֔h ʼé֚ţ ká̇l-ha⁠ké̇li֔ym ʼàşě֖r bé֣̇yţ yĕhwá֑h ʼé֚ţ mizĕbȧ֣ẖ ha⁠zá̇há֔b wĕ⁠ʼeţ-ha⁠şu̇̌lĕẖá֗n ʼàşě֥r ʻálá֛y⁠w le֥ẖem ha⁠pá̇ni֖ym záháֽb׃"],[7,49,"וְ⁠אֶת־הַ֠⁠מְּנֹרוֹת חָמֵ֨שׁ מִ⁠יָּמִ֜ין וְ⁠חָמֵ֧שׁ מִ⁠שְּׂמֹ֛אול לִ⁠פְנֵ֥י הַ⁠דְּבִ֖יר זָהָ֣ב סָג֑וּר וְ⁠הַ⁠פֶּ֧רַח וְ⁠הַ⁠נֵּרֹ֛ת וְ⁠הַ⁠מֶּלְקַחַ֖יִם זָהָֽב׃","wĕ⁠ʼeţ-ha֠⁠mĕ̇nòrwòţ ẖámé֨ş̌ mi⁠yá̇mi֜yn wĕ⁠ẖámé֧ş̌ mi⁠şĕ̇̂mò֛ʼwl li⁠pĕné֥y ha⁠dĕ̇bi֖yr záhá֣b ság֑ẇr wĕ⁠ha⁠pė֧raẖ wĕ⁠ha⁠né̇rò֛ţ wĕ⁠ha⁠mėlĕqaẖa֖yim záháֽb׃"],[7,50,"וְ֠⁠הַ⁠סִּפּוֹת וְ⁠הַֽ⁠מְזַמְּר֧וֹת וְ⁠הַ⁠מִּזְרָק֛וֹת וְ⁠הַ⁠כַּפּ֥וֹת וְ⁠הַ⁠מַּחְתּ֖וֹת זָהָ֣ב סָג֑וּר וְ⁠הַ⁠פֹּת֡וֹת לְ⁠דַלְתוֹת֩ הַ⁠בַּ֨יִת הַ⁠פְּנִימִ֜י לְ⁠קֹ֣דֶשׁ הַ⁠קֳּדָשִׁ֗ים לְ⁠דַלְתֵ֥י הַ⁠בַּ֛יִת לַ⁠הֵיכָ֖ל זָהָֽב׃פ","wĕ֠⁠ha⁠si̇ṗwòţ wĕ⁠haֽ⁠mĕzamĕ̇r֧wòţ wĕ⁠ha⁠mi̇zĕráq֛wòţ wĕ⁠ha⁠kȧṗ֥wòţ wĕ⁠ha⁠mȧẖĕţ֖̇wòţ záhá֣b ság֑ẇr wĕ⁠ha⁠pò̇ţ֡wòţ lĕ⁠dalĕţwòţ֩ ha⁠bȧ֨yiţ ha⁠pĕ̇niymi֜y lĕ⁠qò֣deş̌ ha⁠qȯdáşǐ֗ym lĕ⁠dalĕţé֥y ha⁠bȧ֛yiţ la⁠héyká֖l záháֽb׃p"],[7,51,"וַ⁠תִּשְׁלַם֙ כָּל־הַ⁠מְּלָאכָ֔ה אֲשֶׁ֥ר עָשָׂ֛ה הַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה בֵּ֣ית יְהוָ֑ה וַ⁠יָּבֵ֨א שְׁלֹמֹ֜ה אֶת־קָדְשֵׁ֣י ׀ דָּוִ֣ד אָבִ֗י⁠ו אֶת־הַ⁠כֶּ֤סֶף וְ⁠אֶת־הַ⁠זָּהָב֙ וְ⁠אֶת־הַ⁠כֵּלִ֔ים נָתַ֕ן בְּ⁠אֹצְר֖וֹת בֵּ֥ית יְהוָֽה׃פ","wa⁠ţi̇şĕ̌lam֙ ká̇l-ha⁠mĕ̇láʼká֔h ʼàşě֥r ʻáşá֛̂h ha⁠mė֥lekĕ şĕ̌lòmò֖h bé֣̇yţ yĕhwá֑h wa⁠yá̇bé֨ʼ şĕ̌lòmò֜h ʼeţ-qádĕşé֣̌y ׀ dá̇wi֣d ʼábi֗y⁠w ʼeţ-ha⁠kė֤sep wĕ⁠ʼeţ-ha⁠zá̇háb֙ wĕ⁠ʼeţ-ha⁠ké̇li֔ym náţa֕n bĕ̇⁠ʼòẕĕr֖wòţ bé֥̇yţ yĕhwáֽh׃p"],[8,1,"אָ֣ז יַקְהֵ֣ל שְׁלֹמֹ֣ה אֶת־זִקְנֵ֣י יִשְׂרָאֵ֡ל אֶת־כָּל־רָאשֵׁ֣י הַ⁠מַּטּוֹת֩ נְשִׂיאֵ֨י הָ⁠אָב֜וֹת לִ⁠בְנֵ֧י יִשְׂרָאֵ֛ל אֶל־הַ⁠מֶּ֥לֶךְ שְׁלֹמֹ֖ה יְרוּשָׁלִָ֑ם לְֽ⁠הַעֲל֞וֹת אֶת־אֲר֧וֹן בְּרִית־יְהוָ֛ה מֵ⁠עִ֥יר דָּוִ֖ד הִ֥יא צִיּֽוֹן׃","ʼá֣z yaqĕhé֣l şĕ̌lòmò֣h ʼeţ-ziqĕné֣y yişĕ̂ráʼé֡l ʼeţ-ká̇l-ráʼşé֣̌y ha⁠mȧṫwòţ֩ nĕşîyʼé֨y há⁠ʼáb֜wòţ li⁠bĕné֧y yişĕ̂ráʼé֛l ʼel-ha⁠mė֥lekĕ şĕ̌lòmò֖h yĕrẇşá̌liá֑m lĕֽ⁠haʻàl֞wòţ ʼeţ-ʼàr֧wòn bĕ̇riyţ-yĕhwá֛h mé⁠ʻi֥yr dá̇wi֖d hi֥yʼ ẕiẏֽwòn׃"],[8,2,"וַ⁠יִּקָּ֨הֲל֜וּ אֶל־הַ⁠מֶּ֤לֶךְ שְׁלֹמֹה֙ כָּל־אִ֣ישׁ יִשְׂרָאֵ֔ל בְּ⁠יֶ֥רַח הָ⁠אֵֽתָנִ֖ים בֶּ⁠חָ֑ג ה֖וּא הַ⁠חֹ֥דֶשׁ הַ⁠שְּׁבִיעִֽי׃","wa⁠yi̇qá̇֨hàl֜ẇ ʼel-ha⁠mė֤lekĕ şĕ̌lòmòh֙ ká̇l-ʼi֣yş̌ yişĕ̂ráʼé֔l bĕ̇⁠ye֥raẖ há⁠ʼéֽţáni֖ym bė⁠ẖá֑g h֖ẇʼ ha⁠ẖò֥deş̌ ha⁠şĕ̇̌biyʻiֽy׃"],[8,3,"וַ⁠יָּבֹ֕אוּ כֹּ֖ל זִקְנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּשְׂא֥וּ הַ⁠כֹּהֲנִ֖ים אֶת־הָ⁠אָרֽוֹן׃","wa⁠yá̇bò֕ʼẇ kò֖̇l ziqĕné֣y yişĕ̂ráʼé֑l wa⁠yi̇şĕ̂ʼ֥ẇ ha⁠kò̇hàni֖ym ʼeţ-há⁠ʼárֽwòn׃"],[8,4,"וַֽ⁠יַּעֲל֞וּ אֶת־אֲר֤וֹן יְהוָה֙ וְ⁠אֶת־אֹ֣הֶל מוֹעֵ֔ד וְ⁠אֶֽת־כָּל־כְּלֵ֥י הַ⁠קֹּ֖דֶשׁ אֲשֶׁ֣ר בָּ⁠אֹ֑הֶל וַ⁠יַּעֲל֣וּ אֹתָ֔⁠ם הַ⁠כֹּהֲנִ֖ים וְ⁠הַ⁠לְוִיִּֽם׃","waֽ⁠yȧʻàl֞ẇ ʼeţ-ʼàr֤wòn yĕhwáh֙ wĕ⁠ʼeţ-ʼò֣hel mwòʻé֔d wĕ⁠ʼeֽţ-ká̇l-kĕ̇lé֥y ha⁠qò֖̇deş̌ ʼàşě֣r bá̇⁠ʼò֑hel wa⁠yȧʻàl֣ẇ ʼòţá֔⁠m ha⁠kò̇hàni֖ym wĕ⁠ha⁠lĕwiyiֽ̇m׃"],[8,5,"וְ⁠הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֗ה וְ⁠כָל־עֲדַ֤ת יִשְׂרָאֵל֙ הַ⁠נּוֹעָדִ֣ים עָלָ֔י⁠ו אִתּ֖⁠וֹ לִ⁠פְנֵ֣י הָֽ⁠אָר֑וֹן מְזַבְּחִים֙ צֹ֣אן וּ⁠בָקָ֔ר אֲשֶׁ֧ר לֹֽא־יִסָּפְר֛וּ וְ⁠לֹ֥א יִמָּנ֖וּ מֵ⁠רֹֽב׃","wĕ⁠ha⁠mė֣lekĕ şĕ̌lòmò֗h wĕ⁠kál-ʻàda֤ţ yişĕ̂ráʼél֙ ha⁠ṅwòʻádi֣ym ʻálá֔y⁠w ʼiţ֖̇⁠wò li⁠pĕné֣y háֽ⁠ʼár֑wòn mĕzabĕ̇ẖiym֙ ẕò֣ʼn ẇ⁠báqá֔r ʼàşě֧r lòֽʼ-yisá̇pĕr֛ẇ wĕ⁠lò֥ʼ yimá̇n֖ẇ mé⁠ròֽb׃"],[8,6,"וַ⁠יָּבִ֣אוּ הַ֠⁠כֹּהֲנִים אֶת־אֲר֨וֹן בְּרִית־יְהוָ֧ה אֶל־מְקוֹמ֛⁠וֹ אֶל־דְּבִ֥יר הַ⁠בַּ֖יִת אֶל־קֹ֣דֶשׁ הַ⁠קֳּדָשִׁ֑ים אֶל־תַּ֖חַת כַּנְפֵ֥י הַ⁠כְּרוּבִֽים׃","wa⁠yá̇bi֣ʼẇ ha֠⁠kò̇hàniym ʼeţ-ʼàr֨wòn bĕ̇riyţ-yĕhwá֧h ʼel-mĕqwòm֛⁠wò ʼel-dĕ̇bi֥yr ha⁠bȧ֖yiţ ʼel-qò֣deş̌ ha⁠qȯdáşǐ֑ym ʼel-ţȧ֖ẖaţ kȧnĕpé֥y ha⁠kĕ̇rẇbiֽym׃"],[8,7,"כִּ֤י הַ⁠כְּרוּבִים֙ פֹּרְשִׂ֣ים כְּנָפַ֔יִם אֶל־מְק֖וֹם הָֽ⁠אָר֑וֹן וַ⁠יָּסֹ֧כּוּ הַ⁠כְּרֻבִ֛ים עַל־הָ⁠אָר֥וֹן וְ⁠עַל־בַּדָּ֖י⁠ו מִ⁠לְ⁠מָֽעְלָ⁠ה׃","ki֤̇y ha⁠kĕ̇rẇbiym֙ pò̇rĕşî֣ym kĕ̇nápa֔yim ʼel-mĕq֖wòm háֽ⁠ʼár֑wòn wa⁠yá̇sò֧k̇ẇ ha⁠kĕ̇rubi֛ym ʻal-há⁠ʼár֥wòn wĕ⁠ʻal-bȧdá֖̇y⁠w mi⁠lĕ⁠máֽʻĕlá⁠h׃"],[8,8,"וַֽ⁠יַּאֲרִכוּ֮ הַ⁠בַּדִּים֒ וַ⁠יֵּרָאוּ֩ רָאשֵׁ֨י הַ⁠בַּדִּ֤ים מִן־הַ⁠קֹּ֨דֶשׁ֙ עַל־פְּנֵ֣י הַ⁠דְּבִ֔יר וְ⁠לֹ֥א יֵרָא֖וּ הַ⁠ח֑וּצָ⁠ה וַ⁠יִּ֣הְיוּ שָׁ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wֽa⁠yȧʼàrikẇ֮ ha⁠bȧdi̇ym֒ wa⁠yé̇ráʼẇ֩ ráʼşé̌֨y ha⁠bȧdi֤̇ym min-ha⁠qò̇֨deş̌֙ ʻal-pĕ̇né֣y ha⁠dĕ̇bi֔yr wĕ⁠lò֥ʼ yéráʼ֖ẇ ha⁠ẖ֑ẇẕá⁠h wa⁠yi֣̇hĕyẇ şá̌֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[8,9,"אֵ֚ין בָּֽ⁠אָר֔וֹן רַ֗ק שְׁנֵי֙ לֻח֣וֹת הָ⁠אֲבָנִ֔ים אֲשֶׁ֨ר הִנִּ֥חַ שָׁ֛ם מֹשֶׁ֖ה בְּ⁠חֹרֵ֑ב אֲשֶׁ֨ר כָּרַ֤ת יְהוָה֙ עִם־בְּנֵ֣י יִשְׂרָאֵ֔ל בְּ⁠צֵאתָ֖⁠ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","ʼé֚yn báֽ̇⁠ʼár֔wòn ra֗q şĕ̌néy֙ luẖ֣wòţ há⁠ʼàbáni֔ym ʼàşě֨r hini֥̇ẖa şá֛̌m mòşě֖h bĕ̇⁠ẖòré֑b ʼàşě֨r ká̇ra֤ţ yĕhwáh֙ ʻim-bĕ̇né֣y yişĕ̂ráʼé֔l bĕ̇⁠ẕéʼţá֖⁠m mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[8,10,"וַ⁠יְהִ֕י בְּ⁠צֵ֥את הַ⁠כֹּהֲנִ֖ים מִן־הַ⁠קֹּ֑דֶשׁ וְ⁠הֶ⁠עָנָ֥ן מָלֵ֖א אֶת־בֵּ֥ית יְהוָֽה׃","wa⁠yĕhi֕y bĕ̇⁠ẕé֥ʼţ ha⁠kò̇hàni֖ym min-ha⁠qò֑̇deş̌ wĕ⁠he⁠ʻáná֥n málé֖ʼ ʼeţ-bé֥̇yţ yĕhwáֽh׃"],[8,11,"וְ⁠לֹֽא־יָכְל֧וּ הַ⁠כֹּהֲנִ֛ים לַ⁠עֲמֹ֥ד לְ⁠שָׁרֵ֖ת מִ⁠פְּנֵ֥י הֶֽ⁠עָנָ֑ן כִּי־מָלֵ֥א כְבוֹד־יְהוָ֖ה אֶת־בֵּ֥ית יְהוָֽה׃פ","wĕ⁠lòֽʼ-yákĕl֧ẇ ha⁠kò̇hàni֛ym la⁠ʻàmò֥d lĕ⁠şá̌ré֖ţ mi⁠pĕ̇né֥y heֽ⁠ʻáná֑n ki̇y-málé֥ʼ kĕbwòd-yĕhwá֖h ʼeţ-bé֥̇yţ yĕhwáֽh׃p"],[8,12,"אָ֖ז אָמַ֣ר שְׁלֹמֹ֑ה יְהוָ֣ה אָמַ֔ר לִ⁠שְׁכֹּ֖ן בָּ⁠עֲרָפֶֽל׃","ʼá֖z ʼáma֣r şĕ̌lòmò֑h yĕhwá֣h ʼáma֔r li⁠şĕ̌kò֖̇n bá̇⁠ʻàrápeֽl׃"],[8,13,"בָּנֹ֥ה בָנִ֛יתִי בֵּ֥ית זְבֻ֖ל לָ֑⁠ךְ מָכ֥וֹן לְ⁠שִׁבְתְּ⁠ךָ֖ עוֹלָמִֽים׃","bá̇nò֥h báni֛yţiy bé֥̇yţ zĕbu֖l lá֑⁠kĕ mák֥wòn lĕ⁠şǐbĕţĕ̇⁠ká֖ ʻwòlámiֽym׃"],[8,14,"וַ⁠יַּסֵּ֤ב הַ⁠מֶּ֨לֶךְ֙ אֶת־פָּנָ֔י⁠ו וַ⁠יְבָ֕רֶךְ אֵ֖ת כָּל־קְהַ֣ל יִשְׂרָאֵ֑ל וְ⁠כָל־קְהַ֥ל יִשְׂרָאֵ֖ל עֹמֵֽד׃","wa⁠yȧsé֤̇b ha⁠mė֨lekĕ֙ ʼeţ-pá̇ná֔y⁠w wa⁠yĕbá֕rekĕ ʼé֖ţ ká̇l-qĕha֣l yişĕ̂ráʼé֑l wĕ⁠kál-qĕha֥l yişĕ̂ráʼé֖l ʻòméֽd׃"],[8,15,"וַ⁠יֹּ֗אמֶר בָּר֤וּךְ יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁר֙ דִּבֶּ֣ר בְּ⁠פִ֔י⁠ו אֵ֖ת דָּוִ֣ד אָבִ֑⁠י וּ⁠בְ⁠יָד֥⁠וֹ מִלֵּ֖א לֵ⁠אמֹֽר׃","wa⁠yò̇֗ʼmer bá̇r֤ẇkĕ yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşěr֙ di̇bė֣r bĕ̇⁠pi֔y⁠w ʼé֖ţ dá̇wi֣d ʼábi֑⁠y ẇ⁠bĕ⁠yád֥⁠wò milé֖̇ʼ lé⁠ʼmòֽr׃"],[8,16,"מִן־הַ⁠יּ֗וֹם אֲשֶׁ֨ר הוֹצֵ֜אתִי אֶת־עַמִּ֣⁠י אֶת־יִשְׂרָאֵל֮ מִ⁠מִּצְרַיִם֒ לֹֽא־בָחַ֣רְתִּי בְ⁠עִ֗יר מִ⁠כֹּל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל לִ⁠בְנ֣וֹת בַּ֔יִת לִ⁠הְי֥וֹת שְׁמִ֖⁠י שָׁ֑ם וָ⁠אֶבְחַ֣ר בְּ⁠דָוִ֔ד לִֽ⁠הְי֖וֹת עַל־עַמִּ֥⁠י יִשְׂרָאֵֽל׃","min-ha⁠ẏ֗wòm ʼàşě֨r hwòẕé֜ʼţiy ʼeţ-ʻami֣̇⁠y ʼeţ-yişĕ̂ráʼél֮ mi⁠mi̇ẕĕrayim֒ lòֽʼ-báẖa֣rĕţi̇y bĕ⁠ʻi֗yr mi⁠kò̇l֙ şǐbĕté֣y yişĕ̂ráʼé֔l li⁠bĕn֣wòţ bȧ֔yiţ li⁠hĕy֥wòţ şĕ̌mi֖⁠y şá֑̌m wá⁠ʼebĕẖa֣r bĕ̇⁠dáwi֔d liֽ⁠hĕy֖wòţ ʻal-ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[8,17,"וַ⁠יְהִ֕י עִם־לְבַ֖ב דָּוִ֣ד אָבִ֑⁠י לִ⁠בְנ֣וֹת בַּ֔יִת לְ⁠שֵׁ֥ם יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yĕhi֕y ʻim-lĕba֖b dá̇wi֣d ʼábi֑⁠y li⁠bĕn֣wòţ bȧ֔yiţ lĕ⁠şé֥̌m yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[8,18,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֶל־דָּוִ֣ד אָבִ֔⁠י יַ֗עַן אֲשֶׁ֤ר הָיָה֙ עִם־לְבָ֣בְ⁠ךָ֔ לִ⁠בְנ֥וֹת בַּ֖יִת לִ⁠שְׁמִ֑⁠י הֱטִיבֹ֔תָ כִּ֥י הָיָ֖ה עִם־לְבָבֶֽ⁠ךָ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼel-dá̇wi֣d ʼábi֔⁠y ya֗ʻan ʼàşě֤r háyáh֙ ʻim-lĕbá֣bĕ⁠ká֔ li⁠bĕn֥wòţ bȧ֖yiţ li⁠şĕ̌mi֑⁠y hètiybò֔ţá ki֥̇y háyá֖h ʻim-lĕbábeֽ⁠ká׃"],[8,19,"רַ֣ק אַתָּ֔ה לֹ֥א תִבְנֶ֖ה הַ⁠בָּ֑יִת כִּ֤י אִם־בִּנְ⁠ךָ֙ הַ⁠יֹּצֵ֣א מֵ⁠חֲלָצֶ֔י⁠ךָ הֽוּא־יִבְנֶ֥ה הַ⁠בַּ֖יִת לִ⁠שְׁמִֽ⁠י׃","ra֣q ʼaţá̇֔h lò֥ʼ ţibĕne֖h ha⁠bá֑̇yiţ ki֤̇y ʼim-bi̇nĕ⁠ká֙ ha⁠yò̇ẕé֣ʼ mé⁠ẖàláẕe֔y⁠ká hֽẇʼ-yibĕne֥h ha⁠bȧ֖yiţ li⁠şĕ̌miֽ⁠y׃"],[8,20,"וַ⁠יָּ֣קֶם יְהוָ֔ה אֶת־דְּבָר֖⁠וֹ אֲשֶׁ֣ר דִּבֵּ֑ר וָ⁠אָקֻ֡ם תַּחַת֩ דָּוִ֨ד אָבִ֜⁠י וָ⁠אֵשֵׁ֣ב עַל־כִּסֵּ֣א יִשְׂרָאֵ֗ל כַּֽ⁠אֲשֶׁר֙ דִּבֶּ֣ר יְהוָ֔ה וָ⁠אֶבְנֶ֣ה הַ⁠בַּ֔יִת לְ⁠שֵׁ֥ם יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yá֣̇qem yĕhwá֔h ʼeţ-dĕ̇bár֖⁠wò ʼàşě֣r di̇bé֑̇r wá⁠ʼáqu֡m ţȧẖaţ֩ dá̇wi֨d ʼábi֜⁠y wá⁠ʼéşé֣̌b ʻal-ki̇sé֣̇ʼ yişĕ̂ráʼé֗l kȧֽ⁠ʼàşěr֙ di̇bė֣r yĕhwá֔h wá⁠ʼebĕne֣h ha⁠bȧ֔yiţ lĕ⁠şé֥̌m yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[8,21,"וָ⁠אָשִׂ֨ם שָׁ֤ם מָקוֹם֙ לָֽ⁠אָר֔וֹן אֲשֶׁר־שָׁ֖ם בְּרִ֣ית יְהוָ֑ה אֲשֶׁ֤ר כָּרַת֙ עִם־אֲבֹתֵ֔י⁠נוּ בְּ⁠הוֹצִיא֥⁠וֹ אֹתָ֖⁠ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃ס","wá⁠ʼáşî֨m şá֤̌m máqwòm֙ láֽ⁠ʼár֔wòn ʼàşěr-şá֖̌m bĕ̇ri֣yţ yĕhwá֑h ʼàşě֤r ká̇raţ֙ ʻim-ʼàbòţé֔y⁠nẇ bĕ̇⁠hwòẕiyʼ֥⁠wò ʼòţá֖⁠m mé⁠ʼe֥reẕ miẕĕráֽyim׃s"],[8,22,"וַ⁠יַּעֲמֹ֣ד שְׁלֹמֹ֗ה לִ⁠פְנֵי֙ מִזְבַּ֣ח יְהוָ֔ה נֶ֖גֶד כָּל־קְהַ֣ל יִשְׂרָאֵ֑ל וַ⁠יִּפְרֹ֥שׂ כַּפָּ֖י⁠ו הַ⁠שָּׁמָֽיִם׃","wa⁠yȧʻàmò֣d şĕ̌lòmò֗h li⁠pĕnéy֙ mizĕbȧ֣ẖ yĕhwá֔h ne֖ged ká̇l-qĕha֣l yişĕ̂ráʼé֑l wa⁠yi̇pĕrò֥ş̂ kȧpá֖̇y⁠w ha⁠şá̇̌máֽyim׃"],[8,23,"וַ⁠יֹּאמַ֗ר יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ אֵין־כָּמ֣וֹ⁠ךָ אֱלֹהִ֔ים בַּ⁠שָּׁמַ֣יִם מִ⁠מַּ֔עַל וְ⁠עַל־הָ⁠אָ֖רֶץ מִ⁠תָּ֑חַת שֹׁמֵ֤ר הַ⁠בְּרִית֙ וְֽ⁠הַ⁠חֶ֔סֶד לַ⁠עֲבָדֶ֕י⁠ךָ הַ⁠הֹלְכִ֥ים לְ⁠פָנֶ֖י⁠ךָ בְּ⁠כָל־לִבָּֽ⁠ם׃","wa⁠yò̇ʼma֗r yĕhwá֞h ʼèlòhé֤y yişĕ̂ráʼél֙ ʼéyn-ká̇m֣wò⁠ká ʼèlòhi֔ym bȧ⁠şá̇̌ma֣yim mi⁠mȧ֔ʻal wĕ⁠ʻal-há⁠ʼá֖reẕ mi⁠ţá֑̇ẖaţ şò̌mé֤r ha⁠bĕ̇riyţ֙ wĕֽ⁠ha⁠ẖe֔sed la⁠ʻàbáde֕y⁠ká ha⁠hòlĕki֥ym lĕ⁠páne֖y⁠ká bĕ̇⁠kál-libáֽ̇⁠m׃"],[8,24,"אֲשֶׁ֣ר שָׁמַ֗רְתָּ לְ⁠עַבְדְּ⁠ךָ֙ דָּוִ֣ד אָבִ֔⁠י אֵ֥ת אֲשֶׁר־דִּבַּ֖רְתָּ ל֑⁠וֹ וַ⁠תְּדַבֵּ֥ר בְּ⁠פִ֛י⁠ךָ וּ⁠בְ⁠יָדְ⁠ךָ֥ מִלֵּ֖אתָ כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","ʼàşě֣r şá̌ma֗rĕţá̇ lĕ⁠ʻabĕdĕ̇⁠ká֙ dá̇wi֣d ʼábi֔⁠y ʼé֥ţ ʼàşěr-di̇bȧ֖rĕţá̇ l֑⁠wò wa⁠ţĕ̇dabé֥̇r bĕ̇⁠pi֛y⁠ká ẇ⁠bĕ⁠yádĕ⁠ká֥ milé֖̇ʼţá kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[8,25,"וְ⁠עַתָּ֞ה יְהוָ֣ה ׀ אֱלֹהֵ֣י יִשְׂרָאֵ֗ל שְׁ֠מֹר לְ⁠עַבְדְּ⁠ךָ֨ דָוִ֤ד אָבִ⁠י֙ אֵת֩ אֲשֶׁ֨ר דִּבַּ֤רְתָּ לּ⁠וֹ֙ לֵ⁠אמֹ֔ר לֹא־יִכָּרֵ֨ת לְ⁠ךָ֥ אִישׁ֙ מִ⁠לְּ⁠פָנַ֔⁠י יֹשֵׁ֖ב עַל־כִּסֵּ֣א יִשְׂרָאֵ֑ל רַ֠ק אִם־יִשְׁמְר֨וּ בָנֶ֤י⁠ךָ אֶת־דַּרְכָּ⁠ם֙ לָ⁠לֶ֣כֶת לְ⁠פָנַ֔⁠י כַּ⁠אֲשֶׁ֥ר הָלַ֖כְתָּ לְ⁠פָנָֽ⁠י׃","wĕ⁠ʻaţá̇֞h yĕhwá֣h ׀ ʼèlòhé֣y yişĕ̂ráʼé֗l şĕ̌֠mòr lĕ⁠ʻabĕdĕ̇⁠ká֨ dáwi֤d ʼábi⁠y֙ ʼéţ֩ ʼàşě֨r di̇bȧ֤rĕţá̇ l̇⁠wò֙ lé⁠ʼmò֔r lòʼ-yiká̇ré֨ţ lĕ⁠ká֥ ʼiyş̌֙ mi⁠lĕ̇⁠pána֔⁠y yòşé֖̌b ʻal-ki̇sé֣̇ʼ yişĕ̂ráʼé֑l ra֠q ʼim-yişĕ̌mĕr֨ẇ báne֤y⁠ká ʼeţ-dȧrĕká̇⁠m֙ lá⁠le֣keţ lĕ⁠pána֔⁠y kȧ⁠ʼàşě֥r hála֖kĕţá̇ lĕ⁠pánáֽ⁠y׃"],[8,26,"וְ⁠עַתָּ֖ה אֱלֹהֵ֣י יִשְׂרָאֵ֑ל יֵאָ֤מֶן נָא֙ דברי⁠ך אֲשֶׁ֣ר דִּבַּ֔רְתָּ לְ⁠עַבְדְּ⁠ךָ֖ דָּוִ֥ד אָבִֽ⁠י׃","wĕ⁠ʻaţá֖̇h ʼèlòhé֣y yişĕ̂ráʼé֑l yéʼá֤men náʼ֙ dbry⁠k ʼàşě֣r di̇bȧ֔rĕţá̇ lĕ⁠ʻabĕdĕ̇⁠ká֖ dá̇wi֥d ʼábiֽ⁠y׃"],[8,27,"כִּ֚י הַֽ⁠אֻמְנָ֔ם יֵשֵׁ֥ב אֱלֹהִ֖ים עַל־הָ⁠אָ֑רֶץ הִ֠נֵּה הַ⁠שָּׁמַ֜יִם וּ⁠שְׁמֵ֤י הַ⁠שָּׁמַ֨יִם֙ לֹ֣א יְכַלְכְּל֔וּ⁠ךָ אַ֕ף כִּֽי־הַ⁠בַּ֥יִת הַ⁠זֶּ֖ה אֲשֶׁ֥ר בָּנִֽיתִי׃","ki֚̇y haֽ⁠ʼumĕná֔m yéşé֥̌b ʼèlòhi֖ym ʻal-há⁠ʼá֑reẕ hi֠né̇h ha⁠şá̇̌ma֜yim ẇ⁠şĕ̌mé֤y ha⁠şá̇̌ma֨yim֙ lò֣ʼ yĕkalĕkĕ̇l֔ẇ⁠ká ʼa֕p kiֽ̇y-ha⁠bȧ֥yiţ ha⁠zė֖h ʼàşě֥r bá̇niֽyţiy׃"],[8,28,"וּ⁠פָנִ֜יתָ אֶל־תְּפִלַּ֧ת עַבְדְּ⁠ךָ֛ וְ⁠אֶל־תְּחִנָּת֖⁠וֹ יְהוָ֣ה אֱלֹהָ֑⁠י לִ⁠שְׁמֹ֤עַ אֶל־הָֽ⁠רִנָּה֙ וְ⁠אֶל־הַ⁠תְּפִלָּ֔ה אֲשֶׁ֧ר עַבְדְּ⁠ךָ֛ מִתְפַּלֵּ֥ל לְ⁠פָנֶ֖י⁠ךָ הַ⁠יּֽוֹם׃","ẇ⁠páni֜yţá ʼel-ţĕ̇pilȧ֧ţ ʻabĕdĕ̇⁠ká֛ wĕ⁠ʼel-ţĕ̇ẖiná̇ţ֖⁠wò yĕhwá֣h ʼèlòhá֑⁠y li⁠şĕ̌mò֤ʻa ʼel-háֽ⁠riná̇h֙ wĕ⁠ʼel-ha⁠ţĕ̇pilá̇֔h ʼàşě֧r ʻabĕdĕ̇⁠ká֛ miţĕpȧlé֥̇l lĕ⁠páne֖y⁠ká ha⁠ẏֽwòm׃"],[8,29,"לִ⁠הְיוֹת֩ עֵינֶ֨⁠ךָ פְתֻח֜וֹת אֶל־הַ⁠בַּ֤יִת הַ⁠זֶּה֙ לַ֣יְלָה וָ⁠י֔וֹם אֶל־הַ֨⁠מָּק֔וֹם אֲשֶׁ֣ר אָמַ֔רְתָּ יִהְיֶ֥ה שְׁמִ֖⁠י שָׁ֑ם לִ⁠שְׁמֹ֨עַ֙ אֶל־הַ⁠תְּפִלָּ֔ה אֲשֶׁ֣ר יִתְפַּלֵּ֣ל עַבְדְּ⁠ךָ֔ אֶל־הַ⁠מָּק֖וֹם הַ⁠זֶּֽה׃","li⁠hĕywòţ֩ ʻéyne֨⁠ká pĕţuẖ֜wòţ ʼel-ha⁠bȧ֤yiţ ha⁠zėh֙ la֣yĕláh wá⁠y֔wòm ʼel-ha֨⁠má̇q֔wòm ʼàşě֣r ʼáma֔rĕţá̇ yihĕye֥h şĕ̌mi֖⁠y şá֑̌m li⁠şĕ̌mò֨ʻa֙ ʼel-ha⁠ţĕ̇pilá̇֔h ʼàşě֣r yiţĕpȧlé֣̇l ʻabĕdĕ̇⁠ká֔ ʼel-ha⁠má̇q֖wòm ha⁠zėֽh׃"],[8,30,"וְ⁠שָׁ֨מַעְתָּ֜ אֶל־תְּחִנַּ֤ת עַבְדְּ⁠ךָ֙ וְ⁠עַמְּ⁠ךָ֣ יִשְׂרָאֵ֔ל אֲשֶׁ֥ר יִֽתְפַּֽלְל֖וּ אֶל־הַ⁠מָּק֣וֹם הַ⁠זֶּ֑ה וְ֠⁠אַתָּה תִּשְׁמַ֞ע אֶל־מְק֤וֹם שִׁבְתְּ⁠ךָ֙ אֶל־הַ⁠שָּׁמַ֔יִם וְ⁠שָׁמַעְתָּ֖ וְ⁠סָלָֽחְתָּ׃","wĕ⁠şá̌֨maʻĕţá̇֜ ʼel-ţĕ̇ẖinȧ֤ţ ʻabĕdĕ̇⁠ká֙ wĕ⁠ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֔l ʼàşě֥r yiֽţĕpȧֽlĕl֖ẇ ʼel-ha⁠má̇q֣wòm ha⁠zė֑h wĕ֠⁠ʼaţá̇h ţi̇şĕ̌ma֞ʻ ʼel-mĕq֤wòm şǐbĕţĕ̇⁠ká֙ ʼel-ha⁠şá̇̌ma֔yim wĕ⁠şá̌maʻĕţá֖̇ wĕ⁠sáláֽẖĕţá̇׃"],[8,31,"אֵת֩ אֲשֶׁ֨ר יֶחֱטָ֥א אִישׁ֙ לְ⁠רֵעֵ֔⁠הוּ וְ⁠נָֽשָׁא־ב֥⁠וֹ אָלָ֖ה לְ⁠הַֽאֲלֹת֑⁠וֹ וּ⁠בָ֗א אָלָ֛ה לִ⁠פְנֵ֥י מִֽזְבַּחֲ⁠ךָ֖ בַּ⁠בַּ֥יִת הַ⁠זֶּֽה׃","ʼéţ֩ ʼàşě֨r yeẖètá֥ʼ ʼiyş̌֙ lĕ⁠réʻé֔⁠hẇ wĕ⁠náֽşá̌ʼ-b֥⁠wò ʼálá֖h lĕ⁠haֽʼàlòţ֑⁠wò ẇ⁠bá֗ʼ ʼálá֛h li⁠pĕné֥y miֽzĕbȧẖà⁠ká֖ bȧ⁠bȧ֥yiţ ha⁠zėֽh׃"],[8,32,"וְ⁠אַתָּ֣ה ׀ תִּשְׁמַ֣ע הַ⁠שָּׁמַ֗יִם וְ⁠עָשִׂ֨יתָ֙ וְ⁠שָׁפַטְתָּ֣ אֶת־עֲבָדֶ֔י⁠ךָ לְ⁠הַרְשִׁ֣יעַ רָשָׁ֔ע לָ⁠תֵ֥ת דַּרְכּ֖⁠וֹ בְּ⁠רֹאשׁ֑⁠וֹ וּ⁠לְ⁠הַצְדִּ֣יק צַדִּ֔יק לָ֥⁠תֶת ל֖⁠וֹ כְּ⁠צִדְקָתֽ⁠וֹ׃ס","wĕ⁠ʼaţá֣̇h ׀ ţi̇şĕ̌ma֣ʻ ha⁠şá̇̌ma֗yim wĕ⁠ʻáşî֨yţá֙ wĕ⁠şá̌patĕţá֣̇ ʼeţ-ʻàbáde֔y⁠ká lĕ⁠harĕşǐ֣yʻa ráşá̌֔ʻ lá⁠ţé֥ţ dȧrĕk֖̇⁠wò bĕ̇⁠ròʼş֑̌⁠wò ẇ⁠lĕ⁠haẕĕdi֣̇yq ẕadi̇֔yq lá֥⁠ţeţ l֖⁠wò kĕ̇⁠ẕidĕqáţֽ⁠wò׃s"],[8,33,"בְּֽ⁠הִנָּגֵ֞ף עַמְּ⁠ךָ֧ יִשְׂרָאֵ֛ל לִ⁠פְנֵ֥י אוֹיֵ֖ב אֲשֶׁ֣ר יֶחֶטְאוּ־לָ֑⁠ךְ וְ⁠שָׁ֤בוּ אֵלֶ֨י⁠ךָ֙ וְ⁠הוֹד֣וּ אֶת־שְׁמֶ֔⁠ךָ וְ⁠הִֽתְפַּֽלְל֧וּ וְ⁠הִֽתְחַנְּנ֛וּ אֵלֶ֖י⁠ךָ בַּ⁠בַּ֥יִת הַ⁠זֶּֽה׃","bĕֽ̇⁠hiná̇gé֞p ʻamĕ̇⁠ká֧ yişĕ̂ráʼé֛l li⁠pĕné֥y ʼwòyé֖b ʼàşě֣r yeẖetĕʼẇ-lá֑⁠kĕ wĕ⁠şá֤̌bẇ ʼéle֨y⁠ká֙ wĕ⁠hwòd֣ẇ ʼeţ-şĕ̌me֔⁠ká wĕ⁠hiֽţĕpȧֽlĕl֧ẇ wĕ⁠hiֽţĕẖanĕ̇n֛ẇ ʼéle֖y⁠ká bȧ⁠bȧ֥yiţ ha⁠zėֽh׃"],[8,34,"וְ⁠אַתָּה֙ תִּשְׁמַ֣ע הַ⁠שָּׁמַ֔יִם וְ⁠סָ֣לַחְתָּ֔ לְ⁠חַטַּ֖את עַמְּ⁠ךָ֣ יִשְׂרָאֵ֑ל וַ⁠הֲשֵֽׁבֹתָ⁠ם֙ אֶל־הָ֣⁠אֲדָמָ֔ה אֲשֶׁ֥ר נָתַ֖תָּ לַ⁠אֲבוֹתָֽ⁠ם׃ס","wĕ⁠ʼaţá̇h֙ ţi̇şĕ̌ma֣ʻ ha⁠şá̇̌ma֔yim wĕ⁠sá֣laẖĕţá̇֔ lĕ⁠ẖatȧ֖ʼţ ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֑l wa⁠hàşéֽ̌bòţá⁠m֙ ʼel-há֣⁠ʼàdámá֔h ʼàşě֥r náţa֖ţá̇ la⁠ʼàbwòţáֽ⁠m׃s"],[8,35,"בְּ⁠הֵעָצֵ֥ר שָׁמַ֛יִם וְ⁠לֹא־יִהְיֶ֥ה מָטָ֖ר כִּ֣י יֶחֶטְאוּ־לָ֑⁠ךְ וְ⁠הִֽתְפַּֽלְל֞וּ אֶל־הַ⁠מָּק֤וֹם הַ⁠זֶּה֙ וְ⁠הוֹד֣וּ אֶת־שְׁמֶ֔⁠ךָ וּ⁠מֵ⁠חַטָּאתָ֥⁠ם יְשׁוּב֖וּ⁠ן כִּ֥י תַעֲנֵֽ⁠ם׃","bĕ̇⁠héʻáẕé֥r şá̌ma֛yim wĕ⁠lòʼ-yihĕye֥h mátá֖r ki֣̇y yeẖetĕʼẇ-lá֑⁠kĕ wĕ⁠hiֽţĕpȧֽlĕl֞ẇ ʼel-ha⁠má̇q֤wòm ha⁠zėh֙ wĕ⁠hwòd֣ẇ ʼeţ-şĕ̌me֔⁠ká ẇ⁠mé⁠ẖatá̇ʼţá֥⁠m yĕş̌ẇb֖ẇ⁠n ki֥̇y ţaʻànéֽ⁠m׃"],[8,36,"וְ⁠אַתָּ֣ה ׀ תִּשְׁמַ֣ע הַ⁠שָּׁמַ֗יִם וְ⁠סָ֨לַחְתָּ֜ לְ⁠חַטַּ֤את עֲבָדֶ֨י⁠ךָ֙ וְ⁠עַמְּ⁠ךָ֣ יִשְׂרָאֵ֔ל כִּ֥י תוֹרֵ֛⁠ם אֶת־הַ⁠דֶּ֥רֶךְ הַ⁠טּוֹבָ֖ה אֲשֶׁ֣ר יֵֽלְכוּ־בָ֑⁠הּ וְ⁠נָתַתָּ֤ה מָטָר֙ עַל־אַרְצְ⁠ךָ֔ אֲשֶׁר־נָתַ֥תָּה לְ⁠עַמְּ⁠ךָ֖ לְ⁠נַחֲלָֽה׃ס","wĕ⁠ʼaţá֣̇h ׀ ţi̇şĕ̌ma֣ʻ ha⁠şá̇̌ma֗yim wĕ⁠sá֨laẖĕţá̇֜ lĕ⁠ẖatȧ֤ʼţ ʻàbáde֨y⁠ká֙ wĕ⁠ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֔l ki֥̇y ţwòré֛⁠m ʼeţ-ha⁠dė֥rekĕ ha⁠ṫwòbá֖h ʼàşě֣r yֽélĕkẇ-bá֑⁠ḣ wĕ⁠náţaţá֤̇h mátár֙ ʻal-ʼarĕẕĕ⁠ká֔ ʼàşěr-náţa֥ţá̇h lĕ⁠ʻamĕ̇⁠ká֖ lĕ⁠naẖàláֽh׃s"],[8,37,"רָעָ֞ב כִּֽי־יִהְיֶ֣ה בָ⁠אָ֗רֶץ דֶּ֣בֶר כִּֽי־יִ֠הְיֶה שִׁדָּפ֨וֹן יֵרָק֜וֹן אַרְבֶּ֤ה חָסִיל֙ כִּ֣י יִהְיֶ֔ה כִּ֧י יָֽצַר־ל֛⁠וֹ אֹיְב֖⁠וֹ בְּ⁠אֶ֣רֶץ שְׁעָרָ֑י⁠ו כָּל־נֶ֖גַע כָּֽל־מַחֲלָֽה׃","ráʻá֞b kiֽ̇y-yihĕye֣h bá⁠ʼá֗reẕ dė֣ber kiֽ̇y-yi֠hĕyeh şǐdá̇p֨wòn yéráq֜wòn ʼarĕbė֤h ẖásiyl֙ ki֣̇y yihĕye֔h ki֧̇y yáֽẕar-l֛⁠wò ʼòyĕb֖⁠wò bĕ̇⁠ʼe֣reẕ şĕ̌ʻárá֑y⁠w ká̇l-ne֖gaʻ káֽ̇l-maẖàláֽh׃"],[8,38,"כָּל־תְּפִלָּ֣ה כָל־תְּחִנָּ֗ה אֲשֶׁ֤ר תִֽהְיֶה֙ לְ⁠כָל־הָ֣⁠אָדָ֔ם לְ⁠כֹ֖ל עַמְּ⁠ךָ֣ יִשְׂרָאֵ֑ל אֲשֶׁ֣ר יֵדְע֗וּ⁠ן אִ֚ישׁ נֶ֣גַע לְבָב֔⁠וֹ וּ⁠פָרַ֥שׂ כַּפָּ֖י⁠ו אֶל־הַ⁠בַּ֥יִת הַ⁠זֶּֽה׃","ká̇l-ţĕ̇pilá֣̇h kál-ţĕ̇ẖiná̇֗h ʼàşě֤r ţiֽhĕyeh֙ lĕ⁠kál-há֣⁠ʼádá֔m lĕ⁠kò֖l ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֑l ʼàşě֣r yédĕʻ֗ẇ⁠n ʼi֚yş̌ ne֣gaʻ lĕbáb֔⁠wò ẇ⁠pára֥ş̂ kȧpá֖̇y⁠w ʼel-ha⁠bȧ֥yiţ ha⁠zėֽh׃"],[8,39,"וְ֠⁠אַתָּה תִּשְׁמַ֨ע הַ⁠שָּׁמַ֜יִם מְכ֤וֹן שִׁבְתֶּ֨⁠ךָ֙ וְ⁠סָלַחְתָּ֣ וְ⁠עָשִׂ֔יתָ וְ⁠נָתַתָּ֤ לָ⁠אִישׁ֙ כְּ⁠כָל־דְּרָכָ֔י⁠ו אֲשֶׁ֥ר תֵּדַ֖ע אֶת־לְבָב֑⁠וֹ כִּֽי־אַתָּ֤ה יָדַ֨עְתָּ֙ לְ⁠בַדְּ⁠ךָ֔ אֶת־לְבַ֖ב כָּל־בְּנֵ֥י הָ⁠אָדָֽם׃","wĕ֠⁠ʼaţá̇h ţi̇şĕ̌ma֨ʻ ha⁠şá̇̌ma֜yim mĕk֤wòn şǐbĕţė֨⁠ká֙ wĕ⁠sálaẖĕţá֣̇ wĕ⁠ʻáşî֔yţá wĕ⁠náţaţá֤̇ lá⁠ʼiyş̌֙ kĕ̇⁠kál-dĕ̇ráká֔y⁠w ʼàşě֥r ţé̇da֖ʻ ʼeţ-lĕbáb֑⁠wò kiֽ̇y-ʼaţá֤̇h yáda֨ʻĕţá̇֙ lĕ⁠badĕ̇⁠ká֔ ʼeţ-lĕba֖b ká̇l-bĕ̇né֥y há⁠ʼádáֽm׃"],[8,40,"לְמַ֨עַן֙ יִֽרָא֔וּ⁠ךָ כָּל־הַ֨⁠יָּמִ֔ים אֲשֶׁר־הֵ֥ם חַיִּ֖ים עַל־פְּנֵ֣י הָ⁠אֲדָמָ֑ה אֲשֶׁ֥ר נָתַ֖תָּה לַ⁠אֲבֹתֵֽי⁠נוּ׃","lĕma֨ʻan֙ yiֽráʼ֔ẇ⁠ká ká̇l-ha֨⁠yá̇mi֔ym ʼàşěr-hé֥m ẖayi֖̇ym ʻal-pĕ̇né֣y há⁠ʼàdámá֑h ʼàşě֥r náţa֖ţá̇h la⁠ʼàbòţéֽy⁠nẇ׃"],[8,41,"וְ⁠גַם֙ אֶל־הַ⁠נָּכְרִ֔י אֲשֶׁ֛ר לֹא־מֵ⁠עַמְּ⁠ךָ֥ יִשְׂרָאֵ֖ל ה֑וּא וּ⁠בָ֛א מֵ⁠אֶ֥רֶץ רְחוֹקָ֖ה לְמַ֥עַן שְׁמֶֽ⁠ךָ׃","wĕ⁠gam֙ ʼel-ha⁠ná̇kĕri֔y ʼàşě֛r lòʼ-mé⁠ʻamĕ̇⁠ká֥ yişĕ̂ráʼé֖l h֑ẇʼ ẇ⁠bá֛ʼ mé⁠ʼe֥reẕ rĕẖwòqá֖h lĕma֥ʻan şĕ̌meֽ⁠ká׃"],[8,42,"כִּ֤י יִשְׁמְעוּ⁠ן֙ אֶת־שִׁמְ⁠ךָ֣ הַ⁠גָּד֔וֹל וְ⁠אֶת־יָֽדְ⁠ךָ֙ הַֽ⁠חֲזָקָ֔ה וּֽ⁠זְרֹעֲ⁠ךָ֖ הַ⁠נְּטוּיָ֑ה וּ⁠בָ֥א וְ⁠הִתְפַּלֵּ֖ל אֶל־הַ⁠בַּ֥יִת הַ⁠זֶּֽה׃","ki֤̇y yişĕ̌mĕʻẇ⁠n֙ ʼeţ-şǐmĕ⁠ká֣ ha⁠gá̇d֔wòl wĕ⁠ʼeţ-yáֽdĕ⁠ká֙ hֽa⁠ẖàzáqá֔h ẇֽ⁠zĕròʻà⁠ká֖ ha⁠nĕ̇tẇyá֑h ẇ⁠bá֥ʼ wĕ⁠hiţĕpȧlé֖̇l ʼel-ha⁠bȧ֥yiţ ha⁠zėֽh׃"],[8,43,"אַתָּ֞ה תִּשְׁמַ֤ע הַ⁠שָּׁמַ֨יִם֙ מְכ֣וֹן שִׁבְתֶּ֔⁠ךָ וְ⁠עָשִׂ֕יתָ כְּ⁠כֹ֛ל אֲשֶׁר־יִקְרָ֥א אֵלֶ֖י⁠ךָ הַ⁠נָּכְרִ֑י לְמַ֣עַן יֵדְעוּ⁠ן֩ כָּל־עַמֵּ֨י הָ⁠אָ֜רֶץ אֶת־שְׁמֶ֗⁠ךָ לְ⁠יִרְאָ֤ה אֹֽתְ⁠ךָ֙ כְּ⁠עַמְּ⁠ךָ֣ יִשְׂרָאֵ֔ל וְ⁠לָ⁠דַ֕עַת כִּי־שִׁמְ⁠ךָ֣ נִקְרָ֔א עַל־הַ⁠בַּ֥יִת הַ⁠זֶּ֖ה אֲשֶׁ֥ר בָּנִֽיתִי׃","ʼaţá̇֞h ţi̇şĕ̌ma֤ʻ ha⁠şá̇̌ma֨yim֙ mĕk֣wòn şǐbĕţė֔⁠ká wĕ⁠ʻáşî֕yţá kĕ̇⁠kò֛l ʼàşěr-yiqĕrá֥ʼ ʼéle֖y⁠ká ha⁠ná̇kĕri֑y lĕma֣ʻan yédĕʻẇ⁠n֩ ká̇l-ʻamé̇֨y há⁠ʼá֜reẕ ʼeţ-şĕ̌me֗⁠ká lĕ⁠yirĕʼá֤h ʼòֽţĕ⁠ká֙ kĕ̇⁠ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֔l wĕ⁠lá⁠da֕ʻaţ ki̇y-şǐmĕ⁠ká֣ niqĕrá֔ʼ ʻal-ha⁠bȧ֥yiţ ha⁠zė֖h ʼàşě֥r bá̇niֽyţiy׃"],[8,44,"כִּי־יֵצֵ֨א עַמְּ⁠ךָ֤ לַ⁠מִּלְחָמָה֙ עַל־אֹ֣יְב֔⁠וֹ בַּ⁠דֶּ֖רֶךְ אֲשֶׁ֣ר תִּשְׁלָחֵ֑⁠ם וְ⁠הִתְפַּֽלְל֣וּ אֶל־יְהוָ֗ה דֶּ֤רֶךְ הָ⁠עִיר֙ אֲשֶׁ֣ר בָּחַ֣רְתָּ בָּ֔⁠הּ וְ⁠הַ⁠בַּ֖יִת אֲשֶׁר־בָּנִ֥תִי לִ⁠שְׁמֶֽ⁠ךָ׃","ki̇y-yéẕé֨ʼ ʻamĕ̇⁠ká֤ la⁠mi̇lĕẖámáh֙ ʻal-ʼò֣yĕb֔⁠wò bȧ⁠dė֖rekĕ ʼàşě֣r ţi̇şĕ̌láẖé֑⁠m wĕ⁠hiţĕpȧֽlĕl֣ẇ ʼel-yĕhwá֗h dė֤rekĕ há⁠ʻiyr֙ ʼàşě֣r bá̇ẖa֣rĕţá̇ bá̇֔⁠ḣ wĕ⁠ha⁠bȧ֖yiţ ʼàşěr-bá̇ni֥ţiy li⁠şĕ̌meֽ⁠ká׃"],[8,45,"וְ⁠שָׁמַעְתָּ֙ הַ⁠שָּׁמַ֔יִם אֶת־תְּפִלָּתָ֖⁠ם וְ⁠אֶת־תְּחִנָּתָ֑⁠ם וְ⁠עָשִׂ֖יתָ מִשְׁפָּטָֽ⁠ם׃","wĕ⁠şá̌maʻĕţá̇֙ ha⁠şá̇̌ma֔yim ʼeţ-ţĕ̇pilá̇ţá֖⁠m wĕ⁠ʼeţ-ţĕ̇ẖiná̇ţá֑⁠m wĕ⁠ʻáşî֖yţá mişĕ̌pá̇táֽ⁠m׃"],[8,46,"כִּ֣י יֶֽחֶטְאוּ־לָ֗⁠ךְ כִּ֣י אֵ֤ין אָדָם֙ אֲשֶׁ֣ר לֹא־יֶחֱטָ֔א וְ⁠אָנַפְתָּ֣ בָ֔⁠ם וּ⁠נְתַתָּ֖⁠ם לִ⁠פְנֵ֣י אוֹיֵ֑ב וְ⁠שָׁב֤וּ⁠ם שֹֽׁבֵי⁠הֶם֙ אֶל־אֶ֣רֶץ הָ⁠אוֹיֵ֔ב רְחוֹקָ֖ה א֥וֹ קְרוֹבָֽה׃","ki֣̇y yeֽẖetĕʼẇ-lá֗⁠kĕ ki֣̇y ʼé֤yn ʼádám֙ ʼàşě֣r lòʼ-yeẖètá֔ʼ wĕ⁠ʼánapĕţá֣̇ bá֔⁠m ẇ⁠nĕţaţá֖̇⁠m li⁠pĕné֣y ʼwòyé֑b wĕ⁠şá̌b֤ẇ⁠m şòֽ̌béy⁠hem֙ ʼel-ʼe֣reẕ há⁠ʼwòyé֔b rĕẖwòqá֖h ʼ֥wò qĕrwòbáֽh׃"],[8,47,"וְ⁠הֵשִׁ֨יבוּ֙ אֶל־לִבָּ֔⁠ם בָּ⁠אָ֖רֶץ אֲשֶׁ֣ר נִשְׁבּוּ־שָׁ֑ם וְ⁠שָׁ֣בוּ ׀ וְ⁠הִֽתְחַנְּנ֣וּ אֵלֶ֗י⁠ךָ בְּ⁠אֶ֤רֶץ שֹֽׁבֵי⁠הֶם֙ לֵ⁠אמֹ֔ר חָטָ֥אנוּ וְ⁠הֶעֱוִ֖ינוּ רָשָֽׁעְנוּ׃","wĕ⁠héşǐ֨ybẇ֙ ʼel-libá̇֔⁠m bá̇⁠ʼá֖reẕ ʼàşě֣r nişĕ̌ḃẇ-şá֑̌m wĕ⁠şá֣̌bẇ ׀ wĕ⁠hiֽţĕẖanĕ̇n֣ẇ ʼéle֗y⁠ká bĕ̇⁠ʼe֤reẕ şòֽ̌béy⁠hem֙ lé⁠ʼmò֔r ẖátá֥ʼnẇ wĕ⁠heʻèwi֖ynẇ ráşáֽ̌ʻĕnẇ׃"],[8,48,"וְ⁠שָׁ֣בוּ אֵלֶ֗י⁠ךָ בְּ⁠כָל־לְבָבָ⁠ם֙ וּ⁠בְ⁠כָל־נַפְשָׁ֔⁠ם בְּ⁠אֶ֥רֶץ אֹיְבֵי⁠הֶ֖ם אֲשֶׁר־שָׁב֣וּ אֹתָ֑⁠ם וְ⁠הִֽתְפַּֽלְל֣וּ אֵלֶ֗י⁠ךָ דֶּ֤רֶךְ אַרְצָ⁠ם֙ אֲשֶׁ֣ר נָתַ֣תָּה לַ⁠אֲבוֹתָ֔⁠ם הָ⁠עִיר֙ אֲשֶׁ֣ר בָּחַ֔רְתָּ וְ⁠הַ⁠בַּ֖יִת אֲשֶׁר־בנית לִ⁠שְׁמֶֽ⁠ךָ׃","wĕ⁠şá֣̌bẇ ʼéle֗y⁠ká bĕ̇⁠kál-lĕbábá⁠m֙ ẇ⁠bĕ⁠kál-napĕşá̌֔⁠m bĕ̇⁠ʼe֥reẕ ʼòyĕbéy⁠he֖m ʼàşěr-şá̌b֣ẇ ʼòţá֑⁠m wĕ⁠hiֽţĕpȧֽlĕl֣ẇ ʼéle֗y⁠ká dė֤rekĕ ʼarĕẕá⁠m֙ ʼàşě֣r náţa֣ţá̇h la⁠ʼàbwòţá֔⁠m há⁠ʻiyr֙ ʼàşě֣r bá̇ẖa֔rĕţá̇ wĕ⁠ha⁠bȧ֖yiţ ʼàşěr-bnyţ li⁠şĕ̌meֽ⁠ká׃"],[8,49,"וְ⁠שָׁמַעְתָּ֤ הַ⁠שָּׁמַ֨יִם֙ מְכ֣וֹן שִׁבְתְּ⁠ךָ֔ אֶת־תְּפִלָּתָ֖⁠ם וְ⁠אֶת־תְּחִנָּתָ֑⁠ם וְ⁠עָשִׂ֖יתָ מִשְׁפָּטָֽ⁠ם׃","wĕ⁠şá̌maʻĕţá֤̇ ha⁠şá̇̌ma֨yim֙ mĕk֣wòn şǐbĕţĕ̇⁠ká֔ ʼeţ-ţĕ̇pilá̇ţá֖⁠m wĕ⁠ʼeţ-ţĕ̇ẖiná̇ţá֑⁠m wĕ⁠ʻáşî֖yţá mişĕ̌pá̇táֽ⁠m׃"],[8,50,"וְ⁠סָלַחְתָּ֤ לְ⁠עַמְּ⁠ךָ֙ אֲשֶׁ֣ר חָֽטְאוּ־לָ֔⁠ךְ וּ⁠לְ⁠כָל־פִּשְׁעֵי⁠הֶ֖ם אֲשֶׁ֣ר פָּשְׁעוּ־בָ֑⁠ךְ וּ⁠נְתַתָּ֧⁠ם לְ⁠רַחֲמִ֛ים לִ⁠פְנֵ֥י שֹׁבֵי⁠הֶ֖ם וְ⁠רִֽחֲמֽוּ⁠ם׃","wĕ⁠sálaẖĕţá֤̇ lĕ⁠ʻamĕ̇⁠ká֙ ʼàşě֣r ẖáֽtĕʼẇ-lá֔⁠kĕ ẇ⁠lĕ⁠kál-pi̇şĕ̌ʻéy⁠he֖m ʼàşě֣r pá̇şĕ̌ʻẇ-bá֑⁠kĕ ẇ⁠nĕţaţá֧̇⁠m lĕ⁠raẖàmi֛ym li⁠pĕné֥y şò̌béy⁠he֖m wĕ⁠riֽẖàmֽẇ⁠m׃"],[8,51,"כִּֽי־עַמְּ⁠ךָ֥ וְ⁠נַחֲלָתְ⁠ךָ֖ הֵ֑ם אֲשֶׁ֤ר הוֹצֵ֨אתָ֙ מִ⁠מִּצְרַ֔יִם מִ⁠תּ֖וֹךְ כּ֥וּר הַ⁠בַּרְזֶֽל׃","kiֽ̇y-ʻamĕ̇⁠ká֥ wĕ⁠naẖàláţĕ⁠ká֖ hé֑m ʼàşě֤r hwòẕé֨ʼţá֙ mi⁠mi̇ẕĕra֔yim mi⁠ţ֖̇wòkĕ k֥̇ẇr ha⁠bȧrĕzeֽl׃"],[8,52,"לִ⁠הְי֨וֹת עֵינֶ֤י⁠ךָ פְתֻחוֹת֙ אֶל־תְּחִנַּ֣ת עַבְדְּ⁠ךָ֔ וְ⁠אֶל־תְּחִנַּ֖ת עַמְּ⁠ךָ֣ יִשְׂרָאֵ֑ל לִ⁠שְׁמֹ֣עַ אֲלֵי⁠הֶ֔ם בְּ⁠כֹ֖ל קָרְאָ֥⁠ם אֵלֶֽי⁠ךָ׃","li⁠hĕy֨wòţ ʻéyne֤y⁠ká pĕţuẖwòţ֙ ʼel-ţĕ̇ẖinȧ֣ţ ʻabĕdĕ̇⁠ká֔ wĕ⁠ʼel-ţĕ̇ẖinȧ֖ţ ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֑l li⁠şĕ̌mò֣ʻa ʼàléy⁠he֔m bĕ̇⁠kò֖l qárĕʼá֥⁠m ʼéleֽy⁠ká׃"],[8,53,"כִּֽי־אַתָּ֞ה הִבְדַּלְתָּ֤⁠ם לְ⁠ךָ֙ לְֽ⁠נַחֲלָ֔ה מִ⁠כֹּ֖ל עַמֵּ֣י הָ⁠אָ֑רֶץ כַּ⁠אֲשֶׁ֨ר דִּבַּ֜רְתָּ בְּ⁠יַ֣ד ׀ מֹשֶׁ֣ה עַבְדֶּ֗⁠ךָ בְּ⁠הוֹצִיאֲ⁠ךָ֧ אֶת־אֲבֹתֵ֛י⁠נוּ מִ⁠מִּצְרַ֖יִם אֲדֹנָ֥⁠י יְהוִֽה׃פ","kiֽ̇y-ʼaţá̇֞h hibĕdȧlĕţá֤̇⁠m lĕ⁠ká֙ lĕֽ⁠naẖàlá֔h mi⁠kò֖̇l ʻamé֣̇y há⁠ʼá֑reẕ kȧ⁠ʼàşě֨r di̇bȧ֜rĕţá̇ bĕ̇⁠ya֣d ׀ mòşě֣h ʻabĕdė֗⁠ká bĕ̇⁠hwòẕiyʼà⁠ká֧ ʼeţ-ʼàbòţé֛y⁠nẇ mi⁠mi̇ẕĕra֖yim ʼàdòná֥⁠y yĕhwiֽh׃p"],[8,54,"וַ⁠יְהִ֣י ׀ כְּ⁠כַלּ֣וֹת שְׁלֹמֹ֗ה לְ⁠הִתְפַּלֵּל֙ אֶל־יְהוָ֔ה אֵ֛ת כָּל־הַ⁠תְּפִלָּ֥ה וְ⁠הַ⁠תְּחִנָּ֖ה הַ⁠זֹּ֑את קָ֞ם מִ⁠לִּ⁠פְנֵ֨י מִזְבַּ֤ח יְהוָה֙ מִ⁠כְּרֹ֣עַ עַל־בִּרְכָּ֔י⁠ו וְ⁠כַפָּ֖י⁠ו פְּרֻשׂ֥וֹת הַ⁠שָּׁמָֽיִם׃","wa⁠yĕhi֣y ׀ kĕ̇⁠kal֣̇wòţ şĕ̌lòmò֗h lĕ⁠hiţĕpȧlé̇l֙ ʼel-yĕhwá֔h ʼé֛ţ ká̇l-ha⁠ţĕ̇pilá֥̇h wĕ⁠ha⁠ţĕ̇ẖiná֖̇h ha⁠zò֑̇ʼţ qá֞m mi⁠li̇⁠pĕné֨y mizĕbȧ֤ẖ yĕhwáh֙ mi⁠kĕ̇rò֣ʻa ʻal-bi̇rĕká̇֔y⁠w wĕ⁠kapá֖̇y⁠w pĕ̇ruş֥̂wòţ ha⁠şá̇̌máֽyim׃"],[8,55,"וַֽ⁠יַּעְמֹ֕ד וַ⁠יְבָ֕רֶךְ אֵ֖ת כָּל־קְהַ֣ל יִשְׂרָאֵ֑ל ק֥וֹל גָּד֖וֹל לֵ⁠אמֹֽר׃","waֽ⁠yȧʻĕmò֕d wa⁠yĕbá֕rekĕ ʼé֖ţ ká̇l-qĕha֣l yişĕ̂ráʼé֑l q֥wòl gá̇d֖wòl lé⁠ʼmòֽr׃"],[8,56,"בָּר֣וּךְ יְהוָ֗ה אֲשֶׁ֨ר נָתַ֤ן מְנוּחָה֙ לְ⁠עַמּ֣⁠וֹ יִשְׂרָאֵ֔ל כְּ⁠כֹ֖ל אֲשֶׁ֣ר דִּבֵּ֑ר לֹֽא־נָפַ֞ל דָּבָ֣ר אֶחָ֗ד מִ⁠כֹּל֙ דְּבָר֣⁠וֹ הַ⁠טּ֔וֹב אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠יַ֖ד מֹשֶׁ֥ה עַבְדּֽ⁠וֹ׃","bá̇r֣ẇkĕ yĕhwá֗h ʼàşě֨r náţa֤n mĕnẇẖáh֙ lĕ⁠ʻaṁ֣⁠wò yişĕ̂ráʼé֔l kĕ̇⁠kò֖l ʼàşě֣r di̇bé֑̇r lòֽʼ-nápa֞l dá̇bá֣r ʼeẖá֗d mi⁠kò̇l֙ dĕ̇bár֣⁠wò ha⁠ṫ֔wòb ʼàşě֣r di̇bė֔r bĕ̇⁠ya֖d mòşě֥h ʻabĕḋֽ⁠wò׃"],[8,57,"יְהִ֨י יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ עִמָּ֔⁠נוּ כַּ⁠אֲשֶׁ֥ר הָיָ֖ה עִם־אֲבֹתֵ֑י⁠נוּ אַל־יַעַזְבֵ֖⁠נוּ וְ⁠אַֽל־יִטְּשֵֽׁ⁠נוּ׃","yĕhi֨y yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ ʻimá̇֔⁠nẇ kȧ⁠ʼàşě֥r háyá֖h ʻim-ʼàbòţé֑y⁠nẇ ʼal-yaʻazĕbé֖⁠nẇ wĕ⁠ʼaֽl-yitĕ̇şéֽ̌⁠nẇ׃"],[8,58,"לְ⁠הַטּ֥וֹת לְבָבֵ֖⁠נוּ אֵלָ֑י⁠ו לָ⁠לֶ֣כֶת בְּ⁠כָל־דְּרָכָ֗י⁠ו וְ⁠לִ⁠שְׁמֹ֨ר מִצְוֺתָ֤י⁠ו וְ⁠חֻקָּי⁠ו֙ וּ⁠מִשְׁפָּטָ֔י⁠ו אֲשֶׁ֥ר צִוָּ֖ה אֶת־אֲבֹתֵֽי⁠נוּ׃","lĕ⁠haṫ֥wòţ lĕbábé֖⁠nẇ ʼélá֑y⁠w lá⁠le֣keţ bĕ̇⁠kál-dĕ̇ráká֗y⁠w wĕ⁠li⁠şĕ̌mò֨r miẕĕwֺţá֤y⁠w wĕ⁠ẖuqá̇y⁠w֙ ẇ⁠mişĕ̌pá̇tá֔y⁠w ʼàşě֥r ẕiwá֖̇h ʼeţ-ʼàbòţéֽy⁠nẇ׃"],[8,59,"וְ⁠יִֽהְי֨וּ דְבָרַ֜⁠י אֵ֗לֶּה אֲשֶׁ֤ר הִתְחַנַּ֨נְתִּי֙ לִ⁠פְנֵ֣י יְהוָ֔ה קְרֹבִ֛ים אֶל־יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ יוֹמָ֣ם וָ⁠לָ֑יְלָה לַ⁠עֲשׂ֣וֹת ׀ מִשְׁפַּ֣ט עַבְדּ֗⁠וֹ וּ⁠מִשְׁפַּ֛ט עַמּ֥⁠וֹ יִשְׂרָאֵ֖ל דְּבַר־י֥וֹם בְּ⁠יוֹמֽ⁠וֹ׃","wĕ⁠yiֽhĕy֨ẇ dĕbára֜⁠y ʼé֗lėh ʼàşě֤r hiţĕẖanȧ֨nĕţi̇y֙ li⁠pĕné֣y yĕhwá֔h qĕròbi֛ym ʼel-yĕhwá֥h ʼèlòhé֖y⁠nẇ ywòmá֣m wá⁠lá֑yĕláh la⁠ʻàş֣̂wòţ ׀ mişĕ̌pȧ֣t ʻabĕḋ֗⁠wò ẇ⁠mişĕ̌pȧ֛t ʻaṁ֥⁠wò yişĕ̂ráʼé֖l dĕ̇bar-y֥wòm bĕ̇⁠ywòmֽ⁠wò׃"],[8,60,"לְמַ֗עַן דַּ֚עַת כָּל־עַמֵּ֣י הָ⁠אָ֔רֶץ כִּ֥י יְהוָ֖ה ה֣וּא הָ⁠אֱלֹהִ֑ים אֵ֖ין עֽוֹד׃","lĕma֗ʻan dȧ֚ʻaţ ká̇l-ʻamé֣̇y há⁠ʼá֔reẕ ki֥̇y yĕhwá֖h h֣ẇʼ há⁠ʼèlòhi֑ym ʼé֖yn ʻֽwòd׃"],[8,61,"וְ⁠הָיָ֤ה לְבַבְ⁠כֶם֙ שָׁלֵ֔ם עִ֖ם יְהוָ֣ה אֱלֹהֵ֑י⁠נוּ לָ⁠לֶ֧כֶת בְּ⁠חֻקָּ֛י⁠ו וְ⁠לִ⁠שְׁמֹ֥ר מִצְוֺתָ֖י⁠ו כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wĕ⁠háyá֤h lĕbabĕ⁠kem֙ şá̌lé֔m ʻi֖m yĕhwá֣h ʼèlòhé֑y⁠nẇ lá⁠le֧keţ bĕ̇⁠ẖuqá֛̇y⁠w wĕ⁠li⁠şĕ̌mò֥r miẕĕwֺţá֖y⁠w kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[8,62,"וְֽ⁠הַ⁠מֶּ֔לֶךְ וְ⁠כָל־יִשְׂרָאֵ֖ל עִמּ֑⁠וֹ זֹבְחִ֥ים זֶ֖בַח לִ⁠פְנֵ֥י יְהוָֽה׃","wĕֽ⁠ha⁠mė֔lekĕ wĕ⁠kál-yişĕ̂ráʼé֖l ʻiṁ֑⁠wò zòbĕẖi֥ym ze֖baẖ li⁠pĕné֥y yĕhwáֽh׃"],[8,63,"וַ⁠יִּזְבַּ֣ח שְׁלֹמֹ֗ה אֵ֣ת זֶ֣בַח הַ⁠שְּׁלָמִים֮ אֲשֶׁ֣ר זָבַ֣ח לַ⁠יהוָה֒ בָּקָ֗ר עֶשְׂרִ֤ים וּ⁠שְׁנַ֨יִם֙ אֶ֔לֶף וְ⁠צֹ֕אן מֵאָ֥ה וְ⁠עֶשְׂרִ֖ים אָ֑לֶף וַֽ⁠יַּחְנְכוּ֙ אֶת־בֵּ֣ית יְהוָ֔ה הַ⁠מֶּ֖לֶךְ וְ⁠כָל־בְּנֵ֥י יִשְׂרָאֵֽל׃","wa⁠yi̇zĕbȧ֣ẖ şĕ̌lòmò֗h ʼé֣ţ ze֣baẖ ha⁠şĕ̇̌lámiym֮ ʼàşě֣r zába֣ẖ la⁠yhwáh֒ bá̇qá֗r ʻeşĕ̂ri֤ym ẇ⁠şĕ̌na֨yim֙ ʼe֔lep wĕ⁠ẕò֕ʼn méʼá֥h wĕ⁠ʻeşĕ̂ri֖ym ʼá֑lep waֽ⁠yȧẖĕnĕkẇ֙ ʼeţ-bé֣̇yţ yĕhwá֔h ha⁠mė֖lekĕ wĕ⁠kál-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[8,64,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא קִדַּ֨שׁ הַ⁠מֶּ֜לֶךְ אֶת־תּ֣וֹךְ הֶ⁠חָצֵ֗ר אֲשֶׁר֙ לִ⁠פְנֵ֣י בֵית־יְהוָ֔ה כִּי־עָ֣שָׂה שָׁ֗ם אֶת־הָֽ⁠עֹלָה֙ וְ⁠אֶת־הַ⁠מִּנְחָ֔ה וְ⁠אֵ֖ת חֶלְבֵ֣י הַ⁠שְּׁלָמִ֑ים כִּֽי־מִזְבַּ֤ח הַ⁠נְּחֹ֨שֶׁת֙ אֲשֶׁ֣ר לִ⁠פְנֵ֣י יְהוָ֔ה קָטֹ֗ן מֵֽ⁠הָכִיל֙ אֶת־הָ⁠עֹלָ֣ה וְ⁠אֶת־הַ⁠מִּנְחָ֔ה וְ⁠אֵ֖ת חֶלְבֵ֥י הַ⁠שְּׁלָמִֽים׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ qidȧ֨ş̌ ha⁠mė֜lekĕ ʼeţ-ţ֣̇wòkĕ he⁠ẖáẕé֗r ʼàşěr֙ li⁠pĕné֣y béyţ-yĕhwá֔h ki̇y-ʻá֣şá̂h şá̌֗m ʼeţ-háֽ⁠ʻòláh֙ wĕ⁠ʼeţ-ha⁠mi̇nĕẖá֔h wĕ⁠ʼé֖ţ ẖelĕbé֣y ha⁠şĕ̇̌lámi֑ym kiֽ̇y-mizĕbȧ֤ẖ ha⁠nĕ̇ẖò֨şěţ֙ ʼàşě֣r li⁠pĕné֣y yĕhwá֔h qátò֗n méֽ⁠hákiyl֙ ʼeţ-há⁠ʻòlá֣h wĕ⁠ʼeţ-ha⁠mi̇nĕẖá֔h wĕ⁠ʼé֖ţ ẖelĕbé֥y ha⁠şĕ̇̌lámiֽym׃"],[8,65,"וַ⁠יַּ֣עַשׂ שְׁלֹמֹ֣ה בָֽ⁠עֵת־הַ⁠הִ֣יא ׀ אֶת־הֶ⁠חָ֡ג וְ⁠כָל־יִשְׂרָאֵ֣ל עִמּ⁠וֹ֩ קָהָ֨ל גָּד֜וֹל מִ⁠לְּב֥וֹא חֲמָ֣ת ׀ עַד־נַ֣חַל מִצְרַ֗יִם לִ⁠פְנֵי֙ יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ שִׁבְעַ֥ת יָמִ֖ים וְ⁠שִׁבְעַ֣ת יָמִ֑ים אַרְבָּעָ֥ה עָשָׂ֖ר יֽוֹם׃","wa⁠yȧ֣ʻaş̂ şĕ̌lòmò֣h báֽ⁠ʻéţ-ha⁠hi֣yʼ ׀ ʼeţ-he⁠ẖá֡g wĕ⁠kál-yişĕ̂ráʼé֣l ʻiṁ⁠wò֩ qáhá֨l gá̇d֜wòl mi⁠lĕ̇b֥wòʼ ẖàmá֣ţ ׀ ʻad-na֣ẖal miẕĕra֗yim li⁠pĕnéy֙ yĕhwá֣h ʼèlòhé֔y⁠nẇ şǐbĕʻa֥ţ yámi֖ym wĕ⁠şǐbĕʻa֣ţ yámi֑ym ʼarĕbá̇ʻá֥h ʻáşá֖̂r yֽwòm׃"],[8,66,"בַּ⁠יּ֤וֹם הַ⁠שְּׁמִינִי֙ שִׁלַּ֣ח אֶת־הָ⁠עָ֔ם וַֽ⁠יְבָרֲכ֖וּ אֶת־הַ⁠מֶּ֑לֶךְ וַ⁠יֵּלְכ֣וּ לְ⁠אָהֳלֵי⁠הֶ֗ם שְׂמֵחִים֙ וְ⁠ט֣וֹבֵי לֵ֔ב עַ֣ל כָּל־הַ⁠טּוֹבָ֗ה אֲשֶׁ֨ר עָשָׂ֤ה יְהוָה֙ לְ⁠דָוִ֣ד עַבְדּ֔⁠וֹ וּ⁠לְ⁠יִשְׂרָאֵ֖ל עַמּֽ⁠וֹ׃","bȧ⁠ẏ֤wòm ha⁠şĕ̇̌miyniy֙ şǐlȧ֣ẖ ʼeţ-há⁠ʻá֔m waֽ⁠yĕbáràk֖ẇ ʼeţ-ha⁠mė֑lekĕ wa⁠yé̇lĕk֣ẇ lĕ⁠ʼáholéy⁠he֗m şĕ̂méẖiym֙ wĕ⁠t֣wòbéy lé֔b ʻa֣l ká̇l-ha⁠ṫwòbá֗h ʼàşě֨r ʻáşá֤̂h yĕhwáh֙ lĕ⁠dáwi֣d ʻabĕḋ֔⁠wò ẇ⁠lĕ⁠yişĕ̂ráʼé֖l ʻaṁֽ⁠wò׃"],[9,1,"וַ⁠יְהִי֙ כְּ⁠כַלּ֣וֹת שְׁלֹמֹ֔ה לִ⁠בְנ֥וֹת אֶת־בֵּית־יְהוָ֖ה וְ⁠אֶת־בֵּ֣ית הַ⁠מֶּ֑לֶךְ וְ⁠אֵת֙ כָּל־חֵ֣שֶׁק שְׁלֹמֹ֔ה אֲשֶׁ֥ר חָפֵ֖ץ לַ⁠עֲשֽׂוֹת׃פ","wa⁠yĕhiy֙ kĕ̇⁠kal֣̇wòţ şĕ̌lòmò֔h li⁠bĕn֥wòţ ʼeţ-bé̇yţ-yĕhwá֖h wĕ⁠ʼeţ-bé֣̇yţ ha⁠mė֑lekĕ wĕ⁠ʼéţ֙ ká̇l-ẖé֣şěq şĕ̌lòmò֔h ʼàşě֥r ẖápé֖ẕ la⁠ʻàşֽ̂wòţ׃p"],[9,2,"וַ⁠יֵּרָ֧א יְהוָ֛ה אֶל־שְׁלֹמֹ֖ה שֵׁנִ֑ית כַּ⁠אֲשֶׁ֛ר נִרְאָ֥ה אֵלָ֖י⁠ו בְּ⁠גִבְעֽוֹן׃","wa⁠yé̇rá֧ʼ yĕhwá֛h ʼel-şĕ̌lòmò֖h şé̌ni֑yţ kȧ⁠ʼàşě֛r nirĕʼá֥h ʼélá֖y⁠w bĕ̇⁠gibĕʻֽwòn׃"],[9,3,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלָ֗י⁠ו שָׁ֠מַעְתִּי אֶת־תְּפִלָּתְ⁠ךָ֣ וְ⁠אֶת־תְּחִנָּתְ⁠ךָ֮ אֲשֶׁ֣ר הִתְחַנַּ֣נְתָּה לְ⁠פָנַ⁠י֒ הִקְדַּ֗שְׁתִּי אֶת־הַ⁠בַּ֤יִת הַ⁠זֶּה֙ אֲשֶׁ֣ר בָּנִ֔תָה לָ⁠שֽׂוּם־שְׁמִ֥⁠י שָׁ֖ם עַד־עוֹלָ֑ם וְ⁠הָי֨וּ עֵינַ֧⁠י וְ⁠לִבִּ֛⁠י שָׁ֖ם כָּל־הַ⁠יָּמִֽים׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼélá֗y⁠w şá̌֠maʻĕţi̇y ʼeţ-ţĕ̇pilá̇ţĕ⁠ká֣ wĕ⁠ʼeţ-ţĕ̇ẖiná̇ţĕ⁠ká֮ ʼàşě֣r hiţĕẖanȧ֣nĕţá̇h lĕ⁠pána⁠y֒ hiqĕdȧ֗şĕ̌ţi̇y ʼeţ-ha⁠bȧ֤yiţ ha⁠zėh֙ ʼàşě֣r bá̇ni֔ţáh lá⁠şֽ̂ẇm-şĕ̌mi֥⁠y şá֖̌m ʻad-ʻwòlá֑m wĕ⁠háy֨ẇ ʻéyna֧⁠y wĕ⁠libi֛̇⁠y şá֖̌m ká̇l-ha⁠yá̇miֽym׃"],[9,4,"וְ⁠אַתָּ֞ה אִם־תֵּלֵ֣ךְ לְ⁠פָנַ֗⁠י כַּ⁠אֲשֶׁ֨ר הָלַ֜ךְ דָּוִ֤ד אָבִ֨י⁠ךָ֙ בְּ⁠תָם־לֵבָ֣ב וּ⁠בְ⁠יֹ֔שֶׁר לַ⁠עֲשׂ֕וֹת כְּ⁠כֹ֖ל אֲשֶׁ֣ר צִוִּיתִ֑י⁠ךָ חֻקַּ֥⁠י וּ⁠מִשְׁפָּטַ֖⁠י תִּשְׁמֹֽר׃","wĕ⁠ʼaţá̇֞h ʼim-ţé̇lé֣kĕ lĕ⁠pána֗⁠y kȧ⁠ʼàşě֨r hála֜kĕ dá̇wi֤d ʼábi֨y⁠ká֙ bĕ̇⁠ţám-lébá֣b ẇ⁠bĕ⁠yò֔şěr la⁠ʻàş̂֕wòţ kĕ̇⁠kò֖l ʼàşě֣r ẕiwi̇yţi֑y⁠ká ẖuqȧ֥⁠y ẇ⁠mişĕ̌pá̇ta֖⁠y ţi̇şĕ̌mòֽr׃"],[9,5,"וַ⁠הֲקִ֨מֹתִ֜י אֶת־כִּסֵּ֧א מַֽמְלַכְתְּ⁠ךָ֛ עַל־יִשְׂרָאֵ֖ל לְ⁠עֹלָ֑ם כַּ⁠אֲשֶׁ֣ר דִּבַּ֗רְתִּי עַל־דָּוִ֤ד אָבִ֨י⁠ךָ֙ לֵ⁠אמֹ֔ר לֹֽא־יִכָּרֵ֤ת לְ⁠ךָ֙ אִ֔ישׁ מֵ⁠עַ֖ל כִּסֵּ֥א יִשְׂרָאֵֽל׃","wa⁠hàqi֨mòţi֜y ʼeţ-ki̇sé֧̇ʼ maֽmĕlakĕţĕ̇⁠ká֛ ʻal-yişĕ̂ráʼé֖l lĕ⁠ʻòlá֑m kȧ⁠ʼàşě֣r di̇bȧ֗rĕţi̇y ʻal-dá̇wi֤d ʼábi֨y⁠ká֙ lé⁠ʼmò֔r lòֽʼ-yiká̇ré֤ţ lĕ⁠ká֙ ʼi֔yş̌ mé⁠ʻa֖l ki̇sé֥̇ʼ yişĕ̂ráʼéֽl׃"],[9,6,"אִם־שׁ֨וֹב תְּשֻׁב֜וּ⁠ן אַתֶּ֤ם וּ⁠בְנֵי⁠כֶם֙ מֵֽ⁠אַחֲרַ֔⁠י וְ⁠לֹ֤א תִשְׁמְרוּ֙ מִצְוֺתַ֣⁠י חֻקֹּתַ֔⁠י אֲשֶׁ֥ר נָתַ֖תִּי לִ⁠פְנֵי⁠כֶ֑ם וַ⁠הֲלַכְתֶּ֗ם וַ⁠עֲבַדְתֶּם֙ אֱלֹהִ֣ים אֲחֵרִ֔ים וְ⁠הִשְׁתַּחֲוִיתֶ֖ם לָ⁠הֶֽם׃","ʼim-ş̌֨wòb ţĕ̇şǔb֜ẇ⁠n ʼaţė֤m ẇ⁠bĕnéy⁠kem֙ méֽ⁠ʼaẖàra֔⁠y wĕ⁠lò֤ʼ ţişĕ̌mĕrẇ֙ miẕĕwֺţa֣⁠y ẖuqò̇ţa֔⁠y ʼàşě֥r náţa֖ţi̇y li⁠pĕnéy⁠ke֑m wa⁠hàlakĕţė֗m wa⁠ʻàbadĕţėm֙ ʼèlòhi֣ym ʼàẖéri֔ym wĕ⁠hişĕ̌ţȧẖàwiyţe֖m lá⁠heֽm׃"],[9,7,"וְ⁠הִכְרַתִּ֣י אֶת־יִשְׂרָאֵ֗ל מֵ⁠עַ֨ל פְּנֵ֤י הָ⁠אֲדָמָה֙ אֲשֶׁ֣ר נָתַ֣תִּי לָ⁠הֶ֔ם וְ⁠אֶת־הַ⁠בַּ֨יִת֙ אֲשֶׁ֣ר הִקְדַּ֣שְׁתִּי לִ⁠שְׁמִ֔⁠י אֲשַׁלַּ֖ח מֵ⁠עַ֣ל פָּנָ֑⁠י וְ⁠הָיָ֧ה יִשְׂרָאֵ֛ל לְ⁠מָשָׁ֥ל וְ⁠לִ⁠שְׁנִינָ֖ה בְּ⁠כָל־הָ⁠עַמִּֽים׃","wĕ⁠hikĕraţi֣̇y ʼeţ-yişĕ̂ráʼé֗l mé⁠ʻa֨l pĕ̇né֤y há⁠ʼàdámáh֙ ʼàşě֣r náţa֣ţi̇y lá⁠he֔m wĕ⁠ʼeţ-ha⁠bȧ֨yiţ֙ ʼàşě֣r hiqĕdȧ֣şĕ̌ţi̇y li⁠şĕ̌mi֔⁠y ʼàşǎlȧ֖ẖ mé⁠ʻa֣l pá̇ná֑⁠y wĕ⁠háyá֧h yişĕ̂ráʼé֛l lĕ⁠máşá֥̌l wĕ⁠li⁠şĕ̌niyná֖h bĕ̇⁠kál-há⁠ʻamiֽ̇ym׃"],[9,8,"וְ⁠הַ⁠בַּ֤יִת הַ⁠זֶּה֙ יִהְיֶ֣ה עֶלְי֔וֹן כָּל־עֹבֵ֥ר עָלָ֖י⁠ו יִשֹּׁ֣ם וְ⁠שָׁרָ֑ק וְ⁠אָמְר֗וּ עַל־מֶ֨ה עָשָׂ֤ה יְהוָה֙ כָּ֔כָה לָ⁠אָ֥רֶץ הַ⁠זֹּ֖את וְ⁠לַ⁠בַּ֥יִת הַ⁠זֶּֽה׃","wĕ⁠ha⁠bȧ֤yiţ ha⁠zėh֙ yihĕye֣h ʻelĕy֔wòn ká̇l-ʻòbé֥r ʻálá֖y⁠w yişò֣̇̌m wĕ⁠şá̌rá֑q wĕ⁠ʼámĕr֗ẇ ʻal-me֨h ʻáşá֤̂h yĕhwáh֙ ká̇֔káh lá⁠ʼá֥reẕ ha⁠zò֖̇ʼţ wĕ⁠la⁠bȧ֥yiţ ha⁠zėֽh׃"],[9,9,"וְ⁠אָמְר֗וּ עַל֩ אֲשֶׁ֨ר עָזְב֜וּ אֶת־יְהוָ֣ה אֱלֹהֵי⁠הֶ֗ם אֲשֶׁ֨ר הוֹצִ֣יא אֶת־אֲבֹתָ⁠ם֮ מֵ⁠אֶ֣רֶץ מִצְרַיִם֒ וַֽ⁠יַּחֲזִ֨קוּ֙ בֵּ⁠אלֹהִ֣ים אֲחֵרִ֔ים ו⁠ישתחו לָ⁠הֶ֖ם וַ⁠יַּעַבְדֻ֑⁠ם עַל־כֵּ֗ן הֵבִ֤יא יְהוָה֙ עֲלֵי⁠הֶ֔ם אֵ֥ת כָּל־הָ⁠רָעָ֖ה הַ⁠זֹּֽאת׃פ","wĕ⁠ʼámĕr֗ẇ ʻal֩ ʼàşě֨r ʻázĕb֜ẇ ʼeţ-yĕhwá֣h ʼèlòhéy⁠he֗m ʼàşě֨r hwòẕi֣yʼ ʼeţ-ʼàbòţá⁠m֮ mé⁠ʼe֣reẕ miẕĕrayim֒ waֽ⁠yȧẖàzi֨qẇ֙ bé̇⁠ʼlòhi֣ym ʼàẖéri֔ym w⁠yşţẖw lá⁠he֖m wa⁠yȧʻabĕdu֑⁠m ʻal-ké̇֗n hébi֤yʼ yĕhwáh֙ ʻàléy⁠he֔m ʼé֥ţ ká̇l-há⁠ráʻá֖h ha⁠zòֽ̇ʼţ׃p"],[9,10,"וַ⁠יְהִ֗י מִ⁠קְצֵה֙ עֶשְׂרִ֣ים שָׁנָ֔ה אֲשֶׁר־בָּנָ֥ה שְׁלֹמֹ֖ה אֶת־שְׁנֵ֣י הַ⁠בָּתִּ֑ים אֶת־בֵּ֥ית יְהוָ֖ה וְ⁠אֶת־בֵּ֥ית הַ⁠מֶּֽלֶךְ׃","wa⁠yĕhi֗y mi⁠qĕẕéh֙ ʻeşĕ̂ri֣ym şá̌ná֔h ʼàşěr-bá̇ná֥h şĕ̌lòmò֖h ʼeţ-şĕ̌né֣y ha⁠bá̇ţi֑̇ym ʼeţ-bé֥̇yţ yĕhwá֖h wĕ⁠ʼeţ-bé֥̇yţ ha⁠mėֽlekĕ׃"],[9,11,"חִירָ֣ם מֶֽלֶךְ־צֹ֠ר נִשָּׂ֨א אֶת־שְׁלֹמֹ֜ה בַּ⁠עֲצֵי֩ אֲרָזִ֨ים וּ⁠בַ⁠עֲצֵ֧י בְרוֹשִׁ֛ים וּ⁠בַ⁠זָּהָ֖ב לְ⁠כָל־חֶפְצ֑⁠וֹ אָ֡ז יִתֵּן֩ הַ⁠מֶּ֨לֶךְ שְׁלֹמֹ֤ה לְ⁠חִירָם֙ עֶשְׂרִ֣ים עִ֔יר בְּ⁠אֶ֖רֶץ הַ⁠גָּלִֽיל׃","ẖiyrá֣m meֽlekĕ-ẕò֠r nişá̇̂֨ʼ ʼeţ-şĕ̌lòmò֜h bȧ⁠ʻàẕéy֩ ʼàrázi֨ym ẇ⁠ba⁠ʻàẕé֧y bĕrwòşǐ֛ym ẇ⁠ba⁠zá̇há֖b lĕ⁠kál-ẖepĕẕ֑⁠wò ʼá֡z yiţé̇n֩ ha⁠mė֨lekĕ şĕ̌lòmò֤h lĕ⁠ẖiyrám֙ ʻeşĕ̂ri֣ym ʻi֔yr bĕ̇⁠ʼe֖reẕ ha⁠gá̇liֽyl׃"],[9,12,"וַ⁠יֵּצֵ֤א חִירָם֙ מִ⁠צֹּ֔ר לִ⁠רְאוֹת֙ אֶת־הֶ֣⁠עָרִ֔ים אֲשֶׁ֥ר נָתַן־ל֖⁠וֹ שְׁלֹמֹ֑ה וְ⁠לֹ֥א יָשְׁר֖וּ בְּ⁠עֵינָֽי⁠ו׃","wa⁠yé̇ẕé֤ʼ ẖiyrám֙ mi⁠ẕò̇֔r li⁠rĕʼwòţ֙ ʼeţ-he֣⁠ʻári֔ym ʼàşě֥r náţan-l֖⁠wò şĕ̌lòmò֑h wĕ⁠lò֥ʼ yáşĕ̌r֖ẇ bĕ̇⁠ʻéynáֽy⁠w׃"],[9,13,"וַ⁠יֹּ֕אמֶר מָ֚ה הֶ⁠עָרִ֣ים הָ⁠אֵ֔לֶּה אֲשֶׁר־נָתַ֥תָּה לִּ֖⁠י אָחִ֑⁠י וַ⁠יִּקְרָ֤א לָ⁠הֶם֙ אֶ֣רֶץ כָּב֔וּל עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yò̇֕ʼmer má֚h he⁠ʻári֣ym há⁠ʼé֔lėh ʼàşěr-náţa֥ţá̇h li֖̇⁠y ʼáẖi֑⁠y wa⁠yi̇qĕrá֤ʼ lá⁠hem֙ ʼe֣reẕ ká̇b֔ẇl ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[9,14,"וַ⁠יִּשְׁלַ֥ח חִירָ֖ם לַ⁠מֶּ֑לֶךְ מֵאָ֥ה וְ⁠עֶשְׂרִ֖ים כִּכַּ֥ר זָהָֽב׃","wa⁠yi̇şĕ̌la֥ẖ ẖiyrá֖m la⁠mė֑lekĕ méʼá֥h wĕ⁠ʻeşĕ̂ri֖ym ki̇kȧ֥r záháֽb׃"],[9,15,"וְ⁠זֶ֨ה דְבַר־הַ⁠מַּ֜ס אֲשֶֽׁר־הֶעֱלָ֣ה ׀ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֗ה לִ⁠בְנוֹת֩ אֶת־בֵּ֨ית יְהוָ֤ה וְ⁠אֶת־בֵּית⁠וֹ֙ וְ⁠אֶת־הַ⁠מִּלּ֔וֹא וְ⁠אֵ֖ת חוֹמַ֣ת יְרוּשָׁלִָ֑ם וְ⁠אֶת־חָצֹ֥ר וְ⁠אֶת־מְגִדּ֖וֹ וְ⁠אֶת־גָּֽזֶר׃","wĕ⁠ze֨h dĕbar-ha⁠mȧ֜s ʼàşěֽr-heʻèlá֣h ׀ ha⁠mė֣lekĕ şĕ̌lòmò֗h li⁠bĕnwòţ֩ ʼeţ-bé̇֨yţ yĕhwá֤h wĕ⁠ʼeţ-bé̇yţ⁠wò֙ wĕ⁠ʼeţ-ha⁠mi̇l̇֔wòʼ wĕ⁠ʼé֖ţ ẖwòma֣ţ yĕrẇşá̌liá֑m wĕ⁠ʼeţ-ẖáẕò֥r wĕ⁠ʼeţ-mĕgiḋ֖wò wĕ⁠ʼeţ-gáֽ̇zer׃"],[9,16,"פַּרְעֹ֨ה מֶֽלֶךְ־מִצְרַ֜יִם עָלָ֗ה וַ⁠יִּלְכֹּ֤ד אֶת־גֶּ֨זֶר֙ וַ⁠יִּשְׂרְפָ֣⁠הּ בָּ⁠אֵ֔שׁ וְ⁠אֶת־הַֽ⁠כְּנַעֲנִ֛י הַ⁠יֹּשֵׁ֥ב בָּ⁠עִ֖יר הָרָ֑ג וַֽ⁠יִּתְּנָ⁠הּ֙ שִׁלֻּחִ֔ים לְ⁠בִתּ֖⁠וֹ אֵ֥שֶׁת שְׁלֹמֹֽה׃","pȧrĕʻò֨h meֽlekĕ-miẕĕra֜yim ʻálá֗h wa⁠yi̇lĕkò֤̇d ʼeţ-gė֨zer֙ wa⁠yi̇şĕ̂rĕpá֣⁠ḣ bá̇⁠ʼé֔ş̌ wĕ⁠ʼeţ-haֽ⁠kĕ̇naʻàni֛y ha⁠yò̇şé֥̌b bá̇⁠ʻi֖yr hárá֑g waֽ⁠yi̇ţĕ̇ná⁠ḣ֙ şǐlu̇ẖi֔ym lĕ⁠biţ֖̇⁠wò ʼé֥şěţ şĕ̌lòmòֽh׃"],[9,17,"וַ⁠יִּ֤בֶן שְׁלֹמֹה֙ אֶת־גָּ֔זֶר וְ⁠אֶת־בֵּ֥ית חֹרֹ֖ן תַּחְתּֽוֹן׃","wa⁠yi֤̇ben şĕ̌lòmòh֙ ʼeţ-gá̇֔zer wĕ⁠ʼeţ-bé֥̇yţ ẖòrò֖n ţȧẖĕţֽ̇wòn׃"],[9,18,"וְ⁠אֶֽת־בַּעֲלָ֛ת וְ⁠אֶת־תמר בַּ⁠מִּדְבָּ֖ר בָּ⁠אָֽרֶץ׃","wĕ⁠ʼeֽţ-bȧʻàlá֛ţ wĕ⁠ʼeţ-ţmr bȧ⁠mi̇dĕbá֖̇r bá̇⁠ʼáֽreẕ׃"],[9,19,"וְ⁠אֵ֨ת כָּל־עָרֵ֤י הַֽ⁠מִּסְכְּנוֹת֙ אֲשֶׁ֣ר הָי֣וּ לִ⁠שְׁלֹמֹ֔ה וְ⁠אֵת֙ עָרֵ֣י הָ⁠רֶ֔כֶב וְ⁠אֵ֖ת עָרֵ֣י הַ⁠פָּרָשִׁ֑ים וְ⁠אֵ֣ת ׀ חֵ֣שֶׁק שְׁלֹמֹ֗ה אֲשֶׁ֤ר חָשַׁק֙ לִ⁠בְנ֤וֹת בִּ⁠ירוּשָׁלִַ֨ם֙ וּ⁠בַ⁠לְּבָנ֔וֹן וּ⁠בְ⁠כֹ֖ל אֶ֥רֶץ מֶמְשַׁלְתּֽ⁠וֹ׃","wĕ⁠ʼé֨ţ ká̇l-ʻáré֤y haֽ⁠mi̇sĕkĕ̇nwòţ֙ ʼàşě֣r háy֣ẇ li⁠şĕ̌lòmò֔h wĕ⁠ʼéţ֙ ʻáré֣y há⁠re֔keb wĕ⁠ʼé֖ţ ʻáré֣y ha⁠pá̇ráşǐ֑ym wĕ⁠ʼé֣ţ ׀ ẖé֣şěq şĕ̌lòmò֗h ʼàşě֤r ẖáşǎq֙ li⁠bĕn֤wòţ bi̇⁠yrẇşá̌lia֨m֙ ẇ⁠ba⁠lĕ̇bán֔wòn ẇ⁠bĕ⁠kò֖l ʼe֥reẕ memĕşǎlĕţֽ̇⁠wò׃"],[9,20,"כָּל־הָ֠⁠עָם הַ⁠נּוֹתָ֨ר מִן־הָ⁠אֱמֹרִ֜י הַ⁠חִתִּ֤י הַ⁠פְּרִזִּי֙ הַ⁠חִוִּ֣י וְ⁠הַ⁠יְבוּסִ֔י אֲשֶׁ֛ר לֹֽא־מִ⁠בְּנֵ֥י יִשְׂרָאֵ֖ל הֵֽמָּה׃","ká̇l-há֠⁠ʻám ha⁠ṅwòţá֨r min-há⁠ʼèmòri֜y ha⁠ẖiţi֤̇y ha⁠pĕ̇rizi̇y֙ ha⁠ẖiwi֣̇y wĕ⁠ha⁠yĕbẇsi֔y ʼàşě֛r lòֽʼ-mi⁠bĕ̇né֥y yişĕ̂ráʼé֖l héֽmá̇h׃"],[9,21,"בְּנֵי⁠הֶ֗ם אֲשֶׁ֨ר נֹתְר֤וּ אַחֲרֵי⁠הֶם֙ בָּ⁠אָ֔רֶץ אֲשֶׁ֧ר לֹֽא־יָכְל֛וּ בְּנֵ֥י יִשְׂרָאֵ֖ל לְ⁠הַֽחֲרִימָ֑⁠ם וַ⁠יַּעֲלֵ֤⁠ם שְׁלֹמֹה֙ לְ⁠מַס־עֹבֵ֔ד עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","bĕ̇néy⁠he֗m ʼàşě֨r nòţĕr֤ẇ ʼaẖàréy⁠hem֙ bá̇⁠ʼá֔reẕ ʼàşě֧r lòֽʼ-yákĕl֛ẇ bĕ̇né֥y yişĕ̂ráʼé֖l lĕ⁠hֽaẖàriymá֑⁠m wa⁠yȧʻàlé֤⁠m şĕ̌lòmòh֙ lĕ⁠mas-ʻòbé֔d ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[9,22,"וּ⁠מִ⁠בְּנֵי֙ יִשְׂרָאֵ֔ל לֹֽא־נָתַ֥ן שְׁלֹמֹ֖ה עָ֑בֶד כִּי־הֵ֞ם אַנְשֵׁ֣י הַ⁠מִּלְחָמָ֗ה וַ⁠עֲבָדָי⁠ו֙ וְ⁠שָׂרָ֣י⁠ו וְ⁠שָׁלִשָׁ֔י⁠ו וְ⁠שָׂרֵ֥י רִכְבּ֖⁠וֹ וּ⁠פָרָשָֽׁי⁠ו׃ס","ẇ⁠mi⁠bĕ̇néy֙ yişĕ̂ráʼé֔l lòֽʼ-náţa֥n şĕ̌lòmò֖h ʻá֑bed ki̇y-hé֞m ʼanĕşé֣̌y ha⁠mi̇lĕẖámá֗h wa⁠ʻàbádáy⁠w֙ wĕ⁠şá̂rá֣y⁠w wĕ⁠şá̌lişá̌֔y⁠w wĕ⁠şá̂ré֥y rikĕḃ֖⁠wò ẇ⁠páráşáֽ̌y⁠w׃s"],[9,23,"אֵ֣לֶּה ׀ שָׂרֵ֣י הַ⁠נִּצָּבִ֗ים אֲשֶׁ֤ר עַל־הַ⁠מְּלָאכָה֙ לִ⁠שְׁלֹמֹ֔ה חֲמִשִּׁ֖ים וַ⁠חֲמֵ֣שׁ מֵא֑וֹת הָ⁠רֹדִ֣ים בָּ⁠עָ֔ם הָ⁠עֹשִׂ֖ים בַּ⁠מְּלָאכָֽה׃","ʼé֣lėh ׀ şá̂ré֣y ha⁠ni̇ẕá̇bi֗ym ʼàşě֤r ʻal-ha⁠mĕ̇láʼkáh֙ li⁠şĕ̌lòmò֔h ẖàmişi֖̇̌ym wa⁠ẖàmé֣ş̌ méʼ֑wòţ há⁠ròdi֣ym bá̇⁠ʻá֔m há⁠ʻòşî֖ym bȧ⁠mĕ̇láʼkáֽh׃"],[9,24,"אַ֣ךְ בַּת־פַּרְעֹ֗ה עָֽלְתָה֙ מֵ⁠עִ֣יר דָּוִ֔ד אֶל־בֵּיתָ֖⁠הּ אֲשֶׁ֣ר בָּֽנָה־לָ֑⁠הּ אָ֖ז בָּנָ֥ה אֶת־הַ⁠מִּלּֽוֹא׃","ʼa֣kĕ bȧţ-pȧrĕʻò֗h ʻáֽlĕţáh֙ mé⁠ʻi֣yr dá̇wi֔d ʼel-bé̇yţá֖⁠ḣ ʼàşě֣r báֽ̇náh-lá֑⁠ḣ ʼá֖z bá̇ná֥h ʼeţ-ha⁠mi̇lֽ̇wòʼ׃"],[9,25,"וְ⁠הֶעֱלָ֣ה שְׁלֹמֹ֡ה שָׁלֹשׁ֩ פְּעָמִ֨ים בַּ⁠שָּׁנָ֜ה עֹל֣וֹת וּ⁠שְׁלָמִ֗ים עַל־הַ⁠מִּזְבֵּ֨חַ֙ אֲשֶׁ֣ר בָּנָ֣ה לַ⁠יהוָ֔ה וְ⁠הַקְטֵ֣יר אִתּ֔⁠וֹ אֲשֶׁ֖ר לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠שִׁלַּ֖ם אֶת־הַ⁠בָּֽיִת׃","wĕ⁠heʻèlá֣h şĕ̌lòmò֡h şá̌lòş̌֩ pĕ̇ʻámi֨ym bȧ⁠şá̇̌ná֜h ʻòl֣wòţ ẇ⁠şĕ̌lámi֗ym ʻal-ha⁠mi̇zĕbé̇֨ẖa֙ ʼàşě֣r bá̇ná֣h la⁠yhwá֔h wĕ⁠haqĕté֣yr ʼiţ̇֔⁠wò ʼàşě֖r li⁠pĕné֣y yĕhwá֑h wĕ⁠şǐlȧ֖m ʼeţ-ha⁠báֽ̇yiţ׃"],[9,26,"וָ⁠אֳנִ֡י עָשָׂה֩ הַ⁠מֶּ֨לֶךְ שְׁלֹמֹ֜ה בְּ⁠עֶצְיֽוֹן־גֶּ֨בֶר אֲשֶׁ֧ר אֶת־אֵל֛וֹת עַל־שְׂפַ֥ת יַם־ס֖וּף בְּ⁠אֶ֥רֶץ אֱדֽוֹם׃","wá⁠ʼoni֡y ʻáşá̂h֩ ha⁠mė֨lekĕ şĕ̌lòmò֜h bĕ̇⁠ʻeẕĕyֽwòn-gė֨ber ʼàşě֧r ʼeţ-ʼél֛wòţ ʻal-şĕ̂pa֥ţ yam-s֖ẇp bĕ̇⁠ʼe֥reẕ ʼèdֽwòm׃"],[9,27,"וַ⁠יִּשְׁלַ֨ח חִירָ֤ם בָּֽ⁠אֳנִי֙ אֶת־עֲבָדָ֔י⁠ו אַנְשֵׁ֣י אֳנִיּ֔וֹת יֹדְעֵ֖י הַ⁠יָּ֑ם עִ֖ם עַבְדֵ֥י שְׁלֹמֹֽה׃","wa⁠yi̇şĕ̌la֨ẖ ẖiyrá֤m ḃֽá⁠ʼoniy֙ ʼeţ-ʻàbádá֔y⁠w ʼanĕşé֣̌y ʼoniẏ֔wòţ yòdĕʻé֖y ha⁠yá֑̇m ʻi֖m ʻabĕdé֥y şĕ̌lòmòֽh׃"],[9,28,"וַ⁠יָּבֹ֣אוּ אוֹפִ֔ירָ⁠ה וַ⁠יִּקְח֤וּ מִ⁠שָּׁם֙ זָהָ֔ב אַרְבַּע־מֵא֥וֹת וְ⁠עֶשְׂרִ֖ים כִּכָּ֑ר וַ⁠יָּבִ֖אוּ אֶל־הַ⁠מֶּ֥לֶךְ שְׁלֹמֹֽה׃פ","wa⁠yá̇bò֣ʼẇ ʼwòpi֔yrá⁠h wa⁠yi̇qĕẖ֤ẇ mi⁠şá̇̌m֙ záhá֔b ʼarĕbȧʻ-méʼ֥wòţ wĕ⁠ʻeşĕ̂ri֖ym ki̇ká֑̇r wa⁠yá̇bi֖ʼẇ ʼel-ha⁠mė֥lekĕ şĕ̌lòmòֽh׃p"],[10,1,"וּ⁠מַֽלְכַּת־שְׁבָ֗א שֹׁמַ֛עַת אֶת־שֵׁ֥מַע שְׁלֹמֹ֖ה לְ⁠שֵׁ֣ם יְהוָ֑ה וַ⁠תָּבֹ֥א לְ⁠נַסֹּת֖⁠וֹ בְּ⁠חִידֽוֹת׃","ẇ⁠maֽlĕkȧţ-şĕ̌bá֗ʼ şò̌ma֛ʻaţ ʼeţ-şé֥̌maʻ şĕ̌lòmò֖h lĕ⁠şé֣̌m yĕhwá֑h wa⁠ţá̇bò֥ʼ lĕ⁠nasò̇ţ֖⁠wò bĕ̇⁠ẖiydֽwòţ׃"],[10,2,"וַ⁠תָּבֹ֣א יְרוּשָׁלְַ֗מָ⁠ה בְּ⁠חַיִל֮ כָּבֵ֣ד מְאֹד֒ גְּ֠מַלִּים נֹשְׂאִ֨ים בְּשָׂמִ֧ים וְ⁠זָהָ֛ב רַב־מְאֹ֖ד וְ⁠אֶ֣בֶן יְקָרָ֑ה וַ⁠תָּבֹא֙ אֶל־שְׁלֹמֹ֔ה וַ⁠תְּדַבֵּ֣ר אֵלָ֔י⁠ו אֵ֛ת כָּל־אֲשֶׁ֥ר הָיָ֖ה עִם־לְבָבָֽ⁠הּ׃","wa⁠ţá̇bò֣ʼ yĕrẇşá̌lĕa֗má⁠h bĕ̇⁠ẖayil֮ ká̇bé֣d mĕʼòd֒ gĕ̇֠mali̇ym nòşĕ̂ʼi֨ym bĕ̇şá̂mi֧ym wĕ⁠záhá֛b rab-mĕʼò֖d wĕ⁠ʼe֣ben yĕqárá֑h wa⁠ţá̇bòʼ֙ ʼel-şĕ̌lòmò֔h wa⁠ţĕ̇dabé֣̇r ʼélá֔y⁠w ʼé֛ţ ká̇l-ʼàşě֥r háyá֖h ʻim-lĕbábáֽ⁠ḣ׃"],[10,3,"וַ⁠יַּגֶּד־לָ֥⁠הּ שְׁלֹמֹ֖ה אֶת־כָּל־דְּבָרֶ֑י⁠הָ לֹֽא־הָיָ֤ה דָּבָר֙ נֶעְלָ֣ם מִן־הַ⁠מֶּ֔לֶךְ אֲשֶׁ֧ר לֹ֦א הִגִּ֖יד לָֽ⁠הּ׃","wa⁠yȧgėd-lá֥⁠ḣ şĕ̌lòmò֖h ʼeţ-ká̇l-dĕ̇báre֑y⁠há lòֽʼ-háyá֤h dá̇bár֙ neʻĕlá֣m min-ha⁠mė֔lekĕ ʼàşě֧r lò֦ʼ higi֖̇yd láֽ⁠ḣ׃"],[10,4,"וַ⁠תֵּ֨רֶא֙ מַֽלְכַּת־שְׁבָ֔א אֵ֖ת כָּל־חָכְמַ֣ת שְׁלֹמֹ֑ה וְ⁠הַ⁠בַּ֖יִת אֲשֶׁ֥ר בָּנָֽה׃","wa⁠ţé̇֨reʼ֙ maֽlĕkȧţ-şĕ̌bá֔ʼ ʼé֖ţ ká̇l-ẖákĕma֣ţ şĕ̌lòmò֑h wĕ⁠ha⁠bȧ֖yiţ ʼàşě֥r bá̇náֽh׃"],[10,5,"וּ⁠מַאֲכַ֣ל שֻׁלְחָנ֡⁠וֹ וּ⁠מוֹשַׁ֣ב עֲבָדָי⁠ו֩ וּ⁠מַעֲמַ֨ד משרת⁠ו וּ⁠מַלְבֻּֽשֵׁי⁠הֶם֙ וּ⁠מַשְׁקָ֔י⁠ו וְ⁠עֹ֣לָת֔⁠וֹ אֲשֶׁ֥ר יַעֲלֶ֖ה בֵּ֣ית יְהוָ֑ה וְ⁠לֹא־הָ֥יָה בָ֛⁠הּ ע֖וֹד רֽוּחַ׃","ẇ⁠maʼàka֣l şǔlĕẖán֡⁠wò ẇ⁠mwòşǎ֣b ʻàbádáy⁠w֩ ẇ⁠maʻàma֨d mşrţ⁠w ẇ⁠malĕbuֽ̇şé̌y⁠hem֙ ẇ⁠maşĕ̌qá֔y⁠w wĕ⁠ʻò֣láţ֔⁠wò ʼàşě֥r yaʻàle֖h bé֣̇yţ yĕhwá֑h wĕ⁠lòʼ-há֥yáh bá֛⁠ḣ ʻ֖wòd rֽẇẖa׃"],[10,6,"וַ⁠תֹּ֨אמֶר֙ אֶל־הַ⁠מֶּ֔לֶךְ אֱמֶת֙ הָיָ֣ה הַ⁠דָּבָ֔ר אֲשֶׁ֥ר שָׁמַ֖עְתִּי בְּ⁠אַרְצִ֑⁠י עַל־דְּבָרֶ֖י⁠ךָ וְ⁠עַל־חָכְמָתֶֽ⁠ךָ׃","wa⁠ţò̇֨ʼmer֙ ʼel-ha⁠mė֔lekĕ ʼèmeţ֙ háyá֣h ha⁠dá̇bá֔r ʼàşě֥r şá̌ma֖ʻĕţi̇y bĕ̇⁠ʼarĕẕi֑⁠y ʻal-dĕ̇báre֖y⁠ká wĕ⁠ʻal-ẖákĕmáţeֽ⁠ká׃"],[10,7,"וְ⁠לֹֽא־הֶאֱמַ֣נְתִּי לַ⁠דְּבָרִ֗ים עַ֤ד אֲשֶׁר־בָּ֨אתִי֙ וַ⁠תִּרְאֶ֣ינָה עֵינַ֔⁠י וְ⁠הִנֵּ֥ה לֹֽא־הֻגַּד־לִ֖⁠י הַ⁠חֵ֑צִי הוֹסַ֤פְתָּ חָכְמָה֙ וָ⁠ט֔וֹב אֶל־הַ⁠שְּׁמוּעָ֖ה אֲשֶׁ֥ר שָׁמָֽעְתִּי׃","wĕ⁠lòֽʼ-heʼèma֣nĕţi̇y la⁠dĕ̇bári֗ym ʻa֤d ʼàşěr-bá̇֨ʼţiy֙ wa⁠ţi̇rĕʼe֣ynáh ʻéyna֔⁠y wĕ⁠hiné֥̇h lòֽʼ-hugȧd-li֖⁠y ha⁠ẖé֑ẕiy hwòsa֤pĕţá̇ ẖákĕmáh֙ wá⁠t֔wòb ʼel-ha⁠şĕ̇̌mẇʻá֖h ʼàşě֥r şá̌máֽʻĕţi̇y׃"],[10,8,"אַשְׁרֵ֣י אֲנָשֶׁ֔י⁠ךָ אַשְׁרֵ֖י עֲבָדֶ֣י⁠ךָ אֵ֑לֶּה הָֽ⁠עֹמְדִ֤ים לְ⁠פָנֶ֨י⁠ךָ֙ תָּמִ֔יד הַ⁠שֹּׁמְעִ֖ים אֶת־חָכְמָתֶֽ⁠ךָ׃","ʼaşĕ̌ré֣y ʼànáşě֔y⁠ká ʼaşĕ̌ré֖y ʻàbáde֣y⁠ká ʼé֑lėh háֽ⁠ʻòmĕdi֤ym lĕ⁠páne֨y⁠ká֙ ţá̇mi֔yd ha⁠şò̇̌mĕʻi֖ym ʼeţ-ẖákĕmáţeֽ⁠ká׃"],[10,9,"יְהִ֨י יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ בָּר֔וּךְ אֲשֶׁר֙ חָפֵ֣ץ בְּ⁠ךָ֔ לְ⁠תִתְּ⁠ךָ֖ עַל־כִּסֵּ֣א יִשְׂרָאֵ֑ל בְּ⁠אַהֲבַ֨ת יְהוָ֤ה אֶת־יִשְׂרָאֵל֙ לְ⁠עֹלָ֔ם וַ⁠יְשִֽׂימְ⁠ךָ֣ לְ⁠מֶ֔לֶךְ לַ⁠עֲשׂ֥וֹת מִשְׁפָּ֖ט וּ⁠צְדָקָֽה׃","yĕhi֨y yĕhwá֤h ʼèlòhe֨y⁠ká֙ bá̇r֔ẇkĕ ʼàşěr֙ ẖápé֣ẕ bĕ̇⁠ká֔ lĕ⁠ţiţĕ̇⁠ká֖ ʻal-ki̇sé֣̇ʼ yişĕ̂ráʼé֑l bĕ̇⁠ʼahàba֨ţ yĕhwá֤h ʼeţ-yişĕ̂ráʼél֙ lĕ⁠ʻòlá֔m wa⁠yĕşîֽymĕ⁠ká֣ lĕ⁠me֔lekĕ la⁠ʻàş֥̂wòţ mişĕ̌pá֖̇t ẇ⁠ẕĕdáqáֽh׃"],[10,10,"וַ⁠תִּתֵּ֨ן לַ⁠מֶּ֜לֶךְ מֵאָ֥ה וְ⁠עֶשְׂרִ֣ים ׀ כִּכַּ֣ר זָהָ֗ב וּ⁠בְשָׂמִ֛ים הַרְבֵּ֥ה מְאֹ֖ד וְ⁠אֶ֣בֶן יְקָרָ֑ה לֹא־בָא֩ כַ⁠בֹּ֨שֶׂם הַ⁠ה֥וּא עוֹד֙ לָ⁠רֹ֔ב אֲשֶׁר־נָתְנָ֥ה מַֽלְכַּת־שְׁבָ֖א לַ⁠מֶּ֥לֶךְ שְׁלֹמֹֽה׃","wa⁠ţi̇ţé̇֨n la⁠mė֜lekĕ méʼá֥h wĕ⁠ʻeşĕ̂ri֣ym ׀ ki̇kȧ֣r záhá֗b ẇ⁠bĕşá̂mi֛ym harĕbé֥̇h mĕʼò֖d wĕ⁠ʼe֣ben yĕqárá֑h lòʼ-báʼ֩ ka⁠bò̇֨şêm ha⁠h֥ẇʼ ʻwòd֙ lá⁠rò֔b ʼàşěr-náţĕná֥h maֽlĕkȧţ-şĕ̌bá֖ʼ la⁠mė֥lekĕ şĕ̌lòmòֽh׃"],[10,11,"וְ⁠גַם֙ אֳנִ֣י חִירָ֔ם אֲשֶׁר־נָשָׂ֥א זָהָ֖ב מֵ⁠אוֹפִ֑יר הֵבִ֨יא מֵ⁠אֹפִ֜יר עֲצֵ֧י אַלְמֻגִּ֛ים הַרְבֵּ֥ה מְאֹ֖ד וְ⁠אֶ֥בֶן יְקָרָֽה׃","wĕ⁠gam֙ ʼoni֣y ẖiyrá֔m ʼàşěr-náşá֥̂ʼ záhá֖b mé⁠ʼwòpi֑yr hébi֨yʼ mé⁠ʼòpi֜yr ʻàẕé֧y ʼalĕmugi֛̇ym harĕbé֥̇h mĕʼò֖d wĕ⁠ʼe֥ben yĕqáráֽh׃"],[10,12,"וַ⁠יַּ֣עַשׂ הַ֠⁠מֶּלֶךְ אֶת־עֲצֵ֨י הָ⁠אַלְמֻגִּ֜ים מִסְעָ֤ד לְ⁠בֵית־יְהוָה֙ וּ⁠לְ⁠בֵ֣ית הַ⁠מֶּ֔לֶךְ וְ⁠כִנֹּר֥וֹת וּ⁠נְבָלִ֖ים לַ⁠שָּׁרִ֑ים לֹ֣א בָֽא־כֵ֞ן עֲצֵ֤י אַלְמֻגִּים֙ וְ⁠לֹ֣א נִרְאָ֔ה עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yȧ֣ʻaş̂ ha֠⁠mėlekĕ ʼeţ-ʻàẕé֨y há⁠ʼalĕmugi̇֜ym misĕʻá֤d lĕ⁠béyţ-yĕhwáh֙ ẇ⁠lĕ⁠bé֣yţ ha⁠mė֔lekĕ wĕ⁠kinò̇r֥wòţ ẇ⁠nĕbáli֖ym la⁠şá̇̌ri֑ym lò֣ʼ báֽʼ-ké֞n ʻàẕé֤y ʼalĕmugi̇ym֙ wĕ⁠lò֣ʼ nirĕʼá֔h ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[10,13,"וְ⁠הַ⁠מֶּ֨לֶךְ שְׁלֹמֹ֜ה נָתַ֣ן לְ⁠מַֽלְכַּת־שְׁבָ֗א אֶת־כָּל־חֶפְצָ⁠הּ֙ אֲשֶׁ֣ר שָׁאָ֔לָה מִ⁠לְּ⁠בַד֙ אֲשֶׁ֣ר נָֽתַן־לָ֔⁠הּ כְּ⁠יַ֖ד הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֑ה וַ⁠תֵּ֛פֶן וַ⁠תֵּ֥לֶךְ לְ⁠אַרְצָ֖⁠הּ הִ֥יא וַ⁠עֲבָדֶֽי⁠הָ׃ס","wĕ⁠ha⁠mė֨lekĕ şĕ̌lòmò֜h náţa֣n lĕ⁠maֽlĕkȧţ-şĕ̌bá֗ʼ ʼeţ-ká̇l-ẖepĕẕá⁠ḣ֙ ʼàşě֣r şá̌ʼá֔láh mi⁠lĕ̇⁠bad֙ ʼàşě֣r náֽţan-lá֔⁠ḣ kĕ̇⁠ya֖d ha⁠mė֣lekĕ şĕ̌lòmò֑h wa⁠ţé֛̇pen wa⁠ţé֥̇lekĕ lĕ⁠ʼarĕẕá֖⁠ḣ hi֥yʼ wa⁠ʻàbádeֽy⁠há׃s"],[10,14,"וַֽ⁠יְהִי֙ מִשְׁקַ֣ל הַ⁠זָּהָ֔ב אֲשֶׁר־בָּ֥א לִ⁠שְׁלֹמֹ֖ה בְּ⁠שָׁנָ֣ה אֶחָ֑ת שֵׁ֥שׁ מֵא֛וֹת שִׁשִּׁ֥ים וָ⁠שֵׁ֖שׁ כִּכַּ֥ר זָהָֽב׃","wֽa⁠yĕhiy֙ mişĕ̌qa֣l ha⁠zá̇há֔b ʼàşěr-bá֥̇ʼ li⁠şĕ̌lòmò֖h bĕ̇⁠şá̌ná֣h ʼeẖá֑ţ şé֥̌ş̌ méʼ֛wòţ şǐşi֥̇̌ym wá⁠şé֖̌ş̌ ki̇kȧ֥r záháֽb׃"],[10,15,"לְ⁠בַד֙ מֵ⁠אַנְשֵׁ֣י הַ⁠תָּרִ֔ים וּ⁠מִסְחַ֖ר הָ⁠רֹכְלִ֑ים וְ⁠כָל־מַלְכֵ֥י הָ⁠עֶ֖רֶב וּ⁠פַח֥וֹת הָ⁠אָֽרֶץ׃","lĕ⁠bad֙ mé⁠ʼanĕşé֣̌y ha⁠ţá̇ri֔ym ẇ⁠misĕẖa֖r há⁠ròkĕli֑ym wĕ⁠kál-malĕké֥y há⁠ʻe֖reb ẇ⁠paẖ֥wòţ há⁠ʼáֽreẕ׃"],[10,16,"וַ⁠יַּ֨עַשׂ הַ⁠מֶּ֧לֶךְ שְׁלֹמֹ֛ה מָאתַ֥יִם צִנָּ֖ה זָהָ֣ב שָׁח֑וּט שֵׁשׁ־מֵא֣וֹת זָהָ֔ב יַעֲלֶ֖ה עַל־הַ⁠צִּנָּ֥ה הָ⁠אֶחָֽת׃","wa⁠yȧ֨ʻaş̂ ha⁠mė֧lekĕ şĕ̌lòmò֛h máʼţa֥yim ẕiná֖̇h záhá֣b şá̌ẖ֑ẇt şé̌ş̌-méʼ֣wòţ záhá֔b yaʻàle֖h ʻal-ha⁠ẕi̇ná֥̇h há⁠ʼeẖáֽţ׃"],[10,17,"וּ⁠שְׁלֹשׁ־מֵא֤וֹת מָֽגִנִּים֙ זָהָ֣ב שָׁח֔וּט שְׁלֹ֤שֶׁת מָנִים֙ זָהָ֔ב יַעֲלֶ֖ה עַל־הַ⁠מָּגֵ֣ן הָ⁠אֶחָ֑ת וַ⁠יִּתְּנֵ֣⁠ם הַ⁠מֶּ֔לֶךְ בֵּ֖ית יַ֥עַר הַ⁠לְּבָנֽוֹן׃פ","ẇ⁠şĕ̌lòş̌-méʼ֤wòţ máֽgini̇ym֙ záhá֣b şá̌ẖ֔ẇt şĕ̌lò֤şěţ mániym֙ záhá֔b yaʻàle֖h ʻal-ha⁠má̇gé֣n há⁠ʼeẖá֑ţ wa⁠yi̇ţĕ̇né֣⁠m ha⁠mė֔lekĕ bé֖̇yţ ya֥ʻar ha⁠lĕ̇bánֽwòn׃p"],[10,18,"וַ⁠יַּ֧עַשׂ הַ⁠מֶּ֛לֶךְ כִּסֵּא־שֵׁ֖ן גָּד֑וֹל וַ⁠יְצַפֵּ֖⁠הוּ זָהָ֥ב מוּפָֽז׃","wa⁠yȧ֧ʻaş̂ ha⁠mė֛lekĕ ki̇sé̇ʼ-şé֖̌n gá̇d֑wòl wa⁠yĕẕapé֖̇⁠hẇ záhá֥b mẇpáֽz׃"],[10,19,"שֵׁ֧שׁ מַעֲל֣וֹת לַ⁠כִּסֵּ֗ה וְ⁠רֹאשׁ־עָגֹ֤ל לַ⁠כִּסֵּה֙ מֵ⁠אַֽחֲרָ֔י⁠ו וְ⁠יָדֹ֛ת מִ⁠זֶּ֥ה וּ⁠מִ⁠זֶּ֖ה אֶל־מְק֣וֹם הַ⁠שָּׁ֑בֶת וּ⁠שְׁנַ֣יִם אֲרָי֔וֹת עֹמְדִ֖ים אֵ֥צֶל הַ⁠יָּדֽוֹת׃","şé֧̌ş̌ maʻàl֣wòţ la⁠ki̇sé̇֗h wĕ⁠ròʼş̌-ʻágò֤l la⁠ki̇sé̇h֙ mé⁠ʼaֽẖàrá֔y⁠w wĕ⁠yádò֛ţ mi⁠zė֥h ẇ⁠mi⁠zė֖h ʼel-mĕq֣wòm ha⁠şá֑̇̌beţ ẇ⁠şĕ̌na֣yim ʼàráy֔wòţ ʻòmĕdi֖ym ʼé֥ẕel ha⁠yá̇dֽwòţ׃"],[10,20,"וּ⁠שְׁנֵ֧ים עָשָׂ֣ר אֲרָיִ֗ים עֹמְדִ֥ים שָׁ֛ם עַל־שֵׁ֥שׁ הַֽ⁠מַּעֲל֖וֹת מִ⁠זֶּ֣ה וּ⁠מִ⁠זֶּ֑ה לֹֽא־נַעֲשָׂ֥ה כֵ֖ן לְ⁠כָל־מַמְלָכֽוֹת׃","ẇ⁠şĕ̌né֧ym ʻáşá֣̂r ʼàráyi֗ym ʻòmĕdi֥ym şá֛̌m ʻal-şé֥̌ş̌ haֽ⁠mȧʻàl֖wòţ mi⁠zė֣h ẇ⁠mi⁠zė֑h lòֽʼ-naʻàşá֥̂h ké֖n lĕ⁠kál-mamĕlákֽwòţ׃"],[10,21,"וְ֠⁠כֹל כְּלֵ֞י מַשְׁקֵ֨ה הַ⁠מֶּ֤לֶךְ שְׁלֹמֹה֙ זָהָ֔ב וְ⁠כֹ֗ל כְּלֵ֛י בֵּֽית־יַ֥עַר הַ⁠לְּבָנ֖וֹן זָהָ֣ב סָג֑וּר אֵ֣ין כֶּ֗סֶף לֹ֥א נֶחְשָׁ֛ב בִּ⁠ימֵ֥י שְׁלֹמֹ֖ה לִ⁠מְאֽוּמָה׃","wĕ֠⁠kòl kĕ̇lé֞y maşĕ̌qé֨h ha⁠mė֤lekĕ şĕ̌lòmòh֙ záhá֔b wĕ⁠kò֗l kĕ̇lé֛y béֽ̇yţ-ya֥ʻar ha⁠lĕ̇bán֖wòn záhá֣b ság֑ẇr ʼé֣yn kė֗sep lò֥ʼ neẖĕşá֛̌b bi̇⁠ymé֥y şĕ̌lòmò֖h li⁠mĕʼֽẇmáh׃"],[10,22,"כִּי֩ אֳנִ֨י תַרְשִׁ֤ישׁ לַ⁠מֶּ֨לֶךְ֙ בַּ⁠יָּ֔ם עִ֖ם אֳנִ֣י חִירָ֑ם אַחַת֩ לְ⁠שָׁלֹ֨שׁ שָׁנִ֜ים תָּב֣וֹא ׀ אֳנִ֣י תַרְשִׁ֗ישׁ נֹֽשְׂאֵת֙ זָהָ֣ב וָ⁠כֶ֔סֶף שֶׁנְהַבִּ֥ים וְ⁠קֹפִ֖ים וְ⁠תֻכִּיִּֽים׃","ki̇y֩ ʼoni֨y ţarĕşǐ֤yş̌ la⁠mė֨lekĕ֙ bȧ⁠yá̇֔m ʻi֖m ʼoni֣y ẖiyrá֑m ʼaẖaţ֩ lĕ⁠şá̌lò֨ş̌ şá̌ni֜ym ţá̇b֣wòʼ ׀ ʼoni֣y ţarĕşǐ֗yş̌ nòֽşĕ̂ʼéţ֙ záhá֣b wá⁠ke֔sep şěnĕhabi֥̇ym wĕ⁠qòpi֖ym wĕ⁠ţuki̇yiֽ̇ym׃"],[10,23,"וַ⁠יִּגְדַּל֙ הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֔ה מִ⁠כֹּ֖ל מַלְכֵ֣י הָ⁠אָ֑רֶץ לְ⁠עֹ֖שֶׁר וּ⁠לְ⁠חָכְמָֽה׃","wa⁠yi̇gĕdȧl֙ ha⁠mė֣lekĕ şĕ̌lòmò֔h mi⁠kò֖̇l malĕké֣y há⁠ʼá֑reẕ lĕ⁠ʻò֖şěr ẇ⁠lĕ⁠ẖákĕmáֽh׃"],[10,24,"וְ⁠כָ֨ל־הָ⁠אָ֔רֶץ מְבַקְשִׁ֖ים אֶת־פְּנֵ֣י שְׁלֹמֹ֑ה לִ⁠שְׁמֹ֨עַ֙ אֶת־חָכְמָת֔⁠וֹ אֲשֶׁר־נָתַ֥ן אֱלֹהִ֖ים בְּ⁠לִבּֽ⁠וֹ׃","wĕ⁠ká֨l-há⁠ʼá֔reẕ mĕbaqĕşǐ֖ym ʼeţ-pĕ̇né֣y şĕ̌lòmò֑h li⁠şĕ̌mò֨ʻa֙ ʼeţ-ẖákĕmáţ֔⁠wò ʼàşěr-náţa֥n ʼèlòhi֖ym bĕ̇⁠liḃֽ⁠wò׃"],[10,25,"וְ⁠הֵ֣מָּה מְבִאִ֣ים אִ֣ישׁ מִנְחָת֡⁠וֹ כְּלֵ֣י כֶסֶף֩ וּ⁠כְלֵ֨י זָהָ֤ב וּ⁠שְׂלָמוֹת֙ וְ⁠נֵ֣שֶׁק וּ⁠בְשָׂמִ֔ים סוּסִ֖ים וּ⁠פְרָדִ֑ים דְּבַר־שָׁנָ֖ה בְּ⁠שָׁנָֽה׃ס","wĕ⁠hé֣má̇h mĕbiʼi֣ym ʼi֣yş̌ minĕẖáţ֡⁠wò kĕ̇lé֣y kesep֩ ẇ⁠kĕlé֨y záhá֤b ẇ⁠şĕ̂lámwòţ֙ wĕ⁠né֣şěq ẇ⁠bĕşá̂mi֔ym sẇsi֖ym ẇ⁠pĕrádi֑ym dĕ̇bar-şá̌ná֖h bĕ̇⁠şá̌náֽh׃s"],[10,26,"וַ⁠יֶּאֱסֹ֣ף שְׁלֹמֹה֮ רֶ֣כֶב וּ⁠פָרָשִׁים֒ וַ⁠יְהִי־ל֗⁠וֹ אֶ֤לֶף וְ⁠אַרְבַּע־מֵאוֹת֙ רֶ֔כֶב וּ⁠שְׁנֵים־עָשָׂ֥ר אֶ֖לֶף פָּֽרָשִׁ֑ים וַ⁠יַּנְחֵ⁠ם֙ בְּ⁠עָרֵ֣י הָ⁠רֶ֔כֶב וְ⁠עִם־הַ⁠מֶּ֖לֶךְ בִּ⁠ירוּשָׁלִָֽם׃","wa⁠yėʼèsò֣p şĕ̌lòmòh֮ re֣keb ẇ⁠páráşǐym֒ wa⁠yĕhiy-l֗⁠wò ʼe֤lep wĕ⁠ʼarĕbȧʻ-méʼwòţ֙ re֔keb ẇ⁠şĕ̌néym-ʻáşá֥̂r ʼe֖lep páֽ̇ráşǐ֑ym wa⁠yȧnĕẖé⁠m֙ bĕ̇⁠ʻáré֣y há⁠re֔keb wĕ⁠ʻim-ha⁠mė֖lekĕ bi̇⁠yrẇşá̌liáֽm׃"],[10,27,"וַ⁠יִּתֵּ֨ן הַ⁠מֶּ֧לֶךְ אֶת־הַ⁠כֶּ֛סֶף בִּ⁠ירוּשָׁלִַ֖ם כָּ⁠אֲבָנִ֑ים וְ⁠אֵ֣ת הָ⁠אֲרָזִ֗ים נָתַ֛ן כַּ⁠שִּׁקְמִ֥ים אֲשֶׁר־בַּ⁠שְּׁפֵלָ֖ה לָ⁠רֹֽב׃","wa⁠yi̇ţé̇֨n ha⁠mė֧lekĕ ʼeţ-ha⁠kė֛sep bi̇⁠yrẇşá̌lia֖m ká̇⁠ʼàbáni֑ym wĕ⁠ʼé֣ţ há⁠ʼàrázi֗ym náţa֛n kȧ⁠şi̇̌qĕmi֥ym ʼàşěr-bȧ⁠şĕ̇̌pélá֖h lá⁠ròֽb׃"],[10,28,"וּ⁠מוֹצָ֧א הַ⁠סּוּסִ֛ים אֲשֶׁ֥ר לִ⁠שְׁלֹמֹ֖ה מִ⁠מִּצְרָ֑יִם וּ⁠מִ⁠קְוֵ֕ה סֹחֲרֵ֣י הַ⁠מֶּ֔לֶךְ יִקְח֥וּ מִ⁠קְוֵ֖ה בִּ⁠מְחִֽיר׃","ẇ⁠mwòẕá֧ʼ ha⁠ṡẇsi֛ym ʼàşě֥r li⁠şĕ̌lòmò֖h mi⁠mi̇ẕĕrá֑yim ẇ⁠mi⁠qĕwé֕h sòẖàré֣y ha⁠mė֔lekĕ yiqĕẖ֥ẇ mi⁠qĕwé֖h bi̇⁠mĕẖiֽyr׃"],[10,29,"וַֽ֠⁠תַּעֲלֶה וַ⁠תֵּצֵ֨א מֶרְכָּבָ֤ה מִ⁠מִּצְרַ֨יִם֙ בְּ⁠שֵׁ֣שׁ מֵא֣וֹת כֶּ֔סֶף וְ⁠ס֖וּס בַּ⁠חֲמִשִּׁ֣ים וּ⁠מֵאָ֑ה וְ֠⁠כֵן לְ⁠כָל־מַלְכֵ֧י הַ⁠חִתִּ֛ים וּ⁠לְ⁠מַלְכֵ֥י אֲרָ֖ם בְּ⁠יָדָ֥⁠ם יֹצִֽאוּ׃פ","waֽ֠⁠ţȧʻàleh wa⁠ţé̇ẕé֨ʼ merĕká̇bá֤h mi⁠mi̇ẕĕra֨yim֙ bĕ̇⁠şé֣̌ş̌ méʼ֣wòţ kė֔sep wĕ⁠s֖ẇs bȧ⁠ẖàmişi֣̇̌ym ẇ⁠méʼá֑h wĕ֠⁠kén lĕ⁠kál-malĕké֧y ha⁠ẖiţi֛̇ym ẇ⁠lĕ⁠malĕké֥y ʼàrá֖m bĕ̇⁠yádá֥⁠m yòẕiֽʼẇ׃p"],[11,1,"וְ⁠הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֗ה אָהַ֞ב נָשִׁ֧ים נָכְרִיּ֛וֹת רַבּ֖וֹת וְ⁠אֶת־בַּת־פַּרְעֹ֑ה מוֹאֲבִיּ֤וֹת עַמֳּנִיּוֹת֙ אֲדֹ֣מִיֹּ֔ת צֵדְנִיֹּ֖ת חִתִּיֹּֽת׃","wĕ⁠ha⁠mė֣lekĕ şĕ̌lòmò֗h ʼáha֞b náşǐ֧ym nákĕriẏ֛wòţ raḃ֖wòţ wĕ⁠ʼeţ-bȧţ-pȧrĕʻò֑h mwòʼàbiẏ֤wòţ ʻamȯniẏwòţ֙ ʼàdò֣miyò̇֔ţ ẕédĕniyò֖̇ţ ẖiţi̇yòֽ̇ţ׃"],[11,2,"מִן־הַ⁠גּוֹיִ֗ם אֲשֶׁ֣ר אָֽמַר־יְהוָה֩ אֶל־בְּנֵ֨י יִשְׂרָאֵ֜ל לֹֽא־תָבֹ֣אוּ בָ⁠הֶ֗ם וְ⁠הֵם֙ לֹא־יָבֹ֣אוּ בָ⁠כֶ֔ם אָכֵן֙ יַטּ֣וּ אֶת־לְבַבְ⁠כֶ֔ם אַחֲרֵ֖י אֱלֹהֵי⁠הֶ֑ם בָּ⁠הֶ֛ם דָּבַ֥ק שְׁלֹמֹ֖ה לְ⁠אַהֲבָֽה׃","min-ha⁠ġwòyi֗m ʼàşě֣r ʼáֽmar-yĕhwáh֩ ʼel-bĕ̇né֨y yişĕ̂ráʼé֜l lòֽʼ-ţábò֣ʼẇ bá⁠he֗m wĕ⁠hém֙ lòʼ-yábò֣ʼẇ bá⁠ke֔m ʼákén֙ yaṫ֣ẇ ʼeţ-lĕbabĕ⁠ke֔m ʼaẖàré֖y ʼèlòhéy⁠he֑m bá̇⁠he֛m dá̇ba֥q şĕ̌lòmò֖h lĕ⁠ʼahàbáֽh׃"],[11,3,"וַ⁠יְהִי־ל֣⁠וֹ נָשִׁ֗ים שָׂרוֹת֙ שְׁבַ֣ע מֵא֔וֹת וּ⁠פִֽלַגְשִׁ֖ים שְׁלֹ֣שׁ מֵא֑וֹת וַ⁠יַּטּ֥וּ נָשָׁ֖י⁠ו אֶת־לִבּֽ⁠וֹ׃","wa⁠yĕhiy-l֣⁠wò náşǐ֗ym şá̂rwòţ֙ şĕ̌ba֣ʻ méʼ֔wòţ ẇ⁠piֽlagĕşǐ֖ym şĕ̌lò֣ş̌ méʼ֑wòţ wa⁠yȧṫ֥ẇ náşá֖̌y⁠w ʼeţ-liḃֽ⁠wò׃"],[11,4,"וַ⁠יְהִ֗י לְ⁠עֵת֙ זִקְנַ֣ת שְׁלֹמֹ֔ה נָשָׁי⁠ו֙ הִטּ֣וּ אֶת־לְבָב֔⁠וֹ אַחֲרֵ֖י אֱלֹהִ֣ים אֲחֵרִ֑ים וְ⁠לֹא־הָיָ֨ה לְבָב֤⁠וֹ שָׁלֵם֙ עִם־יְהוָ֣ה אֱלֹהָ֔י⁠ו כִּ⁠לְבַ֖ב דָּוִ֥יד אָבִֽי⁠ו׃","wa⁠yĕhi֗y lĕ⁠ʻéţ֙ ziqĕna֣ţ şĕ̌lòmò֔h náşá̌y⁠w֙ hiṫ֣ẇ ʼeţ-lĕbáb֔⁠wò ʼaẖàré֖y ʼèlòhi֣ym ʼàẖéri֑ym wĕ⁠lòʼ-háyá֨h lĕbáb֤⁠wò şá̌lém֙ ʻim-yĕhwá֣h ʼèlòhá֔y⁠w ki̇⁠lĕba֖b dá̇wi֥yd ʼábiֽy⁠w׃"],[11,5,"וַ⁠יֵּ֣לֶךְ שְׁלֹמֹ֔ה אַחֲרֵ֣י עַשְׁתֹּ֔רֶת אֱלֹהֵ֖י צִדֹנִ֑ים וְ⁠אַחֲרֵ֣י מִלְכֹּ֔ם שִׁקֻּ֖ץ עַמֹּנִֽים׃","wa⁠yé֣̇lekĕ şĕ̌lòmò֔h ʼaẖàré֣y ʻaşĕ̌ţò̇֔reţ ʼèlòhé֖y ẕidòni֑ym wĕ⁠ʼaẖàré֣y milĕkò̇֔m şǐqu֖̇ẕ ʻamò̇niֽym׃"],[11,6,"וַ⁠יַּ֧עַשׂ שְׁלֹמֹ֛ה הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וְ⁠לֹ֥א מִלֵּ֛א אַחֲרֵ֥י יְהוָ֖ה כְּ⁠דָוִ֥ד אָבִֽי⁠ו׃ס","wa⁠yȧ֧ʻaş̂ şĕ̌lòmò֛h há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wĕ⁠lò֥ʼ milé֛̇ʼ ʼaẖàré֥y yĕhwá֖h kĕ̇⁠dáwi֥d ʼábiֽy⁠w׃s"],[11,7,"אָז֩ יִבְנֶ֨ה שְׁלֹמֹ֜ה בָּמָ֗ה לִ⁠כְמוֹשׁ֙ שִׁקֻּ֣ץ מוֹאָ֔ב בָּ⁠הָ֕ר אֲשֶׁ֖ר עַל־פְּנֵ֣י יְרוּשָׁלִָ֑ם וּ⁠לְ⁠מֹ֕לֶךְ שִׁקֻּ֖ץ בְּנֵ֥י עַמּֽוֹן׃","ʼáz֩ yibĕne֨h şĕ̌lòmò֜h bá̇má֗h li⁠kĕmwòş̌֙ şǐqu֣̇ẕ mwòʼá֔b bá̇⁠há֕r ʼàşě֖r ʻal-pĕ̇né֣y yĕrẇşá̌liá֑m ẇ⁠lĕ⁠mò֕lekĕ şǐqu֖̇ẕ bĕ̇né֥y ʻaṁֽwòn׃"],[11,8,"וְ⁠כֵ֣ן עָשָׂ֔ה לְ⁠כָל־נָשָׁ֖י⁠ו הַ⁠נָּכְרִיּ֑וֹת מַקְטִיר֥וֹת וּֽ⁠מְזַבְּח֖וֹת לֵ⁠אלֹהֵי⁠הֶֽן׃","wĕ⁠ké֣n ʻáşá̂֔h lĕ⁠kál-náşá֖̌y⁠w ha⁠ná̇kĕriẏ֑wòţ maqĕtiyr֥wòţ ẇֽ⁠mĕzabĕ̇ẖ֖wòţ lé⁠ʼlòhéy⁠heֽn׃"],[11,9,"וַ⁠יִּתְאַנַּ֥ף יְהוָ֖ה בִּ⁠שְׁלֹמֹ֑ה כִּֽי־נָטָ֣ה לְבָב֗⁠וֹ מֵ⁠עִ֤ם יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל הַ⁠נִּרְאָ֥ה אֵלָ֖י⁠ו פַּעֲמָֽיִם׃","wa⁠yi̇ţĕʼanȧ֥p yĕhwá֖h bi̇⁠şĕ̌lòmò֑h kiֽ̇y-nátá֣h lĕbáb֗⁠wò mé⁠ʻi֤m yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ha⁠ni̇rĕʼá֥h ʼélá֖y⁠w pȧʻàmáֽyim׃"],[11,10,"וְ⁠צִוָּ֤ה אֵלָי⁠ו֙ עַל־הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה לְ⁠בִ֨לְתִּי־לֶ֔כֶת אַחֲרֵ֖י אֱלֹהִ֣ים אֲחֵרִ֑ים וְ⁠לֹ֣א שָׁמַ֔ר אֵ֥ת אֲשֶׁר־צִוָּ֖ה יְהוָֽה׃פ","wĕ⁠ẕiwá֤̇h ʼéláy⁠w֙ ʻal-ha⁠dá̇bá֣r ha⁠zė֔h lĕ⁠bi֨lĕţi̇y-le֔keţ ʼaẖàré֖y ʼèlòhi֣ym ʼàẖéri֑ym wĕ⁠lò֣ʼ şá̌ma֔r ʼé֥ţ ʼàşěr-ẕiwá֖̇h yĕhwáֽh׃p"],[11,11,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה לִ⁠שְׁלֹמֹ֗ה יַ֚עַן אֲשֶׁ֣ר הָֽיְתָה־זֹּ֣את עִמָּ֔⁠ךְ וְ⁠לֹ֤א שָׁמַ֨רְתָּ֙ בְּרִיתִ֣⁠י וְ⁠חֻקֹּתַ֔⁠י אֲשֶׁ֥ר צִוִּ֖יתִי עָלֶ֑י⁠ךָ קָרֹ֨עַ אֶקְרַ֤ע אֶת־הַ⁠מַּמְלָכָה֙ מֵֽ⁠עָלֶ֔י⁠ךָ וּ⁠נְתַתִּ֖י⁠הָ לְ⁠עַבְדֶּֽ⁠ךָ׃","wa⁠yò̇֨ʼmer yĕhwá֜h li⁠şĕ̌lòmò֗h ya֚ʻan ʼàşě֣r háֽyĕţáh-zò֣̇ʼţ ʻimá̇֔⁠kĕ wĕ⁠lò֤ʼ şá̌ma֨rĕţá̇֙ bĕ̇riyţi֣⁠y wĕ⁠ẖuqò̇ţa֔⁠y ʼàşě֥r ẕiwi֖̇yţiy ʻále֑y⁠ká qárò֨ʻa ʼeqĕra֤ʻ ʼeţ-ha⁠mȧmĕlákáh֙ méֽ⁠ʻále֔y⁠ká ẇ⁠nĕţaţi֖̇y⁠há lĕ⁠ʻabĕdėֽ⁠ká׃"],[11,12,"אַךְ־בְּ⁠יָמֶ֨י⁠ךָ֙ לֹ֣א אֶעֱשֶׂ֔⁠נָּה לְמַ֖עַן דָּוִ֣ד אָבִ֑י⁠ךָ מִ⁠יַּ֥ד בִּנְ⁠ךָ֖ אֶקְרָעֶֽ⁠נָּה׃","ʼakĕ-bĕ̇⁠yáme֨y⁠ká֙ lò֣ʼ ʼeʻèşê֔⁠ná̇h lĕma֖ʻan dá̇wi֣d ʼábi֑y⁠ká mi⁠yȧ֥d bi̇nĕ⁠ká֖ ʼeqĕráʻeֽ⁠ná̇h׃"],[11,13,"רַ֤ק אֶת־כָּל־הַ⁠מַּמְלָכָה֙ לֹ֣א אֶקְרָ֔ע שֵׁ֥בֶט אֶחָ֖ד אֶתֵּ֣ן לִ⁠בְנֶ֑⁠ךָ לְמַ֨עַן֙ דָּוִ֣ד עַבְדִּ֔⁠י וּ⁠לְמַ֥עַן יְרוּשָׁלִַ֖ם אֲשֶׁ֥ר בָּחָֽרְתִּי׃","ra֤q ʼeţ-ká̇l-ha⁠mȧmĕlákáh֙ lò֣ʼ ʼeqĕrá֔ʻ şé֥̌bet ʼeẖá֖d ʼeţé֣̇n li⁠bĕne֑⁠ká lĕma֨ʻan֙ dá̇wi֣d ʻabĕdi̇֔⁠y ẇ⁠lĕma֥ʻan yĕrẇşá̌lia֖m ʼàşě֥r bá̇ẖáֽrĕţi̇y׃"],[11,14,"וַ⁠יָּ֨קֶם יְהוָ֤ה שָׂטָן֙ לִ⁠שְׁלֹמֹ֔ה אֵ֖ת הֲדַ֣ד הָ⁠אֲדֹמִ֑י מִ⁠זֶּ֧רַע הַ⁠מֶּ֛לֶךְ ה֖וּא בֶּ⁠אֱדֽוֹם׃","wa⁠yá̇֨qem yĕhwá֤h şá̂tán֙ li⁠şĕ̌lòmò֔h ʼé֖ţ hàda֣d há⁠ʼàdòmi֑y mi⁠zė֧raʻ ha⁠mė֛lekĕ h֖ẇʼ bė⁠ʼèdֽwòm׃"],[11,15,"וַ⁠יְהִ֗י בִּֽ⁠הְי֤וֹת דָּוִד֙ אֶת־אֱד֔וֹם בַּ⁠עֲל֗וֹת יוֹאָב֙ שַׂ֣ר הַ⁠צָּבָ֔א לְ⁠קַבֵּ֖ר אֶת־הַ⁠חֲלָלִ֑ים וַ⁠יַּ֥ךְ כָּל־זָכָ֖ר בֶּ⁠אֱדֽוֹם׃","wa⁠yĕhi֗y biֽ̇⁠hĕy֤wòţ dá̇wid֙ ʼeţ-ʼèd֔wòm bȧ⁠ʻàl֗wòţ ywòʼáb֙ şâ֣r ha⁠ẕá̇bá֔ʼ lĕ⁠qabé֖̇r ʼeţ-ha⁠ẖàláli֑ym wa⁠yȧ֥kĕ ká̇l-záká֖r bė⁠ʼèdֽwòm׃"],[11,16,"כִּ֣י שֵׁ֧שֶׁת חֳדָשִׁ֛ים יָֽשַׁב־שָׁ֥ם יוֹאָ֖ב וְ⁠כָל־יִשְׂרָאֵ֑ל עַד־הִכְרִ֥ית כָּל־זָכָ֖ר בֶּ⁠אֱדֽוֹם׃","ki֣̇y şé֧̌şěţ ẖodáşǐ֛ym yáֽşǎb-şá֥̌m ywòʼá֖b wĕ⁠kál-yişĕ̂ráʼé֑l ʻad-hikĕri֥yţ ká̇l-záká֖r bė⁠ʼèdֽwòm׃"],[11,17,"וַ⁠יִּבְרַ֣ח אֲדַ֡ד הוּא֩ וַ⁠אֲנָשִׁ֨ים אֲדֹמִיִּ֜ים מֵ⁠עַבְדֵ֥י אָבִ֛י⁠ו אִתּ֖⁠וֹ לָ⁠ב֣וֹא מִצְרָ֑יִם וַ⁠הֲדַ֖ד נַ֥עַר קָטָֽן׃","wa⁠yi̇bĕra֣ẖ ʼàda֡d hẇʼ֩ wa⁠ʼànáşǐ֨ym ʼàdòmiyi̇֜ym mé⁠ʻabĕdé֥y ʼábi֛y⁠w ʼiţ֖̇⁠wò lá⁠b֣wòʼ miẕĕrá֑yim wa⁠hàda֖d na֥ʻar qátáֽn׃"],[11,18,"וַ⁠יָּקֻ֨מוּ֙ מִ⁠מִּדְיָ֔ן וַ⁠יָּבֹ֖אוּ פָּארָ֑ן וַ⁠יִּקְחוּ֩ אֲנָשִׁ֨ים עִמָּ֜⁠ם מִ⁠פָּארָ֗ן וַ⁠יָּבֹ֤אוּ מִצְרַ֨יִם֙ אֶל־פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרַ֔יִם וַ⁠יִּתֶּן־ל֣⁠וֹ בַ֗יִת וְ⁠לֶ֨חֶם֙ אָ֣מַר ל֔⁠וֹ וְ⁠אֶ֖רֶץ נָ֥תַן לֽ⁠וֹ׃","wa⁠yá̇qu֨mẇ֙ mi⁠mi̇dĕyá֔n wa⁠yá̇bò֖ʼẇ pá̇ʼrá֑n wa⁠yi̇qĕẖẇ֩ ʼànáşǐ֨ym ʻimá̇֜⁠m mi⁠pá̇ʼrá֗n wa⁠yá̇bò֤ʼẇ miẕĕra֨yim֙ ʼel-pȧrĕʻò֣h meֽlekĕ-miẕĕra֔yim wa⁠yi̇ţėn-l֣⁠wò ba֗yiţ wĕ⁠le֨ẖem֙ ʼá֣mar l֔⁠wò wĕ⁠ʼe֖reẕ ná֥ţan lֽ⁠wò׃"],[11,19,"וַ⁠יִּמְצָא֙ הֲדַ֥ד חֵ֛ן בְּ⁠עֵינֵ֥י פַרְעֹ֖ה מְאֹ֑ד וַ⁠יִּתֶּן־ל֤⁠וֹ אִשָּׁה֙ אֶת־אֲח֣וֹת אִשְׁתּ֔⁠וֹ אֲח֖וֹת תַּחְפְּנֵ֥יס הַ⁠גְּבִירָֽה׃","wa⁠yi̇mĕẕáʼ֙ hàda֥d ẖé֛n bĕ̇⁠ʻéyné֥y parĕʻò֖h mĕʼò֑d wa⁠yi̇ţėn-l֤⁠wò ʼişá̇̌h֙ ʼeţ-ʼàẖ֣wòţ ʼişĕ̌ţ̇֔⁠wò ʼàẖ֖wòţ ţȧẖĕpĕ̇né֥ys ha⁠gĕ̇biyráֽh׃"],[11,20,"וַ⁠תֵּ֨לֶד ל֜⁠וֹ אֲח֣וֹת תַּחְפְּנֵ֗יס אֵ֚ת גְּנֻבַ֣ת בְּנ֔⁠וֹ וַ⁠תִּגְמְלֵ֣⁠הוּ תַחְפְּנֵ֔ס בְּ⁠ת֖וֹךְ בֵּ֣ית פַּרְעֹ֑ה וַ⁠יְהִ֤י גְנֻבַת֙ בֵּ֣ית פַּרְעֹ֔ה בְּ⁠ת֖וֹךְ בְּנֵ֥י פַרְעֹֽה׃","wa⁠ţé̇֨led l֜⁠wò ʼàẖ֣wòţ ţȧẖĕpĕ̇né֗ys ʼé֚ţ gĕ̇nuba֣ţ bĕ̇n֔⁠wò wa⁠ţi̇gĕmĕlé֣⁠hẇ ţaẖĕpĕ̇né֔s bĕ̇⁠ţ֖wòkĕ bé֣̇yţ pȧrĕʻò֑h wa⁠yĕhi֤y gĕnubaţ֙ bé֣̇yţ pȧrĕʻò֔h bĕ̇⁠ţ֖wòkĕ bĕ̇né֥y parĕʻòֽh׃"],[11,21,"וַ⁠הֲדַ֞ד שָׁמַ֣ע בְּ⁠מִצְרַ֗יִם כִּֽי־שָׁכַ֤ב דָּוִד֙ עִם־אֲבֹתָ֔י⁠ו וְ⁠כִי־מֵ֖ת יוֹאָ֣ב שַֽׂר־הַ⁠צָּבָ֑א וַ⁠יֹּ֤אמֶר הֲדַד֙ אֶל־פַּרְעֹ֔ה שַׁלְּחֵ֖⁠נִי וְ⁠אֵלֵ֥ךְ אֶל־אַרְצִֽ⁠י׃","wa⁠hàda֞d şá̌ma֣ʻ bĕ̇⁠miẕĕra֗yim kiֽ̇y-şá̌ka֤b dá̇wid֙ ʻim-ʼàbòţá֔y⁠w wĕ⁠kiy-mé֖ţ ywòʼá֣b şâֽr-ha⁠ẕá̇bá֑ʼ wa⁠yò֤̇ʼmer hàdad֙ ʼel-pȧrĕʻò֔h şǎlĕ̇ẖé֖⁠niy wĕ⁠ʼélé֥kĕ ʼel-ʼarĕẕiֽ⁠y׃"],[11,22,"וַ⁠יֹּ֧אמֶר ל֣⁠וֹ פַרְעֹ֗ה כִּ֠י מָה־אַתָּ֤ה חָסֵר֙ עִמִּ֔⁠י וְ⁠הִנְּ⁠ךָ֥ מְבַקֵּ֖שׁ לָ⁠לֶ֣כֶת אֶל־אַרְצֶ֑⁠ךָ וַ⁠יֹּ֣אמֶר ׀ לֹ֔א כִּ֥י שַׁלֵּ֖חַ תְּשַׁלְּחֵֽ⁠נִי׃","wa⁠yò֧̇ʼmer l֣⁠wò parĕʻò֗h ki̇֠y máh-ʼaţá֤̇h ẖásér֙ ʻimi̇֔⁠y wĕ⁠hinĕ̇⁠ká֥ mĕbaqé֖̇ş̌ lá⁠le֣keţ ʼel-ʼarĕẕe֑⁠ká wa⁠yò֣̇ʼmer ׀ lò֔ʼ ki֥̇y şǎlé֖̇ẖa ţĕ̇şǎlĕ̇ẖéֽ⁠niy׃"],[11,23,"וַ⁠יָּ֨קֶם אֱלֹהִ֥ים ל⁠וֹ֙ שָׂטָ֔ן אֶת־רְז֖וֹן בֶּן־אֶלְיָדָ֑ע אֲשֶׁ֣ר בָּרַ֗ח מֵ⁠אֵ֛ת הֲדַדְעֶ֥זֶר מֶֽלֶךְ־צוֹבָ֖ה אֲדֹנָֽי⁠ו׃","wa⁠yá̇֨qem ʼèlòhi֥ym l⁠wò֙ şá̂tá֔n ʼeţ-rĕz֖wòn bėn-ʼelĕyádá֑ʻ ʼàşě֣r bá̇ra֗ẖ mé⁠ʼé֛ţ hàdadĕʻe֥zer meֽlekĕ-ẕwòbá֖h ʼàdònáֽy⁠w׃"],[11,24,"וַ⁠יִּקְבֹּ֤ץ עָלָי⁠ו֙ אֲנָשִׁ֔ים וַ⁠יְהִ֣י שַׂר־גְּד֔וּד בַּ⁠הֲרֹ֥ג דָּוִ֖ד אֹתָ֑⁠ם וַ⁠יֵּלְכ֤וּ דַמֶּ֨שֶׂק֙ וַ⁠יֵּ֣שְׁבוּ בָ֔⁠הּ וַֽ⁠יִּמְלְכ֖וּ בְּ⁠דַמָּֽשֶׂק׃","wa⁠yi̇qĕbò֤̇ẕ ʻáláy⁠w֙ ʼànáşǐ֔ym wa⁠yĕhi֣y şâr-gĕ̇d֔ẇd bȧ⁠hàrò֥g dá̇wi֖d ʼòţá֑⁠m wa⁠yé̇lĕk֤ẇ damė֨şêq֙ wa⁠yé֣̇şĕ̌bẇ bá֔⁠ḣ waֽ⁠yi̇mĕlĕk֖ẇ bĕ̇⁠damáֽ̇şêq׃"],[11,25,"וַ⁠יְהִ֨י שָׂטָ֤ן לְ⁠יִשְׂרָאֵל֙ כָּל־יְמֵ֣י שְׁלֹמֹ֔ה וְ⁠אֶת־הָ⁠רָעָ֖ה אֲשֶׁ֣ר הֲדָ֑ד וַ⁠יָּ֨קָץ֙ בְּ⁠יִשְׂרָאֵ֔ל וַ⁠יִּמְלֹ֖ךְ עַל־אֲרָֽם׃פ","wa⁠yĕhi֨y şá̂tá֤n lĕ⁠yişĕ̂ráʼél֙ ká̇l-yĕmé֣y şĕ̌lòmò֔h wĕ⁠ʼeţ-há⁠ráʻá֖h ʼàşě֣r hàdá֑d wa⁠yá̇֨qáẕ֙ bĕ̇⁠yişĕ̂ráʼé֔l wa⁠yi̇mĕlò֖kĕ ʻal-ʼàráֽm׃p"],[11,26,"וְ⁠יָרָבְעָם֩ בֶּן־נְבָ֨ט אֶפְרָתִ֜י מִן־הַ⁠צְּרֵדָ֗ה וְ⁠שֵׁ֤ם אִמּ⁠וֹ֙ צְרוּעָה֙ אִשָּׁ֣ה אַלְמָנָ֔ה עֶ֖בֶד לִ⁠שְׁלֹמֹ֑ה וַ⁠יָּ֥רֶם יָ֖ד בַּ⁠מֶּֽלֶךְ׃","wĕ⁠yárábĕʻám֩ bėn-nĕbá֨t ʼepĕráţi֜y min-ha⁠ẕĕ̇rédá֗h wĕ⁠şé֤̌m ʼiṁ⁠wò֙ ẕĕrẇʻáh֙ ʼişá֣̇̌h ʼalĕmáná֔h ʻe֖bed li⁠şĕ̌lòmò֑h wa⁠yá֥̇rem yá֖d bȧ⁠mėֽlekĕ׃"],[11,27,"וְ⁠זֶ֣ה הַ⁠דָּבָ֔ר אֲשֶׁר־הֵרִ֥ים יָ֖ד בַּ⁠מֶּ֑לֶךְ שְׁלֹמֹה֙ בָּנָ֣ה אֶת־הַ⁠מִּלּ֔וֹא סָגַ֕ר אֶת־פֶּ֕רֶץ עִ֖יר דָּוִ֥ד אָבִֽי⁠ו׃","wĕ⁠ze֣h ha⁠dá̇bá֔r ʼàşěr-héri֥ym yá֖d bȧ⁠mė֑lekĕ şĕ̌lòmòh֙ bá̇ná֣h ʼeţ-ha⁠mi̇l̇֔wòʼ sága֕r ʼeţ-pė֕reẕ ʻi֖yr dá̇wi֥d ʼábiֽy⁠w׃"],[11,28,"וְ⁠הָ⁠אִ֥ישׁ יָרָבְעָ֖ם גִּבּ֣וֹר חָ֑יִל וַ⁠יַּ֨רְא שְׁלֹמֹ֜ה אֶת־הַ⁠נַּ֗עַר כִּֽי־עֹשֵׂ֤ה מְלָאכָה֙ ה֔וּא וַ⁠יַּפְקֵ֣ד אֹת֔⁠וֹ לְ⁠כָל־סֵ֖בֶל בֵּ֥ית יוֹסֵֽף׃ס","wĕ⁠há⁠ʼi֥yş̌ yárábĕʻá֖m gi̇ḃ֣wòr ẖá֑yil wa⁠yȧ֨rĕʼ şĕ̌lòmò֜h ʼeţ-ha⁠nȧ֗ʻar kiֽ̇y-ʻòşé֤̂h mĕláʼkáh֙ h֔ẇʼ wa⁠yȧpĕqé֣d ʼòţ֔⁠wò lĕ⁠kál-sé֖bel bé֥̇yţ ywòséֽp׃s"],[11,29,"וַֽ⁠יְהִי֙ בָּ⁠עֵ֣ת הַ⁠הִ֔יא וְ⁠יָֽרָבְעָ֖ם יָצָ֣א מִ⁠ירוּשָׁלִָ֑ם וַ⁠יִּמְצָ֣א אֹת֡⁠וֹ אֲחִיָּה֩ הַ⁠שִּׁילֹנִ֨י הַ⁠נָּבִ֜יא בַּ⁠דֶּ֗רֶךְ וְ⁠ה֤וּא מִתְכַּסֶּה֙ בְּ⁠שַׂלְמָ֣ה חֲדָשָׁ֔ה וּ⁠שְׁנֵי⁠הֶ֥ם לְ⁠בַדָּ֖⁠ם בַּ⁠שָּׂדֶֽה׃","waֽ⁠yĕhiy֙ bá̇⁠ʻé֣ţ ha⁠hi֔yʼ wĕ⁠yáֽrábĕʻá֖m yáẕá֣ʼ mi⁠yrẇşá̌liá֑m wa⁠yi̇mĕẕá֣ʼ ʼòţ֡⁠wò ʼàẖiyá̇h֩ ha⁠şi̇̌ylòni֨y ha⁠ná̇bi֜yʼ bȧ⁠dė֗rekĕ wĕ⁠h֤ẇʼ miţĕkȧsėh֙ bĕ̇⁠şâlĕmá֣h ẖàdáşá̌֔h ẇ⁠şĕ̌néy⁠he֥m lĕ⁠badá֖̇⁠m bȧ⁠şá̇̂deֽh׃"],[11,30,"וַ⁠יִּתְפֹּ֣שׂ אֲחִיָּ֔ה בַּ⁠שַּׂלְמָ֥ה הַ⁠חֲדָשָׁ֖ה אֲשֶׁ֣ר עָלָ֑י⁠ו וַ⁠יִּ֨קְרָעֶ֔⁠הָ שְׁנֵ֥ים עָשָׂ֖ר קְרָעִֽים׃","wa⁠yi̇ţĕpò֣̇ş̂ ʼàẖiyá̇֔h bȧ⁠şȧ̂lĕmá֥h ha⁠ẖàdáşá֖̌h ʼàşě֣r ʻálá֑y⁠w wa⁠yi̇֨qĕráʻe֔⁠há şĕ̌né֥ym ʻáşá֖̂r qĕráʻiֽym׃"],[11,31,"וַ⁠יֹּ֨אמֶר֙ לְ⁠יָֽרָבְעָ֔ם קַח־לְ⁠ךָ֖ עֲשָׂרָ֣ה קְרָעִ֑ים כִּ֣י כֹה֩ אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֣י יִשְׂרָאֵ֗ל הִנְ⁠נִ֨י קֹרֵ֤עַ אֶת־הַ⁠מַּמְלָכָה֙ מִ⁠יַּ֣ד שְׁלֹמֹ֔ה וְ⁠נָתַתִּ֣י לְ⁠ךָ֔ אֵ֖ת עֲשָׂרָ֥ה הַ⁠שְּׁבָטִֽים׃","wa⁠yò̇֨ʼmer֙ lĕ⁠yáֽrábĕʻá֔m qaẖ-lĕ⁠ká֖ ʻàşá̂rá֣h qĕráʻi֑ym ki֣̇y kòh֩ ʼáma֨r yĕhwá֜h ʼèlòhé֣y yişĕ̂ráʼé֗l hinĕ⁠ni֨y qòré֤ʻa ʼeţ-ha⁠mȧmĕlákáh֙ mi⁠yȧ֣d şĕ̌lòmò֔h wĕ⁠náţaţi֣̇y lĕ⁠ká֔ ʼé֖ţ ʻàşá̂rá֥h ha⁠şĕ̇̌bátiֽym׃"],[11,32,"וְ⁠הַ⁠שֵּׁ֥בֶט הָ⁠אֶחָ֖ד יִֽהְיֶה־לּ֑⁠וֹ לְמַ֣עַן ׀ עַבְדִּ֣⁠י דָוִ֗ד וּ⁠לְמַ֨עַן֙ יְר֣וּשָׁלִַ֔ם הָ⁠עִיר֙ אֲשֶׁ֣ר בָּחַ֣רְתִּי בָ֔⁠הּ מִ⁠כֹּ֖ל שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ha⁠şé֥̇̌bet há⁠ʼeẖá֖d yiֽhĕyeh-l֑̇⁠wò lĕma֣ʻan ׀ ʻabĕdi֣̇⁠y dáwi֗d ẇ⁠lĕma֨ʻan֙ yĕr֣ẇşá̌lia֔m há⁠ʻiyr֙ ʼàşě֣r bá̇ẖa֣rĕţi̇y bá֔⁠ḣ mi⁠kò֖̇l şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[11,33,"יַ֣עַן ׀ אֲשֶׁ֣ר עֲזָב֗וּ⁠נִי וַ⁠יִּֽשְׁתַּחֲווּ֮ לְ⁠עַשְׁתֹּרֶת֮ אֱלֹהֵ֣י צִֽדֹנִין֒ לִ⁠כְמוֹשׁ֙ אֱלֹהֵ֣י מוֹאָ֔ב וּ⁠לְ⁠מִלְכֹּ֖ם אֱלֹהֵ֣י בְנֵֽי־עַמּ֑וֹן וְ⁠לֹֽא־הָלְכ֣וּ בִ⁠דְרָכַ֗⁠י לַ⁠עֲשׂ֨וֹת הַ⁠יָּשָׁ֧ר בְּ⁠עֵינַ֛⁠י וְ⁠חֻקֹּתַ֥⁠י וּ⁠מִשְׁפָּטַ֖⁠י כְּ⁠דָוִ֥ד אָבִֽי⁠ו׃","ya֣ʻan ׀ ʼàşě֣r ʻàzáb֗ẇ⁠niy wa⁠yiֽ̇şĕ̌ţȧẖàwẇ֮ lĕ⁠ʻaşĕ̌ţò̇reţ֮ ʼèlòhé֣y ẕiֽdòniyn֒ li⁠kĕmwòş̌֙ ʼèlòhé֣y mwòʼá֔b ẇ⁠lĕ⁠milĕkò֖̇m ʼèlòhé֣y bĕnéֽy-ʻaṁ֑wòn wĕ⁠lòֽʼ-hálĕk֣ẇ bi⁠dĕráka֗⁠y la⁠ʻàş̂֨wòţ ha⁠yá̇şá֧̌r bĕ̇⁠ʻéyna֛⁠y wĕ⁠ẖuqò̇ţa֥⁠y ẇ⁠mişĕ̌pá̇ta֖⁠y kĕ̇⁠dáwi֥d ʼábiֽy⁠w׃"],[11,34,"וְ⁠לֹֽא־אֶקַּ֥ח אֶת־כָּל־הַ⁠מַּמְלָכָ֖ה מִ⁠יָּד֑⁠וֹ כִּ֣י ׀ נָשִׂ֣יא אֲשִׁתֶ֗⁠נּוּ כֹּ֚ל יְמֵ֣י חַיָּ֔י⁠ו לְמַ֨עַן דָּוִ֤ד עַבְדִּ⁠י֙ אֲשֶׁ֣ר בָּחַ֣רְתִּי אֹת֔⁠וֹ אֲשֶׁ֥ר שָׁמַ֖ר מִצְוֺתַ֥⁠י וְ⁠חֻקֹּתָֽ⁠י׃","wĕ⁠lòֽʼ-ʼeqȧ֥ẖ ʼeţ-ká̇l-ha⁠mȧmĕláká֖h mi⁠yá̇d֑⁠wò ki֣̇y ׀ náşî֣yʼ ʼàşǐţe֗⁠ṅẇ kò֚̇l yĕmé֣y ẖayá̇֔y⁠w lĕma֨ʻan dá̇wi֤d ʻabĕdi̇⁠y֙ ʼàşě֣r bá̇ẖa֣rĕţi̇y ʼòţ֔⁠wò ʼàşě֥r şá̌ma֖r miẕĕwֺţa֥⁠y wĕ⁠ẖuqò̇ţáֽ⁠y׃"],[11,35,"וְ⁠לָקַחְתִּ֥י הַ⁠מְּלוּכָ֖ה מִ⁠יַּ֣ד בְּנ֑⁠וֹ וּ⁠נְתַתִּ֣י⁠הָ לְּ⁠ךָ֔ אֵ֖ת עֲשֶׂ֥רֶת הַ⁠שְּׁבָטִֽים׃","wĕ⁠láqaẖĕţi֥̇y ha⁠mĕ̇lẇká֖h mi⁠yȧ֣d bĕ̇n֑⁠wò ẇ⁠nĕţaţi֣̇y⁠há lĕ̇⁠ká֔ ʼé֖ţ ʻàşê֥reţ ha⁠şĕ̇̌bátiֽym׃"],[11,36,"וְ⁠לִ⁠בְנ֖⁠וֹ אֶתֵּ֣ן שֵֽׁבֶט־אֶחָ֑ד לְמַ֣עַן הֱיֽוֹת־נִ֣יר לְ⁠דָֽוִיד־עַ֠בְדִּ⁠י כָּֽל־הַ⁠יָּמִ֤ים ׀ לְ⁠פָנַ⁠י֙ בִּ⁠יר֣וּשָׁלִַ֔ם הָ⁠עִיר֙ אֲשֶׁ֣ר בָּחַ֣רְתִּי לִ֔⁠י לָ⁠שׂ֥וּם שְׁמִ֖⁠י שָֽׁם׃","wĕ⁠li⁠bĕn֖⁠wò ʼeţé֣̇n şéֽ̌bet-ʼeẖá֑d lĕma֣ʻan hèyֽwòţ-ni֣yr lĕ⁠dáֽwiyd-ʻa֠bĕdi̇⁠y káֽ̇l-ha⁠yá̇mi֤ym ׀ lĕ⁠pána⁠y֙ bi̇⁠yr֣ẇşá̌lia֔m há⁠ʻiyr֙ ʼàşě֣r bá̇ẖa֣rĕţi̇y li֔⁠y lá⁠ş֥̂ẇm şĕ̌mi֖⁠y şáֽ̌m׃"],[11,37,"וְ⁠אֹתְ⁠ךָ֣ אֶקַּ֔ח וּ⁠מָ֣לַכְתָּ֔ בְּ⁠כֹ֥ל אֲשֶׁר־תְּאַוֶּ֖ה נַפְשֶׁ֑⁠ךָ וְ⁠הָיִ֥יתָ מֶּ֖לֶךְ עַל־יִשְׂרָאֵֽל׃","wĕ⁠ʼòţĕ⁠ká֣ ʼeqȧ֔ẖ ẇ⁠má֣lakĕţá̇֔ bĕ̇⁠kò֥l ʼàşěr-ţĕ̇ʼawė֖h napĕşě֑⁠ká wĕ⁠háyi֥yţá mė֖lekĕ ʻal-yişĕ̂ráʼéֽl׃"],[11,38,"וְ⁠הָיָ֗ה אִם־תִּשְׁמַע֮ אֶת־כָּל־אֲשֶׁ֣ר אֲצַוֶּ⁠ךָ֒ וְ⁠הָלַכְתָּ֣ בִ⁠דְרָכַ֗⁠י וְ⁠עָשִׂ֨יתָ הַ⁠יָּשָׁ֤ר בְּ⁠עֵינַ⁠י֙ לִ⁠שְׁמ֤וֹר חֻקּוֹתַ⁠י֙ וּ⁠מִצְוֺתַ֔⁠י כַּ⁠אֲשֶׁ֥ר עָשָׂ֖ה דָּוִ֣ד עַבְדִּ֑⁠י וְ⁠הָיִ֣יתִי עִמָּ֗⁠ךְ וּ⁠בָנִ֨יתִי לְ⁠ךָ֤ בַֽיִת־נֶאֱמָן֙ כַּ⁠אֲשֶׁ֣ר בָּנִ֣יתִי לְ⁠דָוִ֔ד וְ⁠נָתַתִּ֥י לְ⁠ךָ֖ אֶת־יִשְׂרָאֵֽל׃","wĕ⁠háyá֗h ʼim-ţi̇şĕ̌maʻ֮ ʼeţ-ká̇l-ʼàşě֣r ʼàẕawė⁠ká֒ wĕ⁠hálakĕţá֣̇ bi⁠dĕráka֗⁠y wĕ⁠ʻáşî֨yţá ha⁠yá̇şá֤̌r bĕ̇⁠ʻéyna⁠y֙ li⁠şĕ̌m֤wòr ẖuq̇wòţa⁠y֙ ẇ⁠miẕĕwֺţa֔⁠y kȧ⁠ʼàşě֥r ʻáşá֖̂h dá̇wi֣d ʻabĕdi֑̇⁠y wĕ⁠háyi֣yţiy ʻimá̇֗⁠kĕ ẇ⁠báni֨yţiy lĕ⁠ká֤ baֽyiţ-neʼèmán֙ kȧ⁠ʼàşě֣r bá̇ni֣yţiy lĕ⁠dáwi֔d wĕ⁠náţaţi֥̇y lĕ⁠ká֖ ʼeţ-yişĕ̂ráʼéֽl׃"],[11,39,"וַֽ⁠אעַנֶּ֛ה אֶת־זֶ֥רַע דָּוִ֖ד לְמַ֣עַן זֹ֑את אַ֖ךְ לֹ֥א כָל־הַ⁠יָּמִֽים׃ס","waֽ⁠ʼʻanė֛h ʼeţ-ze֥raʻ dá̇wi֖d lĕma֣ʻan zò֑ʼţ ʼa֖kĕ lò֥ʼ kál-ha⁠yá̇miֽym׃s"],[11,40,"וַ⁠יְבַקֵּ֥שׁ שְׁלֹמֹ֖ה לְ⁠הָמִ֣ית אֶת־יָרָבְעָ֑ם וַ⁠יָּ֣קָם יָרָבְעָ֗ם וַ⁠יִּבְרַ֤ח מִצְרַ֨יִם֙ אֶל־שִׁישַׁ֣ק מֶֽלֶךְ־מִצְרַ֔יִם וַ⁠יְהִ֥י בְ⁠מִצְרַ֖יִם עַד־מ֥וֹת שְׁלֹמֹֽה׃","wa⁠yĕbaqé֥̇ş̌ şĕ̌lòmò֖h lĕ⁠hámi֣yţ ʼeţ-yárábĕʻá֑m wa⁠yá֣̇qám yárábĕʻá֗m wa⁠yi̇bĕra֤ẖ miẕĕra֨yim֙ ʼel-şǐyşǎ֣q meֽlekĕ-miẕĕra֔yim wa⁠yĕhi֥y bĕ⁠miẕĕra֖yim ʻad-m֥wòţ şĕ̌lòmòֽh׃"],[11,41,"וְ⁠יֶ֨תֶר דִּבְרֵ֧י שְׁלֹמֹ֛ה וְ⁠כָל־אֲשֶׁ֥ר עָשָׂ֖ה וְ⁠חָכְמָת֑⁠וֹ הֲ⁠לֽוֹא־הֵ֣ם כְּתֻבִ֔ים עַל־סֵ֖פֶר דִּבְרֵ֥י שְׁלֹמֹֽה׃","wĕ⁠ye֨ţer di̇bĕré֧y şĕ̌lòmò֛h wĕ⁠kál-ʼàşě֥r ʻáşá֖̂h wĕ⁠ẖákĕmáţ֑⁠wò hà⁠lֽwòʼ-hé֣m kĕ̇ţubi֔ym ʻal-sé֖per di̇bĕré֥y şĕ̌lòmòֽh׃"],[11,42,"וְ⁠הַ⁠יָּמִ֗ים אֲשֶׁר֩ מָלַ֨ךְ שְׁלֹמֹ֤ה בִ⁠ירוּשָׁלִַ֨ם֙ עַל־כָּל־יִשְׂרָאֵ֔ל אַרְבָּעִ֖ים שָׁנָֽה׃","wĕ⁠ha⁠yá̇mi֗ym ʼàşěr֩ mála֨kĕ şĕ̌lòmò֤h bi⁠yrẇşá̌lia֨m֙ ʻal-ká̇l-yişĕ̂ráʼé֔l ʼarĕbá̇ʻi֖ym şá̌náֽh׃"],[11,43,"וַ⁠יִּשְׁכַּ֤ב שְׁלֹמֹה֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּ֨קָּבֵ֔ר בְּ⁠עִ֖יר דָּוִ֣ד אָבִ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ רְחַבְעָ֥ם בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃ס","wa⁠yi̇şĕ̌kȧ֤b şĕ̌lòmòh֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇֨qá̇bé֔r bĕ̇⁠ʻi֖yr dá̇wi֣d ʼábi֑y⁠w wa⁠yi̇mĕlò֛kĕ rĕẖabĕʻá֥m bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃s"],[12,1,"וַ⁠יֵּ֥לֶךְ רְחַבְעָ֖ם שְׁכֶ֑ם כִּ֥י שְׁכֶ֛ם בָּ֥א כָל־יִשְׂרָאֵ֖ל לְ⁠הַמְלִ֥יךְ אֹתֽ⁠וֹ׃","wa⁠yé֥̇lekĕ rĕẖabĕʻá֖m şĕ̌ke֑m ki֥̇y şĕ̌ke֛m bá֥̇ʼ kál-yişĕ̂ráʼé֖l lĕ⁠hamĕli֥ykĕ ʼòţֽ⁠wò׃"],[12,2,"וַ⁠יְהִ֞י כִּ⁠שְׁמֹ֣עַ ׀ יָרָבְעָ֣ם בֶּן־נְבָ֗ט וְ⁠הוּא֙ עוֹדֶ֣⁠נּוּ בְ⁠מִצְרַ֔יִם אֲשֶׁ֣ר בָּרַ֔ח מִ⁠פְּנֵ֖י הַ⁠מֶּ֣לֶךְ שְׁלֹמֹ֑ה וַ⁠יֵּ֥שֶׁב יָרָבְעָ֖ם בְּ⁠מִצְרָֽיִם׃","wa⁠yĕhi֞y ki̇⁠şĕ̌mò֣ʻa ׀ yárábĕʻá֣m bėn-nĕbá֗t wĕ⁠hẇʼ֙ ʻwòde֣⁠ṅẇ bĕ⁠miẕĕra֔yim ʼàşě֣r bá̇ra֔ẖ mi⁠pĕ̇né֖y ha⁠mė֣lekĕ şĕ̌lòmò֑h wa⁠yé֥̇şěb yárábĕʻá֖m bĕ̇⁠miẕĕráֽyim׃"],[12,3,"וַֽ⁠יִּשְׁלְחוּ֙ וַ⁠יִּקְרְאוּ־ל֔⁠וֹ ו⁠יבאו יָרָבְעָ֖ם וְ⁠כָל־קְהַ֣ל יִשְׂרָאֵ֑ל וַֽ⁠יְדַבְּר֔וּ אֶל־רְחַבְעָ֖ם לֵ⁠אמֹֽר׃","waֽ⁠yi̇şĕ̌lĕẖẇ֙ wa⁠yi̇qĕrĕʼẇ-l֔⁠wò w⁠ybʼw yárábĕʻá֖m wĕ⁠kál-qĕha֣l yişĕ̂ráʼé֑l waֽ⁠yĕdabĕ̇r֔ẇ ʼel-rĕẖabĕʻá֖m lé⁠ʼmòֽr׃"],[12,4,"אָבִ֖י⁠ךָ הִקְשָׁ֣ה אֶת־עֻלֵּ֑⁠נוּ וְ⁠אַתָּ֡ה עַתָּ֣ה הָקֵל֩ מֵ⁠עֲבֹדַ֨ת אָבִ֜י⁠ךָ הַ⁠קָּשָׁ֗ה וּ⁠מֵ⁠עֻלּ֧⁠וֹ הַ⁠כָּבֵ֛ד אֲשֶׁר־נָתַ֥ן עָלֵ֖י⁠נוּ וְ⁠נַעַבְדֶֽ⁠ךָּ׃","ʼábi֖y⁠ká hiqĕşá֣̌h ʼeţ-ʻulé֑̇⁠nẇ wĕ⁠ʼaţá̇֡h ʻaţá֣̇h háqél֩ mé⁠ʻàbòda֨ţ ʼábi֜y⁠ká ha⁠qá̇şá̌֗h ẇ⁠mé⁠ʻul֧̇⁠wò ha⁠ká̇bé֛d ʼàşěr-náţa֥n ʻálé֖y⁠nẇ wĕ⁠naʻabĕdeֽ⁠ká̇׃"],[12,5,"וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֗ם לְכ֥וּ עֹ֛ד שְׁלֹשָׁ֥ה יָמִ֖ים וְ⁠שׁ֣וּבוּ אֵלָ֑⁠י וַ⁠יֵּלְכ֖וּ הָ⁠עָֽם׃","wa⁠yò֣̇ʼmer ʼàléy⁠he֗m lĕk֥ẇ ʻò֛d şĕ̌lòşá֥̌h yámi֖ym wĕ⁠ş֣̌ẇbẇ ʼélá֑⁠y wa⁠yé̇lĕk֖ẇ há⁠ʻáֽm׃"],[12,6,"וַ⁠יִּוָּעַ֞ץ הַ⁠מֶּ֣לֶךְ רְחַבְעָ֗ם אֶת־הַ⁠זְּקֵנִים֙ אֲשֶׁר־הָי֣וּ עֹמְדִ֗ים אֶת־פְּנֵי֙ שְׁלֹמֹ֣ה אָבִ֔י⁠ו בִּֽ⁠הְיֹת֥⁠וֹ חַ֖י לֵ⁠אמֹ֑ר אֵ֚יךְ אַתֶּ֣ם נֽוֹעָצִ֔ים לְ⁠הָשִׁ֥יב אֶת־הָֽ⁠עָם־הַ⁠זֶּ֖ה דָּבָֽר׃","wa⁠yi̇wá̇ʻa֞ẕ ha⁠mė֣lekĕ rĕẖabĕʻá֗m ʼeţ-ha⁠zĕ̇qéniym֙ ʼàşěr-háy֣ẇ ʻòmĕdi֗ym ʼeţ-pĕ̇néy֙ şĕ̌lòmò֣h ʼábi֔y⁠w biֽ̇⁠hĕyòţ֥⁠wò ẖa֖y lé⁠ʼmò֑r ʼé֚ykĕ ʼaţė֣m nֽwòʻáẕi֔ym lĕ⁠háşǐ֥yb ʼeţ-háֽ⁠ʻám-ha⁠zė֖h dá̇báֽr׃"],[12,7,"ו⁠ידבר אֵלָ֜י⁠ו לֵ⁠אמֹ֗ר אִם־הַ֠⁠יּוֹם תִּֽהְיֶה־עֶ֜בֶד לָ⁠עָ֤ם הַ⁠זֶּה֙ וַֽ⁠עֲבַדְתָּ֔⁠ם וַ⁠עֲנִיתָ֕⁠ם וְ⁠דִבַּרְתָּ֥ אֲלֵי⁠הֶ֖ם דְּבָרִ֣ים טוֹבִ֑ים וְ⁠הָי֥וּ לְ⁠ךָ֛ עֲבָדִ֖ים כָּל־הַ⁠יָּמִֽים׃","w⁠ydbr ʼélá֜y⁠w lé⁠ʼmò֗r ʼim-ha֠⁠ẏwòm ţiֽ̇hĕyeh-ʻe֜bed lá⁠ʻá֤m ha⁠zėh֙ waֽ⁠ʻàbadĕţá̇֔⁠m wa⁠ʻàniyţá֕⁠m wĕ⁠dibȧrĕţá֥̇ ʼàléy⁠he֖m dĕ̇bári֣ym twòbi֑ym wĕ⁠háy֥ẇ lĕ⁠ká֛ ʻàbádi֖ym ká̇l-ha⁠yá̇miֽym׃"],[12,8,"וַֽ⁠יַּעֲזֹ֛ב אֶת־עֲצַ֥ת הַ⁠זְּקֵנִ֖ים אֲשֶׁ֣ר יְעָצֻ֑⁠הוּ וַ⁠יִּוָּעַ֗ץ אֶת־הַ⁠יְלָדִים֙ אֲשֶׁ֣ר גָּדְל֣וּ אִתּ֔⁠וֹ אֲשֶׁ֥ר הָ⁠עֹמְדִ֖ים לְ⁠פָנָֽי⁠ו׃","waֽ⁠yȧʻàzò֛b ʼeţ-ʻàẕa֥ţ ha⁠zĕ̇qéni֖ym ʼàşě֣r yĕʻáẕu֑⁠hẇ wa⁠yi̇wá̇ʻa֗ẕ ʼeţ-ha⁠yĕládiym֙ ʼàşě֣r gá̇dĕl֣ẇ ʼiţ̇֔⁠wò ʼàşě֥r há⁠ʻòmĕdi֖ym lĕ⁠pánáֽy⁠w׃"],[12,9,"וַ⁠יֹּ֣אמֶר אֲלֵי⁠הֶ֗ם מָ֚ה אַתֶּ֣ם נֽוֹעָצִ֔ים וְ⁠נָשִׁ֥יב דָּבָ֖ר אֶת־הָ⁠עָ֣ם הַ⁠זֶּ֑ה אֲשֶׁ֨ר דִּבְּר֤וּ אֵלַ⁠י֙ לֵ⁠אמֹ֔ר הָקֵל֙ מִן־הָ⁠עֹ֔ל אֲשֶׁר־נָתַ֥ן אָבִ֖י⁠ךָ עָלֵֽי⁠נוּ׃","wa⁠yò֣̇ʼmer ʼàléy⁠he֗m má֚h ʼaţė֣m nֽwòʻáẕi֔ym wĕ⁠náşǐ֥yb dá̇bá֖r ʼeţ-há⁠ʻá֣m ha⁠zė֑h ʼàşě֨r di̇bĕ̇r֤ẇ ʼéla⁠y֙ lé⁠ʼmò֔r háqél֙ min-há⁠ʻò֔l ʼàşěr-náţa֥n ʼábi֖y⁠ká ʻáléֽy⁠nẇ׃"],[12,10,"וַ⁠יְדַבְּר֣וּ אֵלָ֗י⁠ו הַ⁠יְלָדִים֙ אֲשֶׁ֨ר גָּדְל֣וּ אִתּ⁠וֹ֮ לֵ⁠אמֹר֒ כֹּֽה־תֹאמַ֣ר לָ⁠עָ֣ם הַ⁠זֶּ֡ה אֲשֶׁר֩ דִּבְּר֨וּ אֵלֶ֜י⁠ךָ לֵ⁠אמֹ֗ר אָבִ֨י⁠ךָ֙ הִכְבִּ֣יד אֶת־עֻלֵּ֔⁠נוּ וְ⁠אַתָּ֖ה הָקֵ֣ל מֵ⁠עָלֵ֑י⁠נוּ כֹּ֚ה תְּדַבֵּ֣ר אֲלֵי⁠הֶ֔ם קָֽטָנִּ֥⁠י עָבָ֖ה מִ⁠מָּתְנֵ֥י אָבִֽ⁠י׃","wa⁠yĕdabĕ̇r֣ẇ ʼélá֗y⁠w ha⁠yĕládiym֙ ʼàşě֨r gá̇dĕl֣ẇ ʼiţ̇⁠wò֮ lé⁠ʼmòr֒ kòֽ̇h-ţòʼma֣r lá⁠ʻá֣m ha⁠zė֡h ʼàşěr֩ di̇bĕ̇r֨ẇ ʼéle֜y⁠ká lé⁠ʼmò֗r ʼábi֨y⁠ká֙ hikĕbi֣̇yd ʼeţ-ʻulé̇֔⁠nẇ wĕ⁠ʼaţá֖̇h háqé֣l mé⁠ʻálé֑y⁠nẇ kò֚̇h ţĕ̇dabé֣̇r ʼàléy⁠he֔m qáֽtáni֥̇⁠y ʻábá֖h mi⁠má̇ţĕné֥y ʼábiֽ⁠y׃"],[12,11,"וְ⁠עַתָּ֗ה אָבִ⁠י֙ הֶעְמִ֤יס עֲלֵי⁠כֶם֙ עֹ֣ל כָּבֵ֔ד וַ⁠אֲנִ֖י אוֹסִ֣יף עַֽל־עֻלְּ⁠כֶ֑ם אָבִ֗⁠י יִסַּ֤ר אֶתְ⁠כֶם֙ בַּ⁠שּׁוֹטִ֔ים וַ⁠אֲנִ֕י אֲיַסֵּ֥ר אֶתְ⁠כֶ֖ם בָּ⁠עַקְרַבִּֽים׃","wĕ⁠ʻaţá̇֗h ʼábi⁠y֙ heʻĕmi֤ys ʻàléy⁠kem֙ ʻò֣l ká̇bé֔d wa⁠ʼàni֖y ʼwòsi֣yp ʻaֽl-ʻulĕ̇⁠ke֑m ʼábi֗⁠y yisȧ֤r ʼeţĕ⁠kem֙ bȧ⁠ş̇̌wòti֔ym wa⁠ʼàni֕y ʼàyasé֥̇r ʼeţĕ⁠ke֖m bá̇⁠ʻaqĕrabiֽ̇ym׃"],[12,12,"ו⁠יבו יָרָבְעָ֧ם וְ⁠כָל־הָ⁠עָ֛ם אֶל־רְחַבְעָ֖ם בַּ⁠יּ֣וֹם הַ⁠שְּׁלִישִׁ֑י כַּ⁠אֲשֶׁ֨ר דִּבֶּ֤ר הַ⁠מֶּ֨לֶךְ֙ לֵ⁠אמֹ֔ר שׁ֥וּבוּ אֵלַ֖⁠י בַּ⁠יּ֥וֹם הַ⁠שְּׁלִישִֽׁי׃","w⁠ybw yárábĕʻá֧m wĕ⁠kál-há⁠ʻá֛m ʼel-rĕẖabĕʻá֖m bȧ⁠ẏ֣wòm ha⁠şĕ̇̌liyşǐ֑y kȧ⁠ʼàşě֨r di̇bė֤r ha⁠mė֨lekĕ֙ lé⁠ʼmò֔r ş֥̌ẇbẇ ʼéla֖⁠y bȧ⁠ẏ֥wòm ha⁠şĕ̇̌liyşǐֽy׃"],[12,13,"וַ⁠יַּ֧עַן הַ⁠מֶּ֛לֶךְ אֶת־הָ⁠עָ֖ם קָשָׁ֑ה וַֽ⁠יַּעֲזֹ֛ב אֶת־עֲצַ֥ת הַ⁠זְּקֵנִ֖ים אֲשֶׁ֥ר יְעָצֻֽ⁠הוּ׃","wa⁠yȧ֧ʻan ha⁠mė֛lekĕ ʼeţ-há⁠ʻá֖m qáşá֑̌h waֽ⁠yȧʻàzò֛b ʼeţ-ʻàẕa֥ţ ha⁠zĕ̇qéni֖ym ʼàşě֥r yĕʻáẕuֽ⁠hẇ׃"],[12,14,"וַ⁠יְדַבֵּ֣ר אֲלֵי⁠הֶ֗ם כַּ⁠עֲצַ֤ת הַ⁠יְלָדִים֙ לֵ⁠אמֹ֔ר אָבִ⁠י֙ הִכְבִּ֣יד אֶֽת־עֻלְּ⁠כֶ֔ם וַ⁠אֲנִ֖י אֹסִ֣יף עַֽל־עֻלְּ⁠כֶ֑ם אָבִ֗⁠י יִסַּ֤ר אֶתְ⁠כֶם֙ בַּ⁠שּׁוֹטִ֔ים וַ⁠אֲנִ֕י אֲיַסֵּ֥ר אֶתְ⁠כֶ֖ם בָּ⁠עַקְרַבִּֽים׃","wa⁠yĕdabé֣̇r ʼàléy⁠he֗m kȧ⁠ʻàẕa֤ţ ha⁠yĕládiym֙ lé⁠ʼmò֔r ʼábi⁠y֙ hikĕbi֣̇yd ʼeֽţ-ʻulĕ̇⁠ke֔m wa⁠ʼàni֖y ʼòsi֣yp ʻaֽl-ʻulĕ̇⁠ke֑m ʼábi֗⁠y yisȧ֤r ʼeţĕ⁠kem֙ bȧ⁠ş̇̌wòti֔ym wa⁠ʼàni֕y ʼàyasé֥̇r ʼeţĕ⁠ke֖m bá̇⁠ʻaqĕrabiֽ̇ym׃"],[12,15,"וְ⁠לֹֽא־שָׁמַ֥ע הַ⁠מֶּ֖לֶךְ אֶל־הָ⁠עָ֑ם כִּֽי־הָיְתָ֤ה סִבָּה֙ מֵ⁠עִ֣ם יְהוָ֔ה לְמַ֜עַן הָקִ֣ים אֶת־דְּבָר֗⁠וֹ אֲשֶׁ֨ר דִּבֶּ֤ר יְהוָה֙ בְּ⁠יַד֙ אֲחִיָּ֣ה הַ⁠שִּׁילֹנִ֔י אֶל־יָרָבְעָ֖ם בֶּן־נְבָֽט׃","wĕ⁠lòֽʼ-şá̌ma֥ʻ ha⁠mė֖lekĕ ʼel-há⁠ʻá֑m kiֽ̇y-háyĕţá֤h sibá̇h֙ mé⁠ʻi֣m yĕhwá֔h lĕma֜ʻan háqi֣ym ʼeţ-dĕ̇bár֗⁠wò ʼàşě֨r di̇bė֤r yĕhwáh֙ bĕ̇⁠yad֙ ʼàẖiyá֣̇h ha⁠şi̇̌ylòni֔y ʼel-yárábĕʻá֖m bėn-nĕbáֽt׃"],[12,16,"וַ⁠יַּ֣רְא כָּל־יִשְׂרָאֵ֗ל כִּ֠י לֹֽא־שָׁמַ֣ע הַ⁠מֶּלֶךְ֮ אֲלֵי⁠הֶם֒ וַ⁠יָּשִׁ֣בוּ הָ⁠עָ֣ם אֶת־הַ⁠מֶּ֣לֶךְ דָּבָ֣ר ׀ לֵ⁠אמֹ֡ר מַה־לָּ⁠נוּ֩ חֵ֨לֶק בְּ⁠דָוִ֜ד וְ⁠לֹֽא־נַחֲלָ֣ה בְּ⁠בֶן־יִשַׁ֗י לְ⁠אֹהָלֶ֨י⁠ךָ֙ יִשְׂרָאֵ֔ל עַתָּ֕ה רְאֵ֥ה בֵיתְ⁠ךָ֖ דָּוִ֑ד וַ⁠יֵּ֥לֶךְ יִשְׂרָאֵ֖ל לְ⁠אֹהָלָֽי⁠ו׃","wa⁠yȧ֣rĕʼ ká̇l-yişĕ̂ráʼé֗l ki̇֠y lòֽʼ-şá̌ma֣ʻ ha⁠mėlekĕ֮ ʼàléy⁠hem֒ wa⁠yá̇şǐ֣bẇ há⁠ʻá֣m ʼeţ-ha⁠mė֣lekĕ dá̇bá֣r ׀ lé⁠ʼmò֡r mah-lá̇⁠nẇ֩ ẖé֨leq bĕ̇⁠dáwi֜d wĕ⁠lòֽʼ-naẖàlá֣h bĕ̇⁠ben-yişǎ֗y lĕ⁠ʼòhále֨y⁠ká֙ yişĕ̂ráʼé֔l ʻaţá̇֕h rĕʼé֥h béyţĕ⁠ká֖ dá̇wi֑d wa⁠yé֥̇lekĕ yişĕ̂ráʼé֖l lĕ⁠ʼòháláֽy⁠w׃"],[12,17,"וּ⁠בְנֵ֣י יִשְׂרָאֵ֔ל הַ⁠יֹּשְׁבִ֖ים בְּ⁠עָרֵ֣י יְהוּדָ֑ה וַ⁠יִּמְלֹ֥ךְ עֲלֵי⁠הֶ֖ם רְחַבְעָֽם׃פ","ẇ⁠bĕné֣y yişĕ̂ráʼé֔l ha⁠yò̇şĕ̌bi֖ym bĕ̇⁠ʻáré֣y yĕhẇdá֑h wa⁠yi̇mĕlò֥kĕ ʻàléy⁠he֖m rĕẖabĕʻáֽm׃p"],[12,18,"וַ⁠יִּשְׁלַ֞ח הַ⁠מֶּ֣לֶךְ רְחַבְעָ֗ם אֶת־אֲדֹרָם֙ אֲשֶׁ֣ר עַל־הַ⁠מַּ֔ס וַ⁠יִּרְגְּמ֨וּ כָל־יִשְׂרָאֵ֥ל בּ֛⁠וֹ אֶ֖בֶן וַ⁠יָּמֹ֑ת וְ⁠הַ⁠מֶּ֣לֶךְ רְחַבְעָ֗ם הִתְאַמֵּץ֙ לַ⁠עֲל֣וֹת בַּ⁠מֶּרְכָּבָ֔ה לָ⁠נ֖וּס יְרוּשָׁלִָֽם׃","wa⁠yi̇şĕ̌la֞ẖ ha⁠mė֣lekĕ rĕẖabĕʻá֗m ʼeţ-ʼàdòrám֙ ʼàşě֣r ʻal-ha⁠mȧ֔s wa⁠yi̇rĕgĕ̇m֨ẇ kál-yişĕ̂ráʼé֥l ḃ֛⁠wò ʼe֖ben wa⁠yá̇mò֑ţ wĕ⁠ha⁠mė֣lekĕ rĕẖabĕʻá֗m hiţĕʼamé̇ẕ֙ la⁠ʻàl֣wòţ bȧ⁠mėrĕká̇bá֔h lá⁠n֖ẇs yĕrẇşá̌liáֽm׃"],[12,19,"וַ⁠יִּפְשְׁע֤וּ יִשְׂרָאֵל֙ בְּ⁠בֵ֣ית דָּוִ֔ד עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃ס","wa⁠yi̇pĕşĕ̌ʻ֤ẇ yişĕ̂ráʼél֙ bĕ̇⁠bé֣yţ dá̇wi֔d ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃s"],[12,20,"וַ⁠יְהִ֞י כִּ⁠שְׁמֹ֤עַ כָּל־יִשְׂרָאֵל֙ כִּֽי־שָׁ֣ב יָרָבְעָ֔ם וַֽ⁠יִּשְׁלְח֗וּ וַ⁠יִּקְרְא֤וּ אֹת⁠וֹ֙ אֶל־הָ֣⁠עֵדָ֔ה וַ⁠יַּמְלִ֥יכוּ אֹת֖⁠וֹ עַל־כָּל־יִשְׂרָאֵ֑ל לֹ֤א הָיָה֙ אַחֲרֵ֣י בֵית־דָּוִ֔ד זוּלָתִ֥י שֵֽׁבֶט־יְהוּדָ֖ה לְ⁠בַדּֽ⁠וֹ׃","wa⁠yĕhi֞y ki̇⁠şĕ̌mò֤ʻa ká̇l-yişĕ̂ráʼél֙ kiֽ̇y-şá֣̌b yárábĕʻá֔m wֽa⁠yi̇şĕ̌lĕẖ֗ẇ wa⁠yi̇qĕrĕʼ֤ẇ ʼòţ⁠wò֙ ʼel-há֣⁠ʻédá֔h wa⁠yȧmĕli֥ykẇ ʼòţ֖⁠wò ʻal-ká̇l-yişĕ̂ráʼé֑l lò֤ʼ háyáh֙ ʼaẖàré֣y béyţ-dá̇wi֔d zẇláţi֥y şéֽ̌bet-yĕhẇdá֖h lĕ⁠baḋֽ⁠wò׃"],[12,21,"ו⁠יבאו רְחַבְעָם֮ יְרוּשָׁלִַם֒ וַ⁠יַּקְהֵל֩ אֶת־כָּל־בֵּ֨ית יְהוּדָ֜ה וְ⁠אֶת־שֵׁ֣בֶט בִּנְיָמִ֗ן מֵאָ֨ה וּ⁠שְׁמֹנִ֥ים אֶ֛לֶף בָּח֖וּר עֹשֵׂ֣ה מִלְחָמָ֑ה לְ⁠הִלָּחֵם֙ עִם־בֵּ֣ית יִשְׂרָאֵ֔ל לְ⁠הָשִׁיב֙ אֶת־הַ⁠מְּלוּכָ֔ה לִ⁠רְחַבְעָ֖ם בֶּן־שְׁלֹמֹֽה׃פ","w⁠ybʼw rĕẖabĕʻám֮ yĕrẇşá̌liam֒ wa⁠yȧqĕhél֩ ʼeţ-ká̇l-bé̇֨yţ yĕhẇdá֜h wĕ⁠ʼeţ-şé֣̌bet bi̇nĕyámi֗n méʼá֨h ẇ⁠şĕ̌mòni֥ym ʼe֛lep bá̇ẖ֖ẇr ʻòşé֣̂h milĕẖámá֑h lĕ⁠hilá̇ẖém֙ ʻim-bé֣̇yţ yişĕ̂ráʼé֔l lĕ⁠háşǐyb֙ ʼeţ-ha⁠mĕ̇lẇká֔h li⁠rĕẖabĕʻá֖m bėn-şĕ̌lòmòֽh׃p"],[12,22,"וַ⁠יְהִי֙ דְּבַ֣ר הָֽ⁠אֱלֹהִ֔ים אֶל־שְׁמַעְיָ֥ה אִישׁ־הָ⁠אֱלֹהִ֖ים לֵ⁠אמֹֽר׃","wa⁠yĕhiy֙ dĕ̇ba֣r hֽá⁠ʼèlòhi֔ym ʼel-şĕ̌maʻĕyá֥h ʼiyş̌-há⁠ʼèlòhi֖ym lé⁠ʼmòֽr׃"],[12,23,"אֱמֹ֗ר אֶל־רְחַבְעָ֤ם בֶּן־שְׁלֹמֹה֙ מֶ֣לֶךְ יְהוּדָ֔ה וְ⁠אֶל־כָּל־בֵּ֥ית יְהוּדָ֖ה וּ⁠בִנְיָמִ֑ין וְ⁠יֶ֥תֶר הָ⁠עָ֖ם לֵ⁠אמֹֽר׃","ʼèmò֗r ʼel-rĕẖabĕʻá֤m bėn-şĕ̌lòmòh֙ me֣lekĕ yĕhẇdá֔h wĕ⁠ʼel-ká̇l-bé֥̇yţ yĕhẇdá֖h ẇ⁠binĕyámi֑yn wĕ⁠ye֥ţer há⁠ʻá֖m lé⁠ʼmòֽr׃"],[12,24,"כֹּ֣ה אָמַ֣ר יְהוָ֡ה לֹֽא־תַעֲלוּ֩ וְ⁠לֹא־תִלָּ֨חֲמ֜וּ⁠ן עִם־אֲחֵי⁠כֶ֣ם בְּנֵֽי־יִשְׂרָאֵ֗ל שׁ֚וּבוּ אִ֣ישׁ לְ⁠בֵית֔⁠וֹ כִּ֧י מֵ⁠אִתִּ֛⁠י נִהְיָ֖ה הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַ⁠יִּשְׁמְעוּ֙ אֶת־דְּבַ֣ר יְהוָ֔ה וַ⁠יָּשֻׁ֥בוּ לָ⁠לֶ֖כֶת כִּ⁠דְבַ֥ר יְהוָֽה׃ס","kò֣̇h ʼáma֣r yĕhwá֡h lòֽʼ-ţaʻàlẇ֩ wĕ⁠lòʼ-ţilá̇֨ẖàm֜ẇ⁠n ʻim-ʼàẖéy⁠ke֣m bĕ̇néֽy-yişĕ̂ráʼé֗l ş֚̌ẇbẇ ʼi֣yş̌ lĕ⁠béyţ֔⁠wò ki֧̇y mé⁠ʼiţi֛̇⁠y nihĕyá֖h ha⁠dá̇bá֣r ha⁠zė֑h wa⁠yi̇şĕ̌mĕʻẇ֙ ʼeţ-dĕ̇ba֣r yĕhwá֔h wa⁠yá̇şǔ֥bẇ lá⁠le֖keţ ki̇⁠dĕba֥r yĕhwáֽh׃s"],[12,25,"וַ⁠יִּ֨בֶן יָרָבְעָ֧ם אֶת־שְׁכֶ֛ם בְּ⁠הַ֥ר אֶפְרַ֖יִם וַ⁠יֵּ֣שֶׁב בָּ֑⁠הּ וַ⁠יֵּצֵ֣א מִ⁠שָּׁ֔ם וַ⁠יִּ֖בֶן אֶת־פְּנוּאֵֽל׃","wa⁠yi̇֨ben yárábĕʻá֧m ʼeţ-şĕ̌ke֛m bĕ̇⁠ha֥r ʼepĕra֖yim wa⁠yé֣̇şěb bá֑̇⁠ḣ wa⁠yé̇ẕé֣ʼ mi⁠şá̇̌֔m wa⁠yi֖̇ben ʼeţ-pĕ̇nẇʼéֽl׃"],[12,26,"וַ⁠יֹּ֥אמֶר יָרָבְעָ֖ם בְּ⁠לִבּ֑⁠וֹ עַתָּ֛ה תָּשׁ֥וּב הַ⁠מַּמְלָכָ֖ה לְ⁠בֵ֥ית דָּוִֽד׃","wa⁠yò֥̇ʼmer yárábĕʻá֖m bĕ̇⁠liḃ֑⁠wò ʻaţá֛̇h ţá̇ş֥̌ẇb ha⁠mȧmĕláká֖h lĕ⁠bé֥yţ dá̇wiֽd׃"],[12,27,"אִֽם־יַעֲלֶ֣ה ׀ הָ⁠עָ֣ם הַ⁠זֶּ֗ה לַ⁠עֲשׂ֨וֹת זְבָחִ֤ים בְּ⁠בֵית־יְהוָה֙ בִּ⁠יר֣וּשָׁלִַ֔ם וְ֠⁠שָׁב לֵ֣ב הָ⁠עָ֤ם הַ⁠זֶּה֙ אֶל־אֲדֹ֣נֵי⁠הֶ֔ם אֶל־רְחַבְעָ֖ם מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠הֲרָגֻ֕⁠נִי וְ⁠שָׁ֖בוּ אֶל־רְחַבְעָ֥ם מֶֽלֶךְ־יְהוּדָֽה׃","ʼiֽm-yaʻàle֣h ׀ há⁠ʻá֣m ha⁠zė֗h la⁠ʻàş̂֨wòţ zĕbáẖi֤ym bĕ̇⁠béyţ-yĕhwáh֙ bi̇⁠yr֣ẇşá̌lia֔m wĕ֠⁠şá̌b lé֣b há⁠ʻá֤m ha⁠zėh֙ ʼel-ʼàdò֣néy⁠he֔m ʼel-rĕẖabĕʻá֖m me֣lekĕ yĕhẇdá֑h wa⁠hàrágu֕⁠niy wĕ⁠şá֖̌bẇ ʼel-rĕẖabĕʻá֥m meֽlekĕ-yĕhẇdáֽh׃"],[12,28,"וַ⁠יִּוָּעַ֣ץ הַ⁠מֶּ֔לֶךְ וַ⁠יַּ֕עַשׂ שְׁנֵ֖י עֶגְלֵ֣י זָהָ֑ב וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם רַב־לָ⁠כֶם֙ מֵ⁠עֲל֣וֹת יְרוּשָׁלִַ֔ם הִנֵּ֤ה אֱלֹהֶ֨י⁠ךָ֙ יִשְׂרָאֵ֔ל אֲשֶׁ֥ר הֶעֱל֖וּ⁠ךָ מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yi̇wá̇ʻa֣ẕ ha⁠mė֔lekĕ wa⁠yȧ֕ʻaş̂ şĕ̌né֖y ʻegĕlé֣y záhá֑b wa⁠yò֣̇ʼmer ʼàlé⁠he֗m rab-lá⁠kem֙ mé⁠ʻàl֣wòţ yĕrẇşá̌lia֔m hiné֤̇h ʼèlòhe֨y⁠ká֙ yişĕ̂ráʼé֔l ʼàşě֥r heʻèl֖ẇ⁠ká mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[12,29,"וַ⁠יָּ֥שֶׂם אֶת־הָ⁠אֶחָ֖ד בְּ⁠בֵֽית־אֵ֑ל וְ⁠אֶת־הָ⁠אֶחָ֖ד נָתַ֥ן בְּ⁠דָֽן׃","wa⁠yá֥̇şêm ʼeţ-há⁠ʼeẖá֖d bĕ̇⁠béֽyţ-ʼé֑l wĕ⁠ʼeţ-há⁠ʼeẖá֖d náţa֥n bĕ̇⁠dáֽn׃"],[12,30,"וַ⁠יְהִ֛י הַ⁠דָּבָ֥ר הַ⁠זֶּ֖ה לְ⁠חַטָּ֑את וַ⁠יֵּלְכ֥וּ הָ⁠עָ֛ם לִ⁠פְנֵ֥י הָ⁠אֶחָ֖ד עַד־דָּֽן׃","wa⁠yĕhi֛y ha⁠dá̇bá֥r ha⁠zė֖h lĕ⁠ẖatá֑̇ʼţ wa⁠yé̇lĕk֥ẇ há⁠ʻá֛m li⁠pĕné֥y há⁠ʼeẖá֖d ʻad-dáֽ̇n׃"],[12,31,"וַ⁠יַּ֖עַשׂ אֶת־בֵּ֣ית בָּמ֑וֹת וַ⁠יַּ֤עַשׂ כֹּֽהֲנִים֙ מִ⁠קְצ֣וֹת הָ⁠עָ֔ם אֲשֶׁ֥ר לֹֽא־הָי֖וּ מִ⁠בְּנֵ֥י לֵוִֽי׃","wa⁠yȧ֖ʻaş̂ ʼeţ-bé֣̇yţ bá̇m֑wòţ wa⁠yȧ֤ʻaş̂ kòֽ̇hàniym֙ mi⁠qĕẕ֣wòţ há⁠ʻá֔m ʼàşě֥r lòֽʼ-háy֖ẇ mi⁠bĕ̇né֥y léwiֽy׃"],[12,32,"וַ⁠יַּ֣עַשׂ יָרָבְעָ֣ם ׀ חָ֡ג בַּ⁠חֹ֣דֶשׁ הַ⁠שְּׁמִינִ֣י בַּ⁠חֲמִשָּֽׁה־עָשָׂר֩ י֨וֹם ׀ לַ⁠חֹ֜דֶשׁ כֶּ⁠חָ֣ג ׀ אֲשֶׁ֣ר בִּ⁠יהוּדָ֗ה וַ⁠יַּ֨עַל֙ עַל־הַ⁠מִּזְבֵּ֔חַ כֵּ֤ן עָשָׂה֙ בְּ⁠בֵֽית־אֵ֔ל לְ⁠זַבֵּ֖חַ לָ⁠עֲגָלִ֣ים אֲשֶׁר־עָשָׂ֑ה וְ⁠הֶעֱמִיד֙ בְּ⁠בֵ֣ית אֵ֔ל אֶת־כֹּהֲנֵ֥י הַ⁠בָּמ֖וֹת אֲשֶׁ֥ר עָשָֽׂה׃","wa⁠yȧ֣ʻaş̂ yárábĕʻá֣m ׀ ẖá֡g bȧ⁠ẖò֣deş̌ ha⁠şĕ̇̌miyni֣y bȧ⁠ẖàmişáֽ̇̌h-ʻáşá̂r֩ y֨wòm ׀ la⁠ẖò֜deş̌ kė⁠ẖá֣g ׀ ʼàşě֣r bi̇⁠yhẇdá֗h wa⁠yȧ֨ʻal֙ ʻal-ha⁠mi̇zĕbé̇֔ẖa ké֤̇n ʻáşá̂h֙ bĕ̇⁠béֽyţ-ʼé֔l lĕ⁠zabé֖̇ẖa lá⁠ʻàgáli֣ym ʼàşěr-ʻáşá֑̂h wĕ⁠heʻèmiyd֙ bĕ̇⁠bé֣yţ ʼé֔l ʼeţ-kò̇hàné֥y ha⁠bá̇m֖wòţ ʼàşě֥r ʻáşáֽ̂h׃"],[12,33,"וַ⁠יַּ֜עַל עַֽל־הַ⁠מִּזְבֵּ֣חַ ׀ אֲשֶׁר־עָשָׂ֣ה בְּ⁠בֵֽית־אֵ֗ל בַּ⁠חֲמִשָּׁ֨ה עָשָׂ֥ר יוֹם֙ בַּ⁠חֹ֣דֶשׁ הַ⁠שְּׁמִינִ֔י בַּ⁠חֹ֖דֶשׁ אֲשֶׁר־בָּדָ֣א מ⁠ל⁠בד וַ⁠יַּ֤עַשׂ חָג֙ לִ⁠בְנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יַּ֥עַל עַל־הַ⁠מִּזְבֵּ֖חַ לְ⁠הַקְטִֽיר׃פ","wa⁠yȧ֜ʻal ʻaֽl-ha⁠mi̇zĕbé֣̇ẖa ׀ ʼàşěr-ʻáşá֣̂h bĕ̇⁠béֽyţ-ʼé֗l bȧ⁠ẖàmişá̇̌֨h ʻáşá֥̂r ywòm֙ bȧ⁠ẖò֣deş̌ ha⁠şĕ̇̌miyni֔y bȧ⁠ẖò֖deş̌ ʼàşěr-bá̇dá֣ʼ m⁠l⁠bd wa⁠yȧ֤ʻaş̂ ẖág֙ li⁠bĕné֣y yişĕ̂ráʼé֔l wa⁠yȧ֥ʻal ʻal-ha⁠mi̇zĕbé֖̇ẖa lĕ⁠haqĕtiֽyr׃p"],[13,1,"וְ⁠הִנֵּ֣ה ׀ אִ֣ישׁ אֱלֹהִ֗ים בָּ֧א מִ⁠יהוּדָ֛ה בִּ⁠דְבַ֥ר יְהוָ֖ה אֶל־בֵּֽית־אֵ֑ל וְ⁠יָרָבְעָ֛ם עֹמֵ֥ד עַל־הַ⁠מִּזְבֵּ֖חַ לְ⁠הַקְטִֽיר׃","wĕ⁠hiné֣̇h ׀ ʼi֣yş̌ ʼèlòhi֗ym bá֧̇ʼ mi⁠yhẇdá֛h bi̇⁠dĕba֥r yĕhwá֖h ʼel-béֽ̇yţ-ʼé֑l wĕ⁠yárábĕʻá֛m ʻòmé֥d ʻal-ha⁠mi̇zĕbé֖̇ẖa lĕ⁠haqĕtiֽyr׃"],[13,2,"וַ⁠יִּקְרָ֤א עַל־הַ⁠מִּזְבֵּ֨חַ֙ בִּ⁠דְבַ֣ר יְהוָ֔ה וַ⁠יֹּ֨אמֶר֙ מִזְבֵּ֣חַ מִזְבֵּ֔חַ כֹּ֖ה אָמַ֣ר יְהוָ֑ה הִנֵּֽה־בֵ֞ן נוֹלָ֤ד לְ⁠בֵית־דָּוִד֙ יֹאשִׁיָּ֣הוּ שְׁמ֔⁠וֹ וְ⁠זָבַ֣ח עָלֶ֗י⁠ךָ אֶת־כֹּהֲנֵ֤י הַ⁠בָּמוֹת֙ הַ⁠מַּקְטִרִ֣ים עָלֶ֔י⁠ךָ וְ⁠עַצְמ֥וֹת אָדָ֖ם יִשְׂרְפ֥וּ עָלֶֽי⁠ךָ׃","wa⁠yi̇qĕrá֤ʼ ʻal-ha⁠mi̇zĕbé̇֨ẖa֙ bi̇⁠dĕba֣r yĕhwá֔h wa⁠yò̇֨ʼmer֙ mizĕbé֣̇ẖa mizĕbé̇֔ẖa kò֖̇h ʼáma֣r yĕhwá֑h hinéֽ̇h-bé֞n nwòlá֤d lĕ⁠béyţ-dá̇wid֙ yòʼşǐyá֣̇hẇ şĕ̌m֔⁠wò wĕ⁠zába֣ẖ ʻále֗y⁠ká ʼeţ-kò̇hàné֤y ha⁠bá̇mwòţ֙ ha⁠mȧqĕtiri֣ym ʻále֔y⁠ká wĕ⁠ʻaẕĕm֥wòţ ʼádá֖m yişĕ̂rĕp֥ẇ ʻáleֽy⁠ká׃"],[13,3,"וְ⁠נָתַן֩ בַּ⁠יּ֨וֹם הַ⁠ה֤וּא מוֹפֵת֙ לֵ⁠אמֹ֔ר זֶ֣ה הַ⁠מּוֹפֵ֔ת אֲשֶׁ֖ר דִּבֶּ֣ר יְהוָ֑ה הִנֵּ֤ה הַ⁠מִּזְבֵּ֨חַ֙ נִקְרָ֔ע וְ⁠נִשְׁפַּ֖ךְ הַ⁠דֶּ֥שֶׁן אֲשֶׁר־עָלָֽי⁠ו׃","wĕ⁠náţan֩ bȧ⁠ẏ֨wòm ha⁠h֤ẇʼ mwòpéţ֙ lé⁠ʼmò֔r ze֣h ha⁠ṁwòpé֔ţ ʼàşě֖r di̇bė֣r yĕhwá֑h hiné֤̇h ha⁠mi̇zĕbé̇֨ẖa֙ niqĕrá֔ʻ wĕ⁠nişĕ̌pȧ֖kĕ ha⁠dė֥şěn ʼàşěr-ʻáláֽy⁠w׃"],[13,4,"וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ הַ⁠מֶּ֜לֶךְ אֶת־דְּבַ֣ר אִישׁ־הָ⁠אֱלֹהִ֗ים אֲשֶׁ֨ר קָרָ֤א עַל־הַ⁠מִּזְבֵּ֨חַ֙ בְּ⁠בֵֽית־אֵ֔ל וַ⁠יִּשְׁלַ֨ח יָרָבְעָ֧ם אֶת־יָד֛⁠וֹ מֵ⁠עַ֥ל הַ⁠מִּזְבֵּ֖חַ לֵ⁠אמֹ֣ר ׀ תִּפְשֻׂ֑⁠הוּ וַ⁠תִּיבַ֤שׁ יָד⁠וֹ֙ אֲשֶׁ֣ר שָׁלַ֣ח עָלָ֔י⁠ו וְ⁠לֹ֥א יָכֹ֖ל לַ⁠הֲשִׁיבָ֥⁠הּ אֵלָֽי⁠ו׃","wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa ha⁠mė֜lekĕ ʼeţ-dĕ̇ba֣r ʼiyş̌-há⁠ʼèlòhi֗ym ʼàşě֨r qárá֤ʼ ʻal-ha⁠mi̇zĕbé̇֨ẖa֙ bĕ̇⁠béֽyţ-ʼé֔l wa⁠yi̇şĕ̌la֨ẖ yárábĕʻá֧m ʼeţ-yád֛⁠wò mé⁠ʻa֥l ha⁠mi̇zĕbé֖̇ẖa lé⁠ʼmò֣r ׀ ţi̇pĕşû֑⁠hẇ wa⁠ţi̇yba֤ş̌ yád⁠wò֙ ʼàşě֣r şá̌la֣ẖ ʻálá֔y⁠w wĕ⁠lò֥ʼ yákò֖l la⁠hàşǐybá֥⁠ḣ ʼéláֽy⁠w׃"],[13,5,"וְ⁠הַ⁠מִּזְבֵּ֣חַ נִקְרָ֔ע וַ⁠יִּשָּׁפֵ֥ךְ הַ⁠דֶּ֖שֶׁן מִן־הַ⁠מִּזְבֵּ֑חַ כַּ⁠מּוֹפֵ֗ת אֲשֶׁ֥ר נָתַ֛ן אִ֥ישׁ הָ⁠אֱלֹהִ֖ים בִּ⁠דְבַ֥ר יְהוָֽה׃","wĕ⁠ha⁠mi̇zĕbé֣̇ẖa niqĕrá֔ʻ wa⁠yi̇şá̇̌pé֥kĕ ha⁠dė֖şěn min-ha⁠mi̇zĕbé֑̇ẖa kȧ⁠ṁwòpé֗ţ ʼàşě֥r náţa֛n ʼi֥yş̌ há⁠ʼèlòhi֖ym bi̇⁠dĕba֥r yĕhwáֽh׃"],[13,6,"וַ⁠יַּ֨עַן הַ⁠מֶּ֜לֶךְ וַ⁠יֹּ֣אמֶר ׀ אֶל־אִ֣ישׁ הָ⁠אֱלֹהִ֗ים חַל־נָ֞א אֶת־פְּנֵ֨י יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ וְ⁠הִתְפַּלֵּ֣ל בַּעֲדִ֔⁠י וְ⁠תָשֹׁ֥ב יָדִ֖⁠י אֵלָ֑⁠י וַ⁠יְחַ֤ל אִישׁ־הָֽ⁠אֱלֹהִים֙ אֶת־פְּנֵ֣י יְהוָ֔ה וַ⁠תָּ֤שָׁב יַד־הַ⁠מֶּ֨לֶךְ֙ אֵלָ֔י⁠ו וַ⁠תְּהִ֖י כְּ⁠בָ⁠רִֽאשֹׁנָֽה׃","wa⁠yȧ֨ʻan ha⁠mė֜lekĕ wa⁠yò֣̇ʼmer ׀ ʼel-ʼi֣yş̌ há⁠ʼèlòhi֗ym ẖal-ná֞ʼ ʼeţ-pĕ̇né֨y yĕhwá֤h ʼèlòhe֨y⁠ká֙ wĕ⁠hiţĕpȧlé֣̇l bȧʻàdi֔⁠y wĕ⁠ţáşò֥̌b yádi֖⁠y ʼélá֑⁠y wa⁠yĕẖa֤l ʼiyş̌-háֽ⁠ʼèlòhiym֙ ʼeţ-pĕ̇né֣y yĕhwá֔h wa⁠ţá֤̇şá̌b yad-ha⁠mė֨lekĕ֙ ʼélá֔y⁠w wa⁠ţĕ̇hi֖y kĕ̇⁠bá⁠riֽʼşò̌náֽh׃"],[13,7,"וַ⁠יְדַבֵּ֤ר הַ⁠מֶּ֨לֶךְ֙ אֶל־אִ֣ישׁ הָ⁠אֱלֹהִ֔ים בֹּאָ⁠ה־אִתִּ֥⁠י הַ⁠בַּ֖יְתָ⁠ה וּֽ⁠סְעָ֑דָ⁠ה וְ⁠אֶתְּנָ֥ה לְ⁠ךָ֖ מַתָּֽת׃","wa⁠yĕdabé֤̇r ha⁠mė֨lekĕ֙ ʼel-ʼi֣yş̌ há⁠ʼèlòhi֔ym bò̇ʼá⁠h-ʼiţi֥̇⁠y ha⁠bȧ֖yĕţá⁠h ẇֽ⁠sĕʻá֑dá⁠h wĕ⁠ʼeţĕ̇ná֥h lĕ⁠ká֖ maţáֽ̇ţ׃"],[13,8,"וַ⁠יֹּ֤אמֶר אִישׁ־הָֽ⁠אֱלֹהִים֙ אֶל־הַ⁠מֶּ֔לֶךְ אִם־תִּתֶּן־לִ⁠י֙ אֶת־חֲצִ֣י בֵיתֶ֔⁠ךָ לֹ֥א אָבֹ֖א עִמָּ֑⁠ךְ וְ⁠לֹֽא־אֹ֤כַל לֶ֨חֶם֙ וְ⁠לֹ֣א אֶשְׁתֶּה־מַּ֔יִם בַּ⁠מָּק֖וֹם הַ⁠זֶּֽה׃","wa⁠yò֤̇ʼmer ʼiyş̌-háֽ⁠ʼèlòhiym֙ ʼel-ha⁠mė֔lekĕ ʼim-ţi̇ţėn-li⁠y֙ ʼeţ-ẖàẕi֣y béyţe֔⁠ká lò֥ʼ ʼábò֖ʼ ʻimá֑̇⁠kĕ wĕ⁠lòֽʼ-ʼò֤kal le֨ẖem֙ wĕ⁠lò֣ʼ ʼeşĕ̌ţėh-mȧ֔yim bȧ⁠má̇q֖wòm ha⁠zėֽh׃"],[13,9,"כִּֽי־כֵ֣ן ׀ צִוָּ֣ה אֹתִ֗⁠י בִּ⁠דְבַ֤ר יְהוָה֙ לֵ⁠אמֹ֔ר לֹא־תֹ֥אכַל לֶ֖חֶם וְ⁠לֹ֣א תִשְׁתֶּה־מָּ֑יִם וְ⁠לֹ֣א תָשׁ֔וּב בַּ⁠דֶּ֖רֶךְ אֲשֶׁ֥ר הָלָֽכְתָּ׃","kiֽ̇y-ké֣n ׀ ẕiwá֣̇h ʼòţi֗⁠y bi̇⁠dĕba֤r yĕhwáh֙ lé⁠ʼmò֔r lòʼ-ţò֥ʼkal le֖ẖem wĕ⁠lò֣ʼ ţişĕ̌ţėh-má֑̇yim wĕ⁠lò֣ʼ ţáş̌֔ẇb bȧ⁠dė֖rekĕ ʼàşě֥r háláֽkĕţá̇׃"],[13,10,"וַ⁠יֵּ֖לֶךְ בְּ⁠דֶ֣רֶךְ אַחֵ֑ר וְ⁠לֹֽא־שָׁ֣ב בַּ⁠דֶּ֔רֶךְ אֲשֶׁ֛ר בָּ֥א בָ֖⁠הּ אֶל־בֵּֽית־אֵֽל׃פ","wa⁠yé֖̇lekĕ bĕ̇⁠de֣rekĕ ʼaẖé֑r wĕ⁠lòֽʼ-şá֣̌b bȧ⁠dė֔rekĕ ʼàşě֛r bá֥̇ʼ bá֖⁠ḣ ʼel-béֽ̇yţ-ʼéֽl׃p"],[13,11,"וְ⁠נָבִ֤יא אֶחָד֙ זָקֵ֔ן יֹשֵׁ֖ב בְּ⁠בֵֽית־אֵ֑ל וַ⁠יָּב֣וֹא בְנ֡⁠וֹ וַ⁠יְסַפֶּר־ל֣⁠וֹ אֶת־כָּל־הַ⁠מַּעֲשֶׂ֣ה אֲשֶׁר־עָשָׂה֩ אִישׁ־הָ⁠אֱלֹהִ֨ים ׀ הַ⁠יּ֜וֹם בְּ⁠בֵֽית־אֵ֗ל אֶת־הַ⁠דְּבָרִים֙ אֲשֶׁ֣ר דִּבֶּ֣ר אֶל־הַ⁠מֶּ֔לֶךְ וַֽ⁠יְסַפְּר֖וּ⁠ם לַ⁠אֲבִי⁠הֶֽם׃","wĕ⁠nábi֤yʼ ʼeẖád֙ záqé֔n yòşé֖̌b bĕ̇⁠béֽyţ-ʼé֑l wa⁠yá̇b֣wòʼ bĕn֡⁠wò wa⁠yĕsapėr-l֣⁠wò ʼeţ-ká̇l-ha⁠mȧʻàşê֣h ʼàşěr-ʻáşá̂h֩ ʼiyş̌-há⁠ʼèlòhi֨ym ׀ ha⁠ẏ֜wòm bĕ̇⁠béֽyţ-ʼé֗l ʼeţ-ha⁠dĕ̇báriym֙ ʼàşě֣r di̇bė֣r ʼel-ha⁠mė֔lekĕ waֽ⁠yĕsapĕ̇r֖ẇ⁠m la⁠ʼàbiy⁠heֽm׃"],[13,12,"וַ⁠יְדַבֵּ֤ר אֲלֵ⁠הֶם֙ אֲבִי⁠הֶ֔ם אֵֽי־זֶ֥ה הַ⁠דֶּ֖רֶךְ הָלָ֑ךְ וַ⁠יִּרְא֣וּ בָנָ֗י⁠ו אֶת־הַ⁠דֶּ֨רֶךְ֙ אֲשֶׁ֤ר הָלַךְ֙ אִ֣ישׁ הָ⁠אֱלֹהִ֔ים אֲשֶׁר־בָּ֖א מִ⁠יהוּדָֽה׃","wa⁠yĕdabé֤̇r ʼàlé⁠hem֙ ʼàbiy⁠he֔m ʼéֽy-ze֥h ha⁠dė֖rekĕ hálá֑kĕ wa⁠yi̇rĕʼ֣ẇ báná֗y⁠w ʼeţ-ha⁠dė֨rekĕ֙ ʼàşě֤r hálakĕ֙ ʼi֣yş̌ há⁠ʼèlòhi֔ym ʼàşěr-bá֖̇ʼ mi⁠yhẇdáֽh׃"],[13,13,"וַ⁠יֹּ֨אמֶר֙ אֶל־בָּנָ֔י⁠ו חִבְשׁוּ־לִ֖⁠י הַ⁠חֲמ֑וֹר וַ⁠יַּחְבְּשׁוּ־ל֣⁠וֹ הַ⁠חֲמ֔וֹר וַ⁠יִּרְכַּ֖ב עָלָֽי⁠ו׃","wa⁠yò̇֨ʼmer֙ ʼel-bá̇ná֔y⁠w ẖibĕş̌ẇ-li֖⁠y ha⁠ẖàm֑wòr wa⁠yȧẖĕbĕ̇ş̌ẇ-l֣⁠wò ha⁠ẖàm֔wòr wa⁠yi̇rĕkȧ֖b ʻáláֽy⁠w׃"],[13,14,"וַ⁠יֵּ֗לֶךְ אַֽחֲרֵי֙ אִ֣ישׁ הָ⁠אֱלֹהִ֔ים וַ⁠יִּ֨מְצָאֵ֔⁠הוּ יֹשֵׁ֖ב תַּ֣חַת הָ⁠אֵלָ֑ה וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו הַ⁠אַתָּ֧ה אִישׁ־הָ⁠אֱלֹהִ֛ים אֲשֶׁר־בָּ֥אתָ מִֽ⁠יהוּדָ֖ה וַ⁠יֹּ֥אמֶר אָֽנִי׃","wa⁠yé̇֗lekĕ ʼaֽẖàréy֙ ʼi֣yş̌ há⁠ʼèlòhi֔ym wa⁠yi̇֨mĕẕáʼé֔⁠hẇ yòşé֖̌b ţȧ֣ẖaţ há⁠ʼélá֑h wa⁠yò֣̇ʼmer ʼélá֗y⁠w ha⁠ʼaţá֧̇h ʼiyş̌-há⁠ʼèlòhi֛ym ʼàşěr-bá֥̇ʼţá miֽ⁠yhẇdá֖h wa⁠yò֥̇ʼmer ʼáֽniy׃"],[13,15,"וַ⁠יֹּ֣אמֶר אֵלָ֔י⁠ו לֵ֥ךְ אִתִּ֖⁠י הַ⁠בָּ֑יְתָ⁠ה וֶ⁠אֱכֹ֖ל לָֽחֶם׃","wa⁠yò֣̇ʼmer ʼélá֔y⁠w lé֥kĕ ʼiţi֖̇⁠y ha⁠bá֑̇yĕţá⁠h we⁠ʼèkò֖l láֽẖem׃"],[13,16,"וַ⁠יֹּ֗אמֶר לֹ֥א אוּכַ֛ל לָ⁠שׁ֥וּב אִתָּ֖⁠ךְ וְ⁠לָ⁠ב֣וֹא אִתָּ֑⁠ךְ וְ⁠לֹֽא־אֹ֣כַל לֶ֗חֶם וְ⁠לֹֽא־אֶשְׁתֶּ֤ה אִתְּ⁠ךָ֙ מַ֔יִם בַּ⁠מָּק֖וֹם הַ⁠זֶּֽה׃","wa⁠yò̇֗ʼmer lò֥ʼ ʼẇka֛l lá⁠ş֥̌ẇb ʼiţá֖̇⁠kĕ wĕ⁠lá⁠b֣wòʼ ʼiţá֑̇⁠kĕ wĕ⁠lòֽʼ-ʼò֣kal le֗ẖem wĕ⁠lòֽʼ-ʼeşĕ̌ţė֤h ʼiţĕ̇⁠ká֙ ma֔yim bȧ⁠má̇q֖wòm ha⁠zėֽh׃"],[13,17,"כִּֽי־דָבָ֤ר אֵלַ⁠י֙ בִּ⁠דְבַ֣ר יְהוָ֔ה לֹֽא־תֹאכַ֣ל לֶ֔חֶם וְ⁠לֹֽא־תִשְׁתֶּ֥ה שָׁ֖ם מָ֑יִם לֹא־תָשׁ֣וּב לָ⁠לֶ֔כֶת בַּ⁠דֶּ֖רֶךְ אֲשֶׁר־הָלַ֥כְתָּ בָּֽ⁠הּ׃","kiֽ̇y-dábá֤r ʼéla⁠y֙ bi̇⁠dĕba֣r yĕhwá֔h lòֽʼ-ţòʼka֣l le֔ẖem wĕ⁠lòֽʼ-ţişĕ̌ţė֥h şá֖̌m má֑yim lòʼ-ţáş֣̌ẇb lá⁠le֔keţ bȧ⁠dė֖rekĕ ʼàşěr-hála֥kĕţá̇ báֽ̇⁠ḣ׃"],[13,18,"וַ⁠יֹּ֣אמֶר ל֗⁠וֹ גַּם־אֲנִ֣י נָבִיא֮ כָּמוֹ⁠ךָ֒ וּ⁠מַלְאָ֡ךְ דִּבֶּ֣ר אֵלַ⁠י֩ בִּ⁠דְבַ֨ר יְהוָ֜ה לֵ⁠אמֹ֗ר הֲשִׁבֵ֤⁠הוּ אִתְּ⁠ךָ֙ אֶל־בֵּיתֶ֔⁠ךָ וְ⁠יֹ֥אכַל לֶ֖חֶם וְ⁠יֵ֣שְׁתְּ מָ֑יִם כִּחֵ֖שׁ לֽ⁠וֹ׃","wa⁠yò֣̇ʼmer l֗⁠wò gȧm-ʼàni֣y nábiyʼ֮ ká̇mwò⁠ká֒ ẇ⁠malĕʼá֡kĕ di̇bė֣r ʼéla⁠y֩ bi̇⁠dĕba֨r yĕhwá֜h lé⁠ʼmò֗r hàşǐbé֤⁠hẇ ʼiţĕ̇⁠ká֙ ʼel-bé̇yţe֔⁠ká wĕ⁠yò֥ʼkal le֖ẖem wĕ⁠yé֣şĕ̌ţĕ̇ má֑yim ki̇ẖé֖ş̌ lֽ⁠wò׃"],[13,19,"וַ⁠יָּ֣שָׁב אִתּ֗⁠וֹ וַ⁠יֹּ֥אכַל לֶ֛חֶם בְּ⁠בֵית֖⁠וֹ וַ⁠יֵּ֥שְׁתְּ מָֽיִם׃","wa⁠yá֣̇şá̌b ʼiţ̇֗⁠wò wa⁠yò֥̇ʼkal le֛ẖem bĕ̇⁠béyţ֖⁠wò wa⁠yé֥̇şĕ̌ţĕ̇ máֽyim׃"],[13,20,"וַ⁠יְהִ֕י הֵ֥ם יֹשְׁבִ֖ים אֶל־הַ⁠שֻּׁלְחָ֑ן פ וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־הַ⁠נָּבִ֖יא אֲשֶׁ֥ר הֱשִׁיבֽ⁠וֹ׃","wa⁠yĕhi֕y hé֥m yòşĕ̌bi֖ym ʼel-ha⁠şu̇̌lĕẖá֑n p waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-ha⁠ná̇bi֖yʼ ʼàşě֥r hèşǐybֽ⁠wò׃"],[13,21,"וַ⁠יִּקְרָ֞א אֶל־אִ֣ישׁ הָ⁠אֱלֹהִ֗ים אֲשֶׁר־בָּ֤א מִֽ⁠יהוּדָה֙ לֵ⁠אמֹ֔ר כֹּ֖ה אָמַ֣ר יְהוָ֑ה יַ֗עַן כִּ֤י מָרִ֨יתָ֙ פִּ֣י יְהוָ֔ה וְ⁠לֹ֤א שָׁמַ֨רְתָּ֙ אֶת־הַ⁠מִּצְוָ֔ה אֲשֶׁ֥ר צִוְּ⁠ךָ֖ יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","wa⁠yi̇qĕrá֞ʼ ʼel-ʼi֣yş̌ há⁠ʼèlòhi֗ym ʼàşěr-bá֤̇ʼ miֽ⁠yhẇdáh֙ lé⁠ʼmò֔r kò֖̇h ʼáma֣r yĕhwá֑h ya֗ʻan ki֤̇y mári֨yţá֙ pi֣̇y yĕhwá֔h wĕ⁠lò֤ʼ şá̌ma֨rĕţá̇֙ ʼeţ-ha⁠mi̇ẕĕwá֔h ʼàşě֥r ẕiwĕ̇⁠ká֖ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[13,22,"וַ⁠תָּ֗שָׁב וַ⁠תֹּ֤אכַל לֶ֨חֶם֙ וַ⁠תֵּ֣שְׁתְּ מַ֔יִם בַּ⁠מָּקוֹם֙ אֲשֶׁ֣ר דִּבֶּ֣ר אֵלֶ֔י⁠ךָ אַל־תֹּ֥אכַל לֶ֖חֶם וְ⁠אַל־תֵּ֣שְׁתְּ מָ֑יִם לֹֽא־תָב֥וֹא נִבְלָתְ⁠ךָ֖ אֶל־קֶ֥בֶר אֲבֹתֶֽי⁠ךָ׃","wa⁠ţá̇֗şá̌b wa⁠ţò֤̇ʼkal le֨ẖem֙ wa⁠ţé֣̇şĕ̌ţĕ̇ ma֔yim bȧ⁠má̇qwòm֙ ʼàşě֣r di̇bė֣r ʼéle֔y⁠ká ʼal-ţò֥̇ʼkal le֖ẖem wĕ⁠ʼal-ţé֣̇şĕ̌ţĕ̇ má֑yim lòֽʼ-ţáb֥wòʼ nibĕláţĕ⁠ká֖ ʼel-qe֥ber ʼàbòţeֽy⁠ká׃"],[13,23,"וַ⁠יְהִ֗י אַחֲרֵ֛י אָכְל֥⁠וֹ לֶ֖חֶם וְ⁠אַחֲרֵ֣י שְׁתוֹת֑⁠וֹ וַ⁠יַּחֲבָשׁ־ל֣⁠וֹ הַ⁠חֲמ֔וֹר לַ⁠נָּבִ֖יא אֲשֶׁ֥ר הֱשִׁיבֽ⁠וֹ׃","wa⁠yĕhi֗y ʼaẖàré֛y ʼákĕl֥⁠wò le֖ẖem wĕ⁠ʼaẖàré֣y şĕ̌ţwòţ֑⁠wò wa⁠yȧẖàbáş̌-l֣⁠wò ha⁠ẖàm֔wòr la⁠ná̇bi֖yʼ ʼàşě֥r hèşǐybֽ⁠wò׃"],[13,24,"וַ⁠יֵּ֕לֶךְ וַ⁠יִּמְצָאֵ֧⁠הוּ אַרְיֵ֛ה בַּ⁠דֶּ֖רֶךְ וַ⁠יְמִיתֵ֑⁠הוּ וַ⁠תְּהִ֤י נִבְלָת⁠וֹ֙ מֻשְׁלֶ֣כֶת בַּ⁠דֶּ֔רֶךְ וְ⁠הַ⁠חֲמוֹר֙ עֹמֵ֣ד אֶצְלָ֔⁠הּ וְ⁠הָ֣⁠אַרְיֵ֔ה עֹמֵ֖ד אֵ֥צֶל הַ⁠נְּבֵלָֽה׃","wa⁠yé̇֕lekĕ wa⁠yi̇mĕẕáʼé֧⁠hẇ ʼarĕyé֛h bȧ⁠dė֖rekĕ wa⁠yĕmiyţé֑⁠hẇ wa⁠ţĕ̇hi֤y nibĕláţ⁠wò֙ muşĕ̌le֣keţ bȧ⁠dė֔rekĕ wĕ⁠ha⁠ẖàmwòr֙ ʻòmé֣d ʼeẕĕlá֔⁠ḣ wĕ⁠há֣⁠ʼarĕyé֔h ʻòmé֖d ʼé֥ẕel ha⁠nĕ̇béláֽh׃"],[13,25,"וְ⁠הִנֵּ֧ה אֲנָשִׁ֣ים עֹבְרִ֗ים וַ⁠יִּרְא֤וּ אֶת־הַ⁠נְּבֵלָה֙ מֻשְׁלֶ֣כֶת בַּ⁠דֶּ֔רֶךְ וְ⁠אֶת־הָ֣⁠אַרְיֵ֔ה עֹמֵ֖ד אֵ֣צֶל הַ⁠נְּבֵלָ֑ה וַ⁠יָּבֹ֨אוּ֙ וַ⁠יְדַבְּר֣וּ בָ⁠עִ֔יר אֲשֶׁ֛ר הַ⁠נָּבִ֥יא הַ⁠זָּקֵ֖ן יֹשֵׁ֥ב בָּֽ⁠הּ׃","wĕ⁠hiné֧̇h ʼànáşǐ֣ym ʻòbĕri֗ym wa⁠yi̇rĕʼ֤ẇ ʼeţ-ha⁠nĕ̇béláh֙ muşĕ̌le֣keţ bȧ⁠dė֔rekĕ wĕ⁠ʼeţ-há֣⁠ʼarĕyé֔h ʻòmé֖d ʼé֣ẕel ha⁠nĕ̇bélá֑h wa⁠yá̇bò֨ʼẇ֙ wa⁠yĕdabĕ̇r֣ẇ bá⁠ʻi֔yr ʼàşě֛r ha⁠ná̇bi֥yʼ ha⁠zá̇qé֖n yòşé֥̌b báֽ̇⁠ḣ׃"],[13,26,"וַ⁠יִּשְׁמַ֣ע הַ⁠נָּבִיא֮ אֲשֶׁ֣ר הֱשִׁיב֣⁠וֹ מִן־הַ⁠דֶּרֶךְ֒ וַ⁠יֹּ֨אמֶר֙ אִ֣ישׁ הָ⁠אֱלֹהִ֣ים ה֔וּא אֲשֶׁ֥ר מָרָ֖ה אֶת־פִּ֣י יְהוָ֑ה וַ⁠יִּתְּנֵ֨⁠הוּ יְהוָ֜ה לָ⁠אַרְיֵ֗ה וַֽ⁠יִּשְׁבְּרֵ֨⁠הוּ֙ וַ⁠יְמִתֵ֔⁠הוּ כִּ⁠דְבַ֥ר יְהוָ֖ה אֲשֶׁ֥ר דִּבֶּר־לֽ⁠וֹ׃","wa⁠yi̇şĕ̌ma֣ʻ ha⁠ná̇biyʼ֮ ʼàşě֣r hèşǐyb֣⁠wò min-ha⁠dėrekĕ֒ wa⁠yò̇֨ʼmer֙ ʼi֣yş̌ há⁠ʼèlòhi֣ym h֔ẇʼ ʼàşě֥r márá֖h ʼeţ-pi֣̇y yĕhwá֑h wa⁠yi̇ţĕ̇né֨⁠hẇ yĕhwá֜h lá⁠ʼarĕyé֗h waֽ⁠yi̇şĕ̌bĕ̇ré֨⁠hẇ֙ wa⁠yĕmiţé֔⁠hẇ ki̇⁠dĕba֥r yĕhwá֖h ʼàşě֥r di̇bėr-lֽ⁠wò׃"],[13,27,"וַ⁠יְדַבֵּ֤ר אֶל־בָּנָי⁠ו֙ לֵ⁠אמֹ֔ר חִבְשׁוּ־לִ֖⁠י אֶֽת־הַ⁠חֲמ֑וֹר וַֽ⁠יַּחֲבֹֽשׁוּ׃","wa⁠yĕdabé֤̇r ʼel-bá̇náy⁠w֙ lé⁠ʼmò֔r ẖibĕş̌ẇ-li֖⁠y ʼeֽţ-ha⁠ẖàm֑wòr waֽ⁠yȧẖàbòֽş̌ẇ׃"],[13,28,"וַ⁠יֵּ֗לֶךְ וַ⁠יִּמְצָ֤א אֶת־נִבְלָת⁠וֹ֙ מֻשְׁלֶ֣כֶת בַּ⁠דֶּ֔רֶךְ וַֽ⁠חֲמוֹר֙ וְ⁠הָ֣⁠אַרְיֵ֔ה עֹמְדִ֖ים אֵ֣צֶל הַ⁠נְּבֵלָ֑ה לֹֽא־אָכַ֤ל הָֽ⁠אַרְיֵה֙ אֶת־הַ⁠נְּבֵלָ֔ה וְ⁠לֹ֥א שָׁבַ֖ר אֶֽת־הַ⁠חֲמֽוֹר׃","wa⁠yé̇֗lekĕ wa⁠yi̇mĕẕá֤ʼ ʼeţ-nibĕláţ⁠wò֙ muşĕ̌le֣keţ bȧ⁠dė֔rekĕ wֽa⁠ẖàmwòr֙ wĕ⁠há֣⁠ʼarĕyé֔h ʻòmĕdi֖ym ʼé֣ẕel ha⁠nĕ̇bélá֑h lòֽʼ-ʼáka֤l háֽ⁠ʼarĕyéh֙ ʼeţ-ha⁠nĕ̇bélá֔h wĕ⁠lò֥ʼ şá̌ba֖r ʼeֽţ-ha⁠ẖàmֽwòr׃"],[13,29,"וַ⁠יִּשָּׂ֨א הַ⁠נָּבִ֜יא אֶת־נִבְלַ֧ת אִישׁ־הָ⁠אֱלֹהִ֛ים וַ⁠יַּנִּחֵ֥⁠הוּ אֶֽל־הַ⁠חֲמ֖וֹר וַ⁠יְשִׁיבֵ֑⁠הוּ וַ⁠יָּבֹ֗א אֶל־עִיר֙ הַ⁠נָּבִ֣יא הַ⁠זָּקֵ֔ן לִ⁠סְפֹּ֖ד וּ⁠לְ⁠קָבְרֽ⁠וֹ׃","wa⁠yi̇şá̇̂֨ʼ ha⁠ná̇bi֜yʼ ʼeţ-nibĕla֧ţ ʼiyş̌-há⁠ʼèlòhi֛ym wa⁠yȧni̇ẖé֥⁠hẇ ʼeֽl-ha⁠ẖàm֖wòr wa⁠yĕşǐybé֑⁠hẇ wa⁠yá̇bò֗ʼ ʼel-ʻiyr֙ ha⁠ná̇bi֣yʼ ha⁠zá̇qé֔n li⁠sĕpò֖̇d ẇ⁠lĕ⁠qábĕrֽ⁠wò׃"],[13,30,"וַ⁠יַּנַּ֥ח אֶת־נִבְלָת֖⁠וֹ בְּ⁠קִבְר֑⁠וֹ וַ⁠יִּסְפְּד֥וּ עָלָ֖י⁠ו ה֥וֹי אָחִֽ⁠י׃","wa⁠yȧnȧ֥ẖ ʼeţ-nibĕláţ֖⁠wò bĕ̇⁠qibĕr֑⁠wò wa⁠yi̇sĕpĕ̇d֥ẇ ʻálá֖y⁠w h֥wòy ʼáẖiֽ⁠y׃"],[13,31,"וַ⁠יְהִי֮ אַחֲרֵ֣י קָבְר֣⁠וֹ אֹת⁠וֹ֒ וַ⁠יֹּ֤אמֶר אֶל־בָּנָי⁠ו֙ לֵ⁠אמֹ֔ר בְּ⁠מוֹתִ⁠י֙ וּ⁠קְבַרְתֶּ֣ם אֹתִ֔⁠י בַּ⁠קֶּ֕בֶר אֲשֶׁ֛ר אִ֥ישׁ הָ⁠אֱלֹהִ֖ים קָב֣וּר בּ֑⁠וֹ אֵ֚צֶל עַצְמֹתָ֔י⁠ו הַנִּ֖יחוּ אֶת־עַצְמֹתָֽ⁠י׃","wa⁠yĕhiy֮ ʼaẖàré֣y qábĕr֣⁠wò ʼòţ⁠wò֒ wa⁠yò֤̇ʼmer ʼel-bá̇náy⁠w֙ lé⁠ʼmò֔r bĕ̇⁠mwòţi⁠y֙ ẇ⁠qĕbarĕţė֣m ʼòţi֔⁠y bȧ⁠qė֕ber ʼàşě֛r ʼi֥yş̌ há⁠ʼèlòhi֖ym qáb֣ẇr ḃ֑⁠wò ʼé֚ẕel ʻaẕĕmòţá֔y⁠w hani֖̇yẖẇ ʼeţ-ʻaẕĕmòţáֽ⁠y׃"],[13,32,"כִּי֩ הָיֹ֨ה יִהְיֶ֜ה הַ⁠דָּבָ֗ר אֲשֶׁ֤ר קָרָא֙ בִּ⁠דְבַ֣ר יְהוָ֔ה עַל־הַ⁠מִּזְבֵּ֖חַ אֲשֶׁ֣ר בְּ⁠בֵֽית־אֵ֑ל וְ⁠עַל֙ כָּל־בָּתֵּ֣י הַ⁠בָּמ֔וֹת אֲשֶׁ֖ר בְּ⁠עָרֵ֥י שֹׁמְרֽוֹן׃פ","ki̇y֩ háyò֨h yihĕye֜h ha⁠dá̇bá֗r ʼàşě֤r qáráʼ֙ bi̇⁠dĕba֣r yĕhwá֔h ʻal-ha⁠mi̇zĕbé֖̇ẖa ʼàşě֣r bĕ̇⁠béֽyţ-ʼé֑l wĕ⁠ʻal֙ ká̇l-bá̇ţé֣̇y ha⁠bá̇m֔wòţ ʼàşě֖r bĕ̇⁠ʻáré֥y şò̌mĕrֽwòn׃p"],[13,33,"אַחַר֙ הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה לֹֽא־שָׁ֥ב יָרָבְעָ֖ם מִ⁠דַּרְכּ֣⁠וֹ הָ⁠רָעָ֑ה וַ֠⁠יָּשָׁב וַ⁠יַּ֜עַשׂ מִ⁠קְצ֤וֹת הָ⁠עָם֙ כֹּהֲנֵ֣י בָמ֔וֹת הֶֽ⁠חָפֵץ֙ יְמַלֵּ֣א אֶת־יָד֔⁠וֹ וִ⁠יהִ֖י כֹּהֲנֵ֥י בָמֽוֹת׃","ʼaẖar֙ ha⁠dá̇bá֣r ha⁠zė֔h lòֽʼ-şá֥̌b yárábĕʻá֖m mi⁠dȧrĕk֣̇⁠wò há⁠ráʻá֑h wa֠⁠yá̇şá̌b wa⁠yȧ֜ʻaş̂ mi⁠qĕẕ֤wòţ há⁠ʻám֙ kò̇hàné֣y bám֔wòţ heֽ⁠ẖápéẕ֙ yĕmalé֣̇ʼ ʼeţ-yád֔⁠wò wi⁠yhi֖y kò̇hàné֥y bámֽwòţ׃"],[13,34,"וַ⁠יְהִי֙ בַּ⁠דָּבָ֣ר הַ⁠זֶּ֔ה לְ⁠חַטַּ֖את בֵּ֣ית יָרָבְעָ֑ם וּ⁠לְ⁠הַכְחִיד֙ וּ⁠לְ⁠הַשְׁמִ֔יד מֵ⁠עַ֖ל פְּנֵ֥י הָ⁠אֲדָמָֽה׃פ","wa⁠yĕhiy֙ bȧ⁠dá̇bá֣r ha⁠zė֔h lĕ⁠ẖatȧ֖ʼţ bé֣̇yţ yárábĕʻá֑m ẇ⁠lĕ⁠hakĕẖiyd֙ ẇ⁠lĕ⁠haşĕ̌mi֔yd mé⁠ʻa֖l pĕ̇né֥y há⁠ʼàdámáֽh׃p"],[14,1,"בָּ⁠עֵ֣ת הַ⁠הִ֔יא חָלָ֖ה אֲבִיָּ֥ה בֶן־יָרָבְעָֽם׃","bá̇⁠ʻé֣ţ ha⁠hi֔yʼ ẖálá֖h ʼàbiyá֥̇h ben-yárábĕʻáֽm׃"],[14,2,"וַ⁠יֹּ֨אמֶר יָרָבְעָ֜ם לְ⁠אִשְׁתּ֗⁠וֹ ק֤וּמִי נָא֙ וְ⁠הִשְׁתַּנִּ֔ית וְ⁠לֹ֣א יֵֽדְע֔וּ כִּי־ אתי אֵ֣שֶׁת יָרָבְעָ֑ם וְ⁠הָלַ֣כְתְּ שִׁלֹ֗ה הִנֵּה־שָׁם֙ אֲחִיָּ֣ה הַ⁠נָּבִ֔יא הֽוּא־דִבֶּ֥ר עָלַ֛⁠י לְ⁠מֶ֖לֶךְ עַל־הָ⁠עָ֥ם הַ⁠זֶּֽה׃","wa⁠yò̇֨ʼmer yárábĕʻá֜m lĕ⁠ʼişĕ̌ţ̇֗⁠wò q֤ẇmiy náʼ֙ wĕ⁠hişĕ̌ţȧni̇֔yţ wĕ⁠lò֣ʼ yéֽdĕʻ֔ẇ ki̇y- ʼţy ʼé֣şěţ yárábĕʻá֑m wĕ⁠hála֣kĕţĕ̇ şǐlò֗h hiné̇h-şá̌m֙ ʼàẖiyá֣̇h ha⁠ná̇bi֔yʼ hֽẇʼ-dibė֥r ʻála֛⁠y lĕ⁠me֖lekĕ ʻal-há⁠ʻá֥m ha⁠zėֽh׃"],[14,3,"וְ⁠לָקַ֣חַתְּ בְּ֠⁠יָדֵ⁠ךְ עֲשָׂרָ֨ה לֶ֧חֶם וְ⁠נִקֻּדִ֛ים וּ⁠בַקְבֻּ֥ק דְּבַ֖שׁ וּ⁠בָ֣את אֵלָ֑י⁠ו ה֚וּא יַגִּ֣יד לָ֔⁠ךְ מַה־יִּֽהְיֶ֖ה לַ⁠נָּֽעַר׃","wĕ⁠láqa֣ẖaţĕ̇ bĕ̇֠⁠yádé⁠kĕ ʻàşá̂rá֨h le֧ẖem wĕ⁠niqu̇di֛ym ẇ⁠baqĕbu֥̇q dĕ̇ba֖ş̌ ẇ⁠bá֣ʼţ ʼélá֑y⁠w h֚ẇʼ yagi֣̇yd lá֔⁠kĕ mah-yiֽ̇hĕye֖h la⁠náֽ̇ʻar׃"],[14,4,"וַ⁠תַּ֤עַשׂ כֵּן֙ אֵ֣שֶׁת יָרָבְעָ֔ם וַ⁠תָּ֨קָם֙ וַ⁠תֵּ֣לֶךְ שִׁלֹ֔ה וַ⁠תָּבֹ֖א בֵּ֣ית אֲחִיָּ֑ה וַ⁠אֲחִיָּ֨הוּ֙ לֹֽא־יָכֹ֣ל לִ⁠רְא֔וֹת כִּ֛י קָ֥מוּ עֵינָ֖י⁠ו מִ⁠שֵּׂיבֽ⁠וֹ׃ס","wa⁠ţȧ֤ʻaş̂ ké̇n֙ ʼé֣şěţ yárábĕʻá֔m wa⁠ţá̇֨qám֙ wa⁠ţé֣̇lekĕ şǐlò֔h wa⁠ţá̇bò֖ʼ bé֣̇yţ ʼàẖiyá֑̇h wa⁠ʼàẖiyá̇֨hẇ֙ lòֽʼ-yákò֣l li⁠rĕʼ֔wòţ ki֛̇y qá֥mẇ ʻéyná֖y⁠w mi⁠şé̇̂ybֽ⁠wò׃s"],[14,5,"וַ⁠יהוָ֞ה אָמַ֣ר אֶל־אֲחִיָּ֗הוּ הִנֵּ֣ה אֵ֣שֶׁת יָרָבְעָ֡ם בָּאָ֣ה לִ⁠דְרֹשׁ֩ דָּבָ֨ר מֵ⁠עִמְּ⁠ךָ֤ אֶל־בְּנָ⁠הּ֙ כִּֽי־חֹלֶ֣ה ה֔וּא כָּ⁠זֹ֥ה וְ⁠כָ⁠זֶ֖ה תְּדַבֵּ֣ר אֵלֶ֑י⁠הָ וִ⁠יהִ֣י כְ⁠בֹאָ֔⁠הּ וְ⁠הִ֖יא מִתְנַכֵּרָֽה׃","wa⁠yhwá֞h ʼáma֣r ʼel-ʼàẖiyá̇֗hẇ hiné֣̇h ʼé֣şěţ yárábĕʻá֡m bá̇ʼá֣h li⁠dĕròş̌֩ dá̇bá֨r mé⁠ʻimĕ̇⁠ká֤ ʼel-bĕ̇ná⁠ḣ֙ kiֽ̇y-ẖòle֣h h֔ẇʼ ká̇⁠zò֥h wĕ⁠ká⁠ze֖h ţĕ̇dabé֣̇r ʼéle֑y⁠há wi⁠yhi֣y kĕ⁠bòʼá֔⁠ḣ wĕ⁠hi֖yʼ miţĕnaké̇ráֽh׃"],[14,6,"וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ אֲחִיָּ֜הוּ אֶת־ק֤וֹל רַגְלֶ֨י⁠הָ֙ בָּאָ֣ה בַ⁠פֶּ֔תַח וַ⁠יֹּ֕אמֶר בֹּ֖אִי אֵ֣שֶׁת יָרָבְעָ֑ם לָ֣⁠מָּה זֶּ֗ה אַ֚תְּ מִתְנַכֵּרָ֔ה וְ⁠אָ֣נֹכִ֔י שָׁל֥וּחַ אֵלַ֖יִ⁠ךְ קָשָֽׁה׃","wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa ʼàẖiyá̇֜hẇ ʼeţ-q֤wòl ragĕle֨y⁠há֙ bá̇ʼá֣h ba⁠pė֔ţaẖ wa⁠yò̇֕ʼmer bò֖̇ʼiy ʼé֣şěţ yárábĕʻá֑m lá֣⁠má̇h zė֗h ʼa֚ţĕ̇ miţĕnaké̇rá֔h wĕ⁠ʼá֣nòki֔y şá̌l֥ẇẖa ʼéla֖yi⁠kĕ qáşáֽ̌h׃"],[14,7,"לְכִ֞י אִמְרִ֣י לְ⁠יָרָבְעָ֗ם כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל יַ֛עַן אֲשֶׁ֥ר הֲרִימֹתִ֖י⁠ךָ מִ⁠תּ֣וֹךְ הָ⁠עָ֑ם וָ⁠אֶתֶּנְ⁠ךָ֣ נָגִ֔יד עַ֖ל עַמִּ֥⁠י יִשְׂרָאֵֽל׃","lĕki֞y ʼimĕri֣y lĕ⁠yárábĕʻá֗m kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ya֛ʻan ʼàşě֥r hàriymòţi֖y⁠ká mi⁠ţ֣̇wòkĕ há⁠ʻá֑m wá⁠ʼeţėnĕ⁠ká֣ nági֔yd ʻa֖l ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[14,8,"וָ⁠אֶקְרַ֤ע אֶת־הַ⁠מַּמְלָכָה֙ מִ⁠בֵּ֣ית דָּוִ֔ד וָ⁠אֶתְּנֶ֖⁠הָ לָ֑⁠ךְ וְ⁠לֹֽא־הָיִ֜יתָ כְּ⁠עַבְדִּ֣⁠י דָוִ֗ד אֲשֶׁר֩ שָׁמַ֨ר מִצְוֺתַ֜⁠י וַ⁠אֲשֶׁר־הָלַ֤ךְ אַחֲרַ⁠י֙ בְּ⁠כָל־לְבָב֔⁠וֹ לַ⁠עֲשׂ֕וֹת רַ֖ק הַ⁠יָּשָׁ֥ר בְּ⁠עֵינָֽ⁠י׃","wá⁠ʼeqĕra֤ʻ ʼeţ-ha⁠mȧmĕlákáh֙ mi⁠bé֣̇yţ dá̇wi֔d wá⁠ʼeţĕ̇ne֖⁠há lá֑⁠kĕ wĕ⁠lòֽʼ-háyi֜yţá kĕ̇⁠ʻabĕdi֣̇⁠y dáwi֗d ʼàşěr֩ şá̌ma֨r miẕĕwֺţa֜⁠y wa⁠ʼàşěr-hála֤kĕ ʼaẖàra⁠y֙ bĕ̇⁠kál-lĕbáb֔⁠wò la⁠ʻàş̂֕wòţ ra֖q ha⁠yá̇şá֥̌r bĕ̇⁠ʻéynáֽ⁠y׃"],[14,9,"וַ⁠תָּ֣רַע לַ⁠עֲשׂ֔וֹת מִ⁠כֹּ֖ל אֲשֶׁר־הָי֣וּ לְ⁠פָנֶ֑י⁠ךָ וַ⁠תֵּ֡לֶךְ וַ⁠תַּעֲשֶׂה־לְּ⁠ךָ֩ אֱלֹהִ֨ים אֲחֵרִ֤ים וּ⁠מַסֵּכוֹת֙ לְ⁠הַכְעִיסֵ֔⁠נִי וְ⁠אֹתִ֥⁠י הִשְׁלַ֖כְתָּ אַחֲרֵ֥י גַוֶּֽ⁠ךָ׃ס","wa⁠ţá֣̇raʻ la⁠ʻàş̂֔wòţ mi⁠kò֖̇l ʼàşěr-háy֣ẇ lĕ⁠páne֑y⁠ká wa⁠ţé̇֡lekĕ wa⁠ţȧʻàşêh-lĕ̇⁠ká֩ ʼèlòhi֨ym ʼàẖéri֤ym ẇ⁠masé̇kwòţ֙ lĕ⁠hakĕʻiysé֔⁠niy wĕ⁠ʼòţi֥⁠y hişĕ̌la֖kĕţá̇ ʼaẖàré֥y gawėֽ⁠ká׃s"],[14,10,"לָ⁠כֵ֗ן הִנְ⁠נִ֨י מֵבִ֤יא רָעָה֙ אֶל־בֵּ֣ית יָרָבְעָ֔ם וְ⁠הִכְרַתִּ֤י לְ⁠יָֽרָבְעָם֙ מַשְׁתִּ֣ין בְּ⁠קִ֔יר עָצ֥וּר וְ⁠עָז֖וּב בְּ⁠יִשְׂרָאֵ֑ל וּ⁠בִֽעַרְתִּי֙ אַחֲרֵ֣י בֵית־יָרָבְעָ֔ם כַּ⁠אֲשֶׁ֛ר יְבַעֵ֥ר הַ⁠גָּלָ֖ל עַד־תֻּמּֽ⁠וֹ׃","lá⁠ké֗n hinĕ⁠ni֨y mébi֤yʼ ráʻáh֙ ʼel-bé֣̇yţ yárábĕʻá֔m wĕ⁠hikĕraţi֤̇y lĕ⁠yáֽrábĕʻám֙ maşĕ̌ţi֣̇yn bĕ̇⁠qi֔yr ʻáẕ֥ẇr wĕ⁠ʻáz֖ẇb bĕ̇⁠yişĕ̂ráʼé֑l ẇ⁠biֽʻarĕţi̇y֙ ʼaẖàré֣y béyţ-yárábĕʻá֔m kȧ⁠ʼàşě֛r yĕbaʻé֥r ha⁠gá̇lá֖l ʻad-ţu̇ṁֽ⁠wò׃"],[14,11,"הַ⁠מֵּ֨ת לְ⁠יָֽרָבְעָ֤ם בָּ⁠עִיר֙ יֹאכְל֣וּ הַ⁠כְּלָבִ֔ים וְ⁠הַ⁠מֵּת֙ בַּ⁠שָּׂדֶ֔ה יֹאכְל֖וּ ע֣וֹף הַ⁠שָּׁמָ֑יִם כִּ֥י יְהוָ֖ה דִּבֵּֽר׃","ha⁠mé̇֨ţ lĕ⁠yáֽrábĕʻá֤m bá̇⁠ʻiyr֙ yòʼkĕl֣ẇ ha⁠kĕ̇lábi֔ym wĕ⁠ha⁠mé̇ţ֙ bȧ⁠şá̇̂de֔h yòʼkĕl֖ẇ ʻ֣wòp ha⁠şá̇̌má֑yim ki֥̇y yĕhwá֖h di̇béֽ̇r׃"],[14,12,"וְ⁠אַ֥תְּ ק֖וּמִי לְכִ֣י לְ⁠בֵיתֵ֑⁠ךְ בְּ⁠בֹאָ֥ה רַגְלַ֛יִ⁠ךְ הָ⁠עִ֖ירָ⁠ה וּ⁠מֵ֥ת הַ⁠יָּֽלֶד׃","wĕ⁠ʼa֥ţĕ̇ q֖ẇmiy lĕki֣y lĕ⁠béyţé֑⁠kĕ bĕ̇⁠bòʼá֥h ragĕla֛yi⁠kĕ há⁠ʻi֖yrá⁠h ẇ⁠mé֥ţ ha⁠yáֽ̇led׃"],[14,13,"וְ⁠סָֽפְדוּ־ל֤⁠וֹ כָל־יִשְׂרָאֵל֙ וְ⁠קָבְר֣וּ אֹת֔⁠וֹ כִּֽי־זֶ֣ה לְ⁠בַדּ֔⁠וֹ יָבֹ֥א לְ⁠יָרָבְעָ֖ם אֶל־קָ֑בֶר יַ֣עַן נִמְצָא־ב֞⁠וֹ דָּבָ֣ר ט֗וֹב אֶל־יְהוָ֛ה אֱלֹהֵ֥י יִשְׂרָאֵ֖ל בְּ⁠בֵ֥ית יָרָבְעָֽם׃","wĕ⁠sáֽpĕdẇ-l֤⁠wò kál-yişĕ̂ráʼél֙ wĕ⁠qábĕr֣ẇ ʼòţ֔⁠wò kiֽ̇y-ze֣h lĕ⁠baḋ֔⁠wò yábò֥ʼ lĕ⁠yárábĕʻá֖m ʼel-qá֑ber ya֣ʻan nimĕẕáʼ-b֞⁠wò dá̇bá֣r t֗wòb ʼel-yĕhwá֛h ʼèlòhé֥y yişĕ̂ráʼé֖l bĕ̇⁠bé֥yţ yárábĕʻáֽm׃"],[14,14,"וְ⁠הֵקִים֩ יְהוָ֨ה ל֥⁠וֹ מֶ֨לֶךְ֙ עַל־יִשְׂרָאֵ֔ל אֲשֶׁ֥ר יַכְרִ֛ית אֶת־בֵּ֥ית יָרָבְעָ֖ם זֶ֣ה הַ⁠יּ֑וֹם וּ⁠מֶ֖ה גַּם־עָֽתָּה׃","wĕ⁠héqiym֩ yĕhwá֨h l֥⁠wò me֨lekĕ֙ ʻal-yişĕ̂ráʼé֔l ʼàşě֥r yakĕri֛yţ ʼeţ-bé֥̇yţ yárábĕʻá֖m ze֣h ha⁠ẏ֑wòm ẇ⁠me֖h gȧm-ʻáֽţá̇h׃"],[14,15,"וְ⁠הִכָּ֨ה יְהוָ֜ה אֶת־יִשְׂרָאֵ֗ל כַּ⁠אֲשֶׁ֨ר יָנ֣וּד הַ⁠קָּנֶה֮ בַּ⁠מַּיִם֒ וְ⁠נָתַ֣שׁ אֶת־יִשְׂרָאֵ֗ל מֵ֠⁠עַל הָ⁠אֲדָמָ֨ה הַ⁠טּוֹבָ֤ה הַ⁠זֹּאת֙ אֲשֶׁ֤ר נָתַן֙ לַ⁠אֲב֣וֹתֵי⁠הֶ֔ם וְ⁠זֵרָ֖⁠ם מֵ⁠עֵ֣בֶר לַ⁠נָּהָ֑ר יַ֗עַן אֲשֶׁ֤ר עָשׂוּ֙ אֶת־אֲשֵׁ֣רֵי⁠הֶ֔ם מַכְעִיסִ֖ים אֶת־יְהוָֽה׃","wĕ⁠hiká̇֨h yĕhwá֜h ʼeţ-yişĕ̂ráʼé֗l kȧ⁠ʼàşě֨r yán֣ẇd ha⁠qá̇neh֮ bȧ⁠mȧyim֒ wĕ⁠náţa֣ş̌ ʼeţ-yişĕ̂ráʼé֗l mé֠⁠ʻal há⁠ʼàdámá֨h ha⁠ṫwòbá֤h ha⁠zò̇ʼţ֙ ʼàşě֤r náţan֙ la⁠ʼàb֣wòţéy⁠he֔m wĕ⁠zérá֖⁠m mé⁠ʻé֣ber la⁠ná̇há֑r ya֗ʻan ʼàşě֤r ʻáş̂ẇ֙ ʼeţ-ʼàşé֣̌réy⁠he֔m makĕʻiysi֖ym ʼeţ-yĕhwáֽh׃"],[14,16,"וְ⁠יִתֵּ֖ן אֶת־יִשְׂרָאֵ֑ל בִּ⁠גְלַ֞ל חַטֹּ֤אות יָֽרָבְעָם֙ אֲשֶׁ֣ר חָטָ֔א וַ⁠אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃","wĕ⁠yiţé֖̇n ʼeţ-yişĕ̂ráʼé֑l bi̇⁠gĕla֞l ẖatò֤̇ʼwţ yáֽrábĕʻám֙ ʼàşě֣r ẖátá֔ʼ wa⁠ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[14,17,"וַ⁠תָּ֨קָם֙ אֵ֣שֶׁת יָרָבְעָ֔ם וַ⁠תֵּ֖לֶךְ וַ⁠תָּבֹ֣א תִרְצָ֑תָ⁠ה הִ֛יא בָּאָ֥ה בְ⁠סַף־הַ⁠בַּ֖יִת וְ⁠הַ⁠נַּ֥עַר מֵֽת׃","wa⁠ţá̇֨qám֙ ʼé֣şěţ yárábĕʻá֔m wa⁠ţé֖̇lekĕ wa⁠ţá̇bò֣ʼ ţirĕẕá֑ţá⁠h hi֛yʼ bá̇ʼá֥h bĕ⁠sap-ha⁠bȧ֖yiţ wĕ⁠ha⁠nȧ֥ʻar méֽţ׃"],[14,18,"וַ⁠יִּקְבְּר֥וּ אֹת֛⁠וֹ וַ⁠יִּסְפְּדוּ־ל֖⁠וֹ כָּל־יִשְׂרָאֵ֑ל כִּ⁠דְבַ֤ר יְהוָה֙ אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠יַד־עַבְדּ֖⁠וֹ אֲחִיָּ֥הוּ הַ⁠נָּבִֽיא׃","wa⁠yi̇qĕbĕ̇r֥ẇ ʼòţ֛⁠wò wa⁠yi̇sĕpĕ̇dẇ-l֖⁠wò ká̇l-yişĕ̂ráʼé֑l ki̇⁠dĕba֤r yĕhwáh֙ ʼàşě֣r di̇bė֔r bĕ̇⁠yad-ʻabĕḋ֖⁠wò ʼàẖiyá֥̇hẇ ha⁠ná̇biֽyʼ׃"],[14,19,"וְ⁠יֶ֨תֶר֙ דִּבְרֵ֣י יָֽרָבְעָ֔ם אֲשֶׁ֥ר נִלְחַ֖ם וַ⁠אֲשֶׁ֣ר מָלָ֑ךְ הִנָּ֣⁠ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer֙ di̇bĕré֣y yáֽrábĕʻá֔m ʼàşě֥r nilĕẖa֖m wa⁠ʼàşě֣r málá֑kĕ hiná֣̇⁠m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[14,20,"וְ⁠הַ⁠יָּמִים֙ אֲשֶׁ֣ר מָלַ֣ךְ יָרָבְעָ֔ם עֶשְׂרִ֥ים וּ⁠שְׁתַּ֖יִם שָׁנָ֑ה וַ⁠יִּשְׁכַּב֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּמְלֹ֛ךְ נָדָ֥ב בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wĕ⁠ha⁠yá̇miym֙ ʼàşě֣r mála֣kĕ yárábĕʻá֔m ʻeşĕ̂ri֥ym ẇ⁠şĕ̌ţȧ֖yim şá̌ná֑h wa⁠yi̇şĕ̌kȧb֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇mĕlò֛kĕ nádá֥b bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[14,21,"וּ⁠רְחַבְעָם֙ בֶּן־שְׁלֹמֹ֔ה מָלַ֖ךְ בִּֽ⁠יהוּדָ֑ה בֶּן־אַרְבָּעִ֣ים וְ⁠אַחַ֣ת שָׁנָה֩ רְחַבְעָ֨ם בְּ⁠מָלְכ֜⁠וֹ וּֽ⁠שֲׁבַ֨ע עֶשְׂרֵ֥ה שָׁנָ֣ה ׀ מָלַ֣ךְ בִּ⁠ירוּשָׁלִַ֗ם הָ֠⁠עִיר אֲשֶׁר־בָּחַ֨ר יְהוָ֜ה לָ⁠שׂ֨וּם אֶת־שְׁמ֥⁠וֹ שָׁם֙ מִ⁠כֹּל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ נַעֲמָ֖ה הָ⁠עַמֹּנִֽית׃","ẇ⁠rĕẖabĕʻám֙ bėn-şĕ̌lòmò֔h mála֖kĕ biֽ̇⁠yhẇdá֑h bėn-ʼarĕbá̇ʻi֣ym wĕ⁠ʼaẖa֣ţ şá̌náh֩ rĕẖabĕʻá֨m bĕ̇⁠málĕk֜⁠wò ẇֽ⁠şà̌ba֨ʻ ʻeşĕ̂ré֥h şá̌ná֣h ׀ mála֣kĕ bi̇⁠yrẇşá̌lia֗m há֠⁠ʻiyr ʼàşěr-bá̇ẖa֨r yĕhwá֜h lá⁠ş̂֨ẇm ʼeţ-şĕ̌m֥⁠wò şá̌m֙ mi⁠kò̇l֙ şǐbĕté֣y yişĕ̂ráʼé֔l wĕ⁠şé֣̌m ʼiṁ֔⁠wò naʻàmá֖h há⁠ʻamò̇niֽyţ׃"],[14,22,"וַ⁠יַּ֧עַשׂ יְהוּדָ֛ה הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יְקַנְא֣וּ אֹת֗⁠וֹ מִ⁠כֹּל֙ אֲשֶׁ֣ר עָשׂ֣וּ אֲבֹתָ֔⁠ם בְּ⁠חַטֹּאתָ֖⁠ם אֲשֶׁ֥ר חָטָֽאוּ׃","wa⁠yȧ֧ʻaş̂ yĕhẇdá֛h há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yĕqanĕʼ֣ẇ ʼòţ֗⁠wò mi⁠kò̇l֙ ʼàşě֣r ʻáş֣̂ẇ ʼàbòţá֔⁠m bĕ̇⁠ẖatò̇ʼţá֖⁠m ʼàşě֥r ẖátáֽʼẇ׃"],[14,23,"וַ⁠יִּבְנ֨וּ גַם־הֵ֧מָּה לָ⁠הֶ֛ם בָּמ֥וֹת וּ⁠מַצֵּב֖וֹת וַ⁠אֲשֵׁרִ֑ים עַ֚ל כָּל־גִּבְעָ֣ה גְבֹהָ֔ה וְ⁠תַ֖חַת כָּל־עֵ֥ץ רַעֲנָֽן׃","wa⁠yi̇bĕn֨ẇ gam-hé֧má̇h lá⁠he֛m bá̇m֥wòţ ẇ⁠maẕé̇b֖wòţ wa⁠ʼàşé̌ri֑ym ʻa֚l ká̇l-gi̇bĕʻá֣h gĕbòhá֔h wĕ⁠ţa֖ẖaţ ká̇l-ʻé֥ẕ raʻànáֽn׃"],[14,24,"וְ⁠גַם־קָדֵ֖שׁ הָיָ֣ה בָ⁠אָ֑רֶץ עָשׂ֗וּ כְּ⁠כֹל֙ הַ⁠תּוֹעֲבֹ֣ת הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ הוֹרִ֣ישׁ יְהוָ֔ה מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃פ","wĕ⁠gam-qádé֖ş̌ háyá֣h bá⁠ʼá֑reẕ ʻáş̂֗ẇ kĕ̇⁠kòl֙ ha⁠ţ̇wòʻàbò֣ţ ha⁠ġwòyi֔m ʼàşěr֙ hwòri֣yş̌ yĕhwá֔h mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃p"],[14,25,"וַ⁠יְהִ֛י בַּ⁠שָּׁנָ֥ה הַ⁠חֲמִישִׁ֖ית לַ⁠מֶּ֣לֶךְ רְחַבְעָ֑ם עָלָ֛ה שושק מֶֽלֶךְ־מִצְרַ֖יִם עַל־יְרוּשָׁלִָֽם׃","wa⁠yĕhi֛y bȧ⁠şá̇̌ná֥h ha⁠ẖàmiyşǐ֖yţ la⁠mė֣lekĕ rĕẖabĕʻá֑m ʻálá֛h şwşq meֽlekĕ-miẕĕra֖yim ʻal-yĕrẇşá̌liáֽm׃"],[14,26,"וַ⁠יִּקַּ֞ח אֶת־אֹצְר֣וֹת בֵּית־יְהוָ֗ה וְ⁠אֶת־אֽוֹצְרוֹת֙ בֵּ֣ית הַ⁠מֶּ֔לֶךְ וְ⁠אֶת־הַ⁠כֹּ֖ל לָקָ֑ח וַ⁠יִּקַּח֙ אֶת־כָּל־מָגִנֵּ֣י הַ⁠זָּהָ֔ב אֲשֶׁ֥ר עָשָׂ֖ה שְׁלֹמֹֽה׃","wa⁠yi̇qȧ֞ẖ ʼeţ-ʼòẕĕr֣wòţ bé̇yţ-yĕhwá֗h wĕ⁠ʼeţ-ʼֽwòẕĕrwòţ֙ bé֣̇yţ ha⁠mė֔lekĕ wĕ⁠ʼeţ-ha⁠kò֖̇l láqá֑ẖ wa⁠yi̇qȧẖ֙ ʼeţ-ká̇l-máginé֣̇y ha⁠zá̇há֔b ʼàşě֥r ʻáşá֖̂h şĕ̌lòmòֽh׃"],[14,27,"וַ⁠יַּ֨עַשׂ הַ⁠מֶּ֤לֶךְ רְחַבְעָם֙ תַּחְתָּ֔⁠ם מָגִנֵּ֖י נְחֹ֑שֶׁת וְ⁠הִפְקִ֗יד עַל־יַד֙ שָׂרֵ֣י הָ⁠רָצִ֔ים הַ⁠שֹּׁ֣מְרִ֔ים פֶּ֖תַח בֵּ֥ית הַ⁠מֶּֽלֶךְ׃","wa⁠yȧ֨ʻaş̂ ha⁠mė֤lekĕ rĕẖabĕʻám֙ ţȧẖĕţá̇֔⁠m máginé֖̇y nĕẖò֑şěţ wĕ⁠hipĕqi֗yd ʻal-yad֙ şá̂ré֣y há⁠ráẕi֔ym ha⁠şò֣̇̌mĕri֔ym pė֖ţaẖ bé֥̇yţ ha⁠mėֽlekĕ׃"],[14,28,"וַ⁠יְהִ֛י מִ⁠דֵּי־בֹ֥א הַ⁠מֶּ֖לֶךְ בֵּ֣ית יְהוָ֑ה יִשָּׂאוּ⁠ם֙ הָֽ⁠רָצִ֔ים וֶ⁠הֱשִׁיב֖וּ⁠ם אֶל־תָּ֥א הָ⁠רָצִֽים׃","wa⁠yĕhi֛y mi⁠dé̇y-bò֥ʼ ha⁠mė֖lekĕ bé֣̇yţ yĕhwá֑h yişá̇̂ʼẇ⁠m֙ háֽ⁠ráẕi֔ym we⁠hèşǐyb֖ẇ⁠m ʼel-ţá֥̇ʼ há⁠ráẕiֽym׃"],[14,29,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י רְחַבְעָ֖ם וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹא־הֵ֣מָּה כְתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֛ţer di̇bĕré֥y rĕẖabĕʻá֖m wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lòʼ-hé֣má̇h kĕţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[14,30,"וּ⁠מִלְחָמָ֨ה הָיְתָ֧ה בֵין־רְחַבְעָ֛ם וּ⁠בֵ֥ין יָרָבְעָ֖ם כָּל־הַ⁠יָּמִֽים׃","ẇ⁠milĕẖámá֨h háyĕţá֧h béyn-rĕẖabĕʻá֛m ẇ⁠bé֥yn yárábĕʻá֖m ká̇l-ha⁠yá̇miֽym׃"],[14,31,"וַ⁠יִּשְׁכַּ֨ב רְחַבְעָ֜ם עִם־אֲבֹתָ֗י⁠ו וַ⁠יִּקָּבֵ֤ר עִם־אֲבֹתָי⁠ו֙ בְּ⁠עִ֣יר דָּוִ֔ד וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ נַעֲמָ֖ה הָ⁠עַמֹּנִ֑ית וַ⁠יִּמְלֹ֛ךְ אֲבִיָּ֥ם בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֨b rĕẖabĕʻá֜m ʻim-ʼàbòţá֗y⁠w wa⁠yi̇qá̇bé֤r ʻim-ʼàbòţáy⁠w֙ bĕ̇⁠ʻi֣yr dá̇wi֔d wĕ⁠şé֣̌m ʼiṁ֔⁠wò naʻàmá֖h há⁠ʻamò̇ni֑yţ wa⁠yi̇mĕlò֛kĕ ʼàbiyá֥̇m bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[15,1,"וּ⁠בִ⁠שְׁנַת֙ שְׁמֹנֶ֣ה עֶשְׂרֵ֔ה לַ⁠מֶּ֖לֶךְ יָרָבְעָ֣ם בֶּן־נְבָ֑ט מָלַ֥ךְ אֲבִיָּ֖ם עַל־יְהוּדָֽה׃","ẇ⁠bi⁠şĕ̌naţ֙ şĕ̌mòne֣h ʻeşĕ̂ré֔h la⁠mė֖lekĕ yárábĕʻá֣m bėn-nĕbá֑t mála֥kĕ ʼàbiyá֖̇m ʻal-yĕhẇdáֽh׃"],[15,2,"שָׁלֹ֣שׁ שָׁנִ֔ים מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ מַעֲכָ֖ה בַּת־אֲבִישָׁלֽוֹם׃","şá̌lò֣ş̌ şá̌ni֔ym mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò maʻàká֖h bȧţ-ʼàbiyşá̌lֽwòm׃"],[15,3,"וַ⁠יֵּ֕לֶךְ בְּ⁠כָל־חַטֹּ֥אות אָבִ֖י⁠ו אֲשֶׁר־עָשָׂ֣ה לְ⁠פָנָ֑י⁠ו וְ⁠לֹא־הָיָ֨ה לְבָב֤⁠וֹ שָׁלֵם֙ עִם־יְהוָ֣ה אֱלֹהָ֔י⁠ו כִּ⁠לְבַ֖ב דָּוִ֥ד אָבִֽי⁠ו׃","wa⁠yé̇֕lekĕ bĕ̇⁠kál-ẖatò֥̇ʼwţ ʼábi֖y⁠w ʼàşěr-ʻáşá֣̂h lĕ⁠páná֑y⁠w wĕ⁠lòʼ-háyá֨h lĕbáb֤⁠wò şá̌lém֙ ʻim-yĕhwá֣h ʼèlòhá֔y⁠w ki̇⁠lĕba֖b dá̇wi֥d ʼábiֽy⁠w׃"],[15,4,"כִּ֚י לְמַ֣עַן דָּוִ֔ד נָתַן֩ יְהוָ֨ה אֱלֹהָ֥י⁠ו ל֛⁠וֹ נִ֖יר בִּ⁠ירוּשָׁלִָ֑ם לְ⁠הָקִ֤ים אֶת־בְּנ⁠וֹ֙ אַחֲרָ֔י⁠ו וּֽ⁠לְ⁠הַעֲמִ֖יד אֶת־יְרוּשָׁלִָֽם׃","ki֚̇y lĕma֣ʻan dá̇wi֔d náţan֩ yĕhwá֨h ʼèlòhá֥y⁠w l֛⁠wò ni֖yr bi̇⁠yrẇşá̌liá֑m lĕ⁠háqi֤ym ʼeţ-bĕ̇n⁠wò֙ ʼaẖàrá֔y⁠w ẇֽ⁠lĕ⁠haʻàmi֖yd ʼeţ-yĕrẇşá̌liáֽm׃"],[15,5,"אֲשֶׁ֨ר עָשָׂ֥ה דָוִ֛ד אֶת־הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה וְ⁠לֹֽא־סָ֞ר מִ⁠כֹּ֣ל אֲשֶׁר־צִוָּ֗⁠הוּ כֹּ֚ל יְמֵ֣י חַיָּ֔י⁠ו רַ֕ק בִּ⁠דְבַ֖ר אוּרִיָּ֥ה הַ⁠חִתִּֽי׃","ʼàşě֨r ʻáşá֥̂h dáwi֛d ʼeţ-ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h wĕ⁠lòֽʼ-sá֞r mi⁠kò֣̇l ʼàşěr-ẕiwá̇֗⁠hẇ kò֚̇l yĕmé֣y ẖayá̇֔y⁠w ra֕q bi̇⁠dĕba֖r ʼẇriyá֥̇h ha⁠ẖiţiֽ̇y׃"],[15,6,"וּ⁠מִלְחָמָ֨ה הָיְתָ֧ה בֵין־רְחַבְעָ֛ם וּ⁠בֵ֥ין יָרָבְעָ֖ם כָּל־יְמֵ֥י חַיָּֽי⁠ו׃","ẇ⁠milĕẖámá֨h háyĕţá֧h béyn-rĕẖabĕʻá֛m ẇ⁠bé֥yn yárábĕʻá֖m ká̇l-yĕmé֥y ẖayáֽ̇y⁠w׃"],[15,7,"וְ⁠יֶ֨תֶר דִּבְרֵ֤י אֲבִיָּם֙ וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֔ה הֲ⁠לֽוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֣י יְהוּדָ֑ה וּ⁠מִלְחָמָ֥ה הָיְתָ֛ה בֵּ֥ין אֲבִיָּ֖ם וּ⁠בֵ֥ין יָרָבְעָֽם׃","wĕ⁠ye֨ţer di̇bĕré֤y ʼàbiyá̇m֙ wĕ⁠kál-ʼàşě֣r ʻáşá̂֔h hà⁠lֽwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֣y yĕhẇdá֑h ẇ⁠milĕẖámá֥h háyĕţá֛h bé֥̇yn ʼàbiyá֖̇m ẇ⁠bé֥yn yárábĕʻáֽm׃"],[15,8,"וַ⁠יִּשְׁכַּ֤ב אֲבִיָּם֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקְבְּר֥וּ אֹת֖⁠וֹ בְּ⁠עִ֣יר דָּוִ֑ד וַ⁠יִּמְלֹ֛ךְ אָסָ֥א בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b ʼàbiyá̇m֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qĕbĕ̇r֥ẇ ʼòţ֖⁠wò bĕ̇⁠ʻi֣yr dá̇wi֑d wa⁠yi̇mĕlò֛kĕ ʼásá֥ʼ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[15,9,"וּ⁠בִ⁠שְׁנַ֣ת עֶשְׂרִ֔ים לְ⁠יָרָבְעָ֖ם מֶ֣לֶךְ יִשְׂרָאֵ֑ל מָלַ֥ךְ אָסָ֖א מֶ֥לֶךְ יְהוּדָֽה׃","ẇ⁠bi⁠şĕ̌na֣ţ ʻeşĕ̂ri֔ym lĕ⁠yárábĕʻá֖m me֣lekĕ yişĕ̂ráʼé֑l mála֥kĕ ʼásá֖ʼ me֥lekĕ yĕhẇdáֽh׃"],[15,10,"וְ⁠אַרְבָּעִ֤ים וְ⁠אַחַת֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ מַעֲכָ֖ה בַּת־אֲבִישָׁלֽוֹם׃","wĕ⁠ʼarĕbá̇ʻi֤ym wĕ⁠ʼaẖaţ֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò maʻàká֖h bȧţ-ʼàbiyşá̌lֽwòm׃"],[15,11,"וַ⁠יַּ֧עַשׂ אָסָ֛א הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֣י יְהוָ֑ה כְּ⁠דָוִ֖ד אָבִֽי⁠ו׃","wa⁠yȧ֧ʻaş̂ ʼásá֛ʼ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֣y yĕhwá֑h kĕ̇⁠dáwi֖d ʼábiֽy⁠w׃"],[15,12,"וַ⁠יַּעֲבֵ֥ר הַ⁠קְּדֵשִׁ֖ים מִן־הָ⁠אָ֑רֶץ וַ⁠יָּ֨סַר֙ אֶת־כָּל־הַ⁠גִּלֻּלִ֔ים אֲשֶׁ֥ר עָשׂ֖וּ אֲבֹתָֽי⁠ו׃","wa⁠yȧʻàbé֥r ha⁠qĕ̇déşǐ֖ym min-há⁠ʼá֑reẕ wa⁠yá̇֨sar֙ ʼeţ-ká̇l-ha⁠gi̇lu̇li֔ym ʼàşě֥r ʻáş֖̂ẇ ʼàbòţáֽy⁠w׃"],[15,13,"וְ⁠גַ֣ם ׀ אֶת־מַעֲכָ֣ה אִמּ֗⁠וֹ וַ⁠יְסִרֶ֨⁠הָ֙ מִ⁠גְּבִירָ֔ה אֲשֶׁר־עָשְׂתָ֥ה מִפְלֶ֖צֶת לָ⁠אֲשֵׁרָ֑ה וַ⁠יִּכְרֹ֤ת אָסָא֙ אֶת־מִפְלַצְתָּ֔⁠הּ וַ⁠יִּשְׂרֹ֖ף בְּ⁠נַ֥חַל קִדְרֽוֹן׃","wĕ⁠ga֣m ׀ ʼeţ-maʻàká֣h ʼiṁ֗⁠wò wa⁠yĕsire֨⁠há֙ mi⁠gĕ̇biyrá֔h ʼàşěr-ʻáşĕ̂ţá֥h mipĕle֖ẕeţ lá⁠ʼàşé̌rá֑h wa⁠yi̇kĕrò֤ţ ʼásáʼ֙ ʼeţ-mipĕlaẕĕţá̇֔⁠ḣ wa⁠yi̇şĕ̂rò֖p bĕ̇⁠na֥ẖal qidĕrֽwòn׃"],[15,14,"וְ⁠הַ⁠בָּמ֖וֹת לֹא־סָ֑רוּ רַ֣ק לְבַב־אָסָ֗א הָיָ֥ה שָׁלֵ֛ם עִם־יְהוָ֖ה כָּל־יָמָֽי⁠ו׃","wĕ⁠ha⁠bá̇m֖wòţ lòʼ-sá֑rẇ ra֣q lĕbab-ʼásá֗ʼ háyá֥h şá̌lé֛m ʻim-yĕhwá֖h ká̇l-yámáֽy⁠w׃"],[15,15,"וַ⁠יָּבֵא֙ אֶת־קָדְשֵׁ֣י אָבִ֔י⁠ו ו⁠קדש⁠ו בֵּ֣ית יְהוָ֑ה כֶּ֥סֶף וְ⁠זָהָ֖ב וְ⁠כֵלִֽים׃","wa⁠yá̇béʼ֙ ʼeţ-qádĕşé֣̌y ʼábi֔y⁠w w⁠qdş⁠w bé֣̇yţ yĕhwá֑h kė֥sep wĕ⁠záhá֖b wĕ⁠kéliֽym׃"],[15,16,"וּ⁠מִלְחָמָ֨ה הָיְתָ֜ה בֵּ֣ין אָסָ֗א וּ⁠בֵ֛ין בַּעְשָׁ֥א מֶֽלֶךְ־יִשְׂרָאֵ֖ל כָּל־יְמֵי⁠הֶֽם׃","ẇ⁠milĕẖámá֨h háyĕţá֜h bé֣̇yn ʼásá֗ʼ ẇ⁠bé֛yn bȧʻĕşá֥̌ʼ meֽlekĕ-yişĕ̂ráʼé֖l ká̇l-yĕméy⁠heֽm׃"],[15,17,"וַ⁠יַּ֨עַל בַּעְשָׁ֤א מֶֽלֶךְ־יִשְׂרָאֵל֙ עַל־יְהוּדָ֔ה וַ⁠יִּ֖בֶן אֶת־הָ⁠רָמָ֑ה לְ⁠בִלְתִּ֗י תֵּ֚ת יֹצֵ֣א וָ⁠בָ֔א לְ⁠אָסָ֖א מֶ֥לֶךְ יְהוּדָֽה׃","wa⁠yȧ֨ʻal bȧʻĕşá֤̌ʼ meֽlekĕ-yişĕ̂ráʼél֙ ʻal-yĕhẇdá֔h wa⁠yi֖̇ben ʼeţ-há⁠rámá֑h lĕ⁠bilĕţi̇֗y ţé֚̇ţ yòẕé֣ʼ wá⁠bá֔ʼ lĕ⁠ʼásá֖ʼ me֥lekĕ yĕhẇdáֽh׃"],[15,18,"וַ⁠יִּקַּ֣ח אָ֠סָא אֶת־כָּל־הַ⁠כֶּ֨סֶף וְ⁠הַ⁠זָּהָ֜ב הַֽ⁠נּוֹתָרִ֣ים ׀ בְּ⁠אוֹצְר֣וֹת בֵּית־יְהוָ֗ה וְ⁠אֶת־אֽוֹצְרוֹת֙ בֵּ֣ית מלך וַֽ⁠יִּתְּנֵ֖⁠ם בְּ⁠יַד־עֲבָדָ֑י⁠ו וַ⁠יִּשְׁלָחֵ֞⁠ם הַ⁠מֶּ֣לֶךְ אָסָ֗א אֶל־בֶּן־הֲ֠דַד בֶּן־טַבְרִמֹּ֤ן בֶּן־חֶזְיוֹן֙ מֶ֣לֶךְ אֲרָ֔ם הַ⁠יֹּשֵׁ֥ב בְּ⁠דַמֶּ֖שֶׂק לֵ⁠אמֹֽר׃","wa⁠yi̇qȧ֣ẖ ʼá֠sáʼ ʼeţ-ká̇l-ha⁠kė֨sep wĕ⁠ha⁠zá̇há֜b haֽ⁠ṅwòţári֣ym ׀ bĕ̇⁠ʼwòẕĕr֣wòţ bé̇yţ-yĕhwá֗h wĕ⁠ʼeţ-ʼֽwòẕĕrwòţ֙ bé֣̇yţ mlk waֽ⁠yi̇ţĕ̇né֖⁠m bĕ̇⁠yad-ʻàbádá֑y⁠w wa⁠yi̇şĕ̌láẖé֞⁠m ha⁠mė֣lekĕ ʼásá֗ʼ ʼel-bėn-hà֠dad bėn-tabĕrimò֤̇n bėn-ẖezĕywòn֙ me֣lekĕ ʼàrá֔m ha⁠yò̇şé֥̌b bĕ̇⁠damė֖şêq lé⁠ʼmòֽr׃"],[15,19,"בְּרִית֙ בֵּינִ֣⁠י וּ⁠בֵינֶ֔⁠ךָ בֵּ֥ין אָבִ֖⁠י וּ⁠בֵ֣ין אָבִ֑י⁠ךָ הִנֵּה֩ שָׁלַ֨חְתִּֽי לְ⁠ךָ֥ שֹׁ֨חַד֙ כֶּ֣סֶף וְ⁠זָהָ֔ב לֵ֣ךְ הָפֵ֗רָ⁠ה אֶת־בְּרִֽיתְ⁠ךָ֙ אֶת־בַּעְשָׁ֣א מֶֽלֶךְ־יִשְׂרָאֵ֔ל וְ⁠יַעֲלֶ֖ה מֵ⁠עָלָֽ⁠י׃","bĕ̇riyţ֙ bé̇yni֣⁠y ẇ⁠béyne֔⁠ká bé֥̇yn ʼábi֖⁠y ẇ⁠bé֣yn ʼábi֑y⁠ká hiné̇h֩ şá̌la֨ẖĕţiֽ̇y lĕ⁠ká֥ şò̌֨ẖad֙ kė֣sep wĕ⁠záhá֔b lé֣kĕ hápé֗rá⁠h ʼeţ-bĕ̇riֽyţĕ⁠ká֙ ʼeţ-bȧʻĕşá֣̌ʼ meֽlekĕ-yişĕ̂ráʼé֔l wĕ⁠yaʻàle֖h mé⁠ʻáláֽ⁠y׃"],[15,20,"וַ⁠יִּשְׁמַ֨ע בֶּן־הֲדַ֜ד אֶל־הַ⁠מֶּ֣לֶךְ אָסָ֗א וַ֠⁠יִּשְׁלַח אֶת־שָׂרֵ֨י הַ⁠חֲיָלִ֤ים אֲשֶׁר־ל⁠וֹ֙ עַל־עָרֵ֣י יִשְׂרָאֵ֔ל וַ⁠יַּךְ֙ אֶת־עִיּ֣וֹן וְ⁠אֶת־דָּ֔ן וְ⁠אֵ֖ת אָבֵ֣ל בֵּֽית־מַעֲכָ֑ה וְ⁠אֵת֙ כָּל־כִּנְר֔וֹת עַ֖ל כָּל־אֶ֥רֶץ נַפְתָּלִֽי׃","wa⁠yi̇şĕ̌ma֨ʻ bėn-hàda֜d ʼel-ha⁠mė֣lekĕ ʼásá֗ʼ wa֠⁠yi̇şĕ̌laẖ ʼeţ-şá̂ré֨y ha⁠ẖàyáli֤ym ʼàşěr-l⁠wò֙ ʻal-ʻáré֣y yişĕ̂ráʼé֔l wa⁠yȧkĕ֙ ʼeţ-ʻiẏ֣wòn wĕ⁠ʼeţ-dá̇֔n wĕ⁠ʼé֖ţ ʼábé֣l béֽ̇yţ-maʻàká֑h wĕ⁠ʼéţ֙ ká̇l-ki̇nĕr֔wòţ ʻa֖l ká̇l-ʼe֥reẕ napĕţá̇liֽy׃"],[15,21,"וַֽ⁠יְהִי֙ כִּ⁠שְׁמֹ֣עַ בַּעְשָׁ֔א וַ⁠יֶּחְדַּ֕ל מִ⁠בְּנ֖וֹת אֶת־הָֽ⁠רָמָ֑ה וַ⁠יֵּ֖שֶׁב בְּ⁠תִרְצָֽה׃","waֽ⁠yĕhiy֙ ki̇⁠şĕ̌mò֣ʻa bȧʻĕşá̌֔ʼ wa⁠yėẖĕdȧ֕l mi⁠bĕ̇n֖wòţ ʼeţ-hֽá⁠rámá֑h wa⁠yé֖̇şěb bĕ̇⁠ţirĕẕáֽh׃"],[15,22,"וְ⁠הַ⁠מֶּ֨לֶךְ אָסָ֜א הִשְׁמִ֤יעַ אֶת־כָּל־יְהוּדָה֙ אֵ֣ין נָקִ֔י וַ⁠יִּשְׂא֞וּ אֶת־אַבְנֵ֤י הָֽ⁠רָמָה֙ וְ⁠אֶת־עֵצֶ֔י⁠הָ אֲשֶׁ֥ר בָּנָ֖ה בַּעְשָׁ֑א וַ⁠יִּ֤בֶן בָּ⁠ם֙ הַ⁠מֶּ֣לֶךְ אָסָ֔א אֶת־גֶּ֥בַע בִּנְיָמִ֖ן וְ⁠אֶת־הַ⁠מִּצְפָּֽה׃","wĕ⁠ha⁠mė֨lekĕ ʼásá֜ʼ hişĕ̌mi֤yʻa ʼeţ-ká̇l-yĕhẇdáh֙ ʼé֣yn náqi֔y wa⁠yi̇şĕ̂ʼ֞ẇ ʼeţ-ʼabĕné֤y háֽ⁠rámáh֙ wĕ⁠ʼeţ-ʻéẕe֔y⁠há ʼàşě֥r bá̇ná֖h bȧʻĕşá֑̌ʼ wa⁠yi֤̇ben bá̇⁠m֙ ha⁠mė֣lekĕ ʼásá֔ʼ ʼeţ-gė֥baʻ bi̇nĕyámi֖n wĕ⁠ʼeţ-ha⁠mi̇ẕĕpáֽ̇h׃"],[15,23,"וְ⁠יֶ֣תֶר כָּל־דִּבְרֵֽי־אָ֠סָא וְ⁠כָל־גְּב֨וּרָת֜⁠וֹ וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֗ה וְ⁠הֶֽ⁠עָרִים֙ אֲשֶׁ֣ר בָּנָ֔ה הֲ⁠לֹֽא־הֵ֣מָּה כְתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֣י יְהוּדָ֑ה רַ֚ק לְ⁠עֵ֣ת זִקְנָת֔⁠וֹ חָלָ֖ה אֶת־רַגְלָֽי⁠ו׃","wĕ⁠ye֣ţer ká̇l-di̇bĕréֽy-ʼá֠sáʼ wĕ⁠kál-gĕ̇b֨ẇráţ֜⁠wò wĕ⁠kál-ʼàşě֣r ʻáşá̂֗h wĕ⁠heֽ⁠ʻáriym֙ ʼàşě֣r bá̇ná֔h hà⁠lòֽʼ-hé֣má̇h kĕţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֣y yĕhẇdá֑h ra֚q lĕ⁠ʻé֣ţ ziqĕnáţ֔⁠wò ẖálá֖h ʼeţ-ragĕláֽy⁠w׃"],[15,24,"וַ⁠יִּשְׁכַּ֤ב אָסָא֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵר֙ עִם־אֲבֹתָ֔י⁠ו בְּ⁠עִ֖יר דָּוִ֣ד אָבִ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ יְהוֹשָׁפָ֥ט בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b ʼásáʼ֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bér֙ ʻim-ʼàbòţá֔y⁠w bĕ̇⁠ʻi֖yr dá̇wi֣d ʼábi֑y⁠w wa⁠yi̇mĕlò֛kĕ yĕhwòşá̌pá֥t bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[15,25,"וְ⁠נָדָ֣ב בֶּן־יָרָבְעָ֗ם מָלַךְ֙ עַל־יִשְׂרָאֵ֔ל בִּ⁠שְׁנַ֣ת שְׁתַּ֔יִם לְ⁠אָסָ֖א מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠יִּמְלֹ֥ךְ עַל־יִשְׂרָאֵ֖ל שְׁנָתָֽיִם׃","wĕ⁠nádá֣b bėn-yárábĕʻá֗m málakĕ֙ ʻal-yişĕ̂ráʼé֔l bi̇⁠şĕ̌na֣ţ şĕ̌ţȧ֔yim lĕ⁠ʼásá֖ʼ me֣lekĕ yĕhẇdá֑h wa⁠yi̇mĕlò֥kĕ ʻal-yişĕ̂ráʼé֖l şĕ̌náţáֽyim׃"],[15,26,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יֵּ֨לֶךְ֙ בְּ⁠דֶ֣רֶךְ אָבִ֔י⁠ו וּ֨⁠בְ⁠חַטָּאת֔⁠וֹ אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yé̇֨lekĕ֙ bĕ̇⁠de֣rekĕ ʼábi֔y⁠w ẇ֨⁠bĕ⁠ẖatá̇ʼţ֔⁠wò ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[15,27,"וַ⁠יִּקְשֹׁ֨ר עָלָ֜י⁠ו בַּעְשָׁ֤א בֶן־אֲחִיָּה֙ לְ⁠בֵ֣ית יִשָּׂשכָ֔ר וַ⁠יַּכֵּ֣⁠הוּ בַעְשָׁ֔א בְּ⁠גִבְּת֖וֹן אֲשֶׁ֣ר לַ⁠פְּלִשְׁתִּ֑ים וְ⁠נָדָב֙ וְ⁠כָל־יִשְׂרָאֵ֔ל צָרִ֖ים עַֽל־גִּבְּתֽוֹן׃","wa⁠yi̇qĕşò̌֨r ʻálá֜y⁠w bȧʻĕşá֤̌ʼ ben-ʼàẖiyá̇h֙ lĕ⁠bé֣yţ yişá̇̂şká֔r wa⁠yȧké֣̇⁠hẇ baʻĕşá̌֔ʼ bĕ̇⁠gibĕ̇ţ֖wòn ʼàşě֣r la⁠pĕ̇lişĕ̌ţi֑̇ym wĕ⁠nádáb֙ wĕ⁠kál-yişĕ̂ráʼé֔l ẕári֖ym ʻaֽl-gi̇bĕ̇ţֽwòn׃"],[15,28,"וַ⁠יְמִתֵ֣⁠הוּ בַעְשָׁ֔א בִּ⁠שְׁנַ֣ת שָׁלֹ֔שׁ לְ⁠אָסָ֖א מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠יִּמְלֹ֖ךְ תַּחְתָּֽי⁠ו׃","wa⁠yĕmiţé֣⁠hẇ baʻĕşá̌֔ʼ bi̇⁠şĕ̌na֣ţ şá̌lò֔ş̌ lĕ⁠ʼásá֖ʼ me֣lekĕ yĕhẇdá֑h wa⁠yi̇mĕlò֖kĕ ţȧẖĕţáֽ̇y⁠w׃"],[15,29,"וַ⁠יְהִ֣י כְ⁠מָלְכ֗⁠וֹ הִכָּה֙ אֶת־כָּל־בֵּ֣ית יָרָבְעָ֔ם לֹֽא־הִשְׁאִ֧יר כָּל־נְשָׁמָ֛ה לְ⁠יָרָבְעָ֖ם עַד־הִשְׁמִד֑⁠וֹ כִּ⁠דְבַ֣ר יְהוָ֔ה אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠יַד־עַבְדּ֖⁠וֹ אֲחִיָּ֥ה הַ⁠שִּׁילֹנִֽי׃","wa⁠yĕhi֣y kĕ⁠málĕk֗⁠wò hiká̇h֙ ʼeţ-ká̇l-bé֣̇yţ yárábĕʻá֔m lòֽʼ-hişĕ̌ʼi֧yr ká̇l-nĕşá̌má֛h lĕ⁠yárábĕʻá֖m ʻad-hişĕ̌mid֑⁠wò ki̇⁠dĕba֣r yĕhwá֔h ʼàşě֣r di̇bė֔r bĕ̇⁠yad-ʻabĕḋ֖⁠wò ʼàẖiyá֥̇h ha⁠şi̇̌ylòniֽy׃"],[15,30,"עַל־חַטֹּ֤אות יָרָבְעָם֙ אֲשֶׁ֣ר חָטָ֔א וַ⁠אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵ֑ל בְּ⁠כַעְס֕⁠וֹ אֲשֶׁ֣ר הִכְעִ֔יס אֶת־יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","ʻal-ẖatò֤̇ʼwţ yárábĕʻám֙ ʼàşě֣r ẖátá֔ʼ wa⁠ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼé֑l bĕ̇⁠kaʻĕs֕⁠wò ʼàşě֣r hikĕʻi֔ys ʼeţ-yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[15,31,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י נָדָ֖ב וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֛ţer di̇bĕré֥y nádá֖b wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[15,32,"וּ⁠מִלְחָמָ֨ה הָיְתָ֜ה בֵּ֣ין אָסָ֗א וּ⁠בֵ֛ין בַּעְשָׁ֥א מֶֽלֶךְ־יִשְׂרָאֵ֖ל כָּל־יְמֵי⁠הֶֽם׃פ","ẇ⁠milĕẖámá֨h háyĕţá֜h bé֣̇yn ʼásá֗ʼ ẇ⁠bé֛yn bȧʻĕşá֥̌ʼ meֽlekĕ-yişĕ̂ráʼé֖l ká̇l-yĕméy⁠heֽm׃p"],[15,33,"בִּ⁠שְׁנַ֣ת שָׁלֹ֔שׁ לְ⁠אָסָ֖א מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ בַּעְשָׁ֨א בֶן־אֲחִיָּ֤ה עַל־כָּל־יִשְׂרָאֵל֙ בְּ⁠תִרְצָ֔ה עֶשְׂרִ֥ים וְ⁠אַרְבַּ֖ע שָׁנָֽה׃","bi̇⁠şĕ̌na֣ţ şá̌lò֔ş̌ lĕ⁠ʼásá֖ʼ me֣lekĕ yĕhẇdá֑h má֠lakĕ bȧʻĕşá̌֨ʼ ben-ʼàẖiyá֤̇h ʻal-ká̇l-yişĕ̂ráʼél֙ bĕ̇⁠ţirĕẕá֔h ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbȧ֖ʻ şá̌náֽh׃"],[15,34,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יֵּ֨לֶךְ֙ בְּ⁠דֶ֣רֶךְ יָרָבְעָ֔ם וּ֨⁠בְ⁠חַטָּאת֔⁠וֹ אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃ס","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yé̇֨lekĕ֙ bĕ̇⁠de֣rekĕ yárábĕʻá֔m ẇ֨⁠bĕ⁠ẖatá̇ʼţ֔⁠wò ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃s"],[16,1,"וַ⁠יְהִ֤י דְבַר־יְהוָה֙ אֶל־יֵה֣וּא בֶן־חֲנָ֔נִי עַל־בַּעְשָׁ֖א לֵ⁠אמֹֽר׃","wa⁠yĕhi֤y dĕbar-yĕhwáh֙ ʼel-yéh֣ẇʼ ben-ẖàná֔niy ʻal-bȧʻĕşá֖̌ʼ lé⁠ʼmòֽr׃"],[16,2,"יַ֗עַן אֲשֶׁ֤ר הֲרִימֹתִ֨י⁠ךָ֙ מִן־הֶ֣⁠עָפָ֔ר וָ⁠אֶתֶּנְ⁠ךָ֣ נָגִ֔יד עַ֖ל עַמִּ֣⁠י יִשְׂרָאֵ֑ל וַ⁠תֵּ֣לֶךְ ׀ בְּ⁠דֶ֣רֶךְ יָרָבְעָ֗ם וַֽ⁠תַּחֲטִא֙ אֶת־עַמִּ֣⁠י יִשְׂרָאֵ֔ל לְ⁠הַכְעִיסֵ֖⁠נִי בְּ⁠חַטֹּאתָֽ⁠ם׃","ya֗ʻan ʼàşě֤r hàriymòţi֨y⁠ká֙ min-he֣⁠ʻápá֔r wá⁠ʼeţėnĕ⁠ká֣ nági֔yd ʻa֖l ʻami֣̇⁠y yişĕ̂ráʼé֑l wa⁠ţé֣̇lekĕ ׀ bĕ̇⁠de֣rekĕ yárábĕʻá֗m waֽ⁠ţȧẖàtiʼ֙ ʼeţ-ʻami֣̇⁠y yişĕ̂ráʼé֔l lĕ⁠hakĕʻiysé֖⁠niy bĕ̇⁠ẖatò̇ʼţáֽ⁠m׃"],[16,3,"הִנְ⁠נִ֥י מַבְעִ֛יר אַחֲרֵ֥י בַעְשָׁ֖א וְ⁠אַחֲרֵ֣י בֵית֑⁠וֹ וְ⁠נָֽתַתִּי֙ אֶת־בֵּ֣יתְ⁠ךָ֔ כְּ⁠בֵ֖ית יָרָבְעָ֥ם בֶּן־נְבָֽט׃","hinĕ⁠ni֥y mabĕʻi֛yr ʼaẖàré֥y baʻĕşá֖̌ʼ wĕ⁠ʼaẖàré֣y béyţ֑⁠wò wĕ⁠náֽţaţi̇y֙ ʼeţ-bé֣̇yţĕ⁠ká֔ kĕ̇⁠bé֖yţ yárábĕʻá֥m bėn-nĕbáֽt׃"],[16,4,"הַ⁠מֵּ֤ת לְ⁠בַעְשָׁא֙ בָּ⁠עִ֔יר יֹֽאכְל֖וּ הַ⁠כְּלָבִ֑ים וְ⁠הַ⁠מֵּ֥ת ל⁠וֹ֙ בַּ⁠שָּׂדֶ֔ה יֹאכְל֖וּ ע֥וֹף הַ⁠שָּׁמָֽיִם׃","ha⁠mé֤̇ţ lĕ⁠baʻĕşá̌ʼ֙ bá̇⁠ʻi֔yr yòֽʼkĕl֖ẇ ha⁠kĕ̇lábi֑ym wĕ⁠ha⁠mé֥̇ţ l⁠wò֙ bȧ⁠şá̇̂de֔h yòʼkĕl֖ẇ ʻ֥wòp ha⁠şá̇̌máֽyim׃"],[16,5,"וְ⁠יֶ֨תֶר דִּבְרֵ֥י בַעְשָׁ֛א וַ⁠אֲשֶׁ֥ר עָשָׂ֖ה וּ⁠גְבֽוּרָת֑⁠וֹ הֲ⁠לֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer di̇bĕré֥y baʻĕşá֛̌ʼ wa⁠ʼàşě֥r ʻáşá֖̂h ẇ⁠gĕbֽẇráţ֑⁠wò hà⁠lòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[16,6,"וַ⁠יִּשְׁכַּ֤ב בַּעְשָׁא֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵ֖ר בְּ⁠תִרְצָ֑ה וַ⁠יִּמְלֹ֛ךְ אֵלָ֥ה בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","wa⁠yi̇şĕ̌kȧ֤b bȧʻĕşá̌ʼ֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bé֖r bĕ̇⁠ţirĕẕá֑h wa⁠yi̇mĕlò֛kĕ ʼélá֥h bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[16,7,"וְ⁠גַ֡ם בְּ⁠יַד־יֵה֨וּא בֶן־חֲנָ֜נִי הַ⁠נָּבִ֗יא דְּבַר־יְהוָ֡ה הָיָה֩ אֶל־בַּעְשָׁ֨א וְ⁠אֶל־בֵּית֜⁠וֹ וְ⁠עַ֥ל כָּל־הָ⁠רָעָ֣ה ׀ אֲשֶׁר־עָשָׂ֣ה ׀ בְּ⁠עֵינֵ֣י יְהוָ֗ה לְ⁠הַכְעִיס⁠וֹ֙ בְּ⁠מַעֲשֵׂ֣ה יָדָ֔י⁠ו לִ⁠הְי֖וֹת כְּ⁠בֵ֣ית יָרָבְעָ֑ם וְ⁠עַ֥ל אֲשֶׁר־הִכָּ֖ה אֹתֽ⁠וֹ׃פ","wĕ⁠ga֡m bĕ̇⁠yad-yéh֨ẇʼ ben-ẖàná֜niy ha⁠ná̇bi֗yʼ dĕ̇bar-yĕhwá֡h háyáh֩ ʼel-bȧʻĕşá̌֨ʼ wĕ⁠ʼel-bé̇yţ֜⁠wò wĕ⁠ʻa֥l ká̇l-há⁠ráʻá֣h ׀ ʼàşěr-ʻáşá֣̂h ׀ bĕ̇⁠ʻéyné֣y yĕhwá֗h lĕ⁠hakĕʻiys⁠wò֙ bĕ̇⁠maʻàşé֣̂h yádá֔y⁠w li⁠hĕy֖wòţ kĕ̇⁠bé֣yţ yárábĕʻá֑m wĕ⁠ʻa֥l ʼàşěr-hiká֖̇h ʼòţֽ⁠wò׃p"],[16,8,"בִּ⁠שְׁנַ֨ת עֶשְׂרִ֤ים וָ⁠שֵׁשׁ֙ שָׁנָ֔ה לְ⁠אָסָ֖א מֶ֣לֶךְ יְהוּדָ֑ה מָ֠לַךְ אֵלָ֨ה בֶן־בַּעְשָׁ֧א עַל־יִשְׂרָאֵ֛ל בְּ⁠תִרְצָ֖ה שְׁנָתָֽיִם׃","bi̇⁠şĕ̌na֨ţ ʻeşĕ̂ri֤ym wá⁠şé̌ş̌֙ şá̌ná֔h lĕ⁠ʼásá֖ʼ me֣lekĕ yĕhẇdá֑h má֠lakĕ ʼélá֨h ben-bȧʻĕşá֧̌ʼ ʻal-yişĕ̂ráʼé֛l bĕ̇⁠ţirĕẕá֖h şĕ̌náţáֽyim׃"],[16,9,"וַ⁠יִּקְשֹׁ֤ר עָלָי⁠ו֙ עַבְדּ֣⁠וֹ זִמְרִ֔י שַׂ֖ר מַחֲצִ֣ית הָ⁠רָ֑כֶב וְ⁠ה֤וּא בְ⁠תִרְצָה֙ שֹׁתֶ֣ה שִׁכּ֔וֹר בֵּ֣ית אַרְצָ֔א אֲשֶׁ֥ר עַל־הַ⁠בַּ֖יִת בְּ⁠תִרְצָֽה׃","wa⁠yi̇qĕşò֤̌r ʻáláy⁠w֙ ʻabĕḋ֣⁠wò zimĕri֔y şâ֖r maẖàẕi֣yţ há⁠rá֑keb wĕ⁠h֤ẇʼ bĕ⁠ţirĕẕáh֙ şò̌ţe֣h şǐk̇֔wòr bé֣̇yţ ʼarĕẕá֔ʼ ʼàşě֥r ʻal-ha⁠bȧ֖yiţ bĕ̇⁠ţirĕẕáֽh׃"],[16,10,"וַ⁠יָּבֹ֤א זִמְרִי֙ וַ⁠יַּכֵּ֣⁠הוּ וַ⁠יְמִיתֵ֔⁠הוּ בִּ⁠שְׁנַת֙ עֶשְׂרִ֣ים וָ⁠שֶׁ֔בַע לְ⁠אָסָ֖א מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠יִּמְלֹ֖ךְ תַּחְתָּֽי⁠ו׃","wa⁠yá̇bò֤ʼ zimĕriy֙ wa⁠yȧké֣̇⁠hẇ wa⁠yĕmiyţé֔⁠hẇ bi̇⁠şĕ̌naţ֙ ʻeşĕ̂ri֣ym wá⁠şě֔baʻ lĕ⁠ʼásá֖ʼ me֣lekĕ yĕhẇdá֑h wa⁠yi̇mĕlò֖kĕ ţȧẖĕţáֽ̇y⁠w׃"],[16,11,"וַ⁠יְהִ֨י בְ⁠מָלְכ֜⁠וֹ כְּ⁠שִׁבְתּ֣⁠וֹ עַל־כִּסְא֗⁠וֹ הִכָּה֙ אֶת־כָּל־בֵּ֣ית בַּעְשָׁ֔א לֹֽא־הִשְׁאִ֥יר ל֖⁠וֹ מַשְׁתִּ֣ין בְּ⁠קִ֑יר וְ⁠גֹאֲלָ֖י⁠ו וְ⁠רֵעֵֽ⁠הוּ׃","wa⁠yĕhi֨y bĕ⁠málĕk֜⁠wò kĕ̇⁠şǐbĕţ֣̇⁠wò ʻal-ki̇sĕʼ֗⁠wò hiká̇h֙ ʼeţ-ká̇l-bé֣̇yţ bȧʻĕşá̌֔ʼ lòֽʼ-hişĕ̌ʼi֥yr l֖⁠wò maşĕ̌ţi֣̇yn bĕ̇⁠qi֑yr wĕ⁠gòʼàlá֖y⁠w wĕ⁠réʻéֽ⁠hẇ׃"],[16,12,"וַ⁠יַּשְׁמֵ֣ד זִמְרִ֔י אֵ֖ת כָּל־בֵּ֣ית בַּעְשָׁ֑א כִּ⁠דְבַ֤ר יְהוָה֙ אֲשֶׁ֣ר דִּבֶּ֣ר אֶל־בַּעְשָׁ֔א בְּ⁠יַ֖ד יֵה֥וּא הַ⁠נָּבִֽיא׃","wa⁠yȧşĕ̌mé֣d zimĕri֔y ʼé֖ţ ká̇l-bé֣̇yţ bȧʻĕşá֑̌ʼ ki̇⁠dĕba֤r yĕhwáh֙ ʼàşě֣r di̇bė֣r ʼel-bȧʻĕşá̌֔ʼ bĕ̇⁠ya֖d yéh֥ẇʼ ha⁠ná̇biֽyʼ׃"],[16,13,"אֶ֚ל כָּל־חַטֹּ֣אות בַּעְשָׁ֔א וְ⁠חַטֹּ֖אות אֵלָ֣ה בְנ֑⁠וֹ אֲשֶׁ֣ר חָטְא֗וּ וַ⁠אֲשֶׁ֤ר הֶחֱטִ֨יאוּ֙ אֶת־יִשְׂרָאֵ֔ל לְ⁠הַכְעִ֗יס אֶת־יְהוָ֛ה אֱלֹהֵ֥י יִשְׂרָאֵ֖ל בְּ⁠הַבְלֵי⁠הֶֽם׃","ʼe֚l ká̇l-ẖatò֣̇ʼwţ bȧʻĕşá̌֔ʼ wĕ⁠ẖatò֖̇ʼwţ ʼélá֣h bĕn֑⁠wò ʼàşě֣r ẖátĕʼ֗ẇ wa⁠ʼàşě֤r heẖèti֨yʼẇ֙ ʼeţ-yişĕ̂ráʼé֔l lĕ⁠hakĕʻi֗ys ʼeţ-yĕhwá֛h ʼèlòhé֥y yişĕ̂ráʼé֖l bĕ̇⁠habĕléy⁠heֽm׃"],[16,14,"וְ⁠יֶ֛תֶר דִּבְרֵ֥י אֵלָ֖ה וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֽוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃פ","wĕ⁠ye֛ţer di̇bĕré֥y ʼélá֖h wĕ⁠kál-ʼàşě֣r ʻáşá֑̂h hà⁠lֽwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃p"],[16,15,"בִּ⁠שְׁנַת֩ עֶשְׂרִ֨ים וָ⁠שֶׁ֜בַע שָׁנָ֗ה לְ⁠אָסָא֙ מֶ֣לֶךְ יְהוּדָ֔ה מָלַ֥ךְ זִמְרִ֛י שִׁבְעַ֥ת יָמִ֖ים בְּ⁠תִרְצָ֑ה וְ⁠הָ⁠עָ֣ם חֹנִ֔ים עַֽל־גִּבְּת֖וֹן אֲשֶׁ֥ר לַ⁠פְּלִשְׁתִּֽים׃","bi̇⁠şĕ̌naţ֩ ʻeşĕ̂ri֨ym wá⁠şě֜baʻ şá̌ná֗h lĕ⁠ʼásáʼ֙ me֣lekĕ yĕhẇdá֔h mála֥kĕ zimĕri֛y şǐbĕʻa֥ţ yámi֖ym bĕ̇⁠ţirĕẕá֑h wĕ⁠há⁠ʻá֣m ẖòni֔ym ʻaֽl-gi̇bĕ̇ţ֖wòn ʼàşě֥r la⁠pĕ̇lişĕ̌ţiֽ̇ym׃"],[16,16,"וַ⁠יִּשְׁמַ֤ע הָ⁠עָם֙ הַ⁠חֹנִ֣ים לֵ⁠אמֹ֔ר קָשַׁ֣ר זִמְרִ֔י וְ⁠גַ֖ם הִכָּ֣ה אֶת־הַ⁠מֶּ֑לֶךְ וַ⁠יַּמְלִ֣כוּ כָֽל־יִ֠שְׂרָאֵל אֶת־עָמְרִ֨י שַׂר־צָבָ֧א עַל־יִשְׂרָאֵ֛ל בַּ⁠יּ֥וֹם הַ⁠ה֖וּא בַּֽ⁠מַּחֲנֶֽה׃","wa⁠yi̇şĕ̌ma֤ʻ há⁠ʻám֙ ha⁠ẖòni֣ym lé⁠ʼmò֔r qáşǎ֣r zimĕri֔y wĕ⁠ga֖m hiká֣̇h ʼeţ-ha⁠mė֑lekĕ wa⁠yȧmĕli֣kẇ káֽl-yi֠şĕ̂ráʼél ʼeţ-ʻámĕri֨y şâr-ẕábá֧ʼ ʻal-yişĕ̂ráʼé֛l bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ bȧֽ⁠mȧẖàneֽh׃"],[16,17,"וַ⁠יַּעֲלֶ֥ה עָמְרִ֛י וְ⁠כָל־יִשְׂרָאֵ֥ל עִמּ֖⁠וֹ מִֽ⁠גִּבְּת֑וֹן וַ⁠יָּצֻ֖רוּ עַל־תִּרְצָֽה׃","wa⁠yȧʻàle֥h ʻámĕri֛y wĕ⁠kál-yişĕ̂ráʼé֥l ʻiṁ֖⁠wò miֽ⁠gi̇bĕ̇ţ֑wòn wa⁠yá̇ẕu֖rẇ ʻal-ţi̇rĕẕáֽh׃"],[16,18,"וַ⁠יְהִ֞י כִּ⁠רְא֤וֹת זִמְרִי֙ כִּֽי־נִלְכְּדָ֣ה הָ⁠עִ֔יר וַ⁠יָּבֹ֖א אֶל־אַרְמ֣וֹן בֵּית־הַ⁠מֶּ֑לֶךְ וַ⁠יִּשְׂרֹ֨ף עָלָ֧י⁠ו אֶת־בֵּֽית־מֶ֛לֶךְ בָּ⁠אֵ֖שׁ וַ⁠יָּמֹֽת׃","wa⁠yĕhi֞y ki̇⁠rĕʼ֤wòţ zimĕriy֙ kiֽ̇y-nilĕkĕ̇dá֣h há⁠ʻi֔yr wa⁠yá̇bò֖ʼ ʼel-ʼarĕm֣wòn bé̇yţ-ha⁠mė֑lekĕ wa⁠yi̇şĕ̂rò֨p ʻálá֧y⁠w ʼeţ-béֽ̇yţ-me֛lekĕ bá̇⁠ʼé֖ş̌ wa⁠yá̇mòֽţ׃"],[16,19,"עַל־חטאת⁠ו אֲשֶׁ֣ר חָטָ֔א לַ⁠עֲשׂ֥וֹת הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה לָ⁠לֶ֨כֶת֙ בְּ⁠דֶ֣רֶךְ יָרָבְעָ֔ם וּ⁠בְ⁠חַטָּאת⁠וֹ֙ אֲשֶׁ֣ר עָשָׂ֔ה לְ⁠הַחֲטִ֖יא אֶת־יִשְׂרָאֵֽל׃","ʻal-ẖtʼţ⁠w ʼàşě֣r ẖátá֔ʼ la⁠ʻàş֥̂wòţ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h lá⁠le֨keţ֙ bĕ̇⁠de֣rekĕ yárábĕʻá֔m ẇ⁠bĕ⁠ẖatá̇ʼţ⁠wò֙ ʼàşě֣r ʻáşá̂֔h lĕ⁠haẖàti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[16,20,"וְ⁠יֶ֨תֶר֙ דִּבְרֵ֣י זִמְרִ֔י וְ⁠קִשְׁר֖⁠וֹ אֲשֶׁ֣ר קָשָׁ֑ר הֲ⁠לֹֽא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃פ","wĕ⁠ye֨ţer֙ di̇bĕré֣y zimĕri֔y wĕ⁠qişĕ̌r֖⁠wò ʼàşě֣r qáşá֑̌r hà⁠lòֽʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃p"],[16,21,"אָ֧ז יֵחָלֵ֛ק הָ⁠עָ֥ם יִשְׂרָאֵ֖ל לַ⁠חֵ֑צִי חֲצִ֨י הָ⁠עָ֜ם הָ֠יָה אַחֲרֵ֨י תִבְנִ֤י בֶן־גִּינַת֙ לְ⁠הַמְלִיכ֔⁠וֹ וְ⁠הַ⁠חֲצִ֖י אַחֲרֵ֥י עָמְרִֽי׃","ʼá֧z yéẖálé֛q há⁠ʻá֥m yişĕ̂ráʼé֖l la⁠ẖé֑ẕiy ẖàẕi֨y há⁠ʻá֜m há֠yáh ʼaẖàré֨y ţibĕni֤y ben-gi̇ynaţ֙ lĕ⁠hamĕliyk֔⁠wò wĕ⁠ha⁠ẖàẕi֖y ʼaẖàré֥y ʻámĕriֽy׃"],[16,22,"וַ⁠יֶּחֱזַ֤ק הָ⁠עָם֙ אֲשֶׁ֣ר אַחֲרֵ֣י עָמְרִ֔י אֶת־הָ⁠עָ֕ם אֲשֶׁ֥ר אַחֲרֵ֖י תִּבְנִ֣י בֶן־גִּינַ֑ת וַ⁠יָּ֣מָת תִּבְנִ֔י וַ⁠יִּמְלֹ֖ךְ עָמְרִֽי׃פ","wa⁠yėẖèza֤q há⁠ʻám֙ ʼàşě֣r ʼaẖàré֣y ʻámĕri֔y ʼeţ-há⁠ʻá֕m ʼàşě֥r ʼaẖàré֖y ţi̇bĕni֣y ben-gi̇yna֑ţ wa⁠yá֣̇máţ ţi̇bĕni֔y wa⁠yi̇mĕlò֖kĕ ʻámĕriֽy׃p"],[16,23,"בִּ⁠שְׁנַת֩ שְׁלֹשִׁ֨ים וְ⁠אַחַ֜ת שָׁנָ֗ה לְ⁠אָסָא֙ מֶ֣לֶךְ יְהוּדָ֔ה מָלַ֤ךְ עָמְרִי֙ עַל־יִשְׂרָאֵ֔ל שְׁתֵּ֥ים עֶשְׂרֵ֖ה שָׁנָ֑ה בְּ⁠תִרְצָ֖ה מָלַ֥ךְ שֵׁשׁ־שָׁנִֽים׃","bi̇⁠şĕ̌naţ֩ şĕ̌lòşǐ֨ym wĕ⁠ʼaẖa֜ţ şá̌ná֗h lĕ⁠ʼásáʼ֙ me֣lekĕ yĕhẇdá֔h mála֤kĕ ʻámĕriy֙ ʻal-yişĕ̂ráʼé֔l şĕ̌ţé֥̇ym ʻeşĕ̂ré֖h şá̌ná֑h bĕ̇⁠ţirĕẕá֖h mála֥kĕ şé̌ş̌-şá̌niֽym׃"],[16,24,"וַ⁠יִּ֜קֶן אֶת־הָ⁠הָ֥ר שֹׁמְר֛וֹן מֵ֥⁠אֶת שֶׁ֖מֶר בְּ⁠כִכְּרַ֣יִם כָּ֑סֶף וַ⁠יִּ֨בֶן֙ אֶת־הָ⁠הָ֔ר וַ⁠יִּקְרָ֗א אֶת־שֵׁ֤ם הָ⁠עִיר֙ אֲשֶׁ֣ר בָּנָ֔ה עַ֣ל שֶׁם־שֶׁ֔מֶר אֲדֹנֵ֖י הָ⁠הָ֥ר שֹׁמְרֽוֹן׃","wa⁠yi̇֜qen ʼeţ-há⁠há֥r şò̌mĕr֛wòn mé֥⁠ʼeţ şě֖mer bĕ̇⁠kikĕ̇ra֣yim ká֑̇sep wa⁠yi̇֨ben֙ ʼeţ-há⁠há֔r wa⁠yi̇qĕrá֗ʼ ʼeţ-şé֤̌m há⁠ʻiyr֙ ʼàşě֣r bá̇ná֔h ʻa֣l şěm-şě֔mer ʼàdòné֖y há⁠há֥r şò̌mĕrֽwòn׃"],[16,25,"וַ⁠יַּעֲשֶׂ֥ה עָמְרִ֛י הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יָּ֕רַע מִ⁠כֹּ֖ל אֲשֶׁ֥ר לְ⁠פָנָֽי⁠ו׃","wa⁠yȧʻàşê֥h ʻámĕri֛y há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yá̇֕raʻ mi⁠kò֖̇l ʼàşě֥r lĕ⁠pánáֽy⁠w׃"],[16,26,"וַ⁠יֵּ֗לֶךְ בְּ⁠כָל־דֶּ֨רֶךְ֙ יָרָבְעָ֣ם בֶּן־נְבָ֔ט ו⁠ב⁠חטאתי⁠ו אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵ֑ל לְ⁠הַכְעִ֗יס אֶת־יְהוָ֛ה אֱלֹהֵ֥י יִשְׂרָאֵ֖ל בְּ⁠הַבְלֵי⁠הֶֽם׃","wa⁠yé̇֗lekĕ bĕ̇⁠kál-dė֨rekĕ֙ yárábĕʻá֣m bėn-nĕbá֔t w⁠b⁠ẖtʼţy⁠w ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼé֑l lĕ⁠hakĕʻi֗ys ʼeţ-yĕhwá֛h ʼèlòhé֥y yişĕ̂ráʼé֖l bĕ̇⁠habĕléy⁠heֽm׃"],[16,27,"וְ⁠יֶ֨תֶר דִּבְרֵ֤י עָמְרִי֙ אֲשֶׁ֣ר עָשָׂ֔ה וּ⁠גְבוּרָת֖⁠וֹ אֲשֶׁ֣ר עָשָׂ֑ה הֲ⁠לֹֽא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ye֨ţer di̇bĕré֤y ʻámĕriy֙ ʼàşě֣r ʻáşá̂֔h ẇ⁠gĕbẇráţ֖⁠wò ʼàşě֣r ʻáşá֑̂h hà⁠lòֽʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[16,28,"וַ⁠יִּשְׁכַּ֤ב עָמְרִי֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵ֖ר בְּ⁠שֹׁמְר֑וֹן וַ⁠יִּמְלֹ֛ךְ אַחְאָ֥ב בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֤b ʻámĕriy֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bé֖r bĕ̇⁠şò̌mĕr֑wòn wa⁠yi̇mĕlò֛kĕ ʼaẖĕʼá֥b bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[16,29,"וְ⁠אַחְאָ֣ב בֶּן־עָמְרִ֗י מָלַךְ֙ עַל־יִשְׂרָאֵ֔ל בִּ⁠שְׁנַ֨ת שְׁלֹשִׁ֤ים וּ⁠שְׁמֹנֶה֙ שָׁנָ֔ה לְ⁠אָסָ֖א מֶ֣לֶךְ יְהוּדָ֑ה וַ֠⁠יִּמְלֹךְ אַחְאָ֨ב בֶּן־עָמְרִ֤י עַל־יִשְׂרָאֵל֙ בְּ⁠שֹׁ֣מְר֔וֹן עֶשְׂרִ֥ים וּ⁠שְׁתַּ֖יִם שָׁנָֽה׃","wĕ⁠ʼaẖĕʼá֣b bėn-ʻámĕri֗y málakĕ֙ ʻal-yişĕ̂ráʼé֔l bi̇⁠şĕ̌na֨ţ şĕ̌lòşǐ֤ym ẇ⁠şĕ̌mòneh֙ şá̌ná֔h lĕ⁠ʼásá֖ʼ me֣lekĕ yĕhẇdá֑h wa֠⁠yi̇mĕlòkĕ ʼaẖĕʼá֨b bėn-ʻámĕri֤y ʻal-yişĕ̂ráʼél֙ bĕ̇⁠şò֣̌mĕr֔wòn ʻeşĕ̂ri֥ym ẇ⁠şĕ̌ţȧ֖yim şá̌náֽh׃"],[16,30,"וַ⁠יַּ֨עַשׂ אַחְאָ֧ב בֶּן־עָמְרִ֛י הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה מִ⁠כֹּ֖ל אֲשֶׁ֥ר לְ⁠פָנָֽי⁠ו׃","wa⁠yȧ֨ʻaş̂ ʼaẖĕʼá֧b bėn-ʻámĕri֛y há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h mi⁠kò֖̇l ʼàşě֥r lĕ⁠pánáֽy⁠w׃"],[16,31,"וַ⁠יְהִי֙ הֲ⁠נָקֵ֣ל לֶכְתּ֔⁠וֹ בְּ⁠חַטֹּ֖אות יָרָבְעָ֣ם בֶּן־נְבָ֑ט וַ⁠יִּקַּ֨ח אִשָּׁ֜ה אֶת־אִיזֶ֗בֶל בַּת־אֶתְבַּ֨עַל֙ מֶ֣לֶךְ צִידֹנִ֔ים וַ⁠יֵּ֨לֶךְ֙ וַֽ⁠יַּעֲבֹ֣ד אֶת־הַ⁠בַּ֔עַל וַ⁠יִּשְׁתַּ֖חוּ לֽ⁠וֹ׃","wa⁠yĕhiy֙ hà⁠náqé֣l lekĕţ̇֔⁠wò bĕ̇⁠ẖatò֖̇ʼwţ yárábĕʻá֣m bėn-nĕbá֑t wa⁠yi̇qȧ֨ẖ ʼişá̇̌֜h ʼeţ-ʼiyze֗bel bȧţ-ʼeţĕbȧ֨ʻal֙ me֣lekĕ ẕiydòni֔ym wa⁠yé̇֨lekĕ֙ waֽ⁠yȧʻàbò֣d ʼeţ-ha⁠bȧ֔ʻal wa⁠yi̇şĕ̌ţȧ֖ẖẇ lֽ⁠wò׃"],[16,32,"וַ⁠יָּ֥קֶם מִזְבֵּ֖חַ לַ⁠בָּ֑עַל בֵּ֣ית הַ⁠בַּ֔עַל אֲשֶׁ֥ר בָּנָ֖ה בְּ⁠שֹׁמְרֽוֹן׃","wa⁠yá֥̇qem mizĕbé֖̇ẖa la⁠bá֑̇ʻal bé֣̇yţ ha⁠bȧ֔ʻal ʼàşě֥r bá̇ná֖h bĕ̇⁠şò̌mĕrֽwòn׃"],[16,33,"וַ⁠יַּ֥עַשׂ אַחְאָ֖ב אֶת־הָ⁠אֲשֵׁרָ֑ה וַ⁠יּ֨וֹסֶף אַחְאָ֜ב לַ⁠עֲשׂ֗וֹת לְ⁠הַכְעִיס֙ אֶת־יְהֹוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל מִ⁠כֹּ֨ל מַלְכֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֥ר הָי֖וּ לְ⁠פָנָֽי⁠ו׃","wa⁠yȧ֥ʻaş̂ ʼaẖĕʼá֖b ʼeţ-há⁠ʼàşé̌rá֑h wa⁠ẏ֨wòsep ʼaẖĕʼá֜b la⁠ʻàş̂֗wòţ lĕ⁠hakĕʻiys֙ ʼeţ-yĕhòwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l mi⁠kò̇֨l malĕké֣y yişĕ̂ráʼé֔l ʼàşě֥r háy֖ẇ lĕ⁠pánáֽy⁠w׃"],[16,34,"בְּ⁠יָמָ֞י⁠ו בָּנָ֥ה חִיאֵ֛ל בֵּ֥ית הָאֱלִ֖י אֶת־יְרִיחֹ֑ה בַּ⁠אֲבִירָ֨ם בְּכֹר֜⁠וֹ יִסְּדָ֗⁠הּ ו⁠ב⁠שגיב צְעִיר⁠וֹ֙ הִצִּ֣יב דְּלָתֶ֔י⁠הָ כִּ⁠דְבַ֣ר יְהוָ֔ה אֲשֶׁ֣ר דִּבֶּ֔ר בְּ⁠יַ֖ד יְהוֹשֻׁ֥עַ בִּן־נֽוּן׃ס","bĕ̇⁠yámá֞y⁠w bá̇ná֥h ẖiyʼé֛l bé֥̇yţ háʼèli֖y ʼeţ-yĕriyẖò֑h bȧ⁠ʼàbiyrá֨m bĕ̇kòr֜⁠wò yisĕ̇dá֗⁠ḣ w⁠b⁠şgyb ẕĕʻiyr⁠wò֙ hiẕi֣̇yb dĕ̇láţe֔y⁠há ki̇⁠dĕba֣r yĕhwá֔h ʼàşě֣r di̇bė֔r bĕ̇⁠ya֖d yĕhwòşǔ֥ʻa bi̇n-nֽẇn׃s"],[17,1,"וַ⁠יֹּאמֶר֩ אֵלִיָּ֨הוּ הַ⁠תִּשְׁבִּ֜י מִ⁠תֹּשָׁבֵ֣י גִלְעָד֮ אֶל־אַחְאָב֒ חַי־יְהוָ֞ה אֱלֹהֵ֤י יִשְׂרָאֵל֙ אֲשֶׁ֣ר עָמַ֣דְתִּי לְ⁠פָנָ֔י⁠ו אִם־יִהְיֶ֛ה הַ⁠שָּׁנִ֥ים הָ⁠אֵ֖לֶּה טַ֣ל וּ⁠מָטָ֑ר כִּ֖י אִם־לְ⁠פִ֥י דְבָרִֽ⁠י׃ס","wa⁠yò̇ʼmer֩ ʼéliyá̇֨hẇ ha⁠ţi̇şĕ̌bi̇֜y mi⁠ţò̇şá̌bé֣y gilĕʻád֮ ʼel-ʼaẖĕʼáb֒ ẖay-yĕhwá֞h ʼèlòhé֤y yişĕ̂ráʼél֙ ʼàşě֣r ʻáma֣dĕţi̇y lĕ⁠páná֔y⁠w ʼim-yihĕye֛h ha⁠şá̇̌ni֥ym há⁠ʼé֖lėh ta֣l ẇ⁠mátá֑r ki֖̇y ʼim-lĕ⁠pi֥y dĕbáriֽ⁠y׃s"],[17,2,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלָ֥י⁠ו לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼélá֥y⁠w lé⁠ʼmòֽr׃"],[17,3,"לֵ֣ךְ מִ⁠זֶּ֔ה וּ⁠פָנִ֥יתָ לְּ⁠ךָ֖ קֵ֑דְמָ⁠ה וְ⁠נִסְתַּרְתָּ֙ בְּ⁠נַ֣חַל כְּרִ֔ית אֲשֶׁ֖ר עַל־פְּנֵ֥י הַ⁠יַּרְדֵּֽן׃","lé֣kĕ mi⁠zė֔h ẇ⁠páni֥yţá lĕ̇⁠ká֖ qé֑dĕmá⁠h wĕ⁠nisĕţȧrĕţá̇֙ bĕ̇⁠na֣ẖal kĕ̇ri֔yţ ʼàşě֖r ʻal-pĕ̇né֥y ha⁠yȧrĕdéֽ̇n׃"],[17,4,"וְ⁠הָיָ֖ה מֵ⁠הַ⁠נַּ֣חַל תִּשְׁתֶּ֑ה וְ⁠אֶת־הָ⁠עֹרְבִ֣ים צִוִּ֔יתִי לְ⁠כַלְכֶּלְ⁠ךָ֖ שָֽׁם׃","wĕ⁠háyá֖h mé⁠ha⁠nȧ֣ẖal ţi̇şĕ̌ţė֑h wĕ⁠ʼeţ-há⁠ʻòrĕbi֣ym ẕiwi̇֔yţiy lĕ⁠kalĕkėlĕ⁠ká֖ şáֽ̌m׃"],[17,5,"וַ⁠יֵּ֥לֶךְ וַ⁠יַּ֖עַשׂ כִּ⁠דְבַ֣ר יְהוָ֑ה וַ⁠יֵּ֗לֶךְ וַ⁠יֵּ֨שֶׁב֙ בְּ⁠נַ֣חַל כְּרִ֔ית אֲשֶׁ֖ר עַל־פְּנֵ֥י הַ⁠יַּרְדֵּֽן׃","wa⁠yé֥̇lekĕ wa⁠yȧ֖ʻaş̂ ki̇⁠dĕba֣r yĕhwá֑h wa⁠yé̇֗lekĕ wa⁠yé̇֨şěb֙ bĕ̇⁠na֣ẖal kĕ̇ri֔yţ ʼàşě֖r ʻal-pĕ̇né֥y ha⁠yȧrĕdéֽ̇n׃"],[17,6,"וְ⁠הָ⁠עֹרְבִ֗ים מְבִיאִ֨ים ל֜⁠וֹ לֶ֤חֶם וּ⁠בָשָׂר֙ בַּ⁠בֹּ֔קֶר וְ⁠לֶ֥חֶם וּ⁠בָשָׂ֖ר בָּ⁠עָ֑רֶב וּ⁠מִן־הַ⁠נַּ֖חַל יִשְׁתֶּֽה׃","wĕ⁠há⁠ʻòrĕbi֗ym mĕbiyʼi֨ym l֜⁠wò le֤ẖem ẇ⁠báşá̂r֙ bȧ⁠bò̇֔qer wĕ⁠le֥ẖem ẇ⁠báşá֖̂r bá̇⁠ʻá֑reb ẇ⁠min-ha⁠nȧ֖ẖal yişĕ̌ţėֽh׃"],[17,7,"וַ⁠יְהִ֛י מִ⁠קֵּ֥ץ יָמִ֖ים וַ⁠יִּיבַ֣שׁ הַ⁠נָּ֑חַל כִּ֛י לֹֽא־הָיָ֥ה גֶ֖שֶׁם בָּ⁠אָֽרֶץ׃ס","wa⁠yĕhi֛y mi⁠qé֥̇ẕ yámi֖ym wa⁠yi̇yba֣ş̌ ha⁠ná֑̇ẖal ki֛̇y lòֽʼ-háyá֥h ge֖şěm bá̇⁠ʼáֽreẕ׃s"],[17,8,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלָ֥י⁠ו לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼélá֥y⁠w lé⁠ʼmòֽr׃"],[17,9,"ק֣וּם לֵ֤ךְ צָרְפַ֨תָ⁠ה֙ אֲשֶׁ֣ר לְ⁠צִיד֔וֹן וְ⁠יָשַׁבְתָּ֖ שָׁ֑ם הִנֵּ֨ה צִוִּ֥יתִי שָׁ֛ם אִשָּׁ֥ה אַלְמָנָ֖ה לְ⁠כַלְכְּלֶֽ⁠ךָ׃","q֣ẇm lé֤kĕ ẕárĕpa֨ţá⁠h֙ ʼàşě֣r lĕ⁠ẕiyd֔wòn wĕ⁠yáşǎbĕţá֖̇ şá֑̌m hiné̇֨h ẕiwi֥̇yţiy şá֛̌m ʼişá֥̇̌h ʼalĕmáná֖h lĕ⁠kalĕkĕ̇leֽ⁠ká׃"],[17,10,"וַ⁠יָּ֣קָם ׀ וַ⁠יֵּ֣לֶךְ צָרְפַ֗תָ⁠ה וַ⁠יָּבֹא֙ אֶל־פֶּ֣תַח הָ⁠עִ֔יר וְ⁠הִנֵּֽה־שָׁ֛ם אִשָּׁ֥ה אַלְמָנָ֖ה מְקֹשֶׁ֣שֶׁת עֵצִ֑ים וַ⁠יִּקְרָ֤א אֵלֶ֨י⁠הָ֙ וַ⁠יֹּאמַ֔ר קְחִי־נָ֨א לִ֧⁠י מְעַט־מַ֛יִם בַּ⁠כְּלִ֖י וְ⁠אֶשְׁתֶּֽה׃","wa⁠yá֣̇qám ׀ wa⁠yé֣̇lekĕ ẕárĕpa֗ţá⁠h wa⁠yá̇bòʼ֙ ʼel-pė֣ţaẖ há⁠ʻi֔yr wĕ⁠hinéֽ̇h-şá֛̌m ʼişá֥̇̌h ʼalĕmáná֖h mĕqòşě֣şěţ ʻéẕi֑ym wa⁠yi̇qĕrá֤ʼ ʼéle֨y⁠há֙ wa⁠yò̇ʼma֔r qĕẖiy-ná֨ʼ li֧⁠y mĕʻat-ma֛yim bȧ⁠kĕ̇li֖y wĕ⁠ʼeşĕ̌ţėֽh׃"],[17,11,"וַ⁠תֵּ֖לֶךְ לָ⁠קַ֑חַת וַ⁠יִּקְרָ֤א אֵלֶ֨י⁠הָ֙ וַ⁠יֹּאמַ֔ר לִֽקְחִי־נָ֥א לִ֛⁠י פַּת־לֶ֖חֶם בְּ⁠יָדֵֽ⁠ךְ׃","wa⁠ţé֖̇lekĕ lá⁠qa֑ẖaţ wa⁠yi̇qĕrá֤ʼ ʼéle֨y⁠há֙ wa⁠yò̇ʼma֔r liֽqĕẖiy-ná֥ʼ li֛⁠y pȧţ-le֖ẖem bĕ̇⁠yádéֽ⁠kĕ׃"],[17,12,"וַ⁠תֹּ֗אמֶר חַי־יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ אִם־יֶשׁ־לִ֣⁠י מָע֔וֹג כִּ֣י אִם־מְלֹ֤א כַף־קֶ֨מַח֙ בַּ⁠כַּ֔ד וּ⁠מְעַט־שֶׁ֖מֶן בַּ⁠צַּפָּ֑חַת וְ⁠הִנְ⁠נִ֨י מְקֹשֶׁ֜שֶׁת שְׁנַ֣יִם עֵצִ֗ים וּ⁠בָ֨אתִי֙ וַ⁠עֲשִׂיתִ֨י⁠הוּ֙ לִ֣⁠י וְ⁠לִ⁠בְנִ֔⁠י וַ⁠אֲכַלְנֻ֖⁠הוּ וָ⁠מָֽתְנוּ׃","wa⁠ţò̇֗ʼmer ẖay-yĕhwá֤h ʼèlòhe֨y⁠ká֙ ʼim-yeş̌-li֣⁠y máʻ֔wòg ki֣̇y ʼim-mĕlò֤ʼ kap-qe֨maẖ֙ bȧ⁠kȧ֔d ẇ⁠mĕʻat-şě֖men bȧ⁠ẕȧpá֑̇ẖaţ wĕ⁠hinĕ⁠ni֨y mĕqòşě֜şěţ şĕ̌na֣yim ʻéẕi֗ym ẇ⁠bá֨ʼţiy֙ wa⁠ʻàşîyţi֨y⁠hẇ֙ li֣⁠y wĕ⁠li⁠bĕni֔⁠y wa⁠ʼàkalĕnu֖⁠hẇ wá⁠máֽţĕnẇ׃"],[17,13,"וַ⁠יֹּ֨אמֶר אֵלֶ֤י⁠הָ אֵלִיָּ֨הוּ֙ אַל־תִּ֣ירְאִ֔י בֹּ֖אִי עֲשִׂ֣י כִ⁠דְבָרֵ֑⁠ךְ אַ֣ךְ עֲשִׂי־לִ֣⁠י מִ֠⁠שָּׁם עֻגָ֨ה קְטַנָּ֤ה בָ⁠רִאשֹׁנָה֙ וְ⁠הוֹצֵ֣אתְ לִ֔⁠י וְ⁠לָ֣⁠ךְ וְ⁠לִ⁠בְנֵ֔⁠ךְ תַּעֲשִׂ֖י בָּ⁠אַחֲרֹנָֽה׃ס","wa⁠yò̇֨ʼmer ʼéle֤y⁠há ʼéliyá̇֨hẇ֙ ʼal-ţi֣̇yrĕʼi֔y bò֖̇ʼiy ʻàşî֣y ki⁠dĕbáré֑⁠kĕ ʼa֣kĕ ʻàşîy-li֣⁠y mi֠⁠şá̇̌m ʻugá֨h qĕtaná֤̇h bá⁠riʼşò̌náh֙ wĕ⁠hwòẕé֣ʼţĕ li֔⁠y wĕ⁠lá֣⁠kĕ wĕ⁠li⁠bĕné֔⁠kĕ ţȧʻàşî֖y bá̇⁠ʼaẖàrònáֽh׃s"],[17,14,"כִּ֣י כֹה֩ אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֣י יִשְׂרָאֵ֗ל כַּ֤ד הַ⁠קֶּ֨מַח֙ לֹ֣א תִכְלָ֔ה וְ⁠צַפַּ֥חַת הַ⁠שֶּׁ֖מֶן לֹ֣א תֶחְסָ֑ר עַ֠ד י֧וֹם תתן־יְהוָ֛ה גֶּ֖שֶׁם עַל־פְּנֵ֥י הָ⁠אֲדָמָֽה׃","ki֣̇y kòh֩ ʼáma֨r yĕhwá֜h ʼèlòhé֣y yişĕ̂ráʼé֗l kȧ֤d ha⁠qė֨maẖ֙ lò֣ʼ ţikĕlá֔h wĕ⁠ẕapȧ֥ẖaţ ha⁠şė֖̌men lò֣ʼ ţeẖĕsá֑r ʻa֠d y֧wòm ţţn-yĕhwá֛h gė֖şěm ʻal-pĕ̇né֥y há⁠ʼàdámáֽh׃"],[17,15,"וַ⁠תֵּ֥לֶךְ וַ⁠תַּעֲשֶׂ֖ה כִּ⁠דְבַ֣ר אֵלִיָּ֑הוּ וַ⁠תֹּ֧אכַל הוא־ו⁠היא וּ⁠בֵיתָ֖⁠הּ יָמִֽים׃","wa⁠ţé֥̇lekĕ wa⁠ţȧʻàşê֖h ki̇⁠dĕba֣r ʼéliyá֑̇hẇ wa⁠ţò֧̇ʼkal hwʼ-w⁠hyʼ ẇ⁠béyţá֖⁠ḣ yámiֽym׃"],[17,16,"כַּ֤ד הַ⁠קֶּ֨מַח֙ לֹ֣א כָלָ֔תָה וְ⁠צַפַּ֥חַת הַ⁠שֶּׁ֖מֶן לֹ֣א חָסֵ֑ר כִּ⁠דְבַ֣ר יְהוָ֔ה אֲשֶׁ֥ר דִּבֶּ֖ר בְּ⁠יַ֥ד אֵלִיָּֽהוּ׃פ","kȧ֤d ha⁠qė֨maẖ֙ lò֣ʼ kálá֔ţáh wĕ⁠ẕapȧ֥ẖaţ ha⁠şė֖̌men lò֣ʼ ẖásé֑r ki̇⁠dĕba֣r yĕhwá֔h ʼàşě֥r di̇bė֖r bĕ̇⁠ya֥d ʼéliyáֽ̇hẇ׃p"],[17,17,"וַ⁠יְהִ֗י אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה חָלָ֕ה בֶּן־הָ⁠אִשָּׁ֖ה בַּעֲלַ֣ת הַ⁠בָּ֑יִת וַ⁠יְהִ֤י חָלְי⁠וֹ֙ חָזָ֣ק מְאֹ֔ד עַ֛ד אֲשֶׁ֥ר לֹא־נֽוֹתְרָה־בּ֖⁠וֹ נְשָׁמָֽה׃","wa⁠yĕhi֗y ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh ẖálá֕h bėn-há⁠ʼişá֖̇̌h bȧʻàla֣ţ ha⁠bá֑̇yiţ wa⁠yĕhi֤y ẖálĕy⁠wò֙ ẖázá֣q mĕʼò֔d ʻa֛d ʼàşě֥r lòʼ-nֽwòţĕráh-ḃ֖⁠wò nĕşá̌máֽh׃"],[17,18,"וַ⁠תֹּ֨אמֶר֙ אֶל־אֵ֣לִיָּ֔הוּ מַה־לִּ֥⁠י וָ⁠לָ֖⁠ךְ אִ֣ישׁ הָ⁠אֱלֹהִ֑ים בָּ֧אתָ אֵלַ֛⁠י לְ⁠הַזְכִּ֥יר אֶת־עֲוֺנִ֖⁠י וּ⁠לְ⁠הָמִ֥ית אֶת־בְּנִֽ⁠י׃","wa⁠ţò̇֨ʼmer֙ ʼel-ʼé֣liyá̇֔hẇ mah-li֥̇⁠y wá⁠lá֖⁠kĕ ʼi֣yş̌ há⁠ʼèlòhi֑ym bá֧̇ʼţá ʼéla֛⁠y lĕ⁠hazĕki֥̇yr ʼeţ-ʻàwֺni֖⁠y ẇ⁠lĕ⁠hámi֥yţ ʼeţ-bĕ̇niֽ⁠y׃"],[17,19,"וַ⁠יֹּ֥אמֶר אֵלֶ֖י⁠הָ תְּנִֽי־לִ֣⁠י אֶת־בְּנֵ֑⁠ךְ וַ⁠יִּקָּחֵ֣⁠הוּ מֵ⁠חֵיקָ֗⁠הּ וַֽ⁠יַּעֲלֵ֨⁠הוּ֙ אֶל־הָ⁠עֲלִיָּ֗ה אֲשֶׁר־הוּא֙ יֹשֵׁ֣ב שָׁ֔ם וַ⁠יַּשְׁכִּבֵ֖⁠הוּ עַל־מִטָּתֽ⁠וֹ׃","wa⁠yò֥̇ʼmer ʼéle֖y⁠há ţĕ̇niֽy-li֣⁠y ʼeţ-bĕ̇né֑⁠kĕ wa⁠yi̇qá̇ẖé֣⁠hẇ mé⁠ẖéyqá֗⁠ḣ waֽ⁠yȧʻàlé֨⁠hẇ֙ ʼel-há⁠ʻàliyá̇֗h ʼàşěr-hẇʼ֙ yòşé֣̌b şá̌֔m wa⁠yȧşĕ̌ki̇bé֖⁠hẇ ʻal-mitá̇ţֽ⁠wò׃"],[17,20,"וַ⁠יִּקְרָ֥א אֶל־יְהוָ֖ה וַ⁠יֹּאמַ֑ר יְהוָ֣ה אֱלֹהָ֔⁠י הֲ֠⁠גַם עַל־הָ⁠אַלְמָנָ֞ה אֲשֶׁר־אֲנִ֨י מִתְגּוֹרֵ֥ר עִמָּ֛⁠הּ הֲרֵע֖וֹתָ לְ⁠הָמִ֥ית אֶת־בְּנָֽ⁠הּ׃","wa⁠yi̇qĕrá֥ʼ ʼel-yĕhwá֖h wa⁠yò̇ʼma֑r yĕhwá֣h ʼèlòhá֔⁠y hà֠⁠gam ʻal-há⁠ʼalĕmáná֞h ʼàşěr-ʼàni֨y miţĕġwòré֥r ʻimá֛̇⁠ḣ hàréʻ֖wòţá lĕ⁠hámi֥yţ ʼeţ-bĕ̇náֽ⁠ḣ׃"],[17,21,"וַ⁠יִּתְמֹדֵ֤ד עַל־הַ⁠יֶּ֨לֶד֙ שָׁלֹ֣שׁ פְּעָמִ֔ים וַ⁠יִּקְרָ֥א אֶל־יְהוָ֖ה וַ⁠יֹּאמַ֑ר יְהוָ֣ה אֱלֹהָ֔⁠י תָּ֥שָׁב נָ֛א נֶֽפֶשׁ־הַ⁠יֶּ֥לֶד הַ⁠זֶּ֖ה עַל־קִרְבּֽ⁠וֹ׃","wa⁠yi̇ţĕmòdé֤d ʻal-ha⁠yė֨led֙ şá̌lò֣ş̌ pĕ̇ʻámi֔ym wa⁠yi̇qĕrá֥ʼ ʼel-yĕhwá֖h wa⁠yò̇ʼma֑r yĕhwá֣h ʼèlòhá֔⁠y ţá֥̇şá̌b ná֛ʼ neֽpeş̌-ha⁠yė֥led ha⁠zė֖h ʻal-qirĕḃֽ⁠wò׃"],[17,22,"וַ⁠יִּשְׁמַ֥ע יְהוָ֖ה בְּ⁠ק֣וֹל אֵלִיָּ֑הוּ וַ⁠תָּ֧שָׁב נֶֽפֶשׁ־הַ⁠יֶּ֛לֶד עַל־קִרְבּ֖⁠וֹ וַ⁠יֶּֽחִי׃","wa⁠yi̇şĕ̌ma֥ʻ yĕhwá֖h bĕ̇⁠q֣wòl ʼéliyá֑̇hẇ wa⁠ţá֧̇şá̌b neֽpeş̌-ha⁠yė֛led ʻal-qirĕḃ֖⁠wò wa⁠yėֽẖiy׃"],[17,23,"וַ⁠יִּקַּ֨ח אֵלִיָּ֜הוּ אֶת־הַ⁠יֶּ֗לֶד וַ⁠יֹּרִדֵ֤⁠הוּ מִן־הָ⁠עֲלִיָּה֙ הַ⁠בַּ֔יְתָ⁠ה וַֽ⁠יִּתְּנֵ֖⁠הוּ לְ⁠אִמּ֑⁠וֹ וַ⁠יֹּ֨אמֶר֙ אֵ֣לִיָּ֔הוּ רְאִ֖י חַ֥י בְּנֵֽ⁠ךְ׃","wa⁠yi̇qȧ֨ẖ ʼéliyá̇֜hẇ ʼeţ-ha⁠yė֗led wa⁠yò̇ridé֤⁠hẇ min-há⁠ʻàliyá̇h֙ ha⁠bȧ֔yĕţá⁠h waֽ⁠yi̇ţĕ̇né֖⁠hẇ lĕ⁠ʼiṁ֑⁠wò wa⁠yò̇֨ʼmer֙ ʼé֣liyá̇֔hẇ rĕʼi֖y ẖa֥y bĕ̇néֽ⁠kĕ׃"],[17,24,"וַ⁠תֹּ֤אמֶר הָֽ⁠אִשָּׁה֙ אֶל־אֵ֣לִיָּ֔הוּ עַתָּה֙ זֶ֣ה יָדַ֔עְתִּי כִּ֛י אִ֥ישׁ אֱלֹהִ֖ים אָ֑תָּה וּ⁠דְבַר־יְהוָ֥ה בְּ⁠פִ֖י⁠ךָ אֱמֶֽת׃פ","wa⁠ţò֤̇ʼmer háֽ⁠ʼişá̇̌h֙ ʼel-ʼé֣liyá̇֔hẇ ʻaţá̇h֙ ze֣h yáda֔ʻĕţi̇y ki֛̇y ʼi֥yş̌ ʼèlòhi֖ym ʼá֑ţá̇h ẇ⁠dĕbar-yĕhwá֥h bĕ̇⁠pi֖y⁠ká ʼèmeֽţ׃p"],[18,1,"וַ⁠יְהִי֙ יָמִ֣ים רַבִּ֔ים וּ⁠דְבַר־יְהוָ֗ה הָיָה֙ אֶל־אֵ֣לִיָּ֔הוּ בַּ⁠שָּׁנָ֥ה הַ⁠שְּׁלִישִׁ֖ית לֵ⁠אמֹ֑ר לֵ֚ךְ הֵרָאֵ֣ה אֶל־אַחְאָ֔ב וְ⁠אֶתְּנָ֥ה מָטָ֖ר עַל־פְּנֵ֥י הָ⁠אֲדָמָֽה׃","wa⁠yĕhiy֙ yámi֣ym rabi̇֔ym ẇ⁠dĕbar-yĕhwá֗h háyáh֙ ʼel-ʼé֣liyá̇֔hẇ bȧ⁠şá̇̌ná֥h ha⁠şĕ̇̌liyşǐ֖yţ lé⁠ʼmò֑r lé֚kĕ héráʼé֣h ʼel-ʼaẖĕʼá֔b wĕ⁠ʼeţĕ̇ná֥h mátá֖r ʻal-pĕ̇né֥y há⁠ʼàdámáֽh׃"],[18,2,"וַ⁠יֵּ֨לֶךְ֙ אֵֽלִיָּ֔הוּ לְ⁠הֵרָא֖וֹת אֶל־אַחְאָ֑ב וְ⁠הָ⁠רָעָ֖ב חָזָ֥ק בְּ⁠שֹׁמְרֽוֹן׃","wa⁠yé̇֨lekĕ֙ ʼéֽliyá̇֔hẇ lĕ⁠héráʼ֖wòţ ʼel-ʼaẖĕʼá֑b wĕ⁠há⁠ráʻá֖b ẖázá֥q bĕ̇⁠şò̌mĕrֽwòn׃"],[18,3,"וַ⁠יִּקְרָ֣א אַחְאָ֔ב אֶל־עֹבַדְיָ֖הוּ אֲשֶׁ֣ר עַל־הַ⁠בָּ֑יִת וְ⁠עֹבַדְיָ֗הוּ הָיָ֥ה יָרֵ֛א אֶת־יְהוָ֖ה מְאֹֽד׃","wa⁠yi̇qĕrá֣ʼ ʼaẖĕʼá֔b ʼel-ʻòbadĕyá֖hẇ ʼàşě֣r ʻal-ha⁠bá֑̇yiţ wĕ⁠ʻòbadĕyá֗hẇ háyá֥h yáré֛ʼ ʼeţ-yĕhwá֖h mĕʼòֽd׃"],[18,4,"וַ⁠יְהִי֙ בְּ⁠הַכְרִ֣ית אִיזֶ֔בֶל אֵ֖ת נְבִיאֵ֣י יְהוָ֑ה וַ⁠יִּקַּ֨ח עֹבַדְיָ֜הוּ מֵאָ֣ה נְבִאִ֗ים וַֽ⁠יַּחְבִּיאֵ֞⁠ם חֲמִשִּׁ֥ים אִישׁ֙ בַּ⁠מְּעָרָ֔ה וְ⁠כִלְכְּלָ֖⁠ם לֶ֥חֶם וָ⁠מָֽיִם׃","wa⁠yĕhiy֙ bĕ̇⁠hakĕri֣yţ ʼiyze֔bel ʼé֖ţ nĕbiyʼé֣y yĕhwá֑h wa⁠yi̇qȧ֨ẖ ʻòbadĕyá֜hẇ méʼá֣h nĕbiʼi֗ym waֽ⁠yȧẖĕbi̇yʼé֞⁠m ẖàmişi֥̇̌ym ʼiyş̌֙ bȧ⁠mĕ̇ʻárá֔h wĕ⁠kilĕkĕ̇lá֖⁠m le֥ẖem wá⁠máֽyim׃"],[18,5,"וַ⁠יֹּ֤אמֶר אַחְאָב֙ אֶל־עֹ֣בַדְיָ֔הוּ לֵ֤ךְ בָּ⁠אָ֨רֶץ֙ אֶל־כָּל־מַעְיְנֵ֣י הַ⁠מַּ֔יִם וְ⁠אֶ֖ל כָּל־הַ⁠נְּחָלִ֑ים אוּלַ֣י ׀ נִמְצָ֣א חָצִ֗יר וּ⁠נְחַיֶּה֙ ס֣וּס וָ⁠פֶ֔רֶד וְ⁠ל֥וֹא נַכְרִ֖ית מֵ⁠הַ⁠בְּהֵמָֽה׃","wa⁠yò֤̇ʼmer ʼaẖĕʼáb֙ ʼel-ʻò֣badĕyá֔hẇ lé֤kĕ bá̇⁠ʼá֨reẕ֙ ʼel-ká̇l-maʻĕyĕné֣y ha⁠mȧ֔yim wĕ⁠ʼe֖l ká̇l-ha⁠nĕ̇ẖáli֑ym ʼẇla֣y ׀ nimĕẕá֣ʼ ẖáẕi֗yr ẇ⁠nĕẖayėh֙ s֣ẇs wá⁠pe֔red wĕ⁠l֥wòʼ nakĕri֖yţ mé⁠ha⁠bĕ̇hémáֽh׃"],[18,6,"וַֽ⁠יְחַלְּק֥וּ לָ⁠הֶ֛ם אֶת־הָ⁠אָ֖רֶץ לַֽ⁠עֲבָר־בָּ֑⁠הּ אַחְאָ֞ב הָלַ֨ךְ בְּ⁠דֶ֤רֶךְ אֶחָד֙ לְ⁠בַדּ֔⁠וֹ וְ⁠עֹֽבַדְיָ֛הוּ הָלַ֥ךְ בְּ⁠דֶרֶךְ־אֶחָ֖ד לְ⁠בַדּֽ⁠וֹ׃","waֽ⁠yĕẖalĕ̇q֥ẇ lá⁠he֛m ʼeţ-há⁠ʼá֖reẕ laֽ⁠ʻàbár-bá֑̇⁠ḣ ʼaẖĕʼá֞b hála֨kĕ bĕ̇⁠de֤rekĕ ʼeẖád֙ lĕ⁠baḋ֔⁠wò wĕ⁠ʻòֽbadĕyá֛hẇ hála֥kĕ bĕ̇⁠derekĕ-ʼeẖá֖d lĕ⁠baḋֽ⁠wò׃"],[18,7,"וַ⁠יְהִ֤י עֹבַדְיָ֨הוּ֙ בַּ⁠דֶּ֔רֶךְ וְ⁠הִנֵּ֥ה אֵלִיָּ֖הוּ לִ⁠קְרָאת֑⁠וֹ וַ⁠יַּכִּרֵ֨⁠הוּ֙ וַ⁠יִּפֹּ֣ל עַל־פָּנָ֔י⁠ו וַ⁠יֹּ֕אמֶר הַ⁠אַתָּ֥ה זֶ֖ה אֲדֹנִ֥⁠י אֵלִיָּֽהוּ׃","wa⁠yĕhi֤y ʻòbadĕyá֨hẇ֙ bȧ⁠dė֔rekĕ wĕ⁠hiné֥̇h ʼéliyá֖̇hẇ li⁠qĕráʼţ֑⁠wò wa⁠yȧki̇ré֨⁠hẇ֙ wa⁠yi̇pò֣̇l ʻal-pá̇ná֔y⁠w wa⁠yò̇֕ʼmer ha⁠ʼaţá֥̇h ze֖h ʼàdòni֥⁠y ʼéliyáֽ̇hẇ׃"],[18,8,"וַ⁠יֹּ֥אמֶר ל֖⁠וֹ אָ֑נִי לֵ֛ךְ אֱמֹ֥ר לַ⁠אדֹנֶ֖י⁠ךָ הִנֵּ֥ה אֵלִיָּֽהוּ׃","wa⁠yò֥̇ʼmer l֖⁠wò ʼá֑niy lé֛kĕ ʼèmò֥r la⁠ʼdòne֖y⁠ká hiné֥̇h ʼéliyáֽ̇hẇ׃"],[18,9,"וַ⁠יֹּ֖אמֶר מֶ֣ה חָטָ֑אתִי כִּֽי־אַתָּ֞ה נֹתֵ֧ן אֶֽת־עַבְדְּ⁠ךָ֛ בְּ⁠יַד־אַחְאָ֖ב לַ⁠הֲמִיתֵֽ⁠נִי׃","wa⁠yò֖̇ʼmer me֣h ẖátá֑ʼţiy kiֽ̇y-ʼaţá̇֞h nòţé֧n ʼeֽţ-ʻabĕdĕ̇⁠ká֛ bĕ̇⁠yad-ʼaẖĕʼá֖b la⁠hàmiyţéֽ⁠niy׃"],[18,10,"חַ֣י ׀ יְהוָ֣ה אֱלֹהֶ֗י⁠ךָ אִם־יֶשׁ־גּ֤וֹי וּ⁠מַמְלָכָה֙ אֲ֠שֶׁר לֹֽא־שָׁלַ֨ח אֲדֹנִ֥⁠י שָׁם֙ לְ⁠בַקֶּשְׁ⁠ךָ֔ וְ⁠אָמְר֖וּ אָ֑יִן וְ⁠הִשְׁבִּ֤יעַ אֶת־הַ⁠מַּמְלָכָה֙ וְ⁠אֶת־הַ⁠גּ֔וֹי כִּ֖י לֹ֥א יִמְצָאֶֽ⁠כָּה׃","ẖa֣y ׀ yĕhwá֣h ʼèlòhe֗y⁠ká ʼim-yeş̌-ġ֤wòy ẇ⁠mamĕlákáh֙ ʼà֠şěr lòֽʼ-şá̌la֨ẖ ʼàdòni֥⁠y şá̌m֙ lĕ⁠baqėşĕ̌⁠ká֔ wĕ⁠ʼámĕr֖ẇ ʼá֑yin wĕ⁠hişĕ̌bi֤̇yʻa ʼeţ-ha⁠mȧmĕlákáh֙ wĕ⁠ʼeţ-ha⁠ġ֔wòy ki֖̇y lò֥ʼ yimĕẕáʼeֽ⁠ká̇h׃"],[18,11,"וְ⁠עַתָּ֖ה אַתָּ֣ה אֹמֵ֑ר לֵ֛ךְ אֱמֹ֥ר לַ⁠אדֹנֶ֖י⁠ךָ הִנֵּ֥ה אֵלִיָּֽהוּ׃","wĕ⁠ʻaţá֖̇h ʼaţá֣̇h ʼòmé֑r lé֛kĕ ʼèmò֥r la⁠ʼdòne֖y⁠ká hiné֥̇h ʼéliyáֽ̇hẇ׃"],[18,12,"וְ⁠הָיָ֞ה אֲנִ֣י ׀ אֵלֵ֣ךְ מֵ⁠אִתָּ֗⁠ךְ וְ⁠ר֨וּחַ יְהוָ֤ה ׀ יִֽשָּׂאֲ⁠ךָ֙ עַ֚ל אֲשֶׁ֣ר לֹֽא־אֵדָ֔ע וּ⁠בָ֨אתִי לְ⁠הַגִּ֧יד לְ⁠אַחְאָ֛ב וְ⁠לֹ֥א יִֽמְצָאֲ⁠ךָ֖ וַ⁠הֲרָגָ֑⁠נִי וְ⁠עַבְדְּ⁠ךָ֛ יָרֵ֥א אֶת־יְהוָ֖ה מִ⁠נְּעֻרָֽ⁠י׃","wĕ⁠háyá֞h ʼàni֣y ׀ ʼélé֣kĕ mé⁠ʼiţá̇֗⁠kĕ wĕ⁠r֨ẇẖa yĕhwá֤h ׀ yiֽşá̇̂ʼà⁠ká֙ ʻa֚l ʼàşě֣r lòֽʼ-ʼédá֔ʻ ẇ⁠bá֨ʼţiy lĕ⁠hagi֧̇yd lĕ⁠ʼaẖĕʼá֛b wĕ⁠lò֥ʼ yiֽmĕẕáʼà⁠ká֖ wa⁠hàrágá֑⁠niy wĕ⁠ʻabĕdĕ̇⁠ká֛ yáré֥ʼ ʼeţ-yĕhwá֖h mi⁠nĕ̇ʻuráֽ⁠y׃"],[18,13,"הֲ⁠לֹֽא־הֻגַּ֤ד לַֽ⁠אדֹנִ⁠י֙ אֵ֣ת אֲשֶׁר־עָשִׂ֔יתִי בַּ⁠הֲרֹ֣ג אִיזֶ֔בֶל אֵ֖ת נְבִיאֵ֣י יְהוָ֑ה וָ⁠אַחְבִּא֩ מִ⁠נְּבִיאֵ֨י יְהוָ֜ה מֵ֣אָה אִ֗ישׁ חֲמִשִּׁ֨ים חֲמִשִּׁ֥ים אִישׁ֙ בַּ⁠מְּעָרָ֔ה וָ⁠אֲכַלְכְּלֵ֖⁠ם לֶ֥חֶם וָ⁠מָֽיִם׃","hà⁠lòֽʼ-hugȧ֤d laֽ⁠ʼdòni⁠y֙ ʼé֣ţ ʼàşěr-ʻáşî֔yţiy bȧ⁠hàrò֣g ʼiyze֔bel ʼé֖ţ nĕbiyʼé֣y yĕhwá֑h wá⁠ʼaẖĕbi̇ʼ֩ mi⁠nĕ̇biyʼé֨y yĕhwá֜h mé֣ʼáh ʼi֗yş̌ ẖàmişi̇̌֨ym ẖàmişi֥̇̌ym ʼiyş̌֙ bȧ⁠mĕ̇ʻárá֔h wá⁠ʼàkalĕkĕ̇lé֖⁠m le֥ẖem wá⁠máֽyim׃"],[18,14,"וְ⁠עַתָּה֙ אַתָּ֣ה אֹמֵ֔ר לֵ֛ךְ אֱמֹ֥ר לַֽ⁠אדֹנֶ֖י⁠ךָ הִנֵּ֣ה אֵלִיָּ֑הוּ וַ⁠הֲרָגָֽ⁠נִי׃ס","wĕ⁠ʻaţá̇h֙ ʼaţá֣̇h ʼòmé֔r lé֛kĕ ʼèmò֥r laֽ⁠ʼdòne֖y⁠ká hiné֣̇h ʼéliyá֑̇hẇ wa⁠hàrágáֽ⁠niy׃s"],[18,15,"וַ⁠יֹּ֨אמֶר֙ אֵֽלִיָּ֔הוּ חַ֚י יְהוָ֣ה צְבָא֔וֹת אֲשֶׁ֥ר עָמַ֖דְתִּי לְ⁠פָנָ֑י⁠ו כִּ֥י הַ⁠יּ֖וֹם אֵרָאֶ֥ה אֵלָֽי⁠ו׃","wa⁠yò̇֨ʼmer֙ ʼéֽliyá̇֔hẇ ẖa֚y yĕhwá֣h ẕĕbáʼ֔wòţ ʼàşě֥r ʻáma֖dĕţi̇y lĕ⁠páná֑y⁠w ki֥̇y ha⁠ẏ֖wòm ʼéráʼe֥h ʼéláֽy⁠w׃"],[18,16,"וַ⁠יֵּ֧לֶךְ עֹבַדְיָ֛הוּ לִ⁠קְרַ֥את אַחְאָ֖ב וַ⁠יַּגֶּד־ל֑⁠וֹ וַ⁠יֵּ֥לֶךְ אַחְאָ֖ב לִ⁠קְרַ֥את אֵלִיָּֽהוּ׃","wa⁠yé֧̇lekĕ ʻòbadĕyá֛hẇ li⁠qĕra֥ʼţ ʼaẖĕʼá֖b wa⁠yȧgėd-l֑⁠wò wa⁠yé֥̇lekĕ ʼaẖĕʼá֖b li⁠qĕra֥ʼţ ʼéliyáֽ̇hẇ׃"],[18,17,"וַ⁠יְהִ֛י כִּ⁠רְא֥וֹת אַחְאָ֖ב אֶת־אֵלִיָּ֑הוּ וַ⁠יֹּ֤אמֶר אַחְאָב֙ אֵלָ֔י⁠ו הַ⁠אַתָּ֥ה זֶ֖ה עֹכֵ֥ר יִשְׂרָאֵֽל׃","wa⁠yĕhi֛y ki̇⁠rĕʼ֥wòţ ʼaẖĕʼá֖b ʼeţ-ʼéliyá֑̇hẇ wa⁠yò֤̇ʼmer ʼaẖĕʼáb֙ ʼélá֔y⁠w ha⁠ʼaţá֥̇h ze֖h ʻòké֥r yişĕ̂ráʼéֽl׃"],[18,18,"וַ⁠יֹּ֗אמֶר לֹ֤א עָכַ֨רְתִּי֙ אֶת־יִשְׂרָאֵ֔ל כִּ֥י אִם־אַתָּ֖ה וּ⁠בֵ֣ית אָבִ֑י⁠ךָ בַּֽ⁠עֲזָבְ⁠כֶם֙ אֶת־מִצְוֺ֣ת יְהוָ֔ה וַ⁠תֵּ֖לֶךְ אַחֲרֵ֥י הַ⁠בְּעָלִֽים׃","wa⁠yò̇֗ʼmer lò֤ʼ ʻáka֨rĕţi̇y֙ ʼeţ-yişĕ̂ráʼé֔l ki֥̇y ʼim-ʼaţá֖̇h ẇ⁠bé֣yţ ʼábi֑y⁠ká ḃֽa⁠ʻàzábĕ⁠kem֙ ʼeţ-miẕĕwֺ֣ţ yĕhwá֔h wa⁠ţé֖̇lekĕ ʼaẖàré֥y ha⁠bĕ̇ʻáliֽym׃"],[18,19,"וְ⁠עַתָּ֗ה שְׁלַ֨ח קְבֹ֥ץ אֵלַ֛⁠י אֶת־כָּל־יִשְׂרָאֵ֖ל אֶל־הַ֣ר הַ⁠כַּרְמֶ֑ל וְ⁠אֶת־נְבִיאֵ֨י הַ⁠בַּ֜עַל אַרְבַּ֧ע מֵא֣וֹת וַ⁠חֲמִשִּׁ֗ים וּ⁠נְבִיאֵ֤י הָֽ⁠אֲשֵׁרָה֙ אַרְבַּ֣ע מֵא֔וֹת אֹכְלֵ֖י שֻׁלְחַ֥ן אִיזָֽבֶל׃","wĕ⁠ʻaţá̇֗h şĕ̌la֨ẖ qĕbò֥ẕ ʼéla֛⁠y ʼeţ-ká̇l-yişĕ̂ráʼé֖l ʼel-ha֣r ha⁠kȧrĕme֑l wĕ⁠ʼeţ-nĕbiyʼé֨y ha⁠bȧ֜ʻal ʼarĕbȧ֧ʻ méʼ֣wòţ wa⁠ẖàmişi̇̌֗ym ẇ⁠nĕbiyʼé֤y háֽ⁠ʼàşé̌ráh֙ ʼarĕbȧ֣ʻ méʼ֔wòţ ʼòkĕlé֖y şǔlĕẖa֥n ʼiyzáֽbel׃"],[18,20,"וַ⁠יִּשְׁלַ֥ח אַחְאָ֖ב בְּ⁠כָל־בְּנֵ֣י יִשְׂרָאֵ֑ל וַ⁠יִּקְבֹּ֥ץ אֶת־הַ⁠נְּבִיאִ֖ים אֶל־הַ֥ר הַ⁠כַּרְמֶֽל׃","wa⁠yi̇şĕ̌la֥ẖ ʼaẖĕʼá֖b bĕ̇⁠kál-bĕ̇né֣y yişĕ̂ráʼé֑l wa⁠yi̇qĕbò֥̇ẕ ʼeţ-ha⁠nĕ̇biyʼi֖ym ʼel-ha֥r ha⁠kȧrĕmeֽl׃"],[18,21,"וַ⁠יִּגַּ֨שׁ אֵלִיָּ֜הוּ אֶל־כָּל־הָ⁠עָ֗ם וַ⁠יֹּ֨אמֶר֙ עַד־מָתַ֞י אַתֶּ֣ם פֹּסְחִים֮ עַל־שְׁתֵּ֣י הַ⁠סְּעִפִּים֒ אִם־יְהוָ֤ה הָֽ⁠אֱלֹהִים֙ לְכ֣וּ אַחֲרָ֔י⁠ו וְ⁠אִם־הַ⁠בַּ֖עַל לְכ֣וּ אַחֲרָ֑י⁠ו וְ⁠לֹֽא־עָנ֥וּ הָ⁠עָ֛ם אֹת֖⁠וֹ דָּבָֽר׃","wa⁠yi̇gȧ֨ş̌ ʼéliyá̇֜hẇ ʼel-ká̇l-há⁠ʻá֗m wa⁠yò̇֨ʼmer֙ ʻad-máţa֞y ʼaţė֣m pò̇sĕẖiym֮ ʻal-şĕ̌ţé֣̇y ha⁠sĕ̇ʻipi̇ym֒ ʼim-yĕhwá֤h háֽ⁠ʼèlòhiym֙ lĕk֣ẇ ʼaẖàrá֔y⁠w wĕ⁠ʼim-ha⁠bȧ֖ʻal lĕk֣ẇ ʼaẖàrá֑y⁠w wĕ⁠lòֽʼ-ʻán֥ẇ há⁠ʻá֛m ʼòţ֖⁠wò dá̇báֽr׃"],[18,22,"וַ⁠יֹּ֤אמֶר אֵלִיָּ֨הוּ֙ אֶל־הָ⁠עָ֔ם אֲנִ֞י נוֹתַ֧רְתִּי נָבִ֛יא לַ⁠יהוָ֖ה לְ⁠בַדִּ֑⁠י וּ⁠נְבִיאֵ֣י הַ⁠בַּ֔עַל אַרְבַּע־מֵא֥וֹת וַ⁠חֲמִשִּׁ֖ים אִֽישׁ׃","wa⁠yò֤̇ʼmer ʼéliyá̇֨hẇ֙ ʼel-há⁠ʻá֔m ʼàni֞y nwòţa֧rĕţi̇y nábi֛yʼ la⁠yhwá֖h lĕ⁠badi֑̇⁠y ẇ⁠nĕbiyʼé֣y ha⁠bȧ֔ʻal ʼarĕbȧʻ-méʼ֥wòţ wa⁠ẖàmişi֖̇̌ym ʼiֽyş̌׃"],[18,23,"וְ⁠יִתְּנוּ־לָ֜⁠נוּ שְׁנַ֣יִם פָּרִ֗ים וְ⁠יִבְחֲר֣וּ לָ⁠הֶם֩ הַ⁠פָּ֨ר הָ⁠אֶחָ֜ד וִֽ⁠ינַתְּחֻ֗⁠הוּ וְ⁠יָשִׂ֨ימוּ֙ עַל־הָ֣⁠עֵצִ֔ים וְ⁠אֵ֖שׁ לֹ֣א יָשִׂ֑ימוּ וַ⁠אֲנִ֞י אֶעֱשֶׂ֣ה ׀ אֶת־הַ⁠פָּ֣ר הָ⁠אֶחָ֗ד וְ⁠נָֽתַתִּי֙ עַל־הָ֣⁠עֵצִ֔ים וְ⁠אֵ֖שׁ לֹ֥א אָשִֽׂים׃","wĕ⁠yiţĕ̇nẇ-lá֜⁠nẇ şĕ̌na֣yim pá̇ri֗ym wĕ⁠yibĕẖàr֣ẇ lá⁠hem֩ ha⁠pá̇֨r há⁠ʼeẖá֜d wiֽ⁠ynaţĕ̇ẖu֗⁠hẇ wĕ⁠yáşî֨ymẇ֙ ʻal-há֣⁠ʻéẕi֔ym wĕ⁠ʼé֖ş̌ lò֣ʼ yáşî֑ymẇ wa⁠ʼàni֞y ʼeʻèşê֣h ׀ ʼeţ-ha⁠pá֣̇r há⁠ʼeẖá֗d wĕ⁠náֽţaţi̇y֙ ʻal-há֣⁠ʻéẕi֔ym wĕ⁠ʼé֖ş̌ lò֥ʼ ʼáşîֽym׃"],[18,24,"וּ⁠קְרָאתֶ֞ם בְּ⁠שֵׁ֣ם אֱלֹֽהֵי⁠כֶ֗ם וַֽ⁠אֲנִי֙ אֶקְרָ֣א בְ⁠שֵׁם־יְהוָ֔ה וְ⁠הָיָ֧ה הָ⁠אֱלֹהִ֛ים אֲשֶׁר־יַעֲנֶ֥ה בָ⁠אֵ֖שׁ ה֣וּא הָ⁠אֱלֹהִ֑ים וַ⁠יַּ֧עַן כָּל־הָ⁠עָ֛ם וַ⁠יֹּאמְר֖וּ ט֥וֹב הַ⁠דָּבָֽר׃","ẇ⁠qĕráʼţe֞m bĕ̇⁠şé֣̌m ʼèlòֽhéy⁠ke֗m wֽa⁠ʼàniy֙ ʼeqĕrá֣ʼ bĕ⁠şé̌m-yĕhwá֔h wĕ⁠háyá֧h há⁠ʼèlòhi֛ym ʼàşěr-yaʻàne֥h bá⁠ʼé֖ş̌ h֣ẇʼ há⁠ʼèlòhi֑ym wa⁠yȧ֧ʻan ká̇l-há⁠ʻá֛m wa⁠yò̇ʼmĕr֖ẇ t֥wòb ha⁠dá̇báֽr׃"],[18,25,"וַ⁠יֹּ֨אמֶר אֵלִיָּ֜הוּ לִ⁠נְבִיאֵ֣י הַ⁠בַּ֗עַל בַּחֲר֨וּ לָ⁠כֶ֜ם הַ⁠פָּ֤ר הָֽ⁠אֶחָד֙ וַ⁠עֲשׂ֣וּ רִאשֹׁנָ֔ה כִּ֥י אַתֶּ֖ם הָ⁠רַבִּ֑ים וְ⁠קִרְאוּ֙ בְּ⁠שֵׁ֣ם אֱלֹהֵי⁠כֶ֔ם וְ⁠אֵ֖שׁ לֹ֥א תָשִֽׂימוּ׃","wa⁠yò̇֨ʼmer ʼéliyá̇֜hẇ li⁠nĕbiyʼé֣y ha⁠bȧ֗ʻal bȧẖàr֨ẇ lá⁠ke֜m ha⁠pá֤̇r háֽ⁠ʼeẖád֙ wa⁠ʻàş֣̂ẇ riʼşò̌ná֔h ki֥̇y ʼaţė֖m há⁠rabi֑̇ym wĕ⁠qirĕʼẇ֙ bĕ̇⁠şé֣̌m ʼèlòhéy⁠ke֔m wĕ⁠ʼé֖ş̌ lò֥ʼ ţáşîֽymẇ׃"],[18,26,"וַ֠⁠יִּקְחוּ אֶת־הַ⁠פָּ֨ר אֲשֶׁר־נָתַ֣ן לָ⁠הֶם֮ וַֽ⁠יַּעֲשׂוּ֒ וַ⁠יִּקְרְא֣וּ בְ⁠שֵׁם־הַ֠⁠בַּעַל מֵ⁠הַ⁠בֹּ֨קֶר וְ⁠עַד־הַ⁠צָּהֳרַ֤יִם לֵ⁠אמֹר֙ הַ⁠בַּ֣עַל עֲנֵ֔⁠נוּ וְ⁠אֵ֥ין ק֖וֹל וְ⁠אֵ֣ין עֹנֶ֑ה וַֽ⁠יְפַסְּח֔וּ עַל־הַ⁠מִּזְבֵּ֖חַ אֲשֶׁ֥ר עָשָֽׂה׃","wa֠⁠yi̇qĕẖẇ ʼeţ-ha⁠pá̇֨r ʼàşěr-náţa֣n lá⁠hem֮ waֽ⁠yȧʻàş̂ẇ֒ wa⁠yi̇qĕrĕʼ֣ẇ bĕ⁠şé̌m-ha֠⁠bȧʻal mé⁠ha⁠bò̇֨qer wĕ⁠ʻad-ha⁠ẕá̇hora֤yim lé⁠ʼmòr֙ ha⁠bȧ֣ʻal ʻàné֔⁠nẇ wĕ⁠ʼé֥yn q֖wòl wĕ⁠ʼé֣yn ʻòne֑h waֽ⁠yĕpasĕ̇ẖ֔ẇ ʻal-ha⁠mi̇zĕbé֖̇ẖa ʼàşě֥r ʻáşáֽ̂h׃"],[18,27,"וַ⁠יְהִ֨י בַֽ⁠צָּהֳרַ֜יִם וַ⁠יְהַתֵּ֧ל בָּ⁠הֶ֣ם אֵלִיָּ֗הוּ וַ⁠יֹּ֨אמֶר֙ קִרְא֤וּ בְ⁠קוֹל־גָּדוֹל֙ כִּֽי־אֱלֹהִ֣ים ה֔וּא כִּ֣י שִׂ֧יחַ וְ⁠כִֽי־שִׂ֛יג ל֖⁠וֹ וְ⁠כִֽי־דֶ֣רֶךְ ל֑⁠וֹ אוּלַ֛י יָשֵׁ֥ן ה֖וּא וְ⁠יִקָֽץ׃","wa⁠yĕhi֨y baֽ⁠ẕá̇hora֜yim wa⁠yĕhaţé֧̇l bá̇⁠he֣m ʼéliyá̇֗hẇ wa⁠yò̇֨ʼmer֙ qirĕʼ֤ẇ bĕ⁠qwòl-gá̇dwòl֙ kiֽ̇y-ʼèlòhi֣ym h֔ẇʼ ki֣̇y şî֧yẖa wĕ⁠kiֽy-şî֛yg l֖⁠wò wĕ⁠kiֽy-de֣rekĕ l֑⁠wò ʼẇla֛y yáşé֥̌n h֖ẇʼ wĕ⁠yiqáֽẕ׃"],[18,28,"וַֽ⁠יִּקְרְאוּ֙ בְּ⁠ק֣וֹל גָּד֔וֹל וַ⁠יִּתְגֹּֽדְדוּ֙ כְּ⁠מִשְׁפָּטָ֔⁠ם בַּ⁠חֲרָב֖וֹת וּ⁠בָֽ⁠רְמָחִ֑ים עַד־שְׁפָךְ־דָּ֖ם עֲלֵי⁠הֶֽם׃","waֽ⁠yi̇qĕrĕʼẇ֙ bĕ̇⁠q֣wòl gá̇d֔wòl wa⁠yi̇ţĕgòֽ̇dĕdẇ֙ kĕ̇⁠mişĕ̌pá̇tá֔⁠m bȧ⁠ẖàráb֖wòţ ẇ⁠báֽ⁠rĕmáẖi֑ym ʻad-şĕ̌pákĕ-dá֖̇m ʻàléy⁠heֽm׃"],[18,29,"וַֽ⁠יְהִי֙ כַּ⁠עֲבֹ֣ר הַֽ⁠צָּהֳרַ֔יִם וַ⁠יִּֽתְנַבְּא֔וּ עַ֖ד לַ⁠עֲל֣וֹת הַ⁠מִּנְחָ֑ה וְ⁠אֵֽין־ק֥וֹל וְ⁠אֵין־עֹנֶ֖ה וְ⁠אֵ֥ין קָֽשֶׁב׃","waֽ⁠yĕhiy֙ kȧ⁠ʻàbò֣r haֽ⁠ẕá̇hora֔yim wa⁠yiֽ̇ţĕnabĕ̇ʼ֔ẇ ʻa֖d la⁠ʻàl֣wòţ ha⁠mi̇nĕẖá֑h wĕ⁠ʼéֽyn-q֥wòl wĕ⁠ʼéyn-ʻòne֖h wĕ⁠ʼé֥yn qáֽşěb׃"],[18,30,"וַ⁠יֹּ֨אמֶר אֵלִיָּ֤הוּ לְ⁠כָל־הָ⁠עָם֙ גְּשׁ֣וּ אֵלַ֔⁠י וַ⁠יִּגְּשׁ֥וּ כָל־הָ⁠עָ֖ם אֵלָ֑י⁠ו וַ⁠יְרַפֵּ֛א אֶת־מִזְבַּ֥ח יְהוָ֖ה הֶ⁠הָרֽוּס׃","wa⁠yò̇֨ʼmer ʼéliyá֤̇hẇ lĕ⁠kál-há⁠ʻám֙ gĕ̇ş֣̌ẇ ʼéla֔⁠y wa⁠yi̇gĕ̇ş֥̌ẇ kál-há⁠ʻá֖m ʼélá֑y⁠w wa⁠yĕrapé֛̇ʼ ʼeţ-mizĕbȧ֥ẖ yĕhwá֖h he⁠hárֽẇs׃"],[18,31,"וַ⁠יִּקַּ֣ח אֵלִיָּ֗הוּ שְׁתֵּ֤ים עֶשְׂרֵה֙ אֲבָנִ֔ים כְּ⁠מִסְפַּ֖ר שִׁבְטֵ֣י בְנֵֽי־יַעֲקֹ֑ב אֲשֶׁר֩ הָיָ֨ה דְבַר־יְהוָ֤ה אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר יִשְׂרָאֵ֖ל יִהְיֶ֥ה שְׁמֶֽ⁠ךָ׃","wa⁠yi̇qȧ֣ẖ ʼéliyá̇֗hẇ şĕ̌ţé֤̇ym ʻeşĕ̂réh֙ ʼàbáni֔ym kĕ̇⁠misĕpȧ֖r şǐbĕté֣y bĕnéֽy-yaʻàqò֑b ʼàşěr֩ háyá֨h dĕbar-yĕhwá֤h ʼéláy⁠w֙ lé⁠ʼmò֔r yişĕ̂ráʼé֖l yihĕye֥h şĕ̌meֽ⁠ká׃"],[18,32,"וַ⁠יִּבְנֶ֧ה אֶת־הָ⁠אֲבָנִ֛ים מִזְבֵּ֖חַ בְּ⁠שֵׁ֣ם יְהוָ֑ה וַ⁠יַּ֣עַשׂ תְּעָלָ֗ה כְּ⁠בֵית֙ סָאתַ֣יִם זֶ֔רַע סָבִ֖יב לַ⁠מִּזְבֵּֽחַ׃","wa⁠yi̇bĕne֧h ʼeţ-há⁠ʼàbáni֛ym mizĕbé֖̇ẖa bĕ̇⁠şé֣̌m yĕhwá֑h wa⁠yȧ֣ʻaş̂ ţĕ̇ʻálá֗h kĕ̇⁠béyţ֙ sáʼţa֣yim ze֔raʻ sábi֖yb la⁠mi̇zĕbéֽ̇ẖa׃"],[18,33,"וַֽ⁠יַּעֲרֹ֖ךְ אֶת־הָֽ⁠עֵצִ֑ים וַ⁠יְנַתַּח֙ אֶת־הַ⁠פָּ֔ר וַ⁠יָּ֖שֶׂם עַל־הָ⁠עֵצִֽים׃","waֽ⁠yȧʻàrò֖kĕ ʼeţ-háֽ⁠ʻéẕi֑ym wa⁠yĕnaţȧẖ֙ ʼeţ-ha⁠pá̇֔r wa⁠yá֖̇şêm ʻal-há⁠ʻéẕiֽym׃"],[18,34,"וַ⁠יֹּ֗אמֶר מִלְא֨וּ אַרְבָּעָ֤ה כַדִּים֙ מַ֔יִם וְ⁠יִֽצְק֥וּ עַל־הָ⁠עֹלָ֖ה וְ⁠עַל־הָ⁠עֵצִ֑ים וַ⁠יֹּ֤אמֶר שְׁנוּ֙ וַ⁠יִּשְׁנ֔וּ וַ⁠יֹּ֥אמֶר שַׁלֵּ֖שׁוּ וַ⁠יְשַׁלֵּֽשׁוּ׃","wa⁠yò̇֗ʼmer milĕʼ֨ẇ ʼarĕbá̇ʻá֤h kadi̇ym֙ ma֔yim wĕ⁠yiֽẕĕq֥ẇ ʻal-há⁠ʻòlá֖h wĕ⁠ʻal-há⁠ʻéẕi֑ym wa⁠yò֤̇ʼmer şĕ̌nẇ֙ wa⁠yi̇şĕ̌n֔ẇ wa⁠yò֥̇ʼmer şǎlé֖̇ş̌ẇ wa⁠yĕşǎléֽ̇ş̌ẇ׃"],[18,35,"וַ⁠יֵּלְכ֣וּ הַ⁠מַּ֔יִם סָבִ֖יב לַ⁠מִּזְבֵּ֑חַ וְ⁠גַ֥ם אֶת־הַ⁠תְּעָלָ֖ה מִלֵּא־מָֽיִם׃","wa⁠yé̇lĕk֣ẇ ha⁠mȧ֔yim sábi֖yb la⁠mi̇zĕbé֑̇ẖa wĕ⁠ga֥m ʼeţ-ha⁠ţĕ̇ʻálá֖h milé̇ʼ-máֽyim׃"],[18,36,"וַ⁠יְהִ֣י ׀ בַּ⁠עֲל֣וֹת הַ⁠מִּנְחָ֗ה וַ⁠יִּגַּ֞שׁ אֵלִיָּ֣הוּ הַ⁠נָּבִיא֮ וַ⁠יֹּאמַר֒ יְהוָ֗ה אֱלֹהֵי֙ אַבְרָהָם֙ יִצְחָ֣ק וְ⁠יִשְׂרָאֵ֔ל הַ⁠יּ֣וֹם יִוָּדַ֗ע כִּֽי־אַתָּ֧ה אֱלֹהִ֛ים בְּ⁠יִשְׂרָאֵ֖ל וַ⁠אֲנִ֣י עַבְדֶּ֑⁠ךָ ו⁠ב⁠דברי⁠ך עָשִׂ֔יתִי אֵ֥ת כָּל־הַ⁠דְּבָרִ֖ים הָ⁠אֵֽלֶּה׃","wa⁠yĕhi֣y ׀ bȧ⁠ʻàl֣wòţ ha⁠mi̇nĕẖá֗h wa⁠yi̇gȧ֞ş̌ ʼéliyá֣̇hẇ ha⁠ná̇biyʼ֮ wa⁠yò̇ʼmar֒ yĕhwá֗h ʼèlòhéy֙ ʼabĕráhám֙ yiẕĕẖá֣q wĕ⁠yişĕ̂ráʼé֔l ha⁠ẏ֣wòm yiwá̇da֗ʻ kiֽ̇y-ʼaţá֧̇h ʼèlòhi֛ym bĕ̇⁠yişĕ̂ráʼé֖l wa⁠ʼàni֣y ʻabĕdė֑⁠ká w⁠b⁠dbry⁠k ʻáşî֔yţiy ʼé֥ţ ká̇l-ha⁠dĕ̇bári֖ym há⁠ʼéֽlėh׃"],[18,37,"עֲנֵ֤⁠נִי יְהוָה֙ עֲנֵ֔⁠נִי וְ⁠יֵֽדְעוּ֙ הָ⁠עָ֣ם הַ⁠זֶּ֔ה כִּֽי־אַתָּ֥ה יְהוָ֖ה הָ⁠אֱלֹהִ֑ים וְ⁠אַתָּ֛ה הֲסִבֹּ֥תָ אֶת־לִבָּ֖⁠ם אֲחֹרַנִּֽית׃","ʻàné֤⁠niy yĕhwáh֙ ʻàné֔⁠niy wĕ⁠yéֽdĕʻẇ֙ há⁠ʻá֣m ha⁠zė֔h kiֽ̇y-ʼaţá֥̇h yĕhwá֖h há⁠ʼèlòhi֑ym wĕ⁠ʼaţá֛̇h hàsibò֥̇ţá ʼeţ-libá֖̇⁠m ʼàẖòraniֽ̇yţ׃"],[18,38,"וַ⁠תִּפֹּ֣ל אֵשׁ־יְהוָ֗ה וַ⁠תֹּ֤אכַל אֶת־הָֽ⁠עֹלָה֙ וְ⁠אֶת־הָ֣⁠עֵצִ֔ים וְ⁠אֶת־הָ⁠אֲבָנִ֖ים וְ⁠אֶת־הֶ⁠עָפָ֑ר וְ⁠אֶת־הַ⁠מַּ֥יִם אֲשֶׁר־בַּ⁠תְּעָלָ֖ה לִחֵֽכָה׃","wa⁠ţi̇pò֣̇l ʼéş̌-yĕhwá֗h wa⁠ţò֤̇ʼkal ʼeţ-háֽ⁠ʻòláh֙ wĕ⁠ʼeţ-há֣⁠ʻéẕi֔ym wĕ⁠ʼeţ-há⁠ʼàbáni֖ym wĕ⁠ʼeţ-he⁠ʻápá֑r wĕ⁠ʼeţ-ha⁠mȧ֥yim ʼàşěr-bȧ⁠ţĕ̇ʻálá֖h liẖéֽkáh׃"],[18,39,"וַ⁠יַּרְא֙ כָּל־הָ⁠עָ֔ם וַֽ⁠יִּפְּל֖וּ עַל־פְּנֵי⁠הֶ֑ם וַ⁠יֹּ֣אמְר֔וּ יְהוָה֙ ה֣וּא הָ⁠אֱלֹהִ֔ים יְהוָ֖ה ה֥וּא הָ⁠אֱלֹהִֽים׃","wa⁠yȧrĕʼ֙ ká̇l-há⁠ʻá֔m waֽ⁠yi̇pĕ̇l֖ẇ ʻal-pĕ̇néy⁠he֑m wa⁠yò֣̇ʼmĕr֔ẇ yĕhwáh֙ h֣ẇʼ há⁠ʼèlòhi֔ym yĕhwá֖h h֥ẇʼ há⁠ʼèlòhiֽym׃"],[18,40,"וַ⁠יֹּאמֶר֩ אֵלִיָּ֨הוּ לָ⁠הֶ֜ם תִּפְשׂ֣וּ ׀ אֶת־נְבִיאֵ֣י הַ⁠בַּ֗עַל אִ֛ישׁ אַל־יִמָּלֵ֥ט מֵ⁠הֶ֖ם וַֽ⁠יִּתְפְּשׂ֑וּ⁠ם וַ⁠יּוֹרִדֵ֤⁠ם אֵלִיָּ֨הוּ֙ אֶל־נַ֣חַל קִישׁ֔וֹן וַ⁠יִּשְׁחָטֵ֖⁠ם שָֽׁם׃","wa⁠yò̇ʼmer֩ ʼéliyá̇֨hẇ lá⁠he֜m ţi̇pĕş֣̂ẇ ׀ ʼeţ-nĕbiyʼé֣y ha⁠bȧ֗ʻal ʼi֛yş̌ ʼal-yimá̇lé֥t mé⁠he֖m waֽ⁠yi̇ţĕpĕ̇ş֑̂ẇ⁠m wa⁠ẏwòridé֤⁠m ʼéliyá̇֨hẇ֙ ʼel-na֣ẖal qiyş̌֔wòn wa⁠yi̇şĕ̌ẖáté֖⁠m şáֽ̌m׃"],[18,41,"וַ⁠יֹּ֤אמֶר אֵלִיָּ֨הוּ֙ לְ⁠אַחְאָ֔ב עֲלֵ֖ה אֱכֹ֣ל וּ⁠שְׁתֵ֑ה כִּי־ק֖וֹל הֲמ֥וֹן הַ⁠גָּֽשֶׁם׃","wa⁠yò֤̇ʼmer ʼéliyá̇֨hẇ֙ lĕ⁠ʼaẖĕʼá֔b ʻàlé֖h ʼèkò֣l ẇ⁠şĕ̌ţé֑h ki̇y-q֖wòl hàm֥wòn ha⁠gáֽ̇şěm׃"],[18,42,"וַ⁠יַּעֲלֶ֥ה אַחְאָ֖ב לֶ⁠אֱכֹ֣ל וְ⁠לִ⁠שְׁתּ֑וֹת וְ⁠אֵ֨לִיָּ֜הוּ עָלָ֨ה אֶל־רֹ֤אשׁ הַ⁠כַּרְמֶל֙ וַ⁠יִּגְהַ֣ר אַ֔רְצָ⁠ה וַ⁠יָּ֥שֶׂם פָּנָ֖י⁠ו בֵּ֥ין ברכ⁠ו׃","wa⁠yȧʻàle֥h ʼaẖĕʼá֖b le⁠ʼèkò֣l wĕ⁠li⁠şĕ̌ţ֑̇wòţ wĕ⁠ʼé֨liyá̇֜hẇ ʻálá֨h ʼel-rò֤ʼş̌ ha⁠kȧrĕmel֙ wa⁠yi̇gĕha֣r ʼa֔rĕẕá⁠h wa⁠yá֥̇şêm pá̇ná֖y⁠w bé֥̇yn brk⁠w׃"],[18,43,"וַ⁠יֹּ֣אמֶר אֶֽל־נַעֲר֗⁠וֹ עֲלֵֽה־נָא֙ הַבֵּ֣ט דֶּֽרֶךְ־יָ֔ם וַ⁠יַּ֨עַל֙ וַ⁠יַּבֵּ֔ט וַ⁠יֹּ֖אמֶר אֵ֣ין מְא֑וּמָה וַ⁠יֹּ֕אמֶר שֻׁ֖ב שֶׁ֥בַע פְּעָמִֽים׃","wa⁠yò֣̇ʼmer ʼeֽl-naʻàr֗⁠wò ʻàléֽh-náʼ֙ habé֣̇t dėֽrekĕ-yá֔m wa⁠yȧ֨ʻal֙ wa⁠yȧbé̇֔t wa⁠yò֖̇ʼmer ʼé֣yn mĕʼ֑ẇmáh wa⁠yò̇֕ʼmer şǔ֖b şě֥baʻ pĕ̇ʻámiֽym׃"],[18,44,"וַֽ⁠יְהִי֙ בַּ⁠שְּׁבִעִ֔ית וַ⁠יֹּ֗אמֶר הִנֵּה־עָ֛ב קְטַנָּ֥ה כְּ⁠כַף־אִ֖ישׁ עֹלָ֣ה מִ⁠יָּ֑ם וַ⁠יֹּ֗אמֶר עֲלֵ֨ה אֱמֹ֤ר אֶל־אַחְאָב֙ אֱסֹ֣ר וָ⁠רֵ֔ד וְ⁠לֹ֥א יַעַצָרְ⁠כָ֖ה הַ⁠גָּֽשֶׁם׃","wֽa⁠yĕhiy֙ bȧ⁠şĕ̇̌biʻi֔yţ wa⁠yò̇֗ʼmer hiné̇h-ʻá֛b qĕtaná֥̇h kĕ̇⁠kap-ʼi֖yş̌ ʻòlá֣h mi⁠yá֑̇m wa⁠yò̇֗ʼmer ʻàlé֨h ʼèmò֤r ʼel-ʼaẖĕʼáb֙ ʼèsò֣r wá⁠ré֔d wĕ⁠lò֥ʼ yaʻaẕárĕ⁠ká֖h ha⁠gáֽ̇şěm׃"],[18,45,"וַ⁠יְהִ֣י ׀ עַד־כֹּ֣ה וְ⁠עַד־כֹּ֗ה וְ⁠הַ⁠שָּׁמַ֨יִם֙ הִֽתְקַדְּרוּ֙ עָבִ֣ים וְ⁠ר֔וּחַ וַ⁠יְהִ֖י גֶּ֣שֶׁם גָּד֑וֹל וַ⁠יִּרְכַּ֥ב אַחְאָ֖ב וַ⁠יֵּ֥לֶךְ יִזְרְעֶֽאלָ⁠ה׃","wa⁠yĕhi֣y ׀ ʻad-kò֣̇h wĕ⁠ʻad-kò̇֗h wĕ⁠ha⁠şá̇̌ma֨yim֙ hiֽţĕqadĕ̇rẇ֙ ʻábi֣ym wĕ⁠r֔ẇẖa wa⁠yĕhi֖y gė֣şěm gá̇d֑wòl wa⁠yi̇rĕkȧ֥b ʼaẖĕʼá֖b wa⁠yé֥̇lekĕ yizĕrĕʻeֽʼlá⁠h׃"],[18,46,"וְ⁠יַד־יְהוָ֗ה הָֽיְתָה֙ אֶל־אֵ֣לִיָּ֔הוּ וַ⁠יְשַׁנֵּ֖ס מָתְנָ֑י⁠ו וַ⁠יָּ֨רָץ֙ לִ⁠פְנֵ֣י אַחְאָ֔ב עַד־בֹּאֲ⁠כָ֖ה יִזְרְעֶֽאלָ⁠ה׃","wĕ⁠yad-yĕhwá֗h háֽyĕţáh֙ ʼel-ʼé֣liyá̇֔hẇ wa⁠yĕşǎné֖̇s máţĕná֑y⁠w wa⁠yá̇֨ráẕ֙ li⁠pĕné֣y ʼaẖĕʼá֔b ʻad-bò̇ʼà⁠ká֖h yizĕrĕʻeֽʼlá⁠h׃"],[19,1,"וַ⁠יַּגֵּ֤ד אַחְאָב֙ לְ⁠אִיזֶ֔בֶל אֵ֛ת כָּל־אֲשֶׁ֥ר עָשָׂ֖ה אֵלִיָּ֑הוּ וְ⁠אֵ֨ת כָּל־אֲשֶׁ֥ר הָרַ֛ג אֶת־כָּל־הַ⁠נְּבִיאִ֖ים בֶּ⁠חָֽרֶב׃","wa⁠yȧgé֤̇d ʼaẖĕʼáb֙ lĕ⁠ʼiyze֔bel ʼé֛ţ ká̇l-ʼàşě֥r ʻáşá֖̂h ʼéliyá֑̇hẇ wĕ⁠ʼé֨ţ ká̇l-ʼàşě֥r hára֛g ʼeţ-ká̇l-ha⁠nĕ̇biyʼi֖ym bė⁠ẖáֽreb׃"],[19,2,"וַ⁠תִּשְׁלַ֤ח אִיזֶ֨בֶל֙ מַלְאָ֔ךְ אֶל־אֵלִיָּ֖הוּ לֵ⁠אמֹ֑ר כֹּֽה־יַעֲשׂ֤וּ⁠ן אֱלֹהִים֙ וְ⁠כֹ֣ה יוֹסִפ֔וּ⁠ן כִּֽי־כָ⁠עֵ֤ת מָחָר֙ אָשִׂ֣ים אֶֽת־נַפְשְׁ⁠ךָ֔ כְּ⁠נֶ֖פֶשׁ אַחַ֥ד מֵ⁠הֶֽם׃","wa⁠ţi̇şĕ̌la֤ẖ ʼiyze֨bel֙ malĕʼá֔kĕ ʼel-ʼéliyá֖̇hẇ lé⁠ʼmò֑r kòֽ̇h-yaʻàş֤̂ẇ⁠n ʼèlòhiym֙ wĕ⁠kò֣h ywòsip֔ẇ⁠n kiֽ̇y-ká⁠ʻé֤ţ máẖár֙ ʼáşî֣ym ʼeֽţ-napĕşĕ̌⁠ká֔ kĕ̇⁠ne֖peş̌ ʼaẖa֥d mé⁠heֽm׃"],[19,3,"וַ⁠יַּ֗רְא וַ⁠יָּ֨קָם֙ וַ⁠יֵּ֣לֶךְ אֶל־נַפְשׁ֔⁠וֹ וַ⁠יָּבֹ֕א בְּאֵ֥ר שֶׁ֖בַע אֲשֶׁ֣ר לִֽ⁠יהוּדָ֑ה וַ⁠יַּנַּ֥ח אֶֽת־נַעֲר֖⁠וֹ שָֽׁם׃","wa⁠yȧ֗rĕʼ wa⁠yá̇֨qám֙ wa⁠yé֣̇lekĕ ʼel-napĕş̌֔⁠wò wa⁠yá̇bò֕ʼ bĕ̇ʼé֥r şě֖baʻ ʼàşě֣r liֽ⁠yhẇdá֑h wa⁠yȧnȧ֥ẖ ʼeֽţ-naʻàr֖⁠wò şáֽ̌m׃"],[19,4,"וְ⁠הֽוּא־הָלַ֤ךְ בַּ⁠מִּדְבָּר֙ דֶּ֣רֶךְ י֔וֹם וַ⁠יָּבֹ֕א וַ⁠יֵּ֕שֶׁב תַּ֖חַת רֹ֣תֶם אחת וַ⁠יִּשְׁאַ֤ל אֶת־נַפְשׁ⁠וֹ֙ לָ⁠מ֔וּת וַ⁠יֹּ֣אמֶר ׀ רַ֗ב עַתָּ֤ה יְהוָה֙ קַ֣ח נַפְשִׁ֔⁠י כִּֽי־לֹא־ט֥וֹב אָנֹכִ֖י מֵ⁠אֲבֹתָֽ⁠י׃","wĕ⁠hֽẇʼ-hála֤kĕ bȧ⁠mi̇dĕbá̇r֙ dė֣rekĕ y֔wòm wa⁠yá̇bò֕ʼ wa⁠yé̇֕şěb ţȧ֖ẖaţ rò֣ţem ʼẖţ wa⁠yi̇şĕ̌ʼa֤l ʼeţ-napĕş̌⁠wò֙ lá⁠m֔ẇţ wa⁠yò֣̇ʼmer ׀ ra֗b ʻaţá֤̇h yĕhwáh֙ qa֣ẖ napĕşǐ֔⁠y kiֽ̇y-lòʼ-t֥wòb ʼánòki֖y mé⁠ʼàbòţáֽ⁠y׃"],[19,5,"וַ⁠יִּשְׁכַּב֙ וַ⁠יִּישַׁ֔ן תַּ֖חַת רֹ֣תֶם אֶחָ֑ד וְ⁠הִנֵּֽה־זֶ֤ה מַלְאָךְ֙ נֹגֵ֣עַ בּ֔⁠וֹ וַ⁠יֹּ֥אמֶר ל֖⁠וֹ ק֥וּם אֱכֽוֹל׃","wa⁠yi̇şĕ̌kȧb֙ wa⁠yi̇yşǎ֔n ţȧ֖ẖaţ rò֣ţem ʼeẖá֑d wĕ⁠hinéֽ̇h-ze֤h malĕʼákĕ֙ nògé֣ʻa ḃ֔⁠wò wa⁠yò֥̇ʼmer l֖⁠wò q֥ẇm ʼèkֽwòl׃"],[19,6,"וַ⁠יַּבֵּ֕ט וְ⁠הִנֵּ֧ה מְרַאֲשֹׁתָ֛י⁠ו עֻגַ֥ת רְצָפִ֖ים וְ⁠צַפַּ֣חַת מָ֑יִם וַ⁠יֹּ֣אכַל וַ⁠יֵּ֔שְׁתְּ וַ⁠יָּ֖שָׁב וַ⁠יִּשְׁכָּֽב׃","wa⁠yȧbé̇֕t wĕ⁠hiné֧̇h mĕraʼàşò̌ţá֛y⁠w ʻuga֥ţ rĕẕápi֖ym wĕ⁠ẕapȧ֣ẖaţ má֑yim wa⁠yò֣̇ʼkal wa⁠yé̇֔şĕ̌ţĕ̇ wa⁠yá֖̇şá̌b wa⁠yi̇şĕ̌káֽ̇b׃"],[19,7,"וַ⁠יָּשָׁב֩ מַלְאַ֨ךְ יְהוָ֤ה ׀ שֵׁנִית֙ וַ⁠יִּגַּע־בּ֔⁠וֹ וַ⁠יֹּ֖אמֶר ק֣וּם אֱכֹ֑ל כִּ֛י רַ֥ב מִמְּ⁠ךָ֖ הַ⁠דָּֽרֶךְ׃","wa⁠yá̇şá̌b֩ malĕʼa֨kĕ yĕhwá֤h ׀ şé̌niyţ֙ wa⁠yi̇gȧʻ-ḃ֔⁠wò wa⁠yò֖̇ʼmer q֣ẇm ʼèkò֑l ki֛̇y ra֥b mimĕ̇⁠ká֖ ha⁠dáֽ̇rekĕ׃"],[19,8,"וַ⁠יָּ֖קָם וַ⁠יֹּ֣אכַל וַ⁠יִּשְׁתֶּ֑ה וַ⁠יֵּ֜לֶךְ בְּ⁠כֹ֣חַ ׀ הָ⁠אֲכִילָ֣ה הַ⁠הִ֗יא אַרְבָּעִ֥ים יוֹם֙ וְ⁠אַרְבָּעִ֣ים לַ֔יְלָה עַ֛ד הַ֥ר הָ⁠אֱלֹהִ֖ים חֹרֵֽב׃","wa⁠yá֖̇qám wa⁠yò֣̇ʼkal wa⁠yi̇şĕ̌ţė֑h wa⁠yé̇֜lekĕ bĕ̇⁠kò֣ẖa ׀ há⁠ʼàkiylá֣h ha⁠hi֗yʼ ʼarĕbá̇ʻi֥ym ywòm֙ wĕ⁠ʼarĕbá̇ʻi֣ym la֔yĕláh ʻa֛d ha֥r há⁠ʼèlòhi֖ym ẖòréֽb׃"],[19,9,"וַ⁠יָּבֹא־שָׁ֥ם אֶל־הַ⁠מְּעָרָ֖ה וַ⁠יָּ֣לֶן שָׁ֑ם וְ⁠הִנֵּ֤ה דְבַר־יְהוָה֙ אֵלָ֔י⁠ו וַ⁠יֹּ֣אמֶר ל֔⁠וֹ מַה־לְּ⁠ךָ֥ פֹ֖ה אֵלִיָּֽהוּ׃","wa⁠yá̇bòʼ-şá֥̌m ʼel-ha⁠mĕ̇ʻárá֖h wa⁠yá֣̇len şá֑̌m wĕ⁠hiné֤̇h dĕbar-yĕhwáh֙ ʼélá֔y⁠w wa⁠yò֣̇ʼmer l֔⁠wò mah-lĕ̇⁠ká֥ pò֖h ʼéliyáֽ̇hẇ׃"],[19,10,"וַ⁠יֹּאמֶר֩ קַנֹּ֨א קִנֵּ֜אתִי לַ⁠יהוָ֣ה ׀ אֱלֹהֵ֣י צְבָא֗וֹת כִּֽי־עָזְב֤וּ בְרִֽיתְ⁠ךָ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֶת־מִזְבְּחֹתֶ֣י⁠ךָ הָרָ֔סוּ וְ⁠אֶת־נְבִיאֶ֖י⁠ךָ הָרְג֣וּ בֶ⁠חָ֑רֶב וָֽ⁠אִוָּתֵ֤ר אֲנִי֙ לְ⁠בַדִּ֔⁠י וַ⁠יְבַקְשׁ֥וּ אֶת־נַפְשִׁ֖⁠י לְ⁠קַחְתָּֽ⁠הּ׃","wa⁠yò̇ʼmer֩ qanò̇֨ʼ qiné̇֜ʼţiy la⁠yhwá֣h ׀ ʼèlòhé֣y ẕĕbáʼ֗wòţ kiֽ̇y-ʻázĕb֤ẇ bĕriֽyţĕ⁠ká֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼeţ-mizĕbĕ̇ẖòţe֣y⁠ká hárá֔sẇ wĕ⁠ʼeţ-nĕbiyʼe֖y⁠ká hárĕg֣ẇ be⁠ẖá֑reb wֽá⁠ʼiwá̇ţé֤r ʼàniy֙ lĕ⁠badi̇֔⁠y wa⁠yĕbaqĕş֥̌ẇ ʼeţ-napĕşǐ֖⁠y lĕ⁠qaẖĕţáֽ̇⁠ḣ׃"],[19,11,"וַ⁠יֹּ֗אמֶר צֵ֣א וְ⁠עָמַדְתָּ֣ בָ⁠הָר֮ לִ⁠פְנֵ֣י יְהוָה֒ וְ⁠הִנֵּ֧ה יְהוָ֣ה עֹבֵ֗ר וְ⁠ר֣וּחַ גְּדוֹלָ֡ה וְ⁠חָזָ֞ק מְפָרֵק֩ הָרִ֨ים וּ⁠מְשַׁבֵּ֤ר סְלָעִים֙ לִ⁠פְנֵ֣י יְהוָ֔ה לֹ֥א בָ⁠ר֖וּחַ יְהוָ֑ה וְ⁠אַחַ֤ר הָ⁠ר֨וּחַ רַ֔עַשׁ לֹ֥א בָ⁠רַ֖עַשׁ יְהוָֽה׃","wa⁠yò̇֗ʼmer ẕé֣ʼ wĕ⁠ʻámadĕţá֣̇ bá⁠hár֮ li⁠pĕné֣y yĕhwáh֒ wĕ⁠hiné֧̇h yĕhwá֣h ʻòbé֗r wĕ⁠r֣ẇẖa gĕ̇dwòlá֡h wĕ⁠ẖázá֞q mĕpáréq֩ hári֨ym ẇ⁠mĕşǎbé֤̇r sĕláʻiym֙ li⁠pĕné֣y yĕhwá֔h lò֥ʼ bá⁠r֖ẇẖa yĕhwá֑h wĕ⁠ʼaẖa֤r há⁠r֨ẇẖa ra֔ʻaş̌ lò֥ʼ bá⁠ra֖ʻaş̌ yĕhwáֽh׃"],[19,12,"וְ⁠אַחַ֤ר הָ⁠רַ֨עַשׁ֙ אֵ֔שׁ לֹ֥א בָ⁠אֵ֖שׁ יְהוָ֑ה וְ⁠אַחַ֣ר הָ⁠אֵ֔שׁ ק֖וֹל דְּמָמָ֥ה דַקָּֽה׃","wĕ⁠ʼaẖa֤r há⁠ra֨ʻaş̌֙ ʼé֔ş̌ lò֥ʼ bá⁠ʼé֖ş̌ yĕhwá֑h wĕ⁠ʼaẖa֣r há⁠ʼé֔ş̌ q֖wòl dĕ̇mámá֥h daqáֽ̇h׃"],[19,13,"וַ⁠יְהִ֣י ׀ כִּ⁠שְׁמֹ֣עַ אֵלִיָּ֗הוּ וַ⁠יָּ֤לֶט פָּנָי⁠ו֙ בְּ⁠אַדַּרְתּ֔⁠וֹ וַ⁠יֵּצֵ֕א וַֽ⁠יַּעֲמֹ֖ד פֶּ֣תַח הַ⁠מְּעָרָ֑ה וְ⁠הִנֵּ֤ה אֵלָי⁠ו֙ ק֔וֹל וַ⁠יֹּ֕אמֶר מַה־לְּ⁠ךָ֥ פֹ֖ה אֵלִיָּֽהוּ׃","wa⁠yĕhi֣y ׀ ki̇⁠şĕ̌mò֣ʻa ʼéliyá̇֗hẇ wa⁠yá֤̇let pá̇náy⁠w֙ bĕ̇⁠ʼadȧrĕţ̇֔⁠wò wa⁠yé̇ẕé֕ʼ waֽ⁠yȧʻàmò֖d pė֣ţaẖ ha⁠mĕ̇ʻárá֑h wĕ⁠hiné֤̇h ʼéláy⁠w֙ q֔wòl wa⁠yò̇֕ʼmer mah-lĕ̇⁠ká֥ pò֖h ʼéliyáֽ̇hẇ׃"],[19,14,"וַ⁠יֹּאמֶר֩ קַנֹּ֨א קִנֵּ֜אתִי לַ⁠יהוָ֣ה ׀ אֱלֹהֵ֣י צְבָא֗וֹת כִּֽי־עָזְב֤וּ בְרִֽיתְ⁠ךָ֙ בְּנֵ֣י יִשְׂרָאֵ֔ל אֶת־מִזְבְּחֹתֶ֣י⁠ךָ הָרָ֔סוּ וְ⁠אֶת־נְבִיאֶ֖י⁠ךָ הָרְג֣וּ בֶ⁠חָ֑רֶב וָ⁠אִוָּתֵ֤ר אֲנִי֙ לְ⁠בַדִּ֔⁠י וַ⁠יְבַקְשׁ֥וּ אֶת־נַפְשִׁ֖⁠י לְ⁠קַחְתָּֽ⁠הּ׃ס","wa⁠yò̇ʼmer֩ qanò̇֨ʼ qiné̇֜ʼţiy la⁠yhwá֣h ׀ ʼèlòhé֣y ẕĕbáʼ֗wòţ kiֽ̇y-ʻázĕb֤ẇ bĕriֽyţĕ⁠ká֙ bĕ̇né֣y yişĕ̂ráʼé֔l ʼeţ-mizĕbĕ̇ẖòţe֣y⁠ká hárá֔sẇ wĕ⁠ʼeţ-nĕbiyʼe֖y⁠ká hárĕg֣ẇ be⁠ẖá֑reb wá⁠ʼiwá̇ţé֤r ʼàniy֙ lĕ⁠badi̇֔⁠y wa⁠yĕbaqĕş֥̌ẇ ʼeţ-napĕşǐ֖⁠y lĕ⁠qaẖĕţáֽ̇⁠ḣ׃s"],[19,15,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלָ֔י⁠ו לֵ֛ךְ שׁ֥וּב לְ⁠דַרְכְּ⁠ךָ֖ מִדְבַּ֣רָ⁠ה דַמָּ֑שֶׂק וּ⁠בָ֗אתָ וּ⁠מָשַׁחְתָּ֧ אֶת־חֲזָאֵ֛ל לְ⁠מֶ֖לֶךְ עַל־אֲרָֽם׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼélá֔y⁠w lé֛kĕ ş֥̌ẇb lĕ⁠darĕkĕ̇⁠ká֖ midĕbȧ֣rá⁠h damá֑̇şêq ẇ⁠bá֗ʼţá ẇ⁠máşǎẖĕţá֧̇ ʼeţ-ẖàzáʼé֛l lĕ⁠me֖lekĕ ʻal-ʼàráֽm׃"],[19,16,"וְ⁠אֵת֙ יֵה֣וּא בֶן־נִמְשִׁ֔י תִּמְשַׁ֥ח לְ⁠מֶ֖לֶךְ עַל־יִשְׂרָאֵ֑ל וְ⁠אֶת־אֱלִישָׁ֤ע בֶּן־שָׁפָט֙ מֵ⁠אָבֵ֣ל מְחוֹלָ֔ה תִּמְשַׁ֥ח לְ⁠נָבִ֖יא תַּחְתֶּֽי⁠ךָ׃","wĕ⁠ʼéţ֙ yéh֣ẇʼ ben-nimĕşǐ֔y ţi̇mĕşǎ֥ẖ lĕ⁠me֖lekĕ ʻal-yişĕ̂ráʼé֑l wĕ⁠ʼeţ-ʼèliyşá֤̌ʻ bėn-şá̌pát֙ mé⁠ʼábé֣l mĕẖwòlá֔h ţi̇mĕşǎ֥ẖ lĕ⁠nábi֖yʼ ţȧẖĕţėֽy⁠ká׃"],[19,17,"וְ⁠הָיָ֗ה הַ⁠נִּמְלָ֛ט מֵ⁠חֶ֥רֶב חֲזָאֵ֖ל יָמִ֣ית יֵה֑וּא וְ⁠הַ⁠נִּמְלָ֛ט מֵ⁠חֶ֥רֶב יֵה֖וּא יָמִ֥ית אֱלִישָֽׁע׃","wĕ⁠háyá֗h ha⁠ni̇mĕlá֛t mé⁠ẖe֥reb ẖàzáʼé֖l yámi֣yţ yéh֑ẇʼ wĕ⁠ha⁠ni̇mĕlá֛t mé⁠ẖe֥reb yéh֖ẇʼ yámi֥yţ ʼèliyşáֽ̌ʻ׃"],[19,18,"וְ⁠הִשְׁאַרְתִּ֥י בְ⁠יִשְׂרָאֵ֖ל שִׁבְעַ֣ת אֲלָפִ֑ים כָּל־הַ⁠בִּרְכַּ֗יִם אֲשֶׁ֤ר לֹֽא־כָֽרְעוּ֙ לַ⁠בַּ֔עַל וְ⁠כָ֨ל־הַ⁠פֶּ֔ה אֲשֶׁ֥ר לֹֽא־נָשַׁ֖ק לֽ⁠וֹ׃","wĕ⁠hişĕ̌ʼarĕţi֥̇y bĕ⁠yişĕ̂ráʼé֖l şǐbĕʻa֣ţ ʼàlápi֑ym ká̇l-ha⁠bi̇rĕkȧ֗yim ʼàşě֤r lòֽʼ-káֽrĕʻẇ֙ la⁠bȧ֔ʻal wĕ⁠ká֨l-ha⁠pė֔h ʼàşě֥r lòֽʼ-náşǎ֖q lֽ⁠wò׃"],[19,19,"וַ⁠יֵּ֣לֶךְ מִ֠⁠שָּׁם וַ⁠יִּמְצָ֞א אֶת־אֱלִישָׁ֤ע בֶּן־שָׁפָט֙ וְ⁠ה֣וּא חֹרֵ֔שׁ שְׁנֵים־עָשָׂ֤ר צְמָדִים֙ לְ⁠פָנָ֔י⁠ו וְ⁠ה֖וּא בִּ⁠שְׁנֵ֣ים הֶ⁠עָשָׂ֑ר וַ⁠יַּעֲבֹ֤ר אֵלִיָּ֨הוּ֙ אֵלָ֔י⁠ו וַ⁠יַּשְׁלֵ֥ךְ אַדַּרְתּ֖⁠וֹ אֵלָֽי⁠ו׃","wa⁠yé֣̇lekĕ mi֠⁠şá̇̌m wa⁠yi̇mĕẕá֞ʼ ʼeţ-ʼèliyşá֤̌ʻ bėn-şá̌pát֙ wĕ⁠h֣ẇʼ ẖòré֔ş̌ şĕ̌néym-ʻáşá֤̂r ẕĕmádiym֙ lĕ⁠páná֔y⁠w wĕ⁠h֖ẇʼ bi̇⁠şĕ̌né֣ym he⁠ʻáşá֑̂r wa⁠yȧʻàbò֤r ʼéliyá̇֨hẇ֙ ʼélá֔y⁠w wa⁠yȧşĕ̌lé֥kĕ ʼadȧrĕţ֖̇⁠wò ʼéláֽy⁠w׃"],[19,20,"וַ⁠יַּעֲזֹ֣ב אֶת־הַ⁠בָּקָ֗ר וַ⁠יָּ֨רָץ֙ אַחֲרֵ֣י אֵֽלִיָּ֔הוּ וַ⁠יֹּ֗אמֶר אֶשְּׁקָה־נָּא֙ לְ⁠אָבִ֣⁠י וּ⁠לְ⁠אִמִּ֔⁠י וְ⁠אֵלְכָ֖ה אַחֲרֶ֑י⁠ךָ וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ לֵ֣ךְ שׁ֔וּב כִּ֥י מֶה־עָשִׂ֖יתִי לָֽ⁠ךְ׃","wa⁠yȧʻàzò֣b ʼeţ-ha⁠bá̇qá֗r wa⁠yá̇֨ráẕ֙ ʼaẖàré֣y ʼֽéliyá̇֔hẇ wa⁠yò̇֗ʼmer ʼeşĕ̇̌qáh-ná̇ʼ֙ lĕ⁠ʼábi֣⁠y ẇ⁠lĕ⁠ʼimi̇֔⁠y wĕ⁠ʼélĕká֖h ʼaẖàre֑y⁠ká wa⁠yò֤̇ʼmer l⁠wò֙ lé֣kĕ ş̌֔ẇb ki֥̇y meh-ʻáşî֖yţiy láֽ⁠kĕ׃"],[19,21,"וַ⁠יָּ֨שָׁב מֵ⁠אַחֲרָ֜י⁠ו וַ⁠יִּקַּ֣ח אֶת־צֶ֧מֶד הַ⁠בָּקָ֣ר וַ⁠יִּזְבָּחֵ֗⁠הוּ וּ⁠בִ⁠כְלִ֤י הַ⁠בָּקָר֙ בִּשְּׁלָ֣⁠ם הַ⁠בָּשָׂ֔ר וַ⁠יִּתֵּ֥ן לָ⁠עָ֖ם וַ⁠יֹּאכֵ֑לוּ וַ⁠יָּ֗קָם וַ⁠יֵּ֛לֶךְ אַחֲרֵ֥י אֵלִיָּ֖הוּ וַ⁠יְשָׁרְתֵֽ⁠הוּ׃פ","wa⁠yá̇֨şá̌b mé⁠ʼaẖàrá֜y⁠w wa⁠yi̇qȧ֣ẖ ʼeţ-ẕe֧med ha⁠bá̇qá֣r wa⁠yi̇zĕbá̇ẖé֗⁠hẇ ẇ⁠bi⁠kĕli֤y ha⁠bá̇qár֙ bi̇şĕ̇̌lá֣⁠m ha⁠bá̇şá̂֔r wa⁠yi̇ţé֥̇n lá⁠ʻá֖m wa⁠yò̇ʼké֑lẇ wa⁠yá̇֗qám wa⁠yé֛̇lekĕ ʼaẖàré֥y ʼéliyá֖̇hẇ wa⁠yĕşá̌rĕţéֽ⁠hẇ׃p"],[20,1,"וּ⁠בֶן־הֲדַ֣ד מֶֽלֶךְ־אֲרָ֗ם קָבַץ֙ אֶת־כָּל־חֵיל֔⁠וֹ וּ⁠שְׁלֹשִׁ֨ים וּ⁠שְׁנַ֥יִם מֶ֛לֶךְ אִתּ֖⁠וֹ וְ⁠ס֣וּס וָ⁠רָ֑כֶב וַ⁠יַּ֗עַל וַ⁠יָּ֨צַר֙ עַל־שֹׁ֣מְר֔וֹן וַ⁠יִּלָּ֖חֶם בָּֽ⁠הּ׃","ẇ⁠ben-hàda֣d meֽlekĕ-ʼàrá֗m qábaẕ֙ ʼeţ-ká̇l-ẖéyl֔⁠wò ẇ⁠şĕ̌lòşǐ֨ym ẇ⁠şĕ̌na֥yim me֛lekĕ ʼiţ֖̇⁠wò wĕ⁠s֣ẇs wá⁠rá֑keb wa⁠yȧ֗ʻal wa⁠yá̇֨ẕar֙ ʻal-şò֣̌mĕr֔wòn wa⁠yi̇lá֖̇ẖem báֽ̇⁠ḣ׃"],[20,2,"וַ⁠יִּשְׁלַ֧ח מַלְאָכִ֛ים אֶל־אַחְאָ֥ב מֶֽלֶךְ־יִשְׂרָאֵ֖ל הָ⁠עִֽירָ⁠ה׃","wa⁠yi̇şĕ̌la֧ẖ malĕʼáki֛ym ʼel-ʼaẖĕʼá֥b meֽlekĕ-yişĕ̂ráʼé֖l há⁠ʻiֽyrá⁠h׃"],[20,3,"וַ⁠יֹּ֣אמֶר ל֗⁠וֹ כֹּ֚ה אָמַ֣ר בֶּן־הֲדַ֔ד כַּסְפְּ⁠ךָ֥ וּֽ⁠זְהָבְ⁠ךָ֖ לִֽ⁠י־ה֑וּא וְ⁠נָשֶׁ֧י⁠ךָ וּ⁠בָנֶ֛י⁠ךָ הַ⁠טּוֹבִ֖ים לִ⁠י־הֵֽם׃","wa⁠yò֣̇ʼmer l֗⁠wò kò֚̇h ʼáma֣r bėn-hàda֔d kȧsĕpĕ̇⁠ká֥ ẇֽ⁠zĕhábĕ⁠ká֖ liֽ⁠y-h֑ẇʼ wĕ⁠náşě֧y⁠ká ẇ⁠báne֛y⁠ká ha⁠ṫwòbi֖ym li⁠y-héֽm׃"],[20,4,"וַ⁠יַּ֤עַן מֶֽלֶךְ־יִשְׂרָאֵל֙ וַ⁠יֹּ֔אמֶר כִּ⁠דְבָרְ⁠ךָ֖ אֲדֹנִ֣⁠י הַ⁠מֶּ֑לֶךְ לְ⁠ךָ֥ אֲנִ֖י וְ⁠כָל־אֲשֶׁר־לִֽ⁠י׃","wa⁠yȧ֤ʻan meֽlekĕ-yişĕ̂ráʼél֙ wa⁠yò̇֔ʼmer ki̇⁠dĕbárĕ⁠ká֖ ʼàdòni֣⁠y ha⁠mė֑lekĕ lĕ⁠ká֥ ʼàni֖y wĕ⁠kál-ʼàşěr-liֽ⁠y׃"],[20,5,"וַ⁠יָּשֻׁ֨בוּ֙ הַ⁠מַּלְאָכִ֔ים וַ⁠יֹּ֣אמְר֔וּ כֹּֽה־אָמַ֥ר בֶּן־הֲדַ֖ד לֵ⁠אמֹ֑ר כִּֽי־שָׁלַ֤חְתִּי אֵלֶ֨י⁠ךָ֙ לֵ⁠אמֹ֔ר כַּסְפְּ⁠ךָ֧ וּ⁠זְהָבְ⁠ךָ֛ וְ⁠נָשֶׁ֥י⁠ךָ וּ⁠בָנֶ֖י⁠ךָ לִ֥⁠י תִתֵּֽן׃","wa⁠yá̇şǔ֨bẇ֙ ha⁠mȧlĕʼáki֔ym wa⁠yò֣̇ʼmĕr֔ẇ kòֽ̇h-ʼáma֥r bėn-hàda֖d lé⁠ʼmò֑r kiֽ̇y-şá̌la֤ẖĕţi̇y ʼéle֨y⁠ká֙ lé⁠ʼmò֔r kȧsĕpĕ̇⁠ká֧ ẇ⁠zĕhábĕ⁠ká֛ wĕ⁠náşě֥y⁠ká ẇ⁠báne֖y⁠ká li֥⁠y ţiţéֽ̇n׃"],[20,6,"כִּ֣י ׀ אִם־כָּ⁠עֵ֣ת מָחָ֗ר אֶשְׁלַ֤ח אֶת־עֲבָדַ⁠י֙ אֵלֶ֔י⁠ךָ וְ⁠חִפְּשׂוּ֙ אֶת־בֵּ֣יתְ⁠ךָ֔ וְ⁠אֵ֖ת בָּתֵּ֣י עֲבָדֶ֑י⁠ךָ וְ⁠הָיָה֙ כָּל־מַחְמַ֣ד עֵינֶ֔י⁠ךָ יָשִׂ֥ימוּ בְ⁠יָדָ֖⁠ם וְ⁠לָקָֽחוּ׃","ki֣̇y ׀ ʼim-ká̇⁠ʻé֣ţ máẖá֗r ʼeşĕ̌la֤ẖ ʼeţ-ʻàbáda⁠y֙ ʼéle֔y⁠ká wĕ⁠ẖipĕ̇ş̂ẇ֙ ʼeţ-bé֣̇yţĕ⁠ká֔ wĕ⁠ʼé֖ţ bá̇ţé֣̇y ʻàbáde֑y⁠ká wĕ⁠háyáh֙ ká̇l-maẖĕma֣d ʻéyne֔y⁠ká yáşî֥ymẇ bĕ⁠yádá֖⁠m wĕ⁠láqáֽẖẇ׃"],[20,7,"וַ⁠יִּקְרָ֤א מֶֽלֶךְ־יִשְׂרָאֵל֙ לְ⁠כָל־זִקְנֵ֣י הָ⁠אָ֔רֶץ וַ⁠יֹּ֨אמֶר֙ דְּעֽוּ־נָ֣א וּ⁠רְא֔וּ כִּ֥י רָעָ֖ה זֶ֣ה מְבַקֵּ֑שׁ כִּֽי־שָׁלַ֨ח אֵלַ֜⁠י לְ⁠נָשַׁ֤⁠י וּ⁠לְ⁠בָנַ⁠י֙ וּ⁠לְ⁠כַסְפִּ֣⁠י וְ⁠לִ⁠זְהָבִ֔⁠י וְ⁠לֹ֥א מָנַ֖עְתִּי מִמֶּֽ⁠נּוּ׃","wa⁠yi̇qĕrá֤ʼ meֽlekĕ-yişĕ̂ráʼél֙ lĕ⁠kál-ziqĕné֣y há⁠ʼá֔reẕ wa⁠yò̇֨ʼmer֙ dĕ̇ʻֽẇ-ná֣ʼ ẇ⁠rĕʼ֔ẇ ki֥̇y ráʻá֖h ze֣h mĕbaqé֑̇ş̌ kiֽ̇y-şá̌la֨ẖ ʼéla֜⁠y lĕ⁠náşǎ֤⁠y ẇ⁠lĕ⁠bána⁠y֙ ẇ⁠lĕ⁠kasĕpi֣̇⁠y wĕ⁠li⁠zĕhábi֔⁠y wĕ⁠lò֥ʼ mána֖ʻĕţi̇y mimėֽ⁠ṅẇ׃"],[20,8,"וַ⁠יֹּאמְר֥וּ אֵלָ֛י⁠ו כָּל־הַ⁠זְּקֵנִ֖ים וְ⁠כָל־הָ⁠עָ֑ם אַל־תִּשְׁמַ֖ע וְ⁠ל֥וֹא תֹאבֶֽה׃","wa⁠yò̇ʼmĕr֥ẇ ʼélá֛y⁠w ká̇l-ha⁠zĕ̇qéni֖ym wĕ⁠kál-há⁠ʻá֑m ʼal-ţi̇şĕ̌ma֖ʻ wĕ⁠l֥wòʼ ţòʼbeֽh׃"],[20,9,"וַ⁠יֹּ֜אמֶר לְ⁠מַלְאֲכֵ֣י בֶן־הֲדַ֗ד אִמְר֞וּ לַֽ⁠אדֹנִ֤⁠י הַ⁠מֶּ֨לֶךְ֙ כֹּל֩ אֲשֶׁר־שָׁלַ֨חְתָּ אֶל־עַבְדְּ⁠ךָ֤ בָ⁠רִֽאשֹׁנָה֙ אֶעֱשֶׂ֔ה וְ⁠הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה לֹ֥א אוּכַ֖ל לַ⁠עֲשׂ֑וֹת וַ⁠יֵּֽלְכוּ֙ הַ⁠מַּלְאָכִ֔ים וַ⁠יְשִׁבֻ֖⁠הוּ דָּבָֽר׃","wa⁠yò̇֜ʼmer lĕ⁠malĕʼàké֣y ben-hàda֗d ʼimĕr֞ẇ laֽ⁠ʼdòni֤⁠y ha⁠mė֨lekĕ֙ kò̇l֩ ʼàşěr-şá̌la֨ẖĕţá̇ ʼel-ʻabĕdĕ̇⁠ká֤ bá⁠riֽʼşò̌náh֙ ʼeʻèşê֔h wĕ⁠ha⁠dá̇bá֣r ha⁠zė֔h lò֥ʼ ʼẇka֖l la⁠ʻàş֑̂wòţ wa⁠yéֽ̇lĕkẇ֙ ha⁠mȧlĕʼáki֔ym wa⁠yĕşǐbu֖⁠hẇ dá̇báֽr׃"],[20,10,"וַ⁠יִּשְׁלַ֤ח אֵלָי⁠ו֙ בֶּן־הֲדַ֔ד וַ⁠יֹּ֕אמֶר כֹּֽה־יַעֲשׂ֥וּ⁠ן לִ֛⁠י אֱלֹהִ֖ים וְ⁠כֹ֣ה יוֹסִ֑פוּ אִם־יִשְׂפֹּק֙ עֲפַ֣ר שֹׁמְר֔וֹן לִ⁠שְׁעָלִ֕ים לְ⁠כָל־הָ⁠עָ֖ם אֲשֶׁ֥ר בְּ⁠רַגְלָֽ⁠י׃","wa⁠yi̇şĕ̌la֤ẖ ʼéláy⁠w֙ bėn-hàda֔d wa⁠yò̇֕ʼmer kòֽ̇h-yaʻàş֥̂ẇ⁠n li֛⁠y ʼèlòhi֖ym wĕ⁠kò֣h ywòsi֑pẇ ʼim-yişĕ̂pò̇q֙ ʻàpa֣r şò̌mĕr֔wòn li⁠şĕ̌ʻáli֕ym lĕ⁠kál-há⁠ʻá֖m ʼàşě֥r bĕ̇⁠ragĕláֽ⁠y׃"],[20,11,"וַ⁠יַּ֤עַן מֶֽלֶךְ־יִשְׂרָאֵל֙ וַ⁠יֹּ֣אמֶר דַּבְּר֔וּ אַל־יִתְהַלֵּ֥ל חֹגֵ֖ר כִּ⁠מְפַתֵּֽחַ׃","wa⁠yȧ֤ʻan meֽlekĕ-yişĕ̂ráʼél֙ wa⁠yò֣̇ʼmer dȧbĕ̇r֔ẇ ʼal-yiţĕhalé֥̇l ẖògé֖r ki̇⁠mĕpaţéֽ̇ẖa׃"],[20,12,"וַ⁠יְהִ֗י כִּ⁠שְׁמֹ֨עַ֙ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֔ה וְ⁠ה֥וּא שֹׁתֶ֛ה ה֥וּא וְ⁠הַ⁠מְּלָכִ֖ים בַּ⁠סֻּכּ֑וֹת וַ⁠יֹּ֤אמֶר אֶל־עֲבָדָי⁠ו֙ שִׂ֔ימוּ וַ⁠יָּשִׂ֖ימוּ עַל־הָ⁠עִֽיר׃","wa⁠yĕhi֗y ki̇⁠şĕ̌mò֨ʻa֙ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֔h wĕ⁠h֥ẇʼ şò̌ţe֛h h֥ẇʼ wĕ⁠ha⁠mĕ̇láki֖ym bȧ⁠su̇k֑̇wòţ wa⁠yò֤̇ʼmer ʼel-ʻàbádáy⁠w֙ şî֔ymẇ wa⁠yá̇şî֖ymẇ ʻal-há⁠ʻiֽyr׃"],[20,13,"וְ⁠הִנֵּ֣ה ׀ נָבִ֣יא אֶחָ֗ד נִגַּשׁ֮ אֶל־אַחְאָ֣ב מֶֽלֶךְ־יִשְׂרָאֵל֒ וַ⁠יֹּ֗אמֶר כֹּ֚ה אָמַ֣ר יְהוָ֔ה הְֽ⁠רָאִ֔יתָ אֵ֛ת כָּל־הֶ⁠הָמ֥וֹן הַ⁠גָּד֖וֹל הַ⁠זֶּ֑ה הִנְ⁠נִ֨י נֹתְנ֤⁠וֹ בְ⁠יָֽדְ⁠ךָ֙ הַ⁠יּ֔וֹם וְ⁠יָדַעְתָּ֖ כִּֽי־אֲנִ֥י יְהוָֽה׃","wĕ⁠hiné֣̇h ׀ nábi֣yʼ ʼeẖá֗d nigȧş֮̌ ʼel-ʼaẖĕʼá֣b meֽlekĕ-yişĕ̂ráʼél֒ wa⁠yò̇֗ʼmer kò֚̇h ʼáma֣r yĕhwá֔h hĕֽ⁠ráʼi֔yţá ʼé֛ţ ká̇l-he⁠hám֥wòn ha⁠gá̇d֖wòl ha⁠zė֑h hinĕ⁠ni֨y nòţĕn֤⁠wò bĕ⁠yáֽdĕ⁠ká֙ ha⁠ẏ֔wòm wĕ⁠yádaʻĕţá֖̇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[20,14,"וַ⁠יֹּ֤אמֶר אַחְאָב֙ בְּ⁠מִ֔י וַ⁠יֹּ֨אמֶר֙ כֹּֽה־אָמַ֣ר יְהוָ֔ה בְּ⁠נַעֲרֵ֖י שָׂרֵ֣י הַ⁠מְּדִינ֑וֹת וַ⁠יֹּ֛אמֶר מִֽי־יֶאְסֹ֥ר הַ⁠מִּלְחָמָ֖ה וַ⁠יֹּ֥אמֶר אָֽתָּה׃","wa⁠yò֤̇ʼmer ʼaẖĕʼáb֙ bĕ̇⁠mi֔y wa⁠yò̇֨ʼmer֙ kòֽ̇h-ʼáma֣r yĕhwá֔h bĕ̇⁠naʻàré֖y şá̂ré֣y ha⁠mĕ̇diyn֑wòţ wa⁠yò֛̇ʼmer miֽy-yeʼĕsò֥r ha⁠mi̇lĕẖámá֖h wa⁠yò֥̇ʼmer ʼáֽţá̇h׃"],[20,15,"וַ⁠יִּפְקֹ֗ד אֶֽת־נַעֲרֵי֙ שָׂרֵ֣י הַ⁠מְּדִינ֔וֹת וַ⁠יִּהְי֕וּ מָאתַ֖יִם שְׁנַ֣יִם וּ⁠שְׁלֹשִׁ֑ים וְ⁠אַחֲרֵי⁠הֶ֗ם פָּקַ֧ד אֶת־כָּל־הָ⁠עָ֛ם כָּל־בְּנֵ֥י יִשְׂרָאֵ֖ל שִׁבְעַ֥ת אֲלָפִֽים׃","wa⁠yi̇pĕqò֗d ʼeֽţ-naʻàréy֙ şá̂ré֣y ha⁠mĕ̇diyn֔wòţ wa⁠yi̇hĕy֕ẇ máʼţa֖yim şĕ̌na֣yim ẇ⁠şĕ̌lòşǐ֑ym wĕ⁠ʼaẖàréy⁠he֗m pá̇qa֧d ʼeţ-ká̇l-há⁠ʻá֛m ká̇l-bĕ̇né֥y yişĕ̂ráʼé֖l şǐbĕʻa֥ţ ʼàlápiֽym׃"],[20,16,"וַ⁠יֵּצְא֖וּ בַּֽ⁠צָּהֳרָ֑יִם וּ⁠בֶן־הֲדַד֩ שֹׁתֶ֨ה שִׁכּ֜וֹר בַּ⁠סֻּכּ֗וֹת ה֧וּא וְ⁠הַ⁠מְּלָכִ֛ים שְׁלֹשִֽׁים־וּ⁠שְׁנַ֥יִם מֶ֖לֶךְ עֹזֵ֥ר אֹתֽ⁠וֹ׃","wa⁠yé̇ẕĕʼ֖ẇ bȧֽ⁠ẕá̇horá֑yim ẇ⁠ben-hàdad֩ şò̌ţe֨h şǐk̇֜wòr bȧ⁠su̇k̇֗wòţ h֧ẇʼ wĕ⁠ha⁠mĕ̇láki֛ym şĕ̌lòşǐֽym-ẇ⁠şĕ̌na֥yim me֖lekĕ ʻòzé֥r ʼòţֽ⁠wò׃"],[20,17,"וַ⁠יֵּצְא֗וּ נַעֲרֵ֛י שָׂרֵ֥י הַ⁠מְּדִינ֖וֹת בָּ⁠רִֽאשֹׁנָ֑ה וַ⁠יִּשְׁלַ֣ח בֶּן־הֲדַ֗ד וַ⁠יַּגִּ֤ידוּ ל⁠וֹ֙ לֵ⁠אמֹ֔ר אֲנָשִׁ֕ים יָצְא֖וּ מִ⁠שֹּׁמְרֽוֹן׃","wa⁠yé̇ẕĕʼ֗ẇ naʻàré֛y şá̂ré֥y ha⁠mĕ̇diyn֖wòţ bá̇⁠riֽʼşò̌ná֑h wa⁠yi̇şĕ̌la֣ẖ bėn-hàda֗d wa⁠yȧgi֤̇ydẇ l⁠wò֙ lé⁠ʼmò֔r ʼànáşǐ֕ym yáẕĕʼ֖ẇ mi⁠şò̇̌mĕrֽwòn׃"],[20,18,"וַ⁠יֹּ֛אמֶר אִם־לְ⁠שָׁל֥וֹם יָצָ֖אוּ תִּפְשׂ֣וּ⁠ם חַיִּ֑ים וְ⁠אִ֧ם לְ⁠מִלְחָמָ֛ה יָצָ֖אוּ חַיִּ֥ים תִּפְשֽׂוּ⁠ם׃","wa⁠yò֛̇ʼmer ʼim-lĕ⁠şá̌l֥wòm yáẕá֖ʼẇ ţi̇pĕş֣̂ẇ⁠m ẖayi֑̇ym wĕ⁠ʼi֧m lĕ⁠milĕẖámá֛h yáẕá֖ʼẇ ẖayi֥̇ym ţi̇pĕşֽ̂ẇ⁠m׃"],[20,19,"וְ⁠אֵ֨לֶּה֙ יָצְא֣וּ מִן־הָ⁠עִ֔יר נַעֲרֵ֖י שָׂרֵ֣י הַ⁠מְּדִינ֑וֹת וְ⁠הַ⁠חַ֖יִל אֲשֶׁ֥ר אַחֲרֵי⁠הֶֽם׃","wĕ⁠ʼé֨lėh֙ yáẕĕʼ֣ẇ min-há⁠ʻi֔yr naʻàré֖y şá̂ré֣y ha⁠mĕ̇diyn֑wòţ wĕ⁠ha⁠ẖa֖yil ʼàşě֥r ʼaẖàréy⁠heֽm׃"],[20,20,"וַ⁠יַּכּוּ֙ אִ֣ישׁ אִישׁ֔⁠וֹ וַ⁠יָּנֻ֣סוּ אֲרָ֔ם וַֽ⁠יִּרְדְּפֵ֖⁠ם יִשְׂרָאֵ֑ל וַ⁠יִּמָּלֵ֗ט בֶּן־הֲדַד֙ מֶ֣לֶךְ אֲרָ֔ם עַל־ס֖וּס וּ⁠פָרָשִֽׁים׃","wa⁠yȧk̇ẇ֙ ʼi֣yş̌ ʼiyş̌֔⁠wò wa⁠yá̇nu֣sẇ ʼàrá֔m waֽ⁠yi̇rĕdĕ̇pé֖⁠m yişĕ̂ráʼé֑l wa⁠yi̇má̇lé֗t bėn-hàdad֙ me֣lekĕ ʼàrá֔m ʻal-s֖ẇs ẇ⁠páráşǐֽym׃"],[20,21,"וַ⁠יֵּצֵא֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַ⁠יַּ֥ךְ אֶת־הַ⁠סּ֖וּס וְ⁠אֶת־הָ⁠רָ֑כֶב וְ⁠הִכָּ֥ה בַ⁠אֲרָ֖ם מַכָּ֥ה גְדוֹלָֽה׃","wa⁠yé̇ẕéʼ֙ me֣lekĕ yişĕ̂ráʼé֔l wa⁠yȧ֥kĕ ʼeţ-ha⁠ṡ֖ẇs wĕ⁠ʼeţ-há⁠rá֑keb wĕ⁠hiká֥̇h ba⁠ʼàrá֖m maká֥̇h gĕdwòláֽh׃"],[20,22,"וַ⁠יִּגַּ֤שׁ הַ⁠נָּבִיא֙ אֶל־מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ לֵ֣ךְ הִתְחַזַּ֔ק וְ⁠דַ֥ע וּ⁠רְאֵ֖ה אֵ֣ת אֲשֶֽׁר־תַּעֲשֶׂ֑ה כִּ֚י לִ⁠תְשׁוּבַ֣ת הַ⁠שָּׁנָ֔ה מֶ֥לֶךְ אֲרָ֖ם עֹלֶ֥ה עָלֶֽי⁠ךָ׃ס","wa⁠yi̇gȧ֤ş̌ ha⁠ná̇biyʼ֙ ʼel-me֣lekĕ yişĕ̂ráʼé֔l wa⁠yò֤̇ʼmer l⁠wò֙ lé֣kĕ hiţĕẖazȧ֔q wĕ⁠da֥ʻ ẇ⁠rĕʼé֖h ʼé֣ţ ʼàşěֽr-ţȧʻàşê֑h ki֚̇y li⁠ţĕş̌ẇba֣ţ ha⁠şá̇̌ná֔h me֥lekĕ ʼàrá֖m ʻòle֥h ʻáleֽy⁠ká׃s"],[20,23,"וְ⁠עַבְדֵ֨י מֶֽלֶךְ־אֲרָ֜ם אָמְר֣וּ אֵלָ֗י⁠ו אֱלֹהֵ֤י הָרִים֙ אֱלֹ֣הֵי⁠הֶ֔ם עַל־כֵּ֖ן חָזְק֣וּ מִמֶּ֑⁠נּוּ וְ⁠אוּלָ֗ם נִלָּחֵ֤ם אִתָּ⁠ם֙ בַּ⁠מִּישׁ֔וֹר אִם־לֹ֥א נֶחֱזַ֖ק מֵ⁠הֶֽם׃","wĕ⁠ʻabĕdé֨y meֽlekĕ-ʼàrá֜m ʼámĕr֣ẇ ʼélá֗y⁠w ʼèlòhé֤y háriym֙ ʼèlò֣héy⁠he֔m ʻal-ké֖̇n ẖázĕq֣ẇ mimė֑⁠ṅẇ wĕ⁠ʼẇlá֗m nilá̇ẖé֤m ʼiţá̇⁠m֙ bȧ⁠mi̇yş̌֔wòr ʼim-lò֥ʼ neẖèza֖q mé⁠heֽm׃"],[20,24,"וְ⁠אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּ֖ה עֲשֵׂ֑ה הָסֵ֤ר הַ⁠מְּלָכִים֙ אִ֣ישׁ מִ⁠מְּקֹמ֔⁠וֹ וְ⁠שִׂ֥ים פַּח֖וֹת תַּחְתֵּי⁠הֶֽם׃","wĕ⁠ʼeţ-ha⁠dá̇bá֥r ha⁠zė֖h ʻàşé֑̂h hásé֤r ha⁠mĕ̇lákiym֙ ʼi֣yş̌ mi⁠mĕ̇qòm֔⁠wò wĕ⁠şî֥ym pȧẖ֖wòţ ţȧẖĕţé̇y⁠heֽm׃"],[20,25,"וְ⁠אַתָּ֣ה תִֽמְנֶה־לְ⁠ךָ֣ ׀ חַ֡יִל כַּ⁠חַיִל֩ הַ⁠נֹּפֵ֨ל מֵ⁠אוֹתָ֜⁠ךְ וְ⁠ס֣וּס כַּ⁠סּ֣וּס ׀ וְ⁠רֶ֣כֶב כָּ⁠רֶ֗כֶב וְ⁠נִֽלָּחֲמָ֤ה אוֹתָ⁠ם֙ בַּ⁠מִּישׁ֔וֹר אִם־לֹ֥א נֶחֱזַ֖ק מֵ⁠הֶ֑ם וַ⁠יִּשְׁמַ֥ע לְ⁠קֹלָ֖⁠ם וַ⁠יַּ֥עַשׂ כֵּֽן׃פ","wĕ⁠ʼaţá֣̇h ţiֽmĕneh-lĕ⁠ká֣ ׀ ẖa֡yil kȧ⁠ẖayil֩ ha⁠nò̇pé֨l mé⁠ʼwòţá֜⁠kĕ wĕ⁠s֣ẇs kȧ⁠ṡ֣ẇs ׀ wĕ⁠re֣keb ká̇⁠re֗keb wĕ⁠niֽlá̇ẖàmá֤h ʼwòţá⁠m֙ bȧ⁠mi̇yş̌֔wòr ʼim-lò֥ʼ neẖèza֖q mé⁠he֑m wa⁠yi̇şĕ̌ma֥ʻ lĕ⁠qòlá֖⁠m wa⁠yȧ֥ʻaş̂ kéֽ̇n׃p"],[20,26,"וַֽ⁠יְהִי֙ לִ⁠תְשׁוּבַ֣ת הַ⁠שָּׁנָ֔ה וַ⁠יִּפְקֹ֥ד בֶּן־הֲדַ֖ד אֶת־אֲרָ֑ם וַ⁠יַּ֣עַל אֲפֵ֔קָ⁠ה לַ⁠מִּלְחָמָ֖ה עִם־יִשְׂרָאֵֽל׃","waֽ⁠yĕhiy֙ li⁠ţĕş̌ẇba֣ţ ha⁠şá̇̌ná֔h wa⁠yi̇pĕqò֥d bėn-hàda֖d ʼeţ-ʼàrá֑m wa⁠yȧ֣ʻal ʼàpé֔qá⁠h la⁠mi̇lĕẖámá֖h ʻim-yişĕ̂ráʼéֽl׃"],[20,27,"וּ⁠בְנֵ֣י יִשְׂרָאֵ֗ל הָתְפָּקְדוּ֙ וְ⁠כָלְכְּל֔וּ וַ⁠יֵּלְכ֖וּ לִ⁠קְרָאתָ֑⁠ם וַ⁠יַּחֲנ֨וּ בְנֵֽי־יִשְׂרָאֵ֜ל נֶגְדָּ֗⁠ם כִּ⁠שְׁנֵי֙ חֲשִׂפֵ֣י עִזִּ֔ים וַ⁠אֲרָ֖ם מִלְא֥וּ אֶת־הָ⁠אָֽרֶץ׃","ẇ⁠bĕné֣y yişĕ̂ráʼé֗l háţĕpá̇qĕdẇ֙ wĕ⁠kálĕkĕ̇l֔ẇ wa⁠yé̇lĕk֖ẇ li⁠qĕráʼţá֑⁠m wa⁠yȧẖàn֨ẇ bĕnéֽy-yişĕ̂ráʼé֜l negĕdá̇֗⁠m ki̇⁠şĕ̌néy֙ ẖàşîpé֣y ʻizi̇֔ym wa⁠ʼàrá֖m milĕʼ֥ẇ ʼeţ-há⁠ʼáֽreẕ׃"],[20,28,"וַ⁠יִּגַּ֞שׁ אִ֣ישׁ הָ⁠אֱלֹהִ֗ים וַ⁠יֹּאמֶר֮ אֶל־מֶ֣לֶךְ יִשְׂרָאֵל֒ וַ⁠יֹּ֜אמֶר כֹּֽה־אָמַ֣ר יְהוָ֗ה יַ֠עַן אֲשֶׁ֨ר אָמְר֤וּ אֲרָם֙ אֱלֹהֵ֤י הָרִים֙ יְהוָ֔ה וְ⁠לֹֽא־אֱלֹהֵ֥י עֲמָקִ֖ים ה֑וּא וְ֠⁠נָתַתִּי אֶת־כָּל־הֶ⁠הָמ֨וֹן הַ⁠גָּ֤דוֹל הַ⁠זֶּה֙ בְּ⁠יָדֶ֔⁠ךָ וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃","wa⁠yi̇gȧ֞ş̌ ʼi֣yş̌ há⁠ʼèlòhi֗ym wa⁠yò̇ʼmer֮ ʼel-me֣lekĕ yişĕ̂ráʼél֒ wa⁠yò̇֜ʼmer kòֽ̇h-ʼáma֣r yĕhwá֗h ya֠ʻan ʼàşě֨r ʼámĕr֤ẇ ʼàrám֙ ʼèlòhé֤y háriym֙ yĕhwá֔h wĕ⁠lòֽʼ-ʼèlòhé֥y ʻàmáqi֖ym h֑ẇʼ wĕ֠⁠náţaţi̇y ʼeţ-ká̇l-he⁠hám֨wòn ha⁠gá֤̇dwòl ha⁠zėh֙ bĕ̇⁠yáde֔⁠ká wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[20,29,"וַֽ⁠יַּחֲנ֧וּ אֵ֦לֶּה נֹ֥כַח אֵ֖לֶּה שִׁבְעַ֣ת יָמִ֑ים וַ⁠יְהִ֣י ׀ בַּ⁠יּ֣וֹם הַ⁠שְּׁבִיעִ֗י וַ⁠תִּקְרַב֙ הַ⁠מִּלְחָמָ֔ה וַ⁠יַּכּ֨וּ בְנֵֽי־יִשְׂרָאֵ֧ל אֶת־אֲרָ֛ם מֵאָה־אֶ֥לֶף רַגְלִ֖י בְּ⁠י֥וֹם אֶחָֽד׃","waֽ⁠yȧẖàn֧ẇ ʼé֦lėh nò֥kaẖ ʼé֖lėh şǐbĕʻa֣ţ yámi֑ym wa⁠yĕhi֣y ׀ bȧ⁠ẏ֣wòm ha⁠şĕ̇̌biyʻi֗y wa⁠ţi̇qĕrab֙ ha⁠mi̇lĕẖámá֔h wa⁠yȧk̇֨ẇ bĕnéֽy-yişĕ̂ráʼé֧l ʼeţ-ʼàrá֛m méʼáh-ʼe֥lep ragĕli֖y bĕ̇⁠y֥wòm ʼeẖáֽd׃"],[20,30,"וַ⁠יָּנֻ֨סוּ הַ⁠נּוֹתָרִ֥ים ׀ אֲפֵקָ⁠ה֮ אֶל־הָ⁠עִיר֒ וַ⁠תִּפֹּל֙ הַ⁠חוֹמָ֔ה עַל־עֶשְׂרִ֨ים וְ⁠שִׁבְעָ֥ה אֶ֛לֶף אִ֖ישׁ הַ⁠נּוֹתָרִ֑ים וּ⁠בֶן־הֲדַ֣ד נָ֔ס וַ⁠יָּבֹ֥א אֶל־הָ⁠עִ֖יר חֶ֥דֶר בְּ⁠חָֽדֶר׃ס","wa⁠yá̇nu֨sẇ ha⁠ṅwòţári֥ym ׀ ʼàpéqá⁠h֮ ʼel-há⁠ʻiyr֒ wa⁠ţi̇pò̇l֙ ha⁠ẖwòmá֔h ʻal-ʻeşĕ̂ri֨ym wĕ⁠şǐbĕʻá֥h ʼe֛lep ʼi֖yş̌ ha⁠ṅwòţári֑ym ẇ⁠ben-hàda֣d ná֔s wa⁠yá̇bò֥ʼ ʼel-há⁠ʻi֖yr ẖe֥der bĕ̇⁠ẖáֽder׃s"],[20,31,"וַ⁠יֹּאמְר֣וּ אֵלָי⁠ו֮ עֲבָדָי⁠ו֒ הִנֵּֽה־נָ֣א שָׁמַ֔עְנוּ כִּ֗י מַלְכֵי֙ בֵּ֣ית יִשְׂרָאֵ֔ל כִּֽי־מַלְכֵ֥י חֶ֖סֶד הֵ֑ם נָשִׂ֣ימָה נָּא֩ שַׂקִּ֨ים בְּ⁠מָתְנֵ֜י⁠נוּ וַ⁠חֲבָלִ֣ים בְּ⁠רֹאשֵׁ֗⁠נוּ וְ⁠נֵצֵא֙ אֶל־מֶ֣לֶךְ יִשְׂרָאֵ֔ל אוּלַ֖י יְחַיֶּ֥ה אֶת־נַפְשֶֽׁ⁠ךָ׃","wa⁠yò̇ʼmĕr֣ẇ ʼéláy⁠w֮ ʻàbádáy⁠w֒ hinéֽ̇h-ná֣ʼ şá̌ma֔ʻĕnẇ ki̇֗y malĕkéy֙ bé֣̇yţ yişĕ̂ráʼé֔l kiֽ̇y-malĕké֥y ẖe֖sed hé֑m náşî֣ymáh ná̇ʼ֩ şâqi̇֨ym bĕ̇⁠máţĕné֜y⁠nẇ wa⁠ẖàbáli֣ym bĕ̇⁠ròʼşé̌֗⁠nẇ wĕ⁠néẕéʼ֙ ʼel-me֣lekĕ yişĕ̂ráʼé֔l ʼẇla֖y yĕẖayė֥h ʼeţ-napĕşěֽ⁠ká׃"],[20,32,"וַ⁠יַּחְגְּרוּ֩ שַׂקִּ֨ים בְּ⁠מָתְנֵי⁠הֶ֜ם וַ⁠חֲבָלִ֣ים בְּ⁠רָאשֵׁי⁠הֶ֗ם וַ⁠יָּבֹ֨אוּ֙ אֶל־מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַ⁠יֹּ֣אמְר֔וּ עַבְדְּ⁠ךָ֧ בֶן־הֲדַ֛ד אָמַ֖ר תְּחִֽי־נָ֣א נַפְשִׁ֑⁠י וַ⁠יֹּ֛אמֶר הַ⁠עוֹדֶ֥⁠נּוּ חַ֖י אָחִ֥⁠י הֽוּא׃","wa⁠yȧẖĕgĕ̇rẇ֩ şâqi̇֨ym bĕ̇⁠máţĕnéy⁠he֜m wa⁠ẖàbáli֣ym bĕ̇⁠ráʼşé̌y⁠he֗m wa⁠yá̇bò֨ʼẇ֙ ʼel-me֣lekĕ yişĕ̂ráʼé֔l wa⁠yò֣̇ʼmĕr֔ẇ ʻabĕdĕ̇⁠ká֧ ben-hàda֛d ʼáma֖r ţĕ̇ẖiֽy-ná֣ʼ napĕşǐ֑⁠y wa⁠yò֛̇ʼmer ha⁠ʻwòde֥⁠ṅẇ ẖa֖y ʼáẖi֥⁠y hֽẇʼ׃"],[20,33,"וְ⁠הָ⁠אֲנָשִׁים֩ יְנַחֲשׁ֨וּ וַֽ⁠יְמַהֲר֜וּ וַ⁠יַּחְלְט֣וּ הֲ⁠מִמֶּ֗⁠נּוּ וַ⁠יֹּֽאמְרוּ֙ אָחִ֣י⁠ךָ בֶן־הֲדַ֔ד וַ⁠יֹּ֖אמֶר בֹּ֣אוּ קָחֻ֑⁠הוּ וַ⁠יֵּצֵ֤א אֵלָי⁠ו֙ בֶּן־הֲדַ֔ד וַֽ⁠יַּעֲלֵ֖⁠הוּ עַל־הַ⁠מֶּרְכָּבָֽה׃","wĕ⁠há⁠ʼànáşǐym֩ yĕnaẖàş̌֨ẇ waֽ⁠yĕmahàr֜ẇ wa⁠yȧẖĕlĕt֣ẇ hà⁠mimė֗⁠ṅẇ wa⁠yòֽ̇ʼmĕrẇ֙ ʼáẖi֣y⁠ká ben-hàda֔d wa⁠yò֖̇ʼmer bò֣̇ʼẇ qáẖu֑⁠hẇ wa⁠yé̇ẕé֤ʼ ʼéláy⁠w֙ bėn-hàda֔d wֽa⁠yȧʻàlé֖⁠hẇ ʻal-ha⁠mėrĕká̇báֽh׃"],[20,34,"וַ⁠יֹּ֣אמֶר אֵלָ֡י⁠ו הֶ⁠עָרִ֣ים אֲשֶׁר־לָֽקַח־אָבִ⁠י֩ מֵ⁠אֵ֨ת אָבִ֜י⁠ךָ אָשִׁ֗יב וְ֠⁠חוּצוֹת תָּשִׂ֨ים לְ⁠ךָ֤ בְ⁠דַמֶּ֨שֶׂק֙ כַּ⁠אֲשֶׁר־שָׂ֤ם אָבִ⁠י֙ בְּ⁠שֹׁ֣מְר֔וֹן וַ⁠אֲנִ֖י בַּ⁠בְּרִ֣ית אֲשַׁלְּחֶ֑⁠ךָּ וַ⁠יִּכְרָת־ל֥⁠וֹ בְרִ֖ית וַֽ⁠יְשַׁלְּחֵֽ⁠הוּ׃ס","wa⁠yò֣̇ʼmer ʼélá֡y⁠w he⁠ʻári֣ym ʼàşěr-láֽqaẖ-ʼábi⁠y֩ mé⁠ʼé֨ţ ʼábi֜y⁠ká ʼáşǐ֗yb wĕ֠⁠ẖẇẕwòţ ţá̇şî֨ym lĕ⁠ká֤ bĕ⁠damė֨şêq֙ kȧ⁠ʼàşěr-şá֤̂m ʼábi⁠y֙ bĕ̇⁠şò֣̌mĕr֔wòn wa⁠ʼàni֖y bȧ⁠bĕ̇ri֣yţ ʼàşǎlĕ̇ẖe֑⁠ká̇ wa⁠yi̇kĕráţ-l֥⁠wò bĕri֖yţ waֽ⁠yĕşǎlĕ̇ẖéֽ⁠hẇ׃s"],[20,35,"וְ⁠אִ֨ישׁ אֶחָ֜ד מִ⁠בְּנֵ֣י הַ⁠נְּבִיאִ֗ים אָמַ֧ר אֶל־רֵעֵ֛⁠הוּ בִּ⁠דְבַ֥ר יְהוָ֖ה הַכֵּ֣י⁠נִי נָ֑א וַ⁠יְמָאֵ֥ן הָ⁠אִ֖ישׁ לְ⁠הַכֹּתֽ⁠וֹ׃","wĕ⁠ʼi֨yş̌ ʼeẖá֜d mi⁠bĕ̇né֣y ha⁠nĕ̇biyʼi֗ym ʼáma֧r ʼel-réʻé֛⁠hẇ bi̇⁠dĕba֥r yĕhwá֖h haké֣̇y⁠niy ná֑ʼ wa⁠yĕmáʼé֥n há⁠ʼi֖yş̌ lĕ⁠hakò̇ţֽ⁠wò׃"],[20,36,"וַ⁠יֹּ֣אמֶר ל֗⁠וֹ יַ֚עַן אֲשֶׁ֤ר לֹֽא־שָׁמַ֨עְתָּ֙ בְּ⁠ק֣וֹל יְהוָ֔ה הִנְּ⁠ךָ֤ הוֹלֵךְ֙ מֵֽ⁠אִתִּ֔⁠י וְ⁠הִכְּ⁠ךָ֖ הָ⁠אַרְיֵ֑ה וַ⁠יֵּ֨לֶךְ֙ מֵֽ⁠אֶצְל֔⁠וֹ וַ⁠יִּמְצָאֵ֥⁠הוּ הָ⁠אַרְיֵ֖ה וַ⁠יַּכֵּֽ⁠הוּ׃","wa⁠yò֣̇ʼmer l֗⁠wò ya֚ʻan ʼàşě֤r lòֽʼ-şá̌ma֨ʻĕţá̇֙ bĕ̇⁠q֣wòl yĕhwá֔h hinĕ̇⁠ká֤ hwòlékĕ֙ méֽ⁠ʼiţi̇֔⁠y wĕ⁠hikĕ̇⁠ká֖ há⁠ʼarĕyé֑h wa⁠yé̇֨lekĕ֙ méֽ⁠ʼeẕĕl֔⁠wò wa⁠yi̇mĕẕáʼé֥⁠hẇ há⁠ʼarĕyé֖h wa⁠yȧkéֽ̇⁠hẇ׃"],[20,37,"וַ⁠יִּמְצָא֙ אִ֣ישׁ אַחֵ֔ר וַ⁠יֹּ֖אמֶר הַכֵּ֣י⁠נִי נָ֑א וַ⁠יַּכֵּ֥⁠הוּ הָ⁠אִ֖ישׁ הַכֵּ֥ה וּ⁠פָצֹֽעַ׃","wa⁠yi̇mĕẕáʼ֙ ʼi֣yş̌ ʼaẖé֔r wa⁠yò֖̇ʼmer haké֣̇y⁠niy ná֑ʼ wa⁠yȧké֥̇⁠hẇ há⁠ʼi֖yş̌ haké֥̇h ẇ⁠páẕòֽʻa׃"],[20,38,"וַ⁠יֵּ֨לֶךְ֙ הַ⁠נָּבִ֔יא וַ⁠יַּעֲמֹ֥ד לַ⁠מֶּ֖לֶךְ עַל־הַ⁠דָּ֑רֶךְ וַ⁠יִּתְחַפֵּ֥שׂ בָּ⁠אֲפֵ֖ר עַל־עֵינָֽי⁠ו׃","wa⁠yé̇֨lekĕ֙ ha⁠ná̇bi֔yʼ wa⁠yȧʻàmò֥d la⁠mė֖lekĕ ʻal-ha⁠dá֑̇rekĕ wa⁠yi̇ţĕẖapé֥̇ş̂ bá̇⁠ʼàpé֖r ʻal-ʻéynáֽy⁠w׃"],[20,39,"וַ⁠יְהִ֤י הַ⁠מֶּ֨לֶךְ֙ עֹבֵ֔ר וְ⁠ה֖וּא צָעַ֣ק אֶל־הַ⁠מֶּ֑לֶךְ וַ⁠יֹּ֜אמֶר עַבְדְּ⁠ךָ֣ ׀ יָצָ֣א בְ⁠קֶֽרֶב־הַ⁠מִּלְחָמָ֗ה וְ⁠הִנֵּֽה־אִ֨ישׁ סָ֜ר וַ⁠יָּבֵ֧א אֵלַ֣⁠י אִ֗ישׁ וַ⁠יֹּ֨אמֶר֙ שְׁמֹר֙ אֶת־הָ⁠אִ֣ישׁ הַ⁠זֶּ֔ה אִם־הִפָּקֵד֙ יִפָּקֵ֔ד וְ⁠הָיְתָ֤ה נַפְשְׁ⁠ךָ֙ תַּ֣חַת נַפְשׁ֔⁠וֹ א֥וֹ כִכַּר־כֶּ֖סֶף תִּשְׁקֽוֹל׃","wa⁠yĕhi֤y ha⁠mė֨lekĕ֙ ʻòbé֔r wĕ⁠h֖ẇʼ ẕáʻa֣q ʼel-ha⁠mė֑lekĕ wa⁠yò̇֜ʼmer ʻabĕdĕ̇⁠ká֣ ׀ yáẕá֣ʼ bĕ⁠qeֽreb-ha⁠mi̇lĕẖámá֗h wĕ⁠hinéֽ̇h-ʼi֨yş̌ sá֜r wa⁠yá̇bé֧ʼ ʼéla֣⁠y ʼi֗yş̌ wa⁠yò̇֨ʼmer֙ şĕ̌mòr֙ ʼeţ-há⁠ʼi֣yş̌ ha⁠zė֔h ʼim-hipá̇qéd֙ yipá̇qé֔d wĕ⁠háyĕţá֤h napĕşĕ̌⁠ká֙ ţȧ֣ẖaţ napĕş̌֔⁠wò ʼ֥wò kikȧr-kė֖sep ţi̇şĕ̌qֽwòl׃"],[20,40,"וַ⁠יְהִ֣י עַבְדְּ⁠ךָ֗ עֹשֵׂ֥ה הֵ֛נָּה וָ⁠הֵ֖נָּה וְ⁠ה֣וּא אֵינֶ֑⁠נּוּ וַ⁠יֹּ֨אמֶר אֵלָ֧י⁠ו מֶֽלֶךְ־יִשְׂרָאֵ֛ל כֵּ֥ן מִשְׁפָּטֶ֖⁠ךָ אַתָּ֥ה חָרָֽצְתָּ׃","wa⁠yĕhi֣y ʻabĕdĕ̇⁠ká֗ ʻòşé֥̂h hé֛ná̇h wá⁠hé֖ná̇h wĕ⁠h֣ẇʼ ʼéyne֑⁠ṅẇ wa⁠yò̇֨ʼmer ʼélá֧y⁠w meֽlekĕ-yişĕ̂ráʼé֛l ké֥̇n mişĕ̌pá̇te֖⁠ká ʼaţá֥̇h ẖáráֽẕĕţá̇׃"],[20,41,"וַ⁠יְמַהֵ֕ר וַ⁠יָּ֨סַר֙ אֶת־הָ֣⁠אֲפֵ֔ר מ⁠על עֵינָ֑י⁠ו וַ⁠יַּכֵּ֤ר אֹת⁠וֹ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל כִּ֥י מֵֽ⁠הַ⁠נְּבִאִ֖ים הֽוּא׃","wa⁠yĕmahé֕r wa⁠yá̇֨sar֙ ʼeţ-há֣⁠ʼàpé֔r m⁠ʻl ʻéyná֑y⁠w wa⁠yȧké֤̇r ʼòţ⁠wò֙ me֣lekĕ yişĕ̂ráʼé֔l ki֥̇y méֽ⁠ha⁠nĕ̇biʼi֖ym hֽẇʼ׃"],[20,42,"וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר יְהוָ֔ה יַ֛עַן שִׁלַּ֥חְתָּ אֶת־אִישׁ־חֶרְמִ֖⁠י מִ⁠יָּ֑ד וְ⁠הָיְתָ֤ה נַפְשְׁ⁠ךָ֙ תַּ֣חַת נַפְשׁ֔⁠וֹ וְ⁠עַמְּ⁠ךָ֖ תַּ֥חַת עַמּֽ⁠וֹ׃","wa⁠yò֣̇ʼmer ʼélá֗y⁠w kò֚̇h ʼáma֣r yĕhwá֔h ya֛ʻan şǐlȧ֥ẖĕţá̇ ʼeţ-ʼiyş̌-ẖerĕmi֖⁠y mi⁠yá֑̇d wĕ⁠háyĕţá֤h napĕşĕ̌⁠ká֙ ţȧ֣ẖaţ napĕş̌֔⁠wò wĕ⁠ʻamĕ̇⁠ká֖ ţȧ֥ẖaţ ʻaṁֽ⁠wò׃"],[20,43,"וַ⁠יֵּ֧לֶךְ מֶֽלֶךְ־יִשְׂרָאֵ֛ל עַל־בֵּית֖⁠וֹ סַ֣ר וְ⁠זָעֵ֑ף וַ⁠יָּבֹ֖א שֹׁמְרֽוֹנָ⁠ה׃פ","wa⁠yé֧̇lekĕ meֽlekĕ-yişĕ̂ráʼé֛l ʻal-bé̇yţ֖⁠wò sa֣r wĕ⁠záʻé֑p wa⁠yá̇bò֖ʼ şò̌mĕrֽwòná⁠h׃p"],[21,1,"וַ⁠יְהִ֗י אַחַר֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה כֶּ֧רֶם הָיָ֛ה לְ⁠נָב֥וֹת הַ⁠יִּזְרְעֵאלִ֖י אֲשֶׁ֣ר בְּ⁠יִזְרְעֶ֑אל אֵ֚צֶל הֵיכַ֣ל אַחְאָ֔ב מֶ֖לֶךְ שֹׁמְרֽוֹן׃","wa⁠yĕhi֗y ʼaẖar֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh kė֧rem háyá֛h lĕ⁠náb֥wòţ ha⁠yi̇zĕrĕʻéʼli֖y ʼàşě֣r bĕ̇⁠yizĕrĕʻe֑ʼl ʼé֚ẕel héyka֣l ʼaẖĕʼá֔b me֖lekĕ şò̌mĕrֽwòn׃"],[21,2,"וַ⁠יְדַבֵּ֣ר אַחְאָ֣ב אֶל־נָב֣וֹת ׀ לֵ⁠אמֹר֩ ׀ תְּנָ⁠ה־לִּ֨⁠י אֶֽת־כַּרְמְ⁠ךָ֜ וִֽ⁠יהִי־לִ֣⁠י לְ⁠גַן־יָרָ֗ק כִּ֣י ה֤וּא קָרוֹב֙ אֵ֣צֶל בֵּיתִ֔⁠י וְ⁠אֶתְּנָ֤ה לְ⁠ךָ֙ תַּחְתָּ֔י⁠ו כֶּ֖רֶם ט֣וֹב מִמֶּ֑⁠נּוּ אִ֚ם ט֣וֹב בְּ⁠עֵינֶ֔י⁠ךָ אֶתְּנָה־לְ⁠ךָ֥ כֶ֖סֶף מְחִ֥יר זֶֽה׃","wa⁠yĕdabé֣̇r ʼaẖĕʼá֣b ʼel-náb֣wòţ ׀ lé⁠ʼmòr֩ ׀ ţĕ̇ná⁠h-li̇֨⁠y ʼeֽţ-kȧrĕmĕ⁠ká֜ wiֽ⁠yhiy-li֣⁠y lĕ⁠gan-yárá֗q ki֣̇y h֤ẇʼ qárwòb֙ ʼé֣ẕel bé̇yţi֔⁠y wĕ⁠ʼeţĕ̇ná֤h lĕ⁠ká֙ ţȧẖĕţá̇֔y⁠w kė֖rem t֣wòb mimė֑⁠ṅẇ ʼi֚m t֣wòb bĕ̇⁠ʻéyne֔y⁠ká ʼeţĕ̇náh-lĕ⁠ká֥ ke֖sep mĕẖi֥yr zeֽh׃"],[21,3,"וַ⁠יֹּ֥אמֶר נָב֖וֹת אֶל־אַחְאָ֑ב חָלִ֤ילָ⁠ה לִּ⁠י֙ מֵֽ⁠יהוָ֔ה מִ⁠תִּתִּ֛⁠י אֶת־נַחֲלַ֥ת אֲבֹתַ֖⁠י לָֽ⁠ךְ׃","wa⁠yò֥̇ʼmer náb֖wòţ ʼel-ʼaẖĕʼá֑b ẖáli֤ylá⁠h li̇⁠y֙ méֽ⁠yhwá֔h mi⁠ţi̇ţi֛̇⁠y ʼeţ-naẖàla֥ţ ʼàbòţa֖⁠y láֽ⁠kĕ׃"],[21,4,"וַ⁠יָּבֹא֩ אַחְאָ֨ב אֶל־בֵּית֜⁠וֹ סַ֣ר וְ⁠זָעֵ֗ף עַל־הַ⁠דָּבָר֙ אֲשֶׁר־דִּבֶּ֣ר אֵלָ֗י⁠ו נָבוֹת֙ הַ⁠יִּזְרְעֵאלִ֔י וַ⁠יֹּ֕אמֶר לֹֽא־אֶתֵּ֥ן לְ⁠ךָ֖ אֶת־נַחֲלַ֣ת אֲבוֹתָ֑⁠י וַ⁠יִּשְׁכַּב֙ עַל־מִטָּת֔⁠וֹ וַ⁠יַּסֵּ֥ב אֶת־פָּנָ֖י⁠ו וְ⁠לֹֽא־אָ֥כַל לָֽחֶם׃","wa⁠yá̇bòʼ֩ ʼaẖĕʼá֨b ʼel-bé̇yţ֜⁠wò sa֣r wĕ⁠záʻé֗p ʻal-ha⁠dá̇bár֙ ʼàşěr-di̇bė֣r ʼélá֗y⁠w nábwòţ֙ ha⁠yi̇zĕrĕʻéʼli֔y wa⁠yò̇֕ʼmer lòֽʼ-ʼeţé֥̇n lĕ⁠ká֖ ʼeţ-naẖàla֣ţ ʼàbwòţá֑⁠y wa⁠yi̇şĕ̌kȧb֙ ʻal-mitá̇ţ֔⁠wò wa⁠yȧsé֥̇b ʼeţ-pá̇ná֖y⁠w wĕ⁠lòֽʼ-ʼá֥kal láֽẖem׃"],[21,5,"וַ⁠תָּבֹ֥א אֵלָ֖י⁠ו אִיזֶ֣בֶל אִשְׁתּ֑⁠וֹ וַ⁠תְּדַבֵּ֣ר אֵלָ֗י⁠ו מַה־זֶּה֙ רוּחֲ⁠ךָ֣ סָרָ֔ה וְ⁠אֵינְ⁠ךָ֖ אֹכֵ֥ל לָֽחֶם׃","wa⁠ţá̇bò֥ʼ ʼélá֖y⁠w ʼiyze֣bel ʼişĕ̌ţ֑̇⁠wò wa⁠ţĕ̇dabé֣̇r ʼélá֗y⁠w mah-zėh֙ rẇẖà⁠ká֣ sárá֔h wĕ⁠ʼéynĕ⁠ká֖ ʼòké֥l láֽẖem׃"],[21,6,"וַ⁠יְדַבֵּ֣ר אֵלֶ֗י⁠הָ כִּֽי־אֲ֠דַבֵּר אֶל־נָב֨וֹת הַ⁠יִּזְרְעֵאלִ֜י וָ⁠אֹ֣מַר ל֗⁠וֹ תְּנָ⁠ה־לִּ֤⁠י אֶֽת־כַּרְמְ⁠ךָ֙ בְּ⁠כֶ֔סֶף א֚וֹ אִם־חָפֵ֣ץ אַתָּ֔ה אֶתְּנָה־לְ⁠ךָ֥ כֶ֖רֶם תַּחְתָּ֑י⁠ו וַ⁠יֹּ֕אמֶר לֹֽא־אֶתֵּ֥ן לְ⁠ךָ֖ אֶת־כַּרְמִֽ⁠י׃","wa⁠yĕdabé֣̇r ʼéle֗y⁠há kiֽ̇y-ʼà֠dabé̇r ʼel-náb֨wòţ ha⁠yi̇zĕrĕʻéʼli֜y wá⁠ʼò֣mar l֗⁠wò ţĕ̇ná⁠h-li֤̇⁠y ʼeֽţ-kȧrĕmĕ⁠ká֙ bĕ̇⁠ke֔sep ʼ֚wò ʼim-ẖápé֣ẕ ʼaţá̇֔h ʼeţĕ̇náh-lĕ⁠ká֥ ke֖rem ţȧẖĕţá֑̇y⁠w wa⁠yò̇֕ʼmer lòֽʼ-ʼeţé֥̇n lĕ⁠ká֖ ʼeţ-kȧrĕmiֽ⁠y׃"],[21,7,"וַ⁠תֹּ֤אמֶר אֵלָי⁠ו֙ אִיזֶ֣בֶל אִשְׁתּ֔⁠וֹ אַתָּ֕ה עַתָּ֛ה תַּעֲשֶׂ֥ה מְלוּכָ֖ה עַל־יִשְׂרָאֵ֑ל ק֤וּם אֱכָל־לֶ֨חֶם֙ וְ⁠יִטַ֣ב לִבֶּ֔⁠ךָ אֲנִי֙ אֶתֵּ֣ן לְ⁠ךָ֔ אֶת־כֶּ֖רֶם נָב֥וֹת הַ⁠יִּזְרְעֵאלִֽי׃","wa⁠ţò֤̇ʼmer ʼéláy⁠w֙ ʼiyze֣bel ʼişĕ̌ţ̇֔⁠wò ʼaţá̇֕h ʻaţá֛̇h ţȧʻàşê֥h mĕlẇká֖h ʻal-yişĕ̂ráʼé֑l q֤ẇm ʼèkál-le֨ẖem֙ wĕ⁠yita֣b libė֔⁠ká ʼàniy֙ ʼeţé֣̇n lĕ⁠ká֔ ʼeţ-kė֖rem náb֥wòţ ha⁠yi̇zĕrĕʻéʼliֽy׃"],[21,8,"וַ⁠תִּכְתֹּ֤ב סְפָרִים֙ בְּ⁠שֵׁ֣ם אַחְאָ֔ב וַ⁠תַּחְתֹּ֖ם בְּ⁠חֹתָמ֑⁠וֹ וַ⁠תִּשְׁלַ֣ח ה⁠ספרים אֶל־הַ⁠זְקֵנִ֤ים וְ⁠אֶל־הַֽ⁠חֹרִים֙ אֲשֶׁ֣ר בְּ⁠עִיר֔⁠וֹ הַ⁠יֹּשְׁבִ֖ים אֶת־נָבֽוֹת׃","wa⁠ţi̇kĕţò֤̇b sĕpáriym֙ bĕ̇⁠şé֣̌m ʼaẖĕʼá֔b wa⁠ţȧẖĕţò֖̇m bĕ̇⁠ẖòţám֑⁠wò wa⁠ţi̇şĕ̌la֣ẖ h⁠sprym ʼel-ha⁠zĕqéni֤ym wĕ⁠ʼel-haֽ⁠ẖòriym֙ ʼàşě֣r bĕ̇⁠ʻiyr֔⁠wò ha⁠yò̇şĕ̌bi֖ym ʼeţ-nábֽwòţ׃"],[21,9,"וַ⁠תִּכְתֹּ֥ב בַּ⁠סְּפָרִ֖ים לֵ⁠אמֹ֑ר קִֽרְאוּ־צ֔וֹם וְ⁠הוֹשִׁ֥יבוּ אֶת־נָב֖וֹת בְּ⁠רֹ֥אשׁ הָ⁠עָֽם׃","wa⁠ţi̇kĕţò֥̇b bȧ⁠sĕ̇pári֖ym lé⁠ʼmò֑r qiֽrĕʼẇ-ẕ֔wòm wĕ⁠hwòşǐ֥ybẇ ʼeţ-náb֖wòţ bĕ̇⁠rò֥ʼş̌ há⁠ʻáֽm׃"],[21,10,"וְ֠⁠הוֹשִׁיבוּ שְׁנַ֨יִם אֲנָשִׁ֥ים בְּנֵֽי־בְלִיַּעַל֮ נֶגְדּ⁠וֹ֒ וִ⁠יעִדֻ֣⁠הוּ לֵ⁠אמֹ֔ר בֵּרַ֥כְתָּ אֱלֹהִ֖ים וָ⁠מֶ֑לֶךְ וְ⁠הוֹצִיאֻ֥⁠הוּ וְ⁠סִקְלֻ֖⁠הוּ וְ⁠יָמֹֽת׃","wĕ֠⁠hwòşǐybẇ şĕ̌na֨yim ʼànáşǐ֥ym bĕ̇néֽy-bĕliyȧʻal֮ negĕḋ⁠wò֒ wi⁠yʻidu֣⁠hẇ lé⁠ʼmò֔r bé̇ra֥kĕţá̇ ʼèlòhi֖ym wá⁠me֑lekĕ wĕ⁠hwòẕiyʼu֥⁠hẇ wĕ⁠siqĕlu֖⁠hẇ wĕ⁠yámòֽţ׃"],[21,11,"וַ⁠יַּעֲשׂוּ֩ אַנְשֵׁ֨י עִיר֜⁠וֹ הַ⁠זְּקֵנִ֣ים וְ⁠הַ⁠חֹרִ֗ים אֲשֶׁ֤ר הַ⁠יֹּֽשְׁבִים֙ בְּ⁠עִיר֔⁠וֹ כַּ⁠אֲשֶׁ֛ר שָׁלְחָ֥ה אֲלֵי⁠הֶ֖ם אִיזָ֑בֶל כַּ⁠אֲשֶׁ֤ר כָּתוּב֙ בַּ⁠סְּפָרִ֔ים אֲשֶׁ֥ר שָׁלְחָ֖ה אֲלֵי⁠הֶֽם׃","wa⁠yȧʻàş̂ẇ֩ ʼanĕşé̌֨y ʻiyr֜⁠wò ha⁠zĕ̇qéni֣ym wĕ⁠ha⁠ẖòri֗ym ʼàşě֤r ha⁠yòֽ̇şĕ̌biym֙ bĕ̇⁠ʻiyr֔⁠wò kȧ⁠ʼàşě֛r şá̌lĕẖá֥h ʼàléy⁠he֖m ʼiyzá֑bel kȧ⁠ʼàşě֤r ká̇ţẇb֙ bȧ⁠sĕ̇pári֔ym ʼàşě֥r şá̌lĕẖá֖h ʼàléy⁠heֽm׃"],[21,12,"קָרְא֖וּ צ֑וֹם וְ⁠הֹשִׁ֥יבוּ אֶת־נָב֖וֹת בְּ⁠רֹ֥אשׁ הָ⁠עָֽם׃","qárĕʼ֖ẇ ẕ֑wòm wĕ⁠hòşǐ֥ybẇ ʼeţ-náb֖wòţ bĕ̇⁠rò֥ʼş̌ há⁠ʻáֽm׃"],[21,13,"וַ֠⁠יָּבֹאוּ שְׁנֵ֨י הָ⁠אֲנָשִׁ֥ים בְּנֵֽי־בְלִיַּעַל֮ וַ⁠יֵּשְׁב֣וּ נֶגְדּ⁠וֹ֒ וַ⁠יְעִדֻ⁠הוּ֩ אַנְשֵׁ֨י הַ⁠בְּלִיַּ֜עַל אֶת־נָב֗וֹת נֶ֤גֶד הָ⁠עָם֙ לֵ⁠אמֹ֔ר בֵּרַ֥ךְ נָב֛וֹת אֱלֹהִ֖ים וָ⁠מֶ֑לֶךְ וַ⁠יֹּצִאֻ֨⁠הוּ֙ מִ⁠ח֣וּץ לָ⁠עִ֔יר וַ⁠יִּסְקְלֻ֥⁠הוּ בָ⁠אֲבָנִ֖ים וַ⁠יָּמֹֽת׃","wa֠⁠yá̇bòʼẇ şĕ̌né֨y há⁠ʼànáşǐ֥ym bĕ̇néֽy-bĕliyȧʻal֮ wa⁠yé̇şĕ̌b֣ẇ negĕḋ⁠wò֒ wa⁠yĕʻidu⁠hẇ֩ ʼanĕşé̌֨y ha⁠bĕ̇liyȧ֜ʻal ʼeţ-náb֗wòţ ne֤ged há⁠ʻám֙ lé⁠ʼmò֔r bé̇ra֥kĕ náb֛wòţ ʼèlòhi֖ym wá⁠me֑lekĕ wa⁠yò̇ẕiʼu֨⁠hẇ֙ mi⁠ẖ֣ẇẕ lá⁠ʻi֔yr wa⁠yi̇sĕqĕlu֥⁠hẇ bá⁠ʼàbáni֖ym wa⁠yá̇mòֽţ׃"],[21,14,"וַֽ⁠יִּשְׁלְח֖וּ אֶל־אִיזֶ֣בֶל לֵ⁠אמֹ֑ר סֻקַּ֥ל נָב֖וֹת וַ⁠יָּמֹֽת׃","waֽ⁠yi̇şĕ̌lĕẖ֖ẇ ʼel-ʼiyze֣bel lé⁠ʼmò֑r suqȧ֥l náb֖wòţ wa⁠yá̇mòֽţ׃"],[21,15,"וַֽ⁠יְהִי֙ כִּ⁠שְׁמֹ֣עַ אִיזֶ֔בֶל כִּֽי־סֻקַּ֥ל נָב֖וֹת וַ⁠יָּמֹ֑ת וַ⁠תֹּ֨אמֶר אִיזֶ֜בֶל אֶל־אַחְאָ֗ב ק֣וּם רֵ֞שׁ אֶת־כֶּ֣רֶם ׀ נָב֣וֹת הַ⁠יִּזְרְעֵאלִ֗י אֲשֶׁ֤ר מֵאֵן֙ לָ⁠תֶת־לְ⁠ךָ֣ בְ⁠כֶ֔סֶף כִּ֣י אֵ֥ין נָב֛וֹת חַ֖י כִּי־מֵֽת׃","waֽ⁠yĕhiy֙ ki̇⁠şĕ̌mò֣ʻa ʼiyze֔bel kiֽ̇y-suqȧ֥l náb֖wòţ wa⁠yá̇mò֑ţ wa⁠ţò̇֨ʼmer ʼiyze֜bel ʼel-ʼaẖĕʼá֗b q֣ẇm ré֞ş̌ ʼeţ-kė֣rem ׀ náb֣wòţ ha⁠yi̇zĕrĕʻéʼli֗y ʼàşě֤r méʼén֙ lá⁠ţeţ-lĕ⁠ká֣ bĕ⁠ke֔sep ki֣̇y ʼé֥yn náb֛wòţ ẖa֖y ki̇y-méֽţ׃"],[21,16,"וַ⁠יְהִ֛י כִּ⁠שְׁמֹ֥עַ אַחְאָ֖ב כִּ֣י מֵ֣ת נָב֑וֹת וַ⁠יָּ֣קָם אַחְאָ֗ב לָ⁠רֶ֛דֶת אֶל־כֶּ֛רֶם נָב֥וֹת הַ⁠יִּזְרְעֵאלִ֖י לְ⁠רִשְׁתּֽ⁠וֹ׃ס","wa⁠yĕhi֛y ki̇⁠şĕ̌mò֥ʻa ʼaẖĕʼá֖b ki֣̇y mé֣ţ náb֑wòţ wa⁠yá֣̇qám ʼaẖĕʼá֗b lá⁠re֛deţ ʼel-kė֛rem náb֥wòţ ha⁠yi̇zĕrĕʻéʼli֖y lĕ⁠rişĕ̌ţֽ̇⁠wò׃s"],[21,17,"וַ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־אֵלִיָּ֥הוּ הַ⁠תִּשְׁבִּ֖י לֵ⁠אמֹֽר׃","wa⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-ʼéliyá֥̇hẇ ha⁠ţi̇şĕ̌bi֖̇y lé⁠ʼmòֽr׃"],[21,18,"ק֣וּם רֵ֗ד לִ⁠קְרַ֛את אַחְאָ֥ב מֶֽלֶךְ־יִשְׂרָאֵ֖ל אֲשֶׁ֣ר בְּ⁠שֹׁמְר֑וֹן הִנֵּה֙ בְּ⁠כֶ֣רֶם נָב֔וֹת אֲשֶׁר־יָ֥רַד שָׁ֖ם לְ⁠רִשְׁתּֽ⁠וֹ׃","q֣ẇm ré֗d li⁠qĕra֛ʼţ ʼaẖĕʼá֥b meֽlekĕ-yişĕ̂ráʼé֖l ʼàşě֣r bĕ̇⁠şò̌mĕr֑wòn hiné̇h֙ bĕ̇⁠ke֣rem náb֔wòţ ʼàşěr-yá֥rad şá֖̌m lĕ⁠rişĕ̌ţֽ̇⁠wò׃"],[21,19,"וְ⁠דִבַּרְתָּ֨ אֵלָ֜י⁠ו לֵ⁠אמֹ֗ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה הֲ⁠רָצַ֖חְתָּ וְ⁠גַם־יָרָ֑שְׁתָּ וְ⁠דִבַּרְתָּ֨ אֵלָ֜י⁠ו לֵ⁠אמֹ֗ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה בִּ⁠מְק֗וֹם אֲשֶׁ֨ר לָקְק֤וּ הַ⁠כְּלָבִים֙ אֶת־דַּ֣ם נָב֔וֹת יָלֹ֧קּוּ הַ⁠כְּלָבִ֛ים אֶת־דָּמְ⁠ךָ֖ גַּם־אָֽתָּה׃","wĕ⁠dibȧrĕţá̇֨ ʼélá֜y⁠w lé⁠ʼmò֗r kò֚̇h ʼáma֣r yĕhwá֔h hà⁠ráẕa֖ẖĕţá̇ wĕ⁠gam-yárá֑şĕ̌ţá̇ wĕ⁠dibȧrĕţá̇֨ ʼélá֜y⁠w lé⁠ʼmò֗r kò֚̇h ʼáma֣r yĕhwá֔h bi̇⁠mĕq֗wòm ʼàşě֨r láqĕq֤ẇ ha⁠kĕ̇lábiym֙ ʼeţ-dȧ֣m náb֔wòţ yálò֧q̇ẇ ha⁠kĕ̇lábi֛ym ʼeţ-dá̇mĕ⁠ká֖ gȧm-ʼáֽţá̇h׃"],[21,20,"וַ⁠יֹּ֤אמֶר אַחְאָב֙ אֶל־אֵ֣לִיָּ֔הוּ הַֽ⁠מְצָאתַ֖⁠נִי אֹיְבִ֑⁠י וַ⁠יֹּ֣אמֶר מָצָ֔אתִי יַ֚עַן הִתְמַכֶּרְ⁠ךָ֔ לַ⁠עֲשׂ֥וֹת הָ⁠רַ֖ע בְּ⁠עֵינֵ֥י יְהוָֽה׃","wa⁠yò֤̇ʼmer ʼaẖĕʼáb֙ ʼel-ʼé֣liyá̇֔hẇ haֽ⁠mĕẕáʼţa֖⁠niy ʼòyĕbi֑⁠y wa⁠yò֣̇ʼmer máẕá֔ʼţiy ya֚ʻan hiţĕmakėrĕ⁠ká֔ la⁠ʻàş֥̂wòţ há⁠ra֖ʻ bĕ̇⁠ʻéyné֥y yĕhwáֽh׃"],[21,21,"הִנְ⁠נִ֨י מבי אֵלֶ֨י⁠ךָ֙ רָעָ֔ה וּ⁠בִעַרְתִּ֖י אַחֲרֶ֑י⁠ךָ וְ⁠הִכְרַתִּ֤י לְ⁠אַחְאָב֙ מַשְׁתִּ֣ין בְּ⁠קִ֔יר וְ⁠עָצ֥וּר וְ⁠עָז֖וּב בְּ⁠יִשְׂרָאֵֽל׃","hinĕ⁠ni֨y mby ʼéle֨y⁠ká֙ ráʻá֔h ẇ⁠biʻarĕţi֖̇y ʼaẖàre֑y⁠ká wĕ⁠hikĕraţi֤̇y lĕ⁠ʼaẖĕʼáb֙ maşĕ̌ţi֣̇yn bĕ̇⁠qi֔yr wĕ⁠ʻáẕ֥ẇr wĕ⁠ʻáz֖ẇb bĕ̇⁠yişĕ̂ráʼéֽl׃"],[21,22,"וְ⁠נָתַתִּ֣י אֶת־בֵּיתְ⁠ךָ֗ כְּ⁠בֵית֙ יָרָבְעָ֣ם בֶּן־נְבָ֔ט וּ⁠כְ⁠בֵ֖ית בַּעְשָׁ֣א בֶן־אֲחִיָּ֑ה אֶל־הַ⁠כַּ֨עַס֙ אֲשֶׁ֣ר הִכְעַ֔סְתָּ וַֽ⁠תַּחֲטִ֖א אֶת־יִשְׂרָאֵֽל׃","wĕ⁠náţaţi֣̇y ʼeţ-bé̇yţĕ⁠ká֗ kĕ̇⁠béyţ֙ yárábĕʻá֣m bėn-nĕbá֔t ẇ⁠kĕ⁠bé֖yţ bȧʻĕşá֣̌ʼ ben-ʼàẖiyá֑̇h ʼel-ha⁠kȧ֨ʻas֙ ʼàşě֣r hikĕʻa֔sĕţá̇ waֽ⁠ţȧẖàti֖ʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[21,23,"וְ⁠גַ֨ם־לְ⁠אִיזֶ֔בֶל דִּבֶּ֥ר יְהוָ֖ה לֵ⁠אמֹ֑ר הַ⁠כְּלָבִ֛ים יֹאכְל֥וּ אֶת־אִיזֶ֖בֶל בְּ⁠חֵ֥ל יִזְרְעֶֽאל׃","wĕ⁠ga֨m-lĕ⁠ʼiyze֔bel di̇bė֥r yĕhwá֖h lé⁠ʼmò֑r ha⁠kĕ̇lábi֛ym yòʼkĕl֥ẇ ʼeţ-ʼiyze֖bel bĕ̇⁠ẖé֥l yizĕrĕʻeֽʼl׃"],[21,24,"הַ⁠מֵּ֤ת לְ⁠אַחְאָב֙ בָּ⁠עִ֔יר יֹאכְל֖וּ הַ⁠כְּלָבִ֑ים וְ⁠הַ⁠מֵּת֙ בַּ⁠שָּׂדֶ֔ה יֹאכְל֖וּ ע֥וֹף הַ⁠שָּׁמָֽיִם׃","ha⁠mé֤̇ţ lĕ⁠ʼaẖĕʼáb֙ bá̇⁠ʻi֔yr yòʼkĕl֖ẇ ha⁠kĕ̇lábi֑ym wĕ⁠ha⁠mé̇ţ֙ bȧ⁠şá̇̂de֔h yòʼkĕl֖ẇ ʻ֥wòp ha⁠şá̇̌máֽyim׃"],[21,25,"רַ֚ק לֹֽא־הָיָ֣ה כְ⁠אַחְאָ֔ב אֲשֶׁ֣ר הִתְמַכֵּ֔ר לַ⁠עֲשׂ֥וֹת הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה אֲשֶׁר־הֵסַ֥תָּה אֹת֖⁠וֹ אִיזֶ֥בֶל אִשְׁתּֽ⁠וֹ׃","ra֚q lòֽʼ-háyá֣h kĕ⁠ʼaẖĕʼá֔b ʼàşě֣r hiţĕmaké̇֔r la⁠ʻàş֥̂wòţ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h ʼàşěr-hésa֥ţá̇h ʼòţ֖⁠wò ʼiyze֥bel ʼişĕ̌ţֽ̇⁠wò׃"],[21,26,"וַ⁠יַּתְעֵ֣ב מְאֹ֔ד לָ⁠לֶ֖כֶת אַחֲרֵ֣י הַ⁠גִּלֻּלִ֑ים כְּ⁠כֹל֙ אֲשֶׁ֣ר עָשׂ֣וּ הָ⁠אֱמֹרִ֔י אֲשֶׁר֙ הוֹרִ֣ישׁ יְהוָ֔ה מִ⁠פְּנֵ֖י בְּנֵ֥י יִשְׂרָאֵֽל׃ס","wa⁠yȧţĕʻé֣b mĕʼò֔d lá⁠le֖keţ ʼaẖàré֣y ha⁠gi̇lu̇li֑ym kĕ̇⁠kòl֙ ʼàşě֣r ʻáş֣̂ẇ há⁠ʼèmòri֔y ʼàşěr֙ hwòri֣yş̌ yĕhwá֔h mi⁠pĕ̇né֖y bĕ̇né֥y yişĕ̂ráʼéֽl׃s"],[21,27,"וַ⁠יְהִי֩ כִ⁠שְׁמֹ֨עַ אַחְאָ֜ב אֶת־הַ⁠דְּבָרִ֤ים הָ⁠אֵ֨לֶּה֙ וַ⁠יִּקְרַ֣ע בְּגָדָ֔י⁠ו וַ⁠יָּֽשֶׂם־שַׂ֥ק עַל־בְּשָׂר֖⁠וֹ וַ⁠יָּצ֑וֹם וַ⁠יִּשְׁכַּ֣ב בַּ⁠שָּׂ֔ק וַ⁠יְהַלֵּ֖ךְ אַֽט׃ס","wa⁠yĕhiy֩ ki⁠şĕ̌mò֨ʻa ʼaẖĕʼá֜b ʼeţ-ha⁠dĕ̇bári֤ym há⁠ʼé֨lėh֙ wa⁠yi̇qĕra֣ʻ bĕ̇gádá֔y⁠w wa⁠yáֽ̇şêm-şâ֥q ʻal-bĕ̇şá̂r֖⁠wò wa⁠yá̇ẕ֑wòm wa⁠yi̇şĕ̌kȧ֣b bȧ⁠şá̇̂֔q wa⁠yĕhalé֖̇kĕ ʼaֽt׃s"],[21,28,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־אֵלִיָּ֥הוּ הַ⁠תִּשְׁבִּ֖י לֵ⁠אמֹֽר׃","wֽa⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-ʼéliyá֥̇hẇ ha⁠ţi̇şĕ̌bi֖̇y lé⁠ʼmòֽr׃"],[21,29,"הֲֽ⁠רָאִ֔יתָ כִּֽי־נִכְנַ֥ע אַחְאָ֖ב מִ⁠לְּ⁠פָנָ֑⁠י יַ֜עַן כִּֽי־נִכְנַ֣ע מִ⁠פָּנַ֗⁠י לֹֽא־אבי הָֽ⁠רָעָה֙ בְּ⁠יָמָ֔י⁠ו בִּ⁠ימֵ֣י בְנ֔⁠וֹ אָבִ֥יא הָ⁠רָעָ֖ה עַל־בֵּיתֽ⁠וֹ׃","hàֽ⁠ráʼi֔yţá kiֽ̇y-nikĕna֥ʻ ʼaẖĕʼá֖b mi⁠lĕ̇⁠páná֑⁠y ya֜ʻan kiֽ̇y-nikĕna֣ʻ mi⁠pá̇na֗⁠y lòֽʼ-ʼby hֽá⁠ráʻáh֙ bĕ̇⁠yámá֔y⁠w bi̇⁠ymé֣y bĕn֔⁠wò ʼábi֥yʼ há⁠ráʻá֖h ʻal-bé̇yţֽ⁠wò׃"],[22,1,"וַ⁠יֵּשְׁב֖וּ שָׁלֹ֣שׁ שָׁנִ֑ים אֵ֚ין מִלְחָמָ֔ה בֵּ֥ין אֲרָ֖ם וּ⁠בֵ֥ין יִשְׂרָאֵֽל׃פ","wa⁠yé̇şĕ̌b֖ẇ şá̌lò֣ş̌ şá̌ni֑ym ʼé֚yn milĕẖámá֔h bé֥̇yn ʼàrá֖m ẇ⁠bé֥yn yişĕ̂ráʼéֽl׃p"],[22,2,"וַ⁠יְהִ֖י בַּ⁠שָּׁנָ֣ה הַ⁠שְּׁלִישִׁ֑ית וַ⁠יֵּ֛רֶד יְהוֹשָׁפָ֥ט מֶֽלֶךְ־יְהוּדָ֖ה אֶל־מֶ֥לֶךְ יִשְׂרָאֵֽל׃","wa⁠yĕhi֖y bȧ⁠şá̇̌ná֣h ha⁠şĕ̇̌liyşǐ֑yţ wa⁠yé֛̇red yĕhwòşá̌pá֥t meֽlekĕ-yĕhẇdá֖h ʼel-me֥lekĕ yişĕ̂ráʼéֽl׃"],[22,3,"וַ⁠יֹּ֤אמֶר מֶֽלֶךְ־יִשְׂרָאֵל֙ אֶל־עֲבָדָ֔י⁠ו הַ⁠יְדַעְתֶּ֕ם כִּֽי־לָ֖⁠נוּ רָמֹ֣ת גִּלְעָ֑ד וַ⁠אֲנַ֣חְנוּ מַחְשִׁ֔ים מִ⁠קַּ֣חַת אֹתָ֔⁠הּ מִ⁠יַּ֖ד מֶ֥לֶךְ אֲרָֽם׃","wa⁠yò֤̇ʼmer meֽlekĕ-yişĕ̂ráʼél֙ ʼel-ʻàbádá֔y⁠w ha⁠yĕdaʻĕţė֕m kiֽ̇y-lá֖⁠nẇ rámò֣ţ gi̇lĕʻá֑d wa⁠ʼàna֣ẖĕnẇ maẖĕşǐ֔ym mi⁠qȧ֣ẖaţ ʼòţá֔⁠ḣ mi⁠yȧ֖d me֥lekĕ ʼàráֽm׃"],[22,4,"וַ⁠יֹּ֨אמֶר֙ אֶל־יְה֣וֹשָׁפָ֔ט הֲ⁠תֵלֵ֥ךְ אִתִּ֛⁠י לַ⁠מִּלְחָמָ֖ה רָמֹ֣ת גִּלְעָ֑ד וַ⁠יֹּ֤אמֶר יְהֽוֹשָׁפָט֙ אֶל־מֶ֣לֶךְ יִשְׂרָאֵ֔ל כָּמ֧וֹ⁠נִי כָמ֛וֹ⁠ךָ כְּ⁠עַמִּ֥⁠י כְ⁠עַמֶּ֖⁠ךָ כְּ⁠סוּסַ֥⁠י כְּ⁠סוּסֶֽי⁠ךָ׃","wa⁠yò̇֨ʼmer֙ ʼel-yĕh֣wòşá̌pá֔t hà⁠ţélé֥kĕ ʼiţi֛̇⁠y la⁠mi̇lĕẖámá֖h rámò֣ţ gi̇lĕʻá֑d wa⁠yò֤̇ʼmer yĕhֽwòşá̌pát֙ ʼel-me֣lekĕ yişĕ̂ráʼé֔l ká̇m֧wò⁠niy kám֛wò⁠ká kĕ̇⁠ʻami֥̇⁠y kĕ⁠ʻamė֖⁠ká kĕ̇⁠sẇsa֥⁠y kĕ̇⁠sẇseֽy⁠ká׃"],[22,5,"וַ⁠יֹּ֥אמֶר יְהוֹשָׁפָ֖ט אֶל־מֶ֣לֶךְ יִשְׂרָאֵ֑ל דְּרָשׁ־נָ֥א כַ⁠יּ֖וֹם אֶת־דְּבַ֥ר יְהוָֽה׃","wa⁠yò֥̇ʼmer yĕhwòşá̌pá֖t ʼel-me֣lekĕ yişĕ̂ráʼé֑l dĕ̇ráş̌-ná֥ʼ ka⁠ẏ֖wòm ʼeţ-dĕ̇ba֥r yĕhwáֽh׃"],[22,6,"וַ⁠יִּקְבֹּ֨ץ מֶֽלֶךְ־יִשְׂרָאֵ֥ל אֶֽת־הַ⁠נְּבִיאִים֮ כְּ⁠אַרְבַּ֣ע מֵא֣וֹת אִישׁ֒ וַ⁠יֹּ֣אמֶר אֲלֵ⁠הֶ֗ם הַ⁠אֵלֵ֞ךְ עַל־רָמֹ֥ת גִּלְעָ֛ד לַ⁠מִּלְחָמָ֖ה אִם־אֶחְדָּ֑ל וַ⁠יֹּאמְר֣וּ עֲלֵ֔ה וְ⁠יִתֵּ֥ן אֲדֹנָ֖⁠י בְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wa⁠yi̇qĕbò̇֨ẕ meֽlekĕ-yişĕ̂ráʼé֥l ʼeֽţ-ha⁠nĕ̇biyʼiym֮ kĕ̇⁠ʼarĕbȧ֣ʻ méʼ֣wòţ ʼiyş̌֒ wa⁠yò֣̇ʼmer ʼàlé⁠he֗m ha⁠ʼélé֞kĕ ʻal-rámò֥ţ gi̇lĕʻá֛d la⁠mi̇lĕẖámá֖h ʼim-ʼeẖĕdá֑̇l wa⁠yò̇ʼmĕr֣ẇ ʻàlé֔h wĕ⁠yiţé֥̇n ʼàdòná֖⁠y bĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[22,7,"וַ⁠יֹּ֨אמֶר֙ יְה֣וֹשָׁפָ֔ט הַ⁠אֵ֨ין פֹּ֥ה נָבִ֛יא לַ⁠יהוָ֖ה ע֑וֹד וְ⁠נִדְרְשָׁ֖ה מֵ⁠אוֹתֽ⁠וֹ׃","wa⁠yò̇֨ʼmer֙ yĕh֣wòşá̌pá֔t ha⁠ʼé֨yn pò֥̇h nábi֛yʼ la⁠yhwá֖h ʻ֑wòd wĕ⁠nidĕrĕşá֖̌h mé⁠ʼwòţֽ⁠wò׃"],[22,8,"וַ⁠יֹּ֣אמֶר מֶֽלֶךְ־יִשְׂרָאֵ֣ל ׀ אֶֽל־יְהוֹשָׁפָ֡ט ע֣וֹד אִישׁ־אֶחָ֡ד לִ⁠דְרֹשׁ֩ אֶת־יְהוָ֨ה מֵ⁠אֹת֜⁠וֹ וַ⁠אֲנִ֣י שְׂנֵאתִ֗י⁠ו כִּ֠י לֹֽא־יִתְנַבֵּ֨א עָלַ֥⁠י טוֹב֙ כִּ֣י אִם־רָ֔ע מִיכָ֖יְהוּ בֶּן־יִמְלָ֑ה וַ⁠יֹּ֨אמֶר֙ יְה֣וֹשָׁפָ֔ט אַל־יֹאמַ֥ר הַ⁠מֶּ֖לֶךְ כֵּֽן׃","wa⁠yò֣̇ʼmer meֽlekĕ-yişĕ̂ráʼé֣l ׀ ʼeֽl-yĕhwòşá̌pá֡t ʻ֣wòd ʼiyş̌-ʼeẖá֡d li⁠dĕròş̌֩ ʼeţ-yĕhwá֨h mé⁠ʼòţ֜⁠wò wa⁠ʼàni֣y şĕ̂néʼţi֗y⁠w ki̇֠y lòֽʼ-yiţĕnabé̇֨ʼ ʻála֥⁠y twòb֙ ki֣̇y ʼim-rá֔ʻ miyká֖yĕhẇ bėn-yimĕlá֑h wa⁠yò̇֨ʼmer֙ yĕh֣wòşá̌pá֔t ʼal-yòʼma֥r ha⁠mė֖lekĕ kéֽ̇n׃"],[22,9,"וַ⁠יִּקְרָא֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל אֶל־סָרִ֖יס אֶחָ֑ד וַ⁠יֹּ֕אמֶר מַהֲרָ֖⁠ה מִיכָ֥יְהוּ בֶן־יִמְלָֽה׃","wa⁠yi̇qĕráʼ֙ me֣lekĕ yişĕ̂ráʼé֔l ʼel-sári֖ys ʼeẖá֑d wa⁠yò̇֕ʼmer mahàrá֖⁠h miyká֥yĕhẇ ben-yimĕláֽh׃"],[22,10,"וּ⁠מֶ֣לֶךְ יִשְׂרָאֵ֡ל וִֽ⁠יהוֹשָׁפָ֣ט מֶֽלֶךְ־יְהוּדָ֡ה יֹשְׁבִים֩ אִ֨ישׁ עַל־כִּסְא֜⁠וֹ מְלֻבָּשִׁ֤ים בְּגָדִים֙ בְּ⁠גֹ֔רֶן פֶּ֖תַח שַׁ֣עַר שֹׁמְר֑וֹן וְ⁠כָ֨ל־הַ⁠נְּבִיאִ֔ים מִֽתְנַבְּאִ֖ים לִ⁠פְנֵי⁠הֶֽם׃","ẇ⁠me֣lekĕ yişĕ̂ráʼé֡l wiֽ⁠yhwòşá̌pá֣t meֽlekĕ-yĕhẇdá֡h yòşĕ̌biym֩ ʼi֨yş̌ ʻal-ki̇sĕʼ֜⁠wò mĕlubá̇şǐ֤ym bĕ̇gádiym֙ bĕ̇⁠gò֔ren pė֖ţaẖ şǎ֣ʻar şò̌mĕr֑wòn wĕ⁠ká֨l-ha⁠nĕ̇biyʼi֔ym miֽţĕnabĕ̇ʼi֖ym li⁠pĕnéy⁠heֽm׃"],[22,11,"וַ⁠יַּ֥עַשׂ ל֛⁠וֹ צִדְקִיָּ֥ה בֶֽן־כְּנַעֲנָ֖ה קַרְנֵ֣י בַרְזֶ֑ל וַ⁠יֹּ֨אמֶר֙ כֹּֽה־אָמַ֣ר יְהוָ֔ה בְּ⁠אֵ֛לֶּה תְּנַגַּ֥ח אֶת־אֲרָ֖ם עַד־כַּלֹּתָֽ⁠ם׃","wa⁠yȧ֥ʻaş̂ l֛⁠wò ẕidĕqiyá֥̇h beֽn-kĕ̇naʻàná֖h qarĕné֣y barĕze֑l wa⁠yò̇֨ʼmer֙ kòֽ̇h-ʼáma֣r yĕhwá֔h bĕ̇⁠ʼé֛lėh ţĕ̇nagȧ֥ẖ ʼeţ-ʼàrá֖m ʻad-kȧlò̇ţáֽ⁠m׃"],[22,12,"וְ⁠כָל־הַ⁠נְּבִאִ֔ים נִבְּאִ֥ים כֵּ֖ן לֵ⁠אמֹ֑ר עֲלֵ֞ה רָמֹ֤ת גִּלְעָד֙ וְ⁠הַצְלַ֔ח וְ⁠נָתַ֥ן יְהוָ֖ה בְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wĕ⁠kál-ha⁠nĕ̇biʼi֔ym nibĕ̇ʼi֥ym ké֖̇n lé⁠ʼmò֑r ʻàlé֞h rámò֤ţ gi̇lĕʻád֙ wĕ⁠haẕĕla֔ẖ wĕ⁠náţa֥n yĕhwá֖h bĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[22,13,"וְ⁠הַ⁠מַּלְאָ֞ךְ אֲשֶׁר־הָלַ֣ךְ ׀ לִ⁠קְרֹ֣א מִיכָ֗יְהוּ דִּבֶּ֤ר אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר הִנֵּה־נָ֞א דִּבְרֵ֧י הַ⁠נְּבִיאִ֛ים פֶּֽה־אֶחָ֥ד ט֖וֹב אֶל־הַ⁠מֶּ֑לֶךְ יְהִֽי־נָ֣א דברי⁠ך כִּ⁠דְבַ֛ר אַחַ֥ד מֵ⁠הֶ֖ם וְ⁠דִבַּ֥רְתָּ טּֽוֹב׃","wĕ⁠ha⁠mȧlĕʼá֞kĕ ʼàşěr-hála֣kĕ ׀ li⁠qĕrò֣ʼ miyká֗yĕhẇ di̇bė֤r ʼéláy⁠w֙ lé⁠ʼmò֔r hiné̇h-ná֞ʼ di̇bĕré֧y ha⁠nĕ̇biyʼi֛ym pėֽh-ʼeẖá֥d t֖wòb ʼel-ha⁠mė֑lekĕ yĕhiֽy-ná֣ʼ dbry⁠k ki̇⁠dĕba֛r ʼaẖa֥d mé⁠he֖m wĕ⁠dibȧ֥rĕţá̇ ṫֽwòb׃"],[22,14,"וַ⁠יֹּ֖אמֶר מִיכָ֑יְהוּ חַי־יְהוָ֕ה כִּ֠י אֶת־אֲשֶׁ֨ר יֹאמַ֧ר יְהוָ֛ה אֵלַ֖⁠י אֹת֥⁠וֹ אֲדַבֵּֽר׃","wa⁠yò֖̇ʼmer miyká֑yĕhẇ ẖay-yĕhwá֕h ki̇֠y ʼeţ-ʼàşě֨r yòʼma֧r yĕhwá֛h ʼéla֖⁠y ʼòţ֥⁠wò ʼàdabéֽ̇r׃"],[22,15,"וַ⁠יָּבוֹא֮ אֶל־הַ⁠מֶּלֶךְ֒ וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֜לֶךְ אֵלָ֗י⁠ו מִיכָ֨יְהוּ֙ הֲ⁠נֵלֵ֞ךְ אֶל־רָמֹ֥ת גִּלְעָ֛ד לַ⁠מִּלְחָמָ֖ה אִם־נֶחְדָּ֑ל וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ עֲלֵ֣ה וְ⁠הַצְלַ֔ח וְ⁠נָתַ֥ן יְהוָ֖ה בְּ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃","wa⁠yá̇bwòʼ֮ ʼel-ha⁠mėlekĕ֒ wa⁠yò̇֨ʼmer ha⁠mė֜lekĕ ʼélá֗y⁠w miyká֨yĕhẇ֙ hà⁠nélé֞kĕ ʼel-rámò֥ţ gi̇lĕʻá֛d la⁠mi̇lĕẖámá֖h ʼim-neẖĕdá֑̇l wa⁠yò֤̇ʼmer ʼéláy⁠w֙ ʻàlé֣h wĕ⁠haẕĕla֔ẖ wĕ⁠náţa֥n yĕhwá֖h bĕ̇⁠ya֥d ha⁠mėֽlekĕ׃"],[22,16,"וַ⁠יֹּ֤אמֶר אֵלָי⁠ו֙ הַ⁠מֶּ֔לֶךְ עַד־כַּ⁠מֶּ֥ה פְעָמִ֖ים אֲנִ֣י מַשְׁבִּעֶ֑⁠ךָ אֲ֠שֶׁר לֹֽא־תְדַבֵּ֥ר אֵלַ֛⁠י רַק־אֱמֶ֖ת בְּ⁠שֵׁ֥ם יְהוָֽה׃","wa⁠yò֤̇ʼmer ʼéláy⁠w֙ ha⁠mė֔lekĕ ʻad-kȧ⁠mė֥h pĕʻámi֖ym ʼàni֣y maşĕ̌bi̇ʻe֑⁠ká ʼà֠şěr lòֽʼ-ţĕdabé֥̇r ʼéla֛⁠y raq-ʼème֖ţ bĕ̇⁠şé֥̌m yĕhwáֽh׃"],[22,17,"וַ⁠יֹּ֗אמֶר רָאִ֤יתִי אֶת־כָּל־יִשְׂרָאֵל֙ נְפֹצִ֣ים אֶל־הֶ⁠הָרִ֔ים כַּ⁠צֹּ֕אן אֲשֶׁ֥ר אֵין־לָ⁠הֶ֖ם רֹעֶ֑ה וַ⁠יֹּ֤אמֶר יְהוָה֙ לֹֽא־אֲדֹנִ֣ים לָ⁠אֵ֔לֶּה יָשׁ֥וּבוּ אִישׁ־לְ⁠בֵית֖⁠וֹ בְּ⁠שָׁלֽוֹם׃","wa⁠yò̇֗ʼmer ráʼi֤yţiy ʼeţ-ká̇l-yişĕ̂ráʼél֙ nĕpòẕi֣ym ʼel-he⁠hári֔ym kȧ⁠ẕò̇֕ʼn ʼàşě֥r ʼéyn-lá⁠he֖m ròʻe֑h wa⁠yò֤̇ʼmer yĕhwáh֙ lòֽʼ-ʼàdòni֣ym lá⁠ʼé֔lėh yáş֥̌ẇbẇ ʼiyş̌-lĕ⁠béyţ֖⁠wò bĕ̇⁠şá̌lֽwòm׃"],[22,18,"וַ⁠יֹּ֥אמֶר מֶֽלֶךְ־יִשְׂרָאֵ֖ל אֶל־יְהוֹשָׁפָ֑ט הֲ⁠לוֹא֙ אָמַ֣רְתִּי אֵלֶ֔י⁠ךָ לֽוֹא־יִתְנַבֵּ֥א עָלַ֛⁠י ט֖וֹב כִּ֥י אִם־רָֽע׃","wa⁠yò֥̇ʼmer meֽlekĕ-yişĕ̂ráʼé֖l ʼel-yĕhwòşá̌pá֑t hà⁠lwòʼ֙ ʼáma֣rĕţi̇y ʼéle֔y⁠ká lֽwòʼ-yiţĕnabé֥̇ʼ ʻála֛⁠y t֖wòb ki֥̇y ʼim-ráֽʻ׃"],[22,19,"וַ⁠יֹּ֕אמֶר לָ⁠כֵ֖ן שְׁמַ֣ע דְּבַר־יְהוָ֑ה רָאִ֤יתִי אֶת־יְהוָה֙ יֹשֵׁ֣ב עַל־כִּסְא֔⁠וֹ וְ⁠כָל־צְבָ֤א הַ⁠שָּׁמַ֨יִם֙ עֹמֵ֣ד עָלָ֔י⁠ו מִ⁠ימִינ֖⁠וֹ וּ⁠מִ⁠שְּׂמֹאלֽ⁠וֹ׃","wa⁠yò̇֕ʼmer lá⁠ké֖n şĕ̌ma֣ʻ dĕ̇bar-yĕhwá֑h ráʼi֤yţiy ʼeţ-yĕhwáh֙ yòşé֣̌b ʻal-ki̇sĕʼ֔⁠wò wĕ⁠kál-ẕĕbá֤ʼ ha⁠şá̇̌ma֨yim֙ ʻòmé֣d ʻálá֔y⁠w mi⁠ymiyn֖⁠wò ẇ⁠mi⁠şĕ̇̂mòʼlֽ⁠wò׃"],[22,20,"וַ⁠יֹּ֣אמֶר יְהוָ֗ה מִ֤י יְפַתֶּה֙ אֶת־אַחְאָ֔ב וְ⁠יַ֕עַל וְ⁠יִפֹּ֖ל בְּ⁠רָמֹ֣ת גִּלְעָ֑ד וַ⁠יֹּ֤אמֶר זֶה֙ בְּ⁠כֹ֔ה וְ⁠זֶ֥ה אֹמֵ֖ר בְּ⁠כֹֽה׃","wa⁠yò֣̇ʼmer yĕhwá֗h mi֤y yĕpaţėh֙ ʼeţ-ʼaẖĕʼá֔b wĕ⁠ya֕ʻal wĕ⁠yipò֖̇l bĕ̇⁠rámò֣ţ gi̇lĕʻá֑d wa⁠yò֤̇ʼmer zeh֙ bĕ̇⁠kò֔h wĕ⁠ze֥h ʼòmé֖r bĕ̇⁠kòֽh׃"],[22,21,"וַ⁠יֵּצֵ֣א הָ⁠ר֗וּחַ וַֽ⁠יַּעֲמֹד֙ לִ⁠פְנֵ֣י יְהוָ֔ה וַ⁠יֹּ֖אמֶר אֲנִ֣י אֲפַתֶּ֑⁠נּוּ וַ⁠יֹּ֧אמֶר יְהוָ֛ה אֵלָ֖י⁠ו בַּ⁠מָּֽה׃","wa⁠yé̇ẕé֣ʼ há⁠r֗ẇẖa waֽ⁠yȧʻàmòd֙ li⁠pĕné֣y yĕhwá֔h wa⁠yò֖̇ʼmer ʼàni֣y ʼàpaţė֑⁠ṅẇ wa⁠yò֧̇ʼmer yĕhwá֛h ʼélá֖y⁠w bȧ⁠máֽ̇h׃"],[22,22,"וַ⁠יֹּ֗אמֶר אֵצֵא֙ וְ⁠הָיִ֨יתִי֙ ר֣וּחַ שֶׁ֔קֶר בְּ⁠פִ֖י כָּל־נְבִיאָ֑י⁠ו וַ⁠יֹּ֗אמֶר תְּפַתֶּה֙ וְ⁠גַם־תּוּכָ֔ל צֵ֖א וַ⁠עֲשֵׂה־כֵֽן׃","wa⁠yò̇֗ʼmer ʼéẕéʼ֙ wĕ⁠háyi֨yţiy֙ r֣ẇẖa şě֔qer bĕ̇⁠pi֖y ká̇l-nĕbiyʼá֑y⁠w wa⁠yò̇֗ʼmer ţĕ̇paţėh֙ wĕ⁠gam-ţ̇ẇká֔l ẕé֖ʼ wa⁠ʻàşé̂h-kéֽn׃"],[22,23,"וְ⁠עַתָּ֗ה הִנֵּ֨ה נָתַ֤ן יְהוָה֙ ר֣וּחַ שֶׁ֔קֶר בְּ⁠פִ֖י כָּל־נְבִיאֶ֣י⁠ךָ אֵ֑לֶּה וַֽ⁠יהוָ֔ה דִּבֶּ֥ר עָלֶ֖י⁠ךָ רָעָֽה׃","wĕ⁠ʻaţá̇֗h hiné̇֨h náţa֤n yĕhwáh֙ r֣ẇẖa şě֔qer bĕ̇⁠pi֖y ká̇l-nĕbiyʼe֣y⁠ká ʼé֑lėh waֽ⁠yhwá֔h di̇bė֥r ʻále֖y⁠ká ráʻáֽh׃"],[22,24,"וַ⁠יִּגַּשׁ֙ צִדְקִיָּ֣הוּ בֶֽן־כְּנַעֲנָ֔ה וַ⁠יַּכֶּ֥ה אֶת־מִיכָ֖יְהוּ עַל־הַ⁠לֶּ֑חִי וַ⁠יֹּ֕אמֶר אֵי־זֶ֨ה עָבַ֧ר רֽוּחַ־יְהוָ֛ה מֵ⁠אִתִּ֖⁠י לְ⁠דַבֵּ֥ר אוֹתָֽ⁠ךְ׃","wa⁠yi̇gȧş̌֙ ẕidĕqiyá֣̇hẇ beֽn-kĕ̇naʻàná֔h wa⁠yȧkė֥h ʼeţ-miyká֖yĕhẇ ʻal-ha⁠lė֑ẖiy wa⁠yò̇֕ʼmer ʼéy-ze֨h ʻába֧r rֽẇẖa-yĕhwá֛h mé⁠ʼiţi֖̇⁠y lĕ⁠dabé֥̇r ʼwòţáֽ⁠kĕ׃"],[22,25,"וַ⁠יֹּ֣אמֶר מִיכָ֔יְהוּ הִנְּ⁠ךָ֥ רֹאֶ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא אֲשֶׁ֥ר תָּבֹ֛א חֶ֥דֶר בְּ⁠חֶ֖דֶר לְ⁠הֵחָבֵֽה׃","wa⁠yò֣̇ʼmer miyká֔yĕhẇ hinĕ̇⁠ká֥ ròʼe֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ʼàşě֥r ţá̇bò֛ʼ ẖe֥der bĕ̇⁠ẖe֖der lĕ⁠héẖábéֽh׃"],[22,26,"וַ⁠יֹּ֨אמֶר֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל קַ֚ח אֶת־מִיכָ֔יְהוּ וַ⁠הֲשִׁיבֵ֖⁠הוּ אֶל־אָמֹ֣ן שַׂר־הָ⁠עִ֑יר וְ⁠אֶל־יוֹאָ֖שׁ בֶּן־הַ⁠מֶּֽלֶךְ׃","wa⁠yò̇֨ʼmer֙ me֣lekĕ yişĕ̂ráʼé֔l qa֚ẖ ʼeţ-miyká֔yĕhẇ wa⁠hàşǐybé֖⁠hẇ ʼel-ʼámò֣n şâr-há⁠ʻi֑yr wĕ⁠ʼel-ywòʼá֖ş̌ bėn-ha⁠mėֽlekĕ׃"],[22,27,"וְ⁠אָמַרְתָּ֗ כֹּ֚ה אָמַ֣ר הַ⁠מֶּ֔לֶךְ שִׂ֥ימוּ אֶת־זֶ֖ה בֵּ֣ית הַ⁠כֶּ֑לֶא וְ⁠הַאֲכִילֻ֨⁠הוּ לֶ֤חֶם לַ֨חַץ֙ וּ⁠מַ֣יִם לַ֔חַץ עַ֖ד בֹּאִ֥⁠י בְ⁠שָׁלֽוֹם׃","wĕ⁠ʼámarĕţá̇֗ kò֚̇h ʼáma֣r ha⁠mė֔lekĕ şî֥ymẇ ʼeţ-ze֖h bé֣̇yţ ha⁠kė֑leʼ wĕ⁠haʼàkiylu֨⁠hẇ le֤ẖem la֨ẖaẕ֙ ẇ⁠ma֣yim la֔ẖaẕ ʻa֖d bò̇ʼi֥⁠y bĕ⁠şá̌lֽwòm׃"],[22,28,"וַ⁠יֹּ֣אמֶר מִיכָ֔יְהוּ אִם־שׁ֤וֹב תָּשׁוּב֙ בְּ⁠שָׁל֔וֹם לֹֽא־דִבֶּ֥ר יְהוָ֖ה בִּ֑⁠י וַ⁠יֹּ֕אמֶר שִׁמְע֖וּ עַמִּ֥ים כֻּלָּֽ⁠ם׃","wa⁠yò֣̇ʼmer miyká֔yĕhẇ ʼim-ş֤̌wòb ţá̇ş̌ẇb֙ bĕ̇⁠şá̌l֔wòm lòֽʼ-dibė֥r yĕhwá֖h bi֑̇⁠y wa⁠yò̇֕ʼmer şǐmĕʻ֖ẇ ʻami֥̇ym ku̇láֽ̇⁠m׃"],[22,29,"וַ⁠יַּ֧עַל מֶֽלֶךְ־יִשְׂרָאֵ֛ל וְ⁠יהוֹשָׁפָ֥ט מֶֽלֶךְ־יְהוּדָ֖ה רָמֹ֥ת גִּלְעָֽד׃","wa⁠yȧ֧ʻal meֽlekĕ-yişĕ̂ráʼé֛l wĕ⁠yhwòşá̌pá֥t meֽlekĕ-yĕhẇdá֖h rámò֥ţ gi̇lĕʻáֽd׃"],[22,30,"וַ⁠יֹּאמֶר֩ מֶ֨לֶךְ יִשְׂרָאֵ֜ל אֶל־יְהוֹשָׁפָ֗ט הִתְחַפֵּשׂ֙ וָ⁠בֹ֣א בַ⁠מִּלְחָמָ֔ה וְ⁠אַתָּ֖ה לְבַ֣שׁ בְּגָדֶ֑י⁠ךָ וַ⁠יִּתְחַפֵּשׂ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל וַ⁠יָּב֖וֹא בַּ⁠מִּלְחָמָֽה׃","wa⁠yò̇ʼmer֩ me֨lekĕ yişĕ̂ráʼé֜l ʼel-yĕhwòşá̌pá֗t hiţĕẖapé̇ş̂֙ wá⁠bò֣ʼ ba⁠mi̇lĕẖámá֔h wĕ⁠ʼaţá֖̇h lĕba֣ş̌ bĕ̇gáde֑y⁠ká wa⁠yi̇ţĕẖapé̇ş̂֙ me֣lekĕ yişĕ̂ráʼé֔l wa⁠yá̇b֖wòʼ bȧ⁠mi̇lĕẖámáֽh׃"],[22,31,"וּ⁠מֶ֣לֶךְ אֲרָ֡ם צִוָּ֣ה אֶת־שָׂרֵי֩ הָ⁠רֶ֨כֶב אֲשֶׁר־ל֜⁠וֹ שְׁלֹשִׁ֤ים וּ⁠שְׁנַ֨יִם֙ לֵ⁠אמֹ֔ר לֹ֚א תִּלָּ֣חֲמ֔וּ אֶת־קָטֹ֖ן וְ⁠אֶת־גָּד֑וֹל כִּ֛י אִֽם־אֶת־מֶ֥לֶךְ יִשְׂרָאֵ֖ל לְ⁠בַדּֽ⁠וֹ׃","ẇ⁠me֣lekĕ ʼàrá֡m ẕiwá֣̇h ʼeţ-şá̂réy֩ há⁠re֨keb ʼàşěr-l֜⁠wò şĕ̌lòşǐ֤ym ẇ⁠şĕ̌na֨yim֙ lé⁠ʼmò֔r lò֚ʼ ţi̇lá֣̇ẖàm֔ẇ ʼeţ-qátò֖n wĕ⁠ʼeţ-gá̇d֑wòl ki֛̇y ʼiֽm-ʼeţ-me֥lekĕ yişĕ̂ráʼé֖l lĕ⁠baḋֽ⁠wò׃"],[22,32,"וַ⁠יְהִ֡י כִּ⁠רְאוֹת֩ שָׂרֵ֨י הָ⁠רֶ֜כֶב אֶת־יְהוֹשָׁפָ֗ט וְ⁠הֵ֤מָּה אָֽמְרוּ֙ אַ֣ךְ מֶֽלֶךְ־יִשְׂרָאֵ֣ל ה֔וּא וַ⁠יָּסֻ֥רוּ עָלָ֖י⁠ו לְ⁠הִלָּחֵ֑ם וַ⁠יִּזְעַ֖ק יְהוֹשָׁפָֽט׃","wa⁠yĕhi֡y ki̇⁠rĕʼwòţ֩ şá̂ré֨y há⁠re֜keb ʼeţ-yĕhwòşá̌pá֗t wĕ⁠hé֤má̇h ʼáֽmĕrẇ֙ ʼa֣kĕ meֽlekĕ-yişĕ̂ráʼé֣l h֔ẇʼ wa⁠yá̇su֥rẇ ʻálá֖y⁠w lĕ⁠hilá̇ẖé֑m wa⁠yi̇zĕʻa֖q yĕhwòşá̌páֽt׃"],[22,33,"וַ⁠יְהִ֗י כִּ⁠רְאוֹת֙ שָׂרֵ֣י הָ⁠רֶ֔כֶב כִּֽי־לֹא־מֶ֥לֶךְ יִשְׂרָאֵ֖ל ה֑וּא וַ⁠יָּשׁ֖וּבוּ מֵ⁠אַחֲרָֽי⁠ו׃","wa⁠yĕhi֗y ki̇⁠rĕʼwòţ֙ şá̂ré֣y há⁠re֔keb kiֽ̇y-lòʼ-me֥lekĕ yişĕ̂ráʼé֖l h֑ẇʼ wa⁠yá̇ş֖̌ẇbẇ mé⁠ʼaẖàráֽy⁠w׃"],[22,34,"וְ⁠אִ֗ישׁ מָשַׁ֤ךְ בַּ⁠קֶּ֨שֶׁת֙ לְ⁠תֻמּ֔⁠וֹ וַ⁠יַּכֶּה֙ אֶת־מֶ֣לֶךְ יִשְׂרָאֵ֔ל בֵּ֥ין הַ⁠דְּבָקִ֖ים וּ⁠בֵ֣ין הַ⁠שִּׁרְיָ֑ן וַ⁠יֹּ֣אמֶר לְ⁠רַכָּב֗⁠וֹ הֲפֹ֥ךְ יָדְ⁠ךָ֛ וְ⁠הוֹצִיאֵ֥⁠נִי מִן־הַֽ⁠מַּחֲנֶ֖ה כִּ֥י הָחֳלֵֽיתִי׃","wĕ⁠ʼi֗yş̌ máşǎ֤kĕ bȧ⁠qė֨şěţ֙ lĕ⁠ţuṁ֔⁠wò wa⁠yȧkėh֙ ʼeţ-me֣lekĕ yişĕ̂ráʼé֔l bé֥̇yn ha⁠dĕ̇báqi֖ym ẇ⁠bé֣yn ha⁠şi̇̌rĕyá֑n wa⁠yò֣̇ʼmer lĕ⁠raká̇b֗⁠wò hàpò֥kĕ yádĕ⁠ká֛ wĕ⁠hwòẕiyʼé֥⁠niy min-haֽ⁠mȧẖàne֖h ki֥̇y háẖoléֽyţiy׃"],[22,35,"וַ⁠תַּעֲלֶ֤ה הַ⁠מִּלְחָמָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וְ⁠הַ⁠מֶּ֗לֶךְ הָיָ֧ה מָעֳמָ֛ד בַּ⁠מֶּרְכָּבָ֖ה נֹ֣כַח אֲרָ֑ם וַ⁠יָּ֣מָת בָּ⁠עֶ֔רֶב וַ⁠יִּ֥צֶק דַּֽם־הַ⁠מַּכָּ֖ה אֶל־חֵ֥יק הָ⁠רָֽכֶב׃","wa⁠ţȧʻàle֤h ha⁠mi̇lĕẖámáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ wĕ⁠ha⁠mė֗lekĕ háyá֧h máʻomá֛d bȧ⁠mėrĕká̇bá֖h nò֣kaẖ ʼàrá֑m wa⁠yá֣̇máţ bá̇⁠ʻe֔reb wa⁠yi֥̇ẕeq dȧֽm-ha⁠mȧká֖̇h ʼel-ẖé֥yq há⁠ráֽkeb׃"],[22,36,"וַ⁠יַּעֲבֹ֤ר הָ⁠רִנָּה֙ בַּֽ⁠מַּחֲנֶ֔ה כְּ⁠בֹ֥א הַ⁠שֶּׁ֖מֶשׁ לֵ⁠אמֹ֑ר אִ֥ישׁ אֶל־עִיר֖⁠וֹ וְ⁠אִ֥ישׁ אֶל־אַרְצֽ⁠וֹ׃","wa⁠yȧʻàbò֤r há⁠riná̇h֙ bȧֽ⁠mȧẖàne֔h kĕ̇⁠bò֥ʼ ha⁠şė֖̌meş̌ lé⁠ʼmò֑r ʼi֥yş̌ ʼel-ʻiyr֖⁠wò wĕ⁠ʼi֥yş̌ ʼel-ʼarĕẕֽ⁠wò׃"],[22,37,"וַ⁠יָּ֣מָת הַ⁠מֶּ֔לֶךְ וַ⁠יָּב֖וֹא שֹׁמְר֑וֹן וַ⁠יִּקְבְּר֥וּ אֶת־הַ⁠מֶּ֖לֶךְ בְּ⁠שֹׁמְרֽוֹן׃","wa⁠yá֣̇máţ ha⁠mė֔lekĕ wa⁠yá̇b֖wòʼ şò̌mĕr֑wòn wa⁠yi̇qĕbĕ̇r֥ẇ ʼeţ-ha⁠mė֖lekĕ bĕ̇⁠şò̌mĕrֽwòn׃"],[22,38,"וַ⁠יִּשְׁטֹ֨ף אֶת־הָ⁠רֶ֜כֶב עַ֣ל ׀ בְּרֵכַ֣ת שֹׁמְר֗וֹן וַ⁠יָּלֹ֤קּוּ הַ⁠כְּלָבִים֙ אֶת־דָּמ֔⁠וֹ וְ⁠הַ⁠זֹּנ֖וֹת רָחָ֑צוּ כִּ⁠דְבַ֥ר יְהוָ֖ה אֲשֶׁ֥ר דִּבֵּֽר׃","wa⁠yi̇şĕ̌tò֨p ʼeţ-há⁠re֜keb ʻa֣l ׀ bĕ̇réka֣ţ şò̌mĕr֗wòn wa⁠yá̇lò֤q̇ẇ ha⁠kĕ̇lábiym֙ ʼeţ-dá̇m֔⁠wò wĕ⁠ha⁠zò̇n֖wòţ ráẖá֑ẕẇ ki̇⁠dĕba֥r yĕhwá֖h ʼàşě֥r di̇béֽ̇r׃"],[22,39,"וְ⁠יֶתֶר֩ דִּבְרֵ֨י אַחְאָ֜ב וְ⁠כָל־אֲשֶׁ֣ר עָשָׂ֗ה וּ⁠בֵ֤ית הַ⁠שֵּׁן֙ אֲשֶׁ֣ר בָּנָ֔ה וְ⁠כָל־הֶ⁠עָרִ֖ים אֲשֶׁ֣ר בָּנָ֑ה הֲ⁠לֽוֹא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠yeţer֩ di̇bĕré֨y ʼaẖĕʼá֜b wĕ⁠kál-ʼàşě֣r ʻáşá̂֗h ẇ⁠bé֤yţ ha⁠şé̇̌n֙ ʼàşě֣r bá̇ná֔h wĕ⁠kál-he⁠ʻári֖ym ʼàşě֣r bá̇ná֑h hà⁠lֽwòʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yişĕ̂ráʼéֽl׃"],[22,40,"וַ⁠יִּשְׁכַּ֥ב אַחְאָ֖ב עִם־אֲבֹתָ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ אֲחַזְיָ֥הוּ בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃פ","wa⁠yi̇şĕ̌kȧ֥b ʼaẖĕʼá֖b ʻim-ʼàbòţá֑y⁠w wa⁠yi̇mĕlò֛kĕ ʼàẖazĕyá֥hẇ bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃p"],[22,41,"וִ⁠יהֽוֹשָׁפָט֙ בֶּן־אָסָ֔א מָלַ֖ךְ עַל־יְהוּדָ֑ה בִּ⁠שְׁנַ֣ת אַרְבַּ֔ע לְ⁠אַחְאָ֖ב מֶ֥לֶךְ יִשְׂרָאֵֽל׃","wi⁠yhֽwòşá̌pát֙ bėn-ʼásá֔ʼ mála֖kĕ ʻal-yĕhẇdá֑h bi̇⁠şĕ̌na֣ţ ʼarĕbȧ֔ʻ lĕ⁠ʼaẖĕʼá֖b me֥lekĕ yişĕ̂ráʼéֽl׃"],[22,42,"יְהוֹשָׁפָ֗ט בֶּן־שְׁלֹשִׁ֨ים וְ⁠חָמֵ֤שׁ שָׁנָה֙ בְּ⁠מָלְכ֔⁠וֹ וְ⁠עֶשְׂרִ֤ים וְ⁠חָמֵשׁ֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָ֑ם וְ⁠שֵׁ֣ם אִמּ֔⁠וֹ עֲזוּבָ֖ה בַּת־שִׁלְחִֽי׃","yĕhwòşá̌pá֗t bėn-şĕ̌lòşǐ֨ym wĕ⁠ẖámé֤ş̌ şá̌náh֙ bĕ̇⁠málĕk֔⁠wò wĕ⁠ʻeşĕ̂ri֤ym wĕ⁠ẖáméş̌֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liá֑m wĕ⁠şé֣̌m ʼiṁ֔⁠wò ʻàzẇbá֖h bȧţ-şǐlĕẖiֽy׃"],[22,43,"וַ⁠יֵּ֗לֶךְ בְּ⁠כָל־דֶּ֛רֶךְ אָסָ֥א אָבִ֖י⁠ו לֹא־סָ֣ר מִמֶּ֑⁠נּוּ לַ⁠עֲשׂ֥וֹת הַ⁠יָּשָׁ֖ר בְּ⁠עֵינֵ֥י יְהוָֽה׃ אַ֥ךְ הַ⁠בָּמ֖וֹת לֹֽא־סָ֑רוּ ע֥וֹד הָ⁠עָ֛ם מְזַבְּחִ֥ים וּֽ⁠מְקַטְּרִ֖ים בַּ⁠בָּמֽוֹת׃","wa⁠yé̇֗lekĕ bĕ̇⁠kál-dė֛rekĕ ʼásá֥ʼ ʼábi֖y⁠w lòʼ-sá֣r mimė֑⁠ṅẇ la⁠ʻàş֥̂wòţ ha⁠yá̇şá֖̌r bĕ̇⁠ʻéyné֥y yĕhwáֽh׃ ʼa֥kĕ ha⁠bá̇m֖wòţ lòֽʼ-sá֑rẇ ʻ֥wòd há⁠ʻá֛m mĕzabĕ̇ẖi֥ym ẇֽ⁠mĕqatĕ̇ri֖ym bȧ⁠bá̇mֽwòţ׃"],[22,44,"וַ⁠יַּשְׁלֵ֥ם יְהוֹשָׁפָ֖ט עִם־מֶ֥לֶךְ יִשְׂרָאֵֽל׃","wa⁠yȧşĕ̌lé֥m yĕhwòşá̌pá֖t ʻim-me֥lekĕ yişĕ̂ráʼéֽl׃"],[22,45,"וְ⁠יֶ֨תֶר דִּבְרֵ֧י יְהוֹשָׁפָ֛ט וּ⁠גְבוּרָת֥⁠וֹ אֲשֶׁר־עָשָׂ֖ה וַ⁠אֲשֶׁ֣ר נִלְחָ֑ם הֲ⁠לֹֽא־הֵ֣ם כְּתוּבִ֗ים עַל־סֵ֛פֶר דִּבְרֵ֥י הַ⁠יָּמִ֖ים לְ⁠מַלְכֵ֥י יְהוּדָֽה׃","wĕ⁠ye֨ţer di̇bĕré֧y yĕhwòşá̌pá֛t ẇ⁠gĕbẇráţ֥⁠wò ʼàşěr-ʻáşá֖̂h wa⁠ʼàşě֣r nilĕẖá֑m hà⁠lòֽʼ-hé֣m kĕ̇ţẇbi֗ym ʻal-sé֛per di̇bĕré֥y ha⁠yá̇mi֖ym lĕ⁠malĕké֥y yĕhẇdáֽh׃"],[22,46,"וְ⁠יֶ֨תֶר֙ הַ⁠קָּדֵ֔שׁ אֲשֶׁ֣ר נִשְׁאַ֔ר בִּ⁠ימֵ֖י אָסָ֣א אָבִ֑י⁠ו בִּעֵ֖ר מִן־הָ⁠אָֽרֶץ׃","wĕ⁠ye֨ţer֙ ha⁠qá̇dé֔ş̌ ʼàşě֣r nişĕ̌ʼa֔r bi̇⁠ymé֖y ʼásá֣ʼ ʼábi֑y⁠w bi̇ʻé֖r min-há⁠ʼáֽreẕ׃"],[22,47,"וּ⁠מֶ֥לֶךְ אֵ֛ין בֶּ⁠אֱד֖וֹם נִצָּ֥ב מֶֽלֶךְ׃","ẇ⁠me֥lekĕ ʼé֛yn bė⁠ʼèd֖wòm niẕá֥̇b meֽlekĕ׃"],[22,48,"יְהוֹשָׁפָ֡ט עשר אֳנִיּ֨וֹת תַּרְשִׁ֜ישׁ לָ⁠לֶ֧כֶת אוֹפִ֛ירָ⁠ה לַ⁠זָּהָ֖ב וְ⁠לֹ֣א הָלָ֑ךְ כִּֽי־נשברה אֳנִיּ֖וֹת בְּ⁠עֶצְי֥וֹן גָּֽבֶר׃","yĕhwòşá̌pá֡t ʻşr ʼoniẏ֨wòţ ţȧrĕşǐ֜yş̌ lá⁠le֧keţ ʼwòpi֛yrá⁠h la⁠zá̇há֖b wĕ⁠lò֣ʼ hálá֑kĕ kiֽ̇y-nşbrh ʼoniẏ֖wòţ bĕ̇⁠ʻeẕĕy֥wòn gáֽ̇ber׃"],[22,49,"אָ֠ז אָמַ֞ר אֲחַזְיָ֤הוּ בֶן־אַחְאָב֙ אֶל־יְה֣וֹשָׁפָ֔ט יֵלְכ֧וּ עֲבָדַ֛⁠י עִם־עֲבָדֶ֖י⁠ךָ בָּ⁠אֳנִיּ֑וֹת וְ⁠לֹ֥א אָבָ֖ה יְהוֹשָׁפָֽט׃","ʼá֠z ʼáma֞r ʼàẖazĕyá֤hẇ ben-ʼaẖĕʼáb֙ ʼel-yĕh֣wòşá̌pá֔t yélĕk֧ẇ ʻàbáda֛⁠y ʻim-ʻàbáde֖y⁠ká bá̇⁠ʼoniẏ֑wòţ wĕ⁠lò֥ʼ ʼábá֖h yĕhwòşá̌páֽt׃"],[22,50,"וַ⁠יִּשְׁכַּ֤ב יְהֽוֹשָׁפָט֙ עִם־אֲבֹתָ֔י⁠ו וַ⁠יִּקָּבֵר֙ עִם־אֲבֹתָ֔י⁠ו בְּ⁠עִ֖יר דָּוִ֣ד אָבִ֑י⁠ו וַ⁠יִּמְלֹ֛ךְ יְהוֹרָ֥ם בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃ס","wa⁠yi̇şĕ̌kȧ֤b yĕhֽwòşá̌pát֙ ʻim-ʼàbòţá֔y⁠w wa⁠yi̇qá̇bér֙ ʻim-ʼàbòţá֔y⁠w bĕ̇⁠ʻi֖yr dá̇wi֣d ʼábi֑y⁠w wa⁠yi̇mĕlò֛kĕ yĕhwòrá֥m bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃s"],[22,51,"אֲחַזְיָ֣הוּ בֶן־אַחְאָ֗ב מָלַ֤ךְ עַל־יִשְׂרָאֵל֙ בְּ⁠שֹׁ֣מְר֔וֹן בִּ⁠שְׁנַת֙ שְׁבַ֣ע עֶשְׂרֵ֔ה לִ⁠יהוֹשָׁפָ֖ט מֶ֣לֶךְ יְהוּדָ֑ה וַ⁠יִּמְלֹ֥ךְ עַל־יִשְׂרָאֵ֖ל שְׁנָתָֽיִם׃","ʼàẖazĕyá֣hẇ ben-ʼaẖĕʼá֗b mála֤kĕ ʻal-yişĕ̂ráʼél֙ bĕ̇⁠şò֣̌mĕr֔wòn bi̇⁠şĕ̌naţ֙ şĕ̌ba֣ʻ ʻeşĕ̂ré֔h li⁠yhwòşá̌pá֖t me֣lekĕ yĕhẇdá֑h wa⁠yi̇mĕlò֥kĕ ʻal-yişĕ̂ráʼé֖l şĕ̌náţáֽyim׃"],[22,52,"וַ⁠יַּ֥עַשׂ הָ⁠רַ֖ע בְּ⁠עֵינֵ֣י יְהוָ֑ה וַ⁠יֵּ֗לֶךְ בְּ⁠דֶ֤רֶךְ אָבִי⁠ו֙ וּ⁠בְ⁠דֶ֣רֶךְ אִמּ֔⁠וֹ וּ⁠בְ⁠דֶ֨רֶךְ֙ יָרָבְעָ֣ם בֶּן־נְבָ֔ט אֲשֶׁ֥ר הֶחֱטִ֖יא אֶת־יִשְׂרָאֵֽל׃","wa⁠yȧ֥ʻaş̂ há⁠ra֖ʻ bĕ̇⁠ʻéyné֣y yĕhwá֑h wa⁠yé̇֗lekĕ bĕ̇⁠de֤rekĕ ʼábiy⁠w֙ ẇ⁠bĕ⁠de֣rekĕ ʼiṁ֔⁠wò ẇ⁠bĕ⁠de֨rekĕ֙ yárábĕʻá֣m bėn-nĕbá֔t ʼàşě֥r heẖèti֖yʼ ʼeţ-yişĕ̂ráʼéֽl׃"],[22,53,"וַֽ⁠יַּעֲבֹד֙ אֶת־הַ⁠בַּ֔עַל וַ⁠יִּֽשְׁתַּחֲוֶ֖ה ל֑⁠וֹ וַ⁠יַּכְעֵ֗ס אֶת־יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה אָבִֽי⁠ו׃","waֽ⁠yȧʻàbòd֙ ʼeţ-ha⁠bȧ֔ʻal wa⁠yiֽ̇şĕ̌ţȧẖàwe֖h l֑⁠wò wa⁠yȧkĕʻé֗s ʼeţ-yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h ʼábiֽy⁠w׃"]]}};